window.SEMIPRIME_SOURCES={"RiemannGaussian.SemiprimeD1ActualCallAggregation":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1RecursiveCallState\n\n/-! # Fuel-compatible aggregation for proved actual program recurrences\nThis is a proof-only finite-tree summation principle. Concrete controllers must\nprove the zero/successor equations for their OWN reports and derive the contribution\nenvelope; no report function is supplied to any executable public counter.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 300000\nnamespace RiemannGaussian.SemiprimeD1ActualCallAggregation\nopen SemiprimeD1RecursiveCallTree SemiprimeD1RecursiveCallState\n\n/-- A proved actual report recurrence sums to the literal call count, restricted\nto real reachable remaining-fuel states. No nonexistent zero-fuel root is paid. -/\ntheorem report_le_count (s fuel threshold B : ℕ) (root : Call)\n    (report contribution : ℕ → Call → ℕ)\n    (hzero : ∀ c, report 0 c=contribution 0 c)\n    (hsucc : ∀ f c, report (f+1) c=contribution (f+1) c+\n      ((children s c).map (report f)).sum)\n    (hinv : threshold ≤ root.depth+fuel)\n    (hlocal : ∀ c, Reach s root c → ∀ f ≤ fuel,\n      threshold ≤ c.depth+f → contribution f c ≤ B) :\n    report fuel root ≤ B*count s fuel root := by\n  have go : ∀ f ≤ fuel, ∀ c, Reach s root c → threshold ≤ c.depth+f →\n      report f c ≤ B*count s f c := by\n    intro f\n    induction f with\n    | zero =>\n      intro hf c hr hi\n      simpa only [hzero,count,Nat.mul_one] using hlocal c hr 0 hf hi\n    | succ f ih =>\n      intro hf c hr hi\n      have hs : ((children s c).map (report f)).sum ≤\n          ((children s c).map (fun child => B*count s f child)).sum := by\n        apply List.sum_le_sum\n        intro child hchild\n        apply ih (by omega) child (Reach.step hr hchild)\n        rw [mem_children_depth s c child hchild]\n        omega\n      rw [hsucc,count]\n      rw [List.sum_map_mul_left] at hs\n      nlinarith only [hs,hlocal c hr (f+1) hf hi]\n  exact go fuel le_rfl root Reach.root hinv\n\nend RiemannGaussian.SemiprimeD1ActualCallAggregation\n","RiemannGaussian.SemiprimeD1BooleanRootTablesOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackBooleanTableSource\n/-! # Literal source is the complete original checker-built root table\nReference construction is proof-side only. The actual source takes no N,\npredicate, table, coefficient or evaluator input; every byte is a fixed push.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nnamespace RiemannGaussian.SemiprimeD1BooleanRootTablesOriginal\nopen SemiprimeD1TensorTables SemiprimeD1BooleanRootTables\nopen SemiprimeMacroGraph SemiprimeMacroParameters\n/-- The EXACT old factor producer/materializer at an original vertex, before\nits Fin-factor reindexing. This reference is NEVER called by the new source. -/\ndef reference (N : ℕ) (hN : 0<N) (v : SemiprimePublicAcquiredExecution.PublicVertex N) :\n    Table (subdividedArity v) :=\n  (build (subdividedArity v) (fun bits=>\n    let input:=bits.toArray\n    let check:=SemiprimeSubdividedEntry.publicSubdividedEntry N hN v (fun i=>(input[i.val]?).getD false)\n    ⟨[if check.accepted then [true] else []],check.clock+3*bits.length+5⟩)).table\n/-- Exact indexed original factor producer, not an advised comparison table. -/\ntheorem reference_indexed (N : ℕ) (hN : 0<N) (e : Fin (SemiprimePublicAcquiredExecution.factorCount N)) :\n    reference N hN ((SemiprimePublicAcquiredExecution.vertexEnumeration N).equivFin e)=\n      (build (SemiprimePublicAcquiredExecution.indexedArity N e)\n        (SemiprimeD1RootTensorTables.factorProducer N hN e)).table := rfl\n/-- ENTIRE original OR table, with false-first ordered ports, is the literal table. -/\ntheorem or_table (N : ℕ) (hN : 0<N) (side : Fin 2) (j : Fin (digitCount (bitLength N)-1)) :\n    reference N hN (.inl (.orGate side j))=table .orGate := rfl\n/-- ENTIRE original one-port input-check table is the literal table. -/\ntheorem input_table (N : ℕ) (hN : 0<N) (side : Fin 2) :\n    reference N hN (.inl (.inputCheck side))=table .inputCheck := rfl\n/-- ENTIRE original subdivided equality table is the literal two-port table. -/\ntheorem equality_table (N : ℕ) (hN : 0<N)\n    (signal : BitSignal (firstAxis (bitLength N)) (secondAxis (bitLength N)) (digitCount (bitLength N))) :\n    reference N hN (.inr signal)=table .equality := rfl\n/-- Acquired OR bytes are EXACTLY the original complete tagged tree. -/\ntheorem source_or (N : ℕ) (hN : 0<N) (side : Fin 2) (j : Fin (digitCount (bitLength N)-1)) :\n    SemiprimeD1StackBooleanTableSource.B.run SemiprimeD1StackBooleanTableSource.code 48\n      (SemiprimeD1StackBooleanTableSource.initial .orGate)=\n      some ⟨none,none,fun _=>SemiprimeD1TensorTapeCodec.tape (reference N hN (.inl (.orGate side j)))⟩ := by\n  rw [or_table]\n  exact SemiprimeD1StackBooleanTableSource.source_run .orGate\n/-- Acquired input-check bytes are EXACTLY its original complete tagged tree. -/\ntheorem source_input (N : ℕ) (hN : 0<N) (side : Fin 2) :\n    SemiprimeD1StackBooleanTableSource.B.run SemiprimeD1StackBooleanTableSource.code 12\n      (SemiprimeD1StackBooleanTableSource.initial .inputCheck)=\n      some ⟨none,none,fun _=>SemiprimeD1TensorTapeCodec.tape (reference N hN (.inl (.inputCheck side)))⟩ := by\n  rw [input_table]\n  exact SemiprimeD1StackBooleanTableSource.source_run .inputCheck\n/-- Acquired equality bytes are EXACTLY its original complete tagged tree. -/\ntheorem source_equality (N : ℕ) (hN : 0<N)\n    (signal : BitSignal (firstAxis (bitLength N)) (secondAxis (bitLength N)) (digitCount (bitLength N))) :\n    SemiprimeD1StackBooleanTableSource.B.run SemiprimeD1StackBooleanTableSource.code 24\n      (SemiprimeD1StackBooleanTableSource.initial .equality)=\n      some ⟨none,none,fun _=>SemiprimeD1TensorTapeCodec.tape (reference N hN (.inr signal))⟩ := by\n  rw [equality_table]\n  exact SemiprimeD1StackBooleanTableSource.source_run .equality\nend RiemannGaussian.SemiprimeD1BooleanRootTablesOriginal\n","RiemannGaussian.SemiprimeD1ChildPortBijection":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1ChildPortPullbackCorrectness\n\n/-! # Bijective computed original-port pullback\nThe cached physically resolved table contains each selected original endpoint\nonce and contains no missing entry. The codomain is constructed from original\nports and the acquired mask, not supplied as a desired permutation.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2800000\nnamespace RiemannGaussian.SemiprimeD1ChildPortBijection\nopen SemiprimeD1ChildPortPullback SemiprimeD1ChildPortPullbackCorrectness\nopen SemiprimeD1ChildGraph SemiprimeD1ChildActivePorts SemiprimeD1PacketInventory\nopen SemiprimeD1CollisionOriginal\n\n/-- Unmasked typed parent-port/side stream is the original Cartesian pair list. -/\ntheorem typed_full {I : Type*} (pairs : List (I×Placement)) :\n    (pairs.flatMap (fun p => [(p.1,true),(p.1,false)]))=\n      (pairs.map Prod.fst).product [true,false] := by\n  induction pairs with\n  | nil => rfl\n  | cons p pairs ih =>\n    simp only [List.flatMap_cons,List.map_cons,ih]\n    have hp : (p.1::pairs.map Prod.fst).product [true,false]=\n        [(p.1,true),(p.1,false)]++(pairs.map Prod.fst).product [true,false] :=\n      List.product_cons _ _ _\n    exact hp.symm\n\n/-- Actual mask restriction only deletes from the original typed endpoint stream. -/\ntheorem target_sublist {n F : ℕ} {inputArity : Fin F→ℕ}\n    (inputOwner : ((e : Fin F)×Fin (inputArity e))→Fin n)\n    (mask : SemiprimeSourceCompactBits.Report)\n    (pairs : List (((e : Fin F)×Fin (inputArity e))×Placement)) :\n    (targetLinks inputOwner mask pairs).Sublist\n      (pairs.flatMap (fun p => [(p.1,true),(p.1,false)])) := by\n  induction pairs with\n  | nil => exact List.Sublist.refl _\n  | cons p pairs ih =>\n    have hl : (if maskAt mask (endpoints inputOwner p.1 p.2).1 then [(p.1,true)] else []).Sublist [(p.1,true)] := by\n      split_ifs\n      · exact List.Sublist.refl _\n      · exact List.nil_sublist _\n    have hr : (if maskAt mask (endpoints inputOwner p.1 p.2).2 then [(p.1,false)] else []).Sublist [(p.1,false)] := by\n      split_ifs\n      · exact List.Sublist.refl _\n      · exact List.nil_sublist _\n    exact (hl.append hr).append ih\n\n/-- The exact original metadata incidence list has no repeated typed occurrence. -/\ntheorem original_ports_nodup (n F a : ℕ) (inputArity : Fin F→ℕ) :\n    (ports n F a inputArity).Nodup := by\n  change (SemiprimeSourceHistogramMetadata.acquire n F a inputArity).incidences.Nodup\n  rw [(SemiprimeSourceHistogramMetadata.original_fields n F a inputArity).1]\n  change (SemiprimePaidFiniteEnumerations.incidences F inputArity).value.Nodup\n  rw [SemiprimePaidFiniteEnumerations.incidences_value]\n  exact (SemiprimeFiniteEnumerations.indexedIncidences F inputArity).nodup\n\n/-- No selected original typed endpoint repeats in the actual target list. -/\ntheorem target_nodup (n F r a : ℕ) (inputArity : Fin F→ℕ)\n    (inputOwner : ((e : Fin F)×Fin (inputArity e))→Fin n) (q : Fin a) (g : Fin r) :\n    (targetLinks inputOwner (SemiprimeD1ChildActivation.acquire n F r a inputArity inputOwner q g)\n      (originalPairs n F r a inputArity inputOwner)).Nodup := by\n  let source := SemiprimeD1PacketReplayOriginal.acquire n F r a inputArity inputOwner\n  have hlen : (ports n F a inputArity).length=source.placements.length := by\n    have hh := congrArg List.length (SemiprimeD1PacketReplayOriginal.sources n F r a inputArity inputOwner)\n    rw [List.length_map,SemiprimeD1IncidenceAcquisition.keys_original,List.length_map] at hh\n    exact hh.symm\n  have hm : (originalPairs n F r a inputArity inputOwner).map Prod.fst=ports n F a inputArity :=\n    List.map_fst_zip hlen.le\n  have hn : ((originalPairs n F r a inputArity inputOwner).map Prod.fst).Nodup := by\n    rw [hm]\n    exact original_ports_nodup n F a inputArity\n  have hp : (((originalPairs n F r a inputArity inputOwner).map Prod.fst).product [true,false]).Nodup :=\n    hn.product (by decide : ([true,false]:List Bool).Nodup)\n  rw [←typed_full] at hp\n  exact (target_sublist inputOwner _ _).nodup hp\n\n/-- The actual acquired link cache is injective, including distinct original sides. -/\ntheorem links_nodup (n F r a : ℕ) [NeZero r] (inputArity : Fin F→ℕ)\n    (inputOwner : ((e : Fin F)×Fin (inputArity e))→Fin n) (q : Fin a) (g : Fin r) :\n    (SemiprimeD1ChildPortPullback.acquire n F r a inputArity inputOwner q g).links.Nodup := by\n  have hp := links_perm n F r a inputArity inputOwner q g\n  exact hp.nodup_iff.mpr ((target_nodup n F r a inputArity inputOwner q g).map (Option.some_injective _))\n\n/-- Every actually acquired child-port link resolves successfully. -/\ntheorem no_missing (n F r a : ℕ) [NeZero r] (inputArity : Fin F→ℕ)\n    (inputOwner : ((e : Fin F)×Fin (inputArity e))→Fin n) (q : Fin a) (g : Fin r) :\n    none∉(SemiprimeD1ChildPortPullback.acquire n F r a inputArity inputOwner q g).links := by\n  intro hm\n  have hp := (links_perm n F r a inputArity inputOwner q g).mem_iff.mp hm\n  simp at hp\n\n/-- Exact multiplicity of every original typed endpoint in the computed cache.\nThis is a constructive finite bijection certificate, not a supplied inverse. -/\ntheorem link_count (n F r a : ℕ) [NeZero r] (inputArity : Fin F→ℕ)\n    (inputOwner : ((e : Fin F)×Fin (inputArity e))→Fin n) (q : Fin a) (g : Fin r)\n    (link : ((e : Fin F)×Fin (inputArity e))×Bool) :\n    ((SemiprimeD1ChildPortPullback.acquire n F r a inputArity inputOwner q g).links.count (some link))=\n      if link∈targetLinks inputOwner (SemiprimeD1ChildActivation.acquire n F r a inputArity inputOwner q g)\n        (originalPairs n F r a inputArity inputOwner) then 1 else 0 := by\n  have hp := (links_perm n F r a inputArity inputOwner q g).count_eq (some link)\n  rw [hp,List.count_map_of_injective _ Option.some (Option.some_injective _) link]\n  exact (target_nodup n F r a inputArity inputOwner q g).count\n\n/-- Materialize the resolved typed port table by a paid finite cache scan.\nNone is skipped on malformed inputs; the original endpoint proves none absent. -/\ndef resolveCache {A : Type*} : List (Option A)→SemiprimeMaterializedWords.Run (List A)\n  | [] => ⟨[],2⟩\n  | none::xs =>\n    let tail := resolveCache xs\n    ⟨tail.value,tail.work+4⟩\n  | some x::xs =>\n    let tail := resolveCache xs\n    ⟨x::tail.value,tail.work+6⟩\n\n/-- The executed cache traversal returns exactly its successfully resolved links. -/\ntheorem resolveCache_value {A : Type*} (xs : List (Option A)) :\n    (resolveCache xs).value=xs.filterMap id := by\n  induction xs with\n  | nil => rfl\n  | cons x xs ih => cases x <;> simp only [resolveCache,List.filterMap_cons,ih,id_eq]\n\n/-- All visited option cells and typed metadata copies remain in the report. -/\ntheorem resolveCache_work {A : Type*} (xs : List (Option A)) :\n    (resolveCache xs).work≤6*xs.length+2 := by\n  induction xs with\n  | nil => rfl\n  | cons x xs ih => cases x <;> simp only [resolveCache,List.length_cons] <;> omega\n\n/-- Concrete cached permutation values, with no chosen inverse or advice. -/\ndef permutation {n F a : ℕ} {inputArity : Fin F→ℕ}\n    (data : SemiprimeD1ChildPortPullback.Acquired n F a inputArity) :\n    SemiprimeMaterializedWords.Run (List (((e : Fin F)×Fin (inputArity e))×Bool)) :=\n  let out := resolveCache data.links\n  ⟨out.value,data.work+out.work+3⟩\n\n/-- The actually materialized table is a permutation of all selected original endpoints. -/\ntheorem permutation_perm (n F r a : ℕ) [NeZero r] (inputArity : Fin F→ℕ)\n    (inputOwner : ((e : Fin F)×Fin (inputArity e))→Fin n) (q : Fin a) (g : Fin r) :\n    (permutation (SemiprimeD1ChildPortPullback.acquire n F r a inputArity inputOwner q g)).value.Perm\n      (targetLinks inputOwner (SemiprimeD1ChildActivation.acquire n F r a inputArity inputOwner q g)\n        (originalPairs n F r a inputArity inputOwner)) := by\n  have hp := (links_perm n F r a inputArity inputOwner q g).filterMap id\n  change (resolveCache _).value.Perm _\n  rw [resolveCache_value]\n  have he (xs : List (((e : Fin F)×Fin (inputArity e))×Bool)) : (xs.map some).filterMap id=xs := by\n    induction xs with\n    | nil => rfl\n    | cons x xs ih =>\n      change x::((xs.map some).filterMap id)=x::xs\n      rw [ih]\n  rw [he] at hp\n  exact hp\n\n/-- The cached typed pullback is injective as well as surjective onto its target. -/\ntheorem permutation_nodup (n F r a : ℕ) [NeZero r] (inputArity : Fin F→ℕ)\n    (inputOwner : ((e : Fin F)×Fin (inputArity e))→Fin n) (q : Fin a) (g : Fin r) :\n    (permutation (SemiprimeD1ChildPortPullback.acquire n F r a inputArity inputOwner q g)).value.Nodup :=\n  (permutation_perm n F r a inputArity inputOwner q g).nodup_iff.mpr\n    (target_nodup n F r a inputArity inputOwner q g)\n\n/-- Original old vertex of one typed original endpoint, without colour data. -/\ndef linkVertex {n F : ℕ} {inputArity : Fin F→ℕ}\n    (inputOwner : ((e : Fin F)×Fin (inputArity e))→Fin n)\n    (link : ((e : Fin F)×Fin (inputArity e))×Bool) : Fin (n+F) :=\n  if link.2 then ⟨(inputOwner link.1).val,by omega⟩ else ⟨n+link.1.1.val,by omega⟩\n\n/-- Actual acquired activation lookup for a typed original endpoint. -/\ndef activeLink {n F : ℕ} {inputArity : Fin F→ℕ}\n    (inputOwner : ((e : Fin F)×Fin (inputArity e))→Fin n)\n    (mask : SemiprimeSourceCompactBits.Report)\n    (link : ((e : Fin F)×Fin (inputArity e))×Bool) : Bool :=\n  (mask.bits[(linkVertex inputOwner link).val]?).getD false\n\n/-- The typed target list is an actual mask-filtered complete endpoint stream. -/\ntheorem target_filter {n F : ℕ} {inputArity : Fin F→ℕ}\n    (inputOwner : ((e : Fin F)×Fin (inputArity e))→Fin n)\n    (mask : SemiprimeSourceCompactBits.Report)\n    (pairs : List (((e : Fin F)×Fin (inputArity e))×Placement)) :\n    targetLinks inputOwner mask pairs=\n      ((pairs.map Prod.fst).product [true,false]).filter (activeLink inputOwner mask) := by\n  rw [←typed_full]\n  induction pairs with\n  | nil => rfl\n  | cons p pairs ih =>\n    change ((if maskAt mask (endpoints inputOwner p.1 p.2).1 then [(p.1,true)] else [])++\n      (if maskAt mask (endpoints inputOwner p.1 p.2).2 then [(p.1,false)] else []))++\n      targetLinks inputOwner mask pairs=_\n    rw [ih,List.flatMap_cons,List.filter_append]\n    congr 1\n    simp only [List.filter_cons,List.filter_nil,activeLink,linkVertex,maskAt,endpoints,ite_true,\n      Bool.false_eq_true,ite_false]\n    split_ifs\n    all_goals simp_all only [Bool.false_eq_true,ite_true,ite_false,List.cons_append,List.nil_append]\n    all_goals rfl\n\n/-- Every original typed port occurs in the actual original factor-major list. -/\ntheorem original_ports_complete (n F a : ℕ) (inputArity : Fin F→ℕ)\n    (i : (e : Fin F)×Fin (inputArity e)) : i∈ports n F a inputArity := by\n  change i∈(SemiprimeSourceHistogramMetadata.acquire n F a inputArity).incidences\n  rw [(SemiprimeSourceHistogramMetadata.original_fields n F a inputArity).1]\n  change i∈(SemiprimePaidFiniteEnumerations.incidences F inputArity).value\n  rw [SemiprimePaidFiniteEnumerations.incidences_value]\n  exact (SemiprimeFiniteEnumerations.indexedIncidences F inputArity).complete i\n\n/-- Target membership is exactly the physical activation bit of the old vertex. -/\ntheorem target_mem (n F r a : ℕ) (inputArity : Fin F→ℕ)\n    (inputOwner : ((e : Fin F)×Fin (inputArity e))→Fin n) (q : Fin a) (g : Fin r)\n    (link : ((e : Fin F)×Fin (inputArity e))×Bool) :\n    link∈targetLinks inputOwner (SemiprimeD1ChildActivation.acquire n F r a inputArity inputOwner q g)\n      (originalPairs n F r a inputArity inputOwner) ↔\n      activeLink inputOwner (SemiprimeD1ChildActivation.acquire n F r a inputArity inputOwner q g) link=true := by\n  let source := SemiprimeD1PacketReplayOriginal.acquire n F r a inputArity inputOwner\n  have hl : (ports n F a inputArity).length=source.placements.length := by\n    have hh := congrArg List.length (SemiprimeD1PacketReplayOriginal.sources n F r a inputArity inputOwner)\n    rw [List.length_map,SemiprimeD1IncidenceAcquisition.keys_original,List.length_map] at hh\n    exact hh.symm\n  have hm : (originalPairs n F r a inputArity inputOwner).map Prod.fst=ports n F a inputArity :=\n    List.map_fst_zip hl.le\n  rw [target_filter,hm,List.mem_filter]\n  have hi := original_ports_complete n F a inputArity link.1\n  have hb : link.2∈([true,false]:List Bool) := by cases link.2 <;> simp\n  have hprod : link∈(ports n F a inputArity).product [true,false] := by\n    change (link.1,link.2)∈(ports n F a inputArity).product [true,false]\n    exact List.mem_product.mpr ⟨hi,hb⟩\n  simp only [hprod,true_and]\n\n/-- Every original incident port of a selected old vertex is present exactly once\nin the actually computed permutation; inactive old vertices contribute none. -/\ntheorem permutation_count (n F r a : ℕ) [NeZero r] (inputArity : Fin F→ℕ)\n    (inputOwner : ((e : Fin F)×Fin (inputArity e))→Fin n) (q : Fin a) (g : Fin r)\n    (link : ((e : Fin F)×Fin (inputArity e))×Bool) :\n    ((permutation (SemiprimeD1ChildPortPullback.acquire n F r a inputArity inputOwner q g)).value.count link)=\n      if activeLink inputOwner (SemiprimeD1ChildActivation.acquire n F r a inputArity inputOwner q g) link\n        then 1 else 0 := by\n  have hp := (permutation_perm n F r a inputArity inputOwner q g).count_eq link\n  rw [hp,(target_nodup n F r a inputArity inputOwner q g).count]\n  simp only [target_mem]\n\n/-- Literal cached endpoint of one typed child factor-major incidence. -/\ndef portEntry {V : ℕ} (graph : Graph V)\n    (i : (f : Fin graph.factors.length)×Fin (SemiprimeD1ChildGraph.arity graph f)) : Endpoint V :=\n  graph.factors[i.1.val][i.2.val]\n\n/-- Actual typed child metadata enumerates the complete cached endpoint records,\nnot only their vertex projections. -/\ntheorem port_entries {V : ℕ} (graph : Graph V) (Q : ℕ) :\n    (ports V graph.factors.length Q (SemiprimeD1ChildGraph.arity graph)).map (portEntry graph)=\n      graph.factors.flatten := by\n  have inner (f : Fin graph.factors.length) :\n      (List.finRange (SemiprimeD1ChildGraph.arity graph f)).map (fun j => portEntry graph ⟨f,j⟩)=\n        graph.factors[f.val] := by\n    simpa only [List.finRange,List.map_ofFn,Function.comp_def,portEntry,SemiprimeD1ChildGraph.arity] using\n      (List.ofFn_getElem (xs:=graph.factors[f.val]))\n  have hmap : (List.finRange graph.factors.length).map (fun f => graph.factors[f.val])=graph.factors := by\n    simpa only [List.finRange,List.map_ofFn,Function.comp_def] using\n      (List.ofFn_getElem (xs:=graph.factors))\n  have houter := congrArg (fun bs : List (List (Endpoint V)) => bs.flatMap id) hmap\n  rw [List.flatMap_map] at houter\n  have hflat (bs : List (List (Endpoint V))) : bs.flatMap id=bs.flatten := by\n    induction bs with\n    | nil => rfl\n    | cons b bs ih => simp only [List.flatMap_cons,List.flatten_cons,ih,id_eq]\n  simp only [ports,SemiprimeSourceHistogramMetadata.acquire,\n    SemiprimePaidFiniteEnumerationLists.flat_value,SemiprimeSourceHistogramMetadata.finFast_value,\n    SemiprimeSourceHistogramMetadata.ports_value,List.map_flatMap,List.map_map,Function.comp_def]\n  trans (List.finRange graph.factors.length).flatMap (fun f => graph.factors[f.val])\n  · congr 1\n    funext f\n    exact inner f\n  · exact houter.trans (hflat graph.factors)\n\n/-- The computed cache is aligned with the literal typed child port enumeration. -/\ntheorem pullback_port_order (n F r a Q : ℕ) (inputArity : Fin F→ℕ)\n    (inputOwner : ((e : Fin F)×Fin (inputArity e))→Fin n) (q : Fin a) (g : Fin r) :\n    let data := SemiprimeD1ChildPortPullback.acquire n F r a inputArity inputOwner q g\n    data.links=(ports (n+F) data.graph.factors.length Q (SemiprimeD1ChildGraph.arity data.graph)).map\n      (fun i => resolve data.ids (portEntry data.graph i)) := by\n  dsimp only\n  let data := SemiprimeD1ChildPortPullback.acquire n F r a inputArity inputOwner q g\n  have he := congrArg (List.map (resolve data.ids)) (port_entries data.graph Q)\n  simp only [List.map_map,Function.comp_def] at he\n  change data.links=_\n  rw [he]\n  exact SemiprimeD1ChildPortPullback.pull_value _ _\n\nend RiemannGaussian.SemiprimeD1ChildPortBijection\n","RiemannGaussian.SemiprimeD1CrossingExpansion":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1CrossingCoefficient\nimport Mathlib.Algebra.Ring.GeomSum\n\n/-! # Finite positive crossing expansions with an acquired divisible remainder\nAll scalar numerators and odd denominators are constructed from the original\ninteger grid. No infinite series or desired-integrality premise is used.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1CrossingExpansion\nopen scoped BigOperators\nopen Polynomial SemiprimeD1WireKernel SemiprimeD1WireKernelFactors\n  SemiprimeD1WireKernelEntry SemiprimeD1WireKernelOriginal SemiprimeD1WireKernelPaper\n  SemiprimeD1CrossingCoefficient\n\n/-- Stripped tile step; this is a positive power of two for a crossing. -/\ndef step (k i j d : ℕ) : ℤ := (2:ℤ)^(i+1-factorOrder k j d)\n\n/-- Actual denominator unit at the displaced tile column. -/\ndef targetUnit (k i j d : ℕ) (z tile : ℤ) : ℤ :=\n  unitFactor k j d z-step k i j d*tile\n\n/-- The shifted denominator remains odd: only an even multiple was subtracted. -/\ntheorem targetUnit_odd (k i j d : ℕ) (z tile : ℤ) (hj : j<2^k)\n    (hd : d<2^k) (hne : d≠j) (hv : padicValInt 2 (difference j d)≤ i) :\n    Odd (targetUnit k i j d z tile) := by\n  have ho : factorOrder k j d≤ i := by simpa [factorOrder,hne] using hv\n  have hs : Even (step k i j d) := by\n    apply even_iff_two_dvd.mpr\n    exact dvd_pow_self 2 (by omega)\n  exact (unitFactor_odd k j d z hj hd hne).sub_even (hs.mul_right tile)\n\n/-- Full target fraction after cancelling the exact common two-content. -/\ndef target (k center i j d : ℕ) (z tile : ℤ) : Coefficient :=\n  ⟨(2:ℤ)^excess k j d*omittedProduct k j d z*unitFactor k j d z,\n    oddDenominator k center*targetUnit k i j d z tile⟩\n\n/-- Explicit finite geometric remainder, entirely integer acquired data. -/\ndef remainder (k center i j d m : ℕ) (z tile : ℤ) : Coefficient :=\n  ⟨(2:ℤ)^modePower k i j d m*omittedProduct k j d z*tile^m*unitFactor k j d z,\n    oddDenominator k center*(unitFactor k j d z)^m*targetUnit k i j d z tile⟩\n\n/-- Both finite target and remainder invert only genuinely odd original units. -/\ntheorem target_remainder_odd (k center i j d m : ℕ) (z tile : ℤ)\n    (hc : center<2^k) (hj : j<2^k) (hd : d<2^k) (hne : d≠j)\n    (hv : padicValInt 2 (difference j d)≤ i) :\n    Odd (target k center i j d z tile).denominator ∧\n      Odd (remainder k center i j d m z tile).denominator := by\n  have hu := unitFactor_odd k j d z hj hd hne\n  have ht := targetUnit_odd k i j d z tile hj hd hne hv\n  exact ⟨(denominator_odd k center hc).mul ht,\n    ((denominator_odd k center hc).mul hu.pow).mul ht⟩\n\n/-- The true finite remainder has at least m+1 powers of two. -/\ntheorem remainder_divisible (k center i j d m : ℕ) (z tile : ℤ)\n    (hj : j<2^k) (hd : d<2^k) (hi : i<k) (hne : d≠j)\n    (hv : padicValInt 2 (difference j d)≤ i) :\n    (2:ℤ)^(m+1) ∣ (remainder k center i j d m z tile).numerator := by\n  exact dvd_mul_of_dvd_left (dvd_mul_of_dvd_left\n    (dvd_mul_of_dvd_left (pow_dvd_pow 2 (modePower_ge k i j d m hj hd hi hne hv)) _) _) _\n\n/-- A positive geometric expansion with an exact finite remainder over any field. -/\ntheorem finite_geometric {K : Type*} [Field K] (A U V : K) (hU : U≠0)\n    (hV : U-V≠0) (m : ℕ) :\n    A*U/(U-V)=A*(∑ b∈Finset.range m,(V/U)^b)+A*(V/U)^m*U/(U-V) := by\n  have hg := geom_sum_mul_neg (V/U) m\n  have hratio : 1-V/U=(U-V)/U := by field_simp\n  rw [hratio] at hg\n  have he : (∑ b∈Finset.range m,(V/U)^b)*(U-V)=(1-(V/U)^m)*U := by\n    have ht := congrArg (fun x:K => x*U) hg\n    simpa only [div_mul_cancel₀ _ hU,mul_assoc] using ht\n  apply (div_eq_iff hV).2\n  field_simp [hV]\n  linear_combination -A*he\n\n/-- Every acquired mode is the base fraction times a POSITIVE geometric power. -/\ntheorem mode_value (k center i j d b : ℕ) (z tile : ℤ) :\n    value (SemiprimeD1CrossingCoefficient.acquire k center i j d b z)*(tile:ℚ)^b=\n      ((2:ℚ)^excess k j d*(omittedProduct k j d z:ℚ)/(oddDenominator k center:ℚ))*\n        (((step k i j d:ℤ):ℚ)*(tile:ℚ)/(unitFactor k j d z:ℚ))^b := by\n  unfold value SemiprimeD1CrossingCoefficient.acquire modePower step\n  simp only [Int.cast_mul,Int.cast_pow,Int.cast_ofNat,pow_add,div_pow,mul_pow]\n  rw [show b*(i+1-factorOrder k j d)=(i+1-factorOrder k j d)*b by exact Nat.mul_comm _ _,pow_mul]\n  ring\n\n/-- Exact D.12 scalar finite expansion, including an explicit original-derived remainder. -/\ntheorem expansion (k center i j d m : ℕ) (z tile : ℤ)\n    (hc : center<2^k) (hj : j<2^k) (hd : d<2^k) (hne : d≠j)\n    (hv : padicValInt 2 (difference j d)≤ i) :\n    value (target k center i j d z tile)=\n      (∑ b∈Finset.range m,value (SemiprimeD1CrossingCoefficient.acquire k center i j d b z)*(tile:ℚ)^b)+\n      value (remainder k center i j d m z tile) := by\n  have hu := unitFactor_odd k j d z hj hd hne\n  have ht := targetUnit_odd k i j d z tile hj hd hne hv\n  have hun : (unitFactor k j d z:ℚ)≠0 := by\n    exact_mod_cast (show unitFactor k j d z≠0 by intro h;rw [h] at hu;simp at hu)\n  have htn : (unitFactor k j d z:ℚ)-(step k i j d:ℚ)*(tile:ℚ)≠0 := by\n    have h : targetUnit k i j d z tile≠0 := by intro h;rw [h] at ht;simp at ht\n    exact_mod_cast h\n  have hdn : (oddDenominator k center:ℚ)≠0 := by exact_mod_cast denominator_ne_zero k center hc\n  have hg := finite_geometric\n    ((2:ℚ)^excess k j d*(omittedProduct k j d z:ℚ)/(oddDenominator k center:ℚ))\n    (unitFactor k j d z:ℚ) ((step k i j d:ℚ)*(tile:ℚ)) hun htn m\n  simp_rw [mode_value]\n  rw [← Finset.mul_sum]\n  convert hg using 1\n  · simp only [value,target,Int.cast_mul,Int.cast_pow,Int.cast_ofNat,targetUnit,Int.cast_sub]\n    field_simp [hdn,htn]\n  · congr 1\n    simp only [value,remainder,modePower,Int.cast_mul,Int.cast_pow,Int.cast_ofNat,\n      targetUnit,Int.cast_sub,step,pow_add,div_pow,mul_pow]\n    rw [show m*(i+1-factorOrder k j d)=(i+1-factorOrder k j d)*m by exact Nat.mul_comm _ _,pow_mul]\n    field_simp [hdn,hun,htn]\n\nend RiemannGaussian.SemiprimeD1CrossingExpansion\n","RiemannGaussian.SemiprimeD1FactorScopePairEncoding":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackFactorScopePairs\n/-! # Exact nine-field input and factor-key/scope-ID pair byte specifications -/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1FactorScopePairEncoding\nopen SemiprimeSourceHistogramKeyBits (frame frame_length)\n/-- Nine actual parsed fields, scope ID at0 and unchanged factor ordinal at2. -/\nabbrev Record := Fin 9→List Bool\n/-- Proof-only list view of the fixed nine physical input fields. -/\ndef fields (w : Record) : List (List Bool) := List.ofFn w\n/-- Input suffix after a fixed number of actual field parses. -/\ndef suffix (w : Record) (n : Nat) (tail : List Bool) : List Bool :=\n  ((fields w).drop n).foldr frame tail\n/-- Exact source input record, without any artificial row tag. -/\ndef record (w : Record) (tail : List Bool) : List Bool := suffix w 0 tail\n/-- EOF-terminated source stream, preserving original factor-major order. -/\ndef stream (rows : List Record) (tail : List Bool) : List Bool := rows.foldr record tail\n/-- Actual original port plus actual acquired scope ID in authoritative order. -/\ndef joined (w : SemiprimeD1PortScopeEncoding.Port) (id : List Bool) : Record :=\n  ![id,w 0,w 1,w 2,w 3,w 4,w 5,w 6,w 7]\n/-- Literal source grammar agrees exactly with the fixed nine-field parser. -/\ntheorem joined_record (w : SemiprimeD1PortScopeEncoding.Port) (id tail : List Bool) :\n    record (joined w id) tail=SemiprimeD1PortScopeEncoding.scopeFrame w id tail := rfl\n/-- The ordered source output is exactly the zipped nine-field stream. -/\ntheorem joined_stream (ports : List SemiprimeD1PortScopeEncoding.Port) (ids : List (List Bool)) (tail : List Bool) :\n    stream (List.zipWith joined ports ids) tail=SemiprimeD1PortScopeEncoding.output ports ids tail := by\n  induction ports generalizing ids with\n  | nil=>rfl\n  | cons w ws ih=>cases ids with\n    | nil=>rfl\n    | cons id ids=>\n      change record (joined w id) (stream (List.zipWith joined ws ids) tail)=_\n      rw [joined_record,ih]\n      rfl\n/-- Every fixed parser step exposes precisely the next actual framed field. -/\ntheorem suffix_step (w : Record) (part : Fin 9) (tail : List Bool) :\n    suffix w part.val tail=frame (w part) (suffix w (part.val+1) tail) := by fin_cases part <;> rfl\n/-- All nine physical input fields consumed leaves the exact source suffix. -/\ntheorem suffix_end (w : Record) (tail : List Bool) : suffix w 9 tail=tail := rfl\n/-- Key and scope are unchanged physical payloads, never recoded ordinals. -/\ndef pair (w : Record) : List Bool×List Bool := (w 2,w 0)\n/-- Exact tagged two-field row before the one final false catalogue terminator. -/\ndef row (w : Record) : List Bool := true::frame (w 2) (frame (w 0) [])\n/-- Forward row bytes used by the single final physical reversal. -/\ndef raw (rows : List Record) : List Bool := rows.foldr (fun w tail=>row w++tail) []\n/-- Literal pair catalogue is the generic owner-fibre input grammar. -/\ntheorem raw_records (rows : List Record) (tail : List Bool) :\n    raw rows++false::tail=SemiprimeD1StackOwnerFibre.records (rows.map pair) tail := by\n  induction rows with\n  | nil=>rfl\n  | cons w rows ih=>\n    change (row w++raw rows)++false::tail=true::frame (w 2)\n      (frame (w 0) (SemiprimeD1StackOwnerFibre.records (rows.map pair) tail))\n    rw [List.append_assoc,ih]\n    simp only [row,List.cons_append]\n    rw [←SemiprimeD1StackEdgeCatalogueEmit.frame_tail (w 2),\n      ←SemiprimeD1StackEdgeCatalogueEmit.frame_tail (w 0)]\n    rfl\n/-- Actual byte payload mass of all nine input fields. -/\ndef mass (w : Record) : Nat := ((fields w).map List.length).sum\n/-- Every input marker, data byte and field delimiter is counted. -/\ntheorem record_length (w : Record) (tail : List Bool) : (record w tail).length=2*mass w+9+tail.length := by\n  have h (xs : List (List Bool)) : (xs.foldr frame tail).length=2*(xs.map List.length).sum+xs.length+tail.length := by\n    induction xs with\n    | nil=>simp\n    | cons x xs ih=>simp only [List.foldr_cons,frame_length,List.map_cons,List.sum_cons,List.length_cons,ih];omega\n  simpa only [record,suffix,List.drop_zero,mass,fields,List.length_ofFn,Fintype.card_fin] using h (fields w)\nend RiemannGaussian.SemiprimeD1FactorScopePairEncoding\n","RiemannGaussian.SemiprimeD1GlobalRate":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1OriginalEnvelopeRate\n\n/-! # Fixed polynomial slowdowns and all-input rate constants\nThese arithmetic endpoints preserve the requested quantitative rate and absorb\nthe finite initial input segment. A caller must first prove the actual machine\ntime or report inequality being substituted; no simulation is assumed here.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 400000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1GlobalRate\nopen Filter SemiprimeD1OriginalCallRate SemiprimeMacroParameters\nopen scoped Topology\n\n/-- Computable finite initial-segment budget for a fixed total cost function. -/\ndef finiteBudget (cost : ℕ→ℕ) (cutoff : ℕ) : ℕ :=\n  1+∑N∈Finset.range (2^cutoff),cost N\n\n/-- Every actual cost in the finite binary-input segment is included. -/\ntheorem finiteBudget_le (cost : ℕ→ℕ) (cutoff N : ℕ) (hN:N<2^cutoff) :\n    cost N  ≤  finiteBudget cost cutoff := by\n  have h:=Finset.single_le_sum (fun k (_:k∈Finset.range (2^cutoff))=>Nat.zero_le (cost k))\n    (Finset.mem_range.mpr hN)\n  unfold finiteBudget\n  omega\n\nnoncomputable section\n\n/-- A uniform positive scale is available even for one-bit positive inputs. -/\ntheorem inputScale_ge_half (ell : ℕ) (hell:1  ≤  ell) : (1/2:ℝ)  ≤  inputScale ell := by\n  have he:(1:ℝ)  ≤  ell:=by exact_mod_cast hell\n  have hlog:0<Real.log (ell+2:ℕ):=Real.log_pos (by exact_mod_cast (by omega:1<ell+2))\n  have hb:=Real.log_le_sub_one_of_pos (show (0:ℝ)<(ell+2:ℕ) by positivity)\n  have hs:Real.sqrt (Real.log (ell+2:ℕ))  ≤  2*(ell:ℝ):=by\n    apply (Real.sqrt_le_left (by positivity)).mpr\n    push_cast at hb ⊢\n    nlinarith\n  unfold inputScale\n  apply (le_div_iff₀ (Real.sqrt_pos.mpr hlog)).mpr\n  linarith\n\n/-- A concrete fixed polynomial overhead changes only this exponent constant. -/\ndef slowdownConstant (A d C : ℕ) : ℕ := 2*A+d*(C+2)\n\n/-- Quantitative absorption for a proved polynomial simulation inequality.\nThis is arithmetic, not a machine-simulation premise supplied to the algorithm. -/\ntheorem polynomial_slowdown (A d C work : ℕ) (B : ℝ) (hB:(1/2:ℝ)  ≤  B)\n    (hwork:(work:ℝ)  ≤  (2:ℝ)^((C:ℝ)*B)) :\n    (A*(work+1)^d:ℕ)  ≤  (2:ℝ)^((slowdownConstant A d C:ℝ)*B) := by\n  have hpow:(1:ℝ)  ≤  (2:ℝ)^((C:ℝ)*B):=Real.one_le_rpow (by norm_num) (by positivity)\n  have hplus:(work:ℝ)+1  ≤  (2:ℝ)^((C:ℝ)*B+1):=by\n    rw [Real.rpow_add (by norm_num:0<(2:ℝ)),Real.rpow_one]\n    linarith\n  have hA:(A:ℝ)  ≤  (2:ℝ)^(A:ℝ):=by\n    simpa only [Real.rpow_natCast,Nat.cast_pow,Nat.cast_ofNat] using\n      (show (A:ℝ)  ≤  (2^A:ℕ) by exact_mod_cast (Nat.le_of_lt (Nat.lt_two_pow_self (n:=A))))\n  have hd:=pow_le_pow_left₀ (by positivity:(0:ℝ)  ≤  (work:ℝ)+1) hplus d\n  have hm:=mul_le_mul hA hd (by positivity) (by positivity)\n  have hpower:((2:ℝ)^((C:ℝ)*B+1))^d=(2:ℝ)^(((C:ℝ)*B+1)*d):=\n    (Real.rpow_mul_natCast (by norm_num:0  ≤  (2:ℝ)) _ _).symm\n  rw [hpower,←Real.rpow_add (by norm_num:0<(2:ℝ))] at hm\n  have hm':(A*(work+1)^d:ℕ)  ≤  (2:ℝ)^((A:ℝ)+((C:ℝ)*B+1)*d):=by\n    simpa only [Nat.cast_mul,Nat.cast_pow,Nat.cast_add,Nat.cast_one] using hm\n  apply hm'.trans\n  apply Real.rpow_le_rpow_of_exponent_le (by norm_num:1  ≤  (2:ℝ))\n  unfold slowdownConstant\n  push_cast\n  nlinarith [show (0:ℝ) ≤ (A:ℝ) by positivity,show (0:ℝ) ≤ (d:ℝ) by positivity]\n\n/-- An eventual original-length bound extends to EVERY positive original input\nwith one constant chosen before the entire family. No empirical finite coverage\nor new fallback algorithm is used; the fixed total cost itself pays the prefix. -/\ntheorem eventually_to_all (cost : ℕ→ℕ) (C₀ : ℕ)\n    (h:∀ᶠ ell:ℕ in atTop,∀N:ℕ,0<N→bitLength N=ell→\n      (cost N:ℝ)  ≤  (2:ℝ)^((C₀:ℝ)*inputScale ell)) :\n    ∃C:ℕ,∀N:ℕ,0<N→(cost N:ℝ)  ≤  (2:ℝ)^((C:ℝ)*inputScale (bitLength N)) := by\n  obtain ⟨L,hL⟩:=eventually_atTop.mp h\n  let M:=finiteBudget cost L\n  refine ⟨C₀+2*M,?_⟩\n  intro N hN\n  have hB:=inputScale_ge_half (bitLength N) (bitLength_pos hN)\n  by_cases hell:L  ≤  bitLength N\n  · apply (hL (bitLength N) hell N hN rfl).trans\n    apply Real.rpow_le_rpow_of_exponent_le (by norm_num:1  ≤  (2:ℝ))\n    push_cast\n    nlinarith [show (0:ℝ) ≤ (M:ℝ) by positivity]\n  · have hsize:N<2^L:=(input_lt_bitLength_power N).trans_le\n      (Nat.pow_le_pow_right (by decide:0<(2:ℕ)) (by omega))\n    have hcost:cost N  ≤  M:=finiteBudget_le cost L N hsize\n    have hnat:cost N  ≤  2^M:=hcost.trans (Nat.le_of_lt (Nat.lt_two_pow_self (n:=M)))\n    have hreal:(cost N:ℝ)  ≤  (2:ℝ)^(M:ℝ):=by\n      simpa only [Real.rpow_natCast,Nat.cast_pow,Nat.cast_ofNat] using\n        (show (cost N:ℝ)  ≤  (2^M:ℕ) by exact_mod_cast hnat)\n    apply hreal.trans\n    apply Real.rpow_le_rpow_of_exponent_le (by norm_num:1  ≤  (2:ℝ))\n    push_cast\n    nlinarith [show (0:ℝ) ≤ (M:ℝ) by positivity,show (0:ℝ) ≤ (C₀:ℝ) by positivity]\n\nend\nend RiemannGaussian.SemiprimeD1GlobalRate\n","RiemannGaussian.SemiprimeD1GridRawSum":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1GridHistogram\n\n/-! # Original signed-grid valuation sum as an exact translated residue sum -/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1GridRawSum\nopen scoped BigOperators\nopen SemiprimeD1GridValuation SemiprimeD1GridResidue SemiprimeD1GridHistogram\n  SemiprimeD1WireKernelOriginal SemiprimeD1TaperedLoss SemiprimeD1JetRecoveryGrid\n\n/-- Literal complete residue grid with the actual zero/own node removed. -/\ndef residueOthers (k : ℕ) (t : ZMod (2^k)) : Finset (ZMod (2^k)) :=\n  (Finset.univ.erase 0).erase t\n\n/-- Translated exact raw valuation sum, with the original taper. -/\ndef residueValuation (k h u : ℕ) (t : ZMod (2^k)) : ℤ :=\n  ∑ x∈residueOthers k t,(multiplicity h u (order k x):ℤ)*\n    ((order k x:ℤ)-(order k (t-x):ℤ))\n\n/-- Actual original raw grid and residue sums agree by an explicit finite bijection. -/\ntheorem original_raw_sum (a h u : ℕ) (t : Fin (size a)) :\n    rawValuation a h u t.val=residueValuation (a+1) h u (gridEquiv a t) := by\n  unfold rawValuation residueValuation\n  let idx := fun (q:ℕ) (hq:q∈others a t.val) =>\n    (⟨q,Finset.mem_range.mp (Finset.mem_erase.mp (Finset.mem_erase.mp hq).2).2⟩:Fin (size a))\n  apply Finset.sum_bij (fun q hq => gridEquiv a (idx q hq))\n  · intro q hq\n    have hmem := (original_membership a t (idx q hq)).mp hq\n    exact Finset.mem_erase.mpr ⟨hmem.2,Finset.mem_erase.mpr ⟨hmem.1,Finset.mem_univ _⟩⟩\n  · intro q hq r hr he\n    exact congrArg Fin.val ((gridEquiv a).injective he)\n  · intro x hx\n    let q := (gridEquiv a).symm x\n    have hq : q.val∈others a t.val := by\n      apply (original_membership a t q).mpr\n      change gridEquiv a ((gridEquiv a).symm x)≠0 ∧ gridEquiv a ((gridEquiv a).symm x)≠gridEquiv a t\n      rw [Equiv.apply_symm_apply]\n      exact ⟨(Finset.mem_erase.mp (Finset.mem_erase.mp hx).2).1,(Finset.mem_erase.mp hx).1⟩\n    refine ⟨q.val,hq,?_⟩\n    have he : idx q.val hq=q := Fin.ext rfl\n    rw [he]\n    exact (gridEquiv a).apply_symm_apply x\n  · intro q hq\n    have hqc : q≠center a := (Finset.mem_erase.mp (Finset.mem_erase.mp hq).2).1\n    have hqt : idx q hq≠t := by intro he;exact (Finset.mem_erase.mp hq).1 (congrArg Fin.val he)\n    rw [original_order a (idx q hq) hqc,original_difference_order a t (idx q hq) hqt]\n    rfl\n\n/-- Every original residue raw sum is supported on genuine nonzero values. -/\ntheorem residue_membership (k : ℕ) (t x : ZMod (2^k)) :\n    x∈residueOthers k t ↔ x≠0 ∧ x≠t := by\n  simp only [residueOthers,Finset.mem_erase,Finset.mem_univ,and_true]\n  tauto\n\n/-- The ORIGINAL own/zero-node exclusion is preserved by literal reflection. -/\ntheorem residue_reflect (k : ℕ) (t x : ZMod (2^k)) :\n    x∈residueOthers k t ↔ (t-x)∈residueOthers k t := by\n  rw [residue_membership,residue_membership]\n  exact reflect_membership k t x\n\nend RiemannGaussian.SemiprimeD1GridRawSum\n","RiemannGaussian.SemiprimeD1HermiteDenominatorBits":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1HermiteDenominatorHeight\n\n/-! # Original-derived polynomial dyadic envelopes for acquired cardinal/inverse arrays\nThe bounds are attached to actual canonical coefficients and inverse prefix\naccumulators. They are bit-length/height results, not a complete primitive clock.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1HermiteDenominatorBits\nopen SemiprimeD1HermiteDenominatorHeight SemiprimeD1WireKernelOriginal\n  SemiprimeD1JetRecoveryGrid SemiprimeD1JetRecoveryWeights SemiprimeD1TaperedLoss\n  SemiprimeD1WeightPrecision SemiprimeJetArray SemiprimeJetArrayHeight\n\n/-- Logarithmic denominator cap from actual original factor-list length. -/\ndef denominatorExponent (a h u t : ℕ) : ℕ := (a+1)*(slopes a h u t).length\n\n/-- Logarithmic numerator cap of the actual retained original cardinal array. -/\ndef numeratorExponent (a h u t : ℕ) : ℕ :=\n  (nodeMultiplicity a h u t+a+1)*(slopes a h u t).length\n\n/-- Shared logarithmic cap for the ACTUAL inverse outputs and scalar-prefix accumulators. -/\ndef inverseExponent (a h u t : ℕ) : ℕ :=\n  nodeMultiplicity a h u t*(nodeMultiplicity a h u t+denominatorExponent a h u t+\n    numeratorExponent a h u t+3)\n\n/-- Elementary native size bound used only to turn polynomial magnitudes into logarithms. -/\ntheorem self_le_two_power (n : ℕ) : n≤2^n := by\n  induction n with\n  | zero => simp\n  | succ n ih =>\n    rw [pow_succ]\n    have hp : 1≤2^n := Nat.one_le_two_pow\n    omega\n\n/-- Actual product common denominator fits the original-derived dyadic envelope. -/\ntheorem denominator_bound (a h u : ℕ) (t : Fin (size a)) :\n    sourceDenominator a h u t.val≤2^denominatorExponent a h u t.val := by\n  have h := commonDenominator_le (size a) (slopes a h u t.val)\n    (fun c hc => (original_slope_bounds a h u t c hc).1)\n  simpa only [sourceDenominator,denominatorExponent,SemiprimeD1WireKernelOriginal.size,← pow_mul] using h\n\n/-- Actual cardinal numerator bound has polynomial logarithm, not a recurrence tower. -/\ntheorem numerator_bound (a h u t : ℕ) : sourceNumerator a h u t≤2^numeratorExponent a h u t := by\n  let q := nodeMultiplicity a h u t\n  have hq : q≤2^q := self_le_two_power q\n  have hb : q*size a≤2^(q+a+1) := by\n    calc\n      _ ≤ 2^q*size a := Nat.mul_le_mul_right _ hq\n      _ = _ := by rw [SemiprimeD1WireKernelOriginal.size,← pow_add,Nat.add_assoc]\n  have hp := Nat.pow_le_pow_left hb (slopes a h u t).length\n  simpa only [sourceNumerator,numeratorExponent,q,← pow_mul] using hp\n\n/-- Pure finite inverse-base arithmetic: polynomial logarithmic growth only. -/\ntheorem inverseBase_bound (J d B e f : ℕ) (hd : d≤2^e) (hB : B≤2^f) :\n    inverseBase J d B≤2^(J+e+f+3) := by\n  have he : 2^e≤2^(e+f) := Nat.pow_le_pow_right (by decide : 0<(2:ℕ)) (Nat.le_add_right e f)\n  have hf : 2^f≤2^(e+f) := Nat.pow_le_pow_right (by decide : 0<(2:ℕ)) (Nat.le_add_left f e)\n  have hp : 1≤2^(e+f) := Nat.one_le_two_pow\n  have hJ : J≤2^J := self_le_two_power J\n  have hs : d+B+1≤3*2^(e+f) := by omega\n  have hm := Nat.mul_le_mul hJ hs\n  have hone : 1≤2^J*2^(e+f) := by nlinarith [Nat.one_le_two_pow (n:=J),Nat.one_le_two_pow (n:=e+f)]\n  unfold inverseBase\n  rw [show J+e+f+3=J+(e+f)+3 by omega,pow_add,pow_add]\n  norm_num\n  nlinarith\n\n/-- One shared original exponent covers both actual inverse common-denominator\nand actual inverse common-numerator power bounds. -/\ntheorem inverse_power_bounds (a h u : ℕ) (t : Fin (size a)) :\n    (sourceDenominator a h u t.val)^nodeMultiplicity a h u t.val≤2^inverseExponent a h u t.val ∧\n    (inverseBase (nodeMultiplicity a h u t.val) (sourceDenominator a h u t.val)\n      (sourceNumerator a h u t.val))^nodeMultiplicity a h u t.val≤2^inverseExponent a h u t.val := by\n  have hd := denominator_bound a h u t\n  have hB := numerator_bound a h u t.val\n  have hb := inverseBase_bound (nodeMultiplicity a h u t.val) _ _ _ _ hd hB\n  constructor\n  · have hp := Nat.pow_le_pow_left hd (nodeMultiplicity a h u t.val)\n    rw [← pow_mul] at hp\n    exact hp.trans (Nat.pow_le_pow_right (by decide : 0<(2:ℕ)) (by unfold inverseExponent;nlinarith))\n  · have hp := Nat.pow_le_pow_left hb (nodeMultiplicity a h u t.val)\n    simpa only [← pow_mul,inverseExponent,Nat.mul_comm] using hp\n\n/-- ACTUAL normalized inverse output numerators/denominators have an explicit\npolynomial-logarithm dyadic height, without an output-fit oracle. -/\ntheorem original_inverse_bits (a h u : ℕ) (t : Fin (size a))\n    (hq : 0<nodeMultiplicity a h u t.val) (k : ℕ) (hk : k<nodeMultiplicity a h u t.val) :\n    (coefficient (acquire a h u t.val).inverse.coefficients k).den≤2^inverseExponent a h u t.val ∧\n    (coefficient (acquire a h u t.val).inverse.coefficients k).num.natAbs≤2^inverseExponent a h u t.val := by\n  have hr := representation_reduced_bound (pow_pos (sourceDenominator_pos _ _ _ _) _)\n    (original_inverse_representation a h u t hq k hk)\n  have hb := inverse_power_bounds a h u t\n  exact ⟨hr.1.trans hb.1,hr.2.trans hb.2⟩\n\n/-- EVERY actual inverse partial scalar accumulator has the same dyadic cap. -/\ntheorem original_inverse_prefix_bits (a h u : ℕ) (t : Fin (size a)) (n len : ℕ)\n    (hn : n+1<nodeMultiplicity a h u t.val) (hlen : len≤n+1) :\n    (dotPrefix (acquire a h u t.val).denominator.coefficients\n      (SemiprimeJetArray.inverse (acquire a h u t.val).denominator.coefficients (n+1)).coefficients n len).value.den≤\n        2^inverseExponent a h u t.val ∧\n    (dotPrefix (acquire a h u t.val).denominator.coefficients\n      (SemiprimeJetArray.inverse (acquire a h u t.val).denominator.coefficients (n+1)).coefficients n len).value.num.natAbs≤\n        2^inverseExponent a h u t.val := by\n  have hh := original_inverse_dot_heights a h u t n len hn hlen\n  have hp := inverse_power_bounds a h u t\n  have hd : 0<sourceDenominator a h u t.val := sourceDenominator_pos _ _ _ _\n  have hb : 0< inverseBase (nodeMultiplicity a h u t.val) (sourceDenominator a h u t.val)\n      (sourceNumerator a h u t.val) := by unfold inverseBase;positivity\n  exact ⟨hh.1.trans ((Nat.pow_le_pow_right hd (Nat.le_of_lt hn)).trans hp.1),\n    hh.2.trans ((Nat.pow_le_pow_right hb (Nat.le_of_lt hn)).trans hp.2)⟩\n\n/-- Fixed ORIGINAL-dimension polynomial envelope; size=2L is an acquired grid dimension. -/\ndef inverseEnvelope (a M : ℕ) : ℕ :=\n  4*M*(4*M+4*(a+1)*size a*M+4*(4*M+a+1)*size a*M+3)\n\n/-- Original schedule substitution proves the shared exponent is a FIXED polynomial\nin a,M,2L, not an unproved polynomial-cost premise. -/\ntheorem original_inverseExponent_le (a M u t : ℕ) (hM : u≤M) :\n    inverseExponent a (height M u) u t≤ inverseEnvelope a M := by\n  have hq := nodeMultiplicity_le a M u t hM\n  have hT := original_slopes_length a (height M u) u t\n  have hhu := height_mul_le M u hM\n  have hT' : (slopes a (height M u) u t).length≤4*size a*M := by\n    nlinarith [Nat.mul_le_mul_left (size a) hhu]\n  unfold inverseExponent denominatorExponent numeratorExponent inverseEnvelope\n  calc\n    _ ≤ 4*M*(4*M+(a+1)*(4*size a*M)+(4*M+a+1)*(4*size a*M)+3) := by gcongr\n    _ = _ := by ring\n\nend RiemannGaussian.SemiprimeD1HermiteDenominatorBits\n","RiemannGaussian.SemiprimeD1HermiteOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1HermiteNodes\nimport RiemannGaussian.SemiprimeD1ScaledHermite\n\n/-! # Original D.9 from acquired retained-vector local weights\nThe global identity uses the actual original tapered grid. Returned child jets\nare still an internal input whose coefficient refinement must be supplied by\nthe future recursive caller; no Hermite-answer or weight oracle is assumed.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1HermiteOriginal\nopen scoped BigOperators\nopen Polynomial SemiprimeD1WireKernelOriginal SemiprimeD1TaperedLoss\n  SemiprimeD1JetRecoveryGrid SemiprimeD1JetRecoveryWeights\n  SemiprimeD1HermiteIdentity SemiprimeD1HermiteNodes SemiprimeHermiteRecovery\n  SemiprimeJetArray SemiprimeJetRecurrence\n\n/-- Original active-grid cardinal factor, indexed without a node inverse/choice. -/\nnoncomputable def E (a h u t : ℕ) : ℚ[X] :=\n  cardinal (active a h u) (node a) (nodeMultiplicity a h u) t\n\n/-- Actual original alpha=2L as a scalar rational, not an interpolation point. -/\ndef alpha (a : ℕ) : ℚ := (2:ℚ)^(a+1)\n\n/-- All omitted inactive original factors are literal exponent0; active cardinal\nand complete original-grid product are therefore exactly the same polynomial. -/\ntheorem E_product (a h u t : ℕ) : E a h u t=\n    ∏ q∈others a t,((X-C (node a q))*C ((node a t-node a q)⁻¹))^nodeMultiplicity a h u q := by\n  unfold E cardinal\n  apply Finset.prod_subset\n  · intro q hq\n    obtain ⟨hqt,hqa⟩ := Finset.mem_erase.mp hq\n    obtain ⟨hqr,hqc,_⟩ := Finset.mem_filter.mp hqa\n    exact Finset.mem_erase.mpr ⟨hqt,Finset.mem_erase.mpr ⟨hqc,hqr⟩⟩\n  · intro q hq hnot\n    have hqt := (Finset.mem_erase.mp hq).1\n    have hqc := (Finset.mem_erase.mp (Finset.mem_erase.mp hq).2).1\n    have hqr := (Finset.mem_erase.mp (Finset.mem_erase.mp hq).2).2\n    have hm : nodeMultiplicity a h u q=0 := by\n      by_contra hm\n      apply hnot\n      exact Finset.mem_erase.mpr ⟨hqt,Finset.mem_filter.mpr ⟨hqr,hqc,Nat.pos_of_ne_zero hm⟩⟩\n    simp only [hm,pow_zero]\n\n/-- Actual original E_t(0), including signs and unit amplitudes, matches its acquired scalar. -/\ntheorem E_zero (a h u t : ℕ) : (E a h u t).eval 0=Ezero a h u t := by\n  rw [E_product,eval_prod]\n  simp only [eval_pow,eval_mul,eval_sub,eval_X,eval_C,zero_sub,Ezero,node,div_eq_mul_inv]\n\n/-- Original scaled local cardinal factor is the actual acquired affine product. -/\ntheorem E_local (a h u t : ℕ) :\n    (E a h u t).comp (SemiprimeD1ScaledHermite.affine (alpha a) (node a t))=localCardinal a h u t := by\n  rw [E_product]\n  simp only [prod_comp,pow_comp]\n  apply Finset.prod_congr rfl\n  intro q hq\n  have hqt : q≠t := (Finset.mem_erase.mp hq).1\n  have hdiff : node a t-node a q≠0 := sub_ne_zero.mpr\n    (fun he => hqt ((node_injective a) he.symm))\n  have hi : (C (node a t)-C (node a q))*C ((node a t-node a q)⁻¹)=(1:ℚ[X]) := by\n    rw [← C_sub,← C_mul,mul_inv_cancel₀ hdiff,C_1]\n  congr 1\n  simp only [mul_comp,sub_comp,X_comp,C_comp,SemiprimeD1ScaledHermite.affine]\n  have he : (C (node a t)+C (alpha a)*X-C (node a q))*C ((node a t-node a q)⁻¹)=\n      1+C ((alpha a)/(node a t-node a q))*X := by\n    rw [div_eq_mul_inv,C_mul]\n    calc\n      _ = (C (node a t)-C (node a q))*C ((node a t-node a q)⁻¹)+\n          C (alpha a)*C ((node a t-node a q)⁻¹)*X := by ring\n      _ = _ := by rw [hi]\n  simpa only [localCardinal,alpha,node,Int.cast_pow,Int.cast_ofNat] using he\n\n/-- EXACT ORIGINAL D.9 at zero from only retained scaled packets, with all actual\nnode/taper/degree conditions discharged. -/\ntheorem original_scaled_at_zero (a M u : ℕ) (hu : 0<u) (hM : u≤M) (H : ℚ[X])\n    (hH : H.natDegree≤M*(2*(2^a)-1)) :\n    H.eval 0=∑ t∈active a (height M u) u,Ezero a (height M u) u t*\n      (localQuotient\n        ((H.comp (SemiprimeD1ScaledHermite.affine (alpha a) (node a t)))%ₘ X^nodeMultiplicity a (height M u) u t)\n        (localCardinal a (height M u) u t) (nodeMultiplicity a (height M u) u t)).eval (-(node a t)/alpha a) := by\n  have he := SemiprimeD1ScaledHermite.at_zero (active a (height M u) u) (node a)\n    (nodeMultiplicity a (height M u) u) (node_injective a).injOn\n    (fun t ht => active_positive a (height M u) u t ht) (alpha a) (by unfold alpha;positivity)\n    H (hH.trans_lt (original_degree_sufficient a M u hu hM))\n  change H.eval 0=∑ t∈active a (height M u) u,(E a (height M u) u t).eval 0*\n    (localQuotient _ ((E a (height M u) u t).comp _) _).eval _ at he\n  simp_rw [E_zero,E_local] at he\n  exact he\n\n/-- Actual retained coefficient array is equal to a scalar polynomial truncation\nwhen its OWN stored coefficients match; no recovered answer is supplied. -/\ntheorem array_eq_packet (J : ℕ) (H : Array ℚ) (P : ℚ[X]) (hsize : H.size=J)\n    (hcoeff : ∀j<J,coefficient H j=P.coeff j) : asPolynomial H=P%ₘ X^J := by\n  ext j\n  rw [asPolynomial_coeff,coeff_mod_X_pow]\n  by_cases hj : j<J\n  · simp only [hj,ite_true]\n    exact hcoeff j hj\n  · simp only [hj,ite_false]\n    exact coefficient_zero (by omega)\n\n/-- ORIGINAL acquired local scalar weight arrays recover H(0), given the actual\nretained child-jet coefficient refinement. This is the linear-vector stage contract. -/\ntheorem recover_from_retained_arrays (a M u : ℕ) (hu : 0<u) (hM : u≤M) (H : ℚ[X])\n    (hH : H.natDegree≤M*(2*(2^a)-1)) (packets : ℕ→Array ℚ)\n    (hsize : ∀t∈active a (height M u) u,(packets t).size=nodeMultiplicity a (height M u) u t)\n    (hcoeff : ∀t∈active a (height M u) u,∀j<nodeMultiplicity a (height M u) u t,\n      coefficient (packets t) j=(H.comp (SemiprimeD1ScaledHermite.affine (alpha a) (node a t))).coeff j) :\n    H.eval 0=∑ t∈active a (height M u) u,∑ j∈Finset.range (nodeMultiplicity a (height M u) u t),\n      coefficient (acquire a (height M u) u t).weights j*coefficient (packets t) j := by\n  rw [original_scaled_at_zero a M u hu hM H hH]\n  apply Finset.sum_congr rfl\n  intro t ht\n  have hq := active_positive a (height M u) u t ht\n  have hp := array_eq_packet _ (packets t) _ (hsize t ht) (hcoeff t ht)\n  rw [← hp]\n  rw [← SemiprimeHermiteArrayHeight.denominator_truncate (asPolynomial (packets t))\n    (localCardinal a (height M u) u t) _ hq (localCardinal_constant a (height M u) u t)]\n  exact original_node_formula a (height M u) u t (packets t) hq\n\n/-- Finite FREE original-algebra coordinates recover by the same acquired scalar\nweights; no evaluation homomorphism on nilpotent quotients is assumed. -/\ntheorem recover_coordinates (a M u c : ℕ) (hu : 0<u) (hM : u≤M) (H : Fin c→ℚ[X])\n    (hH : ∀d,(H d).natDegree≤M*(2*(2^a)-1)) (packets : Fin c→ℕ→Array ℚ)\n    (hsize : ∀d,∀t∈active a (height M u) u,(packets d t).size=nodeMultiplicity a (height M u) u t)\n    (hcoeff : ∀d,∀t∈active a (height M u) u,∀j<nodeMultiplicity a (height M u) u t,\n      coefficient (packets d t) j=((H d).comp (SemiprimeD1ScaledHermite.affine (alpha a) (node a t))).coeff j) :\n    (fun d => (H d).eval 0)=fun d => ∑ t∈active a (height M u) u,\n      ∑ j∈Finset.range (nodeMultiplicity a (height M u) u t),\n        coefficient (acquire a (height M u) u t).weights j*coefficient (packets d t) j := by\n  funext d\n  exact recover_from_retained_arrays a M u hu hM (H d) (hH d) (packets d) (hsize d) (hcoeff d)\n\nend RiemannGaussian.SemiprimeD1HermiteOriginal\n","RiemannGaussian.SemiprimeD1IntegerRecoveryAcquisition":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1IntegerRecoveryResidue\n\n/-! # Cached original weight acquisition joined to integer recovery\nEach active original weight packet is acquired exactly once. The existing\ncardinal/inverse arithmetic and read reports are retained. These reports do NOT\ncover Ezero, slope metadata, or the scalar localWeight loops; no whole producer\nor primitive-bit clock is asserted.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1IntegerRecoveryAcquisition\nopen SemiprimeD1IntegerRecovery SemiprimeD1JetRecoveryWeights\n  SemiprimeD1TaperedLoss SemiprimeD1JetRecoveryGrid SemiprimeJetArray\n\n/-- Acquired terms with the existing packet operation reports retained. -/\nstructure TermsReport where\n  /-- Original acquired scalar weights paired with actual child words. -/\n  terms : List Term\n  /-- Cardinal and inverse scalar operations, excluding the explicitly open stages. -/\n  packetArithmetic : ℕ\n  /-- Cardinal and inverse array reads. -/\n  packetReads : ℕ\n\n/-- One actual acquisition per active node, with its returned reports preserved. -/\ndef gather (a h u : ℕ) (children : ℕ → Array (List Bool)) : List ℕ → TermsReport\n  | [] => ⟨[],0,0⟩\n  | t::ts =>\n    let w := acquire a h u t\n    let tail := gather a h u children ts\n    let localTerms := (List.range w.retained).map fun j =>\n      Term.mk (coefficient w.weights j) ((children t)[j]?.getD [])\n    ⟨localTerms++tail.terms,\n      w.denominator.arithmetic+w.inverse.arithmetic+tail.packetArithmetic,\n      w.denominator.reads+w.inverse.reads+tail.packetReads⟩\n\n/-- Cached acquisition preserves the literal original term ordering. -/\ntheorem gather_terms (a h u : ℕ) (children : ℕ → Array (List Bool)) (nodes : List ℕ) :\n    (gather a h u children nodes).terms=nodes.flatMap (fun t =>\n      let w := acquire a h u t\n      (List.range w.retained).map fun j =>\n        Term.mk (coefficient w.weights j) ((children t)[j]?.getD [])) := by\n  induction nodes with\n  | nil => rfl\n  | cons t ts ih => simp only [gather,List.flatMap_cons,ih]\n\n/-- One cached weight-acquisition result and the executed integer recovery. -/\nstructure Report where\n  /-- Actual executed integer result. -/\n  result : Result\n  /-- Existing acquired cardinal/inverse operation reports retained. -/\n  packetArithmetic : ℕ\n  /-- Existing acquired cardinal/inverse read reports retained. -/\n  packetReads : ℕ\n\n/-- Actual original-grid acquisition and integer numerator call path. -/\ndef run (a M u : ℕ) (children : ℕ → Array (List Bool)) : Report :=\n  let nodes := (List.range (SemiprimeD1WireKernelOriginal.size a)).filter (fun t =>\n    t≠SemiprimeD1WireKernelOriginal.center a ∧ 0<nodeMultiplicity a (height M u) u t)\n  let acquired := gather a (height M u) u children nodes\n  let dr := denominatorRun acquired.terms\n  let ar := accumulateRun dr.1 acquired.terms\n  ⟨⟨dr.1,ar.1,dr.2+ar.2.1,ar.2.2⟩,acquired.packetArithmetic,acquired.packetReads⟩\n\n/-- The cached producer path has precisely the already verified integer recovery result. -/\ntheorem run_result (a M u : ℕ) (children : ℕ → Array (List Bool)) :\n    (run a M u children).result=SemiprimeD1IntegerRecovery.run a M u children := by\n  simp only [run,gather_terms,SemiprimeD1IntegerRecovery.run,terms]\n\n/-- Exact number of native scalar arithmetic operations in the denominator traversal. -/\ntheorem denominatorRun_arithmetic (ts : List Term) : (denominatorRun ts).2=ts.length := by\n  induction ts with\n  | nil => rfl\n  | cons t ts ih => simp [denominatorRun,ih]\n\n/-- Exact numerator arithmetic count for the actual recursive accumulator. -/\ntheorem accumulateRun_arithmetic (D : ℕ) (ts : List Term) :\n    (accumulateRun D ts).2.1=4*ts.length+2*(ts.map fun t => t.child.length).sum := by\n  induction ts with\n  | nil => rfl\n  | cons t ts ih => simp [accumulateRun,ih];omega\n\n/-- Exact child-cell read count for the actual decoder traversals. -/\ntheorem accumulateRun_reads (D : ℕ) (ts : List Term) :\n    (accumulateRun D ts).2.2=(ts.map fun t => t.child.length).sum := by\n  induction ts with\n  | nil => rfl\n  | cons t ts ih => simp [accumulateRun,ih,Nat.add_comm]\n\n/-- Actual numerator plus denominator traversal takes five operations per term and two per decoded digit. -/\ntheorem run_arithmetic (a M u : ℕ) (children : ℕ → Array (List Bool)) :\n    (run a M u children).result.arithmetic=5*(terms a M u children).length+\n      2*((terms a M u children).map fun t => t.child.length).sum := by\n  rw [run_result]\n  simp only [SemiprimeD1IntegerRecovery.run,denominatorRun_arithmetic,accumulateRun_arithmetic]\n  omega\n\nend RiemannGaussian.SemiprimeD1IntegerRecoveryAcquisition\n","RiemannGaussian.SemiprimeD1IntegralDeformation":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1IntegralLocalKernel\nimport RiemannGaussian.SemiprimeD1OriginalDeformation\n\n/-! # Actual replay-wire deformation over the integral rational subring\nThe local witness uses actual packet/slot bytes and actual normalized kernels.\nCreator coefficients belong to the integral source ring; finite old nilpotent\ncoordinates may subsequently be handled coefficientwise. No execution clock is\nasserted by these polynomial specification identities.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1IntegralDeformation\nopen scoped BigOperators\nopen Polynomial SemiprimeD1DyadicInteger SemiprimeD1IntegralLocalKernel\nopen SemiprimeD1OriginalDeformation\n\n/-- Deformation commutes with a coefficient ring homomorphism, without domain assumptions. -/\ntheorem polynomial_map {R S : Type*} [CommRing R] [CommRing S] (f : R →+* S)\n    (M : ℕ) (A B : (Fin M→Bool)→R) (wire : Fin M→Fin M→Polynomial R) :\n    (SemiprimeD1Deformation.polynomial M A B wire).map f=\n      SemiprimeD1Deformation.polynomial M (fun x => f (A x)) (fun x => f (B x))\n        (fun i j => (wire i j).map f) := by\n  classical\n  change (Polynomial.mapRingHom f) _=_\n  rw [SemiprimeD1Deformation.polynomial,map_sum]\n  apply Finset.sum_congr rfl\n  intro bits _\n  rw [map_mul]\n  have he := SemiprimeCounterNative.evaluate_map (Polynomial.mapRingHom f) M\n    (fun rows => C (A rows)) (SemiprimeD1Deformation.rowForm M wire bits)\n  simp only [Polynomial.coe_mapRingHom,Polynomial.map_C] at he ⊢\n  rw [he]\n  congr 1\n  congr 1\n  funext row\n  simp only [SemiprimeD1Deformation.rowForm,Polynomial.map_sum,Polynomial.map_mul,\n    Polynomial.map_C]\n  congr 1\n  funext column\n  cases bits column <;> simp [SemiprimeStreamingTensor.bit]\n\n/-- Deformation commutes with the ACTUAL scalar affine substitution. -/\ntheorem polynomial_comp {R : Type*} [CommRing R] (M : ℕ)\n    (A B : (Fin M→Bool)→R) (wire : Fin M→Fin M→Polynomial R) (g : Polynomial R) :\n    (SemiprimeD1Deformation.polynomial M A B wire).comp g=\n      SemiprimeD1Deformation.polynomial M A B (fun i j => (wire i j).comp g) := by\n  classical\n  rw [SemiprimeD1Deformation.polynomial,Polynomial.sum_comp]\n  apply Finset.sum_congr rfl\n  intro bits _\n  rw [Polynomial.mul_comp,Polynomial.C_comp]\n  have he := SemiprimeCounterNative.evaluate_map (Polynomial.compRingHom g) M\n    (fun rows => C (A rows)) (SemiprimeD1Deformation.rowForm M wire bits)\n  simp only [Polynomial.coe_compRingHom,Polynomial.C_comp] at he\n  rw [he]\n  congr 1\n  congr 1\n  funext row\n  simp only [SemiprimeD1Deformation.rowForm,Polynomial.sum_comp,Polynomial.mul_comp,\n    Polynomial.C_comp]\n\n/-- Evaluation commutes with the entire tensor deformation in any commutative algebra. -/\ntheorem polynomial_evaluate {R S : Type*} [CommRing R] [CommRing S]\n    (f : R →+* S) (z : S) (M : ℕ) (A B : (Fin M→Bool)→R)\n    (wire : Fin M→Fin M→Polynomial R) :\n    (SemiprimeD1Deformation.polynomial M A B wire).eval₂ f z=\n      ∑bits : Fin M→Bool,f (B bits)*SemiprimeStreamingTensor.evaluate M (fun x => f (A x))\n        (fun i => ∑j,(wire i j).eval₂ f z*SemiprimeStreamingTensor.bit (bits j)) := by\n  classical\n  change (Polynomial.eval₂RingHom f z) _=_\n  rw [SemiprimeD1Deformation.polynomial,map_sum]\n  apply Finset.sum_congr rfl\n  intro bits _\n  rw [map_mul]\n  have he := SemiprimeCounterNative.evaluate_map (Polynomial.eval₂RingHom f z) M\n    (fun rows => C (A rows)) (SemiprimeD1Deformation.rowForm M wire bits)\n  simp only [Polynomial.coe_eval₂RingHom,Polynomial.eval₂_C] at he ⊢\n  rw [he]\n  congr 1\n  congr 1\n  funext row\n  simp only [SemiprimeD1Deformation.rowForm,Polynomial.eval₂_finsetSum,Polynomial.eval₂_mul,\n    Polynomial.eval₂_C]\n  apply Finset.sum_congr rfl\n  intro column _\n  cases bits column <;> simp [SemiprimeStreamingTensor.bit]\n\n/-- Original local wires, constructed from actual packet equality and actual slot bytes. -/\nnoncomputable def localWire (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (i j : Fin (Placements n F r a arity owner).length) : Polynomial integers :=\n  if packet n F r a arity owner i=packet n F r a arity owner j then\n    originalPolynomial a t (slot n F r a arity owner i) (slot n F r a arity owner j)\n  else 0\n\n/-- The literal local wire includes to the original actual replay wire at t+alphaZ. -/\ntheorem localWire_inclusion (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (i j : Fin (Placements n F r a arity owner).length) :\n    (localWire n F r a arity owner t i j).map integers.subtype=\n      (wire (RingHom.id ℚ) n F r a arity owner i j).comp (SemiprimeD1WireKernelPaper.affine a t.val) := by\n  unfold localWire wire\n  split_ifs\n  · simpa only [Polynomial.map_id] using original_inclusion a t\n      (slot n F r a arity owner i) (slot n F r a arity owner j)\n  · simp\n\n/-- The actual original acquired modular entry is exactly each reduced local replay wire. -/\ntheorem localWire_evaluate {S : Type*} [CommRing S] (p : ℕ)\n    (f : ZMod (2^p) →+* S) (z : S) (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (i j : Fin (Placements n F r a arity owner).length) :\n    ((localWire n F r a arity owner t i j).map (reduction p)).eval₂ f z=\n      if packet n F r a arity owner i=packet n F r a arity owner j then\n        SemiprimeD1UniversalModeData.entryValue p f z\n          (SemiprimeD1WireKernelOriginal.acquireOriginal a t\n            (slot n F r a arity owner i) (slot n F r a arity owner j))\n      else 0 := by\n  unfold localWire\n  split_ifs\n  · exact original_evaluate p a f z t _ _\n  · simp\n\n/-- Actual integral local deformation from the actual replay wires and creator values. -/\nnoncomputable def localPolynomial (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (A B : (Fin (Placements n F r a arity owner).length→Bool)→integers) : Polynomial integers :=\n  SemiprimeD1Deformation.polynomial _ A B (localWire n F r a arity owner t)\n\n/-- All local rational coefficients have the explicit integral deformation witness. -/\ntheorem localPolynomial_inclusion (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (A B : (Fin (Placements n F r a arity owner).length→Bool)→integers) :\n    (localPolynomial n F r a arity owner t A B).map integers.subtype=\n      (SemiprimeD1Deformation.polynomial _ (fun x => (A x).val) (fun x => (B x).val)\n        (wire (RingHom.id ℚ) n F r a arity owner)).comp (SemiprimeD1WireKernelPaper.affine a t.val) := by\n  rw [localPolynomial,polynomial_map,polynomial_comp]\n  congr 1\n  funext i j\n  exact localWire_inclusion n F r a arity owner t i j\n\n/-- Actual locally shifted deformation coefficients are integral by the retained witness,\nnot by a supplied coefficientwise integrality certificate. -/\ntheorem original_local_coefficient_integral (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (A B : (Fin (Placements n F r a arity owner).length→Bool)→integers) (j : ℕ) :\n    SemiprimeD1DyadicBounds.AtLeast 0\n      (((SemiprimeD1Deformation.polynomial _ (fun x => (A x).val) (fun x => (B x).val)\n        (wire (RingHom.id ℚ) n F r a arity owner)).comp\n          (SemiprimeD1WireKernelPaper.affine a t.val)).coeff j) := by\n  rw [← localPolynomial_inclusion,Polynomial.coeff_map]\n  exact ((localPolynomial n F r a arity owner t A B).coeff j).property\n\n/-- The actual modular contraction of locally reduced replay wires is the mapped\nintegral deformation, in any target algebra (including formal nilpotent jets). -/\ntheorem original_modular_contraction {S : Type*} [CommRing S] (p : ℕ)\n    (f : ZMod (2^p) →+* S) (z : S) (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (A B : (Fin (Placements n F r a arity owner).length→Bool)→integers) :\n    ((localPolynomial n F r a arity owner t A B).map (reduction p)).eval₂ f z=\n      ∑bits : Fin (Placements n F r a arity owner).length→Bool,\n        f (reduction p (B bits))*SemiprimeStreamingTensor.evaluate _ (fun x => f (reduction p (A x)))\n          (fun i => ∑j,\n            (if packet n F r a arity owner i=packet n F r a arity owner j then\n              SemiprimeD1UniversalModeData.entryValue p f z\n                (SemiprimeD1WireKernelOriginal.acquireOriginal a t\n                  (slot n F r a arity owner i) (slot n F r a arity owner j))\n             else 0)*SemiprimeStreamingTensor.bit (bits j)) := by\n  rw [localPolynomial,polynomial_map,polynomial_evaluate]\n  apply Finset.sum_congr rfl\n  intro bits _\n  congr 1\n  congr 1\n  funext i\n  apply Finset.sum_congr rfl\n  intro j _\n  rw [localWire_evaluate]\n\nend RiemannGaussian.SemiprimeD1IntegralDeformation\n","RiemannGaussian.SemiprimeD1InvolutionRegroup":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport Mathlib\n\n/-! # Exact reflected-grid cancellation in tapered Hermite recovery\n\nReflection pairs points of valuation i with their higher-valuation differences.\nLower levels cancel pointwise. This finite algebraic lemma is independent of\nthe original residue-grid count, which is supplied at the later D.10 join.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1InvolutionRegroup\nopen scoped BigOperators\n\n/-- Reindexing by a genuine finite reflected-grid involution preserves sums. -/\ntheorem sum_reflect {A : Type*} (S : Finset A) (reflect : A→A)\n    (hmem : ∀ x∈S,reflect x∈S) (hinv : ∀ x∈S,reflect (reflect x)=x)\n    (f : A→ℤ) : (∑ x∈S,f (reflect x))=∑ x∈S,f x := by\n  classical\n  apply Finset.sum_bij (fun x _ => reflect x)\n  · exact hmem\n  · intro x hx y hy he\n    exact (hinv x hx).symm.trans ((congrArg reflect he).trans (hinv y hy))\n  · intro y hy\n    exact ⟨reflect y,hmem y hy,hinv y hy⟩\n  · intros;rfl\n\n/-- The exact original raw valuation sum reduces to its high-level differences.\nOnly the actual valuation laws and reflection involution are required; no loss\nbound or distribution of valuation levels is assumed. -/\ntheorem regroup {A : Type*} (S : Finset A) (reflect : A→A) (v : A→ℕ)\n    (q : ℕ→ℤ) (i : ℕ)\n    (hmem : ∀ x∈S,reflect x∈S) (hinv : ∀ x∈S,reflect (reflect x)=x)\n    (hlow : ∀ x∈S,v x < i→v (reflect x)=v x)\n    (hhigh : ∀ x∈S,i < v x→v (reflect x)=i) :\n    (∑ x∈S,q (v x)*((v x:ℤ)-(v (reflect x):ℤ)))=\n      ∑ x∈S,if i < v x then (q (v x)-q i)*((v x:ℤ)-(i:ℤ)) else 0 := by\n  classical\n  let positive : A→ℤ := fun x => if i < v x then q (v x)*((v x:ℤ)-(i:ℤ)) else 0\n  let constant : A→ℤ := fun x => if i < v x then q i*((v x:ℤ)-(i:ℤ)) else 0\n  have hlocal (x : A) (hx : x∈S) :\n      q (v x)*((v x:ℤ)-(v (reflect x):ℤ))=positive x-constant (reflect x) := by\n    rcases lt_trichotomy (v x) i with hlo|heq|hhi\n    · have he := hlow x hx hlo\n      simp only [positive,constant,he,show ¬i < v x by omega,ite_false,sub_self,mul_zero]\n    · have hlower : i≤v (reflect x) := by\n        by_contra hbad\n        have he := hlow (reflect x) (hmem x hx) (by omega)\n        rw [hinv x hx,heq] at he\n        omega\n      by_cases hb : i < v (reflect x)\n      · simp only [positive,constant,heq,lt_self_iff_false,ite_false,hb,ite_true]\n        ring\n      · have he : v (reflect x)=i := by omega\n        simp [positive,constant,heq,he]\n    · have he := hhigh x hx hhi\n      simp only [positive,constant,he,hhi,ite_true,lt_self_iff_false,ite_false,sub_zero]\n  calc\n    _ = ∑ x∈S,(positive x-constant (reflect x)) := Finset.sum_congr rfl hlocal\n    _ = (∑ x∈S,positive x)-(∑ x∈S,constant (reflect x)) := by rw [Finset.sum_sub_distrib]\n    _ = (∑ x∈S,positive x)-(∑ x∈S,constant x) := by rw [sum_reflect S reflect hmem hinv constant]\n    _ = ∑ x∈S,(positive x-constant x) := by rw [Finset.sum_sub_distrib]\n    _ = _ := by\n      apply Finset.sum_congr rfl\n      intro x _\n      dsimp only [positive,constant]\n      split_ifs <;> ring\n\nend RiemannGaussian.SemiprimeD1InvolutionRegroup\n","RiemannGaussian.SemiprimeD1JetWordKernelBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1JetWordKernelBits\n\n/-! # Retained cost of the actual original-word kernel consumer\nEvery bound below concerns the new executed word program, including its own\nfactor, denominator and dyadic-quotient acquisition. Literal agreement with the\nold integer program is not used to transfer a clock. Native small dimensions,\ndigit/control primitives and whole memory simulation remain separate.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 600000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1JetWordKernelBounds\nopen SemiprimeBitArithmetic SemiprimeBitIndexClipping SemiprimeD1JetAxes\nopen SemiprimeD1JetWordKernelBits SemiprimeD1JetPolynomialBits\nopen SemiprimeD1JetPolynomialBitsBounds SemiprimeD1JetAffineCoefficientBounds\nopen SemiprimeD1JetAffineCoefficient (JetRun)\nopen SemiprimeD1RecoveryIntegerBits (positive)\n\n/-- Physical sign/reduction budget at an actual acquired source width. -/\ndef signedBudget (p W : ℕ) : ℕ := 12*p*(p+W+2)+10*p+20\n\n/-- Physical source reduction and copied dense constant allocation. -/\ndef sourceBudget (ctx : Context) (W : ℕ) : ℕ :=\n  12*ctx.precision*(ctx.precision+W+2)+13*ctx.precision+3*ctx.rank+27\n\n/-- Actual byte-source acquisition is monotone in its literal input width. -/\ntheorem source_clock (ctx : Context) (word : SignedWord) (W : ℕ)\n    (hw : word.magnitude.length≤W) :\n    (SemiprimeD1JetWordSourceBits.constant ctx word).clock ≤ sourceBudget ctx W := by\n  apply (SemiprimeD1JetWordSourceBits.constant_clock ctx word).trans\n  unfold sourceBudget\n  gcongr\n\n/-- Both byte sources and the physical multiply and addition are retained. -/\ndef linearBudget (ctx : Context) (W : ℕ) : ℕ :=\n  2*sourceBudget ctx W+\n    SemiprimeD1JetRingBounds.mulBudget ctx.axes.length ctx.rank W ctx.precision+\n    addBudget ctx W+5\n\n/-- An acquired affine factor has intrinsic target rank and precision. -/\ntheorem linear_good (ctx : Context) (z : List (List Bool))\n    (f : SemiprimeD1NormalizedLinearBits.Run) : Good ctx (linear ctx z f).words :=\n  add_good _ _ _\n\n/-- Every actually supplied factor byte is paid, without an integer source. -/\ntheorem linear_clock (ctx : Context) (z : List (List Bool))\n    (f : SemiprimeD1NormalizedLinearBits.Run) (W : ℕ)\n    (hp : ctx.precision≤W) (hz : z.length≤ctx.rank) (hw : ∀w∈z,w.length≤W)\n    (hc : f.constant.magnitude.length≤W) (hs : f.slope.length≤W) :\n    (linear ctx z f).clock≤linearBudget ctx W := by\n  have hcc:=source_clock ctx f.constant W hc\n  have hsc:=source_clock ctx (positive f.slope) W hs\n  have hcg:=SemiprimeD1JetWordSourceBits.constant_good ctx f.constant\n  have hsg:=SemiprimeD1JetWordSourceBits.constant_good ctx (positive f.slope)\n  have hm:=SemiprimeD1JetRingBounds.mul_clock ctx\n    (SemiprimeD1JetWordSourceBits.constant ctx (positive f.slope)).words z W hsg.1.le hz\n    (fun w h=>(hsg.2 w h).trans hp) hw\n  have hmg:=mul_good ctx (SemiprimeD1JetWordSourceBits.constant ctx (positive f.slope)).words z\n  have ha:=SemiprimeD1JetRingBounds.add_clock ctx\n    (SemiprimeD1JetWordSourceBits.constant ctx f.constant).words\n    (SemiprimeD1JetRingBits.mul ctx\n      (SemiprimeD1JetWordSourceBits.constant ctx (positive f.slope)).words z).words W\n    hcg.1.le hmg.1.le (fun w h=>(hcg.2 w h).trans hp) (fun w h=>(hmg.2 w h).trans hp)\n  change (SemiprimeD1JetWordSourceBits.constant ctx f.constant).clock+\n    (SemiprimeD1JetWordSourceBits.constant ctx (positive f.slope)).clock+\n    (SemiprimeD1JetRingBits.mul ctx\n      (SemiprimeD1JetWordSourceBits.constant ctx (positive f.slope)).words z).clock+\n    (SemiprimeD1JetRingBits.add ctx (SemiprimeD1JetWordSourceBits.constant ctx f.constant).words\n      (SemiprimeD1JetRingBits.mul ctx\n        (SemiprimeD1JetWordSourceBits.constant ctx (positive f.slope)).words z).words).clock+5≤_\n  unfold linearBudget addBudget\n  omega\n\n/-- Complete actual entry report after its own word factory, counted separately. -/\ndef entryBudget (ctx : Context) (W F : ℕ) : ℕ :=\n  signedBudget ctx.precision W+400*(ctx.precision+1)^3+\n    (3*ctx.precision+3*ctx.rank+4)+sourceBudget ctx W+\n    F*(linearBudget ctx W+\n      SemiprimeD1JetRingBounds.mulBudget ctx.axes.length ctx.rank W ctx.precision+3)+\n    (9*ctx.precision+3*ctx.rank+8)+\n    2*SemiprimeD1JetRingBounds.mulBudget ctx.axes.length ctx.rank W ctx.precision+20\n\n/-- The actual entry's final physical multiplication gives its full shape/width. -/\ntheorem entry_good (ctx : Context) (z : JetRun) (e : SemiprimeD1KernelEntryBits.Run) :\n    Good ctx (entry ctx z e).words := mul_good _ _ _\n\n/-- New denominator reduction, inverse, power-factor bytes and every cached\nfactor producer are retained. No old report occurs on either side. -/\ntheorem entry_clock (ctx : Context) (z : JetRun) (e : SemiprimeD1KernelEntryBits.Run)\n    (W : ℕ) (hp : ctx.precision≤W) (hz : z.words.length≤ctx.rank)\n    (hw : ∀w∈z.words,w.length≤W) (hd : e.denominator.magnitude.length≤W)\n    (he : e.powerFactor.length≤W)\n    (hf : ∀f∈e.factors,f.constant.magnitude.length≤W ∧ f.slope.length≤W) :\n    (entry ctx z e).clock≤z.clock+entryBudget ctx W e.factors.length := by\n  have hden:=(SemiprimeD1RecoveryStripBits.signed_clock ctx.precision e.denominator).trans\n    (show 12*ctx.precision*(ctx.precision+e.denominator.magnitude.length+2)+\n      10*ctx.precision+20 ≤ signedBudget ctx.precision W by unfold signedBudget;gcongr)\n  let denominator:=SemiprimeD1RecoveryStripBits.signed ctx.precision e.denominator\n  let inverseBits:=(SemiprimeD1OddInverseBits.inverse ctx.precision denominator.bits).bits\n  have hi:=SemiprimeD1OddInverseBounds.inverse_clock ctx.precision denominator.bits\n  have hig:=SemiprimeD1OddInverseBits.inverse_good ctx.precision denominator.bits\n  have hs:=scalar_clock ctx inverseBits\n  have hsg : Good ctx (scalar ctx inverseBits).words:=\n    ⟨scalar_shape _ _,scalar_bounded _ _ _ hig.1⟩\n  have ht:=source_clock ctx (positive e.powerFactor) W he\n  have htg:=SemiprimeD1JetWordSourceBits.constant_good ctx (positive e.powerFactor)\n  have hprod:=product_clock ctx (e.factors.map (linear ctx z.words)) W hp (by\n    intro r hr\n    obtain ⟨f,_,rfl⟩:=List.mem_map.mp hr\n    exact ⟨(linear_good ctx z.words f).1.le,\n      fun w h=>((linear_good ctx z.words f).2 w h).trans hp⟩)\n  have hsum:=SemiprimeD1JetKernelBitsBounds.report_sum_le e.factors (linear ctx z.words)\n    (linearBudget ctx W) (fun f h=>linear_clock ctx z.words f W hp hz hw (hf f h).1 (hf f h).2)\n  simp only [List.length_map] at hprod\n  have hpg:=product_good ctx (e.factors.map (linear ctx z.words))\n  have hl:=SemiprimeD1JetRingBounds.mul_clock ctx (scalar ctx inverseBits).words\n    (SemiprimeD1JetWordSourceBits.constant ctx (positive e.powerFactor)).words W hsg.1.le htg.1.le\n    (fun w h=>(hsg.2 w h).trans hp) (fun w h=>(htg.2 w h).trans hp)\n  have hlg:=mul_good ctx (scalar ctx inverseBits).words\n    (SemiprimeD1JetWordSourceBits.constant ctx (positive e.powerFactor)).words\n  have ho:=SemiprimeD1JetRingBounds.mul_clock ctx\n    (SemiprimeD1JetRingBits.mul ctx (scalar ctx inverseBits).words\n      (SemiprimeD1JetWordSourceBits.constant ctx (positive e.powerFactor)).words).words\n    (product ctx (e.factors.map (linear ctx z.words))).words W hlg.1.le hpg.1.le\n    (fun w h=>(hlg.2 w h).trans hp) (fun w h=>(hpg.2 w h).trans hp)\n  change z.clock+denominator.clock+\n    (SemiprimeD1OddInverseBits.inverse ctx.precision denominator.bits).clock+\n    (scalar ctx inverseBits).clock+\n    (SemiprimeD1JetWordSourceBits.constant ctx (positive e.powerFactor)).clock+\n    (product ctx (e.factors.map (linear ctx z.words))).clock+\n    (SemiprimeD1JetRingBits.mul ctx (scalar ctx inverseBits).words\n      (SemiprimeD1JetWordSourceBits.constant ctx (positive e.powerFactor)).words).clock+\n    (SemiprimeD1JetRingBits.mul ctx\n      (SemiprimeD1JetRingBits.mul ctx (scalar ctx inverseBits).words\n        (SemiprimeD1JetWordSourceBits.constant ctx (positive e.powerFactor)).words).words\n      (product ctx (e.factors.map (linear ctx z.words))).words).clock+20≤_\n  unfold entryBudget\n  nlinarith\n\n/-- Actual factor-count monotonicity, with no change to source multiplicity. -/\ntheorem entryBudget_mono (ctx : Context) (W F G : ℕ) (h : F≤G) :\n    entryBudget ctx W F≤entryBudget ctx W G := by\n  unfold entryBudget\n  gcongr\n\n/-- A single original-dimension width dominates all acquired factor, denominator\nand quotient words, even before precision reduction. -/\ndef originalWidth (a N : ℕ) : ℕ := 2*N*(2*a+5)+a+5\n\n/-- Original input only: all physical source widths are internally derived. -/\ntheorem acquire_widths (a : ℕ) (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (x y : Fin (2^a)) :\n    (SemiprimeD1KernelEntryBits.acquireOriginal a t x y).denominator.magnitude.length≤\n        originalWidth a (SemiprimeD1WireKernelOriginal.size a) ∧\n    (SemiprimeD1KernelEntryBits.acquireOriginal a t x y).powerFactor.length≤\n        originalWidth a (SemiprimeD1WireKernelOriginal.size a) ∧\n    ∀f∈(SemiprimeD1KernelEntryBits.acquireOriginal a t x y).factors,\n      f.constant.magnitude.length≤originalWidth a (SemiprimeD1WireKernelOriginal.size a) ∧\n      f.slope.length≤originalWidth a (SemiprimeD1WireKernelOriginal.size a) := by\n  have hd:=SemiprimeD1KernelDenominatorBits.run_width a\n  have he:=SemiprimeD1KernelEntryBounds.powerFactor_width a t x y\n  have hf:=(SemiprimeD1KernelEntryBounds.acquire_factor_bounds a t x y).2\n  constructor\n  · change (SemiprimeD1KernelDenominatorBits.run a).word.magnitude.length≤_\n    unfold originalWidth\n    nlinarith\n  constructor\n  · unfold originalWidth SemiprimeD1KernelEntryBounds.contentWidth at *\n    omega\n  intro f h\n  have hb:=hf f h\n  unfold originalWidth\n  constructor <;> nlinarith [Nat.zero_le (2*SemiprimeD1WireKernelOriginal.size a*(2*a+5))]\n\n/-- Complete actual original-word factory and consumer budget. -/\ndef budget (ctx : Context) (W a : ℕ) : ℕ :=\n  SemiprimeD1KernelEntryBounds.budget a (SemiprimeD1WireKernelOriginal.size a)+\n    entryBudget ctx (W+originalWidth a (SemiprimeD1WireKernelOriginal.size a))\n      (SemiprimeD1WireKernelOriginal.size a)+3\n\n/-- Original indices alone acquire all source data, with a fixed polynomial in\nthe actual grid size and physical jet dimensions; the source jet is paid once. -/\ntheorem acquireOriginal_clock (ctx : Context) (z : JetRun) (a : ℕ)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (x y : Fin (2^a)) (W : ℕ)\n    (hp : ctx.precision≤W) (hz : z.words.length≤ctx.rank) (hw : ∀w∈z.words,w.length≤W) :\n    (acquireOriginal ctx z a t x y).clock≤z.clock+budget ctx W a := by\n  let V:=W+originalWidth a (SemiprimeD1WireKernelOriginal.size a)\n  have hWV:W≤V:=Nat.le_add_right _ _\n  have hOV:originalWidth a (SemiprimeD1WireKernelOriginal.size a)≤V:=Nat.le_add_left _ _\n  have hs:=acquire_widths a t x y\n  have h:=entry_clock ctx z (SemiprimeD1KernelEntryBits.acquireOriginal a t x y) V\n    (hp.trans hWV) hz (fun w h=>(hw w h).trans hWV) (hs.1.trans hOV) (hs.2.1.trans hOV)\n    (fun f hf=>⟨((hs.2.2 f hf).1).trans hOV,((hs.2.2 f hf).2).trans hOV⟩)\n  have hF:=(SemiprimeD1KernelEntryBounds.acquire_factor_bounds a t x y).1\n  have hm:=entryBudget_mono ctx V _ (SemiprimeD1WireKernelOriginal.size a) hF\n  have hc:=SemiprimeD1KernelEntryBounds.acquire_clock a t x y\n  change (SemiprimeD1KernelEntryBits.acquireOriginal a t x y).clock+\n    (entry ctx z (SemiprimeD1KernelEntryBits.acquireOriginal a t x y)).clock+3≤_\n  unfold budget\n  dsimp only [V] at h hm\n  omega\n\nend RiemannGaussian.SemiprimeD1JetWordKernelBounds\n","RiemannGaussian.SemiprimeD1JetWordPacketEntryBits":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PacketEntryBits\nimport RiemannGaussian.SemiprimeD1JetWordModeBounds\nimport RiemannGaussian.SemiprimeD1PacketModeMask\nimport RiemannGaussian.SemiprimeD1PacketEntryInputs\nimport RiemannGaussian.SemiprimeD1JetKernelBits\nimport RiemannGaussian.SemiprimeD1JetModeBits\nimport RiemannGaussian.SemiprimeD1TensorTables\n\n/-! # Word-supplied concrete packet row recipes and entries\nThe actual child bucket supplies every row/column bit and orientation slot.\nGlobal beta is restricted to this packet's target modes before coefficient\nextraction. Source factors use the original beta. No old tensor evaluator,\nmode-coefficient callback, or semantic ring value appears on the runtime path.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2400000\nnamespace RiemannGaussian.SemiprimeD1JetWordPacketEntryBits\nopen SemiprimeD1JetAxes SemiprimeD1PacketEntryInputs\nopen SemiprimeD1JetAffineCoefficient (JetRun Row)\n\nopen SemiprimeD1PacketEntryBits (borrow multiply sameBit sourceProduct)\n\n/-- Literal sign application; negative uses the actual acquired modular minus one. -/\ndef signed (ctx : Context) (negative : Bool) (value : JetRun) : JetRun :=\n  if negative then multiply ctx (SemiprimeD1JetWordSourceBits.constant ctx ⟨true,[true]⟩) value\n  else\n    let out := copyVector value.words\n    ⟨out.1,value.clock+out.2+3⟩\n\n/-- One actual local-column contribution to a real row. -/\ndef baseTerm (ctx : Context) (z : JetRun) (a : ℕ)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row column : Wire a) : JetRun :=\n  if column.bit then SemiprimeD1JetWordKernelBits.acquireOriginal ctx (borrow z) a t row.slot column.slot\n  else SemiprimeD1JetAffineCoefficient.zero ctx\n\n/-- Actual local constant term, including `1-base` for a false row bit. -/\ndef rowBase (ctx : Context) (z : JetRun) (a : ℕ)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a) (columns : List (Wire a)) : JetRun :=\n  let base := SemiprimeD1JetAffineCoefficient.sumRuns ctx (columns.map (baseTerm ctx z a t row))\n  if row.bit then base else\n    let one := SemiprimeD1JetAffineCoefficient.one ctx\n    let negative := signed ctx true base\n    let out := SemiprimeD1JetRingBits.add ctx one.words negative.words\n    ⟨out.words,one.clock+negative.clock+out.clock+5⟩\n\n/-- Actual signed crossing mode. A physical same-bit test also guards the original\nodd-unit mode supplier, rather than assuming that bit relation as advice. -/\ndef coefficient (ctx : Context) (z : JetRun) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a)\n    (item : SemiprimeD1PacketModeMask.Item) : JetRun :=\n  let tile : Fin (2^a) := ⟨item.tile%2^a,Nat.mod_lt _ (by positivity)⟩\n  let test := sameBit row.slot.val tile.val i.val\n  if item.inPacket && item.targetHere && !item.sourceHere && test.value then\n    let mode := SemiprimeD1JetWordModeBits.acquireOriginal ctx (borrow z) a i.val item.mode.order t row.slot tile\n    let out := signed ctx (!row.bit) mode\n    ⟨out.words,out.clock+test.work+item.tile+row.slot.val+2^a+10⟩\n  else\n    let out := SemiprimeD1JetAffineCoefficient.zero ctx\n    ⟨out.words,out.clock+test.work+item.tile+row.slot.val+2^a+10⟩\n\n/-- Actual coefficient vector acquisition in the unchanged global catalogue order. -/\ndef coefficients (ctx : Context) (z : JetRun) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a) :\n    List SemiprimeD1PacketModeMask.Item→SemiprimeMaterializedWords.Run (List (List (List Bool)))\n  | [] => ⟨[],1⟩\n  | item::items =>\n    let value := coefficient ctx z a i t row item\n    let tail := coefficients ctx z a i t row items\n    ⟨value.words::tail.value,value.clock+tail.work+4⟩\n\n/-- Concrete row recipe and its retained base/mode data acquisition. -/\ndef recipe (ctx : Context) (z : JetRun) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a) (columns : List (Wire a))\n    (items : List SemiprimeD1PacketModeMask.Item) : SemiprimeMaterializedWords.Run Row :=\n  let base := rowBase ctx z a t row columns\n  let modes := coefficients ctx z a i t row items\n  ⟨⟨base.words,modes.value⟩,base.clock+modes.work+5⟩\n\n/-- Acquire every actual real-row recipe once and preserve the original row order. -/\ndef recipes (ctx : Context) (z : JetRun) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (columns : List (Wire a))\n    (items : List SemiprimeD1PacketModeMask.Item) : List (Wire a)→SemiprimeMaterializedWords.Run (List Row)\n  | [] => ⟨[],1⟩\n  | row::rows =>\n    let value := recipe ctx z a i t row columns items\n    let tail := recipes ctx z a i t columns items rows\n    ⟨value.value::tail.value,value.work+tail.work+4⟩\n\n/-- Actual single-entry execution. Header/source producers are retained by the\nouter table acquisition once; this function retains all per-assignment work. -/\ndef evaluate {V : ℕ} (ctx : Context) (z : JetRun) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (items : SemiprimeD1PacketModeMask.Cache)\n    (endpoints : List (SemiprimeD1ChildGraph.Endpoint V)) (beta : List ℕ) (bits : List Bool) : JetRun :=\n  let input := gather a endpoints bits\n  let restricted := SemiprimeD1PacketModeMask.restrict items beta\n  let rows := recipes ctx (borrow z) a i t input.columns items.items input.rows\n  let target := SemiprimeD1JetAffineCoefficient.evaluate ctx items.items.length rows.value restricted.value\n  let source := sourceProduct ctx a i input.columns beta items.items 0\n  let out := multiply ctx target source\n  ⟨out.words,input.clock+restricted.work+rows.work+out.clock+beta.length+10⟩\n\n/-- Physical signed application has the original literal result bytes. -/\ntheorem signed_words (ctx : Context) (negative : Bool) (value : JetRun) :\n    (signed ctx negative value).words=(SemiprimeD1PacketEntryBits.signed ctx negative value).words := by\n  dsimp only [signed,SemiprimeD1PacketEntryBits.signed]\n  split\n  · dsimp only [multiply]\n    rw [SemiprimeD1JetWordSourceBits.constant_words_eq_integerVector ctx ⟨true,[true]⟩ (-1) rfl]\n  · rfl\n\n/-- Signed output depends only on the literal input vector. -/\ntheorem signed_words_congr (ctx : Context) (negative : Bool) (left right : JetRun)\n    (h:left.words=right.words) : (signed ctx negative left).words=(signed ctx negative right).words := by\n  dsimp only [signed,multiply]\n  split <;> rw [h]\n\n/-- Actual sum payloads depend only on the original ordered payload list. -/\ntheorem sum_words_congr (ctx : Context) (xs ys : List JetRun)\n    (h:xs.map (fun r=>r.words)=ys.map (fun r=>r.words)) :\n    (SemiprimeD1JetAffineCoefficient.sumRuns ctx xs).words=\n      (SemiprimeD1JetAffineCoefficient.sumRuns ctx ys).words := by\n  induction xs generalizing ys with\n  | nil => cases ys with\n    | nil => rfl\n    | cons y ys => cases h\n  | cons x xs ih => cases ys with\n    | nil => cases h\n    | cons y ys =>\n      have he:=List.cons.inj h\n      change (SemiprimeD1JetRingBits.add ctx x.words\n        (SemiprimeD1JetAffineCoefficient.sumRuns ctx xs).words).words=_\n      have hx:x.words=y.words:=he.1\n      rw [hx,ih ys he.2]\n      rfl\n\n/-- Actual base contribution uses the acquired original word entry. -/\ntheorem baseTerm_words (ctx : Context) (hpos:ctx.Positive) (z : JetRun) (a : ℕ)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row column : Wire a) :\n    (baseTerm ctx z a t row column).words=\n      (SemiprimeD1PacketEntryBits.baseTerm ctx z a t row column).words := by\n  dsimp only [baseTerm,SemiprimeD1PacketEntryBits.baseTerm]\n  split\n  · exact SemiprimeD1JetWordKernelBits.acquireOriginal_words ctx hpos _ _ _ _ _\n  · rfl\n\n/-- Real-row base bytes retain all original column order and Boolean conventions. -/\ntheorem rowBase_words (ctx : Context) (hpos:ctx.Positive) (z : JetRun) (a : ℕ)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a) (columns : List (Wire a)) :\n    (rowBase ctx z a t row columns).words=\n      (SemiprimeD1PacketEntryBits.rowBase ctx z a t row columns).words := by\n  have hb:(SemiprimeD1JetAffineCoefficient.sumRuns ctx\n      (columns.map (baseTerm ctx z a t row))).words=\n      (SemiprimeD1JetAffineCoefficient.sumRuns ctx\n        (columns.map (SemiprimeD1PacketEntryBits.baseTerm ctx z a t row))).words:=by\n    apply sum_words_congr\n    simp only [List.map_map]\n    apply List.map_congr_left\n    intro column _\n    exact baseTerm_words ctx hpos z a t row column\n  dsimp only [rowBase,SemiprimeD1PacketEntryBits.rowBase]\n  split\n  · exact hb\n  · rw [signed_words,show\n      (SemiprimeD1PacketEntryBits.signed ctx true\n        (SemiprimeD1JetAffineCoefficient.sumRuns ctx (columns.map (baseTerm ctx z a t row)))).words=\n      (SemiprimeD1PacketEntryBits.signed ctx true\n        (SemiprimeD1JetAffineCoefficient.sumRuns ctx\n          (columns.map (SemiprimeD1PacketEntryBits.baseTerm ctx z a t row)))).words from by\n        dsimp only [SemiprimeD1PacketEntryBits.signed,multiply]\n        simp only [ite_true]\n        rw [hb]]\n\n/-- Original gated coefficient bytes now come from the actual word-only mode. -/\ntheorem coefficient_words (ctx : Context) (hpos:ctx.Positive) (z : JetRun) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a)\n    (item : SemiprimeD1PacketModeMask.Item) :\n    (coefficient ctx z a i t row item).words=\n      (SemiprimeD1PacketEntryBits.coefficient ctx z a i t row item).words := by\n  dsimp only [coefficient,SemiprimeD1PacketEntryBits.coefficient]\n  split\n  · rw [signed_words]\n    dsimp only [SemiprimeD1PacketEntryBits.signed,multiply]\n    split <;> rw [SemiprimeD1JetWordModeBits.acquireOriginal_words ctx hpos]\n  · rfl\n\n/-- Acquired coefficient arrays preserve every original catalogue slot. -/\ntheorem coefficients_value (ctx : Context) (hpos:ctx.Positive) (z : JetRun) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a)\n    (items : List SemiprimeD1PacketModeMask.Item) :\n    (coefficients ctx z a i t row items).value=\n      (SemiprimeD1PacketEntryBits.coefficients ctx z a i t row items).value := by\n  induction items with\n  | nil => rfl\n  | cons item items ih =>\n    change (coefficient ctx z a i t row item).words::(coefficients ctx z a i t row items).value=_\n    rw [coefficient_words ctx hpos,ih]\n    rfl\n\n/-- Each actual affine recipe is exactly the original requested-coefficient input. -/\ntheorem recipe_value (ctx : Context) (hpos:ctx.Positive) (z : JetRun) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a) (columns : List (Wire a))\n    (items : List SemiprimeD1PacketModeMask.Item) :\n    (recipe ctx z a i t row columns items).value=\n      (SemiprimeD1PacketEntryBits.recipe ctx z a i t row columns items).value := by\n  dsimp only [recipe,SemiprimeD1PacketEntryBits.recipe]\n  rw [rowBase_words ctx hpos,coefficients_value ctx hpos]\n\n/-- Real-row lists preserve original row order, multiplicity and exact recipe data. -/\ntheorem recipes_value (ctx : Context) (hpos:ctx.Positive) (z : JetRun) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (columns : List (Wire a))\n    (items : List SemiprimeD1PacketModeMask.Item) (rows : List (Wire a)) :\n    (recipes ctx z a i t columns items rows).value=\n      (SemiprimeD1PacketEntryBits.recipes ctx z a i t columns items rows).value := by\n  induction rows with\n  | nil => rfl\n  | cons row rows ih =>\n    change (recipe ctx z a i t row columns items).value::(recipes ctx z a i t columns items rows).value=_\n    rw [recipe_value ctx hpos,ih]\n    rfl\n\n/-- The whole actual packet entry has original bytes, with its own retained report. -/\ntheorem evaluate_words {V : ℕ} (ctx : Context) (hpos:ctx.Positive) (z : JetRun) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (items : SemiprimeD1PacketModeMask.Cache)\n    (endpoints : List (SemiprimeD1ChildGraph.Endpoint V)) (beta : List ℕ) (bits : List Bool) :\n    (evaluate ctx z a i t items endpoints beta bits).words=\n      (SemiprimeD1PacketEntryBits.evaluate ctx z a i t items endpoints beta bits).words := by\n  dsimp only [evaluate,SemiprimeD1PacketEntryBits.evaluate,multiply]\n  rw [recipes_value ctx hpos]\n\n/-- Completed actual entry shape/width follows the final physical product. -/\ntheorem evaluate_good {V : ℕ} (ctx : Context) (z : JetRun) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (items : SemiprimeD1PacketModeMask.Cache)\n    (endpoints : List (SemiprimeD1ChildGraph.Endpoint V)) (beta : List ℕ) (bits : List Bool) :\n    SemiprimeD1JetAffineCoefficientBounds.Good ctx (evaluate ctx z a i t items endpoints beta bits).words :=\n  SemiprimeD1JetAffineCoefficientBounds.mul_good _ _ _\n/-- Every completed literal packet output is canonical in its current context. -/\ntheorem evaluate_canonical {V : ℕ} (ctx : Context) (z : JetRun) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (items : SemiprimeD1PacketModeMask.Cache)\n    (endpoints : List (SemiprimeD1ChildGraph.Endpoint V)) (beta : List ℕ) (bits : List Bool) :\n    SemiprimeD1TensorTables.GoodWords ctx (evaluate ctx z a i t items endpoints beta bits).words := by\n  refine ⟨SemiprimeD1JetRingBits.mul_shape _ _ _,?_⟩\n  intro w hw\n  exact ⟨SemiprimeD1JetRingBits.mul_compact _ _ _ w hw,\n    SemiprimeD1JetRingBits.mul_bounded _ _ _ w hw⟩\nend RiemannGaussian.SemiprimeD1JetWordPacketEntryBits\n","RiemannGaussian.SemiprimeD1ModeRoutingWireColours":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1ModeRoutingColours\n\n/-! # One physical source and one physical target per packet tile\nThe statements refer to actual inverse-read colour bytes and actual slot bits.\nOriginal acquired-packet wrappers discharge the class hypotheses separately.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2800000\nnamespace RiemannGaussian.SemiprimeD1ModeRoutingWireColours\nopen SemiprimeD1OrientationBits SemiprimeD1OrientationInverse SemiprimeD1OrientationComplete\nopen SemiprimeD1ModeRoutingBits SemiprimeD1ModeRoutingColours\n\n/-- A non-source row in a two-colour class necessarily has the tile bit and target colour. -/\ntheorem crossing_choice (low high : List Bool) (slot tile : Bool)\n    (hc : (if slot then high else low)≠(if tile then low else high)) :\n    slot=tile ∧ (if slot then high else low)=(if tile then high else low) := by\n  cases slot <;> cases tile <;> simp_all\n\n/-- Every inverse-realized column with this tile bit has the acquired source colour. -/\ntheorem column_source (a : ℕ) (lows highs : List (List Bool)) (high : List Bool)\n    (hc : Canonical lows highs) (hl : lows.length=a) (hh : highs.length=a)\n    (i : Fin a) (tile : Fin (2^(i.val+1))) (slots : List Bool) (hs : slots.length=a)\n    (hb : (slots[i.val]?).getD false=(SemiprimeD1ModeRoutingBits.acquire (packetKey lows highs high) a i tile).bit) :\n    ((recover (packetKey lows highs high) slots).right[i.val]?).getD []=\n      (SemiprimeD1ModeRoutingBits.acquire (packetKey lows highs high) a i tile).source := by\n  have hr := (recover_colours lows highs high slots hc (hs.trans hl.symm) i.val (by omega)).2\n  have hf := acquire_fields a lows highs high hl hh i tile\n  have hsource := (acquire_colours (packetKey lows highs high) a i tile).1\n  rw [hf.1,hf.2] at hsource\n  rw [hr,hb,hsource]\n\n/-- Every crossing inverse-realized row has the unique acquired target colour and\nexactly the same chosen slot bit as the column tile. -/\ntheorem row_target (a : ℕ) (lows highs : List (List Bool)) (high : List Bool)\n    (hc : Canonical lows highs) (hl : lows.length=a) (hh : highs.length=a)\n    (i : Fin a) (tile : Fin (2^(i.val+1))) (slots : List Bool) (hs : slots.length=a)\n    (hcross : ((recover (packetKey lows highs high) slots).left[i.val]?).getD []≠\n      (SemiprimeD1ModeRoutingBits.acquire (packetKey lows highs high) a i tile).source) :\n    (slots[i.val]?).getD false=(SemiprimeD1ModeRoutingBits.acquire (packetKey lows highs high) a i tile).bit ∧\n    ((recover (packetKey lows highs high) slots).left[i.val]?).getD []=\n      (SemiprimeD1ModeRoutingBits.acquire (packetKey lows highs high) a i tile).target := by\n  have hr := (recover_colours lows highs high slots hc (hs.trans hl.symm) i.val (by omega)).1\n  have hf := acquire_fields a lows highs high hl hh i tile\n  have hsource := (acquire_colours (packetKey lows highs high) a i tile).1\n  have htarget := (acquire_colours (packetKey lows highs high) a i tile).2\n  rw [hf.1,hf.2] at hsource htarget\n  rw [hr,hsource] at hcross\n  have hp := crossing_choice _ _ _ _ hcross\n  refine ⟨hp.1,?_⟩\n  rw [hr,htarget]\n  exact hp.2\n\n/-- Equal physical class fields are entirely local; a crossing mode may be zero. -/\ntheorem equal_class_local (a : ℕ) (lows highs : List (List Bool)) (high : List Bool)\n    (hc : Canonical lows highs) (hl : lows.length=a) (hh : highs.length=a)\n    (i : Fin a) (tile : Fin (2^(i.val+1))) (slots : List Bool) (hs : slots.length=a)\n    (heq : (lows[i.val]?).getD []=(highs[i.val]?).getD []) :\n    ((recover (packetKey lows highs high) slots).left[i.val]?).getD []=\n      (SemiprimeD1ModeRoutingBits.acquire (packetKey lows highs high) a i tile).source ∧\n    ((recover (packetKey lows highs high) slots).right[i.val]?).getD []=\n      (SemiprimeD1ModeRoutingBits.acquire (packetKey lows highs high) a i tile).source := by\n  have hr := recover_colours lows highs high slots hc (hs.trans hl.symm) i.val (by omega)\n  have hf := acquire_fields a lows highs high hl hh i tile\n  have hsource := (acquire_colours (packetKey lows highs high) a i tile).1\n  rw [hf.1,hf.2] at hsource\n  rw [hr.1,hr.2,hsource,heq]\n  simp only [ite_self,and_self]\n\nend RiemannGaussian.SemiprimeD1ModeRoutingWireColours\n","RiemannGaussian.SemiprimeD1NetworkDoubleAssignment":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1NetworkIntegralDeformation\nimport RiemannGaussian.SemiprimeD1TensorNetworkLayout\nimport RiemannGaussian.SemiprimeD1JetEmbedding\n\n/-! # Actual literal-network deformation as two original endpoint assignments\nIndividual current entries are reduced separately before their products. The\nwire forms use original acquired sparse placements, not an advised matrix.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 3000000\nnamespace RiemannGaussian.SemiprimeD1NetworkDoubleAssignment\nopen scoped BigOperators\nopen SemiprimeD1TensorNetwork SemiprimeD1JetAlgebra SemiprimeD1JetBoxIndex\nopen SemiprimeD1JetScalarMap SemiprimeD1DyadicInteger SemiprimeD1OriginalDeformation\nopen SemiprimeD1LeafCounter SemiprimeD1NetworkIntegralDeformation\nnoncomputable section\n\n/-- The actual quotient embedding preserves coefficient constants, including\nall old nilpotent coordinates. No higher-precision ring lift is used. -/\ntheorem outerEmbedding_constants {R : Type*} [CommRing R] {m : ℕ}\n    (q : ℕ) (ds : Fin m→ℕ) (c : R) :\n    SemiprimeD1JetAlgebra.outerEmbedding q ds (constants ds c)=\n      constants (SemiprimeD1JetAlgebra.outerDims q ds) c := by\n  change SemiprimeD1JetAlgebra.outerEmbedding q ds (project ds (MvPowerSeries.C c))=\n    project (SemiprimeD1JetAlgebra.outerDims q ds) (MvPowerSeries.C c)\n  rw [SemiprimeD1JetAlgebra.outerEmbedding_project,MvPowerSeries.rename_C]\n\n/-- Constants square for the actual same-precision fresh-axis embedding. -/\ntheorem outerEmbedding_constants_comp {R : Type*} [CommRing R] {m : ℕ}\n    (q : ℕ) (ds : Fin m→ℕ) :\n    (SemiprimeD1JetAlgebra.outerEmbedding (R:=R) q ds).comp (constants ds)=\n      constants (SemiprimeD1JetAlgebra.outerDims q ds) := by\n  ext c\n  exact outerEmbedding_constants q ds c\n\n/-- Original modular local deformation of the actual network's literal caches\nis the finite X/Y sum with its full original acquired kernel row product. -/\ntheorem network_double_sum {S : Type*} [CommRing S] (axes : List ℕ) (p : ℕ)\n    (f : Algebra (dims axes) (ZMod (2^p))→+*S) (z : S)\n    (net : Network) (r a : ℕ) [NeZero r]\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) :\n    ((networkPolynomial axes net.leftCount net.rows.length r a (arity net.rows) (owner net.rows) t\n      net.left.toList net.right.toList).map (scalarMap (dims axes) (reduction p))).eval₂ f z=\n      ∑x : Fin (Placements net.leftCount net.rows.length r a (arity net.rows) (owner net.rows)).length→Bool,\n      ∑y : Fin (Placements net.leftCount net.rows.length r a (arity net.rows) (owner net.rows)).length→Bool,\n        f ((net.right.toList.map (fun v => SemiprimeD1JetInterpretation.interpret ⟨axes,p⟩\n          (SemiprimeD1TensorTables.valueAt v.table (localAssignment x v)))).prod)*\n        f ((net.left.toList.map (fun v => SemiprimeD1JetInterpretation.interpret ⟨axes,p⟩\n          (SemiprimeD1TensorTables.valueAt v.table (localAssignment y v)))).prod)*\n        ∏i, (if y i then\n          (∑j,(if packet net.leftCount net.rows.length r a (arity net.rows) (owner net.rows) i=\n              packet net.leftCount net.rows.length r a (arity net.rows) (owner net.rows) j then\n            SemiprimeD1UniversalModeData.entryValue p (f.comp (constants (dims axes))) z\n              (SemiprimeD1WireKernelOriginal.acquireOriginal a t\n                (slot net.leftCount net.rows.length r a (arity net.rows) (owner net.rows) i)\n                (slot net.leftCount net.rows.length r a (arity net.rows) (owner net.rows) j)) else 0)*\n            SemiprimeStreamingTensor.bit (x j))\n          else 1-(∑j,(if packet net.leftCount net.rows.length r a (arity net.rows) (owner net.rows) i=\n              packet net.leftCount net.rows.length r a (arity net.rows) (owner net.rows) j then\n            SemiprimeD1UniversalModeData.entryValue p (f.comp (constants (dims axes))) z\n              (SemiprimeD1WireKernelOriginal.acquireOriginal a t\n                (slot net.leftCount net.rows.length r a (arity net.rows) (owner net.rows) i)\n                (slot net.leftCount net.rows.length r a (arity net.rows) (owner net.rows) j)) else 0)*\n            SemiprimeStreamingTensor.bit (x j))) := by\n  classical\n  rw [network_modular_contraction]\n  apply Finset.sum_congr rfl\n  intro x _\n  rw [SemiprimeStreamingTensor.evaluate_eq_sum,Finset.mul_sum]\n  apply Finset.sum_congr rfl\n  intro y _\n  exact (mul_assoc _ _ _).symm\n\nend\nend RiemannGaussian.SemiprimeD1NetworkDoubleAssignment\n","RiemannGaussian.SemiprimeD1OrdinalBankSpec":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackJetReadExecution\nimport RiemannGaussian.SemiprimeD1StackVertexProductPolynomial\nimport RiemannGaussian.SemiprimeD1StackAssignmentOrder\n/-! # Exact padded ordinal-bank values, common width and byte inventory\nThese are specifications of the actual tally-controlled Body/Increment loop,\nnot an executed native range getter or a supplied ID list.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1500000\nnamespace RiemannGaussian.SemiprimeD1OrdinalBankSpec\nopen SemiprimeBitArithmetic (bitValue)\nopen SemiprimeD1StackAssignmentOrder (assignments remaining)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\n\n/-- Mathematical sequence of EXACTLY M repeated wrapped-counter states. -/\ndef words (M : ℕ) : List (List Bool) := assignments M (List.replicate M false)\n/-- Proof-side actual selected padded word; the physical caller uses StackJetRead. -/\ndef idAt (M i : ℕ) : List Bool := ((words M)[i]?).getD []\n/-- Physically allocated zero has numeric value zero, including zero width. -/\ntheorem zero_value (M : ℕ) : bitValue (List.replicate M false)=0 := by\n  induction M with\n  | zero => rfl\n  | succ M ih => simp [List.replicate_succ,SemiprimeBitArithmetic.bitValue,SemiprimeBitArithmetic.bitNat,ih]\n/-- The M-controlled loop never reaches binary capacity, even on its final increment. -/\ntheorem strict_capacity (M : ℕ) : M<2^M := by\n  induction M with\n  | zero => decide\n  | succ M ih =>\n    rw [pow_succ]\n    have hp : (0:ℕ)<2^M := by positivity\n    omega\n/-- Exactly the acquired tally length, not 2^M assignments, is generated. -/\ntheorem length (M : ℕ) : (words M).length=M := SemiprimeD1StackAssignmentOrder.assignments_length _ _\n/-- Exact ascending original ordinal order. -/\ntheorem values (M : ℕ) : (words M).map bitValue=List.range M := by\n  have hn : M≤remaining (List.replicate M false) := by\n    rw [SemiprimeD1StackAssignmentOrder.zero_remaining]\n    exact (strict_capacity M).le\n  simpa [words,zero_value,←List.range_eq_range'] using SemiprimeD1StackAssignmentOrder.assignments_values M (List.replicate M false) hn\n/-- Every generated binary ID retains the SAME acquired width, not compact width. -/\ntheorem word_length (M : ℕ) (word : List Bool) (hw : word∈words M) : word.length=M := by\n  simpa using SemiprimeD1StackAssignmentOrder.assignments_width M (List.replicate M false) word hw\n/-- Actual nth ID's binary value is its canonical ordinal. -/\ntheorem id_value (M i : ℕ) (hi : i<M) : bitValue (idAt M i)=i := by\n  have hir : i<(words M).length := by simpa only [length] using hi\n  have h:=congrArg (fun xs:List ℕ=>(xs[i]?).getD 0) (values M)\n  simpa [idAt,List.getElem?_map,List.getElem?_eq_getElem hir,List.getElem?_range hi] using h\n/-- The actual nth payload has exactly the physically acquired common width. -/\ntheorem id_length (M i : ℕ) (hi : i<M) : (idAt M i).length=M := by\n  have hir : i<(words M).length := by simpa only [length] using hi\n  rw [idAt,List.getElem?_eq_getElem hir,Option.getD_some]\n  exact word_length M _ (List.getElem_mem hir)\n/-- Padded IDs are injective by their actual numeric values, NOT by compactness. -/\ntheorem id_eq_iff (M i j : ℕ) (hi : i<M) (hj : j<M) : idAt M i=idAt M j ↔ i=j := by\n  constructor\n  · intro h\n    have hv:=congrArg bitValue h\n    simpa only [id_value M i hi,id_value M j hj] using hv\n  · intro h; subst j; rfl\n/-- All ordinals are covered, including ordinal zero's all-false payload. -/\ntheorem id_mem (M i : ℕ) (hi : i<M) : idAt M i∈words M := by\n  have hir : i<(words M).length := by simpa only [length] using hi\n  rw [idAt,List.getElem?_eq_getElem hir,Option.getD_some]\n  exact List.getElem_mem hir\n/-- Actual output words have no duplicates despite their retained high zeros. -/\ntheorem nodup (M : ℕ) : (words M).Nodup := by\n  apply List.Nodup.of_map (f:=bitValue)\n  rw [values]\n  exact List.nodup_range\n/-- Every physically logged counter has a false overflow flag on its subsequent\nactual Increment call; M<2^M licenses this, not an overflow/count answer. -/\ntheorem no_overflow (M : ℕ) (word : List Bool) (hw : word∈words M) :\n    SemiprimeD1StackIncrement.overflow word=false := by\n  have hv : bitValue word<M := by\n    have hmem : bitValue word∈(words M).map bitValue := List.mem_map.mpr ⟨word,hw,rfl⟩\n    rw [values] at hmem\n    exact List.mem_range.mp hmem\n  have hlen:=word_length M word hw\n  have hb:=SemiprimeD1StackIncrement.value_balance word\n  cases ho:SemiprimeD1StackIncrement.overflow word with\n  | false => rfl\n  | true =>\n    rw [ho,hlen] at hb\n    simp only [SemiprimeBitArithmetic.bitNat,ite_true] at hb\n    have hc:=strict_capacity M\n    omega\n/-- Exact framed payload inventory of a repeated fixed-width counter prefix. -/\ntheorem assignment_bytes (n : ℕ) (word : List Bool) :\n    (vectorBits (assignments n word)).length=2*n*word.length+2*n+1 := by\n  induction n generalizing word with\n  | zero => simp [assignments,vectorBits]\n  | succ n ih =>\n    simp only [assignments,vectorBits,List.length_cons,SemiprimeSourceHistogramKeyBits.frame_length,ih,\n      SemiprimeD1StackIncrement.wrapped_length]\n    nlinarith\n/-- Exact whole-bank bytes are quadratic in its ACTUALLY acquired tally length. -/\ntheorem bank_bytes (M : ℕ) : (vectorBits (words M)).length=2*M*M+2*M+1 := by\n  simpa [words] using assignment_bytes M (List.replicate M false)\n/-- Any actual scope sublist of this producer has the same honest quadratic\nbyte cap, without a supplied arbitrary-ID width or compactness assumption. -/\ntheorem sublist_bytes (M : ℕ) (ws : List (List Bool)) (hsub : ws.Sublist (words M)) :\n    (vectorBits ws).length≤2*M*M+2*M+1 := by\n  have hl : ws.length≤M := by simpa only [length] using hsub.length_le\n  have hw : ∀w∈ws,w.length≤M := fun w h=> (word_length M w (hsub.subset h)).le\n  have hb:=SemiprimeD1StackVertexProductPolynomial.vector_length ws M hw\n  nlinarith\n\nend RiemannGaussian.SemiprimeD1OrdinalBankSpec\n","RiemannGaussian.SemiprimeD1PackedRootCaches":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PackedNetworkTopology\n/-! # Actual marked-root structural caches, without another acquisition\nThe stopped original-input machine already holds the complete structural\nsource bank and chronological sparse inventory for the NEW marked network.\nOnly table-free bytes are reused. Its NEW record tape remains the separately\nacquired operand, and the physical source retains its own checked clock.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnoncomputable section\nnamespace RiemannGaussian.SemiprimeD1PackedRootCaches\nopen SemiprimeBitArithmetic (bitValue)\nattribute [local irreducible] SemiprimeD1PacketReplayOriginal.acquire\nattribute [local irreducible] SemiprimeD1IncidenceAcquisition.acquire SemiprimeD1IncidenceSearch.run\nnamespace P\nexport SemiprimeD1StackPackedRootInput (Stack program initial rootStack output)\nexport SemiprimeD1StackPackedRootInputEncoding (done)\nend P\nnamespace Q\nexport SemiprimeD1StackSourceSelectionAcquire (Stack)\nexport SemiprimeD1StackSourceSelectionAcquireEncoding (result)\nend Q\nnamespace T\nexport SemiprimeD1PackedNetworkTopology (inventory actual_selection actual_inventory)\nend T\nnamespace A\nexport SemiprimeD1StackRootSelectionAcquireEncoding (dimension)\nend A\n/-- Literal finite embedding of every actual154-word structural cache into the full2505 bank. -/\ndef sourceStack (k : Q.Stack) : P.Stack :=\n  P.rootStack (SemiprimeD1StackRootPacketInventory.rootStack\n    (SemiprimeD1StackRootRecoveryWidth.rootStack\n      (SemiprimeD1StackRootPacketPadding.rootStack\n        (SemiprimeD1StackRootSelectionAcquire.acquisitionStack k))))\n/-- Exact physically retained whole source bank, before changing its mathematical interpretation. -/\ntheorem old_source (bits : List Bool) (hN : 0<bitValue bits) (k : Q.Stack) :\n    (P.done bits hN).data (sourceStack k)=\n      Q.result (SemiprimeD1StackMarkedRootRecordsNetwork.old (bitValue bits) hN) (A.dimension bits) k := by\n  have h0 := SemiprimeD1StackPackedRootInputOriginal.all_root_retained bits hN\n    (SemiprimeD1StackRootPacketInventory.rootStack\n      (SemiprimeD1StackRootRecoveryWidth.rootStack\n        (SemiprimeD1StackRootPacketPadding.rootStack\n          (SemiprimeD1StackRootSelectionAcquire.acquisitionStack k))))\n  have h1 := SemiprimeD1StackRootPacketInventoryExecution.root_retained bits hN\n    (SemiprimeD1StackRootRecoveryWidth.rootStack\n      (SemiprimeD1StackRootPacketPadding.rootStack\n        (SemiprimeD1StackRootSelectionAcquire.acquisitionStack k)))\n  have h2 := SemiprimeD1StackRootRecoveryWidthExecution.root_retained bits hN\n    (SemiprimeD1StackRootPacketPadding.rootStack\n      (SemiprimeD1StackRootSelectionAcquire.acquisitionStack k))\n  have h3 := SemiprimeD1StackRootPacketPaddingExecution.root_retained bits hN\n    (SemiprimeD1StackRootSelectionAcquire.acquisitionStack k)\n  have h4 := SemiprimeD1StackRootSelectionAcquireExecution.acquisition_retained bits hN k\n  exact h0.trans (h1.trans (h2.trans (h3.trans h4)))\n/-- Every literal structural cache byte has its exact NEW marked-network meaning. -/\ntheorem source_original (bits : List Bool) (hN : 0<bitValue bits) (k : Q.Stack) :\n    (P.done bits hN).data (sourceStack k)=\n      Q.result (SemiprimeD1StackMarkedRootRecordsNetwork.network (bitValue bits) hN) (A.dimension bits) k :=\n  (old_source bits hN k).trans\n    (congrArg (fun f => f k) (T.actual_selection (bitValue bits) hN (A.dimension bits))).symm\n/-- The actual chronological placement tape is retained in the original full bank. -/\ndef placements : P.Stack := P.rootStack SemiprimeD1StackRootPacketInventory.output\n/-- The actual observed-packet tape is retained separately from all tensor coefficients. -/\ndef packets : P.Stack := P.rootStack SemiprimeD1StackRootPacketInventory.packets\n/-- Chronological source/slot/edge/valid bytes for the NEW marked network, without replay. -/\ntheorem placements_original (bits : List Bool) (hN : 0<bitValue bits) :\n    (P.done bits hN).data placements=SemiprimeD1TensorTapeCodec.vectorBits\n      ((T.inventory (SemiprimeD1StackMarkedRootRecordsNetwork.network (bitValue bits) hN)\n        (A.dimension bits)).1.map SemiprimeD1StackPacketInventoryEncoding.placementBytes) := by\n  have h0 := SemiprimeD1StackPackedRootInputOriginal.all_root_retained bits hN\n    SemiprimeD1StackRootPacketInventory.output\n  have h1 := SemiprimeD1StackRootPacketInventoryOriginal.output_original bits hN\n  have hi := congrArg (fun x : List SemiprimeD1PacketInventory.Placement × List (List Bool) => SemiprimeD1TensorTapeCodec.vectorBits\n    (x.1.map SemiprimeD1StackPacketInventoryEncoding.placementBytes))\n      (T.actual_inventory (bitValue bits) hN (A.dimension bits))\n  exact h0.trans (h1.trans hi.symm)\n/-- Every raw packet byte and first-discovery order has its NEW marked-network meaning. -/\ntheorem packets_original (bits : List Bool) (hN : 0<bitValue bits) :\n    (P.done bits hN).data packets=SemiprimeD1TensorTapeCodec.vectorBits\n      (T.inventory (SemiprimeD1StackMarkedRootRecordsNetwork.network (bitValue bits) hN)\n        (A.dimension bits)).2 := by\n  have h0 := SemiprimeD1StackPackedRootInputOriginal.all_root_retained bits hN\n    SemiprimeD1StackRootPacketInventory.packets\n  have h1 := SemiprimeD1StackRootPacketInventoryOriginal.packets_original bits hN\n  have hi := congrArg (fun x : List SemiprimeD1PacketInventory.Placement × List (List Bool) => SemiprimeD1TensorTapeCodec.vectorBits x.2)\n    (T.actual_inventory (bitValue bits) hN (A.dimension bits))\n  exact h0.trans (h1.trans hi.symm)\nend RiemannGaussian.SemiprimeD1PackedRootCaches\n","RiemannGaussian.SemiprimeD1PacketEntryClock":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PacketCoefficientClock\nimport RiemannGaussian.SemiprimeD1PacketSourceClock\n\n/-! # Whole actual packet entry report from original finite input bounds\nThe exact real endpoints, acquired mode descriptors and global exponent tuple\nare executed. Every row/column/coefficient/source callback and prefix is paid.\nThe affine requested-coefficient factor `(K+1)^rows` remains explicit; no\npolynomial-in-K claim hides that finite recursion.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 160000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1PacketEntryClock\nopen SemiprimeD1JetAxes SemiprimeD1JetAffineCoefficient SemiprimeD1JetAffineCoefficientBounds\nopen SemiprimeD1PacketEntryBits SemiprimeD1PacketEntryInputs SemiprimeD1PacketArithmeticClock\nopen SemiprimeD1PacketCoefficientClock SemiprimeD1PacketSourceClock\n\n/-- Physical endpoint word copies plus original native slot-value control. -/\ndef wireClock (a E : ℕ) : ℕ := 4*a+3*E+2*2^a+10\n\n/-- Slot bounds are actual original orientation-word lengths, not desired outputs. -/\ntheorem wire_clock {V : ℕ} (a : ℕ) (endpoint : SemiprimeD1ChildGraph.Endpoint V) (bit : Bool)\n    (E : ℕ) (hs : endpoint.slot.length ≤ a) (he : endpoint.edge.length ≤ E) :\n    (wire a endpoint bit).2 ≤ wireClock a E := by\n  have hp := SemiprimeBitArithmetic.bitValue_lt_width endpoint.slot\n  have hpow := Nat.pow_le_pow_right (by decide : 0 < (2:ℕ)) hs\n  have hv : SemiprimeBitArithmetic.bitValue endpoint.slot ≤ 2^a := hp.le.trans hpow\n  simp only [wire,SemiprimeSourceCompactBits.copy_clock,SemiprimeSourceCompactBits.copy_bits]\n  unfold wireClock\n  omega\n\n/-- Complete local side split and every endpoint-word callback. -/\ndef gatherClock (a A E : ℕ) : ℕ := A*(wireClock a E+6)+2\n\n/-- Actual local gather has a fixed polynomial report in original endpoint bounds. -/\ntheorem gather_clock {V : ℕ} (a : ℕ) (endpoints : List (SemiprimeD1ChildGraph.Endpoint V))\n    (bits : List Bool) (E : ℕ) (hs : ∀e∈endpoints,e.slot.length ≤ a)\n    (he : ∀e∈endpoints,e.edge.length ≤ E) :\n    (gather a endpoints bits).clock ≤ gatherClock a endpoints.length E := by\n  induction endpoints generalizing bits with\n  | nil => simp only [gather,gatherClock,List.length_nil,Nat.zero_mul,Nat.zero_add,le_refl]\n  | cons endpoint endpoints ih =>\n    have hh := wire_clock a endpoint (bits.head?.getD false) E\n      (hs _ List.mem_cons_self) (he _ List.mem_cons_self)\n    have ht := ih bits.tail (fun e hm => hs e (List.mem_cons_of_mem _ hm))\n      (fun e hm => he e (List.mem_cons_of_mem _ hm))\n    dsimp only [gather]\n    split <;> dsimp only <;> unfold gatherClock at ht ⊢ <;>\n      simp only [List.length_cons,Nat.add_mul,Nat.one_mul] <;> omega\n\n/-- Every actual target mask entry performs one original global-beta read. -/\ntheorem restrictFrom_work (beta : List ℕ) (items : List SemiprimeD1PacketModeMask.Item) (index : ℕ) :\n    (SemiprimeD1PacketModeMask.restrictFrom beta items index).work ≤\n      items.length*(3*beta.length+6)+1 := by\n  induction items generalizing index with\n  | nil => simp only [SemiprimeD1PacketModeMask.restrictFrom,List.length_nil,Nat.zero_mul,Nat.zero_add,le_refl]\n  | cons item items ih =>\n    have hh := SemiprimeD1AffineCoefficientBounds.read_work 0 beta index\n    have ht := ih (index+1)\n    change (SemiprimeD1AffineCoefficient.read 0 beta index).2+\n      (SemiprimeD1PacketModeMask.restrictFrom beta items (index+1)).work+5 ≤ _\n    simp only [List.length_cons,Nat.add_mul,Nat.one_mul]\n    omega\n\n/-- Actual requested-coefficient budget is monotone in real-row count. -/\ntheorem affine_rows_mono (ctx : Context) (K L A T W C : ℕ) (h : L ≤ A) :\n    budget ctx K L T W C ≤ budget ctx K A T W C := by\n  unfold budget\n  apply Nat.mul_le_mul\n  · exact Nat.mul_le_mul_right _ (Nat.add_le_add_right h 1)\n  · exact Nat.pow_le_pow_right (by omega) h\n\n/-- Real-row acquisition grows linearly with actual column count. -/\ntheorem recipe_columns_mono (ctx : Context) (a C A K P T : ℕ) (h : C ≤ A) :\n    recipeClock ctx a C K P T ≤ recipeClock ctx a A K P T := by\n  unfold recipeClock rowBaseClock\n  gcongr\n\n/-- Original source-factor acquisition grows linearly with actual column count. -/\ntheorem source_columns_mono (ctx : Context) (a C A P B T : ℕ) (h : C ≤ A) :\n    sourceFactorClock ctx a C P B T ≤ sourceFactorClock ctx a A P B T := by\n  unfold sourceFactorClock\n  gcongr\n\n/-- Explicit complete actual entry budget. The only non-polynomial factor is\nits literal requested-coefficient row recursion, with at most A real rows. -/\ndef entryClock (ctx : Context) (a A K P T B L E : ℕ) : ℕ :=\n  gatherClock a A E+(K*(3*L+6)+1)+\n    (A*(recipeClock ctx a A K P T+4)+1)+\n    budget ctx K A K ctx.precision K+\n    (K*(sourceFactorClock ctx a A P B L+mulClock ctx+3)+oneClock ctx)+\n    mulClock ctx+3+L+10\n\n/-- Whole executed packet entry clock from acquired original dimensional bounds.\nEvery intermediate physical width/shape is derived from the concrete routines.\nNo requested coefficient, source-factor value or intermediate clock is supplied. -/\ntheorem evaluate_clock {V : ℕ} (ctx : Context) (z : JetRun) (hz : Good ctx z.words)\n    (a : ℕ) (i : Fin a) (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (items : SemiprimeD1PacketModeMask.Cache) (endpoints : List (SemiprimeD1ChildGraph.Endpoint V))\n    (beta : List ℕ) (bits : List Bool) (P T B E : ℕ)\n    (hmode : ∀item∈items.items,item.mode.order ≤ P) (htile : ∀item∈items.items,item.tile ≤ T)\n    (hbeta : ∀b∈beta,b ≤ B) (hslot : ∀e∈endpoints,e.slot.length ≤ a)\n    (hedge : ∀e∈endpoints,e.edge.length ≤ E) :\n    (evaluate ctx z a i t items endpoints beta bits).clock ≤\n      entryClock ctx a endpoints.length items.items.length P T B beta.length E := by\n  let input := gather a endpoints bits\n  let restricted := SemiprimeD1PacketModeMask.restrict items beta\n  let rows := recipes ctx (borrow z) a i t input.columns items.items input.rows\n  let target := SemiprimeD1JetAffineCoefficient.evaluate ctx items.items.length rows.value restricted.value\n  let source := sourceProduct ctx a i input.columns beta items.items 0\n  have hcount := gather_count a endpoints bits\n  have hR : input.rows.length ≤ endpoints.length := by\n    exact (Nat.le_add_right input.rows.length input.columns.length).trans hcount.le\n  have hC : input.columns.length ≤ endpoints.length := by\n    exact (Nat.le_add_left input.columns.length input.rows.length).trans hcount.le\n  have hinput := gather_clock a endpoints bits E hslot hedge\n  have hrestricted := restrictFrom_work beta items.items 0\n  have hrestrictedLength : restricted.value.length=items.items.length :=\n    SemiprimeD1PacketModeMask.restrictFrom_length _ _ _\n  have hrows := recipes_clock ctx (borrow z) hz a i t input.columns items.items input.rows P T hmode htile\n  have hrecipes := recipe_columns_mono ctx a input.columns.length endpoints.length items.items.length P T hC\n  have hrowsBound : rows.work ≤ endpoints.length*(recipeClock ctx a endpoints.length items.items.length P T+4)+1 := by\n    have hh := Nat.mul_le_mul hR (Nat.add_le_add_right hrecipes 4)\n    exact hrows.trans (Nat.add_le_add_right hh 1)\n  have hrowLength : rows.value.length=input.rows.length := by\n    rw [SemiprimeD1PacketEntryValue.recipes_value,List.length_map]\n  have hsourceRows : ∀row∈rows.value, Source ctx ctx.precision items.items.length row := by\n    intro row hrow\n    change row ∈ (recipes ctx (borrow z) a i t input.columns items.items input.rows).value at hrow\n    rw [SemiprimeD1PacketEntryValue.recipes_value] at hrow\n    obtain ⟨realRow,_,rfl⟩ := List.mem_map.mp hrow\n    exact recipe_source ctx (borrow z) a i t realRow input.columns items.items\n  have htarget := SemiprimeD1JetAffineCoefficientBounds.evaluate_clock ctx items.items.length rows.value restricted.value\n    ctx.precision items.items.length le_rfl hsourceRows\n  rw [hrowLength,hrestrictedLength] at htarget\n  have htargetBound : target.clock ≤ budget ctx items.items.length endpoints.length items.items.length ctx.precision items.items.length :=\n    htarget.trans (affine_rows_mono ctx _ _ _ _ _ _ hR)\n  have hsource := sourceProduct_clock ctx a i input.columns beta items.items 0 P B hmode hbeta\n  have hsourceMono := source_columns_mono ctx a input.columns.length endpoints.length P B beta.length hC\n  have hsourceBound : source.clock ≤ items.items.length*(sourceFactorClock ctx a endpoints.length P B beta.length+mulClock ctx+3)+oneClock ctx :=\n    hsource.trans (Nat.add_le_add_right (Nat.mul_le_mul_left _\n      (Nat.add_le_add_right (Nat.add_le_add_right hsourceMono (mulClock ctx)) 3)) (oneClock ctx))\n  have hout := multiply_clock ctx target source (evaluate_good ctx _ _ _)\n    (sourceProduct_good ctx a i input.columns beta items.items 0)\n  change input.clock+restricted.work+rows.work+(multiply ctx target source).clock+beta.length+10 ≤ _\n  have hrestricted' : restricted.work ≤ items.items.length*(3*beta.length+6)+1 := hrestricted\n  have hinput' : input.clock ≤ gatherClock a endpoints.length E := hinput\n  have hmul := hout.trans (Nat.add_le_add_right (Nat.add_le_add_right\n    (Nat.add_le_add htargetBound hsourceBound) (mulClock ctx)) 3)\n  calc\n    _ ≤ gatherClock a endpoints.length E+(items.items.length*(3*beta.length+6)+1)+\n        (endpoints.length*(recipeClock ctx a endpoints.length items.items.length P T+4)+1)+\n        (budget ctx items.items.length endpoints.length items.items.length ctx.precision items.items.length+\n          (items.items.length*(sourceFactorClock ctx a endpoints.length P B beta.length+mulClock ctx+3)+oneClock ctx)+mulClock ctx+3)+beta.length+10 := by\n      exact Nat.add_le_add (Nat.add_le_add (Nat.add_le_add (Nat.add_le_add\n        (Nat.add_le_add hinput' hrestricted') hrowsBound) hmul) (le_refl beta.length)) (le_refl 10)\n    _ = _ := by unfold entryClock;ring\n\n/-- All entry stages except the explicit finite coefficient recursion. -/\ndef nonAffineClock (ctx : Context) (a A K P T B L E : ℕ) : ℕ :=\n  gatherClock a A E+(K*(3*L+6)+1)+(A*(recipeClock ctx a A K P T+4)+1)+\n    (K*(sourceFactorClock ctx a A P B L+mulClock ctx+3)+oneClock ctx)+\n    mulClock ctx+3+L+10\n\n/-- Fixed arithmetic polynomial prefactor, before the literal (K+1)^A recurrence. -/\ndef entryPolynomial (ctx : Context) (a A K P T B L E : ℕ) : ℕ :=\n  nonAffineClock ctx a A K P T B L E+(A+1)*stageConstant ctx K K ctx.precision K\n\n/-- Exact separation of the finite coefficient-recursion stage. -/\ntheorem entryClock_eq (ctx : Context) (a A K P T B L E : ℕ) :\n    entryClock ctx a A K P T B L E = nonAffineClock ctx a A K P T B L E+\n      budget ctx K A K ctx.precision K := by\n  unfold entryClock nonAffineClock\n  ring\n\n/-- A fixed nonnegative overhead is absorbed without changing the recursion exponent. -/\ntheorem add_mul_le (X Y q : ℕ) (hq : 1 ≤ q) : X+Y*q ≤ (X+Y)*q := by\n  have hx : X ≤ X*q := by simpa only [Nat.mul_one] using Nat.mul_le_mul_left X hq\n  calc\n    _ ≤ X*q+Y*q := Nat.add_le_add_right hx _\n    _ = _ := by ring\n\n/-- Whole entry cost is an explicit original-dimension polynomial times the\nliteral naive coefficient recursion. It does not hide a dynamic-programming shortcut. -/\ntheorem entryClock_factor (ctx : Context) (a A K P T B L E : ℕ) :\n    entryClock ctx a A K P T B L E ≤ entryPolynomial ctx a A K P T B L E*(K+1)^A := by\n  rw [entryClock_eq]\n  unfold budget entryPolynomial\n  exact add_mul_le _ _ _ (Nat.one_le_pow _ _ (by omega))\n\n/-- Uniform table acquisition uses the actual packet arity, including zero-port cases. -/\ntheorem entryClock_mono_arity (ctx : Context) (a A A' K P T B L E : ℕ) (h : A ≤ A') :\n    entryClock ctx a A K P T B L E ≤ entryClock ctx a A' K P T B L E := by\n  unfold entryClock gatherClock recipeClock rowBaseClock sourceFactorClock budget\n  gcongr\n\nend RiemannGaussian.SemiprimeD1PacketEntryClock\n","RiemannGaussian.SemiprimeD1PacketInventoryCoverage":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PacketReplayOriginal\n\n/-! # Every actual real placement belongs to the observed sparse packet inventory\nThe marker invariant proves a newly emitted packet is present. Literal packet\nlist preservation then carries it through every remaining replay step. This is\nforward coverage of the executed inventory, not a supplied packet certificate.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2000000\nnamespace RiemannGaussian.SemiprimeD1PacketInventoryCoverage\nopen SemiprimeD1PacketInventory SemiprimeSourceHistogramTrie\n\n/-- Literal packet discovery never drops a previously recorded packet. -/\ntheorem step_preserves_packet (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (state : State) (key packet : List Bool) (hp : packet ∈ state.packets) :\n    packet ∈ (step dict a state key).2.packets := by\n  change packet ∈ if _ then _::state.packets else state.packets\n  split_ifs\n  · exact List.mem_cons_of_mem _ hp\n  · exact hp\n\n/-- Every remaining original replay suffix preserves all already recorded packets. -/\ntheorem replay_preserves_packet (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (keys : List (List Bool)) (state : State) (packet : List Bool) (hp : packet ∈ state.packets) :\n    packet ∈ (replay dict a keys state).2.packets := by\n  induction keys generalizing state with\n  | nil => exact hp\n  | cons key keys ih => exact ih _ (step_preserves_packet dict a state key packet hp)\n\n/-- The produced placement's own key is present after that SAME actual step. -/\ntheorem step_packet_mem (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (state : State) (key : List Bool) (hg : SeenGood state) :\n    (step dict a state key).1.packet ∈ (step dict a state key).2.packets := by\n  have hs := step_seen dict a state key hg\n  have hw : stored (step dict a state key).2.seen (step dict a state key).1.packet = [true] := by\n    simp only [step,SemiprimeSourceHistogramTrieStore.put_stored,ite_true]\n  rw [hs.2] at hw\n  by_contra hn\n  simp only [hn,ite_false] at hw\n  cases hw\n\n/-- EVERY real placement emitted by replay belongs to its actual final sparse inventory. -/\ntheorem replay_placement_packet (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (keys : List (List Bool)) (state : State) (hg : SeenGood state) (out : Placement)\n    (ho : out ∈ (replay dict a keys state).1) : out.packet ∈ (replay dict a keys state).2.packets := by\n  induction keys generalizing state with\n  | nil => simp only [replay,List.not_mem_nil] at ho\n  | cons key keys ih =>\n    change out ∈ (step dict a state key).1 :: (replay dict a keys (step dict a state key).2).1 at ho\n    rcases List.mem_cons.mp ho with he | ht\n    · subst out\n      exact replay_preserves_packet dict a keys (step dict a state key).2 _ (step_packet_mem dict a state key hg)\n    · exact ih _ (step_seen dict a state key hg) ht\n\n/-- Closed original-input coverage: every actual placement has an actually observed packet. -/\ntheorem original_placement_packet (n F r a : ℕ) (arity : Fin F → ℕ)\n    (owner : ((e : Fin F) × Fin (arity e)) → Fin n) (out : Placement)\n    (ho : out ∈ (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).placements) :\n    out.packet ∈ (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.packets :=\n  replay_placement_packet _ _ _ _ (initial_seen _) out ho\n\nend RiemannGaussian.SemiprimeD1PacketInventoryCoverage\n","RiemannGaussian.SemiprimeD1PacketPolynomialWeight":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PacketPolynomialSupport\nimport RiemannGaussian.SemiprimeD1AcquiredModeSum\n\n/-! # Dyadic weights of the ACTUAL physical packet row recipes\nThe actual coefficient branch supplies its same-bit test. Original D.12 then\nproves divisibility by2^(order+1), including the negative Boolean complement.\nMultiplication preserves this ideal content in the actual multijet ring; no\nmultiplicative valuation law or integral-domain assumption is used.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2400000\nnamespace RiemannGaussian.SemiprimeD1PacketPolynomialWeight\nopen scoped BigOperators\nopen SemiprimeD1WeightedPolynomial SemiprimeD1PacketEntryBits\nopen SemiprimeD1PacketEntryValue SemiprimeD1PacketEntryComponents SemiprimeD1PacketEntryInputs\nopen SemiprimeD1JetAxes SemiprimeD1JetInterpretation\nnoncomputable section\n\n/-- The actual global-index mode weight, in acquired descriptor order. -/\ndef weights (cache : SemiprimeD1PacketModeMask.Cache) : List ℕ :=\n  cache.items.map (fun item => item.mode.order+1)\n\n/-- Each actual physical signed mode coefficient has its ORIGINAL dyadic weight. -/\ntheorem coefficient_weight (ctx : Context) (z : SemiprimeD1JetAffineCoefficient.JetRun)\n    (a : ℕ) (i : Fin a) (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a)\n    (item : SemiprimeD1PacketModeMask.Item) (hpos : ctx.Positive) (hp : 0 < ctx.precision)\n    (ht : SemiprimeD1WireKernelOriginal.point a t.val ≠ 0)\n    (hi : padicValInt 2 (SemiprimeD1WireKernelOriginal.point a t.val) = i.val) :\n    (2 : Carrier ctx)^(item.mode.order+1) ∣ interpret ctx (coefficient ctx z a i t row item).words := by\n  rw [coefficient_value ctx z a i t row item hpos hp ht hi]\n  dsimp only\n  split_ifs with h\n  · have hbit : row.slot.val.testBit i.val = (item.tile%2^a).testBit i.val :=\n      beq_iff_eq.mp (Bool.and_eq_true_iff.mp h).2\n    obtain ⟨c, hc⟩ := SemiprimeD1UniversalModeData.original_weight ctx.precision a i.val item.mode.order\n      (SemiprimeD1JetAlgebra.constants (SemiprimeD1JetBoxIndex.dims ctx.axes))\n      (interpret ctx z.words) t row.slot ⟨item.tile%2^a, Nat.mod_lt _ (by positivity)⟩\n      ht hi i.isLt hbit\n    rw [hc]\n    simp only [map_ofNat]\n    exact dvd_mul_right _ c\n  · have hbit : row.slot.val.testBit i.val = (item.tile%2^a).testBit i.val :=\n      beq_iff_eq.mp (Bool.and_eq_true_iff.mp h).2\n    obtain ⟨c, hc⟩ := SemiprimeD1UniversalModeData.original_weight ctx.precision a i.val item.mode.order\n      (SemiprimeD1JetAlgebra.constants (SemiprimeD1JetBoxIndex.dims ctx.axes))\n      (interpret ctx z.words) t row.slot ⟨item.tile%2^a, Nat.mod_lt _ (by positivity)⟩\n      ht hi i.isLt hbit\n    rw [hc]\n    simp only [map_ofNat]\n    exact dvd_neg.mpr (dvd_mul_right _ c)\n  · exact dvd_zero _\n\n/-- Literal finite mode-polynomial sums retain coefficientwise dyadic content. -/\ntheorem weighted_list_sum {R : Type*} [CommRing R] (w : ℕ → ℕ)\n    (ps : List (MvPolynomial ℕ R)) (hp : ∀ p ∈ ps, Weighted w p) : Weighted w ps.sum := by\n  induction ps with\n  | nil => simpa only [List.sum_nil, map_zero] using weighted_C w (0 : R)\n  | cons p ps ih =>\n    exact weighted_add w _ _ (hp p List.mem_cons_self)\n      (ih (fun q hq => hp q (List.mem_cons_of_mem p hq)))\n\n/-- Literal finite row-polynomial products preserve every dyadic mode weight. -/\ntheorem weighted_list_prod {R : Type*} [CommRing R] (w : ℕ → ℕ)\n    (ps : List (MvPolynomial ℕ R)) (hp : ∀ p ∈ ps, Weighted w p) : Weighted w ps.prod := by\n  induction ps with\n  | nil => simpa only [List.prod_nil, map_one] using weighted_C w (1 : R)\n  | cons p ps ih =>\n    exact weighted_mul w _ _ (hp p List.mem_cons_self)\n      (ih (fun q hq => hp q (List.mem_cons_of_mem p hq)))\n\n/-- An actual affine recipe is weighted once its actual acquired coefficients are. -/\ntheorem rowPolynomial_weighted {R : Type*} [CommRing R] (w : ℕ → ℕ) (K : ℕ)\n    (row : SemiprimeD1AffineCoefficient.Row R)\n    (hc : ∀ j < K, (2 : R)^w j ∣ row.coefficients.getD j 0) :\n    Weighted w (SemiprimeD1AffineCoefficient.rowPolynomial K row) := by\n  unfold SemiprimeD1AffineCoefficient.rowPolynomial\n  apply weighted_add w _ _ (weighted_C w row.base)\n  apply weighted_list_sum\n  intro p hp\n  obtain ⟨j, hj, rfl⟩ := List.mem_map.mp hp\n  rw [MvPolynomial.C_mul_X_eq_monomial]\n  apply weighted_monomial\n  simpa only [degree_single, Nat.mul_one] using hc j (List.mem_range.mp hj)\n\n/-- Every actual row recipe, with its original complete descriptor cache, is weighted. -/\ntheorem recipe_weighted (ctx : Context) (z : SemiprimeD1JetAffineCoefficient.JetRun)\n    (a : ℕ) (i : Fin a) (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a)\n    (columns : List (Wire a)) (cache : SemiprimeD1PacketModeMask.Cache)\n    (hpos : ctx.Positive) (hp : 0 < ctx.precision)\n    (ht : SemiprimeD1WireKernelOriginal.point a t.val ≠ 0)\n    (hi : padicValInt 2 (SemiprimeD1WireKernelOriginal.point a t.val) = i.val) :\n    Weighted (SemiprimeD1AcquiredModeSum.weight (weights cache))\n      (SemiprimeD1AffineCoefficient.rowPolynomial cache.items.length\n        (SemiprimeD1JetAffineCoefficient.rowValue ctx (recipe ctx z a i t row columns cache.items).value)) := by\n  apply rowPolynomial_weighted\n  intro j hj\n  have hw : SemiprimeD1AcquiredModeSum.weight (weights cache) j = cache.items[j].mode.order+1 := by\n    unfold SemiprimeD1AcquiredModeSum.weight weights\n    rw [List.getD_eq_getElem _ _ (by simpa only [List.length_map] using hj), List.getElem_map]\n  rw [hw]\n  change (2 : Carrier ctx)^(cache.items[j].mode.order+1) ∣\n    ((coefficients ctx z a i t row cache.items).value.map (interpret ctx)).getD j 0\n  rw [coefficients_value, List.map_map]\n  rw [List.getD_eq_getElem _ _ (by simpa only [List.length_map] using hj), List.getElem_map]\n  exact coefficient_weight ctx z a i t row cache.items[j] hpos hp ht hi\n\n/-- The COMPLETE actual physical packet polynomial satisfies the weighted-menu\nhypothesis, including every repeated row and all Boolean complements. -/\ntheorem packet_polynomial_weighted (ctx : Context) (z : SemiprimeD1JetAffineCoefficient.JetRun)\n    (a : ℕ) (i : Fin a) (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (columns rows : List (Wire a)) (cache : SemiprimeD1PacketModeMask.Cache)\n    (hpos : ctx.Positive) (hp : 0 < ctx.precision)\n    (ht : SemiprimeD1WireKernelOriginal.point a t.val ≠ 0)\n    (hi : padicValInt 2 (SemiprimeD1WireKernelOriginal.point a t.val) = i.val) :\n    Weighted (SemiprimeD1AcquiredModeSum.weight (weights cache))\n      (SemiprimeD1AffineCoefficient.polynomial cache.items.length\n        ((recipes ctx z a i t columns cache.items rows).value.map\n          (SemiprimeD1JetAffineCoefficient.rowValue ctx))) := by\n  unfold SemiprimeD1AffineCoefficient.polynomial\n  apply weighted_list_prod\n  intro p hp'\n  obtain ⟨row, hrow, rfl⟩ := List.mem_map.mp hp'\n  rw [recipes_value, List.map_map] at hrow\n  obtain ⟨original, _, rfl⟩ := List.mem_map.mp hrow\n  exact recipe_weighted ctx z a i t original columns cache hpos hp ht hi\n\n/-- Actual descriptor weights equal the ORIGINAL acquired catalogue weights. -/\ntheorem original_weights {n F r a : ℕ} {arity : Fin F → ℕ}\n    (source : SemiprimeD1OriginalModeAcquisition.Acquired n F a arity)\n    (packet : Fin source.packets.state.packets.length) (i : Fin a) (g : Fin r) :\n    weights (SemiprimeD1PacketModeMask.fromModes source packet i g) =\n      SemiprimeD1ModeCatalog.weights (source.packets.state.packets.length*2^(i.val+1))\n        (source.precision-1) := by\n  have hc := SemiprimeD1PacketModeMask.fromModes_catalogue source packet i g\n  unfold weights SemiprimeD1ModeCatalog.weights\n  rw [← hc, List.map_map]\n  rfl\n\nend\nend RiemannGaussian.SemiprimeD1PacketPolynomialWeight\n","RiemannGaussian.SemiprimeD1PacketRows":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1IncidenceAcquisitionBounds\nimport RiemannGaussian.SemiprimeD1OrientationForward\nimport RiemannGaussian.SemiprimeD1OrientationInverseBounds\n\n/-! # Physical row reads for retained D1 pair keys\nThe executed reader splits the acquired pair ID once, performs two actual row\ntrie reads and parses each colour field once. It contains no finite-word getter.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1PacketRows\nopen SemiprimeSourceHistogramKeyBits\n\n/-- Parsed colour bytes and all physical parser reports. -/\nstructure Parsed where\n  /-- Actual parsed compact-colour payloads in coordinate order. -/\n  fields : List (List Bool)\n  /-- Actual complete-parse flag, including the empty terminal tail. -/\n  valid : Bool\n  /-- Retained parser/read/copy and finite-control reports. -/\n  clock : ℕ\n\n/-- Parse exactly the original coordinate count, rejecting truncated fields. -/\ndef parse : ℕ → List Bool → Parsed\n  | 0,bs => ⟨[],bs.isEmpty,2⟩\n  | a+1,bs =>\n    let field := split bs\n    if field.valid then\n      let tail := parse a field.rest\n      ⟨field.first::tail.fields,tail.valid,field.clock+tail.clock+5⟩\n    else ⟨[],false,field.clock+3⟩\n\n/-- Literal framing of a finite list of acquired colour fields. -/\ndef serialize : List (List Bool) → List Bool\n  | [] => []\n  | x::xs => frame x (serialize xs)\n\n/-- Every field of an acquired well-formed payload is read exactly. -/\ntheorem parse_serialize (xs : List (List Bool)) :\n    (parse xs.length (serialize xs)).fields=xs ∧\n      (parse xs.length (serialize xs)).valid=true := by\n  induction xs with\n  | nil => exact ⟨rfl,rfl⟩\n  | cons x xs ih =>\n    simp only [List.length_cons,serialize,parse,split_frame,ite_true,ih.1,ih.2]\n    simp\n\n/-- The original row serializer uses exactly its physically trimmed magnitudes. -/\ntheorem serialize_row (row : SemiprimeSourceHistogramRows.Row) :\n    serialize (row.map (fun x => (SemiprimeSourceCompactBits.trim x.numerator.magnitude).bits))=\n      SemiprimeSourceHistogramRows.layout row := by\n  induction row with\n  | nil => rfl\n  | cons x xs ih => simp only [List.map_cons,serialize,SemiprimeSourceHistogramRows.layout,ih]\n\n/-- Actual pair-row read, retaining split/read/parse reports. -/\nstructure PairRows where\n  /-- Parsed original owner-colour row. -/\n  left : List (List Bool)\n  /-- Parsed original factor-colour row. -/\n  right : List (List Bool)\n  /-- Actual complete-parse flag, including the empty terminal tail. -/\n  valid : Bool\n  /-- Retained parser/read/copy and finite-control reports. -/\n  clock : ℕ\n\n/-- Read only the selected IDs encoded in the actual pair key. -/\ndef read (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (key : List Bool) : PairRows :=\n  let ids := split key\n  let lbytes := SemiprimeSourceHistogramRows.readRow dict ids.first\n  let rbytes := SemiprimeSourceHistogramRows.readRow dict ids.rest\n  let left := parse a lbytes.bits\n  let right := parse a rbytes.bits\n  ⟨left.fields,right.fields,ids.valid && left.valid && right.valid,\n    ids.clock+lbytes.clock+rbytes.clock+left.clock+right.clock+9⟩\n\n/-- Exact physical read semantics; all three acquisitions are literal calls. -/\ntheorem read_frame (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (leftId rightId : List Bool) :\n    (read dict a (frame leftId rightId)).left=\n      (parse a (SemiprimeSourceHistogramRows.readRow dict leftId).bits).fields ∧\n    (read dict a (frame leftId rightId)).right=\n      (parse a (SemiprimeSourceHistogramRows.readRow dict rightId).bits).fields := by\n  simp only [read,split_frame]\n  simp\n\n/-- Original physical row output, not a supplied native colour function. -/\ntheorem parse_row (row : SemiprimeSourceHistogramRows.Row) :\n    (parse row.length (SemiprimeSourceHistogramRows.layout row)).fields=\n      row.map (fun x => (SemiprimeSourceCompactBits.trim x.numerator.magnitude).bits) ∧\n    (parse row.length (SemiprimeSourceHistogramRows.layout row)).valid=true := by\n  have h := parse_serialize\n    (row.map (fun x => (SemiprimeSourceCompactBits.trim x.numerator.magnitude).bits))\n  simpa only [List.length_map,serialize_row] using h\n\n/-- Physical fields of an actual acquired row are the canonical palette bytes. -/\ntheorem original_fields (r a : ℕ) [NeZero r] (id : List Bool)\n    (hi : id∈(SemiprimeSourceCompactWordBank.acquire r a).ids) :\n    (parse a (SemiprimeSourceHistogramRows.readRow\n      (SemiprimeSourceHistogramRows.acquire r a) id).bits).fields=\n      SemiprimeD1OrientationPalette.fields (SemiprimeSourceWordBankSemantics.decode r a id) ∧\n    (parse a (SemiprimeSourceHistogramRows.readRow\n      (SemiprimeSourceHistogramRows.acquire r a) id).bits).valid=true := by\n  rw [SemiprimeSourceHistogramRows.lookup_original r a id hi,\n    SemiprimeSourceHistogramRows.encodeRow_bits]\n  let row := (SemiprimeSourceWordBank.readRow (SemiprimeSourceCompactWordBank.acquire r a) id).value\n  have hlen := SemiprimeSourceCompactWordBank.readRow_length r a id hi\n  change row.length=a at hlen\n  have hp := parse_row row\n  rw [hlen] at hp\n  change (parse a (SemiprimeSourceHistogramRows.layout row)).fields=_ ∧\n    (parse a (SemiprimeSourceHistogramRows.layout row)).valid=true\n  rw [hp.1,hp.2]\n  refine ⟨?_,rfl⟩\n  have hvals := SemiprimeSourceHistogramRowKeys.original_colour_values r a id hi\n  change row.map _=_ at hvals\n  apply List.ext_getElem\n  · simp only [List.length_map,SemiprimeD1OrientationPalette.fields,List.length_ofFn,hlen]\n  · intro i h₁ h₂\n    have hiv : i<a := by simpa only [SemiprimeD1OrientationPalette.fields,List.length_ofFn] using h₂\n    have hrow : i<row.length := by omega\n    have hv := congrArg (fun xs : List ℚ => xs[i]?) hvals\n    simp only [List.getElem?_map, List.getElem?_eq_getElem hrow,\n      Option.map_some,SemiprimeSourceWordBankRows.coordinates,\n      List.getElem?_ofFn] at hv\n    simp only [hiv, ↓reduceDIte,Option.some.injEq] at hv\n    simp only [List.getElem_map,SemiprimeD1OrientationPalette.fields,List.getElem_ofFn]\n    apply SemiprimeSourceCompactWordIds.compact_value_injective _ _\n      (SemiprimeSourceCompactBits.trim_compact _)\n      (SemiprimeSourceHistogramHeadRefinement.numberKey_compact _)\n    rw [SemiprimeSourceHistogramHeadRefinement.numberKey_value]\n    exact_mod_cast hv\n\n/-- Every parser prefix has at most the requested number of physical fields. -/\ntheorem parse_length (a : ℕ) (bs : List Bool) : (parse a bs).fields.length≤a := by\n  induction a generalizing bs with\n  | zero => simp only [parse,List.length_nil,Nat.zero_le]\n  | succ a ih =>\n    simp only [parse]\n    split_ifs\n    · simpa only [List.length_cons,Nat.add_le_add_iff_right] using ih _\n    · simp\n\n/-- Parser fields are actual bounded slices of the original acquired payload. -/\ntheorem parse_fields_bound (a : ℕ) (bs : List Bool) :\n    ∀ field∈(parse a bs).fields,field.length≤bs.length := by\n  induction a generalizing bs with\n  | zero => simp [parse]\n  | succ a ih =>\n    intro field hf\n    simp only [parse] at hf\n    split_ifs at hf\n    · rcases List.mem_cons.mp hf with he|he\n      · subst field\n        exact (SemiprimeD1OrientationInverseBounds.split_metrics bs).1\n      · exact le_trans (ih _ field he) (SemiprimeD1OrientationInverseBounds.split_metrics bs).2.1\n    · simp at hf\n\n/-- Paid one-pass field parsing, including malformed/truncated input branches. -/\ntheorem parse_clock (a : ℕ) (bs : List Bool) :\n    (parse a bs).clock≤(a+1)*(6*bs.length+8) := by\n  induction a generalizing bs with\n  | zero => simp only [parse];omega\n  | succ a ih =>\n    have hs := SemiprimeD1OrientationInverseBounds.split_metrics bs\n    have ht := ih (split bs).rest\n    simp only [parse]\n    split_ifs <;> dsimp only\n    · nlinarith\n    · nlinarith\n\n/-- Actual row dictionary reads and parser reports have a polynomial byte bound.\nThe hypotheses bound literal stored payloads, not semantic row answers. -/\ntheorem read_clock (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (key : List Bool) (B : ℕ)\n    (hl : (SemiprimeSourceHistogramTrie.stored dict.trie (split key).first).length≤B)\n    (hr : (SemiprimeSourceHistogramTrie.stored dict.trie (split key).rest).length≤B) :\n    (read dict a key).clock≤22*key.length+6*B+2*(a+1)*(6*B+8)+40 := by\n  have hs := SemiprimeD1OrientationInverseBounds.split_metrics key\n  have hcl := SemiprimeSourceHistogramTrieBounds.lookup_clock dict.trie (split key).first B hl\n  have hcr := SemiprimeSourceHistogramTrieBounds.lookup_clock dict.trie (split key).rest B hr\n  have hpl := parse_clock a (SemiprimeSourceHistogramRows.readRow dict (split key).first).bits\n  have hpr := parse_clock a (SemiprimeSourceHistogramRows.readRow dict (split key).rest).bits\n  have hll : (SemiprimeSourceHistogramRows.readRow dict (split key).first).bits.length≤B := by\n    simpa only [SemiprimeSourceHistogramRows.readRow,SemiprimeSourceHistogramTrie.lookup_bits] using hl\n  have hrl : (SemiprimeSourceHistogramRows.readRow dict (split key).rest).bits.length≤B := by\n    simpa only [SemiprimeSourceHistogramRows.readRow,SemiprimeSourceHistogramTrie.lookup_bits] using hr\n  change (split key).clock+_+_+_+_+9≤_\n  simp only [SemiprimeSourceHistogramRows.readRow] at hpl hpr hll hrl ⊢\n  nlinarith\n\nend RiemannGaussian.SemiprimeD1PacketRows\n","RiemannGaussian.SemiprimeD1PublicCorrectness":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PublicCountConsequences\nimport RiemannGaussian.SemiprimeD1RecursiveCorrectness\nimport RiemannGaussian.SemiprimeD1RootNetworkContraction\n\n/-! # Closed original-input semiprime factorization correctness\nThe executed prefix counter acquires its own original root network. Its actual\nrecursive output equals the complete original contraction, whose residue modulo\nfour is the exact semiprime prefix count. The existing literal search, operand\ndecoder and integer validation therefore recover a prime factor. No count,\nphase, coefficient, layout or factor answer is supplied to the algorithm.\nThis is a correctness theorem; the whole primitive bit-time theorem is separate.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 400000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1PublicCorrectness\nopen SemiprimePublicAcquiredExecution SemiprimeD1TensorNetwork\nopen SemiprimeCountRecovery SemiprimeCounterSearch SemiprimeBitArithmetic\nattribute [local irreducible] SemiprimeD1RootTensorTables.acquirePositive\n  SemiprimePublicAcquiredExecution.indexedPredicate\n\n/-- The actual original-prefix caller returns the canonical complete root\ncontraction, with all recursive child semantics discharged internally. -/\ntheorem prefixRun_words (N : ℕ) (hN : 0 < N)\n    (fixed : List (Fin (wireCount N) × Bool)) :\n    (SemiprimeD1PublicCounter.prefixRun N hN fixed).words =\n      (leaf SemiprimeD1RootOwnerTables.rootContext\n        (SemiprimeD1RootNetwork.acquirePositive N hN fixed).network).words := by\n  unfold SemiprimeD1PublicCounter.prefixRun\n  dsimp only\n  apply SemiprimeD1RecursiveCorrectness.run_words_eq_leaf\n  · simp [SemiprimeD1JetAxes.Context.Positive,SemiprimeD1RootOwnerTables.rootContext]\n  · exact SemiprimeD1RootNetwork.acquirePositive_wellFormed N hN fixed\n  · exact SemiprimeD1RootNetwork.acquirePositive_good N hN fixed\n\n/-- EVERY original semiprime prefix is counted exactly by this executed\nrecursive counter, including repeated primes and inconsistent prefixes. -/\ntheorem prefixCount_exact (N p q : ℕ) (hN : 0 < N) (hp : p.Prime) (hq : q.Prime)\n    (hsem : N = p*q) (fixed : List (Fin (wireCount N) × Bool)) :\n    SemiprimeD1PublicCounter.prefixCount N hN fixed =\n      acceptedCount (restricted assignmentBit (indexedPredicate N hN) fixed) := by\n  have hex := SemiprimeD1RootNetworkContraction.acquired_leaf_exact\n    N p q hN hp hq hsem fixed\n  have hval : (SemiprimeD1JetRingBits.coefficient SemiprimeD1RootOwnerTables.rootContext\n      (SemiprimeD1PublicCounter.prefixRun N hN fixed).words 0).val =\n      acceptedCount (restricted assignmentBit (indexedPredicate N hN) fixed) := by\n    rw [prefixRun_words N hN fixed]\n    exact hex\n  change SemiprimeD1PublicCounter.prefixCount N hN fixed % 4 = _ at hval\n  exact (Nat.mod_eq_of_lt (SemiprimeD1PublicCounter.prefixCount_lt_four N hN fixed)).symm.trans hval\n\n/-- Closed completeness for the fixed original-N public algorithm: every\nsemiprime produces a proper divisor equal to one of its prime factors. -/\ntheorem factor_complete (N p q : ℕ) (hp : p.Prime) (hq : q.Prime) (hsem : N = p*q) :\n    ∃ d,SemiprimeD1PublicCounter.factor N = some d ∧\n      2 ≤ d ∧ d < N ∧ N%d = 0 ∧ (d = p ∨ d = q) := by\n  have hN : 0 < N := by rw [hsem];exact Nat.mul_pos hp.pos hq.pos\n  exact SemiprimeD1PublicCountConsequences.factor_complete N p q hN hp hq hsem\n    (prefixCount_exact N p q hN hp hq hsem)\n\n/-- The actual binary-input entry point factors every decoded semiprime.\nCorrectness is independent of input padding; runtime uses canonical input size. -/\ntheorem factorBits_complete (input : List Bool) (p q : ℕ) (hp : p.Prime) (hq : q.Prime)\n    (hsem : bitValue input = p*q) :\n    ∃ d,SemiprimeD1PublicCounter.factorBits input = some d ∧\n      2 ≤ d ∧ d < bitValue input ∧ bitValue input%d = 0 ∧ (d = p ∨ d = q) :=\n  factor_complete (bitValue input) p q hp hq hsem\n\nend RiemannGaussian.SemiprimeD1PublicCorrectness\n","RiemannGaussian.SemiprimeD1RecoveryScalarWeightBits":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1RecoveryGridBitsBounds\n\n/-! # Physical cached powers and right-recursive local weight sums\nEvery scalar normalization/GCD and coefficient payload lookup is executed on\nphysical words. Address digits and typed loop tests remain native metadata\nstages, explicitly retained apart from the Boolean arithmetic clock.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeD1RecoveryScalarWeightBits\nopen SemiprimeRationalBits SemiprimeJetBits SemiprimeJetArray SemiprimeJetArrayHeight\nopen SemiprimeBitArithmetic\nopen SemiprimeD1RecoveryPowerBits SemiprimeD1RecoveryGridBits\nopen SemiprimeD1RecoveryScalarRun SemiprimeD1RecoveryWeightRun\nopen SemiprimeD1WireKernelOriginal SemiprimeD1JetRecoveryGrid\nopen SemiprimeD1HermiteDenominatorHeight SemiprimeD1HermiteWeightHeight\nopen SemiprimeD1HermiteDenominatorBits SemiprimeD1RecoveryWeightRunState\n\n/-- Actual scalar word with distinctly retained physical and native reports. -/\nstructure WordReport where\n  /-- Actual physical output rational. -/\n  word : RationalWord\n  /-- Actual arithmetic, GCD/division and payload scans/copies. -/\n  clock : ℕ\n  /-- Actual typed address generation and index/control stages. -/\n  metadataWork : ℕ\n\n/-- Acquire actual address digits and perform a literal paid physical memory scan. -/\ndef read (q : ℕ) (memory : List RationalWord) (i : ℕ) : WordReport :=\n  let address:=SemiprimeEncodedRowSelection.digits (q+1) i\n  let out:=SemiprimeSourceMemoryBits.readWord memory address.bits\n  ⟨out.word,out.clock,address.work+3⟩\n\n/-- Physical cache lookup refines the actual native coefficient access. -/\ntheorem read_value (q : ℕ) (memory : List RationalWord) (a : Array ℚ) (i : ℕ)\n    (hm : memory.map RationalWord.value=a.toList) (hi : i < q) :\n    (read q memory i).word.value=coefficient a i := by\n  have he : i < 2^(q+1) := hi.trans_le\n    ((SemiprimeD1HermiteDenominatorBits.self_le_two_power q).trans\n      (Nat.pow_le_pow_right (by decide : 0 < (2:ℕ)) (by omega)))\n  have hd:=SemiprimeEncodedRowSelection.digits_value (q+1) i he\n  change (SemiprimeSourceMemoryBits.readWord memory (SemiprimeEncodedRowSelection.digits (q+1) i).bits).word.value=_\n  rw [SemiprimeSourceMemoryBits.readWord_word,hd]\n  have hget:=congrArg (fun xs : List ℚ => (xs[i]?).getD 0) hm\n  simp only [List.getElem?_map,Array.getElem?_toList] at hget\n  unfold coefficient\n  rw [← hget]\n  cases memory[i]? <;> simp [SemiprimeRationalBits.zeroWord,RationalWord.value,\n    SemiprimeBitIndexClipping.SignedWord.value,SemiprimeBitArithmetic.bitValue]\n\n/-- Actual memory legality gives lookup legality, including the zero default. -/\ntheorem read_valid (q : ℕ) (memory : List RationalWord) (i : ℕ)\n    (hm : ∀x∈memory,x.Valid) : (read q memory i).word.Valid :=\n  SemiprimeSourceMemoryBits.readWord_valid _ _ hm\n\n/-- Actual physical source widths give lookup widths, without output advice. -/\ntheorem read_width (q : ℕ) (memory : List RationalWord) (i W : ℕ)\n    (hW : 0 < W) (hm : ∀x∈memory,Width x W) : Width (read q memory i).word W :=\n  SemiprimeSourceMemoryBits.readWord_width _ _ W (by omega) hm\n\n/-- Every visited address and payload bit is charged. -/\ntheorem read_clock (q : ℕ) (memory : List RationalWord) (i W : ℕ)\n    (hm : ∀x∈memory,Width x W) :\n    (read q memory i).clock ≤ (memory.length+1)*(8*W+15*(q+1)+30) := by\n  exact SemiprimeSourceMemoryBits.readWord_clock _ _ W (q+1) (by omega)\n    (by rw [SemiprimeEncodedRowSelection.digits_length]) hm\n\n/-- Actual address digit acquisition report, not an assumed address-cost oracle. -/\ntheorem read_metadataWork (q : ℕ) (memory : List RationalWord) (i : ℕ) :\n    (read q memory i).metadataWork=4*(q+1)+4 := by\n  simp only [read,SemiprimeEncodedRowSelection.digits_work]\n\n/-- Actual original right-recursive local coefficient sum on physical caches. -/\ndef sum (template : List Bool) (q j : ℕ) (inverse powers : List RationalWord) : List ℕ → WordReport\n  | [] => ⟨SemiprimeRationalBits.zeroWord,3,1⟩\n  | k::ks =>\n    let tail:=sum template q j inverse powers ks\n    if j ≤ k then\n      let left:=read q inverse (k-j)\n      let right:=read q powers k\n      let product:=executeOperation .mul left.word right.word template\n      let out:=executeOperation .add product.word tail.word template\n      ⟨out.word,tail.clock+left.clock+right.clock+product.clock+out.clock+7,\n        tail.metadataWork+left.metadataWork+right.metadataWork+4⟩\n    else ⟨tail.word,tail.clock+3,tail.metadataWork+3⟩\n\n/-- Each actual local weight multiplies the physically acquired Ezero once. -/\ndef weight (template : List Bool) (q j : ℕ) (scalar : RationalWord)\n    (inverse powers : List RationalWord) (keys : List ℕ) : WordReport :=\n  let total:=sum template q j inverse powers keys\n  let out:=executeOperation .mul scalar total.word template\n  ⟨out.word,total.clock+out.clock+3,total.metadataWork+2⟩\n\n/-- Exact original normalization cap for ANY actually visited retained-index list. -/\ntheorem sum_fits (a h u : ℕ) (t : Fin (size a))\n    (hq : 0 < nodeMultiplicity a h u t.val) (j : ℕ) (keys : List ℕ)\n    (hk : ∀k∈keys,k < nodeMultiplicity a h u t.val) (hl : keys.length ≤ nodeMultiplicity a h u t.val)\n    (W : ℕ) (hW : sumExponent a h u t.val < W) :\n    Fits (sumWeights j (SemiprimeD1JetRecoveryWeights.acquire a h u t.val).inverse.coefficients\n      (powersRun (SemiprimeD1WeightPrecision.argument a t.val) (nodeMultiplicity a h u t.val)).value keys).value W := by\n  let q:=nodeMultiplicity a h u t.val\n  let D:=sourceDenominator a h u t.val\n  let V:=inverseBase q D (sourceNumerator a h u t.val)\n  have hr:=representation_reduced_bound (pow_pos (Nat.mul_pos (sourceDenominator_pos a h u t.val)\n      (by unfold size; positivity)) q) (sum_representation a h u t hq j keys hk)\n  have hi:=inverse_power_bounds a h u t\n  have hN : (size a)^q=2^((a+1)*q) := by unfold size; rw [← pow_mul]\n  have hlen : keys.length ≤ 2^q := hl.trans (self_le_two_power q)\n  have hd : (D*size a)^q ≤ 2^(inverseExponent a h u t.val+(a+1)*q) := by\n    rw [mul_pow,hN,pow_add]\n    exact Nat.mul_le_mul_right _ hi.1\n  have hn : keys.length*(V*size a)^q ≤ 2^(q+inverseExponent a h u t.val+(a+1)*q) := by\n    rw [mul_pow,hN,pow_add,pow_add]\n    simpa only [Nat.mul_assoc] using Nat.mul_le_mul hlen (Nat.mul_le_mul_right (2^((a+1)*q)) hi.2)\n  have heD : inverseExponent a h u t.val+(a+1)*q < W := by\n    unfold sumExponent at hW\n    dsimp only [q]\n    omega\n  have heN : q+inverseExponent a h u t.val+(a+1)*q < W := by\n    unfold sumExponent at hW\n    dsimp only [q]\n    omega\n  exact ⟨hr.2.trans_lt (hn.trans_lt (Nat.pow_lt_pow_right (by decide : 1 < (2:ℕ)) heN)),\n    hr.1.trans_lt (hd.trans_lt (Nat.pow_lt_pow_right (by decide : 1 < (2:ℕ)) heD))⟩\n\n/-- Actual retained inverse-times-power products derive normalization capacity\nfrom the original cached inverse and argument representations. -/\ntheorem product_fits (a h u : ℕ) (t : Fin (size a))\n    (hq : 0 < nodeMultiplicity a h u t.val) (j k : ℕ) (hj : j ≤ k)\n    (hk : k < nodeMultiplicity a h u t.val) (W : ℕ)\n    (hW : inverseExponent a h u t.val+(a+1)*nodeMultiplicity a h u t.val < W) :\n    Fits (coefficient (SemiprimeD1JetRecoveryWeights.acquire a h u t.val).inverse.coefficients (k-j)*\n      coefficient (powersRun (SemiprimeD1WeightPrecision.argument a t.val)\n        (nodeMultiplicity a h u t.val)).value k) W := by\n  let q:=nodeMultiplicity a h u t.val\n  let D:=sourceDenominator a h u t.val\n  let V:=inverseBase q D (sourceNumerator a h u t.val)\n  rw [powersRun_coefficient _ q k hk]\n  have hr:=representation_mul (original_inverse_representation a h u t hq (k-j) (by omega))\n    (argument_power_representation a h u t k hk.le)\n  have reduced:=representation_reduced_bound (Nat.mul_pos (pow_pos (sourceDenominator_pos a h u t.val) q)\n    (by unfold size; positivity)) hr\n  have hi:=inverse_power_bounds a h u t\n  have hN : (size a)^q=2^((a+1)*q) := by unfold size; rw [← pow_mul]\n  have hd : D^q*(size a)^q ≤ 2^(inverseExponent a h u t.val+(a+1)*q) := by\n    rw [hN,pow_add]\n    exact Nat.mul_le_mul_right _ hi.1\n  have hn : V^q*(size a)^q ≤ 2^(inverseExponent a h u t.val+(a+1)*q) := by\n    rw [hN,pow_add]\n    exact Nat.mul_le_mul_right _ hi.2\n  have ht : 2^(inverseExponent a h u t.val+(a+1)*q) < 2^W :=\n    Nat.pow_lt_pow_right (by decide : 1 < (2:ℕ)) hW\n  exact ⟨reduced.2.trans_lt (hn.trans_lt ht),reduced.1.trans_lt (hd.trans_lt ht)⟩\n\n/-- Actual original local scalar sum refinement, with every coefficient read,\nmultiply, add and GCD normalization executing on physical words. -/\ntheorem sum_correct (template : List Bool) (a h u : ℕ) (t : Fin (size a))\n    (hq : 0 < nodeMultiplicity a h u t.val) (j : ℕ) (inverse powers : List RationalWord)\n    (hi : inverse.map RationalWord.value=(SemiprimeD1JetRecoveryWeights.acquire a h u t.val).inverse.coefficients.toList)\n    (hp : powers.map RationalWord.value=\n      (powersRun (SemiprimeD1WeightPrecision.argument a t.val) (nodeMultiplicity a h u t.val)).value.toList)\n    (hiv : ∀x∈inverse,x.Valid) (hpv : ∀x∈powers,x.Valid)\n    (hW : sumExponent a h u t.val < template.length)\n    (keys : List ℕ) (hk : ∀k∈keys,k < nodeMultiplicity a h u t.val)\n    (hl : keys.length ≤ nodeMultiplicity a h u t.val) :\n    (sum template (nodeMultiplicity a h u t.val) j inverse powers keys).word.value=\n      (sumWeights j (SemiprimeD1JetRecoveryWeights.acquire a h u t.val).inverse.coefficients\n        (powersRun (SemiprimeD1WeightPrecision.argument a t.val) (nodeMultiplicity a h u t.val)).value keys).value ∧\n    (sum template (nodeMultiplicity a h u t.val) j inverse powers keys).word.Valid ∧\n      Width (sum template (nodeMultiplicity a h u t.val) j inverse powers keys).word template.length := by\n  have hpos : 0 < template.length := by omega\n  have hprod : inverseExponent a h u t.val+(a+1)*nodeMultiplicity a h u t.val < template.length := by\n    unfold sumExponent at hW\n    omega\n  induction keys with\n  | nil =>\n    refine ⟨?_,?_,?_⟩\n    · norm_num [sum,sumWeights,SemiprimeRationalBits.zeroWord,RationalWord.value,\n        SemiprimeBitIndexClipping.SignedWord.value,SemiprimeBitArithmetic.bitValue]\n    · change 0 < 1; decide\n    · exact ⟨by simp [sum,SemiprimeRationalBits.zeroWord],by change 1 ≤ template.length; omega⟩\n  | cons k ks ih =>\n    have hkt:=hk k List.mem_cons_self\n    have tail:=ih (fun k h => hk k (List.mem_cons_of_mem _ h)) (by simp only [List.length_cons] at hl; omega)\n    by_cases hj : j ≤ k\n    · let q:=nodeMultiplicity a h u t.val\n      let old:=sum template q j inverse powers ks\n      let left:=read q inverse (k-j)\n      let right:=read q powers k\n      let product:=executeOperation .mul left.word right.word template\n      have lv:=read_value q inverse (SemiprimeD1JetRecoveryWeights.acquire a h u t.val).inverse.coefficients\n        (k-j) hi (by omega)\n      have rv:=read_value q powers (powersRun (SemiprimeD1WeightPrecision.argument a t.val) q).value k hp hkt\n      have lvalid:=read_valid q inverse (k-j) hiv\n      have rvalid:=read_valid q powers k hpv\n      have productCap : Fits (Operation.mul.value left.word.value right.word.value) template.length := by\n        rw [lv,rv]\n        exact product_fits a h u t hq j k hj hkt template.length hprod\n      have pm:=executeOperation_correct .mul left.word right.word template lvalid rvalid productCap\n      have he : Operation.add.value product.word.value old.word.value=\n          (sumWeights j (SemiprimeD1JetRecoveryWeights.acquire a h u t.val).inverse.coefficients\n            (powersRun (SemiprimeD1WeightPrecision.argument a t.val) q).value (k::ks)).value := by\n        rw [pm.1,lv,rv,tail.1]\n        simp only [Operation.value,sumWeights,hj,ite_true]\n        rfl\n      have addCap : Fits (Operation.add.value product.word.value old.word.value) template.length := by\n        rw [he]\n        exact sum_fits a h u t hq j (k::ks) hk hl template.length hW\n      have out:=executeOperation_correct .add product.word old.word template pm.2.1 tail.2.1 addCap\n      simpa only [sum,hj,ite_true] using And.intro (out.1.trans he) out.2\n    · simpa only [sum,sumWeights,hj,ite_false] using tail\n\n/-- Actual physical power cache, retaining every original power loop once. -/\nstructure Cache where\n  /-- The physical power words in original order. -/\n  words : List RationalWord\n  /-- Actual multiplications/GCDs and constructors. -/\n  clock : ℕ\n  /-- Typed finite-index traversal stages, separate from physical arithmetic. -/\n  metadataWork : ℕ\n\n/-- Cache the executed powers on the ACTUAL original finite index list. -/\ndef powers (template : List Bool) (argument : RationalWord) : List ℕ → Cache\n  | [] => ⟨[],1,1⟩\n  | k::ks =>\n    let tail:=powers template argument ks\n    let current:=power template argument k\n    ⟨current.word::tail.words,current.clock+tail.clock+3,tail.metadataWork+3⟩\n\n/-- Original power-cache values, legality and widths have no scalar-power\nanswer or intermediate Fits premise. -/\ntheorem powers_correct (template : List Bool) (a h u : ℕ) (t : Fin (size a))\n    (argument : RationalWord) (ha : argument.value=SemiprimeD1WeightPrecision.argument a t.val)\n    (hav : argument.Valid) (hW : (a+1)*nodeMultiplicity a h u t.val+1 ≤ template.length)\n    (keys : List ℕ) (hk : ∀k∈keys,k ≤ nodeMultiplicity a h u t.val) :\n    (powers template argument keys).words.map RationalWord.value=\n      keys.map (fun k => (rationalPower (SemiprimeD1WeightPrecision.argument a t.val) k).value) ∧\n    (∀x∈(powers template argument keys).words,x.Valid) ∧\n    (∀x∈(powers template argument keys).words,Width x template.length) := by\n  have ht : 0 < template.length := by omega\n  induction keys with\n  | nil => exact ⟨rfl,by simp [powers],by simp [powers]⟩\n  | cons k ks ih =>\n    have old:=ih (fun k h => hk k (List.mem_cons_of_mem _ h))\n    have cur:=argument_correct template argument a h u t k (hk k List.mem_cons_self) ha hav hW\n    have width:=power_width template argument k ht\n    refine ⟨?_,?_,?_⟩\n    · simp only [powers,List.map_cons,cur.1,old.1]\n    · intro x hx\n      simp only [powers,List.mem_cons] at hx\n      rcases hx with rfl|hx\n      · exact cur.2\n      · exact old.2.1 x hx\n    · intro x hx\n      simp only [powers,List.mem_cons] at hx\n      rcases hx with rfl|hx\n      · exact width\n      · exact old.2.2 x hx\n\n/-- The physical cache matches the exact frozen native cached power array. -/\ntheorem powers_original (template : List Bool) (a h u : ℕ) (t : Fin (size a))\n    (argument : RationalWord) (ha : argument.value=SemiprimeD1WeightPrecision.argument a t.val)\n    (hav : argument.Valid) (hW : (a+1)*nodeMultiplicity a h u t.val+1 ≤ template.length) :\n    (powers template argument (indices (nodeMultiplicity a h u t.val)).value).words.map RationalWord.value=\n      (powersRun (SemiprimeD1WeightPrecision.argument a t.val) (nodeMultiplicity a h u t.val)).value.toList := by\n  have hk : ∀k∈(indices (nodeMultiplicity a h u t.val)).value,k ≤ nodeMultiplicity a h u t.val := by\n    simp only [indices_value,List.mem_range]\n    exact fun k h => h.le\n  have h:=powers_correct template a h u t argument ha hav hW _ hk\n  simpa only [powersRun,List.toList_toArray,List.map_map,Function.comp_def] using h.1\n\n/-- Actual power-cache arithmetic reports are retained; no supplied native work cap. -/\ntheorem powers_clock (template : List Bool) (argument : RationalWord) (q : ℕ)\n    (ht : 0 < template.length) (ha : Width argument template.length)\n    (keys : List ℕ) (hk : ∀k∈keys,k ≤ q) :\n    (powers template argument keys).clock ≤\n      keys.length*(q*(20000*(template.length+1)^3+4)+6)+1 := by\n  induction keys with\n  | nil => simp [powers]\n  | cons k ks ih =>\n    have old:=ih (fun k h => hk k (List.mem_cons_of_mem _ h))\n    have cur:=power_clock template argument k ht ha\n    have hp:=Nat.mul_le_mul_right (20000*(template.length+1)^3+4) (hk k List.mem_cons_self)\n    simp only [powers,List.length_cons,Nat.add_mul,Nat.one_mul]\n    omega\n\n/-- Exact native finite-index traversal report of the power cache. -/\ntheorem powers_metadataWork (template : List Bool) (argument : RationalWord) (keys : List ℕ) :\n    (powers template argument keys).metadataWork=3*keys.length+1 := by\n  induction keys with\n  | nil => rfl\n  | cons k ks ih => simp only [powers,List.length_cons,ih]; omega\n\n/-- Physical normalization exposes actual canonical signed numerator and\npositive-denominator words; no native q.num/q.den operation executes. -/\ntheorem operation_components (op : Operation) (x y : RationalWord) (template : List Bool)\n    (hx : x.Valid) (hy : y.Valid) (hcap : Fits (op.value x.value y.value) template.length) :\n    (executeOperation op x y template).word.numerator.value=(op.value x.value y.value).num ∧\n      SemiprimeBitArithmetic.bitValue (executeOperation op x y template).word.denominator=(op.value x.value y.value).den := by\n  have hv:=rawOperation_value op x y hx hy\n  have hn : Fits (rawOperation op x y).word.value template.length := by rw [hv]; exact hcap\n  have h:=fitRationalBits_components (rawOperation op x y).word template hn.1 hn.2\n  simpa only [executeOperation,hv] using h\n\n/-- Literal source-weight normalization capacity, derived from the actual\nright-suffix common denominator and original integer factor heights. -/\ntheorem weight_fits (a h u : ℕ) (t : Fin (size a))\n    (hq : 0 < nodeMultiplicity a h u t.val) (j W : ℕ)\n    (hW : SemiprimeD1HermiteWeightBits.weightExponent a h u t.val < W) :\n    Fits (weightRun (SemiprimeD1JetRecoveryGrid.Ezero a h u t.val) j\n      (SemiprimeD1JetRecoveryWeights.acquire a h u t.val).inverse.coefficients\n      (powersRun (SemiprimeD1WeightPrecision.argument a t.val) (nodeMultiplicity a h u t.val)).value\n      (indices (nodeMultiplicity a h u t.val)).value).value W := by\n  have hb:=weight_suffix_bits a h u t hq j 0\n  simp only [List.drop_zero] at hb\n  have ht : 2^SemiprimeD1HermiteWeightBits.weightExponent a h u t.val < 2^W :=\n    Nat.pow_lt_pow_right (by decide : 1 < (2:ℕ)) hW\n  exact ⟨hb.2.trans_lt ht,hb.1.trans_lt ht⟩\n\n/-- Actual physical local weight and canonical numerator/denominator words\nrefine the original stored coefficient. No native canonical-field extraction\nor intermediate/output Fits oracle is used at this endpoint. -/\ntheorem weight_correct (template : List Bool) (a h u : ℕ) (t : Fin (size a))\n    (j : ℕ) (hj : j < nodeMultiplicity a h u t.val) (scalar : RationalWord)\n    (inverse powers : List RationalWord)\n    (hs : scalar.value=SemiprimeD1JetRecoveryGrid.Ezero a h u t.val) (hsv : scalar.Valid)\n    (hi : inverse.map RationalWord.value=(SemiprimeD1JetRecoveryWeights.acquire a h u t.val).inverse.coefficients.toList)\n    (hp : powers.map RationalWord.value=\n      (powersRun (SemiprimeD1WeightPrecision.argument a t.val) (nodeMultiplicity a h u t.val)).value.toList)\n    (hiv : ∀x∈inverse,x.Valid) (hpv : ∀x∈powers,x.Valid)\n    (hW : sumExponent a h u t.val < template.length)\n    (hWW : SemiprimeD1HermiteWeightBits.weightExponent a h u t.val < template.length) :\n    let out:=weight template (nodeMultiplicity a h u t.val) j scalar inverse powers\n      (indices (nodeMultiplicity a h u t.val)).value\n    let target:=coefficient (SemiprimeD1JetRecoveryWeights.acquire a h u t.val).weights j\n    out.word.value=target ∧ out.word.Valid ∧ Width out.word template.length ∧\n      out.word.numerator.value=target.num ∧ bitValue out.word.denominator=target.den := by\n  dsimp only\n  let q:=nodeMultiplicity a h u t.val\n  let keys:=(indices q).value\n  have hq : 0 < q := by omega\n  have hk : ∀k∈keys,k < q := by simp only [keys,indices_value,List.mem_range]; exact fun k h => h\n  have hlen : keys.length ≤ q := by simp [keys,indices_value]\n  have total:=sum_correct template a h u t hq j inverse powers hi hp hiv hpv hW keys hk hlen\n  have he : Operation.mul.value scalar.value (sum template q j inverse powers keys).word.value=\n      (weightRun (SemiprimeD1JetRecoveryGrid.Ezero a h u t.val) j\n        (SemiprimeD1JetRecoveryWeights.acquire a h u t.val).inverse.coefficients\n        (powersRun (SemiprimeD1WeightPrecision.argument a t.val) q).value keys).value := by\n    rw [hs,total.1]\n    rfl\n  have cap : Fits (Operation.mul.value scalar.value (sum template q j inverse powers keys).word.value) template.length := by\n    rw [he]\n    exact weight_fits a h u t hq j template.length hWW\n  have out:=executeOperation_correct .mul scalar (sum template q j inverse powers keys).word template hsv total.2.1 cap\n  have canonical:=operation_components .mul scalar (sum template q j inverse powers keys).word template hsv total.2.1 cap\n  have native : (weightRun (SemiprimeD1JetRecoveryGrid.Ezero a h u t.val) j\n        (SemiprimeD1JetRecoveryWeights.acquire a h u t.val).inverse.coefficients\n        (powersRun (SemiprimeD1WeightPrecision.argument a t.val) q).value keys).value=\n      coefficient (SemiprimeD1JetRecoveryWeights.acquire a h u t.val).weights j := by\n    rw [weightRun_value]\n    have hn:=SemiprimeD1JetRecoveryWeights.acquire_weight a h u t.val j hj\n    simpa only [SemiprimeD1WeightPrecision.argument,Int.cast_neg,Int.cast_pow,Int.cast_ofNat] using hn.symm\n  have equal:=he.trans native\n  exact ⟨out.1.trans equal,out.2.1,out.2.2,by simpa only [weight,equal] using canonical.1,\n    by simpa only [weight,equal] using canonical.2⟩\n\n/-- Every scalar-sum output has bounded physical width even before semantics. -/\ntheorem sum_width (template : List Bool) (q j : ℕ) (inverse powers : List RationalWord)\n    (keys : List ℕ) (ht : 0 < template.length) : Width (sum template q j inverse powers keys).word template.length := by\n  induction keys with\n  | nil => exact ⟨by simp [sum,SemiprimeRationalBits.zeroWord],by change 1 ≤ template.length; omega⟩\n  | cons k ks ih =>\n    simp only [sum]\n    split_ifs\n    · exact operation_width _ _ _ _\n    · exact ih\n\n/-- The exact physical memory/normalization budget for one retained-index visit. -/\ndef sumStepBudget (W q A : ℕ) : ℕ := 2*((A+1)*(8*W+15*(q+1)+30))+40000*(W+1)^3+10\n\n/-- Every actual coefficient scan and normalized multiply/add is retained.\nOnly actual physical cache lengths/widths are required, not a work oracle. -/\ntheorem sum_clock (template : List Bool) (q j : ℕ) (inverse powers : List RationalWord)\n    (keys : List ℕ) (ht : 0 < template.length) (A : ℕ)\n    (hi : inverse.length ≤ A) (hp : powers.length ≤ A)\n    (hiw : ∀x∈inverse,Width x template.length) (hpw : ∀x∈powers,Width x template.length) :\n    (sum template q j inverse powers keys).clock ≤ keys.length*sumStepBudget template.length q A+3 := by\n  induction keys with\n  | nil => simp [sum]\n  | cons k ks ih =>\n    by_cases hj : j ≤ k\n    · let old:=sum template q j inverse powers ks\n      let left:=read q inverse (k-j)\n      let right:=read q powers k\n      let product:=executeOperation .mul left.word right.word template\n      have lw:=read_width q inverse (k-j) template.length ht hiw\n      have rw:=read_width q powers k template.length ht hpw\n      have pw:=operation_width .mul left.word right.word template\n      have ow:=sum_width template q j inverse powers ks ht\n      have cl:=read_clock q inverse (k-j) template.length hiw\n      have cr:=read_clock q powers k template.length hpw\n      have cm:=executeOperation_cost .mul left.word right.word template lw rw le_rfl\n      have ca:=executeOperation_cost .add product.word old.word template pw ow le_rfl\n      have clb : (inverse.length+1)*(8*template.length+15*(q+1)+30) ≤\n          (A+1)*(8*template.length+15*(q+1)+30) := Nat.mul_le_mul_right _ (by omega)\n      have crb : (powers.length+1)*(8*template.length+15*(q+1)+30) ≤\n          (A+1)*(8*template.length+15*(q+1)+30) := Nat.mul_le_mul_right _ (by omega)\n      simp only [sum,hj,ite_true,List.length_cons,Nat.add_mul,Nat.one_mul]\n      unfold sumStepBudget at *\n      dsimp only [old,left,right,product] at *\n      omega\n    · simp only [sum,hj,ite_false,List.length_cons,Nat.add_mul,Nat.one_mul]\n      have hb : 3 ≤ sumStepBudget template.length q A := by unfold sumStepBudget; omega\n      omega\n\n/-- Every native address-generation stage is retained for the actual scalar sum. -/\ntheorem sum_metadataWork (template : List Bool) (q j : ℕ) (inverse powers : List RationalWord)\n    (keys : List ℕ) :\n    (sum template q j inverse powers keys).metadataWork ≤ keys.length*(8*(q+1)+12)+1 := by\n  induction keys with\n  | nil => simp [sum]\n  | cons k ks ih =>\n    simp only [sum]\n    split_ifs <;> dsimp only\n    · simp only [read_metadataWork,List.length_cons,Nat.add_mul,Nat.one_mul]\n      omega\n    · simp only [List.length_cons,Nat.add_mul,Nat.one_mul]\n      omega\n\n/-- Full physical local-weight clock including the final real normalization. -/\ntheorem weight_clock (template : List Bool) (q j : ℕ) (scalar : RationalWord)\n    (inverse powers : List RationalWord) (keys : List ℕ) (ht : 0 < template.length) (A : ℕ)\n    (hi : inverse.length ≤ A) (hp : powers.length ≤ A)\n    (hiw : ∀x∈inverse,Width x template.length) (hpw : ∀x∈powers,Width x template.length)\n    (hs : Width scalar template.length) :\n    (weight template q j scalar inverse powers keys).clock ≤\n      keys.length*sumStepBudget template.length q A+20000*(template.length+1)^3+6 := by\n  have hsum:=sum_clock template q j inverse powers keys ht A hi hp hiw hpw\n  have hw:=sum_width template q j inverse powers keys ht\n  have hout:=executeOperation_cost .mul scalar (sum template q j inverse powers keys).word template hs hw le_rfl\n  simp only [weight]\n  omega\n\nend RiemannGaussian.SemiprimeD1RecoveryScalarWeightBits\n","RiemannGaussian.SemiprimeD1RecoveryWeightRun":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1RecoveryScalarRun\n\n/-! # Actual original-grid scalar weight producer with retained native loops\nEvery scalar, slope, inverse packet and canonical integer row is acquired from\noriginal grid parameters. Native rational normalization is an explicit scalar\nboundary, not a unit physical-bit operation or a supplied coefficient answer.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeD1RecoveryWeightRun\nopen scoped BigOperators\nopen SemiprimeD1RecoveryScalarRun SemiprimeD1WireKernelOriginal\n  SemiprimeD1TaperedLoss SemiprimeD1JetRecoveryGrid SemiprimeD1JetRecoveryWeights\n  SemiprimeJetArray SemiprimeD1JetRecoveryScalarHeight\n\n/-- Cached original grid geometry, acquired by actual repeated integer powers. -/\nstructure Geometry where\n  /-- Actual2L grid size. -/\n  size : ℕ\n  /-- Actual grid centre as a signed integer. -/\n  center : ℤ\n  /-- Actual supplied node's signed grid point. -/\n  point : ℤ\n  /-- Actual alpha=2L, acquired once. -/\n  alpha : ℤ\n  /-- All original native power/point arithmetic retained. -/\n  work : ℕ\n\n/-- Original grid geometry from a and the actual node index, never supplied scalar values. -/\ndef geometry (a t : ℕ) : Geometry :=\n  let center:=intPower 2 a\n  let alpha:=center.value*2\n  ⟨alpha.natAbs,center.value,(t:ℤ)-center.value,alpha,center.work+7⟩\n\n/-- Actual acquired centre is the original signed grid centre. -/\ntheorem geometry_center (a t : ℕ) : (geometry a t).center=(center a:ℤ) := by\n  simp [geometry,intPower_value,center]\n\n/-- Actual acquired centre index is the original nonnegative centre. -/\ntheorem geometry_center_abs (a t : ℕ) : (geometry a t).center.natAbs=center a := by\n  rw [geometry_center]\n  simp\n\n/-- Actual acquired grid size is the original2L. -/\ntheorem geometry_size (a t : ℕ) : (geometry a t).size=size a := by\n  simp [geometry,intPower_value,size,pow_succ,Int.natAbs_mul,Int.natAbs_pow]\n\n/-- The original local point is acquired by actual signed subtraction. -/\ntheorem geometry_point (a t : ℕ) : (geometry a t).point=point a t := by\n  simp [geometry,intPower_value,point,center]\n\n/-- The actual acquired alpha equals the original source scalar. -/\ntheorem geometry_alpha (a t : ℕ) : (geometry a t).alpha=(2:ℤ)^(a+1) := by\n  simp only [geometry,intPower_value,pow_succ]\n\n/-- Compute ORIGINAL multiplicity by explicit bounded dyadic modulo/division steps. -/\ndef multiplicityRun (g : Geometry) (h u q : ℕ) : Run ℕ :=\n  let order:=orderFuel g.size ((q:ℤ)-g.center).natAbs\n  ⟨h*(u-order.value),order.work+5⟩\n\n/-- Actual original multiplicity is derived, not supplied as a valuation/count answer. -/\ntheorem multiplicityRun_value (a h u t q : ℕ) (hq : q<size a) :\n    (multiplicityRun (geometry a t) h u q).value=nodeMultiplicity a h u q := by\n  have hp : ((q:ℤ)-(geometry a t).center).natAbs≤(geometry a t).size := by\n    rw [geometry_center,geometry_size]\n    exact (point_abs_lt a q hq).le\n  have hv : padicValNat 2 ((q:ℤ)-(geometry a t).center).natAbs≤(geometry a t).size :=\n    (Nat.padicValNat_le_self _).trans hp\n  dsimp only [multiplicityRun]\n  rw [orderFuel_value _ _ (Or.inr hv)]\n  simp only [geometry_center,nodeMultiplicity,SemiprimeD1TaperedLoss.multiplicity,padicValInt,point]\n\n/-- Actual grid products, slope list and every retained native operation/cell report. -/\nstructure GridReport where\n  /-- Signed original Ezero numerator product. -/\n  numerator : ℤ\n  /-- Signed original nonzero Ezero denominator product. -/\n  denominator : ℤ\n  /-- Original ordered slopes repeated by acquired multiplicities. -/\n  slopes : List ℚ\n  /-- All grid visits, powers, integer products, rational normalizations and copied cells. -/\n  work : ℕ\n\n/-- Traverse the ACTUAL acquired grid, caching each multiplicity and slope once. -/\ndef gridRows (g : Geometry) (h u t : ℕ) : List ℕ → GridReport\n  | [] => ⟨1,1,[],1⟩\n  | q::qs =>\n    let tail:=gridRows g h u t qs\n    if q=g.center.natAbs ∨ q=t then\n      ⟨tail.numerator,tail.denominator,tail.slopes,tail.work+4⟩\n    else\n      let m:=multiplicityRun g h u q\n      let x:=(q:ℤ)-g.center\n      let d:=g.point-x\n      let numerator:=intPower (-x) m.value\n      let denominator:=intPower d m.value\n      let slope:ℚ:=(g.alpha:ℚ)/(d:ℚ)\n      let copies:=replicateRun m.value slope\n      ⟨numerator.value*tail.numerator,denominator.value*tail.denominator,\n        copies.value++tail.slopes,\n        tail.work+m.work+numerator.work+denominator.work+copies.work+2*copies.value.length+15⟩\n\n/-- The original numerator grid fold is the literal finite integer product. -/\ntheorem gridRows_numerator (a h u t : ℕ) (qs : List ℕ) (hq : ∀q∈qs,q<size a) :\n    (gridRows (geometry a t) h u t qs).numerator=\n      (qs.map fun q => if q=center a ∨ q=t then 1 else (-point a q)^nodeMultiplicity a h u q).prod := by\n  induction qs with\n  | nil => rfl\n  | cons q qs ih =>\n    have hm:=multiplicityRun_value a h u t q (hq q List.mem_cons_self)\n    have hi:=ih (fun q h => hq q (List.mem_cons_of_mem _ h))\n    by_cases hs : q=center a ∨ q=t\n    · simp only [gridRows,geometry_center_abs,hs,ite_true,List.map_cons,List.prod_cons,one_mul,hi]\n    · simp only [gridRows,hs,ite_false,List.map_cons,List.prod_cons,\n        intPower_value,hm,geometry_center,Int.natAbs_natCast,point,hi]\n\n/-- The original denominator grid fold is the literal signed node-difference product. -/\ntheorem gridRows_denominator (a h u t : ℕ) (qs : List ℕ) (hq : ∀q∈qs,q<size a) :\n    (gridRows (geometry a t) h u t qs).denominator=\n      (qs.map fun q => if q=center a ∨ q=t then 1 else\n        (point a t-point a q)^nodeMultiplicity a h u q).prod := by\n  induction qs with\n  | nil => rfl\n  | cons q qs ih =>\n    have hm:=multiplicityRun_value a h u t q (hq q List.mem_cons_self)\n    have hi:=ih (fun q h => hq q (List.mem_cons_of_mem _ h))\n    by_cases hs : q=center a ∨ q=t\n    · simp only [gridRows,geometry_center_abs,hs,ite_true,List.map_cons,List.prod_cons,one_mul,hi]\n    · simp only [gridRows,hs,ite_false,List.map_cons,List.prod_cons,\n        intPower_value,hm,geometry_center,Int.natAbs_natCast,geometry_point,point,hi]\n\n/-- The actual acquired grid folds yield the exact original slope ordering. -/\ntheorem gridRows_slopes (a h u t : ℕ) (qs : List ℕ) (hq : ∀q∈qs,q<size a) :\n    (gridRows (geometry a t) h u t qs).slopes=\n      qs.flatMap (fun q => if q=center a ∨ q=t then [] else List.replicate (nodeMultiplicity a h u q)\n        (((2:ℤ)^(a+1):ℚ)/((point a t:ℚ)-(point a q:ℚ)))) := by\n  induction qs with\n  | nil => rfl\n  | cons q qs ih =>\n    have hm:=multiplicityRun_value a h u t q (hq q List.mem_cons_self)\n    have hi:=ih (fun q h => hq q (List.mem_cons_of_mem _ h))\n    by_cases hs : q=center a ∨ q=t\n    · simp only [gridRows,geometry_center_abs,hs,ite_true,List.flatMap_cons,List.nil_append,hi]\n    · simp only [gridRows,hs,ite_false,List.flatMap_cons,repeat_value,hm,\n        geometry_point,geometry_center,Int.natAbs_natCast,geometry_alpha,point,Int.cast_sub,Int.cast_pow,Int.cast_ofNat,hi]\n\n/-- The literal masked grid product is exactly the original omitted-node product. -/\ntheorem original_product {K : Type*} [CommMonoid K] (a t : ℕ) (f : ℕ→K) :\n    ((List.range (size a)).map fun q => if q=center a ∨ q=t then 1 else f q).prod=\n      ∏q∈others a t,f q := by\n  classical\n  rw [← List.prod_toFinset _ List.nodup_range,List.toFinset_range]\n  have hs : others a t=(Finset.range (size a)).filter (fun q => ¬(q=center a ∨ q=t)) := by\n    ext q\n    simp only [others,Finset.mem_erase,Finset.mem_range,Finset.mem_filter]\n    tauto\n  rw [hs,Finset.prod_filter]\n  apply Finset.prod_congr rfl\n  intro q _\n  by_cases h : q=center a ∨ q=t <;> simp only [h,not_true_eq_false,not_false_eq_true,ite_true,ite_false]\n\n/-- ACTUAL original-grid numerator acquisition, including signs and inactive multiplicities. -/\ntheorem fullGrid_numerator (a h u t : ℕ) :\n    (gridRows (geometry a t) h u t (indices (geometry a t).size).value).numerator=\n      SemiprimeD1JetRecoveryScalarHeight.numerator a h u t := by\n  rw [geometry_size,indices_value,gridRows_numerator a h u t _ (fun q h => List.mem_range.mp h)]\n  exact original_product a t _\n\n/-- ACTUAL original-grid denominator acquisition, without a supplied clearing scalar. -/\ntheorem fullGrid_denominator (a h u t : ℕ) :\n    (gridRows (geometry a t) h u t (indices (geometry a t).size).value).denominator=\n      SemiprimeD1JetRecoveryScalarHeight.denominator a h u t := by\n  rw [geometry_size,indices_value,gridRows_denominator a h u t _ (fun q h => List.mem_range.mp h)]\n  exact original_product a t _\n\n/-- ACTUAL original slope acquisition in precisely the frozen constructor's order. -/\ntheorem fullGrid_slopes (a h u t : ℕ) :\n    (gridRows (geometry a t) h u t (indices (geometry a t).size).value).slopes=slopes a h u t := by\n  rw [geometry_size,indices_value,gridRows_slopes a h u t _ (fun q h => List.mem_range.mp h)]\n  rfl\n\n/-- Cache actual scalar powers once for each retained coefficient index. -/\ndef powersRun (x : ℚ) (q : ℕ) : Run (Array ℚ) :=\n  let keys:=indices q\n  let reports:=keys.value.map (rationalPower x)\n  ⟨(reports.map (fun r => r.value)).toArray,\n    keys.work+(reports.map (fun r => r.work)).sum+4*keys.value.length+3⟩\n\n/-- Every cached power is the actual original scalar power. -/\ntheorem powersRun_coefficient (x : ℚ) (q k : ℕ) (hk : k<q) :\n    coefficient (powersRun x q).value k=x^k := by\n  simp [powersRun,indices_value,coefficient,hk,rationalPower_value]\n\n/-- Explicit right-recursive local coefficient sum with retained reads and normalizations. -/\ndef sumWeights (j : ℕ) (inv powers : Array ℚ) : List ℕ → Run ℚ\n  | [] => ⟨0,1⟩\n  | k::ks =>\n    let tail:=sumWeights j inv powers ks\n    if j≤k then\n      let term:=coefficient inv (k-j)*coefficient powers k\n      ⟨term+tail.value,tail.work+7⟩\n    else ⟨tail.value,tail.work+3⟩\n\n/-- The executed scalar suffix sum has its actual literal list meaning. -/\ntheorem sumWeights_value (j : ℕ) (inv powers : Array ℚ) (ks : List ℕ) :\n    (sumWeights j inv powers ks).value=\n      (ks.map fun k => if j≤k then coefficient inv (k-j)*coefficient powers k else 0).sum := by\n  induction ks with\n  | nil => rfl\n  | cons k ks ih =>\n    by_cases h : j≤k <;> simp only [sumWeights,h,ite_true,ite_false,List.map_cons,List.sum_cons,zero_add,ih]\n\n/-- One actual weight, retaining every suffix/read and the final Ezero multiplication. -/\ndef weightRun (E : ℚ) (j : ℕ) (inv powers : Array ℚ) (keys : List ℕ) : Run ℚ :=\n  let total:=sumWeights j inv powers keys\n  ⟨E*total.value,total.work+3⟩\n\n/-- Explicit acquired scalar loops compute EXACTLY the original finite localWeight. -/\ntheorem weightRun_value (q j : ℕ) (E x : ℚ) (inv : Array ℚ) :\n    (weightRun E j inv (powersRun x q).value (indices q).value).value=localWeight q E x inv j := by\n  simp only [weightRun,sumWeights_value,indices_value,localWeight]\n  congr 1\n  rw [← List.sum_toFinset _ List.nodup_range,List.toFinset_range]\n  apply Finset.sum_congr rfl\n  intro k hk\n  by_cases h : j≤k\n  · simp only [h,ite_true,powersRun_coefficient x q k (Finset.mem_range.mp hk)]\n  · simp only [h,ite_false]\n\n/-- Actual canonical integer data extracted ONCE from an already acquired scalar. -/\nstructure CanonicalRow where\n  /-- Actual canonical signed numerator. -/\n  numerator : ℤ\n  /-- Actual canonical positive denominator. -/\n  denominator : ℕ\n  deriving Repr\n\n/-- Traverse actual scalar reports, retaining their work and canonical field accesses. -/\ndef canonicalRows : List (Run ℚ) → Run (List CanonicalRow)\n  | [] => ⟨[],1⟩\n  | r::rs =>\n    let tail:=canonicalRows rs\n    ⟨⟨r.value.num,r.value.den⟩::tail.value,r.work+tail.work+4⟩\n\n/-- Canonical-row acquisition uses the actual computed values, never supplied Int rows. -/\ntheorem canonicalRows_value (rs : List (Run ℚ)) :\n    (canonicalRows rs).value=rs.map (fun r => CanonicalRow.mk r.value.num r.value.den) := by\n  induction rs with\n  | nil => rfl\n  | cons r rs ih => simp only [canonicalRows,List.map_cons,ih]\n\n/-- All original scalar/packet data, cached canonical Int rows and their retained acquisition report. -/\nstructure NodeReport where\n  /-- Actual acquired original weight data. -/\n  data : WeightData\n  /-- Canonical numerator/denominator rows, cached once. -/\n  rows : List CanonicalRow\n  /-- ALL executed native scalar, array, index and list stages retained. -/\n  work : ℕ\n\n/-- Full node producer from ORIGINAL a,M,u,t. No slopes, Ezero, coefficient,\ninverse, canonical integer row, height or operation-count answer is supplied. -/\ndef acquire (a M u : ℕ) (t : Fin (size a)) : NodeReport :=\n  let h:=height M u\n  let g:=geometry a t.val\n  let gridKeys:=indices g.size\n  let grid:=gridRows g h u t.val gridKeys.value\n  let multiplicity:=multiplicityRun g h u t.val\n  let q:=multiplicity.value\n  let E:ℚ:=(grid.numerator:ℚ)/(grid.denominator:ℚ)\n  let x:ℚ:=-(g.point:ℚ)/(g.alpha:ℚ)\n  let denominator:=SemiprimeHermiteArrayHeight.buildAffine q grid.slopes\n  let inverse:=SemiprimeJetArray.inverse denominator.coefficients q\n  let keys:=indices q\n  let powers:=powersRun x q\n  let reports:=keys.value.map (fun j => weightRun E j inverse.coefficients powers.value keys.value)\n  let canonical:=canonicalRows reports\n  ⟨⟨q,E,x,denominator,inverse,(reports.map (fun r => r.value)).toArray⟩,canonical.value,\n    g.work+gridKeys.work+grid.work+multiplicity.work+denominator.arithmetic+denominator.reads+\n      inverse.arithmetic+inverse.reads+keys.work+powers.work+canonical.work+4*keys.value.length+20⟩\n\n/-- Actual scalar report values form the ORIGINAL stored weight array. -/\ntheorem weight_array (q : ℕ) (E x : ℚ) (inv : Array ℚ) :\n    (((indices q).value.map (fun j => weightRun E j inv (powersRun x q).value (indices q).value)).map\n      (fun r => r.value)).toArray=\n      Array.ofFn (fun j : Fin q => localWeight q E x inv j.val) := by\n  simp only [List.map_map,Function.comp_def,indices_value]\n  apply Array.ext\n  · simp\n  · intro j hj hj'\n    simp only [List.getElem_toArray,List.getElem_map,List.getElem_range,Array.getElem_ofFn]\n    simpa only [indices_value] using weightRun_value q j E x inv\n\n/-- Full original-input producer refines the FROZEN actual weight constructor,\nincluding acquired denominator/inverse arrays and their retained reports. -/\ntheorem acquire_data (a M u : ℕ) (t : Fin (size a)) :\n    (acquire a M u t).data=SemiprimeD1JetRecoveryWeights.acquire a (height M u) u t.val := by\n  simp only [acquire,fullGrid_numerator,fullGrid_denominator,fullGrid_slopes,\n    multiplicityRun_value a (height M u) u t.val t.val t.isLt,geometry_point,geometry_alpha,\n    ← ratio_spec,weight_array,SemiprimeD1JetRecoveryWeights.acquire]\n  simp only [Int.cast_pow,Int.cast_ofNat]\n\n/-- Canonical numerators/denominators are extracted from ACTUAL producer values once. -/\ntheorem acquire_rows (a M u : ℕ) (t : Fin (size a)) :\n    (acquire a M u t).rows=(acquire a M u t).data.weights.toList.map\n      (fun q => CanonicalRow.mk q.num q.den) := by\n  simp only [acquire,canonicalRows_value,List.toList_toArray,List.map_map,Function.comp_def]\n\n/-- Cached canonical integer rows agree EXACTLY with the original acquired scalar rows. -/\ntheorem acquire_original_rows (a M u : ℕ) (t : Fin (size a)) :\n    (acquire a M u t).rows=(SemiprimeD1JetRecoveryWeights.acquire a (height M u) u t.val).weights.toList.map\n      (fun q => CanonicalRow.mk q.num q.den) := by\n  rw [acquire_rows,acquire_data]\n\nend RiemannGaussian.SemiprimeD1RecoveryWeightRun\n","RiemannGaussian.SemiprimeD1RecursivePhaseCorrectness":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1RecursiveRecoveryRun\nimport RiemannGaussian.SemiprimeD1JetBlockPolynomial\n\n/-! # Concrete phase composition from the acquired network query\nThe continuation premise is an induction hypothesis on actual constructed\nchildren. The other premise is the precise original-network query identity;\nthere is no supplied block, coefficient, width or entry answer.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 50000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1RecursivePhaseCorrectness\nopen scoped BigOperators\nopen SemiprimeD1JetAxes SemiprimeD1TensorNetwork SemiprimeD1RecursiveCounter\nopen SemiprimeD1JetInterpretation SemiprimeD1JetAffineCoefficient\nopen SemiprimeD1WireKernelOriginal SemiprimeD1HermiteNodes SemiprimeD1JetRecoveryGrid\nopen SemiprimeD1RecursivePhaseControl SemiprimeD1RecursiveRecovery\nattribute [local irreducible] SemiprimeD1OriginalModeAcquisition.acquire\n\n/-- Correctness required only of the structurally smaller continuation. -/\ndef NextCorrect (next : Context → Network → JetRun) : Prop :=\n  ∀ ctx net, ctx.Positive → WellFormed net → Good ctx net →\n    interpret ctx (next ctx net).words = interpret ctx (leaf ctx net).words\n\n/-- Actual retained-node valuation index, with its bound derived from the grid. -/\ndef phaseIndex (net : Network) (a u : ℕ) (t : Fin (size a)) (hua : u ≤ a)\n    (ht : t.val ∈ active a (SemiprimeD1TaperedLoss.height (edgeCount net) u) u) : Fin a :=\n  ⟨_,(active_guard net a u t hua ht).1⟩\n\n/-- Erased view of the exact inner product/sum component in `phase`. Its\ncomponent clock is not asserted to include the surrounding source acquisition. -/\ndef phaseTotal (next : Context → Network → JetRun) (ctx : Context) (net : Network)\n    (a u : ℕ) (t : Fin (size a)) (i : Fin a) : JetRun :=\n  let source := SemiprimeD1OriginalModeAcquisition.acquire net.leftCount net.rows.length 64\n    a u i.val ctx.precision (arity net.rows) (owner net.rows)\n  let q := SemiprimeD1ModeRate.jetHeight (edgeCount net) u * (u-i.val)\n  let fresh := SemiprimeD1FreshJetBits.acquireFresh ctx q source.precision\n  let current : Context := ⟨q::ctx.axes,source.precision⟩\n  sumRuns current (source.modes.values.map (fun beta =>\n    product current ((List.finRange 64).map (fun g =>\n      let child := SemiprimeD1ChildNetwork.fromSource net source i g\n        ctx [q] source.precision fresh t beta\n      let answer := next current child.network\n      (⟨answer.words,child.clock+answer.clock+5⟩ : JetRun)))))\n\n/-- A generic type barrier keeps actual source acquisition out of ring-instance\nunification. This is an erased equality, not an acquired entry interface. -/\ndef queryEquation (ctx : Context) (q p : ℕ)\n    (F : Polynomial (Carrier ⟨ctx.axes,p⟩))\n    (words : List (List Bool))\n    (rhs : Carrier ⟨q::ctx.axes,p⟩) : Prop :=\n  F.eval₂ (SemiprimeD1JetBlockPolynomial.actualEmbedding ctx q p)\n    (interpret ⟨q::ctx.axes,p⟩ words) = rhs\n\n/-- Generic equality composition and block extraction keep concrete source\nprograms out of ring-instance inference. -/\ntheorem extract_of_query (ctx : Context) (q p j : ℕ) (input : JetRun)\n    (hpos : ctx.Positive) (hj : j < q) (F : Polynomial (Carrier ⟨ctx.axes,p⟩))\n    (rhs : Carrier ⟨q::ctx.axes,p⟩)\n    (htotal : interpret ⟨q::ctx.axes,p⟩ input.words = rhs)\n    (hquery : queryEquation ctx q p F\n      (SemiprimeD1FreshJetBits.acquireFresh ctx q p).words rhs) :\n    interpret ⟨ctx.axes,p⟩ (SemiprimeD1JetBlockBits.extractRun ctx j input).words = F.coeff j := by\n  exact SemiprimeD1JetBlockPolynomial.extractRun_polynomial ctx q p j input hpos hj F\n    (htotal.trans hquery.symm)\n\n/-- The original integral polynomial reduced at an explicit scalar precision.\nKeeping the precision abstract prevents executable acquisition during elaboration. -/\nnoncomputable def reducedPolynomial (ctx : Context) (net : Network) (a : ℕ)\n    (t : Fin (size a)) (p : ℕ) : Polynomial (Carrier ⟨ctx.axes,p⟩) :=\n  (SemiprimeD1NetworkIntegralDeformation.networkPolynomial ctx.axes\n    net.leftCount net.rows.length 64 a (arity net.rows) (owner net.rows)\n    t net.left.toList net.right.toList).map\n      (SemiprimeD1JetScalarMap.scalarMap (SemiprimeD1JetBoxIndex.dims ctx.axes)\n        (SemiprimeD1DyadicInteger.reduction p))\n\n/-- Erased finite sum of actual child leaf values, at an explicit context. -/\nnoncomputable def leafSum (net : Network) {a : ℕ} (source : SemiprimeD1ChildNetwork.Source net a)\n    (i : Fin a) (ctx : Context) (q p : ℕ) (fresh : SemiprimeD1JetRingBits.Run)\n    (t : Fin (size a)) : Carrier ⟨q::ctx.axes,p⟩ :=\n  (source.modes.values.map (fun beta => ∏ g : Fin 64, interpret ⟨q::ctx.axes,p⟩\n    (leaf ⟨q::ctx.axes,p⟩ (SemiprimeD1ChildNetwork.fromSource net source i g\n      ctx [q] p fresh t beta).network).words)).sum\n\n/-- The exact query identity needed at one actual node. Every polynomial,\nmode, child network and fresh word is constructed from the original input. -/\ndef QueryAt (ctx : Context) (net : Network) (a u : ℕ) (t : Fin (size a)) (i : Fin a) : Prop :=\n  let source := SemiprimeD1OriginalModeAcquisition.acquire net.leftCount net.rows.length 64\n    a u i.val ctx.precision (arity net.rows) (owner net.rows)\n  let q := SemiprimeD1ModeRate.jetHeight (edgeCount net) u * (u-i.val)\n  let fresh := SemiprimeD1FreshJetBits.acquireFresh ctx q source.precision\n  let F := reducedPolynomial ctx net a t source.precision\n  queryEquation ctx q source.precision F fresh.words\n    (leafSum net source i ctx q source.precision fresh t)\n\n/-- Actual cached products and sums inherit the continuation's child correctness. -/\ntheorem phaseTotal_value (next : Context → Network → JetRun) (ctx : Context)\n    (net : Network) (a u : ℕ) (t : Fin (size a)) (i : Fin a)\n    (hnext : NextCorrect next) (hg : Good ctx net)\n    (hpos : (⟨(SemiprimeD1ModeRate.jetHeight (edgeCount net) u * (u-i.val))::ctx.axes,\n      (SemiprimeD1OriginalModeAcquisition.acquire net.leftCount net.rows.length 64\n        a u i.val ctx.precision (arity net.rows) (owner net.rows)).precision⟩ : Context).Positive) :\n    let source := SemiprimeD1OriginalModeAcquisition.acquire net.leftCount net.rows.length 64\n      a u i.val ctx.precision (arity net.rows) (owner net.rows)\n    let q := SemiprimeD1ModeRate.jetHeight (edgeCount net) u * (u-i.val)\n    let current : Context := ⟨q::ctx.axes,source.precision⟩\n    let fresh := SemiprimeD1FreshJetBits.acquireFresh ctx q source.precision\n    interpret current (phaseTotal next ctx net a u t i).words =\n      (source.modes.values.map (fun beta => ∏ g : Fin 64, interpret current\n        (leaf current (SemiprimeD1ChildNetwork.fromSource net source i g\n          ctx [q] source.precision fresh t beta).network).words)).sum := by\n  dsimp only\n  unfold phaseTotal\n  rw [sumRuns_value _ _ hpos]\n  simp only [List.map_map,Function.comp_def]\n  apply congrArg List.sum\n  apply List.map_congr_left\n  intro beta _\n  rw [product_value _ hpos]\n  simp only [List.map_map,Function.comp_def]\n  have hq : 0 < SemiprimeD1ModeRate.jetHeight (edgeCount net) u * (u-i.val) :=\n    hpos _ (List.mem_cons_self ..)\n  let source := SemiprimeD1OriginalModeAcquisition.acquire net.leftCount net.rows.length 64\n    a u i.val ctx.precision (arity net.rows) (owner net.rows)\n  let q := SemiprimeD1ModeRate.jetHeight (edgeCount net) u * (u-i.val)\n  let fresh := SemiprimeD1FreshJetBits.acquireFresh ctx q source.precision\n  have hchild := fun g : Fin 64 => hnext _ _ hpos\n    (SemiprimeD1ChildNetwork.fromSource_wellFormed net source i g ctx [q] source.precision fresh t beta)\n    (SemiprimeD1ChildNetwork.fromSource_good net source i g ctx [q] source.precision fresh t beta hg\n      (by simpa only [List.prod_cons,List.prod_nil,mul_one] using hq))\n  rw [← List.ofFn_eq_map,List.prod_ofFn]\n  apply Finset.prod_congr rfl\n  intro g _\n  exact hchild g\n\n/-- A retained phase uses the actual original multiplicity as its fresh axis. -/\ntheorem phaseIndex_multiplicity (net : Network) (a u : ℕ) (t : Fin (size a))\n    (hua : u ≤ a)\n    (ht : t.val ∈ active a (SemiprimeD1TaperedLoss.height (edgeCount net) u) u) :\n    SemiprimeD1ModeRate.jetHeight (edgeCount net) u *\n      (u-(phaseIndex net a u t hua ht).val) =\n      nodeMultiplicity a (SemiprimeD1TaperedLoss.height (edgeCount net) u) u t.val := by\n  dsimp only [phaseIndex]\n  rw [order_value]\n  rfl\n\n/-- Literal array lookup in the actually constructed ascending block list. -/\ntheorem blocks_read (ctx : Context) (q j : ℕ) (words : List (List Bool)) (hj : j < q) :\n    ((((List.range q).map (fun k => SemiprimeD1JetBlockBits.extract ctx k words)).map\n      (fun block => block.words)).toArray[j]?).getD [] =\n      (SemiprimeD1JetBlockBits.extract ctx j words).words := by\n  simp [List.map_map,Function.comp_def,hj]\n\n/-- The exact controller phase stores the exact extraction of its cached total. -/\ntheorem phase_block (next : Context → Network → JetRun) (ctx : Context) (net : Network)\n    (a u : ℕ) (t : Fin (size a)) (hua : u ≤ a)\n    (ht : t.val ∈ active a (SemiprimeD1TaperedLoss.height (edgeCount net) u) u)\n    (j : ℕ) (hj : j < nodeMultiplicity a (SemiprimeD1TaperedLoss.height (edgeCount net) u) u t.val) :\n    ((phase next ctx net a u t).blocks[j]?).getD [] =\n      (SemiprimeD1JetBlockBits.extract ctx j\n        (phaseTotal next ctx net a u t (phaseIndex net a u t hua ht)).words).words := by\n  have hg := active_guard net a u t hua ht\n  dsimp only at hg\n  have hj' := hj\n  rw [← phaseIndex_multiplicity net a u t hua ht] at hj'\n  dsimp only [phase]\n  rw [dite_eq_left hg]\n  exact blocks_read ctx _ j _ hj'\n\n/-- The phase's actual stored precision is the actual acquired source precision. -/\ntheorem phase_precision (next : Context → Network → JetRun) (ctx : Context) (net : Network)\n    (a u : ℕ) (t : Fin (size a)) (hua : u ≤ a)\n    (ht : t.val ∈ active a (SemiprimeD1TaperedLoss.height (edgeCount net) u) u) :\n    (phase next ctx net a u t).precision =\n      (SemiprimeD1OriginalModeAcquisition.acquire net.leftCount net.rows.length 64\n        a u (phaseIndex net a u t hua ht).val ctx.precision (arity net.rows) (owner net.rows)).precision := by\n  have hg := active_guard net a u t hua ht\n  dsimp only at hg\n  dsimp only [phase]\n  rw [dite_eq_left hg]\n  rfl\n\n/-- Concrete network query semantics and correctness of actual children suffice\nfor every retained block postcondition needed by the original D.5 recovery. -/\ntheorem phaseCorrect_of_query (next : Context → Network → JetRun) (ctx : Context)\n    (net : Network) (a u : ℕ) (hpos : ctx.Positive) (hg : Good ctx net)\n    (hua : u ≤ a) (hnext : NextCorrect next)\n    (hquery : ∀ t : Fin (size a), ∀ ht : t.val ∈\n      active a (SemiprimeD1TaperedLoss.height (edgeCount net) u) u,\n      QueryAt ctx net a u t (phaseIndex net a u t hua ht)) :\n    PhaseCorrect next ctx net a u := by\n  intro t ht j hj\n  let i := phaseIndex net a u t hua ht\n  let source := SemiprimeD1OriginalModeAcquisition.acquire net.leftCount net.rows.length 64\n    a u i.val ctx.precision (arity net.rows) (owner net.rows)\n  let q := SemiprimeD1ModeRate.jetHeight (edgeCount net) u * (u-i.val)\n  let current : Context := ⟨q::ctx.axes,source.precision⟩\n  have hc : current.Positive := active_context_positive ctx net a u t hpos ht\n  have hjq : j < q := by\n    dsimp only [q,i]\n    rw [phaseIndex_multiplicity]\n    exact hj\n  have htotal := phaseTotal_value next ctx net a u t i hnext hg hc\n  let F := reducedPolynomial ctx net a t source.precision\n  have hquery' := hquery t ht\n  dsimp only [QueryAt,leafSum] at hquery'\n  have he := extract_of_query ctx q source.precision j\n    (phaseTotal next ctx net a u t i) hpos hjq F\n    ((source.modes.values.map (fun beta => ∏ g : Fin 64, interpret current\n      (leaf current (SemiprimeD1ChildNetwork.fromSource net source i g ctx [q]\n        source.precision (SemiprimeD1FreshJetBits.acquireFresh ctx q source.precision) t beta).network).words)).sum)\n    htotal hquery'\n  rw [phase_block next ctx net a u t hua ht j hj]\n  rw [phase_precision next ctx net a u t hua ht]\n  exact he\n\nend RiemannGaussian.SemiprimeD1RecursivePhaseCorrectness\n","RiemannGaussian.SemiprimeD1RootPortCounts":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1RootCopyContraction\nimport RiemannGaussian.SemiprimeD1PacketColumnPartition\n\n/-! # Original root owner-copy degrees from actual cached records\nFactor grouping may reorder records but preserves every owner occurrence.\nNo old/new owner-degree equality or incidence bijection is supplied.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2500000\nnamespace RiemannGaussian.SemiprimeD1RootPortCounts\nopen SemiprimeD1TensorNetwork SemiprimeD1RootTensorTables\nopen SemiprimeD1PacketColumnPartition\nnoncomputable section\nattribute [local instance] Classical.propDecidable\n\n/-- Flattening the actual finite grouped rows is the literal concatenation. -/\ntheorem flatten_map {A B : Type*} (xs : List A) (f : A→List B) :\n    (xs.map f).flatten=xs.flatMap f := by\n  induction xs with\n  | nil => rfl\n  | cons x xs ih => simp only [List.map_cons,List.flatten_cons,List.flatMap_cons,ih]\n\n/-- The actual typed occurrence enumeration reads every row owner in order. -/\ntheorem incidence_owners {n : ℕ} (rs : Rows n) :\n    (incidences rs).map (owner rs)=rs.flatten := by\n  change ((List.finRange rs.length).flatMap (fun e => (List.finRange (arity rs e)).map\n    (fun j => (⟨e,j⟩ : Incidence rs)))).map (owner rs)=_\n  rw [List.map_flatMap]\n  simp only [List.map_map,Function.comp_def]\n  have hf (e : Fin rs.length) :\n      (List.finRange (arity rs e)).map (fun j => owner rs ⟨e,j⟩)=rs[e.val] := by\n    change (List.finRange rs[e.val].length).map (fun j => rs[e.val][j.val])=rs[e.val]\n    rw [←List.ofFn_eq_map,List.ofFn_getElem]\n  simp_rw [hf]\n  have hr := List.ofFn_getElem (xs:=rs)\n  rw [List.ofFn_eq_map] at hr\n  rw [←flatten_map,hr]\n\n/-- Canonical left ports have exactly the actual owner multiplicity in rows. -/\ntheorem leftPorts_length {n : ℕ} (rs : Rows n) (v : Fin n) :\n    (leftPorts rs v).length=rs.flatten.countP (fun w => decide (w=v)) := by\n  unfold leftPorts\n  rw [List.length_map,←List.countP_eq_length_filter]\n  have h := congrArg (List.countP (fun w : Fin n => decide (w=v))) (incidence_owners rs)\n  simpa only [List.countP_map,Function.comp_def] using h\n\n/-- Actual factor grouping preserves the complete cached owner list as a\nmultiset, including parallel incidences and repeated owner coordinates. -/\ntheorem rows_owner_perm {n F : ℕ} {arity : Fin F→ℕ}\n    (data : SemiprimeD1RootTensorTables.Acquired n F arity) :\n    (SemiprimeD1RootNetwork.rows data).flatten.Perm (data.records.map PortRecord.owner) := by\n  have hp := partition_perm data.records (fun p => p.port.1) (fun p => some p.owner)\n  have hf (e : Fin F) : partitionMap data.records (fun p => p.port.1) (fun p => some p.owner) e=\n      (data.records.filter (fun p => decide (p.port.1=e))).map PortRecord.owner := by\n    induction data.records with\n    | nil => rfl\n    | cons p ps ih =>\n      unfold partitionMap at ih\n      by_cases h : p.port.1=e <;>\n        simp only [partitionMap,List.filterMap_cons,List.filter_cons,h,decide_true,decide_false,\n          Bool.false_eq_true,ite_true,ite_false,List.map_cons,ih]\n  have hr : data.records.filterMap (fun p => some p.owner)=data.records.map PortRecord.owner := by\n    induction data.records with\n    | nil => rfl\n    | cons p ps ih => simp only [List.filterMap_cons,List.map_cons,ih]\n  have hfun : partitionMap data.records (fun p => p.port.1) (fun p => some p.owner)=\n      (fun e => (data.records.filter (fun p => decide (p.port.1=e))).map PortRecord.owner) := funext hf\n  rw [hfun] at hp\n  rw [hr] at hp\n  unfold SemiprimeD1RootNetwork.rows\n  rw [List.ofFn_eq_map,flatten_map]\n  exact hp\n\n/-- No supplied owner-degree answer: canonical network copies and original\ncached owner tables have exactly the same number of local ports. -/\ntheorem original_owner_degree {n F : ℕ} {arity : Fin F→ℕ}\n    (data : SemiprimeD1RootTensorTables.Acquired n F arity) (v : Fin n) :\n    (leftPorts (SemiprimeD1RootNetwork.rows data) v).length=\n      (data.records.filter (fun p => decide (p.owner=v))).length := by\n  rw [leftPorts_length,←List.countP_eq_length_filter]\n  have h := (rows_owner_perm data).countP_eq (fun w => decide (w=v))\n  simpa only [List.countP_map,Function.comp_def] using h\n\nend\nend RiemannGaussian.SemiprimeD1RootPortCounts\n","RiemannGaussian.SemiprimeD1StackBinarySquareRootFinish":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackBinarySquareRootLoop\n/-! # Actual final consuming reversal and compact binary square-root output -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackBinarySquareRootFinish\nopen SemiprimeD1StackBinarySquareRoot SemiprimeD1StackBinarySquareRootEncoding\nopen SemiprimeD1StackBinarySquareRootPrimitives SemiprimeD1StackProcedureTrace\n/-- Actual final reversed root occupies the consumed power word temporarily. -/\ndef reversed (bits r : List Bool) : Stack→List Bool :=\n  bank (retained bits r.reverse) (fun _ => []) (fun _ => []) (fun _ => []) (words [] [])\n/-- Exact final full bank with only the compact root and the twelve retained metadata words. -/\ndef finished (bits r : List Bool) : Stack→List Bool :=\n  bank (retained bits []) (fun _ => []) (fun _ => []) (fun _ => [])\n    (words [] (SemiprimeD1StackReduceExecution.trimReverse r.reverse))\n/-- Actual consuming reverse moves every raw root cell, with its real return. -/\ntheorem reverse_call (bits r : List Bool) :\n    Runs program (2*r.length+3) (ctl .reverse) (idle bits [] r) (ctl .trim) (reversed bits r) := by\n  let source:=SemiprimeD1StackReverseWord.state none r []\n  let stop:=SemiprimeD1StackReverseWord.done r.reverse\n  let before:=idle bits [] r\n  have hi : Link.DataRel reverseStack before source.store before := by\n    constructor\n    · intro k;fin_cases k <;> rfl\n    · intro k _;rfl\n  have h0:=Link.data_update reverseStack reverse_injective before source.store before hi (0:Fin 2) []\n  have h1:=Link.data_update reverseStack reverse_injective before _ _ h0 (1:Fin 2) r.reverse\n  have he : Function.update (Function.update source.store 0 []) 1 r.reverse=stop.store := by\n    funext k;fin_cases k <;> rfl\n  rw [he] at h1\n  have he0 : Function.update before (reverseStack 0) []=idle bits [] [] := by\n    change Function.update (idle bits [] r) (aux .root) []=idle bits [] []\n    rw [idle,bank_aux,words_update]\n    rfl\n  have he1 : Function.update (idle bits [] []) (reverseStack 1) r.reverse=reversed bits r := by\n    change Function.update (idle bits [] []) (metadata (M.aux .base)) r.reverse=reversed bits r\n    rw [idle,bank_metadata,retained_update]\n    rfl\n  rw [he0,he1] at h1\n  exact included_call program reverseStack reverseLabel reverse_injective SemiprimeD1StackReverseWord.code 0\n    (fun _ => rfl) (ctl .reverse) (ctl .trim) rfl (2*r.length+2) source stop before _ rfl rfl\n    (by simpa only [List.append_nil] using SemiprimeD1StackReverseWord.reverse_run r [] none) hi h1\n/-- Actual final trimming restores the borrowed power role to empty and leaves every private role empty. -/\ntheorem trim_call (bits r : List Bool) :\n    Runs program (SemiprimeD1StackReduceExecution.trimTime r.reverse+1) (ctl .trim) (reversed bits r)\n      (ctl .done) (finished bits r) := by\n  let source:=SemiprimeD1StackReduce.state (some .trim) none [] [] r.reverse []\n  let stop:=SemiprimeD1StackReduce.state none none [] [] [] (SemiprimeD1StackReduceExecution.trimReverse r.reverse)\n  let before:=reversed bits r\n  have hi : Link.DataRel trimStack before source.store before := by\n    constructor\n    · intro k;cases k <;> rfl\n    · intro k _;rfl\n  have ho : Link.DataRel trimStack before stop.store (finished bits r) := by\n    constructor\n    · intro k;cases k <;> rfl\n    · intro k hk\n      rcases k with k|k|k|k|k\n      · rcases k with k|k|k\n        · cases k <;> rfl\n        · cases k <;> rfl\n        · cases k with\n          | base => exact False.elim (hk .scratch rfl)\n          | reader | copyScratch | precision | template => rfl\n      · cases k with\n        | left => exact False.elim (hk .left rfl)\n        | right => exact False.elim (hk .right rfl)\n        | scratch | output => rfl\n      · rfl\n      · rfl\n      · cases k with\n        | root => rfl\n        | output => exact False.elim (hk .output rfl)\n  exact included_call program trimStack trimLabel trim_injective SemiprimeD1StackReduce.code .trim\n    (fun _ => rfl) (ctl .trim) (ctl .done) rfl _ source stop before _ rfl rfl\n    (by simpa only [List.append_nil] using SemiprimeD1StackReduceExecution.trim_run r.reverse [] none) hi ho\n/-- Exact own time includes the two real final word traversals and returns. -/\ndef finishTime (r : List Bool) : ℕ := 2*r.length+3+(SemiprimeD1StackReduceExecution.trimTime r.reverse+1)\n/-- Complete actual compact output adapter, with all33 words accounted for. -/\ntheorem finish_run (bits r : List Bool) :\n    Runs program (finishTime r) (ctl .reverse) (idle bits [] r) (ctl .done) (finished bits r) :=\n  join (reverse_call bits r) (trim_call bits r)\nend RiemannGaussian.SemiprimeD1StackBinarySquareRootFinish\n","RiemannGaussian.SemiprimeD1StackBoundaryRecord":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackZeroBoundaryTableBounds\nimport RiemannGaussian.SemiprimeD1StackPortOrdinalStreamOriginal\nimport RiemannGaussian.SemiprimeD1StackVertexRecordStream\n/-! # Actual boundary table, acquired scope conversion and original record logging\nThe original binary N and an acquired binary occurrence-ID vector are the only\nsource fields. The two acquired outputs are the logger's actual operands.\nScope routing remains the caller's acquisition work.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackBoundaryRecord\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State run)\nend C\nnamespace Z\nexport SemiprimeD1StackZeroBoundaryTable (Stack Label program initial done original output)\nend Z\nnamespace S\nexport SemiprimeD1StackPortOrdinalStream (Stack Label program initial result)\nend S\nnamespace R\nexport SemiprimeD1StackVertexRecordStream (Stack Label code data row recordTime)\nend R\n/-- All forty-eight physical roles, including the two unused alias shadows. -/\nabbrev Stack := Z.Stack ⊕ (S.Stack ⊕ R.Stack)\n/-- Actual N-only source's private registers and public metadata. -/\ndef boundaryStack (k : Z.Stack) : Stack := .inl k\n/-- Actual preserving binary-ID serializer's private registers and bank. -/\ndef scopeStack (k : S.Stack) : Stack := .inr (.inl k)\n/-- Direct operands: neither acquired answer is copied or recoded. -/\ndef recordStack : R.Stack → Stack\n  | .ports => scopeStack .output\n  | .table => boundaryStack Z.output\n  | k => .inr (.inr k)\n/-- Original binary N's physical input role. -/\ndef original : Stack := boundaryStack Z.original\n/-- The actual caller's accumulated reverse row log. -/\ndef history : Stack := recordStack .history\n/-- The actual caller's retained final output accumulator. -/\ndef output : Stack := recordStack .output\n/-- Four finite local controls, independent of every input value. -/\ninductive Control where | start | scope | record | done\n  deriving DecidableEq\ninstance : Fintype Control := Fintype.ofList [.start,.scope,.record,.done] (by intro k;cases k <;> simp)\n/-- All real component labels, with no decoded identifier in control. -/\nabbrev Label := Control ⊕ (Z.Label ⊕ (S.Label ⊕ R.Label))\n/-- Literal whole-table acquisition procedure inclusion. -/\ndef boundaryLabel (pc : Z.Label) : Label := .inr (.inl pc)\n/-- Literal binary ordinal serialization procedure inclusion. -/\ndef scopeLabel (pc : S.Label) : Label := .inr (.inr (.inl pc))\n/-- Literal physical frame logger inclusion. -/\ndef recordLabel (pc : R.Label) : Label := .inr (.inr (.inr pc))\n/-- The actual three calls; the logger consumes both acquired outputs directly. -/\ndef program : Label → C.Instruction Stack Label\n  | .inl .start => .call (boundaryLabel (.inl .start)) (.inl .scope)\n  | .inl .scope => .call (scopeLabel (.control .start)) (.inl .record)\n  | .inl .record => .call (recordLabel .record) (.inl .done)\n  | .inl .done => .base .halt\n  | .inr (.inl pc) => SemiprimeD1StackValidationLink.instruction boundaryStack boundaryLabel (Z.program pc)\n  | .inr (.inr (.inl pc)) => SemiprimeD1StackValidationLink.instruction scopeStack scopeLabel (S.program pc)\n  | .inr (.inr (.inr pc)) => SemiprimeD1StackMultiplierLink.instruction recordStack recordLabel (R.code pc)\n/-- Entire physical inventory; both unused alias shadows stay empty. -/\ndef data (z : Z.Stack → List Bool) (s : S.Stack → List Bool) (hist out : List Bool) : Stack → List Bool :=\n  Sum.elim z (Sum.elim s (R.data [] [] hist out))\n/-- Only original binary N, acquired binary scope bytes and caller accumulators. -/\ndef initial (bits bank hist out : List Bool) : C.State Stack Label :=\n  ⟨some (.inl .start),none,none,data (Z.initial bits).data (S.initial bank).data hist out,[]⟩\n/-- Proof-side exact acquired boundary bytes, never a runtime input. -/\ndef table (bits : List Bool) : List Bool := (Z.done bits).data Z.output\n/-- Both acquired fields are consumed; the public caches and original bank remain. -/\ndef done (bits : List Bool) (words : List (List Bool)) (hist out : List Bool) : C.State Stack Label :=\n  ⟨none,none,none,data (Function.update (Z.done bits).data Z.output [])\n    (Function.update (SemiprimeD1StackPortOrdinalStreamExecution.done words).data (SemiprimeD1StackPortOrdinalStream.Stack.output) [])\n    ((R.row (S.result words) (table bits)).reverse++hist) out,[]⟩\n/-- Genuine fixed finite procedure machine, including the actual return alphabet. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine original output (.inl .start) program\n/-- Every original metadata, private scratch and unused alias role is counted. -/\ntheorem stack_card : Fintype.card Stack=48 := by decide\n/-- The logger's two shared operands and its own accumulators are distinct. -/\ntheorem recordStack_injective : Function.Injective recordStack := by decide\n/-- The actual public acquisition's complete metadata cache survives record logging. -/\ntheorem retained_public (bits : List Bool) (words : List (List Bool)) (hist out : List Bool)\n    (k : SemiprimeD1StackZeroBoundaryTable.P.Stack) :\n    (done bits words hist out).data (boundaryStack (.inl k))=\n      SemiprimeD1StackZeroBoundaryTable.context bits k := rfl\n/-- The original binary occurrence-ID bank is preserved byte for byte. -/\ntheorem retained_bank (bits : List Bool) (words : List (List Bool)) (hist out : List Bool) :\n    (done bits words hist out).data (scopeStack .bank)=SemiprimeD1TensorTapeCodec.vectorBits words := rfl\n/-- Appending a row leaves the caller's final output accumulator intact. -/\ntheorem retained_output (bits : List Bool) (words : List (List Bool)) (hist out : List Bool) :\n    (done bits words hist out).data output=out := rfl\nend RiemannGaussian.SemiprimeD1StackBoundaryRecord\n","RiemannGaussian.SemiprimeD1StackCachePhaseBankCalls":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackCachePhaseBankPrimitives\nimport RiemannGaussian.SemiprimeD1StackCachePhaseBankStopped\n/-! # ONE actual cached-phase source call per actual issued reference\nThe actual frozen restore+guard supplies accepted/rejected behavior. No branch\nflag, q, rank, precision, output or evaluator is a caller input instruction.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackCachePhaseBankCalls\nopen SemiprimeD1StackCachePhaseBank SemiprimeD1StackCachePhaseBankState\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeD1StackJetFoldWords (Modes)\nnamespace O\nexport SemiprimeD1StackCachePhaseRootOriginal (rootSource rootDone root_source_run rootDone_halted rootSize)\nend O\n/-- A full actual callee-bank replacement retains ALL8 actual outer words. -/\ntheorem whole_data_rel (before after:P.Stack→List Bool) (w:Aux→List Bool):\n    SemiprimeD1StackMultiplierLink.DataRel cached (data before w) after (data after w):=by\n  constructor\n  · intro k;rfl\n  · intro k hk\n    rcases k with k|k\n    · exact False.elim (hk k rfl)\n    · rfl\n/-- Own actual whole frozen source cap, plus its genuine outer call/return. -/\ndef callBound (bits:List Bool) (i:Fin (SemiprimeD1StackRootPhaseParametersEncoding.phases bits).length) (modes:Modes):Nat:=\n  10^80*(O.rootSize bits i modes+1)^16+1\n/-- Real per-issued-phase call; accepted/rejected choice follows the actual restored original guard. -/\ntheorem original_call (bits:List Bool) (i:Fin (SemiprimeD1StackRootPhaseParametersEncoding.phases bits).length)\n    (modes:Modes) (w:Aux→List Bool):\n    ∃t ≤callBound bits i modes,Runs program t (.local .phase) (data (O.rootSource bits i modes).data w)\n      (.local .frame) (data (O.rootDone bits i modes).data w):=by\n  obtain ⟨t,ht,hr⟩:=O.root_source_run bits i modes\n  have hh:=O.rootDone_halted bits i modes\n  have hp:(O.rootDone bits i modes).pc=none:=congrArg (fun q:C.State P.Stack P.Label=>q.pc) hh\n  have hf:(O.rootDone bits i modes).frames=[]:=congrArg (fun q:C.State P.Stack P.Label=>q.frames) hh\n  have h0:=SemiprimeD1StackProcedureCallsTrace.included_call program cached Label.phase cached_injective P.program\n    (.local .start) (fun _=>rfl) (.local .phase) (.local .frame) rfl t\n    (O.rootSource bits i modes) (O.rootDone bits i modes) _ _ rfl rfl hp hf hr\n    (whole_data_rel _ _ w) (whole_data_rel _ _ w)\n  exact ⟨t+1,Nat.add_le_add_right ht 1,h0⟩\n/-- Borrowing the real shared copy scratch AFTER the source is justified by the actual stopped result. -/\ntheorem after_call_scratch (bits:List Bool) (i:Fin (SemiprimeD1StackRootPhaseParametersEncoding.phases bits).length)\n    (modes:Modes) (w:Aux→List Bool):data (O.rootDone bits i modes).data w scratch=[]:=\n  SemiprimeD1StackCachePhaseBankStopped.original_scratch bits i modes\nend RiemannGaussian.SemiprimeD1StackCachePhaseBankCalls\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivationLoop":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivationRow\n/-! # Actual EOF-controlled all-old-vertex activation loop\nRows below are proof-side descriptions of fields acquired from the two actual\nsource words. They are never runtime inputs, control values, or instructions.\nThe original-source specialization must derive Valid from the retained caches.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivationLoop\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryPrimitives\nopen SemiprimeD1StackChildGroupFactoryActivation SemiprimeD1StackChildGroupFactoryActivationView\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\nnamespace RowSource\nexport SemiprimeD1StackChildGroupFactoryActivationRow (timeBound source_trace)\nend RowSource\n/-- Description of physically acquired fields, solely for the correctness statement. -/\nstructure Row where\n  /-- ID physically returned after the real present marker. -/\n  selected:List Bool\n  /-- Actual unread dictionary suffix, which is physically drained. -/\n  unread:List Bool\n  /-- Actual fields physically produced by the real paired-row source. -/\n  colours:List (List Bool)\n/-- The actual full-adder output is the loop's next binary key. -/\ndef advance (key:List Bool):List Bool:=(SemiprimeBitArithmetic.addBits key [true] false).bits\n/-- Domain of the actual acquired source words at every visited physical key. -/\ndef Valid (environment catalogue:List (List Bool×List Bool)) :List Bool→List Row→Prop\n  | _,[]=>True\n  | key,row::rows=>\n    SemiprimeD1StackOwnerLookup.result key environment []=(true::row.selected,row.unread) ∧\n    SemiprimeD1StackPacketRowsEncoding.present row.selected catalogue=true ∧\n    SemiprimeD1StackPacketRowsAcquire.payload row.selected catalogue=SemiprimeD1PacketRows.serialize row.colours ∧\n    Valid environment catalogue (advance key) rows\n/-- Full physical loop-boundary interpretation. No object of this type is in program control. -/\nstructure Summary where\n  /-- Actual generated binary next key. -/\n  key:List Bool\n  /-- Actual reversed Boolean activation log. -/\n  history:List Bool\n  /-- Actual newest-first numeric-key/flag map. -/\n  map:List Bool\n/-- Exact interpretation of repeated actual row logging. -/\ndef finish (i:Inputs) (coordinate:Nat):List Bool→List Bool→List Bool→List Row→Summary\n  | key,hist,map,[]=>⟨key,hist,map⟩\n  | key,hist,map,row::rows=>finish i coordinate (advance key)\n      (active i coordinate row.colours::hist)\n      (true::frame key (frame [active i coordinate row.colours] map)) rows\n/-- Sum of the same literal row traces and real marker/EOF pops. -/\ndef timeBound (i:Inputs) (coordinate:Nat) (environment catalogue:List (List Bool×List Bool)):\n    List Bool→List Row→Nat\n  | _,[]=>1\n  | key,row::rows=>1+RowSource.timeBound i key row.selected row.unread coordinate environment catalogue row.colours+\n      timeBound i coordinate environment catalogue (advance key) rows\n/-- The only cross-iteration marker-word write updates its physical role. -/\ntheorem data_write_todo (i:Inputs) (todo next key hist map:List Bool):\n    Function.update (data i todo key hist map) (aux .vertexTodo) next=data i next key hist map:=by\n  funext k\n  rcases k with k|k|k|k|k|k\n  · rfl\n  · rfl\n  · rfl\n  · rfl\n  · rfl\n  · cases k <;> rfl\n/-- Complete real all-old-vertex loop: every physical marker triggers one actual row source. -/\ntheorem source_trace (i:Inputs) (coordinate:Nat) (environment catalogue:List (List Bool×List Bool))\n    (he:i.environment=SemiprimeD1StackOwnerLookup.records environment [])\n    (hk:i.catalogue=SemiprimeD1StackOwnerLookup.records catalogue [])\n    (hi:i.colourIndex=List.replicate coordinate true)\n    (rows:List Row) (todo key hist map:List Bool)\n    (hlen:todo.length=rows.length) (hv:Valid environment catalogue key rows):\n    ∃t≤timeBound i coordinate environment catalogue key rows,\n      Runs program t (.local 0 3) (data i todo key hist map) (.local 2 16)\n        (data i [] (finish i coordinate key hist map rows).key\n          (finish i coordinate key hist map rows).history (finish i coordinate key hist map rows).map):=by\n  induction rows generalizing todo key hist map with\n  | nil=>\n    have hz:todo=[]:=by cases todo <;> simp_all\n    subst todo\n    have h:=pop_run (.local 0 3) (.local 2 16) (.local 0 4) (.local 0 4)\n      (aux .vertexTodo) (data i [] key hist map) [] rfl rfl\n    simp only [List.head?_nil,List.tail_nil,SemiprimeD1StackBytecode.choose] at h\n    rw [data_write_todo] at h\n    exact ⟨1,le_refl _,h⟩\n  | cons row rows ih=>\n    rcases todo with _|⟨bit,todo⟩\n    · simp only [List.length_nil,List.length_cons] at hlen;omega\n    · have hl:todo.length=rows.length:=by simp only [List.length_cons] at hlen;omega\n      rcases hv with ⟨hget,hp,hr,hvalid⟩\n      have h0:=pop_run (.local 0 3) (.local 2 16) (.local 0 4) (.local 0 4)\n        (aux .vertexTodo) (data i (bit::todo) key hist map) (bit::todo) rfl rfl\n      have h0':Runs program 1 (.local 0 3) (data i (bit::todo) key hist map)\n          (.local 0 4) (data i todo key hist map):=by\n        cases bit <;> simpa only [List.head?_cons,List.tail_cons,\n          SemiprimeD1StackBytecode.choose,data_write_todo] using h0\n      obtain ⟨a,ha,h1⟩:=RowSource.source_trace i todo key hist map coordinate environment catalogue\n        row.selected row.unread row.colours he hk hi hget hp hr\n      obtain ⟨b,hb,h2⟩:=ih todo (advance key) (active i coordinate row.colours::hist)\n        (true::frame key (frame [active i coordinate row.colours] map)) hl hvalid\n      refine ⟨1+(a+b),?_,join h0' (join h1 h2)⟩\n      dsimp only [timeBound]\n      omega\n/-- Actual next-key numeric value advances once per marker, regardless of padding. -/\ntheorem advance_value (key:List Bool):\n    SemiprimeBitArithmetic.bitValue (advance key)=SemiprimeBitArithmetic.bitValue key+1:=by\n  rw [advance,SemiprimeBitArithmetic.addBits_correct]\n  simp [SemiprimeBitArithmetic.bitValue,SemiprimeBitArithmetic.bitNat]\n/-- Generated key bytes are bounded by the paid number of markers. -/\ntheorem advance_length (key:List Bool):(advance key).length≤key.length+2:=by\n  have h:=(SemiprimeBitArithmetic.addBits_counts key [true] false).2.2.2.2\n  simp only [List.length_cons,List.length_nil] at h\n  change (SemiprimeBitArithmetic.addBits key [true] false).bits.length≤key.length+2\n  omega\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivationLoop\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivationMeaning":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivationLoop\nimport RiemannGaussian.SemiprimeD1StackSourceEnvironmentMeaning\nimport RiemannGaussian.SemiprimeD1ChildActivation\n/-! # Acquired complete environment supplies every real activation row\nThe plan is a proof interpretation of the retained environment/catalogue;\nno plan, ID list, decoded colour, flag, or getter is a runtime operand.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivationMeaning\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactory\nopen SemiprimeD1StackChildGroupFactoryActivation SemiprimeD1StackChildGroupFactoryActivationView\nopen SemiprimeD1StackChildGroupFactoryActivationLoop\nopen SemiprimeBitArithmetic (bitValue)\nnamespace Env\nexport SemiprimeD1StackSourceEnvironmentEncoding (prefixRows)\nexport SemiprimeD1StackSourceEnvironmentMeaning (lookup_prefix markedRead)\nend Env\nnamespace Palette\nexport SemiprimeD1StackPacketRowsMeaning (fields originalEntries original_lookup fields_original)\nend Palette\n/-- Actual next unread dictionary bytes are determined by the physical first-match scan. -/\ndef plan (a:Nat) (ids:List (List Bool)):List Bool→List (List Bool)→List Row\n  | _,[]=>[]\n  | key,id::rest=>⟨id,(SemiprimeD1StackOwnerLookup.result key (Env.prefixRows ids) []).2,\n      Palette.fields 64 a id⟩::plan a ids (advance key) rest\n/-- Exact number of real activation rows, independent of original incidence degree. -/\ntheorem plan_length (a:Nat) (ids:List (List Bool)) (key:List Bool) (remaining:List (List Bool)):\n    (plan a ids key remaining).length=remaining.length:=by\n  induction remaining generalizing key with\n  | nil=>rfl\n  | cons id rest ih=>simp only [plan,List.length_cons,ih]\n/-- Actual reverse-prefix position at the next original vertex. -/\ntheorem getD_append_head (before:List (List Bool)) (id:List Bool) (after:List (List Bool)):\n    (((before++id::after)[before.length]?).getD [])=id:=by\n  simp\n/-- Complete source-environment membership discharges every real row-source obligation. -/\ntheorem plan_valid (a:Nat) (ids:List (List Bool))\n    (hm:∀id∈ids,id∈(SemiprimeSourceCompactWordBank.acquire 64 a).ids)\n    (remaining:List (List Bool)) (before:List (List Bool)) (key:List Bool)\n    (hp:before++remaining=ids.reverse) (hk:bitValue key=before.length):\n    Valid (Env.prefixRows ids) (Palette.originalEntries 64 a) key (plan a ids key remaining):=by\n  induction remaining generalizing before key with\n  | nil=>trivial\n  | cons id rest ih=>\n    have hmem:id∈ids:=by\n      apply List.mem_reverse.mp\n      rw [←hp]\n      exact List.mem_append_right _ (List.mem_cons_self)\n    have hid:=hm id hmem\n    have hc:=SemiprimeSourceCompactWordBank.ids_compact 64 a id hid\n    have htrim:(SemiprimeSourceCompactBits.trim id).bits=id:=\n      SemiprimeSourceCompactWordIds.compact_value_injective _ _\n        (SemiprimeSourceCompactBits.trim_compact id) hc (SemiprimeSourceCompactBits.trim_value id)\n    have hlen:=congrArg List.length hp\n    have hlt:bitValue key < ids.length:=by\n      simp only [List.length_append,List.length_cons,List.length_reverse] at hlen\n      omega\n    have hexpected:SemiprimeSourceHistogramPrefix.expected ids (bitValue key)=id:=by\n      simp only [SemiprimeSourceHistogramPrefix.expected,hk]\n      rw [←hp,getD_append_head,htrim]\n    have hout:(SemiprimeD1StackOwnerLookup.result key (Env.prefixRows ids) []).1=true::id:=by\n      rw [Env.lookup_prefix]\n      simp only [Env.markedRead,hlt,ite_true,hexpected]\n    have hget:SemiprimeD1StackOwnerLookup.result key (Env.prefixRows ids) []=\n        (true::id,(SemiprimeD1StackOwnerLookup.result key (Env.prefixRows ids) []).2):=Prod.ext hout rfl\n    have hrow:=Palette.original_lookup 64 a id hid\n    have hprefix:(before++[id])++rest=ids.reverse:=by simpa only [List.append_assoc,List.singleton_append] using hp\n    have hkey:bitValue (advance key)=(before++[id]).length:=by\n      rw [advance_value,hk,List.length_append,List.length_singleton]\n    exact ⟨hget,hrow.2.1,hrow.1,ih (before++[id]) (advance key) hprefix hkey⟩\n/-- Initial key ZERO and the complete original vertex list need no row/order advice. -/\ntheorem plan_valid_all (a:Nat) (ids:List (List Bool))\n    (hm:∀id∈ids,id∈(SemiprimeSourceCompactWordBank.acquire 64 a).ids):\n    Valid (Env.prefixRows ids) (Palette.originalEntries 64 a) [] (plan a ids [] ids.reverse):=\n  plan_valid a ids hm ids.reverse [] [] rfl rfl\n/-- Physical computed colour equality agrees with the exact native selected-row read. -/\ntheorem active_original (i:Inputs) (a coordinate:Nat) (id:List Bool)\n    (hi:id∈(SemiprimeSourceCompactWordBank.acquire 64 a).ids):\n    active i coordinate (Palette.fields 64 a id)=\n      (SemiprimeD1ChildActivation.readOne (SemiprimeSourceHistogramRows.acquire 64 a) a coordinate i.group id).value:=by\n  have hv:=(SemiprimeD1PacketRows.original_fields 64 a id hi).2\n  unfold SemiprimeD1ChildActivation.readOne\n  dsimp only\n  rw [hv]\n  change active i coordinate (Palette.fields 64 a id)=\n    (SemiprimeD1ChildGraph.testColour i.group coordinate (SemiprimeD1PacketRows.parse a\n      (SemiprimeSourceHistogramRows.readRow (SemiprimeSourceHistogramRows.acquire 64 a) id).bits).fields).value\n  apply Bool.eq_iff_iff.mpr\n  rw [SemiprimeD1ChildGraph.testColour_correct]\n  simp only [active,SemiprimeD1StackChildGroupFactoryColour.result_word,decide_eq_true_eq]\n  rw [←Palette.fields_original 64 a id hi]\n  rfl\n/-- Actual all-vertex flag order is the original reverse-selected-ID order, including isolated vertices. -/\ntheorem plan_flags (i:Inputs) (a coordinate:Nat) (ids remaining:List (List Bool)) (key:List Bool):\n    (plan a ids key remaining).map (fun row=>active i coordinate row.colours)=\n      remaining.map (fun id=>active i coordinate (Palette.fields 64 a id)):=by\n  induction remaining generalizing key with\n  | nil=>rfl\n  | cons id rest ih=>simp only [plan,List.map_cons,ih]\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivationMeaning\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketOne":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketScanView\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketConvert\n/-! # Complete actual one-packet factory iteration\nThe observed packet is physically parsed, all acquired endpoints are scanned,\nits empty or nonempty bucket is logged, the real ordinal converter runs, and\nall fifteen packet/callee words are physically cleared before the next packet.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketOne\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryPrimitives\nopen SemiprimeD1StackProcedureTrace SemiprimeD1StackChildGroupFactoryFields\nnamespace Scan\nexport SemiprimeD1StackChildGroupFactoryBucketScan (result timeBound source_trace)\nend Scan\nnamespace SV\nexport SemiprimeD1StackChildGroupFactoryBucketScanView (result_children result_ports result_clean result_other)\nend SV\nnamespace Parse\nexport SemiprimeD1StackChildGroupFactoryBucketParse (Endpoint cleanRoles records)\nend Parse\nnamespace View\nexport SemiprimeD1StackChildGroupFactoryBucketLoopView (records portWords)\nend View\nnamespace Cleanup\nexport SemiprimeD1StackChildGroupFactoryBucketCleanup (role)\nend Cleanup\nnamespace Convert\nexport SemiprimeD1StackChildGroupFactoryBucketConvert (result timeBound source_trace)\nend Convert\nopen SemiprimeSourceHistogramKeyBits (frame)\n/-- Actual one-field packet parse bank. -/\ndef prepared (before:Stack→List Bool) (packet tail:List Bool):Stack→List Bool:=\n  Function.update (Function.update before (aux .packetReader) tail) (aux .packetKey) packet\n/-- Actual scanned bucket bank, with both ordered binary vectors physically present. -/\ndef scanned (before:Stack→List Bool) (es:List Parse.Endpoint) (packet tail position:List Bool):Stack→List Bool:=\n  Scan.result (prepared before packet tail) es packet position\n/-- Full actual iteration result, with all private packet/converter words cleared. -/\ndef result (before:Stack→List Bool) (es:List Parse.Endpoint) (packet tail position:List Bool):Stack→List Bool:=\n  Convert.result (scanned before es packet tail position) packet (View.records es packet position++[false])\n    (View.portWords es packet position)\n/-- Every actual parse/copy/scan/reverse/conversion/logger/cleanup clock is retained. -/\ndef timeBound (before:Stack→List Bool) (es:List Parse.Endpoint) (packet tail position:List Bool):Nat:=\n  1+(8*packet.length+8)+Scan.timeBound es packet position+\n    Convert.timeBound (scanned before es packet tail position) packet (View.records es packet position++[false])\n      (View.portWords es packet position)\n/-- One COMPLETE actual loop iteration, including every observed empty bucket and every repeated prepared packet. -/\ntheorem source_trace (before:Stack→List Bool) (es:List Parse.Endpoint) (packet tail position:List Bool)\n    (ht:before (aux .packetReader)=true::frame packet tail)\n    (he:before (aux .endpoints)=Parse.records es) (her:before (aux .endpointReader)=[])\n    (hz:∀k∈Parse.cleanRoles,before k=[])\n    (hpk:before (aux .packetKey)=[]) (hpos:before (aux .globalPosition)=position)\n    (hb:before (aux .frameBuffer)=[]) (hc:before (aux .copyScratch)=[])\n    (ha:∀k,before (arithmetic k)=[]) (ho:∀k,before (ordinal k)=[])\n    (hbh:before (aux .bucketHistory)=[]) (hph:before (aux .portHistory)=[])\n    (hj:before (aux .jointKey)=[]) (hpb:before (aux .portBank)=[]):\n    ∃t≤timeBound before es packet tail position,\n      Runs program t (.local 6 18) before (.local 6 18) (result before es packet tail position):=by\n  have h0:=pop_run (.local 6 18) abort (.local 6 19) (.local 6 20) (aux .packetReader) before\n    (true::frame packet tail) rfl ht\n  simp only [List.head?_cons,List.tail_cons,SemiprimeD1StackBytecode.choose] at h0\n  let b1:=Function.update before (aux .packetReader) (frame packet tail)\n  have hscratch:=hz (field (.inl .scratch)) (by simp [Parse.cleanRoles])\n  have hvalid:=hz (field (.inr ())) (by simp [Parse.cleanRoles])\n  have h1:=field_read 10 (.local 6 20) (.local 6 21) (.local 6 22) abort abort rfl rfl b1 packet tail\n    (Function.update_self _ _ _) (by simpa [b1,aux,fieldStack,fieldPorts] using hpk)\n    (by simpa [b1,aux,field] using hscratch) (by simpa [b1,aux,field] using hvalid)\n  change Runs program _ _ b1 _ (Function.update (Function.update b1 (aux .packetReader) tail) (aux .packetKey) packet) at h1\n  have he1:Function.update (Function.update b1 (aux .packetReader) tail) (aux .packetKey) packet=prepared before packet tail:=by\n    dsimp only [b1,prepared]\n    rw [Function.update_idem]\n  rw [he1] at h1\n  have hz':∀k∈Parse.cleanRoles,prepared before packet tail k=[]:=by\n    simpa [prepared,Parse.cleanRoles,aux,field] using hz\n  have h2:=Scan.source_trace (prepared before packet tail) es packet position\n    (by simpa [prepared,aux] using he) (by simpa [prepared,aux] using her) hz' rfl\n    (by simpa [prepared,aux] using hpos) (by simpa [prepared,aux] using hb)\n    (by simpa [prepared,aux] using hc) (by intro k;simpa [prepared,aux,arithmetic] using ha k)\n    (by simpa [prepared,aux] using hbh) (by simpa [prepared,aux] using hph)\n    (by simpa [prepared,aux] using hj) (by simpa [prepared,aux] using hpb)\n  change Runs program _ _ _ _ (scanned before es packet tail position) at h2\n  have hp':scanned before es packet tail position (aux .packetKey)=packet:=by\n    rw [scanned,SV.result_other _ _ _ _ _ (by intro j;fin_cases j <;> decide)\n      (by decide) (by decide) (by decide) (by decide) (by decide) (by decide)]\n    rfl\n  have ho':∀k,scanned before es packet tail position (ordinal k)=[]:=by\n    intro k\n    rw [scanned,SV.result_other _ _ _ _ _ (by intro j;fin_cases j <;> simp [Cleanup.role,ordinal,aux])\n      (by simp [ordinal,aux]) (by simp [ordinal,aux]) (by simp [ordinal,aux])\n      (by simp [ordinal,aux]) (by simp [ordinal,aux]) (by simp [ordinal,aux])]\n    simpa [prepared,aux,ordinal] using ho k\n  have hr':scanned before es packet tail position (aux .rowBuffer)=[]:=\n    SV.result_clean _ _ _ _ hz' _ (by simp [Parse.cleanRoles])\n  have hb':scanned before es packet tail position (aux .frameBuffer)=[]:=by\n    rw [scanned,SV.result_other _ _ _ _ _ (by intro j;fin_cases j <;> decide)\n      (by decide) (by decide) (by decide) (by decide) (by decide) (by decide)]\n    simpa [prepared,aux] using hb\n  have hc':scanned before es packet tail position (aux .copyScratch)=[]:=by\n    rw [scanned,SV.result_other _ _ _ _ _ (by intro j;fin_cases j <;> decide)\n      (by decide) (by decide) (by decide) (by decide) (by decide) (by decide)]\n    simpa [prepared,aux] using hc\n  obtain ⟨t,htime,h3⟩:=Convert.source_trace (scanned before es packet tail position) packet\n    (View.records es packet position++[false]) (View.portWords es packet position) hp'\n      (SV.result_children _ _ _ _) (SV.result_ports _ _ _ _) ho' hr' hb' hc'\n  refine ⟨1+(8*packet.length+8)+Scan.timeBound es packet position+t,?_,?_⟩\n  · dsimp only [timeBound]\n    omega\n  · have hwhole:=join h0 (join h1 (join h2 h3))\n    simpa only [result,Nat.add_assoc] using hwhole\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketOne\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketReady":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketsSourceView\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryVertexBody\n/-! # Actual post-bucket readiness for the whole all-vertex source\nAll twenty query words, arithmetic and twelve converter words are derived\nfrom actual cleanup and retained initial emptiness, including zero packets.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketReady\nopen SemiprimeD1StackChildGroupFactoryRoles\nnamespace B\nexport SemiprimeD1StackChildGroupFactoryBucketsSource (result)\nexport SemiprimeD1StackChildGroupFactoryBucketsSourceView\n  (Protected result_other result_clean result_reuse_word result_endpointReader result_histories)\nend B\nnamespace Body\nexport SemiprimeD1StackChildGroupFactoryVertexBody (Ready)\nend Body\nnamespace Work\nexport SemiprimeD1StackChildGroupFactoryOldPortsLoop (freshRole)\nend Work\nnamespace Parse\nexport SemiprimeD1StackChildGroupFactoryBucketParse (Endpoint cleanRoles)\nend Parse\n/-- Actual whole completed bucket source restores precisely the next source's physical obligations. -/\ntheorem result_ready (before:Stack→List Bool) (packets:List (List Bool)) (es:List Parse.Endpoint)\n    (position:List Bool) (hr:Body.Ready before) (hbh:before (aux .bucketHistory)=[]):\n    Body.Ready (B.result before packets es position):=by\n  have keep (k:Stack) (hk:B.Protected k) (hz:before k=[]):B.result before packets es position k=[]:=\n    (B.result_other _ _ _ _ _ hk).trans hz\n  have hc:∀k∈Parse.cleanRoles,before k=[]:=by\n    intro k hk\n    simp only [Parse.cleanRoles,List.mem_cons,List.not_mem_nil,or_false] at hk\n    rcases hk with rfl|rfl|rfl|rfl|rfl|rfl|rfl|rfl\n    · exact hr.work (4:Fin 20) (by decide)\n    · exact hr.work (5:Fin 20) (by decide)\n    · exact hr.work (6:Fin 20) (by decide)\n    · exact hr.work (7:Fin 20) (by decide)\n    · exact hr.work (8:Fin 20) (by decide)\n    · exact hr.work (3:Fin 20) (by decide)\n    · exact hr.work (16:Fin 20) (by decide)\n    · exact hr.work (17:Fin 20) (by decide)\n  have hclean:=B.result_clean before packets es position hc\n  constructor\n  · intro j hj\n    have hz:=hr.work j hj\n    fin_cases j\n    · exact keep _ (by\n        constructor\n        all_goals first | (intro k;fin_cases k <;> decide) | decide) hz\n    · exact keep _ (by\n        constructor\n        all_goals first | (intro k;fin_cases k <;> decide) | decide) hz\n    · exact B.result_endpointReader _ _ _ _ hz\n    · exact hclean _ (by simp [Parse.cleanRoles,Work.freshRole])\n    · exact hclean _ (by simp [Parse.cleanRoles,Work.freshRole])\n    · exact hclean _ (by simp [Parse.cleanRoles,Work.freshRole])\n    · exact hclean _ (by simp [Parse.cleanRoles,Work.freshRole])\n    · exact hclean _ (by simp [Parse.cleanRoles,Work.freshRole])\n    · exact hclean _ (by simp [Parse.cleanRoles,Work.freshRole])\n    · exact (hj rfl).elim\n    · exact keep _ (by\n        constructor\n        all_goals first | (intro k;fin_cases k <;> decide) | decide) hz\n    · exact keep _ (by\n        constructor\n        all_goals first | (intro k;fin_cases k <;> decide) | decide) hz\n    · exact keep _ (by\n        constructor\n        all_goals first | (intro k;fin_cases k <;> decide) | decide) hz\n    · exact keep _ (by\n        constructor\n        all_goals first | (intro k;fin_cases k <;> decide) | decide) hz\n    · exact B.result_reuse_word _ _ _ _ 0 hz\n    · exact keep _ (by\n        constructor\n        all_goals first | (intro k;fin_cases k <;> decide) | decide) hz\n    · exact hclean _ (by simp [Parse.cleanRoles,Work.freshRole])\n    · exact hclean _ (by simp [Parse.cleanRoles,Work.freshRole])\n    · exact keep _ (by\n        constructor\n        all_goals first | (intro k;fin_cases k <;> decide) | decide) hz\n    · exact keep _ (by\n        constructor\n        all_goals first | (intro k;fin_cases k <;> decide) | decide) hz\n  · intro k\n    exact keep _ (by\n      constructor\n      all_goals first | (intro j;fin_cases j <;> cases k <;> decide) | (cases k <;> decide)) (hr.arithmetic_clean k)\n  · intro k\n    have h:=B.result_reuse_word before packets es position\n      (SemiprimeD1StackChildGroupFactoryBucketConvertView.ordinalIndex k)\n      (by rw [SemiprimeD1StackChildGroupFactoryBucketConvertView.ordinalIndex_role];exact hr.ordinal_clean k)\n    simpa only [SemiprimeD1StackChildGroupFactoryBucketConvertView.ordinalIndex_role] using h\n  · exact keep _ (by\n      constructor\n      all_goals first | (intro j;fin_cases j <;> decide) | decide) hr.oldReader_empty\n  · exact B.result_reuse_word _ _ _ _ 2 hr.portBank_empty\n  · exact (B.result_histories _ _ _ _ hbh hr.portHistory_empty).2\n  · exact keep _ (by\n      constructor\n      all_goals first | (intro j;fin_cases j <;> decide) | decide) hr.orderBank_empty\n  · exact keep _ (by\n      constructor\n      all_goals first | (intro j;fin_cases j <;> decide) | decide) hr.orderHistory_empty\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketReady\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketsSourceView":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketsSource\n/-! # Whole actual bucket catalogue restoration, including empty packet vectors -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketsSourceView\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryBucketsSource\nnamespace One\nexport SemiprimeD1StackChildGroupFactoryBucketOneView\n  (result_clean result_reuse result_endpointReader result_histories)\nend One\nnamespace LoopDef\nexport SemiprimeD1StackChildGroupFactoryBucketsLoop (result atEOF)\nend LoopDef\n/-- Fixed physical source-bank exclusions, independent of any prepared operand. -/\nstructure Protected (k:Stack):Prop where\n  raw:∀j,Cleanup.role j≠k\n  reuse:∀j,Reuse.role j≠k\n  packetReader:k≠aux .packetReader\n  endpointReader:k≠aux .endpointReader\n  bucketHistory:k≠aux .bucketHistory\n  portHistory:k≠aux .portHistory\n  globalPosition:k≠aux .globalPosition\n  factorHistory:k≠aux .factorHistory\n  buckets:k≠aux .buckets\n/-- All actual source/cache words outside fixed work and outputs remain byte-identical. -/\ntheorem result_other (before:Stack→List Bool) (packets:List (List Bool)) (es:List Parse.Endpoint)\n    (position:List Bool) (k:Stack) (hk:Protected k):result before packets es position k=before k:=by\n  simp only [result,Function.update_of_ne hk.buckets,Function.update_of_ne hk.factorHistory]\n  rw [View.result_other _ _ _ _ _ hk.raw hk.reuse hk.packetReader hk.endpointReader hk.bucketHistory\n    hk.portHistory hk.globalPosition hk.factorHistory]\n  exact Function.update_of_ne hk.packetReader _ _\n/-- Parser/raw fields are clean after every real observed-packet iteration. -/\ntheorem loop_clean (packets:List (List Bool)) (before:Stack→List Bool) (es:List Parse.Endpoint) (position:List Bool)\n    (hz:∀k∈Parse.cleanRoles,before k=[]):∀k∈Parse.cleanRoles,Loop.result packets before es position k=[]:=by\n  induction packets generalizing before position with\n  | nil=>\n    intro k hk\n    simp only [Parse.cleanRoles,List.mem_cons,List.not_mem_nil,or_false] at hk\n    rcases hk with rfl|rfl|rfl|rfl|rfl|rfl|rfl|rfl\n    all_goals simpa [LoopDef.result,LoopDef.atEOF,aux,field] using hz _ (by simp [Parse.cleanRoles,aux,field])\n  | cons packet packets ih=>exact ih _ _ (One.result_clean _ _ _ _ _ hz)\n/-- The actual packet/converter reuse word is empty even when no packet was present. -/\ntheorem loop_reuse (packets:List (List Bool)) (before:Stack→List Bool) (es:List Parse.Endpoint) (position:List Bool)\n    (hz:∀j,before (Reuse.role j)=[]):∀j,Loop.result packets before es position (Reuse.role j)=[]:=by\n  induction packets generalizing before position with\n  | nil=>\n    intro j\n    exact (Function.update_of_ne (by fin_cases j <;> decide : Reuse.role j≠aux .packetReader) _ _).trans (hz j)\n  | cons packet packets ih=>exact ih _ _ (One.result_reuse _ _ _ _ _)\n/-- Real endpoint EOF consumption or retained initial emptiness makes its work reader empty. -/\ntheorem loop_endpointReader (packets:List (List Bool)) (before:Stack→List Bool) (es:List Parse.Endpoint) (position:List Bool)\n    (hz:before (aux .endpointReader)=[]):Loop.result packets before es position (aux .endpointReader)=[]:=by\n  induction packets generalizing before position with\n  | nil=>simpa [LoopDef.result,LoopDef.atEOF,aux] using hz\n  | cons packet packets ih=>exact ih _ _ (One.result_endpointReader _ _ _ _ _)\n/-- Both real row histories are physically empty at each completed bucket boundary. -/\ntheorem loop_histories (packets:List (List Bool)) (before:Stack→List Bool) (es:List Parse.Endpoint) (position:List Bool)\n    (hb:before (aux .bucketHistory)=[]) (hp:before (aux .portHistory)=[]):\n    Loop.result packets before es position (aux .bucketHistory)=[] ∧\n      Loop.result packets before es position (aux .portHistory)=[]:=by\n  induction packets generalizing before position with\n  | nil=>constructor\n         · simpa [LoopDef.result,LoopDef.atEOF,aux] using hb\n         · simpa [LoopDef.result,LoopDef.atEOF,aux] using hp\n  | cons packet packets ih=>exact ih _ _ (One.result_histories _ _ _ _ _).1 (One.result_histories _ _ _ _ _).2\n/-- The complete source preserves actual parser freshness through the final real bucket reversal. -/\ntheorem result_clean (before:Stack→List Bool) (packets:List (List Bool)) (es:List Parse.Endpoint) (position:List Bool)\n    (hz:∀k∈Parse.cleanRoles,before k=[]):∀k∈Parse.cleanRoles,result before packets es position k=[]:=by\n  have hz':∀k∈Parse.cleanRoles,copied before packets k=[]:=by simpa [copied,Parse.cleanRoles,aux,field] using hz\n  have h:=loop_clean packets (copied before packets) es position hz'\n  intro k hk\n  simp only [Parse.cleanRoles,List.mem_cons,List.not_mem_nil,or_false] at hk\n  rcases hk with rfl|rfl|rfl|rfl|rfl|rfl|rfl|rfl\n  all_goals simpa [result,aux,field] using h _ (by simp [Parse.cleanRoles,aux,field])\n/-- All fifteen reuse roles, including all twelve converter allocations, are actually empty. -/\ntheorem result_reuse (before:Stack→List Bool) (packets:List (List Bool)) (es:List Parse.Endpoint) (position:List Bool)\n    (hz:∀j,before (Reuse.role j)=[]):∀j,result before packets es position (Reuse.role j)=[]:=by\n  have hz':∀j,copied before packets (Reuse.role j)=[]:=by\n    intro j\n    exact (Function.update_of_ne (by fin_cases j <;> decide : Reuse.role j≠aux .packetReader) _ _).trans (hz j)\n  have h:=loop_reuse packets (copied before packets) es position hz'\n  intro j\n  have hn:Reuse.role j≠aux .buckets:=by fin_cases j <;> decide\n  have hf:Reuse.role j≠aux .factorHistory:=by fin_cases j <;> decide\n  simpa only [result,Function.update_of_ne hn,Function.update_of_ne hf] using h j\n/-- Single reuse word restoration requires only its own actual initial emptiness. -/\ntheorem loop_reuse_word (packets:List (List Bool)) (before:Stack→List Bool) (es:List Parse.Endpoint) (position:List Bool)\n    (j:Fin 15) (hz:before (Reuse.role j)=[]):Loop.result packets before es position (Reuse.role j)=[]:=by\n  induction packets generalizing before position with\n  | nil=>exact (Function.update_of_ne (by fin_cases j <;> decide : Reuse.role j≠aux .packetReader) _ _).trans hz\n  | cons packet packets ih=>exact ih _ _ (One.result_reuse _ _ _ _ _ j)\n/-- Single reuse role after the actual final reversal, including the zero-packet case. -/\ntheorem result_reuse_word (before:Stack→List Bool) (packets:List (List Bool)) (es:List Parse.Endpoint) (position:List Bool)\n    (j:Fin 15) (hz:before (Reuse.role j)=[]):result before packets es position (Reuse.role j)=[]:=by\n  have hz':copied before packets (Reuse.role j)=[]:=\n    (Function.update_of_ne (by fin_cases j <;> decide : Reuse.role j≠aux .packetReader) _ _).trans hz\n  have h:=loop_reuse_word packets (copied before packets) es position j hz'\n  have hn:Reuse.role j≠aux .buckets:=by fin_cases j <;> decide\n  have hf:Reuse.role j≠aux .factorHistory:=by fin_cases j <;> decide\n  simpa only [result,Function.update_of_ne hn,Function.update_of_ne hf] using h\n/-- Actual endpoint-reader emptiness survives the complete catalogue reversal. -/\ntheorem result_endpointReader (before:Stack→List Bool) (packets:List (List Bool)) (es:List Parse.Endpoint) (position:List Bool)\n    (hz:before (aux .endpointReader)=[]):result before packets es position (aux .endpointReader)=[]:=by\n  have h:=loop_endpointReader packets (copied before packets) es position (by simpa [copied,aux] using hz)\n  simpa [result,aux] using h\n/-- Both real per-bucket histories remain empty after the final catalogue reversal. -/\ntheorem result_histories (before:Stack→List Bool) (packets:List (List Bool)) (es:List Parse.Endpoint) (position:List Bool)\n    (hb:before (aux .bucketHistory)=[]) (hp:before (aux .portHistory)=[]):\n    result before packets es position (aux .bucketHistory)=[] ∧ result before packets es position (aux .portHistory)=[]:=by\n  have h:=loop_histories packets (copied before packets) es position\n    (by simpa [copied,aux] using hb) (by simpa [copied,aux] using hp)\n  constructor\n  · simpa [result,aux] using h.1\n  · simpa [result,aux] using h.2\n/-- The actual source clears its completed bucket-log history with a genuine reversal. -/\ntheorem result_factorHistory (before:Stack→List Bool) (packets:List (List Bool)) (es:List Parse.Endpoint) (position:List Bool):\n    result before packets es position (aux .factorHistory)=[]:=rfl\n/-- Exact emitted bucket tape, with every observed empty or duplicate bucket retained. -/\ntheorem result_buckets (before:Stack→List Bool) (packets:List (List Bool)) (es:List Parse.Endpoint) (position:List Bool):\n    result before packets es position (aux .buckets)=View.records packets es position++[false]:=rfl\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketsSourceView\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryCleanup":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryPrimitives\n/-! # Literal complete 115-role physical cleanup\nThe actual fixed cleanup order visits every allocated word, including callee\nshadows. Retained input/output words are skipped by static jumps; every other\nword is physically popped through EOF. Ranks below are proof notation only.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryCleanup\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryPrimitives\nopen SemiprimeD1StackProcedureTrace\nnoncomputable section\n\n/-- Proof-side inverse of the literal complete cleanup order. -/\ndef rank (k:Stack):Fin 115:=Classical.choose (role_complete k)\ntheorem role_rank (k:Stack):role (rank k)=k:=Classical.choose_spec (role_complete k)\ntheorem rank_role (i:Fin 115):rank (role i)=i:=role_injective (role_rank (role i))\n/-- Exact word bank after the first n static cleanup labels have executed. -/\ndef swept (aborted:Bool) (before:Stack→List Bool) (n:Nat) (k:Stack):List Bool:=\n  if retained aborted k then before k else if (rank k).val < n then [] else before k\n/-- Exact completely cleaned physical bank. -/\ndef result (aborted:Bool) (before:Stack→List Bool) (k:Stack):List Bool:=\n  if retained aborted k then before k else []\n/-- Exact bounded static program location, including its real final status label. -/\ndef pc (aborted:Bool) (n:Nat):Label:=\n  if h:n<115 then .clear aborted ⟨n,h⟩ else if aborted then reject else accept\n/-- All allocated physical words contribute to this actual byte sum. -/\ndef mass (before:Stack→List Bool):Nat:=∑i:Fin 115,(before (role i)).length\nprivate theorem sum_cell {n:Nat} (f:Fin n→Nat) (i:Fin n):f i ≤ ∑j,f j:=by\n  exact Finset.single_le_sum (fun _ _=>Nat.zero_le _) (Finset.mem_univ i)\n/-- A currently visited word is paid by the whole actual allocated byte sum. -/\ntheorem word_le_mass (before:Stack→List Bool) (i:Fin 115):\n    (before (role i)).length≤ mass before:=by\n  exact sum_cell (fun j:Fin 115=>(before (role j)).length) i\ntheorem swept_zero (aborted:Bool) (before:Stack→List Bool):swept aborted before 0=before:=by\n  funext k;simp only [swept,Nat.not_lt_zero,ite_false];split <;> rfl\ntheorem swept_all (aborted:Bool) (before:Stack→List Bool):swept aborted before 115=result aborted before:=by\n  funext k;simp only [swept,result,(rank k).isLt,ite_true]\ntheorem swept_current (aborted:Bool) (before:Stack→List Bool) (i:Fin 115):\n    swept aborted before i.val (role i)=before (role i):=by\n  simp only [swept,rank_role,lt_self_iff_false,ite_false];split <;> rfl\ntheorem swept_step_skip (aborted:Bool) (before:Stack→List Bool) (i:Fin 115)\n    (hi:retained aborted (role i)=true):swept aborted before (i.val+1)=swept aborted before i.val:=by\n  funext k\n  by_cases hk:k=role i\n  · subst k;simp only [swept,hi,ite_true]\n  · have hn:(rank k).val≠i.val:=by\n      intro he\n      have hri:rank k=i:=Fin.ext he\n      exact hk ((role_rank k).symm.trans (congrArg role hri))\n    have hlt:((rank k).val < i.val+1)↔((rank k).val < i.val):=by omega\n    simp only [swept,hlt]\ntheorem swept_step_clear (aborted:Bool) (before:Stack→List Bool) (i:Fin 115)\n    (hi:retained aborted (role i)=false):\n    Function.update (swept aborted before i.val) (role i) []=swept aborted before (i.val+1):=by\n  funext k\n  by_cases hk:k=role i\n  · subst k;simp only [Function.update_self,swept,hi,rank_role,Nat.lt_succ_self,Bool.false_eq_true,ite_false,ite_true]\n  · have hn:(rank k).val≠i.val:=by\n      intro he\n      have hri:rank k=i:=Fin.ext he\n      exact hk ((role_rank k).symm.trans (congrArg role hri))\n    have hlt:((rank k).val < i.val+1)↔((rank k).val < i.val):=by omega\n    simp only [Function.update_of_ne hk,swept,hlt]\ntheorem next_pc (aborted:Bool) (i:Fin 115):nextClear aborted i=pc aborted (i.val+1):=rfl\n/-- One actual static cleanup label: retained jump or complete physical word drain. -/\ntheorem step_trace (aborted:Bool) (before:Stack→List Bool) (i:Fin 115):\n    ∃t≤ mass before+1,Runs program t (pc aborted i.val) (swept aborted before i.val)\n      (pc aborted (i.val+1)) (swept aborted before (i.val+1)):=by\n  have hpc:pc aborted i.val=.clear aborted i:=by simp [pc,i.isLt]\n  cases he:retained aborted (role i) with\n  | false=>\n    have hc:program (.clear aborted i)=.base (.pop (role i) (nextClear aborted i) (.clear aborted i) (.clear aborted i)):=by\n      simp only [program,he,Bool.false_eq_true,ite_false]\n    have h:=drain_loop (.clear aborted i) (nextClear aborted i) (role i) hc\n      (swept aborted before i.val) (before (role i)) (swept_current _ _ _)\n    rw [swept_step_clear _ _ _ he,next_pc] at h\n    exact ⟨(before (role i)).length+1,Nat.add_le_add_right (word_le_mass before i) 1,by simpa only [hpc] using h⟩\n  | true=>\n    have hc:program (.clear aborted i)=.base (.jump (nextClear aborted i)):=by simp only [program,he,ite_true]\n    have h:=jump_run (.clear aborted i) (nextClear aborted i) (swept aborted before i.val) hc\n    rw [next_pc] at h\n    refine ⟨1,by omega,?_⟩\n    rw [hpc,swept_step_skip _ _ _ he]\n    exact h\n/-- Complete real remaining sweep, uniformly bounded using the SAME actual bank bytes. -/\ntheorem sweep_trace (aborted:Bool) (before:Stack→List Bool) (n:Nat) (hn:n≤115):\n    ∃t≤(115-n)*(mass before+1),Runs program t (pc aborted n) (swept aborted before n)\n      (pc aborted 115) (result aborted before):=by\n  by_cases hlast:n=115\n  · subst n\n    refine ⟨0,by omega,?_⟩\n    rw [swept_all]\n    exact runs_refl program _ _\n  · have hn':n<115:=by omega\n    obtain ⟨x,hx,h0⟩:=step_trace aborted before ⟨n,hn'⟩\n    obtain ⟨y,hy,h1⟩:=sweep_trace aborted before (n+1) (by omega)\n    refine ⟨x+y,?_,join h0 h1⟩\n    have he:115-n=1+(115-(n+1)):=by omega\n    rw [he,Nat.add_mul,one_mul]\n    exact Nat.add_le_add hx hy\ntermination_by 115-n\n/-- Actual entire cleanup, from its first physical role to its real status push. -/\ntheorem source_trace (aborted:Bool) (before:Stack→List Bool):\n    ∃t≤115*(mass before+1),Runs program t (.clear aborted 0) before\n      (if aborted then reject else accept) (result aborted before):=by\n  obtain ⟨t,ht,h⟩:=sweep_trace aborted before 0 (by omega)\n  refine ⟨t,by simpa using ht,?_⟩\n  simpa [pc,swept_zero] using h\n/-- No physical word outside the fixed retained roles survives silently. -/\ntheorem result_word (aborted:Bool) (before:Stack→List Bool) (k:Stack):\n    result aborted before k=if retained aborted k then before k else []:=rfl\nend\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryCleanup\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryEndpointFlag":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryCalls\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivationMap\n/-! # Literal endpoint activation lookup and both real cleanup branches\nThe flag in the theorem describes the actual dictionary result. The source\nobtains it through its real lookup and physical output pop, not as an input.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryEndpointFlag\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryPrimitives\nopen SemiprimeD1StackChildGroupFactoryCalls SemiprimeD1StackProcedureTrace\n/-- Owner and factor keys are the actual pair fields, not supplied vertex addresses. -/\ndef vertex (owner:Bool):Stack:=aux (if owner then .ownerKey else .factorKey)\n/-- The four literal actual query/table/call/result positions for each endpoint. -/\ndef pc (owner:Bool) (slot:Fin 4):Label:=if owner then match slot.val with\n  | 0=>(.local 3 22)\n  | 1=>(.local 3 23)\n  | 2=>(.local 3 24)\n  | 3=>(.local 3 25)\n  | _=>(.local 3 25)\nelse match slot.val with\n  | 0=>(.local 5 2)\n  | 1=>(.local 5 3)\n  | 2=>(.local 5 4)\n  | 3=>(.local 5 5)\n  | _=>(.local 5 5)\n/-- Only the physically read flag selects actual emit or clear continuation. -/\ndef next (owner flag:Bool):Label:=if owner then (if flag then (.local 4 16) else (.local 4 25))\n  else (if flag then (.local 5 28) else (.local 6 5))\n/-- Actual eleven-word physical cleanup sites for all four finite branches. -/\ndef clearPC (owner flag:Bool) (slot:Fin 12):Label:=if owner then\n  if flag then match slot.val with\n    | 0=>(.local 4 5)\n    | 1=>(.local 4 6)\n    | 2=>(.local 4 7)\n    | 3=>(.local 4 8)\n    | 4=>(.local 4 9)\n    | 5=>(.local 4 10)\n    | 6=>(.local 4 11)\n    | 7=>(.local 4 12)\n    | 8=>(.local 4 13)\n    | 9=>(.local 4 14)\n    | 10=>(.local 4 15)\n    | _=>next true true\n  else match slot.val with\n    | 0=>(.local 3 26)\n    | 1=>(.local 3 27)\n    | 2=>(.local 3 28)\n    | 3=>(.local 3 29)\n    | 4=>(.local 3 30)\n    | 5=>(.local 3 31)\n    | 6=>(.local 4 0)\n    | 7=>(.local 4 1)\n    | 8=>(.local 4 2)\n    | 9=>(.local 4 3)\n    | 10=>(.local 4 4)\n    | _=>next true false\nelse\n  if flag then match slot.val with\n    | 0=>(.local 5 17)\n    | 1=>(.local 5 18)\n    | 2=>(.local 5 19)\n    | 3=>(.local 5 20)\n    | 4=>(.local 5 21)\n    | 5=>(.local 5 22)\n    | 6=>(.local 5 23)\n    | 7=>(.local 5 24)\n    | 8=>(.local 5 25)\n    | 9=>(.local 5 26)\n    | 10=>(.local 5 27)\n    | _=>next false true\n  else match slot.val with\n    | 0=>(.local 5 6)\n    | 1=>(.local 5 7)\n    | 2=>(.local 5 8)\n    | 3=>(.local 5 9)\n    | 4=>(.local 5 10)\n    | 5=>(.local 5 11)\n    | 6=>(.local 5 12)\n    | 7=>(.local 5 13)\n    | 8=>(.local 5 14)\n    | 9=>(.local 5 15)\n    | 10=>(.local 5 16)\n    | _=>next false false\n/-- Same actual copies, complete first-match source, result pop, and every cleanup EOF. -/\ndef timeBound (query table:List Bool) (entries:List (List Bool×List Bool)) (unread:List Bool):Nat:=\n  (5*query.length+4)+(5*table.length+4)+(SemiprimeD1StackOwnerLookupExecution.loopTime query entries+2)+1+\n    (query.length+unread.length+11)\n/-- Full physical activation lookup, restoring all eleven callee words before endpoint emit/clear. -/\ntheorem source_trace (owner flag:Bool) (before:Stack→List Bool) (query unread:List Bool)\n    (entries:List (List Bool×List Bool))\n    (hq:before (vertex owner)=query)\n    (hm:before (aux .activationMap)=SemiprimeD1StackOwnerLookup.records entries [])\n    (hc:before (aux .copyScratch)=[]) (hl:∀k,before (lookup k)=[])\n    (hget:SemiprimeD1StackOwnerLookup.result query entries []=([flag],unread)):\n    Runs program (timeBound query (SemiprimeD1StackOwnerLookup.records entries []) entries unread)\n      (pc owner 0) before (next owner flag) before:=by\n  simp only [vertex,aux,lookup] at hq hm hc hl\n  have hsrc:copyStack (if owner then 16 else 18) 0=vertex owner:=by cases owner <;> rfl\n  have hdst:copyStack (if owner then 16 else 18) 1=lookup (.inr .query):=by cases owner <;> rfl\n  let b0:=before\n  let b1:=Function.update b0 (lookup (.inr .query)) (query++[])\n  have h0a:=copy_call (if owner then 16 else 18) (pc owner 0) (pc owner 1)\n    (by cases owner <;> rfl) b0 query []\n    (by cases owner <;> simp at hq <;> simp [b0,aux,lookup,copyStack,copyPorts,hq]) (by cases owner <;> simp at hq <;> simp [b0,aux,lookup,copyStack,copyPorts,hl]) (by cases owner <;> simp at hq <;> simp [b0,aux,copyStack,hc])\n  have h0:Runs program (5*query.length+4) (pc owner 0) b0 (pc owner 1) b1:=by\n    simpa only [hdst] using h0a\n  let b2:=Function.update b1 (lookup (.inr .reader)) (SemiprimeD1StackOwnerLookup.records entries []++[])\n  have h1:Runs program (5*(SemiprimeD1StackOwnerLookup.records entries []).length+4) (pc owner 1) b1 (pc owner 2) b2:=\n    copy_call 17 (pc owner 1) (pc owner 2) (by cases owner <;> rfl) b1 (SemiprimeD1StackOwnerLookup.records entries []) [] (by cases owner <;> simp at hq <;> simp [b0,b1,aux,lookup,copyStack,copyPorts,hm]) (by cases owner <;> simp at hq <;> simp [b0,b1,aux,lookup,copyStack,copyPorts,hl]) (by cases owner <;> simp at hq <;> simp [b0,b1,aux,lookup,copyStack,hc])\n  let b3:=withLookup b2 (SemiprimeD1StackOwnerLookup.done query entries []).data\n  have h2:Runs program (SemiprimeD1StackOwnerLookupExecution.loopTime query entries+2)\n      (pc owner 2) b2 (pc owner 3) b3:=\n    lookup_call (pc owner 2) (pc owner 3) (by cases owner <;> rfl) b2 query entries [] (by\n      intro k;rcases k with k|k <;> cases k <;> simp [b0,b1,b2,lookup,SemiprimeD1StackOwnerLookup.initial,SemiprimeD1StackOwnerLookup.data,SemiprimeD1StackAdder.store,hl])\n  let b4:=Function.update b3 (lookup (.inr .output)) []\n  have h3a:=pop_run (pc owner 3) abort (clearPC owner false 0) (clearPC owner true 0) (lookup (.inr .output)) b3 [flag] (by cases owner <;> rfl) (by cases owner <;> simp at hq <;> simp [b0,b1,b2,b3,lookup,withLookup,SemiprimeD1StackOwnerLookup.done,SemiprimeD1StackOwnerLookup.data,hget])\n  have h3:Runs program 1 (pc owner 3) b3 (clearPC owner flag 0) b4:=by\n    cases flag <;> simpa only [List.head?_cons,List.tail_cons,SemiprimeD1StackBytecode.choose] using h3a\n  let b5:Stack→List Bool:=Function.update b4 (lookup (.inl .left)) []\n  have h4:Runs program (([]:List Bool).length+1) (clearPC owner flag 0) b4 (clearPC owner flag 1) b5:=\n    drain_loop (clearPC owner flag 0) (clearPC owner flag 1) (lookup (.inl .left))\n      (by cases owner <;> cases flag <;> rfl) b4 ([]:List Bool) (by cases owner <;> simp at hq <;> simp [b0,b1,b2,b3,b4,lookup,withLookup,SemiprimeD1StackOwnerLookup.done,SemiprimeD1StackOwnerLookup.data,SemiprimeD1StackAdder.store,hget])\n  let b6:Stack→List Bool:=Function.update b5 (lookup (.inl .right)) []\n  have h5:Runs program (([]:List Bool).length+1) (clearPC owner flag 1) b5 (clearPC owner flag 2) b6:=\n    drain_loop (clearPC owner flag 1) (clearPC owner flag 2) (lookup (.inl .right))\n      (by cases owner <;> cases flag <;> rfl) b5 ([]:List Bool) (by cases owner <;> simp at hq <;> simp [b0,b1,b2,b3,b4,b5,lookup,withLookup,SemiprimeD1StackOwnerLookup.done,SemiprimeD1StackOwnerLookup.data,SemiprimeD1StackAdder.store,hget])\n  let b7:Stack→List Bool:=Function.update b6 (lookup (.inl .scratch)) []\n  have h6:Runs program (([]:List Bool).length+1) (clearPC owner flag 2) b6 (clearPC owner flag 3) b7:=\n    drain_loop (clearPC owner flag 2) (clearPC owner flag 3) (lookup (.inl .scratch))\n      (by cases owner <;> cases flag <;> rfl) b6 ([]:List Bool) (by cases owner <;> simp at hq <;> simp [b0,b1,b2,b3,b4,b5,b6,lookup,withLookup,SemiprimeD1StackOwnerLookup.done,SemiprimeD1StackOwnerLookup.data,SemiprimeD1StackAdder.store,hget])\n  let b8:Stack→List Bool:=Function.update b7 (lookup (.inl .output)) []\n  have h7:Runs program (([]:List Bool).length+1) (clearPC owner flag 3) b7 (clearPC owner flag 4) b8:=\n    drain_loop (clearPC owner flag 3) (clearPC owner flag 4) (lookup (.inl .output))\n      (by cases owner <;> cases flag <;> rfl) b7 ([]:List Bool) (by cases owner <;> simp at hq <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,lookup,withLookup,SemiprimeD1StackOwnerLookup.done,SemiprimeD1StackOwnerLookup.data,SemiprimeD1StackAdder.store,hget])\n  let b9:Stack→List Bool:=Function.update b8 (lookup (.inr .query)) []\n  have h8:Runs program (query.length+1) (clearPC owner flag 4) b8 (clearPC owner flag 5) b9:=\n    drain_loop (clearPC owner flag 4) (clearPC owner flag 5) (lookup (.inr .query))\n      (by cases owner <;> cases flag <;> rfl) b8 query (by cases owner <;> simp at hq <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,lookup,withLookup,SemiprimeD1StackOwnerLookup.done,SemiprimeD1StackOwnerLookup.data,hget])\n  let b10:Stack→List Bool:=Function.update b9 (lookup (.inr .reader)) []\n  have h9:Runs program (unread.length+1) (clearPC owner flag 5) b9 (clearPC owner flag 6) b10:=\n    drain_loop (clearPC owner flag 5) (clearPC owner flag 6) (lookup (.inr .reader))\n      (by cases owner <;> cases flag <;> rfl) b9 unread (by cases owner <;> simp at hq <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,lookup,withLookup,SemiprimeD1StackOwnerLookup.done,SemiprimeD1StackOwnerLookup.data,hget])\n  let b11:Stack→List Bool:=Function.update b10 (lookup (.inr .fieldScratch)) []\n  have h10:Runs program (([]:List Bool).length+1) (clearPC owner flag 6) b10 (clearPC owner flag 7) b11:=\n    drain_loop (clearPC owner flag 6) (clearPC owner flag 7) (lookup (.inr .fieldScratch))\n      (by cases owner <;> cases flag <;> rfl) b10 ([]:List Bool) (by cases owner <;> simp at hq <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,lookup,withLookup,SemiprimeD1StackOwnerLookup.done,SemiprimeD1StackOwnerLookup.data,hget])\n  let b12:Stack→List Bool:=Function.update b11 (lookup (.inr .valid)) []\n  have h11:Runs program (([]:List Bool).length+1) (clearPC owner flag 7) b11 (clearPC owner flag 8) b12:=\n    drain_loop (clearPC owner flag 7) (clearPC owner flag 8) (lookup (.inr .valid))\n      (by cases owner <;> cases flag <;> rfl) b11 ([]:List Bool) (by cases owner <;> simp at hq <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,b11,lookup,withLookup,SemiprimeD1StackOwnerLookup.done,SemiprimeD1StackOwnerLookup.data,hget])\n  let b13:Stack→List Bool:=Function.update b12 (lookup (.inr .copyScratch)) []\n  have h12:Runs program (([]:List Bool).length+1) (clearPC owner flag 8) b12 (clearPC owner flag 9) b13:=\n    drain_loop (clearPC owner flag 8) (clearPC owner flag 9) (lookup (.inr .copyScratch))\n      (by cases owner <;> cases flag <;> rfl) b12 ([]:List Bool) (by cases owner <;> simp at hq <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,b11,b12,lookup,withLookup,SemiprimeD1StackOwnerLookup.done,SemiprimeD1StackOwnerLookup.data,hget])\n  let b14:Stack→List Bool:=Function.update b13 (lookup (.inr .discard)) []\n  have h13:Runs program (([]:List Bool).length+1) (clearPC owner flag 9) b13 (clearPC owner flag 10) b14:=\n    drain_loop (clearPC owner flag 9) (clearPC owner flag 10) (lookup (.inr .discard))\n      (by cases owner <;> cases flag <;> rfl) b13 ([]:List Bool) (by cases owner <;> simp at hq <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,b11,b12,b13,lookup,withLookup,SemiprimeD1StackOwnerLookup.done,SemiprimeD1StackOwnerLookup.data,hget])\n  let b15:Stack→List Bool:=Function.update b14 (lookup (.inr .output)) []\n  have h14:Runs program (([]:List Bool).length+1) (clearPC owner flag 10) b14 (clearPC owner flag 11) b15:=\n    drain_loop (clearPC owner flag 10) (clearPC owner flag 11) (lookup (.inr .output))\n      (by cases owner <;> cases flag <;> rfl) b14 ([]:List Bool) (by cases owner <;> simp at hq <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,b11,b12,b13,b14,lookup,SemiprimeD1StackOwnerLookup.done,hget])\n  have hout:b15=before:=by\n    funext k\n    rcases k with k|k\n    · rcases k with k|k <;> cases k <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,b11,b12,b13,b14,b15,lookup,SemiprimeD1StackOwnerLookup.done,hl,hget]\n    · cases owner <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,b11,b12,b13,b14,b15,lookup,withLookup,SemiprimeD1StackOwnerLookup.done,hget]\n  have hwhole:=join h0 (join h1 (join h2 (join h3 (join h4 (join h5 (join h6 (join h7 (join h8 (join h9 (join h10 (join h11 (join h12 (join h13 (h14))))))))))))))\n  rw [hout] at hwhole\n  have ht:((5*query.length+4))+((5*(SemiprimeD1StackOwnerLookup.records entries []).length+4))+((SemiprimeD1StackOwnerLookupExecution.loopTime query entries+2))+(1)+((([]:List Bool).length+1))+((([]:List Bool).length+1))+((([]:List Bool).length+1))+((([]:List Bool).length+1))+((query.length+1))+((unread.length+1))+((([]:List Bool).length+1))+((([]:List Bool).length+1))+((([]:List Bool).length+1))+((([]:List Bool).length+1))+((([]:List Bool).length+1))=timeBound query (SemiprimeD1StackOwnerLookup.records entries []) entries unread:=by\n    simp only [timeBound,List.length_nil]\n    omega\n  have hlast:clearPC owner flag 11=next owner flag:=by cases owner <;> cases flag <;> rfl\n  rw [hlast] at hwhole\n  simpa only [←ht,Nat.add_assoc] using hwhole\n/-- The actual prior activation source, rather than an input mask, determines the endpoint branch. -/\ntheorem source_from_activation (owner:Bool) (before:Stack→List Bool) (i:Inputs) (coordinate:Nat)\n    (rows:List SemiprimeD1StackChildGroupFactoryActivationLoop.Row) (query:List Bool) (j:Nat)\n    (hj:j<rows.length) (hvalue:SemiprimeBitArithmetic.bitValue query=j)\n    (hq:before (vertex owner)=query)\n    (hm:before (aux .activationMap)=\n      SemiprimeD1StackChildGroupFactoryActivationSource.result i coordinate rows (aux .activationMap))\n    (hc:before (aux .copyScratch)=[]) (hl:∀k,before (lookup k)=[]):\n    let records:=SemiprimeD1StackChildGroupFactoryActivationMap.entries i coordinate [] rows\n    let flag:=(SemiprimeD1StackChildGroupFactoryActivationMap.flags i coordinate rows).getD j false\n    let unread:=(SemiprimeD1StackOwnerLookup.result query records []).2\n    Runs program (timeBound query (SemiprimeD1StackOwnerLookup.records records []) records unread)\n      (pc owner 0) before (next owner flag) before:=by\n  dsimp only\n  let records:=SemiprimeD1StackChildGroupFactoryActivationMap.entries i coordinate [] rows\n  let flag:=(SemiprimeD1StackChildGroupFactoryActivationMap.flags i coordinate rows).getD j false\n  let unread:=(SemiprimeD1StackOwnerLookup.result query records []).2\n  have hmap:before (aux .activationMap)=SemiprimeD1StackOwnerLookup.records records []:=\n    hm.trans (SemiprimeD1StackChildGroupFactoryActivationMap.source_map i coordinate rows)\n  have hflag:(SemiprimeD1StackOwnerLookup.result query records []).1=[flag]:=\n    SemiprimeD1StackChildGroupFactoryActivationMap.lookup_value i coordinate rows [] query j hj\n      (by simpa only [SemiprimeBitArithmetic.bitValue,Nat.zero_add] using hvalue)\n  exact source_trace owner flag before query unread records hq hmap hc hl (Prod.ext hflag rfl)\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryEndpointFlag\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryEndpointSource":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryEndpointLoopView\n/-! # Actual retained-source copies and complete forward endpoint catalogue\nBoth actual cached source tapes are copied, every pair is really parsed and\nqueried, and both chronological vector outputs are physically reversed once.\nThis prefix stops before packet buckets and derived port-order acquisition.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryEndpointSource\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryPrimitives\nopen SemiprimeD1StackProcedureTrace\nnamespace Loop\nexport SemiprimeD1StackChildGroupFactoryEndpointLoop (Row pairs placements Valid result timeBound source_trace)\nend Loop\nnamespace View\nexport SemiprimeD1StackChildGroupFactoryEndpointLoopView\n  (result_other result_oldHistory result_endpointHistory oldRecords selectedRecords)\nend View\nnamespace Parse\nexport SemiprimeD1StackChildGroupFactoryEndpointParse (cleanRoles)\nend Parse\nnamespace Cleanup\nexport SemiprimeD1StackChildGroupFactoryEndpointCleanup (role)\nend Cleanup\n/-- The only initial acquisition operations are two paid copies of the actual retained source tapes. -/\ndef copied (before:Stack→List Bool) (rows:List Loop.Row):Stack→List Bool:=\n  Function.update (Function.update before (aux .pairReader) (Loop.pairs rows))\n    (aux .placementReader) (Loop.placements rows)\n/-- Both actual endpoint catalogues and the full retained physical bank. -/\ndef result (before:Stack→List Bool) (rows:List Loop.Row):Stack→List Bool:=\n  let out:=Loop.result rows (copied before rows)\n  Function.update (Function.update (Function.update (Function.update out\n    (aux .endpointHistory) []) (aux .endpoints) (View.selectedRecords rows++[false]))\n    (aux .oldHistory) []) (aux .oldEndpoints) (View.oldRecords rows++[false])\n/-- All own source clocks, including both copies, both real seed writes and both genuine reversals. -/\ndef timeBound (entries:List (List Bool×List Bool)) (rows:List Loop.Row):Nat:=\n  (5*(Loop.pairs rows).length+4)+(5*(Loop.placements rows).length+4)+Loop.timeBound entries rows+\n    (1+(2*(View.selectedRecords rows).length+3))+(1+(2*(View.oldRecords rows).length+3))\n/-- Complete actual forward endpoint catalogue from retained actual source words, without a mask/edge getter input. -/\ntheorem source_trace (entries:List (List Bool×List Bool)) (rows:List Loop.Row) (before:Stack→List Bool)\n    (hpair:before (aux .occurrences)=Loop.pairs rows) (hplacement:before (aux .placements)=Loop.placements rows)\n    (hp:before (aux .pairReader)=[]) (hm:before (aux .placementReader)=[])\n    (hclean:∀k∈Parse.cleanRoles,before k=[])\n    (hside:before (aux .sideWord)=[]) (hr:before (aux .rowBuffer)=[])\n    (hb:before (aux .frameBuffer)=[]) (hc:before (aux .copyScratch)=[])\n    (hl:∀k,before (lookup k)=[])\n    (hmap:before (aux .activationMap)=SemiprimeD1StackOwnerLookup.records entries [])\n    (heh:before (aux .endpointHistory)=[]) (hoh:before (aux .oldHistory)=[])\n    (heo:before (aux .endpoints)=[]) (hoo:before (aux .oldEndpoints)=[]) (hv:Loop.Valid entries rows):\n    Runs program (timeBound entries rows) (.local 2 18) before (.local 6 17) (result before rows):=by\n  simp only [aux] at heh hoh\n  let c1:=Function.update before (aux .pairReader) (Loop.pairs rows)\n  have h0:=copy_call 14 (.local 2 18) (.local 2 19) rfl before (Loop.pairs rows) [] hpair hp hc\n  simp only [List.append_nil] at h0\n  change Runs program _ _ before _ c1 at h0\n  have h1:=copy_call 15 (.local 2 19) (.local 2 20) rfl c1 (Loop.placements rows) []\n    (by simpa [c1,aux,copyStack,copyPorts] using hplacement) (by simpa [c1,aux,copyStack,copyPorts] using hm) (by simpa [c1,aux,copyStack,copyPorts] using hc)\n  simp only [List.append_nil] at h1\n  change Runs program _ _ _ _ (copied before rows) at h1\n  have h2:=Loop.source_trace entries rows (copied before rows) rfl rfl\n    (by simpa [copied,Parse.cleanRoles,aux,field] using hclean)\n    (by simpa [copied,aux] using hside) (by simpa [copied,aux] using hr)\n    (by simpa [copied,aux] using hb) (by simpa [copied,aux] using hc)\n    (by intro k;simpa [copied,aux,lookup] using hl k)\n    (by simpa [copied,aux] using hmap) hv\n  let out:=Loop.result rows (copied before rows)\n  have hehist:out (aux .endpointHistory)=(View.selectedRecords rows).reverse:=by\n    dsimp only [out]\n    rw [View.result_endpointHistory]\n    simp [copied,aux,heh]\n  have hohist:out (aux .oldHistory)=(View.oldRecords rows).reverse:=by\n    dsimp only [out]\n    rw [View.result_oldHistory]\n    simp [copied,aux,hoh]\n  have heout:out (aux .endpoints)=[]:=by\n    dsimp only [out]\n    rw [View.result_other rows (copied before rows) (aux .endpoints)\n      (by intro j;fin_cases j <;> decide) (by decide) (by decide) (by decide) (by decide)]\n    simpa [copied,aux] using heo\n  have hoout:out (aux .oldEndpoints)=[]:=by\n    dsimp only [out]\n    rw [View.result_other rows (copied before rows) (aux .oldEndpoints)\n      (by intro j;fin_cases j <;> decide) (by decide) (by decide) (by decide) (by decide)]\n    simpa [copied,aux] using hoo\n  let b1:=Function.update out (aux .endpoints) [false]\n  have h3:=push_run (.local 6 13) (.local 6 14) (aux .endpoints) false out rfl\n  rw [heout] at h3\n  have h4:=reverse_call 3 (.local 6 14) (.local 6 15) rfl b1 (View.selectedRecords rows).reverse [false]\n    (by simpa [b1,aux,reverseStack,reversePorts] using hehist) (Function.update_self _ _ _)\n  simp only [List.length_reverse,List.reverse_reverse] at h4\n  change Runs program _ _ b1 _ (Function.update (Function.update b1 (aux .endpointHistory) [])\n    (aux .endpoints) (View.selectedRecords rows++[false])) at h4\n  let b2:=Function.update (Function.update out (aux .endpointHistory) []) (aux .endpoints) (View.selectedRecords rows++[false])\n  have he2:Function.update (Function.update b1 (aux .endpointHistory) [])\n      (aux .endpoints) (View.selectedRecords rows++[false])=b2:=by\n    dsimp only [b1,b2]\n    rw [Function.update_comm (by decide:aux .endpoints≠aux .endpointHistory),Function.update_idem]\n  rw [he2] at h4\n  let b3:=Function.update b2 (aux .oldEndpoints) [false]\n  have hb2old:b2 (aux .oldEndpoints)=[]:=by simpa [b2,aux] using hoout\n  have h5:=push_run (.local 6 15) (.local 6 16) (aux .oldEndpoints) false b2 rfl\n  rw [hb2old] at h5\n  have h6:=reverse_call 4 (.local 6 16) (.local 6 17) rfl b3 (View.oldRecords rows).reverse [false]\n    (by simpa [b3,b2,aux,reverseStack,reversePorts] using hohist) (Function.update_self _ _ _)\n  simp only [List.length_reverse,List.reverse_reverse] at h6\n  change Runs program _ _ b3 _ (Function.update (Function.update b3 (aux .oldHistory) [])\n    (aux .oldEndpoints) (View.oldRecords rows++[false])) at h6\n  have he6:Function.update (Function.update b3 (aux .oldHistory) [])\n      (aux .oldEndpoints) (View.oldRecords rows++[false])=result before rows:=by\n    dsimp only [b3,b2,result]\n    rw [Function.update_comm (by decide:aux .oldEndpoints≠aux .oldHistory),Function.update_idem]\n  rw [he6] at h6\n  have hwhole:=join h0 (join h1 (join h2 (join h3 (join h4 (join h5 h6)))))\n  simpa only [timeBound,Nat.add_assoc] using hwhole\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryEndpointSource\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryEndpointSourceView":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryEndpointSource\n/-! # Exact actual forward-source caller retention and parser restoration -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryEndpointSourceView\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryEndpointSource\nnamespace One\nexport SemiprimeD1StackChildGroupFactoryEndpointOccurrenceView (result_clean)\nend One\n/-- Actual fixed source workspace exclusions; no input-dependent map or answer. -/\nstructure Protected (k:Stack):Prop where\n  raw:∀j,Cleanup.role j≠k\n  pair:k≠aux .pairReader\n  placement:k≠aux .placementReader\n  endpointHistory:k≠aux .endpointHistory\n  endpoints:k≠aux .endpoints\n  oldHistory:k≠aux .oldHistory\n  oldEndpoints:k≠aux .oldEndpoints\n/-- Every protected physical word survives all original repeated endpoint visits and final reversals. -/\ntheorem result_other (before:Stack→List Bool) (rows:List Loop.Row) (k:Stack) (hk:Protected k):\n    result before rows k=before k:=by\n  simp only [result,Function.update_of_ne hk.oldEndpoints,Function.update_of_ne hk.oldHistory,\n    Function.update_of_ne hk.endpoints,Function.update_of_ne hk.endpointHistory]\n  rw [View.result_other _ _ _ hk.raw hk.pair hk.placement hk.oldHistory hk.endpointHistory]\n  simp only [copied,Function.update_of_ne hk.placement,Function.update_of_ne hk.pair]\n/-- The complete actual original-pair loop restores every parser/raw destination. -/\ntheorem loop_clean (rows:List Loop.Row) (before:Stack→List Bool)\n    (hc:∀k∈Parse.cleanRoles,before k=[]):∀k∈Parse.cleanRoles,Loop.result rows before k=[]:=by\n  induction rows generalizing before with\n  | nil=>\n    intro k hk\n    simp only [Parse.cleanRoles,List.mem_cons,List.not_mem_nil,or_false] at hk\n    rcases hk with rfl|rfl|rfl|rfl|rfl|rfl|rfl|rfl|rfl|rfl|rfl\n    all_goals simpa [Loop.result,SemiprimeD1StackChildGroupFactoryEndpointLoop.atEOF,aux,field] using hc _ (by simp [Parse.cleanRoles,aux,field])\n  | cons r rows ih=>exact ih _ (One.result_clean r.ownerFlag r.factorFlag before r.fields _ _ hc)\n/-- The actual whole forward source leaves its complete parser/raw bank clean. -/\ntheorem result_clean (before:Stack→List Bool) (rows:List Loop.Row)\n    (hc:∀k∈Parse.cleanRoles,before k=[]):∀k∈Parse.cleanRoles,result before rows k=[]:=by\n  have hc':∀k∈Parse.cleanRoles,copied before rows k=[]:=by simpa [copied,Parse.cleanRoles,aux,field] using hc\n  have hl:=loop_clean rows (copied before rows) hc'\n  intro k hk\n  simp only [Parse.cleanRoles,List.mem_cons,List.not_mem_nil,or_false] at hk\n  rcases hk with rfl|rfl|rfl|rfl|rfl|rfl|rfl|rfl|rfl|rfl|rfl\n  all_goals simpa [result,aux,field] using hl _ (by simp [Parse.cleanRoles,aux,field])\n/-- The selected endpoint vector is the exact literal emitted forward stream. -/\ntheorem result_endpoints (before:Stack→List Bool) (rows:List Loop.Row):\n    result before rows (aux .endpoints)=View.selectedRecords rows++[false]:=rfl\n/-- The old endpoint vector always includes both sides in original order. -/\ntheorem result_oldEndpoints (before:Stack→List Bool) (rows:List Loop.Row):\n    result before rows (aux .oldEndpoints)=View.oldRecords rows++[false]:=rfl\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryEndpointSourceView\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryFinishBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactorySuffix\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryTraceBounds\n/-! # The actual six-frame final output and complete115-role sweep have linear cost\nEvery allocated private/shadow role is charged to its actual final bank, even\nwhen empty. No output length or cleanup clock is supplied to the finite source.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryFinishBounds\nopen SemiprimeD1StackChildGroupFactoryRoles\nnamespace F\nexport SemiprimeD1StackChildGroupFactoryFinalFrames (buffer result stage timeBound wordRole)\nend F\nnamespace H\nexport SemiprimeD1StackChildGroupFactoryFinish (timeBound)\nend H\n/-- Whole actual six-call frame clock is linear in the complete incoming physical cap. -/\ntheorem frame_time (before:Stack→List Bool) (cap:Nat) (hc:∀k,(before k).length≤cap):\n    F.timeBound before≤36*cap+30:=by\n  have h0:=hc (aux .oldEndpoints)\n  have h1:=hc (aux .orders)\n  have h2:=hc (aux .leftPorts)\n  have h3:=hc (aux .buckets)\n  have h4:=hc (aux .endpoints)\n  have h5:=hc (aux .activation)\n  dsimp only [F.timeBound]\n  omega\n/-- Real preserving frames have only additive literal payload/delimiter growth. -/\ntheorem buffer_length (before:Stack→List Bool) (cap:Nat) (hc:∀k,(before k).length≤cap) (n:Nat):\n    (F.buffer before n).length≤cap+n*(2*cap+1):=by\n  induction n with\n  | zero=>simpa only [F.buffer,Nat.zero_mul,Nat.add_zero] using hc (aux .output)\n  | succ n ih=>\n    have h:=hc (F.wordRole ⟨n%6,Nat.mod_lt _ (by decide)⟩)\n    simp only [F.buffer,SemiprimeSourceHistogramKeyBits.frame_length ]\n    nlinarith\n/-- ALL115 completed frame-source words, not only the public output, are covered. -/\ntheorem frame_word (before:Stack→List Bool) (cap:Nat) (hc:∀k,(before k).length≤cap):\n    ∀k,(F.result before k).length≤13*cap+6:=by\n  have hb:=buffer_length before cap hc 6\n  intro k\n  by_cases h:k=aux .output\n  · subst k\n    simp only [F.result,F.stage,Function.update_self]\n    omega\n  · rw [F.result,F.stage,Function.update_of_ne h]\n    exact (hc k).trans (by omega)\n/-- Generic full finite-store sum, instantiated only after abstract summation. -/\ntheorem finite_word_sum {K:Type} [Fintype K] (words:K→List Bool) (cap:Nat)\n    (hc:∀k,(words k).length≤cap): (∑k,(words k).length)≤Fintype.card K*cap:=by\n  calc\n    _≤∑_k:K,cap:=Finset.sum_le_sum (fun k _=>hc k)\n    _=_:=by simp only [Finset.sum_const,Finset.card_univ,smul_eq_mul]\n/-- SAME actual six-frame output source followed by the literal full physical sweep has linear time. -/\ntheorem timeBound_le (before:Stack→List Bool) (cap:Nat) (hc:∀k,(before k).length≤cap):\n    F.timeBound before+H.timeBound (F.result before)≤1000000*(cap+1):=by\n  have hf:=frame_time before cap hc\n  have hw:=frame_word before cap hc\n  have hm:=finite_word_sum (F.result before) (13*cap+6) hw\n  rw [stack_card] at hm\n  change SemiprimeD1StackChildGroupFactoryCleanup.mass (F.result before)≤115*(13*cap+6) at hm\n  dsimp only [H.timeBound]\n  omega\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryFinishBounds\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativeBuckets":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativeEndpoints\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryCatalogueNumbers\n/-! # Exact original child buckets and their physically generated global numbering\nObserved packet order, empty buckets and repeated raw packet distinctions are\npreserved. Actual binary IDs name the real packet-major endpoint ordinal; no\noriginal occurrence IDs are identified with this separate generated namespace.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativeBuckets\nopen SemiprimeD1StackChildGroupFactory (Inputs)\nnamespace Code\nexport SemiprimeD1StackChildGroupFactoryCatalogueCodecs (buckets)\nend Code\nnamespace Num\nexport SemiprimeD1StackChildGroupFactoryCatalogueNumbers (filtered ordered selected_numbered catalogue_zero)\nend Num\nnamespace Scan\nexport SemiprimeD1StackChildGroupFactoryBucketLoopView (selected)\nend Scan\nnamespace E\nexport SemiprimeD1StackChildGroupFactoryBucketParse (Endpoint)\nend E\nnamespace N\nexport SemiprimeD1StackChildGroupFactoryNativeEndpoints (encode endpoints_original)\nend N\nnamespace Fld\nexport SemiprimeD1StackChildGroupFactoryNativeFields (source fields)\nend Fld\nnamespace Act\nexport SemiprimeD1StackChildGroupFactoryNativeActivation (originalIDs)\nend Act\nnamespace Forward\nexport SemiprimeD1StackChildGroupFactoryForwardBucketsSource (endpoints)\nend Forward\n/-- Actual physical numbering never changes any original endpoint byte. -/\ntheorem selected_fields (es:List E.Endpoint) (packet position:List Bool):\n    (Scan.selected es packet position).map Prod.fst=Num.filtered es packet:=by\n  have h:=congrArg (List.map Prod.fst) (Num.selected_numbered es packet position)\n  simpa only [List.map_map,List.zipIdx_map_fst,Function.comp_def] using h\n/-- Every real chronological bucket retains precisely its literal packet-filtered endpoint stream. -/\ntheorem bucket_fields (packets:List (List Bool)) (es:List E.Endpoint) (position:List Bool):\n    (Code.buckets packets es position).map (fun b=>b.children.map Prod.fst)=packets.map (Num.filtered es):=by\n  induction packets generalizing position with\n  | nil=>rfl\n  | cons p ps ih=>simp only [Code.buckets,List.map_cons,selected_fields,ih]\n/-- Literal whole packet bytes commute with typed endpoint encoding, with no normalization. -/\ntheorem filtered_encoded {V:Nat} (es:List (SemiprimeD1ChildGraph.Endpoint V)) (packet:List Bool):\n    Num.filtered (es.map N.encode) packet=(es.filter (fun e=>decide (e.packet=packet))).map N.encode:=by\n  simp only [Num.filtered,List.filter_map,Function.comp_def,N.encode]\n  rfl\n/-- Every acquired bucket has exactly the original native factor's endpoint bytes, including empty factors. -/\ntheorem factors_original (i:Inputs) (n F a:Nat) (arity:Fin F→Nat)\n    (owner:((e:Fin F)×Fin (arity e))→Fin n) (q:Fin a) (g:Fin 64)\n    (hg:SemiprimeBitArithmetic.bitValue i.group=g.val):\n    (Code.buckets (Fld.source n F a arity owner).state.packets\n      (Forward.endpoints i a q.val (Act.originalIDs n F a arity owner) (Fld.fields n F a arity owner)) []).map\n        (fun b=>b.children.map Prod.fst)=\n      (SemiprimeD1ChildGraph.acquire n F 64 a arity owner q g).factors.map (List.map N.encode):=by\n  rw [bucket_fields,N.endpoints_original i n F a arity owner q g hg]\n  change _=(SemiprimeD1ChildGraph.buckets\n    (SemiprimeD1ChildGraph.acquire n F 64 a arity owner q g).endpoints\n    (Fld.source n F a arity owner).state.packets).value.map (List.map N.encode)\n  rw [SemiprimeD1ChildGraphSemantics.buckets_value,List.map_map]\n  apply List.map_congr_left\n  intro packet _\n  exact filtered_encoded _ _\n/-- Flattening the actual physical bucket view does not discard any counted child. -/\ntheorem flattened_fields (packets:List (List Bool)) (es:List E.Endpoint) (position:List Bool):\n    ((Code.buckets packets es position).flatMap (fun b=>b.children)).map Prod.fst=Num.ordered packets es:=by\n  have h:=congrArg List.flatten (bucket_fields packets es position)\n  simpa only [←List.flatMap_def,List.map_flatMap,Num.ordered] using h\n/-- All actual binary global IDs are exactly the zero-based ORIGINAL child-graph incidence order. -/\ntheorem numbering_original (i:Inputs) (n F a:Nat) (arity:Fin F→Nat)\n    (owner:((e:Fin F)×Fin (arity e))→Fin n) (q:Fin a) (g:Fin 64)\n    (hg:SemiprimeBitArithmetic.bitValue i.group=g.val):\n    ((Code.buckets (Fld.source n F a arity owner).state.packets\n      (Forward.endpoints i a q.val (Act.originalIDs n F a arity owner) (Fld.fields n F a arity owner)) []).flatMap\n        (fun b=>b.children)).map (fun p=>(p.1,SemiprimeBitArithmetic.bitValue p.2))=\n      ((SemiprimeD1ChildGraph.acquire n F 64 a arity owner q g).factors.flatten.map N.encode).zipIdx:=by\n  have h:=congrArg List.flatten (factors_original i n F a arity owner q g hg)\n  simp only [←List.flatMap_def,←List.map_flatMap] at h\n  rw [flattened_fields] at h\n  rw [Num.catalogue_zero,h]\n  congr 1\n  rw [←List.flatMap_id,List.map_flatMap]\n  rfl\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativeBuckets\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativeEndpoints":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativePairs\n/-! # Actual complete forward endpoint catalogue is exactly the original child graph\nThe source emits owner BEFORE factor at each real original incidence, selecting\nboth/one/neither from actual computed colour flags. All raw packet/slot/edge\nbytes and all original repeated incidences retain their exact order.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativeEndpoints\nopen SemiprimeD1StackChildGroupFactory (Inputs)\nnamespace Fld\nexport SemiprimeD1StackChildGroupFactoryNativeFields (source fields)\nend Fld\nnamespace Pair\nexport SemiprimeD1StackChildGroupFactoryNativePairs (paired fieldOf fields_typed source_aligned owner_flag factor_flag)\nend Pair\nnamespace Act\nexport SemiprimeD1StackChildGroupFactoryNativeActivation (originalIDs)\nend Act\nnamespace Forward\nexport SemiprimeD1StackChildGroupFactoryForwardSource (activation rows)\nexport SemiprimeD1StackChildGroupFactoryForwardBucketsSource (endpoints)\nend Forward\nnamespace Keys\nexport SemiprimeD1StackChildGroupFactoryEndpointKeys (row)\nend Keys\nnamespace Code\nexport SemiprimeD1StackChildGroupFactoryCatalogueCodecs (selected side)\nend Code\nnamespace E\nexport SemiprimeD1StackChildGroupFactoryBucketParse (Endpoint)\nend E\nnamespace Native\nexport SemiprimeD1ChildGraph (Endpoint one acquire scan)\nend Native\n/-- Exact five-field encoding of an original typed endpoint; only its bounded vertex key is compact. -/\ndef encode {V:Nat} (e:Native.Endpoint V):E.Endpoint:=\n  ⟨SemiprimeSourceHistogramHeadRefinement.numberKey e.vertex.val,e.packet,e.slot,e.edge,[e.side]⟩\n/-- The real selected endpoint stream is the ordered concatenation of each actual two-sided visit. -/\ntheorem selected_flatMap (rows:List SemiprimeD1StackChildGroupFactoryEndpointLoop.Row):\n    Code.selected rows=rows.flatMap (fun r=>Code.selected [r]):=by\n  induction rows with\n  | nil=>rfl\n  | cons r rs ih=>\n    simp only [Code.selected,List.flatMap_cons,ih,List.append_nil,List.append_assoc]\n/-- One actual parsed occurrence emits exactly the original native two-sided endpoint bytes. -/\ntheorem one_original (i:Inputs) (n F a:Nat) (arity:Fin F→Nat)\n    (owner:((e:Fin F)×Fin (arity e))→Fin n) (q:Fin a) (g:Fin 64)\n    (hg:SemiprimeBitArithmetic.bitValue i.group=g.val)\n    (p:((e:Fin F)×Fin (arity e))×SemiprimeD1PacketInventory.Placement)\n    (hp:p∈Pair.paired n F a arity owner):\n    Code.selected [Keys.row i q.val (Forward.activation a (Act.originalIDs n F a arity owner)) (Pair.fieldOf owner p)]=\n      (Native.one owner (Fld.source n F a arity owner).padding.source.selection.cache.rows.source.dictionary\n        a q.val (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits p.1 p.2).value.map encode:=by\n  have hs:=Pair.source_aligned n F a arity owner p hp\n  have ho:=Pair.owner_flag i n F a arity owner q g hg p\n  have hf:=Pair.factor_flag i n F a arity owner q g hg p\n  have hnative:=SemiprimeD1ChildGraphSemantics.one_original n F 64 a arity owner q g p.1 p.2 hs\n  change Code.selected [_]=(Native.one owner\n    (SemiprimeD1IncidenceAcquisition.acquire n F 64 a arity owner).selection.cache.rows.source.dictionary\n      a q.val (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits p.1 p.2).value.map encode\n  rw [hnative]\n  simp only [Code.selected,Keys.row,Code.side,List.append_nil,List.map_append]\n  simp only [ho,hf,decide_eq_true_eq]\n  split_ifs <;> simp_all only [decide_true,decide_false,ite_true,ite_false,\n    List.nil_append,List.append_nil,List.map_nil,List.map_cons] <;> rfl\n/-- Whole actual forward catalogue equals the ENTIRE original native endpoint list, in exact order. -/\ntheorem endpoints_original (i:Inputs) (n F a:Nat) (arity:Fin F→Nat)\n    (owner:((e:Fin F)×Fin (arity e))→Fin n) (q:Fin a) (g:Fin 64)\n    (hg:SemiprimeBitArithmetic.bitValue i.group=g.val):\n    Forward.endpoints i a q.val (Act.originalIDs n F a arity owner) (Fld.fields n F a arity owner)=\n      (Native.acquire n F 64 a arity owner q g).endpoints.map encode:=by\n  rw [Forward.endpoints,Forward.rows,Pair.fields_typed,List.map_map,selected_flatMap,List.flatMap_map]\n  change _=(Native.scan owner (Fld.source n F a arity owner).padding.source.selection.cache.rows.source.dictionary\n    a q.val (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits\n      ((Fld.source n F a arity owner).padding.source.selection.cache.data.metadata.incidences.zip\n        (Fld.source n F a arity owner).placements)).value.map encode\n  have hports:(Fld.source n F a arity owner).padding.source.selection.cache.data.metadata.incidences=\n      SemiprimeD1CollisionOriginal.ports n F a arity:=\n    SemiprimeD1ChildGraphSemantics.original_ports n F 64 a arity owner\n  rw [hports,SemiprimeD1ChildGraphSemantics.scan_value,List.map_flatMap]\n  apply List.flatMap_congr\n  intro p hp\n  exact one_original i n F a arity owner q g hg p hp\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativeEndpoints\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortsLoopBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortOneBounds\n/-! # Whole actual original-port loop from additive bytes and real nested searches\nThe acquired cache and original records determine every search. Per-query bank\ngrowth is paid by actual answer rows, never by iterated runtime polynomials.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortsLoopBounds\nopen SemiprimeD1StackChildGroupFactoryRoles\nnamespace One\nexport SemiprimeD1StackChildGroupFactoryOldPortOne (result timeBound)\nend One\nnamespace V\nexport SemiprimeD1StackChildGroupFactoryOldPortOneView (result_other)\nend V\nnamespace Loop\nexport SemiprimeD1StackChildGroupFactoryOldPortsLoop (Fresh fresh_step timeBound)\nend Loop\nnamespace P\nexport SemiprimeD1StackChildGroupFactoryOldPortParse (Point records)\nend P\nnamespace B\nexport SemiprimeD1StackChildGroupFactoryLeftPortsLoop (Bucket records)\nend B\nnamespace Bounds\nexport SemiprimeD1StackChildGroupFactoryOldPortOneBounds (pointBytes timeBound_le tag_length)\nend Bounds\nnamespace Search\nexport SemiprimeD1StackChildGroupFactoryTagSearchBounds (bucketBudget outer_time)\nend Search\nnamespace Tag\nexport SemiprimeD1StackChildGroupFactoryTagLoop (timeBound)\nend Tag\nnamespace Build\nexport SemiprimeD1StackChildGroupFactoryTagBuild (rawTag)\nend Build\n/-- Static mathematical allowance for actual nested searches; not a runtime counter or supplier. -/\ndef queryBudget (H D K:Nat):Nat:=(1000*H+10000*(5*H+2*D+1)*(D+1)+2)*(K+1)\n/-- Every actual edge/side query has the same bound from retained physical cache bytes. -/\ntheorem query_time (buckets:List B.Bucket) (p:P.Point) (target:List Bool) (H D:Nat)\n    (hbs:(B.records buckets).length≤H) (hp:Bounds.pointBytes p≤H) (ht:target.length≤H)\n    (hd:(buckets.flatMap (fun b=>b.children)).length≤D):\n    Tag.timeBound buckets target (Build.rawTag p.edge p.side) []≤queryBudget H D buckets.length:=by\n  have hc:=fun p hp=>(SemiprimeD1StackChildGroupFactoryStructuralByteBounds.flattened_child_fields buckets p hp).trans hbs\n  have hh:=fun b hb=>(SemiprimeD1StackChildGroupFactoryStructuralByteBounds.bucket_fields buckets b hb).trans hbs\n  have h:=Search.outer_time buckets target (Build.rawTag p.edge p.side) [] H H D (2*D)\n    hc hh hd (by simp only [List.length_nil,Nat.zero_add];omega)\n  have htag:=Bounds.tag_length p\n  apply h.trans\n  dsimp only [Search.bucketBudget,queryBudget]\n  gcongr\n  omega\n/-- All real queries retain the actual cache, vertex key and empty arithmetic bank. -/\ntheorem step_retained (before:Stack→List Bool) (buckets:List B.Bucket) (p:P.Point) (tail target:List Bool):\n    One.result before buckets p tail target (aux .buckets)=before (aux .buckets) ∧\n    One.result before buckets p tail target (aux .vertexKey)=before (aux .vertexKey) ∧\n    ∀k,One.result before buckets p tail target (arithmetic k)=before (arithmetic k):=by\n  constructor\n  · exact V.result_other _ _ _ _ _ _ (by intro j;fin_cases j <;> decide)\n      (by decide) (by decide) (by decide) (by decide) (by decide)\n  constructor\n  · exact V.result_other _ _ _ _ _ _ (by intro j;fin_cases j <;> decide)\n      (by decide) (by decide) (by decide) (by decide) (by decide)\n  · intro k\n    exact V.result_other _ _ _ _ _ _\n      (by intro j;fin_cases j <;> simp [SemiprimeD1StackChildGroupFactoryTagEarlyClear.role,arithmetic,aux])\n      (by simp [arithmetic,aux]) (by simp [arithmetic,aux]) (by simp [arithmetic,aux])\n      (by simp [arithmetic,aux]) (by simp [arithmetic,aux])\n/-- Whole same-program old-record loop, including every actual failed/missing search and EOF. -/\ntheorem timeBound_le (points:List P.Point) (before:Stack→List Bool) (buckets:List B.Bucket)\n    (target:List Bool) (cap H D:Nat) (hc:∀k,(before k).length≤cap)\n    (hf:Loop.Fresh before) (hr:(P.records points).length≤cap)\n    (hs:before (aux .buckets)=B.records buckets) (ht:before (aux .vertexKey)=target)\n    (ha:∀k,before (arithmetic k)=[]) (hbs:(B.records buckets).length≤H)\n    (hp:∀p∈points,Bounds.pointBytes p≤H) (htarget:target.length≤H)\n    (hd:(buckets.flatMap (fun b=>b.children)).length≤D):\n    Loop.timeBound points before buckets target≤10000000*\n      (cap+points.length*(4*D+2)+3*H+queryBudget H D buckets.length+D+1)*(points.length+1):=by\n  induction points generalizing before cap with\n  | nil=>simp only [Loop.timeBound,List.length_nil,Nat.zero_mul,Nat.add_zero,Nat.zero_add,Nat.mul_one];omega\n  | cons p ps ih=>\n    let Q:=4*D+2\n    have htail: (P.records ps).length≤cap:=\n      (SemiprimeD1StackChildGroupFactoryOldPortsByteBounds.records_tail p ps).trans hr\n    have hstep:=Bounds.timeBound_le before buckets p (P.records ps) target cap D hc htail hf hs ht ha hd\n    have hquery:=query_time buckets p target H D hbs (hp p List.mem_cons_self) htarget hd\n    have hbytes0:=SemiprimeD1StackChildGroupFactoryOldPortsByteBounds.one_word_le before buckets p\n      (P.records ps) target cap hc hf htail\n    have hbytes:∀k,(One.result before buckets p (P.records ps) target k).length≤cap+Q:=by\n      intro k;exact (hbytes0 k).trans (by dsimp only [Q];omega)\n    have hf':=Loop.fresh_step before buckets p (P.records ps) target hf\n    have hret:=step_retained before buckets p (P.records ps) target\n    have ht': (P.records ps).length≤cap+Q:=htail.trans (Nat.le_add_right _ _)\n    have hi:=ih (One.result before buckets p (P.records ps) target) (cap+Q) hbytes hf' ht'\n      (hret.1.trans hs) (hret.2.1.trans ht) (fun k=>(hret.2.2 k).trans (ha k))\n      (fun q h=>hp q (List.mem_cons_of_mem p h))\n    have hh:=hp p List.mem_cons_self\n    simp only [Loop.timeBound,List.length_cons]\n    dsimp only [Q] at hi\n    have he:cap+(4*D+2)+ps.length*(4*D+2)+3*H+queryBudget H D buckets.length+D+1=\n      cap+(ps.length+1)*(4*D+2)+3*H+queryBudget H D buckets.length+D+1:=by ring\n    rw [he] at hi\n    nlinarith\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortsLoopBounds\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryOrderBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryTagIndexMeaning\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortsLoop\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryUnaryScopeBounds\n/-! # Computed original-order words and their actual unary-converter costs\nBinary query counters are bounded by actual reached child occurrences. A\nmissing tag returns the real filtered length; repeated old ports are retained.\nNumeric original N and coefficient values never become unary addresses.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryOrderBounds\nnamespace Meaning\nexport SemiprimeD1StackChildGroupFactoryTagIndexMeaning (tags allTags inner_value outer_value)\nend Meaning\nnamespace V\nexport SemiprimeD1StackChildGroupFactoryTagVisitView (advance hit)\nend V\nnamespace Inner\nexport SemiprimeD1StackChildGroupFactoryTagInnerView (finalPosition)\nend Inner\nnamespace Outer\nexport SemiprimeD1StackChildGroupFactoryTagLoopView (finalPosition)\nend Outer\nnamespace B\nexport SemiprimeD1StackChildGroupFactoryLeftPortsLoop (Bucket)\nend B\nnamespace E\nexport SemiprimeD1StackChildGroupFactoryBucketParse (Endpoint)\nend E\nnamespace P\nexport SemiprimeD1StackChildGroupFactoryOldPortParse (Point)\nend P\nnamespace Old\nexport SemiprimeD1StackChildGroupFactoryOldPortsLoop (orderWords)\nexport SemiprimeD1StackChildGroupFactoryOldPortOneView (answerWord)\nend Old\nopen SemiprimeBitArithmetic (bitValue)\n/-- One real query-counter advance changes raw width by at most two. -/\ntheorem advance_length (e:E.Endpoint) (target position:List Bool):\n    (V.advance e target position).length≤position.length+2:=by\n  by_cases h:bitValue e.vertex=bitValue target\n  · simp only [V.advance,h,ite_true]\n    exact SemiprimeD1StackChildGroupFactoryCounterBounds.successor_length position\n  · simp only [V.advance,h,ite_false];omega\n/-- First-hit short circuit and physical EOF both preserve an actual visit-count width bound. -/\ntheorem inner_length (children:List (E.Endpoint×List Bool)) (target tag position:List Bool):\n    (Inner.finalPosition children target tag position).length≤position.length+2*children.length:=by\n  induction children generalizing position with\n  | nil=>simp only [Inner.finalPosition,List.length_nil,Nat.mul_zero,Nat.add_zero,le_refl]\n  | cons p ps ih=>\n    by_cases hh:V.hit p.1 target tag\n    · simp only [Inner.finalPosition,hh,ite_true,List.length_cons];omega\n    · have ht:=ih (V.advance p.1 target position)\n      have ha:=advance_length p.1 target position\n      simp only [Inner.finalPosition,hh,ite_false,List.length_cons];omega\n/-- Every outer bucket is an actual byte traversal; no search index exceeds all child occurrences. -/\ntheorem outer_length (buckets:List B.Bucket) (target tag position:List Bool):\n    (Outer.finalPosition buckets target tag position).length≤\n      position.length+2*(buckets.flatMap (fun b=>b.children)).length:=by\n  induction buckets generalizing position with\n  | nil=>simp only [Outer.finalPosition,List.flatMap_nil,List.length_nil,Nat.mul_zero,Nat.add_zero,le_refl]\n  | cons b bs ih=>\n    have hi:=inner_length b.children target tag position\n    by_cases hh:SemiprimeD1StackChildGroupFactoryTagInner.found b.children target tag=true\n    · simp only [Outer.finalPosition,hh,ite_true,List.flatMap_cons,List.length_append];omega\n    · have ht:=ih (Inner.finalPosition b.children target tag position)\n      simp only [Outer.finalPosition,hh,Bool.false_eq_true,ite_false,List.flatMap_cons,List.length_append];omega\n/-- Same-vertex tag filtering retains at most the real child count. -/\ntheorem tags_length (children:List (E.Endpoint×List Bool)) (target:List Bool):\n    (Meaning.tags children target).length≤children.length:=by\n  induction children with\n  | nil=>exact le_rfl\n  | cons p ps ih=>\n    by_cases h:bitValue p.1.vertex=bitValue target <;>\n      simp only [Meaning.tags,h,ite_true,ite_false,List.length_cons] <;> omega\n/-- Complete ordered query tag list is bounded by the whole physical child catalogue. -/\ntheorem allTags_length (buckets:List B.Bucket) (target:List Bool):\n    (Meaning.allTags buckets target).length≤(buckets.flatMap (fun b=>b.children)).length:=by\n  induction buckets with\n  | nil=>exact le_rfl\n  | cons b bs ih=>\n    have h:=tags_length b.children target\n    simp only [Meaning.allTags,List.flatMap_cons,List.length_append] at ih ⊢\n    omega\n/-- Every actual answer starts at zero and is bounded in raw width AND numeric value by actual children. -/\ntheorem answer_bounds (buckets:List B.Bucket) (p:P.Point) (target:List Bool):\n    (Old.answerWord buckets p target).length≤2*(buckets.flatMap (fun b=>b.children)).length ∧\n      bitValue (Old.answerWord buckets p target)≤(buckets.flatMap (fun b=>b.children)).length:=by\n  constructor\n  · simpa only [Old.answerWord,List.length_nil,Nat.zero_add] using outer_length buckets target _ []\n  · have h:=Meaning.outer_value buckets target\n      (SemiprimeD1StackChildGroupFactoryTagBuild.rawTag p.edge p.side) []\n    change bitValue (Old.answerWord buckets p target)=_ at h\n    rw [h]\n    simp only [SemiprimeBitArithmetic.bitValue,Nat.zero_add]\n    exact (List.idxOf_le_length).trans (allTags_length buckets target)\n/-- Every matching old port emits once, and every actual duplicate old port remains present. -/\ntheorem order_count (buckets:List B.Bucket) (points:List P.Point) (target:List Bool):\n    (Old.orderWords buckets points target).length≤points.length:=by\n  induction points with\n  | nil=>exact le_rfl\n  | cons p ps ih=>\n    by_cases h:bitValue p.vertex=bitValue target <;>\n      simp only [Old.orderWords,h,ite_true,ite_false,List.length_cons] <;> omega\n/-- Every word passed to real Ordinal12 has this derived bound; no source VALUE bound is assumed. -/\ntheorem order_word_bounds (buckets:List B.Bucket) (points:List P.Point) (target word:List Bool)\n    (hw:word∈Old.orderWords buckets points target):\n    word.length≤2*(buckets.flatMap (fun b=>b.children)).length ∧\n      bitValue word≤(buckets.flatMap (fun b=>b.children)).length:=by\n  induction points with\n  | nil=>simp only [Old.orderWords,List.not_mem_nil] at hw\n  | cons p ps ih=>\n    by_cases h:bitValue p.vertex=bitValue target\n    · simp only [Old.orderWords,h,ite_true,List.mem_cons] at hw\n      rcases hw with rfl|hw\n      · exact answer_bounds buckets p target\n      · exact ih hw\n    · exact ih (by simpa only [Old.orderWords,h,ite_false] using hw)\n/-- The SAME actual unary-converter clock on all computed order IDs is polynomial in physical visit counts. -/\ntheorem ordinal_time (buckets:List B.Bucket) (points:List P.Point) (target:List Bool):\n    SemiprimeD1StackPortOrdinalStreamExecution.timeBound (Old.orderWords buckets points target)≤\n      100*(points.length+1)*(2*(buckets.flatMap (fun b=>b.children)).length+1):=by\n  have h:=SemiprimeD1StackPortOrdinalStreamBounds.timeBound_le (Old.orderWords buckets points target)\n    (2*(buckets.flatMap (fun b=>b.children)).length)\n    (fun w hw=>(order_word_bounds buckets points target w hw).1)\n    (fun w hw=>(order_word_bounds buckets points target w hw).2.trans (by omega))\n  have hc:=order_count buckets points target\n  nlinarith\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryOrderBounds\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryStructuralByteBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryTagSearchBounds\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortParse\n/-! # Raw field lengths from the actual retained nested record tapes\nThese are byte-layout inequalities for actual parsed records. They introduce no\nnew input, decoded-field supplier, or clock. In particular each field is paid by\nthe literal retained tape, even for repeated packets and padded numeric words.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryStructuralByteBounds\nnamespace B\nexport SemiprimeD1StackChildGroupFactoryLeftPortsLoop (Bucket payload records)\nend B\nnamespace I\nexport SemiprimeD1StackChildGroupFactoryLeftPortsInner (Child records)\nend I\nnamespace P\nexport SemiprimeD1StackChildGroupFactoryOldPortParse (Point payload records)\nend P\nnamespace Op\nexport SemiprimeD1StackChildGroupFactoryOperationBounds (endpointBytes)\nend Op\n/-- Every actual six-field child's fields are bounded by its enclosing child tape. -/\ntheorem child_fields (children:List I.Child) (p:I.Child) (hp:p∈children):\n    Op.endpointBytes p.1+p.2.length≤(I.records children).length:=by\n  induction children with\n  | nil=>simp only [List.not_mem_nil] at hp\n  | cons q qs ih=>\n    simp only [List.mem_cons] at hp\n    rcases hp with rfl|hp\n    · simp only [I.records,List.length_cons,SemiprimeSourceHistogramKeyBits.frame_length,\n        SemiprimeD1StackChildGroupFactoryBucketEmit.payload,List.length_nil,Op.endpointBytes]\n      omega\n    · have h:=ih hp\n      simp only [I.records,List.length_cons,SemiprimeSourceHistogramKeyBits.frame_length]\n      omega\n/-- Every real bucket's three physical fields are paid by the retained bucket tape. -/\ntheorem bucket_fields (buckets:List B.Bucket) (b:B.Bucket) (hb:b∈buckets):\n    b.packet.length+(I.records b.children).length+b.ports.length+1≤(B.records buckets).length:=by\n  induction buckets with\n  | nil=>simp only [List.not_mem_nil] at hb\n  | cons q qs ih=>\n    simp only [List.mem_cons] at hb\n    rcases hb with rfl|hb\n    · simp only [B.records,B.payload,SemiprimeD1StackChildGroupFactoryBucketRecord.payload,\n        List.length_cons,SemiprimeSourceHistogramKeyBits.frame_length,List.length_nil]\n      omega\n    · have h:=ih hb\n      simp only [B.records,List.length_cons,SemiprimeSourceHistogramKeyBits.frame_length]\n      omega\n/-- Any actual packet-major child is bounded by the complete retained bucket tape. -/\ntheorem flattened_child_fields (buckets:List B.Bucket) (p:I.Child)\n    (hp:p∈buckets.flatMap (fun b=>b.children)):\n    Op.endpointBytes p.1+p.2.length≤(B.records buckets).length:=by\n  obtain ⟨b,hb,hp⟩:=List.mem_flatMap.mp hp\n  have hc:=child_fields b.children p hp\n  have hh:=bucket_fields buckets b hb\n  omega\n/-- Every original endpoint's actual raw fields are paid by its enclosing tape. -/\ntheorem point_fields (points:List P.Point) (p:P.Point) (hp:p∈points):\n    p.vertex.length+p.edge.length+p.side.length+1≤(P.records points).length:=by\n  induction points with\n  | nil=>simp only [List.not_mem_nil] at hp\n  | cons q qs ih=>\n    simp only [List.mem_cons] at hp\n    rcases hp with rfl|hp\n    · simp only [P.records,P.payload,List.length_cons,SemiprimeSourceHistogramKeyBits.frame_length,List.length_nil]\n      omega\n    · have h:=ih hp\n      simp only [P.records,List.length_cons,SemiprimeSourceHistogramKeyBits.frame_length]\n      omega\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryStructuralByteBounds\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryTagCompleteView":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryTagComplete\n/-! # Complete actual search-answer restoration and cache retention\nAn actual hit really clears eleven unread/current words; exhausted searches\nretain their already empty words. Both paths physically erase answer/counter/tag.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryTagCompleteView\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryTagComplete\nnamespace Log\nexport SemiprimeD1StackChildGroupFactoryWordLog (row)\nend Log\n/-- Every physical cache word outside actual early disposal, three search words and the answer history is retained. -/\ntheorem result_other (found:Bool) (before:Stack→List Bool) (position:List Bool) (k:Stack)\n    (hf:∀j,Early.role j≠k) (ha:k≠aux .answerPosition) (hp:k≠aux .localPosition)\n    (ht:k≠aux .tagWord) (hh:k≠aux .orderHistory):result found before position k=before k:=by\n  simp only [result,Answer.result,Function.update_of_ne ht,Function.update_of_ne hp,\n    Function.update_of_ne ha,Function.update_of_ne hh]\n  cases found with\n  | false=>exact Function.update_of_ne ha _ _\n  | true=>\n    change Early.result (copied before position) k=before k\n    rw [Early.result_other _ _ hf]\n    exact Function.update_of_ne ha _ _\n/-- The actual answer word is physically empty after its real drain. -/\ntheorem result_answer (found:Bool) (before:Stack→List Bool) (position:List Bool):\n    result found before position (aux .answerPosition)=[]:=rfl\n/-- The actual binary local counter is physically empty after its real drain. -/\ntheorem result_local (found:Bool) (before:Stack→List Bool) (position:List Bool):\n    result found before position (aux .localPosition)=[]:=rfl\n/-- The actual old target tag is physically empty after its real drain. -/\ntheorem result_tag (found:Bool) (before:Stack→List Bool) (position:List Bool):\n    result found before position (aux .tagWord)=[]:=rfl\n/-- At a real hit, every one of the eleven actual unread/current tapes is physically erased. -/\ntheorem result_hit_role (before:Stack→List Bool) (position:List Bool) (j:Fin 11):\n    result true before position (Early.role j)=[]:=by fin_cases j <;> rfl\n/-- Exhausted-search finishing preserves the real work words that were already cleared by the actual search. -/\ntheorem result_missing_role (before:Stack→List Bool) (position:List Bool) (j:Fin 11):\n    result false before position (Early.role j)=before (Early.role j):=by fin_cases j <;> rfl\n/-- Exact computed binary index answer in actual original-port log order. -/\ntheorem result_orderHistory (found:Bool) (before:Stack→List Bool) (position:List Bool):\n    result found before position (aux .orderHistory)=\n      (Log.row position).reverse++before (aux .orderHistory):=by\n  have hh:cleared found before position (aux .orderHistory)=before (aux .orderHistory):=by\n    cases found with\n    | false=>rfl\n    | true=>\n      change Early.result (copied before position) (aux .orderHistory)=before (aux .orderHistory)\n      rw [Early.result_other _ _ (by intro j;fin_cases j <;> decide)]\n      rfl\n  change (Log.row position).reverse++cleared found before position (aux .orderHistory)=_\n  rw [hh]\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryTagCompleteView\n","RiemannGaussian.SemiprimeD1StackDescriptorRecordBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackDescriptorRecordExecution\n/-! # Complete loader-to-record clock and every physical source/return prefix -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1600000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackDescriptorRecordBounds\nopen SemiprimeD1StackDescriptorRecord SemiprimeD1StackDescriptorRecordExecution\nopen SemiprimeD1StackDescriptorRecordLoadView\nopen SemiprimeD1StackStaticTableSpec (CheckerTrace)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nvariable {K L : Type} [DecidableEq K] [Fintype K] (s : T.Static K L) (sourceMap : K→Option (Fin 6))\n/-- Sum of ALL actual initial physical words, including old template bytes. -/\ndef inputSize (oldTemplate : K→List Bool) (fields : Fin 6→List Bool) (bank hist out : List Bool) : Nat :=\n  inventory (initial s oldTemplate fields bank hist out).data\n/-- Same full source clock: actual dirty-template load, concrete checker-table\nclock, physical scope conversion and every literal tensor framing byte. -/\ndef runBound (oldTemplate : K→List Bool) (fields : Fin 6→List Bool) (words : List (List Bool))\n    (budget : Nat→Nat) (M : Nat) (hist out : List Bool) : Nat :=\n  prepareBound s oldTemplate fields (vectorBits words) hist out+\n    SemiprimeD1StackStaticTableBounds.runBound s (selected sourceMap fields) words budget+\n    110*(words.length+1)*(M+1)+21*2^words.length+22\nomit [DecidableEq K] in\n/-- The complete actual source's own bit clock; no native bound is transported. -/\ntheorem timeBound_le (oldTemplate : K→List Bool) (fields : Fin 6→List Bool) (words : List (List Bool))\n    (answer : List Bool→Bool) (budget : Nat→Nat) (M : Nat) (hist out : List Bool)\n    (hl : ∀w∈words,w.length≤M) (hv : ∀w∈words,SemiprimeBitArithmetic.bitValue w≤M) :\n    timeBound s sourceMap oldTemplate fields words answer budget hist out≤\n      runBound s sourceMap oldTemplate fields words budget M hist out := by\n  have h:=SemiprimeD1StackStaticRecordClock.timeBound_le s (selected sourceMap fields) words answer budget M hl hv\n  unfold timeBound runBound\n  omega\n/-- A successful actual whole-source halt bounds every successful prefix. -/\ntheorem prefix_fuel_le (oldTemplate : K→List Bool) (fields : Fin 6→List Bool)\n    (hraw : selected sourceMap fields s.raw=[]) (answer : List Bool→Bool) (budget : Nat→Nat)\n    (hc : CheckerTrace s (selected sourceMap fields) answer budget) (words : List (List Bool)) (hist out : List Bool)\n    (fuel : Nat) (finish : C.State (Stack K) (Label L s.roles.length))\n    (hr : C.run (program s sourceMap) fuel (initial s oldTemplate fields (vectorBits words) hist out)=some finish) :\n    fuel≤timeBound s sourceMap oldTemplate fields words answer budget hist out := by\n  obtain ⟨t,ht,he⟩:=source_run s sourceMap oldTemplate fields hraw answer budget hc words hist out\n  have hf:fuel≤t:=by\n    by_contra hn\n    have h:fuel=t+(1+(fuel-(t+1))):=by omega\n    rw [h,SemiprimeD1StackReturnLink.run_add,he,Option.bind_some,SemiprimeD1StackReturnLink.run_add] at hr\n    have hz:C.run (program s sourceMap) 1 (done s sourceMap fields words answer hist out)=none:=rfl\n    rw [hz,Option.bind_none] at hr\n    cases hr\n  exact hf.trans ht\n/-- Every2K+35 actual Boolean data role, all shadows, six source fields,\nloader scratch and every actual nested return cell at EVERY reached prefix. -/\ntheorem prefix_cells (oldTemplate : K→List Bool) (fields : Fin 6→List Bool)\n    (hraw : selected sourceMap fields s.raw=[]) (answer : List Bool→Bool) (budget : Nat→Nat)\n    (hc : CheckerTrace s (selected sourceMap fields) answer budget) (words : List (List Bool)) (hist out : List Bool)\n    (fuel : Nat) (finish : C.State (Stack K) (Label L s.roles.length))\n    (hr : C.run (program s sourceMap) fuel (initial s oldTemplate fields (vectorBits words) hist out)=some finish) :\n    (∑k:Stack K,(finish.data k).length)+finish.frames.length≤\n      (2*Fintype.card K+36)*(inputSize s oldTemplate fields (vectorBits words) hist out+\n        timeBound s sourceMap oldTemplate fields words answer budget hist out+1) := by\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound (program s sourceMap) fuel\n    (inputSize s oldTemplate fields (vectorBits words) hist out) _ finish\n    (cell_le (initial s oldTemplate fields (vectorBits words) hist out).data) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound (program s sourceMap) fuel _ finish hr\n  change finish.frames.length≤0+fuel at hf\n  have hs:(∑k:Stack K,(finish.data k).length)≤\n      (2*Fintype.card K+35)*(inputSize s oldTemplate fields (vectorBits words) hist out+fuel):=by\n    calc\n      _≤∑_k:Stack K,(inputSize s oldTemplate fields (vectorBits words) hist out+fuel):=\n        Finset.sum_le_sum (fun k _=>hd k)\n      _= _:=by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  have ht:=prefix_fuel_le s sourceMap oldTemplate fields hraw answer budget hc words hist out fuel finish hr\n  nlinarith\n/-- Same complete bound for the genuine compiled finite machine itself. -/\ntheorem machine_prefix_cells [Fintype L] (oldTemplate : K→List Bool) (fields : Fin 6→List Bool)\n    (hraw : selected sourceMap fields s.raw=[]) (answer : List Bool→Bool) (budget : Nat→Nat)\n    (hc : CheckerTrace s (selected sourceMap fields) answer budget) (words : List (List Bool)) (hist out : List Bool)\n    (fuel : Nat) (cfg : (machine s sourceMap).Cfg)\n    (hr : (fun q=>q.bind (machine s sourceMap).step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial s oldTemplate fields (vectorBits words) hist out)))=some cfg) :\n    (∑k:Stack K,(cfg.stk (some k)).length)+(cfg.stk none).length≤\n      (2*Fintype.card K+36)*(inputSize s oldTemplate fields (vectorBits words) hist out+\n        timeBound s sourceMap oldTemplate fields words answer budget hist out+1) := by\n  have he:=SemiprimeD1StackCalls.run_correct original output (.inl .start) (program s sourceMap) fuel\n    (initial s oldTemplate fields (vectorBits words) hist out)\n  have hh:(C.run (program s sourceMap) fuel (initial s oldTemplate fields (vectorBits words) hist out)).map\n    SemiprimeD1StackCalls.configuration=some cfg:=he.trans hr\n  cases hrun:C.run (program s sourceMap) fuel (initial s oldTemplate fields (vectorBits words) hist out) with\n  | none=>rw [hrun] at hh;cases hh\n  | some finish=>\n    rw [hrun] at hh\n    have heq:SemiprimeD1StackCalls.configuration finish=cfg:=Option.some.inj hh\n    subst cfg\n    exact prefix_cells s sourceMap oldTemplate fields hraw answer budget hc words hist out fuel finish hrun\n/-- All actual Boolean/remembered-return flags are finite before N. -/\ntheorem control_finite [Fintype L] : Finite (machine s sourceMap).σ :=\n  SemiprimeD1StackCalls.control_finite original output (.inl .start) (program s sourceMap)\n/-- Every physical data and actual return-stack alphabet is finite. -/\ntheorem all_alphabets_finite [Fintype L] (k : (machine s sourceMap).K) : Finite ((machine s sourceMap).Γ k) :=\n  SemiprimeD1StackCalls.all_alphabets_finite original output (.inl .start) (program s sourceMap) k\n/-- All actual component instructions compile to at most four primitive commands. -/\ntheorem compile_depth [Fintype L] (pc : Label L s.roles.length) :\n    SemiprimeD1StackBytecode.statementDepth ((machine s sourceMap).m pc)≤4 :=\n  SemiprimeD1StackCalls.compile_depth (.inl .start : Label L s.roles.length) (program s sourceMap pc)\nend RiemannGaussian.SemiprimeD1StackDescriptorRecordBounds\n","RiemannGaussian.SemiprimeD1StackDigitBlockBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackDigitBlockExecution\n\n/-! # Whole streaming block prefix storage\nHigh input and cached width remain live deliberately. Their cells and every\ntemporary/return cell are included in the actual executed prefix bound.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 500000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackDigitBlockBounds\nopen SemiprimeD1StackDigitBlock SemiprimeD1StackDigitBlockExecution\n\n/-- Successful source prefixes cannot continue beyond the genuine proved halt. -/\ntheorem prefix_fuel_le (word width : List Bool) (fuel : ℕ) (out : C.State Stack Label)\n    (hr : C.run program fuel\n      (⟨some .start,none,none,store word width [] [] [] [] [] [],[]⟩:C.State Stack Label)=some out) :\n    fuel ≤ 8*width.length+5*word.length+11 := by\n  have hf : fuel ≤ totalTime word width := by\n    by_contra hn\n    have he : fuel=totalTime word width+(1+(fuel-(totalTime word width+1))) := by omega\n    rw [he,SemiprimeD1StackReturnLink.run_add,source_run,Option.bind_some,\n      SemiprimeD1StackReturnLink.run_add] at hr\n    have hz : C.run program 1\n      (⟨none,none,none,store (word.drop width.length) width [] [] [] [] [] (result word width),[]⟩:\n        C.State Stack Label)=none := rfl\n    rw [hz,Option.bind_none] at hr\n    cases hr\n  exact hf.trans (totalTime_le word width)\n\n/-- Every visited source configuration counts the retained input/cache too. -/\ntheorem prefix_cells (word width : List Bool) (fuel : ℕ) (out : C.State Stack Label)\n    (hr : C.run program fuel\n      (⟨some .start,none,none,store word width [] [] [] [] [] [],[]⟩:C.State Stack Label)=some out) :\n    (∑k : Stack,(out.data k).length)+out.frames.length ≤\n      9*(6*word.length+9*width.length+11) := by\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel (word.length+width.length)\n    _ out (by intro k;cases k <;> simp only [store,List.length_nil] <;> omega) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ out hr\n  change out.frames.length ≤ 0+fuel at hf\n  have hs : (∑k : Stack,(out.data k).length) ≤ 8*(word.length+width.length+fuel) := by\n    calc\n      _ ≤ ∑_k : Stack,(word.length+width.length+fuel) := Finset.sum_le_sum (fun k _=>hd k)\n      _ = _ := by\n        have hc : Fintype.card Stack=8 := by decide\n        simp only [Finset.sum_const,Finset.card_univ,hc,smul_eq_mul]\n  have ht:=prefix_fuel_le word width fuel out hr\n  omega\n\n/-- The same total storage bound holds on EVERY actual target-machine prefix. -/\ntheorem machine_prefix_cells (word width : List Bool) (fuel : ℕ) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration\n        (⟨some .start,none,none,store word width [] [] [] [] [] [],[]⟩:C.State Stack Label)))=some cfg) :\n    (∑k : Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤\n      9*(6*word.length+9*width.length+11) := by\n  let start : C.State Stack Label:=⟨some .start,none,none,store word width [] [] [] [] [] [],[]⟩\n  have he:=SemiprimeD1StackCalls.run_correct Stack.input Stack.output Label.start program fuel start\n  change (C.run program fuel start).map SemiprimeD1StackCalls.configuration=\n    (fun q=>q.bind machine.step)^[fuel] (some (SemiprimeD1StackCalls.configuration start)) at he\n  rw [hr] at he\n  cases hc:C.run program fuel start with\n  | none => rw [hc] at he;cases he\n  | some out =>\n    rw [hc] at he\n    have hcfg : SemiprimeD1StackCalls.configuration out=cfg := Option.some.inj he\n    subst cfg\n    exact prefix_cells word width fuel out hc\n\nend RiemannGaussian.SemiprimeD1StackDigitBlockBounds\n","RiemannGaussian.SemiprimeD1StackDigitCountExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackDigitCountLoop\n\n/-! # Complete physical cached-record counting\nThe only input of this internal machine is the actual cached byte vector.\nIt acquires the reader by a real Copy and counts records by actual parser\ncalls. The graph frontend will supply the cache from original N acquisition.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 16000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackDigitCountExecution\nopen SemiprimeD1StackDigitCount SemiprimeD1StackDigitCountComponents SemiprimeD1StackDigitCountLoop\nopen SemiprimeD1StackProcedureFragments (At Runs)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\n\n/-- Actual bank-only input; no record count or reader is supplied. -/\ndef initial (bank:List Bool) : C.State Stack Label := ⟨some (.inl .main),none,none,data bank [] [] [] [] [] [],[]⟩\n/-- Actual acquired unary count with the original cached bytes retained. -/\ndef done (words:List (List Bool)) : C.State Stack Label :=\n  ⟨none,none,none,data (vectorBits words) [] (List.replicate words.length true) [] [] [] [],[]⟩\n/-- Exact complete transition count, including copy and final halt. -/\ndef totalTime (words:List (List Bool)) : ℕ := 5*(vectorBits words).length+4+loopTime words+1\n\n/-- Reusable actual cache-count stage before final halt, retaining the entire source cache. -/\ntheorem ready (words:List (List Bool)) :\n    Runs program (5*(vectorBits words).length+4+loopTime words) (.inl .main)\n      (data (vectorBits words) [] [] [] [] [] []) (.inl .halt)\n      (data (vectorBits words) [] (List.replicate words.length true) [] [] [] []) := by\n  have h:=(copy_call (vectorBits words)).trans (loop_run words (vectorBits words) [])\n  simpa only [List.append_nil] using h\n\n/-- The whole physical scanner acquires the exact count; zero-valued empty fields still count. -/\ntheorem acquire_run (words:List (List Bool)) :\n    C.run program (totalTime words) (initial (vectorBits words))=some (done words) := by\n  obtain ⟨finish,hfinish,hout⟩:=ready words [] (initial (vectorBits words)) ⟨rfl,rfl,rfl⟩\n  unfold totalTime\n  rw [SemiprimeD1StackReturnLink.run_add,hfinish,Option.bind_some]\n  rcases hout with ⟨hpc,hdata,hframes⟩\n  change C.step program finish=some (done words)\n  simp [C.step,SemiprimeD1StackCalls.step,hpc,program,C.execute,SemiprimeD1StackCalls.execute,hdata,hframes,done]\n\n/-- One actual whole-cache linear transition bound. -/\ntheorem totalTime_le (words:List (List Bool)) : totalTime words≤11*(vectorBits words).length+5 := by\n  have h:=loopTime_le words\n  unfold totalTime\n  omega\n\n/-- Actual initialization uses only cache bytes, never a count/field-value answer. -/\ntheorem initial_eq (bank:List Bool) :\n    Turing.initList machine bank=SemiprimeD1StackCalls.configuration (initial bank) := by\n  have he:initial bank=SemiprimeD1StackCalls.initial Stack.bank (.inl .main) bank:=by\n    dsimp only [initial,SemiprimeD1StackCalls.initial]\n    congr 1\n    funext k\n    cases k <;> simp [data]\n  rw [he]\n  exact (SemiprimeD1StackCalls.initial_correct Stack.bank Stack.count (.inl .main) program bank).symm\n\n/-- Real finite-machine time from an actually acquired well-formed cache, not from its count. -/\ndef countInTime (words:List (List Bool)) :\n    StateTransition.EvalsToInTime machine.step (Turing.initList machine (vectorBits words))\n      (some (SemiprimeD1StackCalls.configuration (done words))) (11*(vectorBits words).length+5) := by\n  rw [initial_eq]\n  apply SemiprimeD1StackCalls.evalsCorrect Stack.bank Stack.count (.inl .main) program\n  exact ⟨⟨totalTime words,acquire_run words⟩,totalTime_le words⟩\nend RiemannGaussian.SemiprimeD1StackDigitCountExecution\n","RiemannGaussian.SemiprimeD1StackEdgeCatalogueTransduction":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackEdgeCatalogueScan\n\n/-! # Complete actual edge transduction and final tape reversal -/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 16000\nset_option synthInstance.maxSize 8192\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackEdgeCatalogueTransduction\nopen SemiprimeD1StackEdgeCatalogue SemiprimeD1StackEdgeCatalogueComponents\nopen SemiprimeD1StackEdgeCatalogueView SemiprimeD1StackEdgeCatalogueEmit SemiprimeD1StackEdgeCatalogueScan\nopen SemiprimeD1StackProcedureFragments (Runs one_base)\nopen SemiprimeD1EdgeCatalogueEncoding (Record record half selected tape output)\nopen SemiprimeSourceHistogramKeyBits (frame frame_length)\n\n/-- Final physical data: consumed source descriptors, retained metadata, actual edge tape. -/\ndef finalData (base:Cat.Stack→List Bool) (edges:List Bool) : Stack→List Bool :=\n  Function.update (clean base [] (fun _=>[]) [] []) (aux .output) edges\n/-- Exact emitted pair byte count. -/\ntheorem pair_length (words:Record) :\n    (half false words (half true words [])).length=2*(record words []).length+4 := by\n  simp only [half,SemiprimeD1EdgeCatalogueEncoding.sideWord,Bool.false_eq_true,ite_false,\n    ite_true,List.length_cons,List.length_nil,frame_length,record_length]\n  omega\n/-- Emitting both half edges never needs a supplied output-byte bound. -/\ntheorem output_length (records:List Record) : (output records []).length≤3*(tape records []).length := by\n  induction records with\n  | nil => simp [output,tape]\n  | cons words rest ih =>\n    change (if selected words then half false words (half true words (output rest [])) else output rest []).length≤\n      3*(record words (tape rest [])).length\n    rw [record_append,List.length_append,mul_add]\n    by_cases hs:selected words\n    · rw [ite_eq_left hs,pair_append,List.length_append,pair_length]\n      have hm:5≤(record words []).length:=by rw [record_length,List.length_nil];omega\n      omega\n    · rw [ite_eq_right hs]\n      omega\n/-- Actual EOF peek on the physically consumed descriptor tape. -/\ntheorem eof_run (base:Cat.Stack→List Bool) (raw:List Bool) :\n    Runs program 1 (.inl .parse) (clean base [] (fun _=>[]) raw [])\n      (.inl .finalReverse) (clean base [] (fun _=>[]) raw []) := by\n  apply one_base program _ _ (.peek reader (.inl .finalReverse) (.inl (.field 0)) (.inl (.field 0))) _ _ rfl\n  · rfl\n  · rfl\n/-- The WHOLE real transducer, including final reversal, not merely its per-record loop. -/\ntheorem ready (base:Cat.Stack→List Bool) (records:List Record) :\n    ∃time≤56*(tape records []).length+4,Runs program time (.inl .parse)\n      (clean base (tape records []) (fun _=>[]) [] []) (.inl .halt) (finalData base (output records [])) := by\n  obtain ⟨time,ht,h0⟩:=scan_run base records []\n  rw [List.append_nil] at h0\n  have h1:=eof_run base (output records []).reverse\n  have h2:=reverse_call true (clean base [] (fun _=>[]) (output records []).reverse [])\n    (.inl .finalReverse) (.inl .halt) rfl\n  change Runs program (2*(output records []).reverse.length+3) _ _ _\n    (Function.update (Function.update (clean base [] (fun _=>[]) (output records []).reverse [])\n      (aux .reversed) []) (aux .output) ((output records []).reverse.reverse++[])) at h2\n  rw [List.length_reverse,List.reverse_reverse,List.append_nil,clean_raw] at h2\n  have h:=h0.trans (h1.trans h2)\n  refine ⟨time+(1+(2*(output records []).length+3)),?_,h⟩\n  have ho:=output_length records\n  omega\nend RiemannGaussian.SemiprimeD1StackEdgeCatalogueTransduction\n","RiemannGaussian.SemiprimeD1StackEuclidGCDSpec":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackEuclidGCD\nimport RiemannGaussian.SemiprimeD1StackSourceEnvironmentEncoding\n/-! # Meaning of the actual byte-fuel Euclid loop\nThe recursive interpretation and natural fuel below are proof objects only.\nThe fixed source obtains every fuel marker by scanning its retained inputs.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackEuclidGCDSpec\nopen SemiprimeBitArithmetic (bitValue)\nopen SemiprimeSourceCompactBits (Compact)\nopen SemiprimeD1StackSourceEnvironmentEncoding (normalize normalize_value normalize_compact normalize_length)\n/-- Proof interpretation of the actual public output and actual fuel-abort branch. -/\nstructure Outcome where\n  /-- Compact actual result word. -/\n  word:List Bool\n  /-- True means the physical fuel-empty branch would be taken. -/\n  exhausted:Bool\n/-- Interpretation of literal positive divisions, physical Euclid swaps and trimming. -/\ndef iterate :Nat→List Bool→List Bool→Outcome\n  | 0,x,_=>⟨normalize x,true⟩\n  | n+1,x,y=>if y=[] then ⟨normalize x,false⟩ else\n      iterate n y (normalize (SemiprimeBitDivision.divideLoop x y).remainder)\n/-- Exactly two physically pushed markers per original input byte and one literal terminal marker. -/\ndef fuelLength (left right:List Bool) :Nat:=2*(left.length+right.length)+1\n/-- Source output interpretation from the two actual original words. -/\ndef answer (left right:List Bool) :Outcome:=iterate (fuelLength left right) left (normalize right)\n/-- Compact numeric zero is physically empty, including after an all-zero padded input. -/\ntheorem compact_zero (word:List Bool) (hc:Compact word) :bitValue word=0 ↔ word=[] :=by\n  constructor\n  · intro h\n    exact SemiprimeSourceCompactWordIds.compact_value_injective word [] hc trivial h\n  · intro h;rw [h];rfl\n/-- A nonempty trimmed actual divisor is a genuinely positive numeric divisor. -/\ntheorem compact_positive (word:List Bool) (hc:Compact word) (hne:word≠[]) :0<bitValue word:=by\n  have hz:bitValue word≠0:=fun h=>hne ((compact_zero word hc).mp h)\n  omega\n/-- Every returned interpretation is compact even for insufficient proof-side fuel. -/\ntheorem iterate_compact (n:Nat) (x y:List Bool) :Compact (iterate n x y).word:=by\n  induction n generalizing x y with\n  | zero=>exact normalize_compact x\n  | succ n ih=>\n    simp only [iterate]\n    split\n    · exact normalize_compact x\n    · exact ih _ _\n/-- Numeric words and exhaustion agree with the legacy finite-fuel Euclid semantics.\nThis is only a value/termination proof, never a transport of its report clock. -/\ntheorem legacy_correspond (n:Nat) (x y rawX rawY:List Bool) (hc:Compact y)\n    (hx:bitValue x=bitValue rawX) (hy:bitValue y=bitValue rawY) :\n    bitValue (iterate n x y).word=bitValue (SemiprimeBitGcd.gcdLoop rawX rawY (List.replicate n ())).bits ∧\n    (iterate n x y).exhausted=(SemiprimeBitGcd.gcdLoop rawX rawY (List.replicate n ())).exhausted :=by\n  induction n generalizing x y rawX rawY with\n  | zero=>exact ⟨(normalize_value x).trans hx,rfl⟩\n  | succ n ih=>\n    by_cases hz:y=[]\n    · have hv:bitValue rawY=0:=by rw [←hy,hz];rfl\n      have hb:¬(SemiprimeBitDivision.nonzeroBits rawY).nonzero=true:=by\n        intro h;have hp:=(SemiprimeBitDivision.nonzeroBits_correct rawY).mp h;omega\n      simp only [iterate,hz,ite_true,List.replicate_succ,SemiprimeBitGcd.gcdLoop,ite_eq_right hb]\n      exact ⟨(normalize_value x).trans hx,trivial⟩\n    · have hp:=compact_positive y hc hz\n      have hb:(SemiprimeBitDivision.nonzeroBits rawY).nonzero=true:=\n        (SemiprimeBitDivision.nonzeroBits_correct rawY).mpr (by omega)\n      have hr:bitValue (normalize (SemiprimeBitDivision.divideLoop x y).remainder)=\n          bitValue (SemiprimeBitDivision.divideBits rawX rawY).remainder:=by\n        rw [normalize_value,(SemiprimeD1StackDividerExecution.output_values x y hp).2,\n          (SemiprimeBitDivision.divideBits_correct rawX rawY).2,hx,hy]\n      simpa only [iterate,ite_eq_right hz,List.replicate_succ,SemiprimeBitGcd.gcdLoop,ite_eq_left hb] using\n        ih y (normalize (SemiprimeBitDivision.divideLoop x y).remainder) rawY\n          (SemiprimeBitDivision.divideBits rawX rawY).remainder (normalize_compact _) hy hr\n/-- The physically acquired byte fuel suffices for every original binary word, including padded zero. -/\ntheorem answer_stopped (left right:List Bool) :(answer left right).exhausted=false:=by\n  have h:=legacy_correspond (fuelLength left right) left (normalize right) left right\n    (normalize_compact right) rfl (normalize_value right)\n  have hs:=(SemiprimeBitGcd.gcdLoop_stops_pow right.length left right\n    (List.replicate (fuelLength left right) ()) (SemiprimeBitArithmetic.bitValue_lt_width right)\n    (by simp only [List.length_replicate,fuelLength];omega)).1\n  exact h.2.trans hs\n/-- The actual source's compact output represents the exact mathematical GCD. -/\ntheorem answer_value (left right:List Bool) :\n    bitValue (answer left right).word=(bitValue left).gcd (bitValue right):=by\n  have h:=legacy_correspond (fuelLength left right) left (normalize right) left right\n    (normalize_compact right) rfl (normalize_value right)\n  have hs:(SemiprimeBitGcd.gcdLoop left right (List.replicate (fuelLength left right) ())).exhausted=false:=\n    h.2.symm.trans (answer_stopped left right)\n  exact h.1.trans (SemiprimeBitGcd.gcdLoop_correct_of_stopped _ _ _ hs)\n/-- Required byte ABI: exact compact normalization of the legacy GCD result, without its arbitrary input padding. -/\ntheorem answer_legacy_bits (left right:List Bool) :\n    (answer left right).word=normalize (SemiprimeBitGcd.gcdBits left right).bits:=by\n  apply SemiprimeSourceCompactWordIds.compact_value_injective _ _ (iterate_compact _ _ _) (normalize_compact _)\n  change bitValue (answer left right).word=_\n  rw [answer_value,normalize_value,(SemiprimeBitGcd.gcdBits_correct left right).1]\nend RiemannGaussian.SemiprimeD1StackEuclidGCDSpec\n","RiemannGaussian.SemiprimeD1StackExpr":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackExprLiteralBounds\nimport RiemannGaussian.SemiprimeD1StackResidueAddBounds\nimport RiemannGaussian.SemiprimeD1StackResidueSubBounds\nimport RiemannGaussian.SemiprimeD1StackResidueMulBounds\nimport RiemannGaussian.SemiprimeD1StackFrame\nimport RiemannGaussian.SemiprimeD1StackRecursiveCallTrace\n/-! # Closed physical prefix arithmetic expression evaluator\nOnly physical code/cache/operand words enter the program. Recursive evaluation\nuses real finite-label call/return frames, framed saved values, and the literal\ncomplete Add/Sub/Mul procedures. No Expr/Nat/List/function is stored in control.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option synthInstance.maxSize 4096\nnamespace RiemannGaussian.SemiprimeD1StackExpr\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State execute step run)\nend C\nnamespace Lit\nexport SemiprimeD1StackExprLiteral (Stack Label program inputCode output ctl input)\nend Lit\nnamespace Add\nexport SemiprimeD1StackResidueAdd (Stack Label program modulus output input initial)\nend Add\nnamespace Sub\nexport SemiprimeD1StackResidueSub (Stack Label program modulus output input initial)\nend Sub\nnamespace Mul\nexport SemiprimeD1StackResidueMul (Stack Label program modulus output input initial)\nend Mul\nnamespace Field\nexport SemiprimeD1TensorTapeFieldBytecode (Stack Label code active)\nend Field\n\n/-- Only three fixed operator cases are carried by continuation labels. -/\ninductive Op | add | sub | mul deriving DecidableEq,Repr,Inhabited\ninstance : Fintype Op where\n  elems := {.add,.sub,.mul}\n  complete := by intro op;cases op <;> simp\n/-- Shared physical roles and disjoint complete private component banks. -/\ninductive Stack where\n  | code | modulus | saved | result | left | right | flag | scratch\n  | literal (k : Lit.Stack) | addition (k : Add.Stack)\n  | subtraction (k : Sub.Stack) | multiplication (k : Mul.Stack)\n  deriving DecidableEq,Fintype\n/-- Fixed real recursive and component locations, independent of syntax size. -/\ninductive Label where\n  | start | eval | secondLow | secondHigh | literalCall | returnPC | done | bad\n  | begin (op : Op) | saveLeft (op : Op) | clearLeft (op : Op)\n  | rightEval (op : Op) | copyRight (op : Op) | clearRight (op : Op)\n  | readLeft (op : Op) | checkLeft (op : Op) | applyOp (op : Op)\n  | literal (pc : Lit.Label) | addition (pc : Add.Label)\n  | subtraction (pc : Sub.Label) | multiplication (pc : Mul.Label)\n  | frame (pc : Fin 11) | copy (pc : Fin 9) | field (pc : Field.Label)\n  deriving DecidableEq,Fintype\n\n/-- Literal input/cache/output share the actual caller's roles, not copies or getters. -/\ndef literalStack (k : Lit.Stack) : Stack :=\n  if k=Lit.inputCode then .code else\n  if k=.inl SemiprimeD1StackExprLiteral.Fit.template then .modulus else\n  if k=Lit.output then .result else .literal k\n/-- The real first addition operand. -/\ndef addLeft : Add.Stack := .inl .left\n/-- The real second addition operand. -/\ndef addRight : Add.Stack := .inl .right\n/-- Actual addition wiring with all other roles private. -/\ndef addStack (k : Add.Stack) : Stack :=\n  if k=addLeft then .left else if k=addRight then .right else\n  if k=Add.modulus then .modulus else if k=Add.output then .result else .addition k\n/-- The real first subtraction operand. -/\ndef subLeft : Sub.Stack := .inl .left\n/-- The real second subtraction operand. -/\ndef subRight : Sub.Stack := .inr (.inl .right)\n/-- Actual subtraction wiring; both internal modulus copies remain real operations. -/\ndef subStack (k : Sub.Stack) : Stack :=\n  if k=subLeft then .left else if k=subRight then .right else\n  if k=Sub.modulus then .modulus else if k=Sub.output then .result else .subtraction k\n/-- The real first multiplication operand. -/\ndef mulLeft : Mul.Stack := .inl SemiprimeD1StackResidueMul.M.input\n/-- The real second multiplication operand. -/\ndef mulRight : Mul.Stack := .inl SemiprimeD1StackResidueMul.M.factor\n/-- Actual multiplication wiring, including its real restoring divider. -/\ndef mulStack (k : Mul.Stack) : Stack :=\n  if k=mulLeft then .left else if k=mulRight then .right else\n  if k=Mul.modulus then .modulus else if k=Mul.output then .result else .multiplication k\n/-- Actual left-result frame append into the physical saved-value stack. -/\ndef frameStack (k : Fin 3) : Stack := if k=0 then .result else if k=1 then .saved else .scratch\n/-- Actual right-result copy into its arithmetic operand slot. -/\ndef copyStack (k : Fin 3) : Stack := if k=0 then .result else if k=1 then .right else .scratch\n/-- Actual saved-left field parser, with a physically produced validity bit. -/\ndef fieldStack : Field.Stack→Stack\n  | .inl .input=>.saved | .inl .scratch=>.scratch | .inl .output=>.left | .inr _=>.flag\n\n/-- ONE closed instruction table. Recursive calls really target this same .eval. -/\ndef program : Label→C.Instruction Stack Label\n  | .start=>.call .eval .done\n  | .eval=>.base (.pop .code .bad .secondLow .secondHigh)\n  | .secondLow=>.base (.pop .code .bad .literalCall (.begin .add))\n  | .secondHigh=>.base (.pop .code .bad (.begin .sub) (.begin .mul))\n  | .literalCall=>.call (.literal (Lit.ctl .fieldCall)) .returnPC\n  | .begin op=>.call .eval (.saveLeft op)\n  | .saveLeft op=>.call (.frame 0) (.clearLeft op)\n  | .clearLeft op=>.base (.pop .result (.rightEval op) (.clearLeft op) (.clearLeft op))\n  | .rightEval op=>.call .eval (.copyRight op)\n  | .copyRight op=>.call (.copy 0) (.clearRight op)\n  | .clearRight op=>.base (.pop .result (.readLeft op) (.clearRight op) (.clearRight op))\n  | .readLeft op=>.call (.field (Field.active .tagPop (none,false))) (.checkLeft op)\n  | .checkLeft op=>.base (.pop .flag .bad .bad (.applyOp op))\n  | .applyOp .add=>.call (.addition .start) .returnPC\n  | .applyOp .sub=>.call (.subtraction .start) .returnPC\n  | .applyOp .mul=>.call (.multiplication .start) .returnPC\n  | .returnPC=>.ret\n  | .done | .bad=>.base .halt\n  | .literal pc=>SemiprimeD1StackValidationLink.instruction literalStack Label.literal (Lit.program pc)\n  | .addition pc=>SemiprimeD1StackValidationLink.instruction addStack Label.addition (Add.program pc)\n  | .subtraction pc=>SemiprimeD1StackValidationLink.instruction subStack Label.subtraction (Sub.program pc)\n  | .multiplication pc=>SemiprimeD1StackValidationLink.instruction mulStack Label.multiplication (Mul.program pc)\n  | .frame pc=>SemiprimeD1StackMultiplierLink.instruction frameStack Label.frame (SemiprimeD1StackFrame.code pc)\n  | .copy pc=>SemiprimeD1StackMultiplierLink.instruction copyStack Label.copy (SemiprimeD1StackCopy.code pc)\n  | .field pc=>SemiprimeD1StackMultiplierLink.instruction fieldStack Label.field (Field.code pc)\n\n/-- Exact shared-payload view; all actual private component stacks are empty. -/\ndef bank (code cached saved result left right flag scratch : List Bool) : Stack→List Bool\n  | .code=>code | .modulus=>cached | .saved=>saved | .result=>result\n  | .left=>left | .right=>right | .flag=>flag | .scratch=>scratch | _=>[]\n/-- Prepared physical syntax/cache data, without a decoded expression argument. -/\ndef input (code cached : List Bool) : Stack→List Bool := bank code cached [] [] [] [] [] []\n/-- Closed actual entry for physical code and cached modulus alone. -/\ndef initial (code cached : List Bool) : C.State Stack Label :=\n  ⟨some .start,none,none,input code cached,[]⟩\n/-- Actual finite machine; supplying the encoded syntax/cache is caller work. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine Stack.code Stack.result .start program\n/-- Every stack alphabet, including real return tags, is genuinely finite. -/\ntheorem all_alphabets_finite : ∀k,Finite (machine.Γ k) :=\n  SemiprimeD1StackCalls.all_alphabets_finite Stack.code Stack.result Label.start program\n/-- No input-sized syntax, natural or closure occurs in internal machine control. -/\ntheorem control_finite : Finite machine.σ :=\n  SemiprimeD1StackCalls.control_finite Stack.code Stack.result Label.start program\n/-- The literal data-stack inventory is fixed before all expressions and moduli. -/\ntheorem stack_card : Fintype.card Stack=75 := by decide\nend RiemannGaussian.SemiprimeD1StackExpr\n","RiemannGaussian.SemiprimeD1StackFermatBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackFermatExecution\nimport RiemannGaussian.SemiprimeD1StackTransformBounds\n\n/-! # Actual prefix storage and positive-input public constant agreement\nZero-width execution produces its own local E=0/R=1 words; the legacy macro\nnormalizer equality is deliberately restricted to positive original input width.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 16000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackFermatBounds\nopen SemiprimeD1StackFermatConstants SemiprimeD1StackFermatComponents SemiprimeD1StackFermatExecution\nopen SemiprimeMacroParameters SemiprimeBitArithmetic\n\n/-- Every actual data stack has at most original width plus executed pushes. -/\ntheorem prefix_data_bound (bits:List Bool) (fuel:ℕ) (out:C.State Stack Label)\n    (hr:C.run program fuel (initial bits)=some out) :\n    ∀k,(out.data k).length≤bits.length+fuel := by\n  apply SemiprimeD1StackReturnLink.run_data_bound program fuel bits.length _ out ?_ hr\n  intro k\n  cases k with\n  | inl k => cases k <;> simp [initial,input,Meta.input]\n  | inr bit => cases bit <;> simp [initial,input]\n\n/-- Pure scalar substitution independent of executable projection contexts. -/\ntheorem numeric_space (n fuel cells frames time:ℕ)\n    (hc:cells≤13*(n+fuel)) (hf:frames≤fuel) (ht:fuel≤time)\n    (hb:time≤150000*(n+1)^2) : cells+frames≤2200000*(n+1)^2 := by\n  nlinarith\n\n/-- All thirteen Boolean stacks and the real return stack are included. -/\ntheorem machine_space (bits:List Bool) (fuel:ℕ) (cfg:machine.Cfg)\n    (hr:(fun cfg=>cfg.bind machine.step)^[fuel] (some (Turing.initList machine bits))=some cfg) :\n    (cfg.stk (some (.inl .input))).length+(cfg.stk (some (.inl .width))).length+(cfg.stk (some (.inl .nonzero))).length+(cfg.stk (some (.inl .threshold))).length+(cfg.stk (some (.inl .radius))).length+(cfg.stk (some (.inl .square))).length+(cfg.stk (some (.inl .exponent))).length+(cfg.stk (some (.inl .squareWork))).length+(cfg.stk (some (.inl .thresholdWork))).length+(cfg.stk (some (.inl .temporary))).length+(cfg.stk (some (.inl .radix))).length+(cfg.stk (some (.inr false))).length+(cfg.stk (some (.inr true))).length+(cfg.stk none).length≤2200000*(bits.length+1)^2 := by\n  rw [initial_eq] at hr\n  let state:=initial bits\n  change (fun cfg=>cfg.bind machine.step)^[fuel]\n    (some (SemiprimeD1StackCalls.configuration state))=some cfg at hr\n  have he:=SemiprimeD1StackCalls.run_correct (.inl .input) (.inr true) (.inl .start) program fuel state\n  change (C.run program fuel state).map SemiprimeD1StackCalls.configuration=\n    (fun cfg=>cfg.bind machine.step)^[fuel] (some (SemiprimeD1StackCalls.configuration state)) at he\n  cases hc:C.run program fuel state with\n  | none => rw [hc,hr] at he;cases he\n  | some out =>\n    rw [hc,hr] at he\n    have hcfg:SemiprimeD1StackCalls.configuration out=cfg:=Option.some.inj he\n    rw [←hcfg]\n    have hbound:=prefix_data_bound bits fuel out hc\n    have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel state out hc\n    have htime:fuel≤totalTime bits.length:=by\n      by_contra hn\n      have ht:fuel=totalTime bits.length+((fuel-totalTime bits.length-1)+1):=by omega\n      rw [ht,SemiprimeD1StackReturnLink.run_add,acquire_run bits,Option.bind_some] at hc\n      have hh:C.run program ((fuel-totalTime bits.length-1)+1) (done bits)=none:=by\n        unfold C.run\n        rw [Function.iterate_succ_apply]\n        have hs:C.step program (done bits)=none:=by\n          simp [C.step,SemiprimeD1StackCalls.step,done]\n        simp only [Option.bind_some,hs]\n        exact Function.iterate_fixed rfl _\n      rw [hh] at hc;cases hc\n    have h0:=hbound (.inl .input)\n    have h1:=hbound (.inl .width)\n    have h2:=hbound (.inl .nonzero)\n    have h3:=hbound (.inl .threshold)\n    have h4:=hbound (.inl .radius)\n    have h5:=hbound (.inl .square)\n    have h6:=hbound (.inl .exponent)\n    have h7:=hbound (.inl .squareWork)\n    have h8:=hbound (.inl .thresholdWork)\n    have h9:=hbound (.inl .temporary)\n    have h10:=hbound (.inl .radix)\n    have h11:=hbound (.inr false)\n    have h12:=hbound (.inr true)\n    change out.frames.length≤0+fuel at hf\n    have hs:(out.data (.inl .input)).length+(out.data (.inl .width)).length+(out.data (.inl .nonzero)).length+(out.data (.inl .threshold)).length+(out.data (.inl .radius)).length+(out.data (.inl .square)).length+(out.data (.inl .exponent)).length+(out.data (.inl .squareWork)).length+(out.data (.inl .thresholdWork)).length+(out.data (.inl .temporary)).length+(out.data (.inl .radix)).length+(out.data (.inr false)).length+(out.data (.inr true)).length≤13*(bits.length+fuel):=by omega\n    change (out.data (.inl .input)).length+(out.data (.inl .width)).length+(out.data (.inl .nonzero)).length+(out.data (.inl .threshold)).length+(out.data (.inl .radius)).length+(out.data (.inl .square)).length+(out.data (.inl .exponent)).length+(out.data (.inl .squareWork)).length+(out.data (.inl .thresholdWork)).length+(out.data (.inl .temporary)).length+(out.data (.inl .radix)).length+(out.data (.inr false)).length+(out.data (.inr true)).length+out.frames.length≤_\n    exact numeric_space bits.length fuel _ _ _ hs (by simpa only [Nat.zero_add] using hf) htime (totalTime_le bits.length)\n\n/-- The original binary input and actual nonzero flag remain physically retained. -/\ntheorem retained (bits:List Bool) :\n    result bits (.inl .input)=bits ∧\n      result bits (.inl .nonzero)=[SemiprimeD1BinaryBootstrap.seenOne bits] := by\n  exact ⟨rfl,rfl⟩\n\n/-- On positive physical width, the returned normalizer is the existing original macro normalizer. -/\ntheorem original_normalizer (bits:List Bool) (hL:0<bits.length) :\n    bitValue (result bits (.inr true))=\n      (SemiprimeMacroEntryExecution.explicitNormalizer (macroDepth bits.length)).val := by\n  exact SemiprimeD1StackFermatWords.original_normalizer bits.length hL\n\n/-- The returned modulus agrees with the legacy positive-width macro modulus. -/\ntheorem original_modulus (bits:List Bool) (hL:0<bits.length) :\n    bitValue (result bits (.inr false))=2^(SemiprimeMacroFermatNetwork.macroLength (macroDepth bits.length))+1 := by\n  change bitValue (SemiprimeD1StackFermatWords.modulusWord (transformLength bits.length))=_\n  rw [transform_eq_macroLength hL]\n  exact SemiprimeD1StackFermatWords.modulus_value _ (by unfold SemiprimeMacroFermatNetwork.macroLength; positivity)\n\n/-- The actual returned word agrees with the full existing positive public configuration. -/\ntheorem public_normalizer (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0<bitValue bits) :\n    bitValue (result bits (.inr true))=\n      (SemiprimePublicFactorCount.publicConfig (bitValue bits) hN).normalizer.val := by\n  rw [SemiprimeMacroEntryExecution.normalizer_eq_explicit]\n  have hw:bits.length=bitLength (bitValue bits):=\n    SemiprimeD1BinaryBootstrap.canonical_width bits hc\n  have hL:0<bits.length:=by\n    rw [hw]\n    exact Nat.size_pos.mpr hN\n  change bitValue (result bits (.inr true))=\n    (SemiprimeMacroEntryExecution.explicitNormalizer (macroDepth (bitLength (bitValue bits)))).val\n  rw [←hw]\n  exact original_normalizer bits hL\n\n/-- Canonical original input ties physical width to the public bitLength. -/\ndef originalInTime (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) :\n    StateTransition.EvalsToInTime machine.step (Turing.initList machine bits)\n      (some (SemiprimeD1StackCalls.configuration (done bits)))\n      (150000*(bitLength (bitValue bits)+1)^2) := by\n  have hw:=SemiprimeD1BinaryBootstrap.canonical_width bits hc\n  simpa only [hw,bitLength] using acquireInTime bits\nend RiemannGaussian.SemiprimeD1StackFermatBounds\n","RiemannGaussian.SemiprimeD1StackFullFactorCatalogue":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackFactorScopeFibreBounds\nimport RiemannGaussian.SemiprimeD1StackAllDescriptorRecordClock\nimport RiemannGaussian.SemiprimeD1StackVertexCatalogueBounds\n/-! # Actual binary-N-only ALL original factor-record controller\nThe pair source and descriptor catalogue are acquired once. Every descriptor\nis physically parsed into five real raw fields. The actual eighteen-tag\nsource acquires its table and unary ports and logs the row. All five raw\nfields and retained binary scope are physically drained before key advancement.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 3000000\nset_option maxRecDepth 100000\nset_option synthInstance.maxSize 1000000\nnamespace RiemannGaussian.SemiprimeD1StackFullFactorCatalogue\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State execute step run)\nend C\nnamespace F\nexport SemiprimeD1StackFactorScopeFibre (Stack Label program initial originalInput query output)\nend F\nnamespace V\nexport SemiprimeD1StackVertexCatalogue (Stack Label program originalInput kernelStack)\nend V\nnamespace D\nexport SemiprimeD1StackAllDescriptorRecord (Stack Label Common program source scopeBank history output copyScratch tagReader cleanData commonData)\nend D\nnamespace Field\nexport SemiprimeD1TensorTapeFieldBytecode (Stack Label code active)\nend Field\nnamespace Log\nexport SemiprimeD1StackVertexRecordStream (Stack Label code)\nend Log\n/-- All1454 roles, including both unused descriptor-input shadows. -/\nabbrev Stack :=F.Stack⊕(V.Stack⊕(D.Stack⊕Unit))\n/-- Complete137-role actual pair acquisition and repeated scope filter. -/\ndef sourceStack :F.Stack→Stack:=Sum.inl\n/-- Complete53-role physically acquired original descriptor catalogue. -/\ndef catalogueStack (k:V.Stack) :Stack:=.inr (.inl k)\n/-- Actual descriptor reader is the original catalogue output, with no copy or supplier. -/\ndef descriptorReader :Stack:=catalogueStack (V.kernelStack (SemiprimeD1StackCartesian4.aux 2))\n/-- Original binary N is loaded only in the actual pair-source input. -/\ndef originalInput :Stack:=sourceStack F.originalInput\n/-- Actual scope vector is shared directly with the eighteen-tag record source. -/\ndef scope :Stack:=sourceStack F.output\n/-- Real descriptor operands share ONLY the acquired original binary N and binary scope. -/\ndef descriptorStack (k:D.Stack) :Stack:=\n  if k=D.source 0 then originalInput else if k=D.scopeBank then scope else .inr (.inr (.inl k))\n/-- Actual parsed tag and coordinates occupy raw source fields1 through5. -/\ndef fieldPart (i:Fin 5) :Fin 6:=⟨i.val+1,by omega⟩\n/-- Actual raw descriptor payload role; no descriptor or typed vertex enters control. -/\ndef cache (i:Fin 5) :Stack:=descriptorStack (D.source (fieldPart i))\n/-- One fresh Boolean validity word is physically written and consumed per field. -/\ndef valid :Stack:=.inr (.inr (.inr ()))\n/-- The preserving N copy and real field parser reuse the actual clean copy scratch. -/\ndef scratch :Stack:=descriptorStack D.copyScratch\n/-- The actual factor counter is unary length n, with numeric value2^n-1. -/\ndef counter :Stack:=sourceStack F.query\n/-- Shared actual reverse chronological row log. -/\ndef history :Stack:=descriptorStack D.history\n/-- Actual complete forward factor-record output. -/\ndef output :Stack:=descriptorStack D.output\n/-- Four literal logger roles use the shared accumulators and physically empty consuming fields. -/\ndef loggerStack :Log.Stack→Stack\n  | .ports=>descriptorStack D.tagReader\n  | .table=>scratch\n  | .history=>history\n  | .output=>output\n/-- Static preserving binary-N copy operands. -/\ndef copyStack (k:Fin 3) :Stack:=\n  if k=0 then originalInput else if k=1 then catalogueStack V.originalInput else scratch\n/-- Static physical parser operands; every raw field is actually parsed. -/\ndef fieldStack (part:Fin 5) :Field.Stack→Stack\n  | .inl .input=>descriptorReader | .inl .scratch=>scratch\n  | .inl .output=>cache part | .inr _=>valid\n/-- Fixed source, parser, cleanup, unary-key and final-reversal phases. -/\ninductive Control where\n  | main | copyN | catalogue | seed | loop | field (part:Fin 5) | valid (part:Fin 5)\n  | row | clearField (part:Fin 5) | clearScope | advance | next | query | reverse | done | abort\n  deriving DecidableEq,Fintype\n/-- All source and return labels are finite and fixed before original N. -/\ninductive Label where\n  | local (pc:Control) | source (pc:F.Label) | catalogue (pc:V.Label)\n  | descriptor (pc:D.Label) | copy (pc:Fin 9) | field (part:Fin 5) (pc:Field.Label) | logger (pc:Log.Label)\n  deriving Fintype\n/-- Next actual field-parser call, or the real eighteen-tag source. -/\ndef nextField (part:Fin 5) :Label:=\n  if h:part.val<4 then .local (.field ⟨part.val+1,by omega⟩) else .local .row\n/-- Next actual field drain, or the complete acquired-scope drain. -/\ndef nextClear (part:Fin 5) :Label:=\n  if h:part.val<4 then .local (.clearField ⟨part.val+1,by omega⟩) else .local .clearScope\n/-- One fixed actual N-only full-factor compiler; no key, table, arity or mode answer is supplied. -/\ndef program :Label→C.Instruction Stack Label\n  | .local .main=>.call (.source .main) (.local .copyN)\n  | .local .copyN=>.call (.copy 0) (.local .catalogue)\n  | .local .catalogue=>.call (.catalogue (.inl .main)) (.local .seed)\n  | .local .seed=>.base (.push output false (.local .loop))\n  | .local .loop=>.base (.peek descriptorReader (.local .reverse) (.local (.field 0)) (.local (.field 0)))\n  | .local (.field part)=>.call (.field part (Field.active .tagPop (none,false))) (.local (.valid part))\n  | .local (.valid part)=>.base (.pop valid (.local .abort) (.local .abort) (nextField part))\n  | .local .row=>.call (.descriptor (.inl .start)) (.local (.clearField 0))\n  | .local (.clearField part)=>.base (.pop (cache part) (nextClear part)\n      (.local (.clearField part)) (.local (.clearField part)))\n  | .local .clearScope=>.base (.pop scope (.local .advance) (.local .clearScope) (.local .clearScope))\n  | .local .advance=>.base (.push counter true (.local .next))\n  | .local .next=>.base (.peek descriptorReader (.local .reverse) (.local .query) (.local .query))\n  | .local .query=>.call (.source .copy) (.local .loop)\n  | .local .reverse=>.call (.logger .reverse) (.local .done)\n  | .local .done|.local .abort=>.base .halt\n  | .source pc=>SemiprimeD1StackValidationLink.instruction sourceStack Label.source (F.program pc)\n  | .catalogue pc=>SemiprimeD1StackValidationLink.instruction catalogueStack Label.catalogue (V.program pc)\n  | .descriptor pc=>SemiprimeD1StackValidationLink.instruction descriptorStack Label.descriptor (D.program pc)\n  | .copy pc=>SemiprimeD1StackMultiplierLink.instruction copyStack Label.copy (SemiprimeD1StackCopy.code pc)\n  | .field part pc=>SemiprimeD1StackMultiplierLink.instruction (fieldStack part) (Label.field part) (Field.code pc)\n  | .logger pc=>SemiprimeD1StackMultiplierLink.instruction loggerStack Label.logger (Log.code pc)\n/-- Standard initialization contains original binary N alone. -/\ndef input (bits:List Bool) :Stack→List Bool:=Sum.elim (F.initial bits []).data (fun _=>[])\n/-- The output terminator, all keys and all original descriptors are physically acquired. -/\ndef initial (bits:List Bool) :C.State Stack Label:=⟨some (.local .main),none,none,input bits,[]⟩\n/-- Genuine fixed finite machine with all actual enlarged return labels. -/\ndef machine :Turing.FinTM2:=SemiprimeD1StackCalls.machine originalInput output (.local .main) program\n/-- All actual source, catalogue, table/serializer/logger and validity roles are counted. -/\ntheorem stack_card :Fintype.card Stack=1454:=by\n  change Fintype.card (F.Stack⊕(V.Stack⊕(D.Stack⊕Unit)))=1454\n  rw [Fintype.card_sum]\n  conv_lhs =>\n    arg 2\n    rw [Fintype.card_sum]\n    arg 2\n    rw [Fintype.card_sum]\n  rw [SemiprimeD1StackFactorScopeFibre.stack_card,SemiprimeD1StackVertexCatalogue.stack_card,\n    SemiprimeD1StackAllDescriptorRecord.stack_card,Fintype.card_unit]\n/-- Static role inverse used solely to prove that the two physical aliases cannot collide. -/\ndef descriptorInverse :Stack→D.Stack\n  | .inl k=>if k=F.output then D.scopeBank else D.source 0\n  | .inr (.inr (.inl k))=>k\n  | _=>D.source 0\n/-- Every real record-source role has its unique physical outer target. -/\ntheorem descriptor_inverse (k:D.Stack) :descriptorInverse (descriptorStack k)=k:=by\n  by_cases h0:k=D.source 0\n  · subst k;rfl\n  · by_cases hb:k=D.scopeBank\n    · subst k;rfl\n    · simp only [descriptorStack,h0,hb,ite_false,descriptorInverse]\n/-- Actual source inclusion is injective without enumerating its1252 private slots. -/\ntheorem descriptor_injective :Function.Injective descriptorStack:=by\n  intro a b h\n  have hh:=congrArg descriptorInverse h\n  simpa only [descriptor_inverse] using hh\n/-- Field-cache roles are private raw fields1..5 and cannot hit either shared alias. -/\ntheorem cache_private (i:Fin 5) :cache i=.inr (.inr (.inl (D.source (fieldPart i)))):=by\n  have hn:fieldPart i≠0:=by intro h;have hv:=congrArg Fin.val h;dsimp only [fieldPart] at hv;omega\n  simp only [cache,descriptorStack,D.source,Sum.inl.injEq,SemiprimeD1StackAllDescriptorRecord.Common.source.injEq,hn,ite_false]\n  rfl\n/-- Four distinct actual common words support the single final physical reversal. -/\ntheorem logger_injective :Function.Injective loggerStack:=by decide\n/-- The one original N copy has distinct source, catalogue target and clean scratch roles. -/\ntheorem copy_injective :Function.Injective copyStack:=by decide\n/-- Every real field parser has four distinct physical roles. -/\ntheorem field_injective :∀part:Fin 5,Function.Injective (fieldStack part):=by decide\n/-- Runtime control and flags, including return labels, are finite before every original input. -/\ntheorem control_finite :Finite machine.σ:=SemiprimeD1StackCalls.control_finite originalInput output (.local .main) program\n/-- Every data and actual return alphabet is fixed finite before original N. -/\ntheorem all_alphabets_finite :∀k,Finite (machine.Γ k):=\n  SemiprimeD1StackCalls.all_alphabets_finite originalInput output (.local .main) program\nend RiemannGaussian.SemiprimeD1StackFullFactorCatalogue\n","RiemannGaussian.SemiprimeD1StackGuardedDotBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackGuardedDotExecution\n/-! # Closed guarded dot time and complete all-prefix inventory\nCanonicality and whole-source validity are derived only after the actual true\nverdict. The rejected path pays the guard and preserves every original input.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1000000\nset_option synthInstance.maxSize 4096\nnamespace RiemannGaussian.SemiprimeD1StackGuardedDotBounds\nopen SemiprimeD1StackGuardedDotEvaluate SemiprimeD1StackGuardedDotExecution\nopen SemiprimeD1StackUnaryDivmod (unary)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeMacroEntryBitPrimitives (Expr Valid)\n/-- Fixed-degree actual transition bound, before all prepared physical inputs. -/\ndef runBound (c : D.Cache) (cached : List Bool) : ℕ :=\n  30000000000*(SemiprimeD1StackDotEvaluateBounds.inputSize c cached+1)^8\n/-- Uniform actual guard plus CONDITIONAL real DotEvaluate bound. There is no\ncanonical-vector/Valid-whole/count-result/source-size/clock advice premise. -/\ntheorem timeBound_le (c : D.Cache) (cached : List Bool) (baseExpr : Expr)\n    (hbase : c.base=SemiprimeD1StackExprCodec.encode baseExpr []) (words : List (List Bool))\n    (stride frequency n : ℕ) (hs : c.stride=unary stride) (hf : c.frequency=unary frequency)\n    (hn : c.count=unary n) (hc : c.words=vectorBits words)\n    (hm : 1<SemiprimeBitArithmetic.bitValue cached) (hb : Valid cached baseExpr) :\n    timeBound c cached baseExpr words stride frequency n ≤ runBound c cached := by\n  let S:=SemiprimeD1StackDotEvaluateBounds.inputSize c cached\n  have hi : (vectorBits words).length+cached.length+1 ≤ S+1 := by\n    dsimp [S,SemiprimeD1StackDotEvaluateBounds.inputSize,SemiprimeD1StackExprDotBounds.inputSize]\n    rw [hc]\n    omega\n  have hG:=SemiprimeD1StackVectorCanonicalBounds.timeBound_le words cached\n  have h2 : ((vectorBits words).length+cached.length+1)^2 ≤ (S+1)^2 := Nat.pow_le_pow_left hi 2\n  have h28 : (S+1)^2 ≤ (S+1)^8 := Nat.pow_le_pow_right (by omega) (by decide)\n  have hguard : SemiprimeD1StackVectorCanonicalExecution.timeBound words cached ≤ 200*(S+1)^8 :=\n    hG.trans (Nat.mul_le_mul_left 200 (h2.trans h28))\n  have hpos : 0<(S+1)^8 := by positivity\n  cases ha : answer cached words with\n  | false=>\n    simp only [timeBound,ha,Bool.false_eq_true,ite_false,runBound]\n    change _ ≤ 30000000000*(S+1)^8\n    omega\n  | true=>\n    have hDot:=SemiprimeD1StackDotEvaluateBounds.timeBound_le c cached baseExpr hbase words stride frequency n hs hf hn hc\n      (by omega) (expression_valid cached baseExpr words stride frequency n hm hb ha)\n    change SemiprimeD1StackDotEvaluateExecution.timeBound c cached baseExpr words stride frequency n ≤ 10000000000*(S+1)^8 at hDot\n    simp only [timeBound,ha,ite_true,runBound]\n    change _ ≤ 30000000000*(S+1)^8\n    omega\n/-- Actual completed source trace with the uniform physical-input polynomial. -/\ntheorem source_run_bounded (c : D.Cache) (cached : List Bool) (baseExpr : Expr)\n    (hbase : c.base=SemiprimeD1StackExprCodec.encode baseExpr []) (words : List (List Bool))\n    (stride frequency n : ℕ) (hs : c.stride=unary stride) (hf : c.frequency=unary frequency)\n    (hn : c.count=unary n) (hc : c.words=vectorBits words) (tail : List Bool)\n    (hm : 1<SemiprimeBitArithmetic.bitValue cached) (hb : Valid cached baseExpr) :\n    ∃t ≤ runBound c cached,C.run program t (initial c cached tail)=some (done c cached baseExpr words stride frequency n tail) := by\n  obtain ⟨t,ht,hr⟩:=source_run c cached baseExpr hbase words stride frequency n hs hf hn hc tail hm hb\n  exact ⟨t,ht.trans (timeBound_le c cached baseExpr hbase words stride frequency n hs hf hn hc hm hb),hr⟩\n/-- Proof-side choice of a PROVED actual trace, never an executing time oracle. -/\nnoncomputable def sourceEvaluate (c : D.Cache) (cached : List Bool) (baseExpr : Expr)\n    (hbase : c.base=SemiprimeD1StackExprCodec.encode baseExpr []) (words : List (List Bool))\n    (stride frequency n : ℕ) (hs : c.stride=unary stride) (hf : c.frequency=unary frequency)\n    (hn : c.count=unary n) (hc : c.words=vectorBits words) (tail : List Bool)\n    (hm : 1<SemiprimeBitArithmetic.bitValue cached) (hb : Valid cached baseExpr) :\n    StateTransition.EvalsToInTime (C.step program) (initial c cached tail)\n      (some (done c cached baseExpr words stride frequency n tail)) (runBound c cached) := by\n  let h:=source_run_bounded c cached baseExpr hbase words stride frequency n hs hf hn hc tail hm hb\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\n/-- Genuine fixed FinTM2 caller from physical source/vector/metadata/modulus caches. -/\nnoncomputable def machineEvaluate (c : D.Cache) (cached : List Bool) (baseExpr : Expr)\n    (hbase : c.base=SemiprimeD1StackExprCodec.encode baseExpr []) (words : List (List Bool))\n    (stride frequency n : ℕ) (hs : c.stride=unary stride) (hf : c.frequency=unary frequency)\n    (hn : c.count=unary n) (hc : c.words=vectorBits words) (tail : List Bool)\n    (hm : 1<SemiprimeBitArithmetic.bitValue cached) (hb : Valid cached baseExpr) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial c cached tail))\n      (some (SemiprimeD1StackCalls.configuration (done c cached baseExpr words stride frequency n tail))) (runBound c cached) :=\n  SemiprimeD1StackCalls.evalsCorrect (.inl (.inl .base)) output Label.start program _ _ _\n    (sourceEvaluate c cached baseExpr hbase words stride frequency n hs hf hn hc tail hm hb)\n/-- Any actual successful prefix lies before the proved actual completed halt. -/\ntheorem prefix_fuel_le (c : D.Cache) (cached : List Bool) (baseExpr : Expr)\n    (hbase : c.base=SemiprimeD1StackExprCodec.encode baseExpr []) (words : List (List Bool))\n    (stride frequency n : ℕ) (hs : c.stride=unary stride) (hf : c.frequency=unary frequency)\n    (hn : c.count=unary n) (hc : c.words=vectorBits words) (tail : List Bool)\n    (hm : 1<SemiprimeBitArithmetic.bitValue cached) (hb : Valid cached baseExpr)\n    (fuel : ℕ) (out : C.State Stack Label)\n    (hr : C.run program fuel (initial c cached tail)=some out) : fuel ≤ runBound c cached := by\n  obtain ⟨t,ht,hh⟩:=source_run_bounded c cached baseExpr hbase words stride frequency n hs hf hn hc tail hm hb\n  have hfuel : fuel ≤ t := by\n    by_contra hn'\n    have he : fuel=t+(1+(fuel-(t+1))) := by omega\n    rw [he,SemiprimeD1StackReturnLink.run_add,hh,Option.bind_some,SemiprimeD1StackReturnLink.run_add] at hr\n    have hz : C.run program 1 (done c cached baseExpr words stride frequency n tail)=none := rfl\n    rw [hz,Option.bind_none] at hr\n    cases hr\n  exact hfuel.trans ht\n/-- Every successful source prefix includes ALL107 Boolean data stacks and actual\nreturn-label cells, with duplicate private cache/modulus aliases counted as well. -/\ntheorem prefix_cells (c : D.Cache) (cached : List Bool) (baseExpr : Expr)\n    (hbase : c.base=SemiprimeD1StackExprCodec.encode baseExpr []) (words : List (List Bool))\n    (stride frequency n : ℕ) (hs : c.stride=unary stride) (hf : c.frequency=unary frequency)\n    (hn : c.count=unary n) (hc : c.words=vectorBits words) (tail : List Bool)\n    (hm : 1<SemiprimeBitArithmetic.bitValue cached) (hb : Valid cached baseExpr)\n    (fuel : ℕ) (out : C.State Stack Label)\n    (hr : C.run program fuel (initial c cached tail)=some out) :\n    (∑k : Stack,(out.data k).length)+out.frames.length ≤\n      108*(SemiprimeD1StackDotEvaluateBounds.inputSize c cached+tail.length+runBound c cached) := by\n  let inv:=SemiprimeD1StackDotEvaluateBounds.inputSize c cached+tail.length\n  have hdata : ∀k,((initial c cached tail).data k).length ≤ inv := by\n    intro k\n    rcases k with k|k\n    · rcases k with k|k\n      · cases k <;> simp [initial,store,D.initial,SemiprimeD1StackDotEvaluate.store,\n          SemiprimeD1StackExprDot.bank,SemiprimeD1StackDotEvaluateBounds.inputSize,\n          SemiprimeD1StackExprDotBounds.inputSize,inv] <;> omega\n      · cases k <;> simp [initial,store,D.initial,SemiprimeD1StackDotEvaluate.store,\n          SemiprimeD1StackExpr.input,SemiprimeD1StackExpr.bank,SemiprimeD1StackDotEvaluateBounds.inputSize,inv];omega\n    · cases k <;> change 0 ≤ inv <;> omega\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel inv _ out hdata hr\n  have hfuel:=SemiprimeD1StackCalls.run_frame_bound program fuel _ out hr\n  change out.frames.length ≤ 0+fuel at hfuel\n  have hsum : (∑k : Stack,(out.data k).length) ≤ 107*(inv+fuel) := by\n    calc\n      _ ≤ ∑_k : Stack,(inv+fuel) := Finset.sum_le_sum (fun k _=>hd k)\n      _ = _ := by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  have ht:=prefix_fuel_le c cached baseExpr hbase words stride frequency n hs hf hn hc tail hm hb fuel out hr\n  change (∑k : Stack,(out.data k).length)+out.frames.length ≤ 108*(inv+runBound c cached)\n  omega\n/-- Fixed-degree original-input inventory form, including retained arbitrary suffix. -/\ntheorem prefix_cells_polynomial (c : D.Cache) (cached : List Bool) (baseExpr : Expr)\n    (hbase : c.base=SemiprimeD1StackExprCodec.encode baseExpr []) (words : List (List Bool))\n    (stride frequency n : ℕ) (hs : c.stride=unary stride) (hf : c.frequency=unary frequency)\n    (hn : c.count=unary n) (hc : c.words=vectorBits words) (tail : List Bool)\n    (hm : 1<SemiprimeBitArithmetic.bitValue cached) (hb : Valid cached baseExpr)\n    (fuel : ℕ) (out : C.State Stack Label)\n    (hr : C.run program fuel (initial c cached tail)=some out) :\n    (∑k : Stack,(out.data k).length)+out.frames.length ≤\n      4000000000000*(SemiprimeD1StackDotEvaluateBounds.inputSize c cached+tail.length+1)^8 := by\n  have h:=prefix_cells c cached baseExpr hbase words stride frequency n hs hf hn hc tail hm hb fuel out hr\n  let inv:=SemiprimeD1StackDotEvaluateBounds.inputSize c cached+tail.length\n  have hp : (SemiprimeD1StackDotEvaluateBounds.inputSize c cached+1)^8 ≤ (inv+1)^8 := Nat.pow_le_pow_left (by dsimp [inv];omega) 8\n  have hi : inv ≤ (inv+1)^8 := by\n    have hh:=Nat.pow_le_pow_right (by omega : 1 ≤ inv+1) (by decide : 1 ≤ 8)\n    simp only [pow_one] at hh\n    omega\n  unfold runBound at h\n  change (∑k : Stack,(out.data k).length)+out.frames.length ≤ 4000000000000*(inv+1)^8\n  have hh:=Nat.mul_le_mul_left 30000000000 hp\n  change (∑k : Stack,(out.data k).length)+out.frames.length ≤ 108*(inv+30000000000*(SemiprimeD1StackDotEvaluateBounds.inputSize c cached+1)^8) at h\n  omega\n/-- Same complete fixed-degree all-prefix inventory on the genuine target machine. -/\ntheorem machine_prefix_cells (c : D.Cache) (cached : List Bool) (baseExpr : Expr)\n    (hbase : c.base=SemiprimeD1StackExprCodec.encode baseExpr []) (words : List (List Bool))\n    (stride frequency n : ℕ) (hs : c.stride=unary stride) (hf : c.frequency=unary frequency)\n    (hn : c.count=unary n) (hc : c.words=vectorBits words) (tail : List Bool)\n    (hm : 1<SemiprimeBitArithmetic.bitValue cached) (hb : Valid cached baseExpr)\n    (fuel : ℕ) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial c cached tail)))=some cfg) :\n    (∑k : Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤\n      4000000000000*(SemiprimeD1StackDotEvaluateBounds.inputSize c cached+tail.length+1)^8 := by\n  have he:=SemiprimeD1StackCalls.run_correct (.inl (.inl .base)) output Label.start program fuel (initial c cached tail)\n  have hh:=he.trans hr\n  cases hc' : C.run program fuel (initial c cached tail) with\n  | none=>rw [hc'] at hh;cases hh\n  | some out=>\n    rw [hc'] at hh\n    have hcfg : SemiprimeD1StackCalls.configuration out=cfg := Option.some.inj hh\n    subst cfg\n    exact prefix_cells_polynomial c cached baseExpr hbase words stride frequency n hs hf hn hc tail hm hb fuel out hc'\nend RiemannGaussian.SemiprimeD1StackGuardedDotBounds\n","RiemannGaussian.SemiprimeD1StackHeapReadExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackHeapReadComponents\nimport RiemannGaussian.SemiprimeD1StackHeapAllocate\n\n/-! # Original allocator-history dereference execution\nEvery counter/reference bit and every skipped record is visited by the actual\nfixed program. The logical store is used only to prove the meaning of bytes\ncreated by the actual allocator, never as a runtime getter or read answer.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackHeapReadExecution\nopen SemiprimeD1StackHeapRead SemiprimeD1StackHeapReadComponents\nopen SemiprimeSourceHistogramKeyBits (frame)\n\n/-- Exact physical payload at all top-level protocol boundaries. -/\ndef payload (heap counter reference reader depth work output valid:List Bool) : Stack→List Bool\n  | .heap => heap\n  | .counter => counter\n  | .reference => reference\n  | .reader => reader\n  | .depth => depth\n  | .referenceWork => work\n  | .output => output\n  | .valid => valid\n  | _ => []\n\n/-- Three actual included copies preserve heap/counter/reference and acquire their work copies. -/\ntheorem prepare (heap counter reference:List Bool) :\n    Runs (5*heap.length+5*counter.length+5*reference.length+12) (.inl .start)\n      (payload heap counter reference [] [] [] [] []) (.inl .afterReference)\n      (payload heap counter reference heap counter reference [] []) := by\n  have h0:=copy_call 0 (payload heap counter reference [] [] [] [] []) rfl\n    (.inl .start) (.inl .afterHeap) rfl\n  have hd0:Function.update (payload heap counter reference [] [] [] [] []) Stack.reader heap=\n      payload heap counter reference heap [] [] [] []:=by funext k;cases k <;> simp [payload,Function.update]\n  simp only [copyInput,copyOutput,payload,List.append_nil,ite_true] at h0\n  rw [hd0] at h0\n  have h1:=copy_call 1 (payload heap counter reference heap [] [] [] []) rfl\n    (.inl .afterHeap) (.inl .afterCounter) rfl\n  have hd1:Function.update (payload heap counter reference heap [] [] [] []) Stack.depth counter=\n      payload heap counter reference heap counter [] [] []:=by funext k;cases k <;> simp [payload,Function.update]\n  simp only [copyInput,copyOutput,payload,show ¬((1:Fin 3)=0) by decide,ite_false,ite_true,List.append_nil] at h1\n  rw [hd1] at h1\n  have h2:=copy_call 2 (payload heap counter reference heap counter [] [] []) rfl\n    (.inl .afterCounter) (.inl .afterReference) rfl\n  have hd2:Function.update (payload heap counter reference heap counter [] [] []) Stack.referenceWork reference=\n      payload heap counter reference heap counter reference [] []:=by funext k;cases k <;> simp [payload,Function.update]\n  simp only [copyInput,copyOutput,payload,show ¬((2:Fin 3)=0) by decide,\n    show ¬((2:Fin 3)=1) by decide,ite_false,List.append_nil] at h2\n  rw [hd2] at h2\n  have h:=h0.trans (h1.trans h2)\n  convert h using 1\n  omega\n\n/-- An actual pair of unary work-stack pops decreases both lengths once. -/\ntheorem reference_pair (heap counter reference reader depth work:List Bool) :\n    Runs 2 (.inl .referenceLoop) (payload heap counter reference reader (true::depth) (true::work) [] [])\n      (.inl .referenceLoop) (payload heap counter reference reader depth work [] []) := by\n  have h0:Runs 1 (.inl .referenceLoop) (payload heap counter reference reader (true::depth) (true::work) [] [])\n      (.inl .referenceStep) (payload heap counter reference reader (true::depth) work [] []):=by\n    apply one_base _ _ (.pop .referenceWork (.inl .scan) (.inl .referenceStep) (.inl .referenceStep)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> simp [B.execute,SemiprimeD1StackBytecode.execute,payload,Function.update]\n  have h1:Runs 1 (.inl .referenceStep) (payload heap counter reference reader (true::depth) work [] [])\n      (.inl .referenceLoop) (payload heap counter reference reader depth work [] []):=by\n    apply one_base _ _ (.pop .depth (.inl .bad) (.inl .referenceLoop) (.inl .referenceLoop)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> simp [B.execute,SemiprimeD1StackBytecode.execute,payload,Function.update]\n  exact h0.trans h1\n\n/-- The actual unary-reference loop computes the residual depth without native subtraction. -/\ntheorem reference_loop (i d:ℕ) (heap counter reference reader:List Bool) :\n    Runs (2*i+1) (.inl .referenceLoop)\n      (payload heap counter reference reader (List.replicate (i+d) true) (List.replicate i true) [] [])\n      (.inl .scan) (payload heap counter reference reader (List.replicate d true) [] [] []) := by\n  induction i with\n  | zero =>\n    apply one_base _ _ (.pop .referenceWork (.inl .scan) (.inl .referenceStep) (.inl .referenceStep)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> simp [B.execute,SemiprimeD1StackBytecode.execute,payload,Function.update]\n  | succ i ih =>\n    have h:=reference_pair heap counter reference reader (List.replicate (i+d) true) (List.replicate i true)\n    have hh:=h.trans ih\n    simpa only [Nat.succ_add,List.replicate_succ,show 2+ (2*i+1)=2*(i+1)+1 by omega] using hh\n\n/-- Physical newest-record adjustment followed by the actual unary-reference scan. -/\ntheorem acquire_depth (i d:ℕ) (heap counter reference reader:List Bool) :\n    Runs (2*i+2) (.inl .afterReference)\n      (payload heap counter reference reader (List.replicate (i+d+1) true) (List.replicate i true) [] [])\n      (.inl .scan) (payload heap counter reference reader (List.replicate d true) [] [] []) := by\n  have h0:Runs 1 (.inl .afterReference)\n      (payload heap counter reference reader (true::List.replicate (i+d) true) (List.replicate i true) [] [])\n      (.inl .referenceLoop)\n      (payload heap counter reference reader (List.replicate (i+d) true) (List.replicate i true) [] []):=by\n    apply one_base _ _ (.pop .depth (.inl .bad) (.inl .referenceLoop) (.inl .referenceLoop)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> simp [B.execute,SemiprimeD1StackBytecode.execute,payload,Function.update]\n  have h:=h0.trans (reference_loop i d heap counter reference reader)\n  simpa only [List.replicate_succ,show 1+(2*i+1)=2*i+2 by omega] using h\n/-- Parser store refinement for the bytes actually written by the allocator. -/\ntheorem parsed_frame (heap counter reference word tail depth work valid:List Bool) :\n    parsed (payload heap counter reference (frame word tail) depth work [] valid)=\n      payload heap counter reference tail depth work word (true::valid) := by\n  have h:=SemiprimeSourceHistogramKeyBits.split_frame word tail\n  funext k\n  cases k <;> simp [parsed,payload,h.1,h.2.1,h.2.2]\n\n/-- Actual included parser call on a real frame, with no supplied parse answer. -/\ntheorem parse_field (heap counter reference word tail depth work valid:List Bool)\n    (pc next:Label) (hcall:program pc=.call (fieldLabel (Field.active .tagPop (none,false))) next) :\n    Runs (8*word.length+7) pc (payload heap counter reference (frame word tail) depth work [] valid)\n      next (payload heap counter reference tail depth work word (true::valid)) := by\n  have h:=field_call (payload heap counter reference (frame word tail) depth work [] valid) rfl rfl pc next hcall\n  rw [parsed_frame] at h\n  simpa only [payload,SemiprimeD1TensorTapeFieldBounds.fieldSteps_frame] using h\n\n/-- Every skipped field's actual copied bits are physically popped. -/\ntheorem clear_skipped (word heap counter reference reader depth work:List Bool) :\n    Runs (word.length+1) (.inl .clearSkipped) (payload heap counter reference reader depth work word [])\n      (.inl .scan) (payload heap counter reference reader depth work [] []) := by\n  induction word with\n  | nil =>\n    apply one_base _ _ (.pop .output (.inl .scan) (.inl .clearSkipped) (.inl .clearSkipped)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> simp [B.execute,payload,Function.update]\n  | cons bit word ih =>\n    have h0:Runs 1 (.inl .clearSkipped) (payload heap counter reference reader depth work (bit::word) [])\n        (.inl .clearSkipped) (payload heap counter reference reader depth work word []):=by\n      apply one_base _ _ (.pop .output (.inl .scan) (.inl .clearSkipped) (.inl .clearSkipped)) _ _ rfl\n      · cases bit <;> rfl\n      · funext k;cases k <;> simp [B.execute,payload,Function.update]\n    have h:=h0.trans ih\n    convert h using 1\n    simp only [List.length_cons]\n    omega\n\n/-- The final reader suffix is physically cleared, preserving heap and returned record. -/\ntheorem clear_reader (reader heap counter reference output:List Bool) :\n    Runs (reader.length+1) (.inl .clearReader) (payload heap counter reference reader [] [] output [true])\n      (.inl .halt) (payload heap counter reference [] [] [] output [true]) := by\n  induction reader with\n  | nil =>\n    apply one_base _ _ (.pop .reader (.inl .halt) (.inl .clearReader) (.inl .clearReader)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> simp [B.execute,payload,Function.update]\n  | cons bit reader ih =>\n    have h0:Runs 1 (.inl .clearReader) (payload heap counter reference (bit::reader) [] [] output [true])\n        (.inl .clearReader) (payload heap counter reference reader [] [] output [true]):=by\n      apply one_base _ _ (.pop .reader (.inl .halt) (.inl .clearReader) (.inl .clearReader)) _ _ rfl\n      · cases bit <;> rfl\n      · funext k;cases k <;> simp [B.execute,payload,Function.update]\n    have h:=h0.trans ih\n    convert h using 1\n    simp only [List.length_cons]\n    omega\n\n/-- Physical newest-first framing of a finite record list with an existing byte tail. -/\ndef tape (records:List (List Bool)) (tail:List Bool) : List Bool := records.foldr frame tail\n\n/-- Exact executed scan budget; no native budget is an instruction operand. -/\ndef scanTime : List (List Bool)→ℕ\n  | [] => 1\n  | word::words => 9*word.length+10+scanTime words\n\n/-- Actual skip loop scans, verifies and clears each newer allocator-produced record. -/\ntheorem scan_fields (newer:List (List Bool)) (tail heap counter reference:List Bool) :\n    Runs (scanTime newer) (.inl .scan)\n      (payload heap counter reference (tape newer tail) (List.replicate newer.length true) [] [] [])\n      (.inl .finalCall) (payload heap counter reference tail [] [] [] []) := by\n  induction newer with\n  | nil =>\n    apply one_base _ _ (.pop .depth (.inl .finalCall) (.inl .skipCall) (.inl .skipCall)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> simp [B.execute,payload,tape,Function.update]\n  | cons word newer ih =>\n    let rest:=tape newer tail\n    let depth:=List.replicate newer.length true\n    have h0:Runs 1 (.inl .scan) (payload heap counter reference (frame word rest) (true::depth) [] [] [])\n        (.inl .skipCall) (payload heap counter reference (frame word rest) depth [] [] []):=by\n      apply one_base _ _ (.pop .depth (.inl .finalCall) (.inl .skipCall) (.inl .skipCall)) _ _ rfl\n      · rfl\n      · funext k;cases k <;> simp [B.execute,payload,Function.update]\n    have h1:=parse_field heap counter reference word rest depth [] [] (.inl .skipCall) (.inl .afterSkip) rfl\n    have h2:Runs 1 (.inl .afterSkip) (payload heap counter reference rest depth [] word [true])\n        (.inl .clearSkipped) (payload heap counter reference rest depth [] word []):=by\n      apply one_base _ _ (.pop .valid (.inl .bad) (.inl .bad) (.inl .clearSkipped)) _ _ rfl\n      · rfl\n      · funext k;cases k <;> simp [B.execute,payload,Function.update]\n    have h3:=clear_skipped word heap counter reference rest depth []\n    have h:=h0.trans (h1.trans (h2.trans (h3.trans ih)))\n    change Runs (scanTime (word::newer)) (.inl .scan)\n      (payload heap counter reference (frame word rest) (List.replicate (newer.length+1) true) [] [] [])\n      (.inl .finalCall) (payload heap counter reference tail [] [] [] [])\n    rw [List.replicate_succ]\n    convert h using 1\n    simp only [scanTime]\n    omega\n\n/-- Actual final parse, validity inspection and complete reader clearing. -/\ntheorem final_field (word older heap counter reference:List Bool) :\n    Runs (8*word.length+older.length+9) (.inl .finalCall)\n      (payload heap counter reference (frame word older) [] [] [] [])\n      (.inl .halt) (payload heap counter reference [] [] [] word [true]) := by\n  have h0:=parse_field heap counter reference word older [] [] [] (.inl .finalCall) (.inl .afterFinal) rfl\n  have h1:Runs 1 (.inl .afterFinal) (payload heap counter reference older [] [] word [true])\n      (.inl .clearReader) (payload heap counter reference older [] [] word [true]):=by\n    apply one_base _ _ (.peek .valid (.inl .bad) (.inl .bad) (.inl .clearReader)) _ _ rfl\n    · rfl\n    · rfl\n  have h2:=clear_reader older heap counter reference word\n  have h:=h0.trans (h1.trans h2)\n  convert h using 1\n  omega\n/-- Actual allocator bytes expose newer records in newest-first order. -/\ntheorem heap_decomposition (before:List (List Bool)) (word:List Bool) (after:List (List Bool)) :\n    SemiprimeD1StackHeapAllocate.heapBytes (before++word::after)=\n      tape after.reverse (frame word (SemiprimeD1StackHeapAllocate.heapBytes before)) := by\n  simp only [SemiprimeD1StackHeapAllocate.heapBytes,List.foldl_append,List.foldl_cons,tape,List.foldr_reverse]\n\n/-- Exact executed dereference time, assembled from actual component and local-loop costs. -/\ndef readTime (before:List (List Bool)) (word:List Bool) (after:List (List Bool)) : ℕ :=\n  let heap:=SemiprimeD1StackHeapAllocate.heapBytes (before++word::after)\n  (5*heap.length+5*(before++word::after).length+5*before.length+12)+\n    ((2*before.length+2)+(scanTime after.reverse+\n      (8*word.length+(SemiprimeD1StackHeapAllocate.heapBytes before).length+9)))+1\n\n/-- Exact actual successful heap-read output, with every work stack cleared. -/\ndef done (heap counter reference word:List Bool) : C.State Stack Label :=\n  ⟨none,none,none,payload heap counter reference [] [] [] word [true],[]⟩\n\n/-- Exact actual dereference of a record in the original allocator's append order. -/\ntheorem read_split (before:List (List Bool)) (word:List Bool) (after:List (List Bool)) :\n    C.run program (readTime before word after)\n      (initial (SemiprimeD1StackHeapAllocate.heapBytes (before++word::after))\n        (List.replicate (before++word::after).length true) (List.replicate before.length true))=\n      some (done (SemiprimeD1StackHeapAllocate.heapBytes (before++word::after))\n        (List.replicate (before++word::after).length true) (List.replicate before.length true) word) := by\n  let heap:=SemiprimeD1StackHeapAllocate.heapBytes (before++word::after)\n  let counter:=List.replicate (before++word::after).length true\n  let reference:=List.replicate before.length true\n  have h0:=prepare heap counter reference\n  have h1:=acquire_depth before.length after.length heap counter reference heap\n  have hc:counter=List.replicate (before.length+after.length+1) true:=by\n    dsimp only [counter]\n    congr 1\n    simp only [List.length_append,List.length_cons]\n    omega\n  have hd:List.replicate after.length true=List.replicate after.reverse.length true:=by simp\n  rw [←hc,hd] at h1\n  have hheap:heap=tape after.reverse (frame word (SemiprimeD1StackHeapAllocate.heapBytes before)):=\n    heap_decomposition before word after\n  have h2:=scan_fields after.reverse (frame word (SemiprimeD1StackHeapAllocate.heapBytes before)) heap counter reference\n  rw [←hheap] at h2\n  have h3:=final_field word (SemiprimeD1StackHeapAllocate.heapBytes before) heap counter reference\n  have h:=h0.trans (h1.trans (h2.trans h3))\n  let time:=(5*heap.length+5*counter.length+5*reference.length+12)+\n    ((2*before.length+2)+(scanTime after.reverse+\n      (8*word.length+(SemiprimeD1StackHeapAllocate.heapBytes before).length+9)))\n  have hs:At (.inl .start) (payload heap counter reference [] [] [] [] []) [] (initial heap counter reference):=by\n    refine ⟨rfl,?_,rfl⟩\n    funext k;cases k <;> rfl\n  obtain ⟨finish,hfinish,hout⟩:=h [] (initial heap counter reference) hs\n  have he:time+1=readTime before word after:=by\n    simp only [time,readTime,counter,reference,heap,List.length_replicate]\n  rw [←he,SemiprimeD1StackReturnLink.run_add]\n  change (C.run program time (initial heap counter reference)).bind (C.run program 1)=_\n  have ht:time=(5*heap.length+5*counter.length+5*reference.length+12)+\n      ((2*before.length+2)+(scanTime after.reverse+\n        (8*word.length+(SemiprimeD1StackHeapAllocate.heapBytes before).length+9))):=rfl\n  rw [ht,hfinish,Option.bind_some]\n  rcases hout with ⟨hpc,hdata,hframes⟩\n  change C.step program finish=some (done heap counter reference word)\n  simp [C.step,SemiprimeD1StackCalls.step,hpc,program,C.execute,SemiprimeD1StackCalls.execute,\n    hdata,hframes,done]\nend RiemannGaussian.SemiprimeD1StackHeapReadExecution\n","RiemannGaussian.SemiprimeD1StackJetPointRead":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackJetPointExecution\n/-! # Actual cached binary coefficient reads inside convolution\nEach selected coefficient is physically parsed/copied from its existing encoded\nvector. Original arrays appear only in the refinement proof, not in machine code.\n-/\nset_option autoImplicit false\nset_option synthInstance.maxSize 4096\nset_option maxRecDepth 8192\nset_option maxHeartbeats 1000000\nnamespace RiemannGaussian.SemiprimeD1StackJetPointRead\nopen SemiprimeD1StackJetPoint SemiprimeD1StackJetPointExecution\nopen SemiprimeD1StackProcedureTrace (Runs)\nnamespace V\nexport SemiprimeD1StackJetRead (state store program)\nend V\n\n/-- Declarative invariant when one actual reader's index is prepared. -/\ndef reading (c : Cache) (i j acc query other : List Bool) (right : Bool) : Stack → List Bool :=\n  Function.update (loaded c i j acc (if right then other else []) (if right then [] else other))\n    (aux .index) query\n\n/-- Real cached read and all cleanup, at either literal reader-call site.\nThe only cache relation is exact physical input encoding; no getter answer,\nfield-bound oracle, or execution-clock supplier is an argument. -/\ntheorem read_call (c : Cache) (i j acc query other : List Bool) (right : Bool)\n    (words : List (List Bool))\n    (hc : (if right then c.b else c.a)=SemiprimeD1TensorTapeCodec.vectorBits words) :\n    Runs program (SemiprimeD1StackJetReadExecution.totalTime query words+1)\n      (if right then .readRightCall else .readLeftCall) (reading c i j acc query other right)\n      (if right then .multiply else .readRightCopy)\n      (Function.update (Function.update (reading c i j acc query other right) (aux .index) [])\n        (readStack right .output) ((words[query.length]?).getD [])) := by\n  apply SemiprimeD1StackProcedureInclusion.included_call program (readStack right) (Label.read right)\n    (readStack_injective right) V.program .start (fun _=>rfl)\n    (if right then .readRightCall else .readLeftCall) (if right then .multiply else .readRightCopy)\n    (by cases right <;> rfl) _\n    (V.state (some .start) none none (SemiprimeD1TensorTapeCodec.vectorBits words) [] query [] [] [] [] [])\n    (V.state none none none (SemiprimeD1TensorTapeCodec.vectorBits words) [] [] [] [] ((words[query.length]?).getD []) [] [])\n  · rfl\n  · rfl\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackJetReadExecution.source_run query words\n  · constructor\n    · intro k\n      cases right <;> cases k <;>\n        simp [reading,loaded,resting,readStack,aux,mulStack,\n          SemiprimeD1StackMultiplier.input,SemiprimeD1StackMultiplier.factor,V.state,V.store] at hc ⊢ <;> assumption\n    · intro k hk\n      rfl\n  · constructor\n    · intro k\n      cases right <;> cases k <;>\n        simp [reading,loaded,resting,readStack,aux,mulStack,\n          SemiprimeD1StackMultiplier.input,SemiprimeD1StackMultiplier.factor,V.state,V.store] at hc ⊢ <;> assumption\n    · intro k hk\n      have hi : k ≠ aux .index := fun he=>hk .index he.symm\n      have ho : k ≠ readStack right .output := fun he=>hk .output he.symm\n      simp only [Function.update_of_ne ho,Function.update_of_ne hi]\n\n/-- The actual read result restores the loop workspace and loads only the\nselected multiplier operand; padding is preserved verbatim. -/\ntheorem read_result (c : Cache) (i j acc query other : List Bool) (right : Bool) (word : List Bool) :\n    Function.update (Function.update (reading c i j acc query other right) (aux .index) [])\n      (readStack right .output) word=\n    loaded c i j acc (if right then other else word) (if right then word else other) := by\n  funext k\n  cases right <;> rcases k with k|k\n  · cases k <;> rfl\n  · rcases k with k|k\n    · rcases k with k|k\n      · rcases k with k|k\n        · cases k <;> rfl\n        · rcases k with k|k\n          · fin_cases k <;> rfl\n          · cases k <;> rfl\n      · cases k <;> rfl\n    · rcases k with k|k\n      · cases k <;> rfl\n      · cases k <;> rfl\n  · cases k <;> rfl\n  · rcases k with k|k\n    · rcases k with k|k\n      · rcases k with k|k\n        · cases k <;> rfl\n        · rcases k with k|k\n          · fin_cases k <;> rfl\n          · cases k <;> rfl\n      · cases k <;> rfl\n    · rcases k with k|k\n      · cases k <;> rfl\n      · cases k <;> rfl\n\n/-- Empty multiplier inputs are the actual clean loop invariant. -/\ntheorem loaded_empty (c : Cache) (i j acc : List Bool) :\n    loaded c i j acc [] []=resting c i j acc := by\n  unfold loaded\n  have hi : resting c i j acc (mulStack (.inl SemiprimeD1StackMultiplier.input))=[] := rfl\n  have hf : resting c i j acc (mulStack (.inl SemiprimeD1StackMultiplier.factor))=[] := rfl\n  rw [(Function.update_eq_self_iff.mpr hi.symm :\n    Function.update (resting c i j acc) (mulStack (.inl SemiprimeD1StackMultiplier.input)) []=resting c i j acc)]\n  exact Function.update_eq_self_iff.mpr hf.symm\n\n/-- Exact transition count of both physical cache reads and linked binary arithmetic. -/\ndef readPipelineTime (width i j acc : List Bool) (a b : List (List Bool)) : ℕ :=\n  let left:=(a[i.length]?).getD []\n  let right:=(b[j.length]?).getD []\n  ((((5*i.length+4)+(SemiprimeD1StackJetReadExecution.totalTime i a+1))+(5*j.length+4))+\n    (SemiprimeD1StackJetReadExecution.totalTime j b+1))+pipelineTime left right acc width\n\n/-- Complete actual selected-pair path: real counter copies, two physical\nvector reads, multiplication, modular addition and temporary cleanup. -/\ntheorem read_pipeline (c : Cache) (i j acc : List Bool) (a b : List (List Bool))\n    (ha : c.a=SemiprimeD1TensorTapeCodec.vectorBits a)\n    (hb : c.b=SemiprimeD1TensorTapeCodec.vectorBits b) :\n    Runs program (readPipelineTime c.width i j acc a b) .readLeftCopy (resting c i j acc) .inner\n      (resting c i j (SemiprimeD1StackJetScalarAddExecution.result\n        (SemiprimeD1StackJetScalarMulExecution.result ((a[i.length]?).getD []) ((b[j.length]?).getD []) c.width)\n        acc c.width)) := by\n  let left:=(a[i.length]?).getD []\n  let right:=(b[j.length]?).getD []\n  have h1:=copy_call .readI .readLeftCopy .readLeftCall (resting c i j acc) rfl (by rfl) (by rfl)\n  change Runs program (5*i.length+4) .readLeftCopy (resting c i j acc) .readLeftCall\n    (Function.update (resting c i j acc) (aux .index) i) at h1\n  have hprepare : Function.update (resting c i j acc) (aux .index) i=reading c i j acc i [] false := by\n    simp only [reading,Bool.false_eq_true,ite_false,loaded_empty]\n  rw [hprepare] at h1\n  have h2:=read_call c i j acc i [] false a ha\n  rw [read_result] at h2\n  change Runs program _ .readLeftCall _ .readRightCopy (loaded c i j acc left []) at h2\n  have h3:=copy_call .readJ .readRightCopy .readRightCall (loaded c i j acc left []) rfl (by rfl) (by rfl)\n  change Runs program (5*j.length+4) .readRightCopy (loaded c i j acc left []) .readRightCall\n    (reading c i j acc j left true) at h3\n  have h4:=read_call c i j acc j left true b hb\n  rw [read_result] at h4\n  change Runs program _ .readRightCall _ .multiply (loaded c i j acc left right) at h4\n  have h5:=pipeline_run c i j acc left right\n  exact SemiprimeD1StackProcedureTrace.runs_trans program _ _ _ _ _ _ _ _\n    (SemiprimeD1StackProcedureTrace.runs_trans program _ _ _ _ _ _ _ _\n      (SemiprimeD1StackProcedureTrace.runs_trans program _ _ _ _ _ _ _ _\n        (SemiprimeD1StackProcedureTrace.runs_trans program _ _ _ _ _ _ _ _ h1 h2) h3) h4) h5\n\nend RiemannGaussian.SemiprimeD1StackJetPointRead\n","RiemannGaussian.SemiprimeD1StackJetPointTerm":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackJetPointDecision\nimport RiemannGaussian.SemiprimeD1StackJetPointRead\nimport RiemannGaussian.SemiprimeD1StackJetPointOrder\n/-! # Closed actual physical convolution-pair execution\nBoth route/matching flags, both coefficients, the product and modular partial sum\nare acquired by literal included finite procedures. Arrays are proof-side input\nencoding relations only. There is no routing, coefficient, fit or time supplier.\n-/\nset_option autoImplicit false\nset_option synthInstance.maxSize 4096\nset_option maxRecDepth 8192\nset_option maxHeartbeats 1000000\nnamespace RiemannGaussian.SemiprimeD1StackJetPointTerm\nopen SemiprimeD1StackJetPoint SemiprimeD1StackJetPointExecution\nopen SemiprimeD1StackJetPointRouting SemiprimeD1StackJetPointDecision SemiprimeD1StackJetPointRead\nopen SemiprimeD1StackProcedureTrace (Runs runs_trans)\nopen SemiprimeD1StackUnaryDivmod (unary)\n\n/-- Concrete retained per-pair transition bound, including rejected pairs. -/\ndef pairBudget (ctx : SemiprimeD1JetAxes.Context) (c : Cache) (i j : ℕ)\n    (acc : List Bool) (a b : List (List Bool)) : ℕ :=\n  (5*c.axes.length+5*i+5*j+12)+(SemiprimeD1StackJetRouteExecution.budget ctx.axes i j+2)+\n    (i+j+6*c.target.length+11)+readPipelineTime c.width (unary i) (unary j) acc a b\n\n/-- One actual original pair is routed, selected, read and accumulated, with\nall temporary data consumed on both branches and every included call paid. -/\ntheorem pair_run (ctx : SemiprimeD1JetAxes.Context) (hp : ctx.Positive) (c : Cache)\n    (i j k : ℕ) (acc : List Bool) (a b : List (List Bool))\n    (ha : c.a=SemiprimeD1TensorTapeCodec.vectorBits a)\n    (hb : c.b=SemiprimeD1TensorTapeCodec.vectorBits b)\n    (haxes : c.axes=SemiprimeD1TensorTapeCodec.vectorBits (ctx.axes.map unary))\n    (hwidth : c.width.length=ctx.precision) (htarget : c.target.length=k) :\n    ∃ m ≤ pairBudget ctx c i j acc a b,\n      Runs program m .axesCopy (resting c (unary i) (unary j) acc) .inner\n        (resting c (unary i) (unary j) (SemiprimeD1StackJetPointOrder.pairStep ctx a b k (i,j) acc)) := by\n  have hprepare:=prepare_route ctx c i j acc haxes\n  obtain ⟨mr,hr,hroute⟩:=route_call ctx hp c i j acc\n  obtain ⟨ms,hs,hselect⟩:=route_select ctx c i j acc\n  have hpre:=runs_trans program _ _ _ _ _ _ _ _ (runs_trans program _ _ _ _ _ _ _ _ hprepare hroute) hselect\n  have hguard : (SemiprimeD1JetRouting.admissible ctx.axes i j ∧ SemiprimeD1JetRouting.sumIndex ctx.axes i j=k) ↔\n      (SemiprimeD1JetRouting.admissible ctx.axes i j ∧ i+j=c.target.length) := by\n    by_cases had : SemiprimeD1JetRouting.admissible ctx.axes i j\n    · rw [SemiprimeD1StackRouteArithmetic.sumIndex_eq_add ctx.axes i j had,htarget]\n    · simp [had]\n  by_cases hmatch : SemiprimeD1JetRouting.admissible ctx.axes i j ∧ i+j=c.target.length\n  · rw [ite_eq_left hmatch] at hpre\n    have hread:=read_pipeline c (unary i) (unary j) acc a b ha hb\n    have hh:=runs_trans program _ _ _ _ _ _ _ _ hpre hread\n    have hstep : SemiprimeD1StackJetPointOrder.pairStep ctx a b k (i,j) acc=\n        SemiprimeD1StackJetScalarAddExecution.result\n          (SemiprimeD1StackJetScalarMulExecution.result ((a[(unary i).length]?).getD [])\n            ((b[(unary j).length]?).getD []) c.width) acc c.width := by\n      simp only [SemiprimeD1StackJetPointOrder.pairStep,ite_eq_left (hguard.mpr hmatch),\n        SemiprimeD1StackJetScalarAddExecution.result,SemiprimeD1StackJetScalarMulExecution.result,\n        hwidth,SemiprimeD1JetRingBits.read_bits,unary,List.length_replicate]\n    rw [hstep]\n    refine ⟨_,?_,hh⟩\n    unfold pairBudget\n    omega\n  · rw [ite_eq_right hmatch] at hpre\n    have hstep : SemiprimeD1StackJetPointOrder.pairStep ctx a b k (i,j) acc=acc := by\n      simp only [SemiprimeD1StackJetPointOrder.pairStep,ite_eq_right (fun he=>hmatch (hguard.mp he))]\n    rw [hstep]\n    refine ⟨_,?_,hpre⟩\n    unfold pairBudget\n    omega\n\nend RiemannGaussian.SemiprimeD1StackJetPointTerm\n","RiemannGaussian.SemiprimeD1StackKernelLinearAcquisition":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackKernelLinearPower\nimport RiemannGaussian.SemiprimeD1StackKernelLinearSum\nimport RiemannGaussian.SemiprimeD1StackKernelLinearFit\n/-! # Actual original-input center, grid and displacement front door -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackKernelLinearAcquisition\nopen SemiprimeD1StackKernelLinear SemiprimeD1StackKernelLinearView\nopen SemiprimeD1StackKernelLinearPrimitives SemiprimeD1StackProcedureTrace\nnamespace P\nexport SemiprimeD1StackKernelLinearPower (result source_trace)\nend P\nnamespace Sum\nexport SemiprimeD1StackKernelLinearSum (value timeBound source_trace)\nend Sum\nnamespace Fit\nexport SemiprimeD1StackKernelLinearFit (displacement displacementTime displacement_trace grid_trace)\nend Fit\n/-- Actual stopped binary sum cache, before real displacement subtraction. -/\ndef sumWords (a t x y:List Bool):Words:={P.result a t x y with buffer:=Sum.value (P.result a t x y)}\n/-- Actual fitted displacement cache, before fitting original t. -/\ndef displacementWords (a t x y:List Bool):Words:=\n  {sumWords a t x y with displacement:=Fit.displacement (sumWords a t x y)}\n/-- Both actual fitted original index words, retaining every original input. -/\ndef gridWords (a t x y:List Bool):Words:=\n  {displacementWords a t x y with j:=SemiprimeD1StackWordFitExecution.result t (true::a)}\n/-- Exact acquired normalization-ready cache; no factor/result is present yet. -/\ndef readyWords (a t x y:List Bool):Words:={gridWords a t x y with alpha:=false::(P.result a t x y).center}\n/-- Real alpha copy and actual binary shift, with every original/cache field retained. -/\ntheorem alpha_trace (w:Words) (hs:w.scratch=[]) (ha:w.alpha=[]):\n    Runs program ((5*w.center.length+4)+1) (.local .alphaCopy) (data w) (.local .normalize)\n      (data {w with alpha:=false::w.center}):=by\n  have h0:=copy_call .centerAlpha (.local .alphaCopy) (.local .alphaShift) rfl (data w) w.center [] rfl ha hs\n  simp only [List.append_nil] at h0\n  change Runs program _ _ _ _ (Function.update (data w) (aux .alpha) w.center) at h0\n  simp only [data,bank_aux_update,SemiprimeD1StackKernelLinearView.set] at h0\n  have h1:=push_run (.local .alphaShift) (.local .normalize) (aux .alpha) false (data {w with alpha:=w.center}) rfl\n  change Runs program 1 _ _ _ (Function.update (data {w with alpha:=w.center}) (aux .alpha) (false::w.center)) at h1\n  simp only [data,bank_aux_update,SemiprimeD1StackKernelLinearView.set] at h1\n  simpa only [data] using join h0 h1\n/-- Own total actual acquisition clock, composed only from real call clocks. -/\ndef timeBound (a t x y:List Bool):Nat:=\n  (12*a.length+11)+Sum.timeBound (P.result a t x y)+Fit.displacementTime (sumWords a t x y)+\n    ((5*t.length+4)+SemiprimeD1StackKernelLinearCalls.fitTime t (true::a))+\n      ((5*(P.result a t x y).center.length+4)+1)\n/-- Original physical x range discharges the actual borrow check, without displacement advice. -/\ntheorem source_trace (a t x y:List Bool) (hx:SemiprimeBitArithmetic.bitValue x<2^a.length):\n    Runs program (timeBound a t x y) (.local .start) (data (sourceWords a t x y))\n      (.local .normalize) (data (readyWords a t x y)):=by\n  have h0:=P.source_trace a t x y\n  have h1:=Sum.source_trace (P.result a t x y) rfl rfl\n  have hb:(SemiprimeBitDivision.subBits (sumWords a t x y).buffer (sumWords a t x y).x false).borrow=false:=by\n    change (SemiprimeD1StackKernelLinearSpec.displaced a.length x y).borrow=false\n    exact SemiprimeD1StackKernelLinearSpec.displaced_borrow a.length x y hx\n  have h2:=Fit.displacement_trace (sumWords a t x y) rfl rfl rfl hb\n  have h3:=Fit.grid_trace (displacementWords a t x y) rfl rfl rfl\n  have h4:=alpha_trace (gridWords a t x y) rfl rfl\n  have hh:=join h0 (join h1 (join h2 (join h3 h4)))\n  simpa only [timeBound,readyWords,gridWords,displacementWords,sumWords,P.result,\n    SemiprimeD1StackKernelLinearPower.result,sourceWords,Nat.add_assoc] using hh\nend RiemannGaussian.SemiprimeD1StackKernelLinearAcquisition\n","RiemannGaussian.SemiprimeD1StackKernelLinearFinish":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackKernelLinearDivisionView\n/-! # Actual final divider/cache cleanup and literal accepted halt boundary -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackKernelLinearFinish\nopen SemiprimeD1StackKernelLinear SemiprimeD1StackKernelLinearView\nopen SemiprimeD1StackKernelLinearPrimitives SemiprimeD1StackKernelLinearDivisionView\nopen SemiprimeD1StackProcedureTrace\n/-- Actual final bank may still contain the zero branch's padded magnitude. -/\ndef input (w:Words) (mag remainder quotient:List Bool):Stack→List Bool:=\n  bank (SemiprimeD1StackDivider.payload [] [] [] [] [] [] mag remainder quotient [] []) w\n/-- The real magnitude cleanup produces the identical clean divider boundary. -/\ntheorem input_output_update (w:Words) (mag remainder quotient:List Bool):\n    Function.update (input w mag remainder quotient) (arithmetic .output) []=\n      divisionData w [] [] remainder quotient:=by\n  funext r;rcases r with r|r\n  · rcases r with r|r <;> cases r <;> rfl\n  · rfl\n/-- Every retained binary result and source word survives actual private cleanup. -/\ndef result (w:Words):Words:={w with buffer:=[],valid:=[true]}\n/-- Own actual cleanup clock includes four EOF pops, real returns and accepted bit push. -/\ndef timeBound (w:Words) (mag remainder quotient:List Bool):Nat:=mag.length+w.buffer.length+quotient.length+remainder.length+13\n/-- Both branch paths execute the same actual final cleanup and accepted push. -/\ntheorem source_trace (w:Words) (mag remainder quotient:List Bool) (hv:w.valid=[]):\n    Runs program (timeBound w mag remainder quotient) (.local .clearDelta) (input w mag remainder quotient)\n      (.local .done) (data (result w)):=by\n  have h0:=drain_call (.local .clearDelta) (.local .clearBuffer) (arithmetic .output)\n    (input w mag remainder quotient) mag rfl rfl\n  rw [input_output_update] at h0\n  have h1:=drain_call (.local .clearBuffer) (.local .clearQuotient) (aux .buffer)\n    (divisionData w [] [] remainder quotient) w.buffer rfl rfl\n  rw [divisionData_aux_update] at h1\n  have h2:=drain_call (.local .clearQuotient) (.local .clearRemainder) (divider (.inr .quotient))\n    (divisionData {w with buffer:=[]} [] [] remainder quotient) quotient rfl rfl\n  rw [divisionData_quotient_update] at h2\n  have h3:=drain_call (.local .clearRemainder) (.local .accept) (divider (.inr .remainder))\n    (divisionData {w with buffer:=[]} [] [] remainder []) remainder rfl rfl\n  rw [divisionData_remainder_update,divisionData_empty] at h3\n  have h4:=push_run (.local .accept) (.local .done) (aux .valid) true (data {w with buffer:=[]}) rfl\n  change Runs program 1 _ _ _ (Function.update (data {w with buffer:=[]}) (aux .valid) (true::w.valid)) at h4\n  simp only [data,bank_aux_update,SemiprimeD1StackKernelLinearView.set] at h4\n  have hh:=join h0 (join h1 (join h2 (join h3 h4)))\n  simpa only [timeBound,result,data,hv,SemiprimeD1StackKernelLinearView.set,List.length_nil,\n    Nat.add_assoc,Nat.add_comm,Nat.add_left_comm] using hh\nend RiemannGaussian.SemiprimeD1StackKernelLinearFinish\n","RiemannGaussian.SemiprimeD1StackLeafPolynomial":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackLeafExecution\nimport RiemannGaussian.SemiprimeD1StackVertexProductPolynomial\n/-! # Fixed polynomial physical leaf overhead with the actual 2^M enumeration -/\nset_option autoImplicit false\nset_option maxRecDepth 32768\nset_option maxHeartbeats 2500000\nnamespace RiemannGaussian.SemiprimeD1StackLeafPolynomial\nopen SemiprimeD1StackLeaf SemiprimeD1StackLeafState\nopen SemiprimeD1TensorTapeCodec (vectorBits tape)\nopen SemiprimeD1StackVertexProductPolynomial (vectorBound preparedPolynomial)\n\n/-- Literal records contain every encoded original field and every vertex tag. -/\ntheorem records_caps (vertices : List SemiprimeD1LeafCounter.Vertex) :\n    vertices.length≤(SemiprimeD1StackVertexProduct.records vertices).length ∧\n    ∀v∈vertices,(SemiprimeD1StackVertexReadExecution.portTape v.ports).length≤\n      (SemiprimeD1StackVertexProduct.records vertices).length ∧\n      (tape v.table).length≤(SemiprimeD1StackVertexProduct.records vertices).length := by\n  induction vertices with\n  | nil => simp [SemiprimeD1StackVertexProduct.records]\n  | cons x xs ih =>\n    have hlen : (SemiprimeD1StackVertexProduct.records (x::xs)).length=\n        2*(SemiprimeD1StackVertexReadExecution.portTape x.ports).length+2*(tape x.table).length+\n          (SemiprimeD1StackVertexProduct.records xs).length+3 := by\n      simp [SemiprimeD1StackVertexProduct.records,SemiprimeSourceHistogramKeyBits.frame_length]\n      omega\n    constructor\n    · simp only [List.length_cons]\n      omega\n    · intro y hy\n      rcases List.mem_cons.mp hy with rfl|hy\n      · constructor <;> omega\n      · have hh:=ih.2 y hy\n        constructor <;> omega\n\n/-- Fixed polynomial covering one full assignment parse/product/add/cleanup. -/\ndef roundPolynomial (S : ℕ) : ℕ :=\n  8*S+8+(preparedPolynomial S+2)+(200*(S+1)*(2*vectorBound S+S+2)+1)+\n    (5*vectorBound S+4)+(vectorBound S+1)+(S+1)\n\n/-- The reached product/add round has a closed polynomial cap from original\nliteral-table data invariants and physical context/input dimensions only. -/\ntheorem roundBudget_le (ctx : SemiprimeD1JetAxes.Context)\n    (vertices : List SemiprimeD1LeafCounter.Vertex) (p : PS.Values) (word : List Bool)\n    (acc : List (List Bool)) (S : ℕ)\n    (hv : ∀x∈vertices,SemiprimeD1TensorTables.Good ctx x.table ∧\n      (SemiprimeD1StackVertexReadExecution.portTape x.ports).length≤S ∧ (tape x.table).length≤S)\n    (hcount : vertices.length≤S) (hrecords : (p .vertices).length≤S)\n    (hr : ctx.rank≤S) (hp : ctx.precision≤S) (ha : ctx.axes.length≤S)\n    (haxes : (p .axes).length≤S) (hw : (p .width).length≤S) (hrank : (p .rank).length≤S)\n    (hword : word.length≤S) (hacc : (vectorBits acc).length≤vectorBound S) :\n    SemiprimeD1StackLeafRound.roundBudget ctx vertices p word acc≤roundPolynomial S := by\n  let entry:=(SemiprimeD1TensorTapeLeaf.evaluateAssignment ctx vertices word).words\n  have hentry:=SemiprimeD1StackVertexProductPolynomial.good_vector_length ctx entry\n    (SemiprimeD1TensorTapeLeaf.evaluateAssignment_good ctx vertices word) S hr hp\n  have hout:=SemiprimeD1StackVertexProductPolynomial.good_vector_length ctx\n    (SemiprimeD1JetRingBits.add ctx entry acc).words (SemiprimeD1LeafCounterBounds.add_good ctx _ _) S hr hp\n  have hprod:=SemiprimeD1StackVertexProductPolynomial.preparedBudget_le ctx vertices\n    (Function.update p .assignment word) S hv hcount (by simpa using hrecords) hr hp ha\n    (by simpa using haxes) (by simpa using hw) (by simpa using hrank) (by simpa using hword)\n  have hadd:=SemiprimeD1StackJetAddExecution.totalTime_le (p .width) (p .rank) entry acc\n  have hadd' : SemiprimeD1StackJetAddExecution.totalTime (p .width) (p .rank) entry acc≤\n      200*(S+1)*(2*vectorBound S+S+2) := by\n    apply hadd.trans\n    unfold SemiprimeD1StackJetAddExecution.timeBound\n    have hm:=Nat.mul_le_mul (Nat.add_le_add_right hrank 1)\n      (by omega : (vectorBits entry).length+(vectorBits acc).length+(p .width).length+2≤2*vectorBound S+S+2)\n    nlinarith [Nat.mul_le_mul_left 200 hm]\n  dsimp only [SemiprimeD1StackLeafRound.roundBudget,roundPolynomial]\n  dsimp only [entry] at hentry hout hadd'\n  omega\n\n/-- No enumeration-count oracle: this bound follows the actual reached dense\naccumulators, each new one canonical by the actual adder. -/\ntheorem loopBudget_le (ctx : SemiprimeD1JetAxes.Context)\n    (vertices : List SemiprimeD1LeafCounter.Vertex) (p : PS.Values)\n    (words : List (List Bool)) (acc : List (List Bool)) (S : ℕ)\n    (hv : ∀x∈vertices,SemiprimeD1TensorTables.Good ctx x.table ∧\n      (SemiprimeD1StackVertexReadExecution.portTape x.ports).length≤S ∧ (tape x.table).length≤S)\n    (hcount : vertices.length≤S) (hrecords : (p .vertices).length≤S)\n    (hr : ctx.rank≤S) (hp : ctx.precision≤S) (ha : ctx.axes.length≤S)\n    (haxes : (p .axes).length≤S) (hw : (p .width).length≤S) (hrank : (p .rank).length≤S)\n    (hwords : ∀word∈words,word.length≤S) (hacc : (vectorBits acc).length≤vectorBound S) :\n    SemiprimeD1StackLeafLoop.loopBudget ctx vertices p words acc≤words.length*(1+roundPolynomial S)+1 := by\n  induction words generalizing acc with\n  | nil => simp [SemiprimeD1StackLeafLoop.loopBudget]\n  | cons word rest ih =>\n    have hword:=hwords word (by simp)\n    have hround:=roundBudget_le ctx vertices p word acc S hv hcount hrecords hr hp ha haxes hw hrank hword hacc\n    let next:=(SemiprimeD1JetRingBits.add ctx\n      (SemiprimeD1TensorTapeLeaf.evaluateAssignment ctx vertices word).words acc).words\n    have hout:=SemiprimeD1StackVertexProductPolynomial.good_vector_length ctx next\n      (SemiprimeD1LeafCounterBounds.add_good ctx _ _) S hr hp\n    have ht:=ih next (fun w hw=>hwords w (by simp [hw])) hout\n    change 1+SemiprimeD1StackLeafRound.roundBudget ctx vertices p word acc+\n      SemiprimeD1StackLeafLoop.loopBudget ctx vertices p rest\n        (SemiprimeD1JetRingBits.add ctx (SemiprimeD1TensorTapeLeaf.evaluateAssignment ctx vertices word).words acc).words≤_\n    simp only [List.length_cons]\n    nlinarith\n\nend RiemannGaussian.SemiprimeD1StackLeafPolynomial\n","RiemannGaussian.SemiprimeD1StackMarkedRootRecordsIntegral":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1RootOwnerTables\nimport RiemannGaussian.SemiprimeD1PackedMomentPrecision\n/-! # Integer and canonical-shape facts for physically relayed root tables\nThese proofs inspect original literal coefficient words over the natural\nnumbers. They do not transfer equality modulo four to a larger modulus.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackMarkedRootRecordsIntegral\nopen SemiprimeBitArithmetic SemiprimeD1TensorTables\nnamespace O\nexport SemiprimeD1RootOwnerTables (producer weight rootContext)\nend O\n/-- Each Boolean contribution is at most one, including empty incident scopes. -/\ntheorem bitNat_le_one (b : Bool) : bitNat b ≤ 1 := by cases b <;> decide\n/-- The original owner entry is the exact integer sum zero, one or two. -/\ntheorem owner_value {n : Nat} (fixed : List (Fin n × Bool)) (v : Fin n) (bits : List Bool) :\n    (O.producer fixed v bits).words.map bitValue=[O.weight fixed v bits] := by\n  have hb (low high : Bool) : (bitValue [low]+bitValue [high]) < 2^2 := by\n    cases low <;> cases high <;> decide\n  change [bitValue (SemiprimeD1JetScalarBits.add 2 _ _).bits]=_\n  rw [SemiprimeD1JetScalarBits.add_value,Nat.mod_eq_of_lt (hb _ _),\n    SemiprimeD1RootOwnerTables.prefixRun_value,SemiprimeD1RootOwnerTables.prefixRun_value,\n    SemiprimeD1RootOwnerTables.sameRun_value,SemiprimeD1RootOwnerTables.sameRun_value]\n  rfl\n/-- The retained owner multiplicity has an exact natural-number upper bound. -/\ntheorem owner_weight_le_two {n : Nat} (fixed : List (Fin n × Bool)) (v : Fin n) (bits : List Bool) :\n    O.weight fixed v bits ≤ 2 := by\n  unfold O.weight\n  exact Nat.add_le_add (bitNat_le_one _) (bitNat_le_one _)\n/-- Increasing scalar precision preserves every word's compactness and rank. -/\ntheorem goodWords_mono (axes : List Nat) (p q : Nat) (hp : p ≤ q)\n    (words : List (List Bool)) (h : GoodWords ⟨axes,p⟩ words) : GoodWords ⟨axes,q⟩ words := by\n  refine ⟨h.1,?_⟩\n  intro word hw\n  exact ⟨(h.2 word hw).1,((h.2 word hw).2).trans hp⟩\n/-- A complete relayed table remains Good after an actual precision increase. -/\ntheorem good_mono (axes : List Nat) (p q : Nat) (hp : p ≤ q)\n    {n : Nat} (table : Table n) (h : Good ⟨axes,p⟩ table) : Good ⟨axes,q⟩ table := by\n  induction table with\n  | leaf words => exact goodWords_mono axes p q hp words h\n  | fork low high ihlow ihhigh => exact ⟨ihlow h.1,ihhigh h.2⟩\n/-- Every original owner producer is canonical at any scalar precision at least two. -/\ntheorem owner_good {n : Nat} (fixed : List (Fin n × Bool)) (v : Fin n) (bits : List Bool)\n    (p : Nat) (hp : 2 ≤ p) : GoodWords ⟨[],p⟩ (O.producer fixed v bits).words :=\n  goodWords_mono [] 2 p hp _ (SemiprimeD1RootOwnerTables.producer_good fixed v bits)\n/-- All original owner materializations can be relayed without changing a byte. -/\ntheorem owner_table_good {n : Nat} (fixed : List (Fin n × Bool)) (v : Fin n)\n    (degree p : Nat) (hp : 2 ≤ p) :\n    Good ⟨[],p⟩ (SemiprimeD1RootOwnerTables.acquire fixed v degree).table :=\n  good_mono [] 2 p hp _ (SemiprimeD1RootOwnerTables.acquire_good fixed v degree)\nend RiemannGaussian.SemiprimeD1StackMarkedRootRecordsIntegral\n","RiemannGaussian.SemiprimeD1StackMarkedRootRecordsSide":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackMarkedRootRecordsRowView\nimport RiemannGaussian.SemiprimeD1StackMarkedRootRecordsPrimitives\n/-! # Actual unary-side to singleton conversion before the144-role source -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackMarkedRootRecordsSide\nopen SemiprimeD1StackMarkedRootRecords SemiprimeD1StackMarkedRootRecordsView\nopen SemiprimeD1StackMarkedRootRecordsRowView SemiprimeD1StackMarkedRootRecordsPrimitives\nopen SemiprimeD1StackProcedureTrace\n/-- Actual []/[TRUE] side parsing; the TRUE case additionally pays the real EOF peek. -/\ntheorem normalize (r : R.Stack → List Bool) (v : V.Stack → List Bool) (bits : List Bool)\n    (p : TableWork) (w : Work) (sideBit : Bool) :\n    ∃ t ≤ 3, Runs program t (ctl .sideRead)\n      (view r v bits {p with sideWord := []} {w with coord0 := if sideBit then [true] else []})\n      (ctl .clearOldTable) (view r v bits {p with sideWord := [sideBit]} {w with coord0 := []}) := by\n  cases sideBit\n  · have h0 : Runs program 1 (ctl .sideRead)\n        (view r v bits {p with sideWord := []} {w with coord0 := []}) (ctl .sideFalse)\n        (view r v bits {p with sideWord := []} {w with coord0 := []}) := by\n      apply one_base program _ _ (.pop (aux .coord0) (ctl .sideFalse) (ctl .abort) (ctl .sideEOF)) _ _ rfl\n      · rfl\n      · exact set_coord0 _ _ _ _ _ _\n    have h1 : Runs program 1 (ctl .sideFalse)\n        (view r v bits {p with sideWord := []} {w with coord0 := []}) (ctl .clearOldTable)\n        (view r v bits {p with sideWord := [false]} {w with coord0 := []}) := by\n      apply one_base program _ _ (.push side false (ctl .clearOldTable)) _ _ rfl\n      · rfl\n      · exact set_sideWord _ _ _ _ _ _\n    exact ⟨2,by omega,join h0 h1⟩\n  · have h0 : Runs program 1 (ctl .sideRead)\n        (view r v bits {p with sideWord := []} {w with coord0 := [true]}) (ctl .sideEOF)\n        (view r v bits {p with sideWord := []} {w with coord0 := []}) := by\n      apply one_base program _ _ (.pop (aux .coord0) (ctl .sideFalse) (ctl .abort) (ctl .sideEOF)) _ _ rfl\n      · rfl\n      · exact set_coord0 _ _ _ _ _ _\n    have h1 : Runs program 1 (ctl .sideEOF)\n        (view r v bits {p with sideWord := []} {w with coord0 := []}) (ctl .sideTrue)\n        (view r v bits {p with sideWord := []} {w with coord0 := []}) := by\n      apply one_base program _ _ (.peek (aux .coord0) (ctl .sideTrue) (ctl .abort) (ctl .abort)) _ _ rfl\n      · rfl\n      · rfl\n    have h2 : Runs program 1 (ctl .sideTrue)\n        (view r v bits {p with sideWord := []} {w with coord0 := []}) (ctl .clearOldTable)\n        (view r v bits {p with sideWord := [true]} {w with coord0 := []}) := by\n      apply one_base program _ _ (.push side true (ctl .clearOldTable)) _ _ rfl\n      · rfl\n      · exact set_sideWord _ _ _ _ _ _\n    exact ⟨3,by omega,join (join h0 h1) h2⟩\n/-- Every old table byte is physically erased before any new table computation. -/\ntheorem clear_table (r : R.Stack → List Bool) (v : V.Stack → List Bool) (bits : List Bool)\n    (p : TableWork) (w : Work) :\n    Runs program (p.tableWord.length+1) (ctl .clearOldTable) (view r v bits p w)\n      (ctl .inputTable) (view r v bits {p with tableWord := []} w) := by\n  have h := SemiprimeD1StackPhysicalLoops.drain program (ctl .clearOldTable) (ctl .inputTable)\n    table rfl (view r v bits p w) p.tableWord\n  rw [show Function.update (view r v bits p w) table p.tableWord=view r v bits p w from\n    Function.update_eq_self _ _,set_tableWord] at h\n  exact h\n/-- EMPTY parsed input tag really enters side decoding, including valid side zero. -/\ntheorem input_tag (r : R.Stack → List Bool) (v : V.Stack → List Bool) (bits : List Bool)\n    (p : TableWork) (w : Work) :\n    Runs program 1 (ctl .caseTag) (view r v bits p {w with tag := []})\n      (ctl .sideRead) (view r v bits p {w with tag := []}) := by\n  apply one_base program _ _ (.peek (aux .tag) (ctl .sideRead) (ctl .abort) (ctl .log)) _ _ rfl\n  · rfl\n  · rfl\n/-- Every other canonical original tag takes the actual byte-relay branch. -/\ntheorem relay_tag (r : R.Stack → List Bool) (v : V.Stack → List Bool) (bits : List Bool)\n    (p : TableWork) (w : Work) (tail : List Bool) :\n    Runs program 1 (ctl .caseTag) (view r v bits p {w with tag := true::tail})\n      (ctl .log) (view r v bits p {w with tag := true::tail}) := by\n  apply one_base program _ _ (.peek (aux .tag) (ctl .sideRead) (ctl .abort) (ctl .log)) _ _ rfl\n  · rfl\n  · rfl\nend RiemannGaussian.SemiprimeD1StackMarkedRootRecordsSide\n","RiemannGaussian.SemiprimeD1StackMultiplierLink":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackReturnLink\n\n/-! # Literal procedure inclusion for the fixed multiplier\nA source component's actual halt becomes a real return-frame pop. Both stack\nand label maps are fixed finite program data, and all unmapped payload is kept.\nThe final multiplier instantiates this with the proved Copy and Adder traces.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 800000\nnamespace RiemannGaussian.SemiprimeD1StackMultiplierLink\nnamespace B\nexport SemiprimeD1StackBytecode (Instruction State execute step run choose)\nend B\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State execute step run)\nend C\n\n/-- Literal stack/label substitution, with component halt replaced by real return. -/\ndef instruction {A K L G : Type} (stack : A → K) (label : L → G) :\n    B.Instruction A L → C.Instruction K G\n  | .push k bit next => .base (.push (stack k) bit (label next))\n  | .pop k empty low high => .base (.pop (stack k) (label empty) (label low) (label high))\n  | .peek k empty low high => .base (.peek (stack k) (label empty) (label low) (label high))\n  | .jump next => .base (.jump (label next))\n  | .halt => .ret\n\n/-- Exact mapped component cells and every untouched auxiliary cell. -/\ndef DataRel {A K : Type} (stack : A → K) (aux : K → List Bool)\n    (source : A → List Bool) (target : K → List Bool) : Prop :=\n  (∀i,target (stack i)=source i) ∧ (∀k,(∀i,stack i≠k) → target k=aux k)\n\n/-- Reading a prepared component projection requires no supplied operand. -/\ntheorem data_initial {A K : Type} (stack : A → K) (input : K → List Bool) :\n    DataRel stack input (fun i => input (stack i)) input := ⟨fun _ => rfl,fun _ _ => rfl⟩\n\n/-- One literal component write touches only its actual included stack. -/\ntheorem data_update {A K : Type} [DecidableEq A] [DecidableEq K]\n    (stack : A → K) (hinj : Function.Injective stack) (aux : K → List Bool)\n    (source : A → List Bool) (target : K → List Bool) (hd : DataRel stack aux source target)\n    (j : A) (bits : List Bool) :\n    DataRel stack aux (Function.update source j bits) (Function.update target (stack j) bits) := by\n  constructor\n  · intro i\n    by_cases h : i=j\n    · subst i\n      simp only [Function.update_self]\n    · have hs : stack i≠stack j := fun he => h (hinj he)\n      simpa only [Function.update_of_ne h,Function.update_of_ne hs] using hd.1 i\n  · intro k hk\n    have hs : k≠stack j := (hk j).symm\n    simpa only [Function.update_of_ne hs] using hd.2 k hk\n\n/-- The same mapped result and preserved auxiliary data determine the whole store. -/\ntheorem data_unique {A K : Type} (stack : A → K) (aux : K → List Bool)\n    (source : A → List Bool) (left right : K → List Bool)\n    (hl : DataRel stack aux source left) (hr : DataRel stack aux source right) : left=right := by\n  classical\n  funext k\n  by_cases hk : ∃i,stack i=k\n  · obtain ⟨i,rfl⟩:=hk\n    exact (hl.1 i).trans (hr.1 i).symm\n  · have hnone : ∀i,stack i≠k := by intro i hi;exact hk ⟨i,hi⟩\n    exact (hl.2 k hnone).trans (hr.2 k hnone).symm\n\n/-- Finite EOF/Boolean dispatch commutes with literal label inclusion. -/\ntheorem choose_map {L G : Type} (label : L → G) (empty low high : L) (bit : Option Bool) :\n    B.choose (label empty) (label low) (label high) bit=label (B.choose empty low high bit) := by\n  cases bit with\n  | none => rfl\n  | some bit => cases bit <;> rfl\n\n/-- Exact active/returned program counters and actual return stack. -/\ndef PcRel {A K L G : Type} (label : L → G) (returnTo : G) (frames : List G)\n    (source : B.State A L) (target : C.State K G) : Prop :=\n  match source.pc with\n  | none => target.pc=some returnTo ∧ target.frames=frames\n  | some pc => target.pc=some (label pc) ∧ target.frames=returnTo::frames\n\n/-- A component inclusion retains data, real continuation and all outer frames.\nRead flags are finite transient control and are deliberately unconstrained. -/\ndef Rel {A K L G : Type} (stack : A → K) (label : L → G) (aux : K → List Bool)\n    (returnTo : G) (frames : List G) (source : B.State A L) (target : C.State K G) : Prop :=\n  DataRel stack aux source.store target.data ∧ PcRel label returnTo frames source target\n\n/-- Every actual included instruction preserves its source/return correspondence. -/\ntheorem instruction_rel {A K L G : Type} [DecidableEq A] [DecidableEq K]\n    (stack : A → K) (label : L → G) (hinj : Function.Injective stack)\n    (aux : K → List Bool) (returnTo : G) (frames : List G)\n    (op : B.Instruction A L) (source : B.State A L) (target : C.State K G) (pc : L)\n    (hp : source.pc=some pc) (h : Rel stack label aux returnTo frames source target) :\n    Rel stack label aux returnTo frames (B.execute op source) (C.execute (instruction stack label op) target) := by\n  rcases h with ⟨hd,hpc⟩\n  have ht : target.pc=some (label pc) ∧ target.frames=returnTo::frames := by\n    simpa only [PcRel,hp] using hpc\n  cases op with\n  | push j bit next =>\n    constructor\n    · simpa only [instruction,B.execute,C.execute,hd.1 j] using\n        data_update stack hinj aux source.store target.data hd j (bit::source.store j)\n    · simp only [PcRel,instruction,B.execute,C.execute,ht.2,and_self]\n  | pop j empty low high =>\n    constructor\n    · simpa only [instruction,B.execute,C.execute,hd.1 j] using\n        data_update stack hinj aux source.store target.data hd j (source.store j).tail\n    · simp only [PcRel,instruction,B.execute,C.execute,hd.1 j,choose_map,ht.2,and_self]\n  | peek j empty low high =>\n    constructor\n    · exact hd\n    · simp only [PcRel,instruction,B.execute,C.execute,hd.1 j,choose_map,ht.2,and_self]\n  | jump next =>\n    constructor\n    · exact hd\n    · simp only [PcRel,instruction,B.execute,C.execute,ht.2,and_self]\n  | halt =>\n    constructor\n    · simpa only [instruction,B.execute,C.execute,ht.2] using hd\n    · simp only [PcRel,instruction,B.execute,C.execute,ht.2,and_self]\n\n/-- Successful component traces execute in the actual enclosing call program. -/\ntheorem run_rel {A K L G : Type} [DecidableEq A] [DecidableEq K]\n    (stack : A → K) (label : L → G) (hinj : Function.Injective stack)\n    (program : G → C.Instruction K G) (component : L → B.Instruction A L)\n    (hcode : ∀l,program (label l)=instruction stack label (component l))\n    (aux : K → List Bool) (returnTo : G) (frames : List G)\n    (fuel : ℕ) (s out : B.State A L) (t : C.State K G)\n    (h : Rel stack label aux returnTo frames s t)\n    (hr : B.run component fuel s=some out) :\n    ∃finish,C.run program fuel t=some finish ∧ Rel stack label aux returnTo frames out finish := by\n  induction fuel generalizing s t with\n  | zero => change some s=some out at hr; cases hr; exact ⟨t,rfl,h⟩\n  | succ fuel ih =>\n    rw [show fuel+1=1+fuel by omega,SemiprimeD1StackCopy.run_add] at hr\n    change (B.step component s).bind (B.run component fuel)=some out at hr\n    cases hp:s.pc with\n    | none => simp [B.step,SemiprimeD1StackBytecode.step,hp] at hr\n    | some pc =>\n      have hs : B.step component s=some (B.execute (component pc) s) := by\n        simp [B.step,SemiprimeD1StackBytecode.step,hp]\n      rw [hs,Option.bind_some] at hr\n      have htpc : t.pc=some (label pc) := by\n        have hh:=h.2\n        rw [PcRel,hp] at hh\n        exact hh.1\n      have ht : C.step program t=some (C.execute (instruction stack label (component pc)) t) := by\n        simp [C.step,SemiprimeD1StackCalls.step,htpc,hcode]\n      obtain ⟨finish,hfinish,hrel⟩:=ih (B.execute (component pc) s)\n        (C.execute (instruction stack label (component pc)) t)\n        (instruction_rel stack label hinj aux returnTo frames _ s t pc hp h) hr\n      refine ⟨finish,?_,hrel⟩\n      rw [show fuel+1=1+fuel by omega,SemiprimeD1StackReturnLink.run_add]\n      change (C.step program t).bind (C.run program fuel)=some finish\n      rw [ht,Option.bind_some,hfinish]\n\nend RiemannGaussian.SemiprimeD1StackMultiplierLink\n","RiemannGaussian.SemiprimeD1StackNetworkOwnerIndex":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackVertexProduct\nimport RiemannGaussian.SemiprimeD1StackIncrementBytecode\nimport RiemannGaussian.SemiprimeD1StackFrame\nimport RiemannGaussian.SemiprimeD1StackReverseWord\n\n/-! # Physical network-record acquisition of the occurrence-to-owner index\nOnly literal vertex-record bytes and an actually acquired bounded unary left\ncount enter. The first leftCount records are parsed physically, including their\ntables; each unary occurrence port is paired with a physically incremented\nbinary owner ordinal. Every table parse/drain, pair frame and reversal is paid.\nThe original record tape and left count are retained; the factor-record suffix\nremains on the reader for the subsequent actual factor-row acquisition.\nThis is a generic physical source stage, not an original-N factoring theorem.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackNetworkOwnerIndex\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State)\nend C\nnamespace Field\nexport SemiprimeD1TensorTapeFieldBytecode (Stack Label code active)\nend Field\nnamespace Inc\nexport SemiprimeD1StackIncrementBytecode (Label code entry)\nend Inc\n/-- All seventeen physical words, with numeric owner ordinals stored in binary. -/\ninductive Stack where\n  | vertices | leftCount | reader | todo | ports | table | valid | key | owner | ownerNext\n  | incrementScratch | scratch | fieldScratch | frameBuffer | frameScratch | history | output\n  deriving DecidableEq,Repr\ninstance :Fintype Stack :=Fintype.ofList\n  [.vertices,.leftCount,.reader,.todo,.ports,.table,.valid,.key,.owner,.ownerNext,\n    .incrementScratch,.scratch,.fieldScratch,.frameBuffer,.frameScratch,.history,.output]\n  (by intro k;cases k <;> simp)\n/-- The two actual preserving-copy operand maps. -/\ninductive Copy where | vertices | count deriving DecidableEq\ninstance :Fintype Copy :=Fintype.ofList [.vertices,.count] (by intro k;cases k <;> simp)\n/-- Every copied source, target and scratch word is physically distinct. -/\ndef copyStack (what:Copy) (k:Fin 3) :Stack :=\n  if k=0 then (if what=.vertices then .vertices else .leftCount)\n  else if k=1 then (if what=.vertices then .reader else .todo) else .scratch\n/-- The three actual framed fields: ports, table and one current occurrence key. -/\ninductive Part where | ports | table | key deriving DecidableEq\ninstance :Fintype Part :=Fintype.ofList [.ports,.table,.key] (by intro k;cases k <;> simp)\n/-- Port/table parsing consumes actual record bytes; port keys come from the actual port vector. -/\ndef fieldStack (part:Part) :Field.Stack→Stack\n  | .inl .input=>if part=.key then .ports else .reader\n  | .inl .scratch=>.fieldScratch\n  | .inl .output=>match part with | .ports=>.ports | .table=>.table | .key=>.key\n  | .inr _=>.valid\n/-- Both components of the actual key/owner pair use preserving field framing. -/\ninductive Frame where | value | key deriving DecidableEq\ninstance :Fintype Frame :=Fintype.ofList [.value,.key] (by intro k;cases k <;> simp)\n/-- Owner values are binary; bounded unary port keys retain the original record ABI. -/\ndef frameStack (what:Frame) (k:Fin 3) :Stack :=\n  if k=0 then (if what=.value then .owner else .key)\n  else if k=1 then .frameBuffer else .frameScratch\n/-- Actual reversals for pair history, binary-counter transfer and whole output. -/\ninductive Reverse where | pair | ownerFirst | ownerSecond | finish deriving DecidableEq\ninstance :Fintype Reverse :=Fintype.ofList [.pair,.ownerFirst,.ownerSecond,.finish] (by intro k;cases k <;> simp)\n/-- Two physical counter reversals transfer its little-endian bits without reversing their order. -/\ndef reverseStack (what:Reverse) (k:Fin 2) :Stack :=\n  if k=0 then match what with\n    | .pair=>.frameBuffer | .ownerFirst=>.ownerNext | .ownerSecond=>.incrementScratch | .finish=>.history\n  else match what with\n    | .pair=>.history | .ownerFirst=>.incrementScratch | .ownerSecond=>.owner | .finish=>.output\n/-- Actual three-role fixed-width binary incrementer inclusion. -/\ndef incrementStack :SemiprimeD1TensorTapeFieldMachine.Stack→Stack\n  | .input=>.owner | .scratch=>.incrementScratch | .output=>.ownerNext\n/-- Literal source/count initialization, record/port loops, counter update and final return. -/\ninductive Control where\n  | start | zeroCount | zeroSeed | zeroLoop | zeroPush | copyCount | owners | vertexTag\n  | parsePorts | portsValid | parseTable | tableValid | clearTable | portLoop | parseKey | keyValid\n  | valueFrame | keyFrame | pairTag | reversePair | clearKey | increment | carry\n  | ownerFirst | ownerSecond | finish | reverseOutput | done | abort\n  deriving DecidableEq\ninstance :Fintype Control :=Fintype.ofList\n  [.start,.zeroCount,.zeroSeed,.zeroLoop,.zeroPush,.copyCount,.owners,.vertexTag,\n    .parsePorts,.portsValid,.parseTable,.tableValid,.clearTable,.portLoop,.parseKey,.keyValid,\n    .valueFrame,.keyFrame,.pairTag,.reversePair,.clearKey,.increment,.carry,\n    .ownerFirst,.ownerSecond,.finish,.reverseOutput,.done,.abort]\n  (by intro k;cases k <;> simp)\n/-- All actual code and return locations are fixed finite before every network. -/\ninductive Label where\n  | local (pc:Control) | copy (what:Copy) (pc:Fin 9) | field (part:Part) (pc:Field.Label)\n  | frame (what:Frame) (pc:Fin 11) | reverse (what:Reverse) (pc:Fin 4) | increment (pc:Inc.Label)\n  deriving Fintype\n/-- One concrete program extracts the owner index from physical vertex bytes. -/\ndef program :Label→C.Instruction Stack Label\n  | .local .start=>.call (.copy .vertices 0) (.local .zeroCount)\n  | .local .zeroCount=>.call (.copy .count 0) (.local .zeroSeed)\n  | .local .zeroSeed=>.base (.push .owner false (.local .zeroLoop))\n  | .local .zeroLoop=>.base (.pop .todo (.local .copyCount) (.local .abort) (.local .zeroPush))\n  | .local .zeroPush=>.base (.push .owner false (.local .zeroLoop))\n  | .local .copyCount=>.call (.copy .count 0) (.local .owners)\n  | .local .owners=>.base (.pop .todo (.local .finish) (.local .abort) (.local .vertexTag))\n  | .local .vertexTag=>.base (.pop .reader (.local .abort) (.local .abort) (.local .parsePorts))\n  | .local .parsePorts=>.call (.field .ports (Field.active .tagPop (none,false))) (.local .portsValid)\n  | .local .portsValid=>.base (.pop .valid (.local .abort) (.local .abort) (.local .parseTable))\n  | .local .parseTable=>.call (.field .table (Field.active .tagPop (none,false))) (.local .tableValid)\n  | .local .tableValid=>.base (.pop .valid (.local .abort) (.local .abort) (.local .clearTable))\n  | .local .clearTable=>.base (.pop .table (.local .portLoop) (.local .clearTable) (.local .clearTable))\n  | .local .portLoop=>.base (.pop .ports (.local .abort) (.local .increment) (.local .parseKey))\n  | .local .parseKey=>.call (.field .key (Field.active .tagPop (none,false))) (.local .keyValid)\n  | .local .keyValid=>.base (.pop .valid (.local .abort) (.local .abort) (.local .valueFrame))\n  | .local .valueFrame=>.call (.frame .value 0) (.local .keyFrame)\n  | .local .keyFrame=>.call (.frame .key 0) (.local .pairTag)\n  | .local .pairTag=>.base (.push .frameBuffer true (.local .reversePair))\n  | .local .reversePair=>.call (.reverse .pair 0) (.local .clearKey)\n  | .local .clearKey=>.base (.pop .key (.local .portLoop) (.local .clearKey) (.local .clearKey))\n  | .local .increment=>.call (.increment Inc.entry) (.local .carry)\n  | .local .carry=>.base (.pop .ownerNext (.local .abort) (.local .ownerFirst) (.local .abort))\n  | .local .ownerFirst=>.call (.reverse .ownerFirst 0) (.local .ownerSecond)\n  | .local .ownerSecond=>.call (.reverse .ownerSecond 0) (.local .owners)\n  | .local .finish=>.base (.push .history false (.local .reverseOutput))\n  | .local .reverseOutput=>.call (.reverse .finish 0) (.local .done)\n  | .local .done|.local .abort=>.base .halt\n  | .copy what pc=>SemiprimeD1StackMultiplierLink.instruction (copyStack what) (Label.copy what)\n      (SemiprimeD1StackCopy.code pc)\n  | .field part pc=>SemiprimeD1StackMultiplierLink.instruction (fieldStack part) (Label.field part) (Field.code pc)\n  | .frame what pc=>SemiprimeD1StackMultiplierLink.instruction (frameStack what) (Label.frame what)\n      (SemiprimeD1StackFrame.code pc)\n  | .reverse what pc=>SemiprimeD1StackMultiplierLink.instruction (reverseStack what) (Label.reverse what)\n      (SemiprimeD1StackReverseWord.code pc)\n  | .increment pc=>SemiprimeD1StackMultiplierLink.instruction incrementStack Label.increment (Inc.code pc)\n/-- Actual source input has the complete record tape and acquired unary left count only. -/\ndef input (vertices count:List Bool) :Stack→List Bool\n  | .vertices=>vertices | .leftCount=>count | _=>[]\n/-- Literal source start with every dictionary, counter and work word initially empty. -/\ndef initial (vertices count:List Bool) :C.State Stack Label :=\n  ⟨some (.local .start),none,none,input vertices count,[]⟩\n/-- Fixed finite physical owner-index source; factor rows are still present on the reader at return. -/\ndef machine :Turing.FinTM2 :=SemiprimeD1StackCalls.machine Stack.vertices Stack.output (.local .start) program\n/-- Both actual preserving-copy instances have three distinct operands. -/\ntheorem copy_injective (what:Copy) :Function.Injective (copyStack what) :=by cases what <;> decide\n/-- Every actual field parser has four distinct physical operands. -/\ntheorem field_injective (part:Part) :Function.Injective (fieldStack part) :=by cases part <;> decide\n/-- Both preserving pair frames have three distinct physical operands. -/\ntheorem frame_injective (what:Frame) :Function.Injective (frameStack what) :=by cases what <;> decide\n/-- Each actual reversal has distinct source and target words. -/\ntheorem reverse_injective (what:Reverse) :Function.Injective (reverseStack what) :=by cases what <;> decide\n/-- Actual binary increment input/scratch/output roles cannot alias. -/\ntheorem increment_injective :Function.Injective incrementStack :=by decide\n/-- All seventeen data roles, including parsed table bytes and real binary-counter work, are counted. -/\ntheorem stack_card :Fintype.card Stack=17 :=by decide\n/-- Only finite read flags and actual fixed real-return labels inhabit runtime control. -/\ntheorem control_finite :Finite machine.σ :=SemiprimeD1StackCalls.control_finite _ _ _ _\n/-- Every data/return alphabet is fixed finite before the source inputs. -/\ntheorem alphabets_finite :∀k,Finite (machine.Γ k) :=SemiprimeD1StackCalls.all_alphabets_finite _ _ _ _\nend RiemannGaussian.SemiprimeD1StackNetworkOwnerIndex\n","RiemannGaussian.SemiprimeD1StackNetworkOwnerIndexSetup":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackNetworkOwnerIndexPrimitives\n/-! # Actual source copies and acquired-width binary owner-counter initialization\nThe unary left-count input is copied and physically traversed to allocate a\nzero binary word of width n+1. No native bit-length, counter or zero-word answer\nis an instruction or initially supplied payload.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackNetworkOwnerIndexSetup\nopen SemiprimeD1StackNetworkOwnerIndex SemiprimeD1StackNetworkOwnerIndexPrimitives\nopen SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => Label.local\n/-- Whole source boundary: all unlisted parser/frame/counter work words are physically empty. -/\ndef view (vertices count reader todo ports owner history:List Bool) :Stack→List Bool\n  | .vertices=>vertices | .leftCount=>count | .reader=>reader | .todo=>todo\n  | .ports=>ports | .owner=>owner | .history=>history | _=>[]\n/-- Literal input has no acquired counter, dictionary, work or factor-reader suffix yet. -/\ntheorem input_view (vertices count:List Bool) :input vertices count=view vertices count [] [] [] [] [] :=by\n  funext k;cases k <;> rfl\n/-- Updating the physical record reader leaves every original input/cache word unchanged. -/\ntheorem view_reader (vertices count reader todo ports owner history xs:List Bool) :\n    Function.update (view vertices count reader todo ports owner history) .reader xs=\n      view vertices count xs todo ports owner history :=by\n  funext k;cases k <;> simp [view,Function.update]\n/-- Updating the physical countdown leaves the acquired original count unchanged. -/\ntheorem view_todo (vertices count reader todo ports owner history xs:List Bool) :\n    Function.update (view vertices count reader todo ports owner history) .todo xs=\n      view vertices count reader xs ports owner history :=by\n  funext k;cases k <;> simp [view,Function.update]\n/-- Updating the current port-vector reader does not alter either original tape. -/\ntheorem view_ports (vertices count reader todo ports owner history xs:List Bool) :\n    Function.update (view vertices count reader todo ports owner history) .ports xs=\n      view vertices count reader todo xs owner history :=by\n  funext k;cases k <;> simp [view,Function.update]\n/-- Updating the physical binary owner word changes exactly its actual counter address. -/\ntheorem view_owner (vertices count reader todo ports owner history xs:List Bool) :\n    Function.update (view vertices count reader todo ports owner history) .owner xs=\n      view vertices count reader todo ports xs history :=by\n  funext k;cases k <;> simp [view,Function.update]\n/-- Updating actual reverse pair history retains the current owner and unconsumed vertex/port bytes. -/\ntheorem view_history (vertices count reader todo ports owner history xs:List Bool) :\n    Function.update (view vertices count reader todo ports owner history) .history xs=\n      view vertices count reader todo ports owner xs :=by\n  funext k;cases k <;> simp [view,Function.update]\n/-- The source physically copies the whole record tape exactly once. -/\ntheorem records_copy (vertices count:List Bool) :\n    Runs program (5*vertices.length+4) (ctl .start) (input vertices count) (ctl .zeroCount)\n      (view vertices count vertices [] [] [] []) :=by\n  rw [input_view]\n  have h:=copy_call .vertices .start .zeroCount rfl (view vertices count [] [] [] [] []) vertices [] rfl rfl rfl\n  change Runs program _ _ _ _ (Function.update (view vertices count [] [] [] [] []) .reader (vertices++[])) at h\n  simpa only [List.append_nil,view_reader] using h\n/-- Each count copy reads the retained original left-count word and charges every marker. -/\ntheorem count_copy (pc next:Control) (vertices count reader ports owner history:List Bool)\n    (hc:program (ctl pc)=.call (.copy .count 0) (ctl next)) :\n    Runs program (5*count.length+4) (ctl pc) (view vertices count reader [] ports owner history) (ctl next)\n      (view vertices count reader count ports owner history) :=by\n  have h:=copy_call .count pc next hc (view vertices count reader [] ports owner history) count [] rfl rfl rfl\n  change Runs program _ _ _ _ (Function.update (view vertices count reader [] ports owner history) .todo (count++[])) at h\n  simpa only [List.append_nil,view_todo] using h\n/-- One literal false bit seeds the original width before the actual marker loop. -/\ntheorem zero_seed (vertices count reader todo ports history:List Bool) :\n    Runs program 1 (ctl .zeroSeed) (view vertices count reader todo ports [] history) (ctl .zeroLoop)\n      (view vertices count reader todo ports [false] history) :=by\n  have h:=push_run .zeroSeed (ctl .zeroLoop) .owner false (view vertices count reader todo ports [] history) rfl\n  simpa only [view_owner,view] using h\n/-- Actual count-marker traversal allocates the zero's width; m is proof-side initial physical width. -/\ntheorem zero_loop (vertices count reader ports history:List Bool) (n m:Nat) :\n    Runs program (2*n+1) (ctl .zeroLoop)\n      (view vertices count reader (List.replicate n true) ports (List.replicate m false) history) (ctl .copyCount)\n      (view vertices count reader [] ports (List.replicate (n+m) false) history) :=by\n  induction n generalizing m with\n  | zero=>\n    have h:=pop_run .zeroLoop (ctl .copyCount) (ctl .abort) (ctl .zeroPush) .todo\n      (view vertices count reader [] ports (List.replicate m false) history) [] rfl rfl\n    rw [view_todo] at h\n    change Runs program 1 (ctl .zeroLoop) _ (ctl .copyCount)\n      (view vertices count reader [] ports (List.replicate m false) history) at h\n    simpa only [Nat.mul_zero,Nat.zero_add,List.replicate_zero] using h\n  | succ n ih=>\n    have h0:=pop_run .zeroLoop (ctl .copyCount) (ctl .abort) (ctl .zeroPush) .todo\n      (view vertices count reader (List.replicate (n+1) true) ports (List.replicate m false) history)\n      (true::List.replicate n true) rfl rfl\n    change Runs program 1 (ctl .zeroLoop) _ (ctl .zeroPush)\n      (Function.update (view vertices count reader (List.replicate (n+1) true) ports\n        (List.replicate m false) history) .todo (List.replicate n true)) at h0\n    rw [view_todo] at h0\n    have h1:=push_run .zeroPush (ctl .zeroLoop) .owner false\n      (view vertices count reader (List.replicate n true) ports (List.replicate m false) history) rfl\n    rw [view_owner] at h1\n    change Runs program 1 _ _ _\n      (view vertices count reader (List.replicate n true) ports (List.replicate (m+1) false) history) at h1\n    have h2:=ih (m+1)\n    have h:=join (join h0 h1) h2\n    have hc:(1+1)+(2*n+1)=2*(n+1)+1:=by omega\n    have hw:n+(m+1)=(n+1)+m:=by omega\n    simpa only [hc,hw] using h\n/-- Whole original physical source setup: paid record/count copies and physically allocated binary zero. -/\ntheorem setup_trace (vertices:List Bool) (n:Nat) :\n    Runs program (5*vertices.length+12*n+14) (ctl .start)\n      (initial vertices (List.replicate n true)).data (ctl .owners)\n      (view vertices (List.replicate n true) vertices (List.replicate n true) [] (List.replicate (n+1) false) []) :=by\n  have h0:=records_copy vertices (List.replicate n true)\n  have h1:=count_copy .zeroCount .zeroSeed vertices (List.replicate n true) vertices [] [] [] rfl\n  have h2:=zero_seed vertices (List.replicate n true) vertices (List.replicate n true) [] []\n  have h3:=zero_loop vertices (List.replicate n true) vertices [] [] n 1\n  have h4:=count_copy .copyCount .owners vertices (List.replicate n true) vertices [] (List.replicate (n+1) false) [] rfl\n  have h:=join (join (join (join h0 h1) h2) h3) h4\n  have hc:((((5*vertices.length+4)+(5*(List.replicate n true).length+4))+1)+(2*n+1))+\n      (5*(List.replicate n true).length+4)=5*vertices.length+12*n+14 :=by\n    simp only [List.length_replicate]\n    omega\n  simpa only [hc,initial] using h\nend RiemannGaussian.SemiprimeD1StackNetworkOwnerIndexSetup\n","RiemannGaussian.SemiprimeD1StackNormalizedInverseOperationInput":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverseCalls\n/-! # Four real operand copies before every inverse rational operation\nCopies finish before any aliased destination register is erased. The fixed\noperation site chooses only actual source/destination addresses, never values.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackNormalizedInverseOperationInput\nopen SemiprimeD1StackNormalizedInverse SemiprimeD1StackNormalizedInverseView SemiprimeD1StackNormalizedInverseCalls\nopen SemiprimeD1StackProcedureTrace\n/-- Literal four-front-field update, corresponding exactly to the four executed preserving copies. -/\ndef filled (width ls ld rs rd:List Bool) :R.Stack→List Bool:=\n  Function.update (Function.update (Function.update (Function.update (emptyRational width)\n    (SemiprimeD1StackRationalOperation.aux .leftSigned) ls) (SemiprimeD1StackRationalOperation.aux .leftDen) ld)\n    (SemiprimeD1StackRationalOperation.aux .rightSigned) rs) (SemiprimeD1StackRationalOperation.aux .rightDen) rd\n/-- The actual four writes form EXACTLY the sealed R36 source's honest five-tape input bank. -/\ntheorem filled_input (width ls ld rs rd:List Bool) :\n    filled width ls ld rs rd=SemiprimeD1StackRationalOperation.input ls ld rs rd width:=by\n  funext k\n  rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k\n      · rcases k with k|k <;> cases k <;> rfl\n      · cases k <;> rfl\n    · cases k <;> rfl\n  · rcases k with k|k\n    · rcases k with k|k\n      · fin_cases k <;> rfl\n      · cases k <;> rfl\n    · cases k <;> rfl\n/-- Four actual preserving copies include all input bytes, restoration loops and real caller returns. -/\ndef inputsTime (ls ld rs rd:List Bool) :Nat:=5*(ls.length+ld.length+rs.length+rd.length)+16\n/-- Actual cached operands initialize R36 before an aliased output register may be changed. -/\ntheorem inputs_run (site:Site) (w:Words) (width ls ld rs rd:List Bool)\n    (hr:w.rational=emptyRational width) (hs:w.auxiliary .copyScratch=[])\n    (hls:w.registers (operand site false,false)=ls) (hld:w.registers (operand site false,true)=ld)\n    (hrs:w.registers (operand site true,false)=rs) (hrd:w.registers (operand site true,true)=rd) :\n    Runs program (inputsTime ls ld rs rd) (.operation site (.copyInput false false)) (store w)\n      (.operation site .run) (store {w with rational:=SemiprimeD1StackRationalOperation.input ls ld rs rd width}):=by\n  let rls:=SemiprimeD1StackRationalOperation.aux .leftSigned\n  let rld:=SemiprimeD1StackRationalOperation.aux .leftDen\n  let rrs:=SemiprimeD1StackRationalOperation.aux .rightSigned\n  let rrd:=SemiprimeD1StackRationalOperation.aux .rightDen\n  let w1:Words:={w with rational:=Function.update w.rational rls ls}\n  let w2:Words:={w1 with rational:=Function.update w1.rational rld ld}\n  let w3:Words:={w2 with rational:=Function.update w2.rational rrs rs}\n  let w4:Words:={w3 with rational:=Function.update w3.rational rrd rd}\n  have hz0:store w (copyTarget (.input site false false))=[]:=by\n    change w.rational rls=[]\n    rw [hr]\n    rfl\n  have h0:=PTrace.copy_call (.input site false false) (.operation site (.copyInput false false))\n    (.operation site (.copyInput false true)) rfl (store w) ls [] hls hz0 hs\n  change Runs _ _ _ _ _ (Function.update (store w) (rational rls) (ls++[])) at h0\n  rw [List.append_nil,update_rational] at h0\n  have hz1:store w1 (copyTarget (.input site false true))=[]:=by\n    change Function.update w.rational rls ls rld=[]\n    rw [hr]\n    rfl\n  have h1:=PTrace.copy_call (.input site false true) (.operation site (.copyInput false true))\n    (.operation site (.copyInput true false)) rfl (store w1) ld [] hld hz1 hs\n  change Runs _ _ _ _ _ (Function.update (store w1) (rational rld) (ld++[])) at h1\n  rw [List.append_nil,update_rational] at h1\n  have hz2:store w2 (copyTarget (.input site true false))=[]:=by\n    change Function.update (Function.update w.rational rls ls) rld ld rrs=[]\n    rw [hr]\n    rfl\n  have h2:=PTrace.copy_call (.input site true false) (.operation site (.copyInput true false))\n    (.operation site (.copyInput true true)) rfl (store w2) rs [] hrs hz2 hs\n  change Runs _ _ _ _ _ (Function.update (store w2) (rational rrs) (rs++[])) at h2\n  rw [List.append_nil,update_rational] at h2\n  have hz3:store w3 (copyTarget (.input site true true))=[]:=by\n    change Function.update (Function.update (Function.update w.rational rls ls) rld ld) rrs rs rrd=[]\n    rw [hr]\n    rfl\n  have h3:=PTrace.copy_call (.input site true true) (.operation site (.copyInput true true))\n    (.operation site .run) rfl (store w3) rd [] hrd hz3 hs\n  change Runs _ _ _ _ _ (Function.update (store w3) (rational rrd) (rd++[])) at h3\n  rw [List.append_nil,update_rational] at h3\n  have hw:w4={w with rational:=SemiprimeD1StackRationalOperation.input ls ld rs rd width}:=by\n    change {w with rational:=Function.update (Function.update (Function.update (Function.update w.rational rls ls) rld ld) rrs rs) rrd rd}=_\n    rw [hr]\n    change {w with rational:=filled width ls ld rs rd}=_\n    rw [filled_input]\n  have h:=PTrace.join (PTrace.join (PTrace.join h0 h1) h2) h3\n  change Runs program _ _ _ _ (store w4) at h\n  rw [hw] at h\n  convert h using 1\n  unfold inputsTime\n  omega\nend RiemannGaussian.SemiprimeD1StackNormalizedInverseOperationInput\n","RiemannGaussian.SemiprimeD1StackNormalizedInverseReadBuffers":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverseView\n/-! # Actual array-reader buffers and disjoint coefficient/cache writes -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackNormalizedInverseReadBuffers\nopen SemiprimeD1StackNormalizedInverse SemiprimeD1StackNormalizedInverseView\n/-- Actual bounded unary metadata, never a decoded runtime Nat. -/\ndef unary (n : ℕ) : List Bool := List.replicate n true\n/-- Only the physical array reader and query-marker copy are changed. -/\ndef buffers (w : Words) (reader todo : List Bool) : Words :=\n  {w with auxiliary:=fun k=>if k=.reader then reader else if k=.readTodo then todo else w.auxiliary k}\n/-- Every actual reader pop changes only that physical word. -/\ntheorem update_reader (w : Words) (reader todo xs : List Bool) :\n    Function.update (store (buffers w reader todo)) (aux .reader) xs=store (buffers w xs todo) := by\n  rw [update_aux]\n  congr 1\n  congr 1\n  funext k;cases k <;> simp [buffers]\n/-- Every actual index-marker pop changes only that physical word. -/\ntheorem update_todo (w : Words) (reader todo xs : List Bool) :\n    Function.update (store (buffers w reader todo)) (aux .readTodo) xs=store (buffers w reader xs) := by\n  rw [update_aux]\n  congr 1\n  congr 1\n  funext k;cases k <;> simp [buffers]\n/-- Actual cache acquisition commutes with reader/counter writes at disjoint physical addresses. -/\ntheorem put_buffers (w : Words) (r : Reg) (word : SemiprimeRationalBits.RationalWord) (reader todo : List Bool) :\n    putReg (buffers w reader todo) r word=buffers (putReg w r word) reader todo := rfl\n/-- Actual cache clearing commutes with reader/counter writes at disjoint physical addresses. -/\ntheorem empty_buffers (w : Words) (r : Reg) (reader todo : List Bool) :\n    emptyReg (buffers w reader todo) r=buffers (emptyReg w r) reader todo := rfl\n/-- A completed reader restores exactly its actual two originally empty helper words. -/\ntheorem buffers_self (w : Words) : buffers w (w.auxiliary .reader) (w.auxiliary .readTodo)=w := by\n  unfold buffers\n  congr 1\n  funext k;cases k <;> rfl\n/-- Actual two-field drains restore an originally empty cache, regardless of padding/validity. -/\ntheorem erase_put (w : Words) (r : Reg) (word : SemiprimeRationalBits.RationalWord)\n    (hn : w.registers (r,false)=[]) (hd : w.registers (r,true)=[]) : emptyReg (putReg w r word) r=w := by\n  dsimp only [emptyReg,putReg]\n  congr 1\n  funext k\n  rcases k with ⟨other,den⟩\n  by_cases he:other=r\n  · subst other;cases den <;> simp [hn,hd]\n  · cases den <;> simp [he]\n/-- A real read completion writes its actual TRUE marker for the real caller to pop. -/\ndef success (w : Words) : Words := {w with auxiliary:=Function.update w.auxiliary .valid [true]}\n/-- An actual success-marker push leaves every other word unchanged. -/\ntheorem update_success (w : Words) (hv : w.auxiliary .valid=[]) :\n    Function.update (store w) (aux .valid) (true::w.auxiliary .valid)=store (success w) := by\n  rw [hv,update_aux]\n  rfl\n/-- Original source/cache fields are retained by actual reader-buffer changes. -/\ntheorem buffers_other (w : Words) (reader todo : List Bool) (k : Aux) (hr : k≠.reader) (ht : k≠.readTodo) :\n    (buffers w reader todo).auxiliary k=w.auxiliary k := by simp only [buffers,hr,ht,ite_false]\nend RiemannGaussian.SemiprimeD1StackNormalizedInverseReadBuffers\n","RiemannGaussian.SemiprimeD1StackNormalizedInverseView":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverse\n/-! # Whole physical normalized-inverse bank views and exact rational-cache bytes\nAll getters below are proof specifications of physical words, never instructions\nor suppliers in the finite program. Actual fields are acquired by real parsers.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackNormalizedInverseView\nopen SemiprimeD1StackNormalizedInverse\n/-- Full58-word view; no caller source, output, helper or shadow is omitted. -/\nstructure Words where\n  /-- All36 actual normalized-operation words. -/\n  rational : R.Stack→List Bool:=fun _=>[]\n  /-- All eight actual signed/denominator cache fields. -/\n  registers : Reg×Bool→List Bool:=fun _=>[]\n  /-- Every one of14 original/controller/prefix/output words. -/\n  auxiliary : Aux→List Bool:=fun _=>[]\n/-- Exact complete physical source bank. -/\ndef store (w : Words) : Stack→List Bool := bank w.rational w.registers w.auxiliary\n/-- A clean R36 bank holds only the actually retained W template. -/\ndef emptyRational (width : List Bool) : R.Stack→List Bool := fun k=>if k=R.aux .template then width else []\n/-- Honest three-input prepared source state, with no numeric size or coefficient answers. -/\ndef originals (array q width : List Bool) : Words := {rational:=emptyRational width,auxiliary:=originalAux array q}\n/-- Proof-side view of an actual signed cache and its actual binary denominator. -/\ndef getReg (w : Words) (r : Reg) : SemiprimeRationalBits.RationalWord :=\n  ⟨⟨(w.registers (r,false)).head?.getD false,(w.registers (r,false)).tail⟩,w.registers (r,true)⟩\n/-- Exact two-field cache write corresponding to actual signed/denominator bytes. -/\ndef putReg (w : Words) (r : Reg) (word : SemiprimeRationalBits.RationalWord) : Words :=\n  {w with registers:=Function.update (Function.update w.registers (r,false) (signed word)) (r,true) word.denominator}\n/-- Exact actual cache drain. -/\ndef emptyReg (w : Words) (r : Reg) : Words :=\n  {w with registers:=Function.update (Function.update w.registers (r,false) []) (r,true) []}\n/-- One actual R36 physical update leaves all coefficient and controller words unchanged. -/\ntheorem update_rational (w : Words) (k : R.Stack) (xs : List Bool) :\n    Function.update (store w) (rational k) xs=store {w with rational:=Function.update w.rational k xs} :=\n  Sum.update_elim_inl\n/-- One actual coefficient-field update leaves all other physical banks unchanged. -/\ntheorem update_register (w : Words) (r : Reg) (den : Bool) (xs : List Bool) :\n    Function.update (store w) (reg r den) xs=store {w with registers:=Function.update w.registers (r,den) xs} := by\n  dsimp only [store,bank,reg]\n  rw [Sum.update_elim_inr,Sum.update_elim_inl]\n/-- One actual controller update retains every source and coefficient word outside that role. -/\ntheorem update_aux (w : Words) (k : Aux) (xs : List Bool) :\n    Function.update (store w) (aux k) xs=store {w with auxiliary:=Function.update w.auxiliary k xs} := by\n  dsimp only [store,bank,aux]\n  rw [Sum.update_elim_inr,Sum.update_elim_inr]\n/-- Actual acquired cached words always retain their sign prefix, including W=0. -/\ntheorem putReg_fields (w : Words) (r : Reg) (word : SemiprimeRationalBits.RationalWord) :\n    (putReg w r word).registers (r,false)=signed word ∧ (putReg w r word).registers (r,true)=word.denominator := by\n  simp only [putReg,Function.update_apply,Prod.mk.injEq,eq_self,true_and,Bool.false_eq_true,\n    Bool.true_eq_false,ite_false,ite_true]\n/-- A physically acquired word has exactly the same decoded signed/cache fields. -/\ntheorem getReg_put (w : Words) (r : Reg) (word : SemiprimeRationalBits.RationalWord) : getReg (putReg w r word) r=word := by\n  rw [getReg,(putReg_fields w r word).1,(putReg_fields w r word).2]\n  cases word\n  rfl\n/-- Actual cache clearing empties BOTH data fields. -/\ntheorem emptyReg_fields (w : Words) (r : Reg) :\n    (emptyReg w r).registers (r,false)=[] ∧ (emptyReg w r).registers (r,true)=[] := by\n  simp only [emptyReg,Function.update_apply,Prod.mk.injEq,eq_self,true_and,Bool.false_eq_true,\n    Bool.true_eq_false,ite_false,ite_true]\n/-- Other signed/denominator caches are retained byte for byte by this actual cache write. -/\ntheorem putReg_other (w : Words) (r other : Reg) (word : SemiprimeRationalBits.RationalWord)\n    (den : Bool) (h : other≠r) : (putReg w r word).registers (other,den)=w.registers (other,den) := by\n  have h0 : (other,den)≠(r,true) := by intro he;exact h (congrArg Prod.fst he)\n  have h1 : (other,den)≠(r,false) := by intro he;exact h (congrArg Prod.fst he)\n  dsimp only [putReg]\n  rw [Function.update_of_ne h0,Function.update_of_ne h1]\n/-- A nonempty actual signed field equals its full sign-plus-magnitude word specification. -/\ntheorem signed_getReg (w : Words) (r : Reg) (h : w.registers (r,false)≠[]) :\n    w.registers (r,false)=signed (getReg w r) := by\n  cases he:w.registers (r,false) with\n  | nil=>exact (h he).elim\n  | cons b xs=>simp only [getReg,signed,he,List.head?_cons,Option.getD_some,List.tail_cons]\n/-- Physical original/ready source views agree on every one of58 tapes. -/\ntheorem initial_store (array q width : List Bool) : (initial array q width).data=store (originals array q width) := rfl\n/-- Literal framed rational-row width includes both fields, both delimiters and the TRUE tag. -/\ntheorem row_length (word : SemiprimeRationalBits.RationalWord) (tail : List Bool) :\n    (row word tail).length=2*(signed word).length+2*word.denominator.length+tail.length+3 := by\n  simp only [row,List.length_cons,SemiprimeSourceHistogramKeyBits.frame_length]\n  omega\n/-- Every physical typed array has its ONE final FALSE cell, even for zero coefficients. -/\ntheorem tape_length_pos (words : List SemiprimeRationalBits.RationalWord) : 0<(tape words).length := by\n  induction words with\n  | nil=>decide\n  | cons word words ih=>\n    change 0<(row word (tape words)).length\n    rw [row_length]\n    omega\n/-- Proof-side total mass counts all58 physical roles. -/\ndef mass (w : Words) : ℕ := ∑k : Stack,(store w k).length\nend RiemannGaussian.SemiprimeD1StackNormalizedInverseView\n","RiemannGaussian.SemiprimeD1StackOwnerCatalogueLoop":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOwnerCatalogueOriginalRow\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 131072\nnamespace RiemannGaussian.SemiprimeD1StackOwnerCatalogueLoop\nopen SemiprimeD1StackOwnerCatalogue SemiprimeD1StackOwnerCatalogueSource\nopen SemiprimeD1StackOwnerCatalogueParse SemiprimeD1StackOwnerCatalogueRow\nopen SemiprimeD1StackOwnerCatalogueOriginalRow\nopen SemiprimeD1StackPortOwnerRecipeSpec (original)\nopen SemiprimeD1StackPortOwnerRecipeClassify (originalTag)\nopen SemiprimeD1StackProcedureTrace (Runs runs_trans)\nopen SemiprimeSourceHistogramKeyBits (frame)\n/-- Proof specification of the actual E records and the first E physically acquired M-bank words. -/\nabbrev Pair (r t digits:Nat) := SemiprimeMacroGraph.Edge r t digits×List Bool\n/-- Exact actual six-field edge reader; each record has no extra vector marker. -/\ndef edgeTapeOf {r t digits:Nat} (pairs:List (Pair r t digits)) : List Bool :=\n  pairs.foldr (fun p rest=>SemiprimeD1EdgeCatalogueEncoding.edge p.1 rest) []\n/-- Exact actual acquired ID-vector prefix followed by the untouched M-E suffix. -/\ndef idTapeOf {r t digits:Nat} (pairs:List (Pair r t digits)) (tail:List Bool) : List Bool :=\n  pairs.foldr (fun p rest=>true::frame p.2 rest) tail\n/-- The actual emitted row bytes, preserving physical edge order and both endpoint halves. -/\ndef bytes {r t digits:Nat} (pairs:List (Pair r t digits)) : List Bool :=\n  pairs.flatMap (fun p=>emitted (fields p.1 p.2) (original p.1) (originalTag p.1))\n/-- Sum of the SAME physical row-iteration budgets. -/\ndef budget {r t digits:Nat} (pairs:List (Pair r t digits)) : Nat :=\n  (pairs.map (fun p=>SemiprimeD1StackOwnerCatalogueRow.budget (fields p.1 p.2)\n    (original p.1) (originalTag p.1))).sum\n/-- Entire real E-wire loop, consuming exactly one owner-ID word per actual edge.\nThe unused acquired ID suffix remains present; no identification of E and M is used. -/\ntheorem loop_run {r t digits:Nat} (hd:0<digits) (s:S.Stack→List Bool) (hm:Metadata s r t digits)\n    (pairs:List (Pair r t digits)) (ids collector:List Bool) :\n    ∃time≤budget pairs,Runs program time (.local .parse)\n      (data s (fun _=>[]) (fun _=>[]) (rowAux (edgeTapeOf pairs) (idTapeOf pairs ids) collector))\n      (.local .parse) (data s (fun _=>[]) (fun _=>[]) (rowAux [] ids ((bytes pairs).reverse++collector))) := by\n  induction pairs generalizing collector with\n  | nil=>\n    refine ⟨0,by simp [budget],?_⟩\n    exact SemiprimeD1StackProcedureTrace.runs_refl program _ _\n  | cons p pairs ih=>\n    obtain ⟨a,ha,har⟩:=original_row_run hd s hm p.1 p.2 (edgeTapeOf pairs) (idTapeOf pairs ids) collector\n    obtain ⟨b,hb,hbr⟩:=ih ((emitted (fields p.1 p.2) (original p.1) (originalTag p.1)).reverse++collector)\n    have h:=runs_trans program _ _ _ _ _ _ _ _ har hbr\n    refine ⟨a+b,?_,?_⟩\n    · simp only [budget,List.map_cons,List.sum_cons] at *\n      omega\n    · simpa only [edgeTapeOf,idTapeOf,List.foldr_cons,bytes,List.flatMap_cons,List.reverse_append,List.append_assoc] using h\nend RiemannGaussian.SemiprimeD1StackOwnerCatalogueLoop\n","RiemannGaussian.SemiprimeD1StackOwnerEqualityKey":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackProcedureFragments\nimport RiemannGaussian.SemiprimeD1PortOwnerEndpointEncoding\n/-! # Physical equality-endpoint key from the acquired original edge record\nThis internal stage physically prepends the sentinel to its output and calls\npreserving Copy on the actual six-field record. It has no endpoint/key answer.\nThe original-N outer routing loop remains a separate integration obligation.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nnamespace RiemannGaussian.SemiprimeD1StackOwnerEqualityKey\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State run step execute)\nend C\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (instruction)\nend Link\nopen SemiprimeD1StackProcedureFragments (Runs included_call one_base)\n/-- Input, destination and physical scratch are three fixed Boolean roles. -/\nabbrev Stack := Fin 3\n/-- Static local control plus the actual immutable Copy procedure. -/\nabbrev Label := Fin 3 ⊕ Fin 9\n/-- Literal sentinel push, real Copy call, final halt. -/\ndef program : Label→C.Instruction Stack Label\n  | .inr pc => Link.instruction id Sum.inr (SemiprimeD1StackCopy.code pc)\n  | .inl pc => if pc=0 then .base (.push 1 true (.inl 1))\n      else if pc=1 then .call (.inr 0) (.inl 2) else .base .halt\n/-- Actual acquired record and fresh work; not a source descriptor constructor. -/\ndef initial (record:List Bool) : C.State Stack Label :=\n  ⟨some (.inl 0),none,none,SemiprimeD1StackCopy.payload record [] [],[]⟩\n/-- Original record retained and exact new compact-key bytes returned. -/\ndef done (record:List Bool) : C.State Stack Label :=\n  ⟨none,none,none,SemiprimeD1StackCopy.payload record (record++[true]) [],[]⟩\n/-- The sentinel cell is actually pushed, not preloaded as an advised key. -/\ntheorem sentinel (record:List Bool) : Runs program 1 (.inl 0)\n    (SemiprimeD1StackCopy.payload record [] []) (.inl 1)\n    (SemiprimeD1StackCopy.payload record [true] []) := by\n  apply one_base program (.inl 0) (.inl 1) (.push 1 true (.inl 1)) _ _ rfl rfl\n  funext k;fin_cases k <;> rfl\n/-- Real nested preserving Copy and all three original/scratch data roles. -/\ntheorem copy_call (record:List Bool) : Runs program (5*record.length+4) (.inl 1)\n    (SemiprimeD1StackCopy.payload record [true] []) (.inl 2)\n    (SemiprimeD1StackCopy.payload record (record++[true]) []) := by\n  apply included_call program id Sum.inr Function.injective_id SemiprimeD1StackCopy.code 0\n    (fun _=>rfl) (.inl 1) (.inl 2) rfl (5*record.length+3)\n    (SemiprimeD1StackCopy.state 0 none record [true] [])\n    (SemiprimeD1StackCopy.done record (record++[true]))\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackCopy.copy_words record [true] none\n  · exact ⟨fun _=>rfl,fun _ _=>rfl⟩\n  · exact ⟨fun _=>rfl,fun k hk=>False.elim (hk k rfl)⟩\n/-- Actual complete fixed-program trace, preserving the original acquired record. -/\ntheorem source_run (record:List Bool) :\n    C.run program (5*record.length+6) (initial record)=some (done record) := by\n  have h:Runs program (1+(5*record.length+4)) (.inl 0)\n      (SemiprimeD1StackCopy.payload record [] []) (.inl 2)\n      (SemiprimeD1StackCopy.payload record (record++[true]) []) :=\n    (sentinel record).trans (copy_call record)\n  obtain ⟨finish,hr,hout⟩:=h [] (initial record) ⟨rfl,rfl,rfl⟩\n  have he:5*record.length+6=(1+(5*record.length+4))+1:=by omega\n  rw [he,SemiprimeD1StackReturnLink.run_add,hr,Option.bind_some]\n  rcases hout with ⟨hpc,hdata,hframes⟩\n  change C.step program finish=some (done record)\n  simp [C.step,SemiprimeD1StackCalls.step,hpc,program,C.execute,\n    SemiprimeD1StackCalls.execute,hdata,hframes,done]\n/-- A single fixed finite machine, with all three alphabets Boolean. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine 0 1 (.inl 0) program\n/-- Every stack alphabet is finite, including scratch and output. -/\ntheorem all_alphabets_finite : ∀ k,Finite (machine.Γ k) :=\n  SemiprimeD1StackCalls.all_alphabets_finite 0 1 (.inl 0) program\n/-- Framing appends a literal tail; this proof does not execute a key decoder. -/\ntheorem frame_append (xs ys zs:List Bool) :\n    SemiprimeSourceHistogramKeyBits.frame xs ys++zs=\n      SemiprimeSourceHistogramKeyBits.frame xs (ys++zs) := by\n  induction xs with\n  | nil => rfl\n  | cons b bs ih => simp only [SemiprimeSourceHistogramKeyBits.frame,List.cons_append,ih]\n/-- The physical sentinel-copy output on an actual original edge is exactly\nits original equality-endpoint key. -/\ntheorem original_key {r t digits:ℕ} (hd:0<digits) (hc:digits≤r*t)\n    (e:SemiprimeMacroGraph.Edge r t digits) :\n    (done (SemiprimeD1EdgeCatalogueEncoding.edge e [])).data 1=\n      SemiprimeD1PortOwnerKeys.key (SemiprimeD1PortOwnerKeys.endpoint hd hc e true) := by\n  rw [SemiprimeD1PortOwnerEndpointEncoding.equality_key]\n  change SemiprimeD1EdgeCatalogueEncoding.edge e []++[true]=_\n  simp only [SemiprimeD1EdgeCatalogueEncoding.edge,SemiprimeD1EdgeCatalogueEncoding.half,\n    SemiprimeD1EdgeCatalogueEncoding.record,frame_append,List.nil_append]\nend RiemannGaussian.SemiprimeD1StackOwnerEqualityKey\n","RiemannGaussian.SemiprimeD1StackOwnerFibre":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOwnerLookupOriginal\nimport RiemannGaussian.SemiprimeD1StackFrame\nimport RiemannGaussian.SemiprimeD1StackReverseWord\n/-! # Physical factor-major owner-fibre filtering\nThe input is an actually acquired stream of computed owner-ID/scope-ID pairs.\nEvery numeric equality, payload parse, selected framing and output reversal is\nexecuted by the fixed finite source. Scope IDs retain their original order.\nAcquiring this routed stream from original N remains explicit caller work.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeD1StackOwnerFibre\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State execute step run)\nend C\nnamespace E\nexport SemiprimeD1StackWordEqual (Label code)\nexport SemiprimeD1StackAdder (Stack store)\nend E\nnamespace F\nexport SemiprimeD1TensorTapeFieldBytecode (Stack Label code active)\nend F\n/-- Ten fixed caller roles in addition to all four actual equality roles. -/\ninductive Aux where | query | reader | fieldScratch | valid | copyScratch | payload | output | frameBuffer | frameScratch | reversed\n  deriving DecidableEq\ninstance : Fintype Aux := Fintype.ofList [.query,.reader,.fieldScratch,.valid,.copyScratch,.payload,.output,.frameBuffer,.frameScratch,.reversed]\n  (by intro k;cases k <;> simp)\n/-- All fourteen Boolean data roles, independent of original input. -/\nabbrev Stack := E.Stack⊕Aux\n/-- Only actual one-bit comparison outcomes enter control. -/\ninductive Label where\n  | loop | parseKey | parsedKey | copyKey | compare | matched\n  | parseValue (same:Bool) | parsedValue (same:Bool) | clear | emitTag | frame | reverse\n  | finishTag | finishReverse | done | abort\n  | field (part:Option Bool) (pc:F.Label) | copy (pc:Fin 9) | equal (pc:E.Label)\n  | frameCode (pc:Fin 11) | reverseCode (finish:Bool) (pc:Fin 4)\n  deriving Fintype\n/-- None parses an owner key; some parses the actual scope-ID payload cache. -/\ndef fieldOutput : Option Bool→Stack\n  | none=>.inl .left\n  | some _=>.inr .payload\n/-- Actual field parser inclusion; the computed equality selects later emission. -/\ndef fieldStack (part:Option Bool) : F.Stack→Stack\n  | .inl .input=>.inr .reader\n  | .inl .scratch=>.inr .fieldScratch\n  | .inl .output=>fieldOutput part\n  | .inr _=>.inr .valid\n/-- Actual query-preserving copy operands. -/\ndef copyStack (k:Fin 3) : Stack :=\n  if k=0 then .inr .query else if k=1 then .inl .right else .inr .copyScratch\n/-- Actual preserving payload Frame operands. -/\ndef frameStack (k:Fin 3) : Stack :=\n  if k=0 then .inr .payload else if k=1 then .inr .frameBuffer else .inr .frameScratch\n/-- Each row reverses its new frame; finish reverses the entire collector. -/\ndef reverseStack (finish:Bool) (k:Fin 2) : Stack :=\n  if k=0 then (if finish then .inr .reversed else .inr .frameBuffer)\n  else if finish then .inr .output else .inr .reversed\n/-- Every actual field read and failed-row payload erase executes this table. -/\ndef program : Label→C.Instruction Stack Label\n  | .loop=>.base (.pop (.inr .reader) .finishTag .finishTag .parseKey)\n  | .parseKey=>.call (.field none (F.active .tagPop (none,false))) .parsedKey\n  | .parsedKey=>.base (.pop (.inr .valid) .abort .abort .copyKey)\n  | .copyKey=>.call (.copy 0) .compare\n  | .compare=>.call (.equal .loop) .matched\n  | .matched=>.base (.pop (.inl .output) .abort (.parseValue false) (.parseValue true))\n  | .parseValue same=>.call (.field (some same) (F.active .tagPop (none,false))) (.parsedValue same)\n  | .parsedValue same=>.base (.pop (.inr .valid) .abort .abort (if same then .emitTag else .clear))\n  | .clear=>.base (.pop (.inr .payload) .loop .clear .clear)\n  | .emitTag=>.base (.push (.inr .reversed) true .frame)\n  | .frame=>.call (.frameCode 0) .reverse\n  | .reverse=>.call (.reverseCode false 0) .clear\n  | .finishTag=>.base (.push (.inr .reversed) false .finishReverse)\n  | .finishReverse=>.call (.reverseCode true 0) .done\n  | .done | .abort=>.base .halt\n  | .frameCode pc=>SemiprimeD1StackMultiplierLink.instruction frameStack Label.frameCode (SemiprimeD1StackFrame.code pc)\n  | .reverseCode finish pc=>SemiprimeD1StackMultiplierLink.instruction (reverseStack finish) (Label.reverseCode finish) (SemiprimeD1StackReverseWord.code pc)\n  | .field part pc=>SemiprimeD1StackMultiplierLink.instruction (fieldStack part) (Label.field part) (F.code pc)\n  | .copy pc=>SemiprimeD1StackMultiplierLink.instruction copyStack Label.copy (SemiprimeD1StackCopy.code pc)\n  | .equal pc=>SemiprimeD1StackMultiplierLink.instruction Sum.inl Label.equal (E.code pc)\n/-- Mathematical view of the physical store, not an instruction-time evaluator. -/\ndef data (query reader left right comparison valid payload raw buffer output:List Bool) : Stack→List Bool\n  | .inl k=>E.store left right [] comparison k\n  | .inr .query=>query\n  | .inr .reader=>reader\n  | .inr .valid=>valid\n  | .inr .payload=>payload\n  | .inr .reversed=>raw\n  | .inr .frameBuffer=>buffer\n  | .inr .output=>output\n  | .inr .fieldScratch | .inr .copyScratch | .inr .frameScratch=>[]\nopen SemiprimeSourceHistogramKeyBits (frame)\n/-- Same two-field physical format as the owner lookup: owner-ID then scope-ID. -/\nabbrev records := SemiprimeD1StackOwnerLookup.records\n/-- Proof-side order-preserving selected scope-ID list. -/\ndef values (query:List Bool) : List (List Bool×List Bool)→List (List Bool)\n  | []=>[]\n  | (owner,scope)::rows=>if SemiprimeBitArithmetic.bitValue owner=SemiprimeBitArithmetic.bitValue query\n      then scope::values query rows else values query rows\n/-- Literal emitted row bytes, before the final false vector delimiter. -/\ndef selected (query:List Bool) (rows:List (List Bool×List Bool)) : List Bool :=\n  (values query rows).foldr (fun word tail=>true::frame word tail) []\n/-- Only the physically acquired query and catalogue are loaded initially. -/\ndef initial (query reader:List Bool) : C.State Stack Label :=\n  ⟨some .loop,none,none,data query reader [] [] [] [] [] [] [] [],[]⟩\n/-- Exact halt state with the original ordered scope-ID fibre and suffix. -/\ndef done (query:List Bool) (rows:List (List Bool×List Bool)) (tail:List Bool) : C.State Stack Label :=\n  ⟨none,none,none,data query tail [] [] [] [] [] [] [] (SemiprimeD1TensorTapeCodec.vectorBits (values query rows)),[]⟩\n/-- One fixed finite TM2 for actual scope-ID fibre acquisition. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine (.inr .reader) (.inr .output) .loop program\ntheorem stack_card : Fintype.card Stack=14 := by decide\ntheorem field_injective (part:Option Bool) : Function.Injective (fieldStack part) := by\n  cases part with\n  | none=>decide\n  | some b=>cases b <;> decide\ntheorem copy_injective : Function.Injective copyStack := by decide\n/-- All actual frame operands are distinct. -/\ntheorem frame_injective : Function.Injective frameStack := by decide\n/-- Both real reversals have distinct source and destination. -/\ntheorem reverse_injective (finish:Bool) : Function.Injective (reverseStack finish) := by cases finish <;> decide\ntheorem all_alphabets_finite : ∀k,Finite (machine.Γ k) :=\n  SemiprimeD1StackCalls.all_alphabets_finite (.inr .reader) (.inr .output) Label.loop program\ntheorem control_finite : Finite machine.σ :=\n  SemiprimeD1StackCalls.control_finite (.inr .reader) (.inr .output) Label.loop program\nend RiemannGaussian.SemiprimeD1StackOwnerFibre\n","RiemannGaussian.SemiprimeD1StackOwnerRecords":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOwnerFibreCatalogueResources\nimport RiemannGaussian.SemiprimeD1StackOwnerRecordBounds\n/-! # Actual original-N all-owner record source\nThe retained N-only catalogue is physically copied and parsed. Every owner\ngets a fresh physical copy of the caller prefix, the real table/ordinal/logger\nsource runs, and retained key/tail/bank words are physically drained. Empty\nprefix initialization is a literal push. No owner/key/fibre/table is supplied.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackOwnerRecords\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State run)\nend C\nnamespace S\nexport SemiprimeD1StackOwnerFibreCatalogue (Stack Label program originalInput input)\nend S\nnamespace R\nexport SemiprimeD1StackOwnerRecord (Stack Label program original history output initial done)\nend R\nnamespace F\nexport SemiprimeD1TensorTapeFieldBytecode (Stack Label code active)\nend F\nnamespace L\nexport SemiprimeD1StackVertexRecordStream (Stack Label code data row)\nend L\n/-- Five physically allocated outer reader, prefix, copy and parser work roles. -/\ninductive Aux where\n  | reader | prefixBytes | copyScratch | fieldScratch | valid\n  deriving DecidableEq\ninstance : Fintype Aux :=Fintype.ofList [.reader,.prefixBytes,.copyScratch,.fieldScratch,.valid]\n  (by intro k;cases k <;> simp)\n/-- All344 physical roles, including every retained source cache and unused alias shadow. -/\nabbrev Stack := S.Stack ⊕ (R.Stack ⊕ Aux)\n/-- Complete actual N-only all-owner fibre source role inclusion. -/\ndef source (k : S.Stack) : Stack := .inl k\n/-- Complete actual34-role table, ordinal and consuming logger inclusion. -/\ndef record (k : R.Stack) : Stack := .inr (.inl k)\n/-- Literal outer reader, retained-prefix or parser work role. -/\ndef aux (k : Aux) : Stack := .inr (.inr k)\n/-- Only original binary N is present at standard machine initialization. -/\ndef originalInput : Stack := source S.originalInput\n/-- Actual accumulated reverse row log. -/\ndef history : Stack := record R.history\n/-- Actual final forward record stream output. -/\ndef output : Stack := record R.output\n/-- Actual parsed original binary E-owner key operand. -/\ndef key : Stack := record (SemiprimeD1StackOwnerRecord.tableStack SemiprimeD1StackOwnerTable.query)\n/-- Actual fresh copy of the retained caller prefix for this owner. -/\ndef prefixReader : Stack := record (SemiprimeD1StackOwnerRecord.tableStack SemiprimeD1StackOwnerTable.reader)\n/-- Actual parsed ordered binary scope-ID vector, shared by table counter and serializer. -/\ndef bank : Stack := record R.original\n/-- Logger role inclusion with its actual source operands directly aliased. -/\ndef logStack (k : L.Stack) : Stack :=record (SemiprimeD1StackOwnerRecord.recordStack k)\n/-- Two actual copies: complete source catalogue and caller prefix bytes per owner. -/\ndef copyStack (part : Bool) (k : Fin 3) : Stack :=\n  if k=0 then (if part then aux .prefixBytes else source (SemiprimeD1StackOwnerFibreCatalogue.aux .output))\n  else if k=1 then (if part then prefixReader else aux .reader) else aux .copyScratch\n/-- Actual source-catalogue parser roles; the finite phase chooses key or bank output. -/\ndef fieldStack (scopes : Bool) : F.Stack → Stack\n  | .inl .input => aux .reader\n  | .inl .scratch => aux .fieldScratch\n  | .inl .output => if scopes then bank else key\n  | .inr _ => aux .valid\n/-- Fixed finite outer source phases, with no unbounded control data. -/\ninductive Control where\n  | empty | main | copyCatalogue | initialize | loop | field (scopes : Bool) | valid (scopes : Bool)\n  | copyPrefix | emit | clearKey | clearTail | clearBank | reverse | halt | abort\n  deriving Fintype\n/-- All included source and literal bytecode labels, fixed before original N. -/\ninductive Label where\n  | local (pc : Control) | source (pc : S.Label) | record (pc : R.Label)\n  | copy (part : Bool) (pc : Fin 9) | field (scopes : Bool) (pc : F.Label) | log (pc : L.Label)\n  deriving Fintype\n/-- ONE fixed original-input source; original E/M counts and tables never enter control. -/\ndef program : Label → C.Instruction Stack Label\n  | .source pc => SemiprimeD1StackValidationLink.instruction source Label.source (S.program pc)\n  | .record pc => SemiprimeD1StackValidationLink.instruction record Label.record (R.program pc)\n  | .copy part pc => SemiprimeD1StackMultiplierLink.instruction (copyStack part) (Label.copy part) (SemiprimeD1StackCopy.code pc)\n  | .field scopes pc => SemiprimeD1StackMultiplierLink.instruction (fieldStack scopes) (Label.field scopes) (F.code pc)\n  | .log pc => SemiprimeD1StackMultiplierLink.instruction logStack Label.log (L.code pc)\n  | .local .empty => .base (.push (aux .prefixBytes) false (.local .main))\n  | .local .main => .call (.source (.local .main)) (.local .copyCatalogue)\n  | .local .copyCatalogue => .call (.copy false 0) (.local .initialize)\n  | .local .initialize => .call (.log .initialize) (.local .loop)\n  | .local .loop => .base (.pop (aux .reader) (.local .reverse) (.local .reverse) (.local (.field false)))\n  | .local (.field scopes) => .call (.field scopes (F.active .tagPop (none,false))) (.local (.valid scopes))\n  | .local (.valid scopes) => .base (.pop (aux .valid) (.local .abort) (.local .abort)\n      (if scopes then .local .copyPrefix else .local (.field true)))\n  | .local .copyPrefix => .call (.copy true 0) (.local .emit)\n  | .local .emit => .call (.record (.inl .start)) (.local .clearKey)\n  | .local .clearKey => .base (.pop key (.local .clearTail) (.local .clearKey) (.local .clearKey))\n  | .local .clearTail => .base (.pop prefixReader (.local .clearBank) (.local .clearTail) (.local .clearTail))\n  | .local .clearBank => .base (.pop bank (.local .loop) (.local .clearBank) (.local .clearBank))\n  | .local .reverse => .call (.log .reverse) (.local .halt)\n  | .local .halt | .local .abort => .base .halt\n/-- Complete physical source, owner-record and outer-role store description. -/\ndef data (s : S.Stack → List Bool) (r : R.Stack → List Bool) (a : Aux → List Bool) : Stack → List Bool :=\n  Sum.elim s (Sum.elim r a)\n/-- Actual remaining catalogue reader and retained caller prefix, with work roles empty. -/\ndef rowAux (reader prefixBytes : List Bool) : Aux → List Bool\n  | .reader => reader | .prefixBytes => prefixBytes | _ => []\n/-- Arbitrary actual caller prefix is retained separately and copied before every owner. -/\ndef initialPrefix (bits prefixBytes : List Bool) : C.State Stack Label :=\n  ⟨some (.local .main),none,none,data (S.input bits) (fun _=>[]) (rowAux [] prefixBytes),[]⟩\n/-- Empty-prefix specialization initially contains ONLY binary original N. -/\ndef initial (bits : List Bool) : C.State Stack Label :=\n  ⟨some (.local .empty),none,none,data (S.input bits) (fun _=>[]) (rowAux [] []),[]⟩\n/-- Genuine fixed finite machine compiling the actual source and real return alphabet. -/\ndef machine : Turing.FinTM2 :=SemiprimeD1StackCalls.machine originalInput output (.local .empty) program\ntheorem stack_card :Fintype.card Stack=344:=by decide\nend RiemannGaussian.SemiprimeD1StackOwnerRecords\n","RiemannGaussian.SemiprimeD1StackOwnerRecordsNumeric":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOwnerRecordsLoop\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackOwnerRecordsNumeric\nopen SemiprimeD1StackOwnerRecords SemiprimeD1StackOwnerRecordsLoop SemiprimeD1StackOwnerRecordsEmit\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeD1OwnerPrefixBits (records records_length)\n/-- Entire arbitrary caller tail is physically copied and then drained at EVERY owner. -/\ntheorem tail_length (fixed:List (List Bool×Bool)) (tail:List Bool) :tail.length≤(records fixed tail).length:=by\n  rw [records_length];omega\ntheorem empty_length (fixed:List (List Bool×Bool)) (tail:List Bool) :\n    (records fixed []).length≤(records fixed tail).length:=by rw [records_length,records_length];simp only [List.length_nil];omega\n/-- Closed bound for a whole actual parse/copy/table/ordinal/log/cleanup iteration. -/\ndef rowCap (M P:Nat) :Nat:=10000*(M+1)*(P+1)\ntheorem row_budget_le (r:Row) (fixed:List (List Bool×Bool)) (tail:List Bool) (M:Nat)\n    (hk:(keyOf r).length≤M) (hl:∀w∈wordsOf r,w.length≤M)\n    (hv:∀w∈wordsOf r,SemiprimeBitArithmetic.bitValue w≤M) :\n    rowBudget r fixed tail≤rowCap M (records fixed tail).length:=by\n  have ht:=SemiprimeD1StackOwnerRecordBounds.timeBound_le (keyOf r) fixed (wordsOf r) r.property M hl hv\n  have hb:=SemiprimeD1StackPortOrdinalStreamBounds.bank_length (wordsOf r) M hl\n  have hd:=r.property\n  have hp:=empty_length fixed tail\n  have hs:=tail_length fixed tail\n  have hb':(vectorBits (wordsOf r)).length≤2*(2*M+2)+1:=by nlinarith\n  have hm:100*((keyOf r).length+1)*((records fixed []).length+1)≤\n      100*(M+1)*((records fixed tail).length+1):=by gcongr\n  unfold rowBudget rowCap\n  nlinarith\n/-- Every actual row byte is paid by the SAME real logger subtrace. -/\ntheorem row_bytes_le (r:Row) (fixed:List (List Bool×Bool)) (tail:List Bool) :\n    (rowBytes r fixed).length≤rowBudget r fixed tail:=by\n  have ht:(rowBytes r fixed).length≤E.timeBound (keyOf r) fixed (wordsOf r) r.property:=by\n    unfold rowBytes SemiprimeD1StackOwnerRecordExecution.timeBound L.row\n      SemiprimeD1StackOwnerRecord.R.recordTime\n    simp only [List.length_cons,SemiprimeSourceHistogramKeyBits.frame_length,List.length_nil]\n    omega\n  unfold rowBudget;omega\n/-- Complete emitted row bytes are bounded by the actual all-owner loop budget. -/\ntheorem bytes_budget (rows:List Row) (fixed:List (List Bool×Bool)) (tail:List Bool) :\n    (bytes rows fixed).length≤loopBudget rows fixed tail:=by\n  induction rows with\n  | nil=>rfl\n  | cons r rows ih=>\n    have h:=row_bytes_le r fixed tail\n    simp only [bytes,List.map_cons,List.flatten_cons,List.length_append,loopBudget,List.sum_cons] at *\n    omega\n/-- Summing actual original owner iterations introduces no supplied owner count. -/\ntheorem loop_budget_le (rows:List Row) (fixed:List (List Bool×Bool)) (tail:List Bool) (M:Nat)\n    (hk:∀r∈rows,(keyOf r).length≤M) (hl:∀r∈rows,∀w∈wordsOf r,w.length≤M)\n    (hv:∀r∈rows,∀w∈wordsOf r,SemiprimeBitArithmetic.bitValue w≤M) :\n    loopBudget rows fixed tail≤rows.length*rowCap M (records fixed tail).length:=by\n  induction rows with\n  | nil=>simp only [loopBudget,List.map_nil,List.sum_nil,List.length_nil,Nat.zero_mul,Nat.le_refl]\n  | cons r rows ih=>\n    have h0:=row_budget_le r fixed tail M (hk r List.mem_cons_self)\n      (hl r List.mem_cons_self) (hv r List.mem_cons_self)\n    have h1:=ih (fun x hx=>hk x (List.mem_cons_of_mem r hx))\n      (fun x hx=>hl x (List.mem_cons_of_mem r hx)) (fun x hx=>hv x (List.mem_cons_of_mem r hx))\n    change rowBudget r fixed tail+loopBudget rows fixed tail≤_\n    simp only [List.length_cons,Nat.add_mul,Nat.one_mul];omega\nend RiemannGaussian.SemiprimeD1StackOwnerRecordsNumeric\n","RiemannGaussian.SemiprimeD1StackOwnerRecordsView":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOwnerRecords\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackOwnerRecordsView\nopen SemiprimeD1StackOwnerRecords\n/-- Actual owner-filter work roles alias no upstream source or outer loop word. -/\ntheorem record_injective :Function.Injective record:=Sum.inr_injective.comp Sum.inl_injective\n/-- Actual private outer roles alias no source or filter role. -/\ntheorem aux_injective :Function.Injective aux:=Sum.inr_injective.comp Sum.inr_injective\n/-- Literal reached filter-work projection. -/\ntheorem data_record (s:S.Stack→List Bool) (f:R.Stack→List Bool) (a:Aux→List Bool) (k:R.Stack) :\n    data s f a (record k)=f k:=rfl\n/-- Literal reached private metadata/reader/collector projection. -/\ntheorem data_aux (s:S.Stack→List Bool) (f:R.Stack→List Bool) (a:Aux→List Bool) (k:Aux) :\n    data s f a (aux k)=a k:=rfl\n/-- Exact physical filter-role update preserving the retained actual source and every outer word. -/\ntheorem update_record (s:S.Stack→List Bool) (f:R.Stack→List Bool) (a:Aux→List Bool) (k:R.Stack) (word:List Bool) :\n    Function.update (data s f a) (record k) word=data s (Function.update f k word) a:=by\n  funext j;rcases j with j|j\n  · exact Function.update_of_ne (by intro h;cases h) _ _\n  · rcases j with j|j\n    · change Function.update (data s f a) (record k) word (record j)=(Function.update f k word) j\n      simp only [Function.update_apply,data_record,record_injective.eq_iff]\n    · exact Function.update_of_ne (by intro h;cases h) _ _\n/-- Exact physical outer-role update preserving all original source/filter data. -/\ntheorem update_aux (s:S.Stack→List Bool) (f:R.Stack→List Bool) (a:Aux→List Bool) (k:Aux) (word:List Bool) :\n    Function.update (data s f a) (aux k) word=data s f (Function.update a k word):=by\n  funext j;rcases j with j|j\n  · exact Function.update_of_ne (by intro h;cases h) _ _\n  · rcases j with j|j\n    · exact Function.update_of_ne (by intro h;cases h) _ _\n    · change Function.update (data s f a) (aux k) word (aux j)=(Function.update a k word) j\n      simp only [Function.update_apply,data_aux,aux_injective.eq_iff]\n/-- Literal owner-record operand store; only bytes already parsed or physically copied. -/\ndef payload (key prefixBytes bank hist out : List Bool) : R.Stack→List Bool :=\n  (R.initial key prefixBytes bank hist out).data\n/-- Physical parsed key insertion affects no other operand or alias shadow. -/\ntheorem payload_key (key prefixBytes bank hist out word : List Bool) :\n    Function.update (payload key prefixBytes bank hist out)\n      (SemiprimeD1StackOwnerRecord.tableStack SemiprimeD1StackOwnerTable.query) word=\n      payload word prefixBytes bank hist out :=by\n  funext k;fin_cases k <;> rfl\ntheorem payload_prefix (key prefixBytes bank hist out word : List Bool) :\n    Function.update (payload key prefixBytes bank hist out)\n      (SemiprimeD1StackOwnerRecord.tableStack SemiprimeD1StackOwnerTable.reader) word=\n      payload key word bank hist out :=by\n  funext k;fin_cases k <;> rfl\ntheorem payload_bank (key prefixBytes bank hist out word : List Bool) :\n    Function.update (payload key prefixBytes bank hist out) R.original word=\n      payload key prefixBytes word hist out :=by\n  funext k;fin_cases k <;> rfl\ntheorem payload_history (key prefixBytes bank hist out word : List Bool) :\n    Function.update (payload key prefixBytes bank hist out) R.history word=\n      payload key prefixBytes bank word out :=by\n  funext k;fin_cases k <;> rfl\ntheorem payload_output (key prefixBytes bank hist out word : List Bool) :\n    Function.update (payload key prefixBytes bank hist out) R.output word=\n      payload key prefixBytes bank hist word :=by\n  funext k;fin_cases k <;> rfl\nend RiemannGaussian.SemiprimeD1StackOwnerRecordsView\n","RiemannGaussian.SemiprimeD1StackPackedRootContextPrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPackedRootContextEncoding\n/-! # Actual derived-precision copy with its own physical call and return -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPackedRootContextPrimitives\nopen SemiprimeD1StackPackedRootContext SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => (Sum.inl : Control→Label)\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel data_update)\nend Link\n/-- Actual fragments concatenate with all external real return frames retained. -/\ntheorem join {m n:Nat} {pc mid next:Label} {before between after:Stack→List Bool}\n    (h:Runs program m pc before mid between) (g:Runs program n mid between next after) :\n    Runs program (m+n) pc before next after :=runs_trans program m n pc mid next before between after h g\n/-- Actual preserving copy of the derived binary precision, including restoring scratch and the real return. -/\ntheorem copy_call (before:Stack→List Bool) (xs ys:List Bool)\n    (hx:before (copyStack 0)=xs) (hy:before (copyStack 1)=ys) (hs:before (copyStack 2)=[]) :\n    Runs program (5*xs.length+4) (ctl .copyPrecision) before (ctl .seedAxes)\n      (Function.update before (copyStack 1) (xs++ys)) :=by\n  let start:=SemiprimeD1StackCopy.state 0 none xs ys []\n  let stop:=SemiprimeD1StackCopy.done xs (xs++ys)\n  have hi:Link.DataRel copyStack before start.store before:=by\n    constructor\n    · intro k;fin_cases k\n      · exact hx\n      · exact hy\n      · exact hs\n    · intro k _;rfl\n  have ho:=Link.data_update copyStack copy_injective before start.store before hi (1:Fin 3) (xs++ys)\n  have he:Function.update start.store 1 (xs++ys)=stop.store:=by funext k;fin_cases k <;> rfl\n  rw [he] at ho\n  exact included_call program copyStack copyLabel copy_injective SemiprimeD1StackCopy.code 0\n    (fun _=>rfl) (ctl .copyPrecision) (ctl .seedAxes) rfl (5*xs.length+3) start stop before _ rfl rfl\n    (SemiprimeD1StackCopy.copy_words xs ys none) hi ho\n/-- Literal empty-axis header seed pays its actual FALSE-cell push. -/\ntheorem axes_seed (before:Stack→List Bool):\n    Runs program 1 (ctl .seedAxes) before (ctl .acquireContext)\n      (Function.update before (context J.axesCache) (false::before (context J.axesCache))) :=\n  one_base program _ _ _ _ _ rfl rfl rfl\nend RiemannGaussian.SemiprimeD1StackPackedRootContextPrimitives\n","RiemannGaussian.SemiprimeD1StackPackedRootInputStorage":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPackedRootInputBounds\n/-! # All2505 words and real returns from genuine original-input initialization -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPackedRootInputStorage\nopen scoped BigOperators\nopen SemiprimeD1StackPackedRootInput SemiprimeD1StackPackedRootInputEncoding\nopen SemiprimeD1StackPackedRootInputBounds\nopen SemiprimeD1StackCalls (run configuration)\nopen SemiprimeBitArithmetic (bitValue)\n/-- Every non-input role really starts empty. -/\ntheorem input_single (bits : List Bool) : input bits=fun k => if k=originalInput then bits else [] := by\n  funext k\n  rcases k with k|k\n  · have h:=congrFun (SemiprimeD1StackRootPacketInventoryStorage.input_single bits) k\n    simpa only [input,bank,rootStack,originalInput,Sum.elim_inl,Sum.inl.injEq] using h\n  · rcases k with k|k <;> rfl\n/-- Genuine Turing.initList is exactly the new source's sole-binary-input initial state. -/\ntheorem initial_eq (bits : List Bool) : Turing.initList machine bits=configuration (initial bits) := by\n  have hs : SemiprimeD1StackCalls.initial originalInput (Label.local .start) bits=initial bits := by\n    apply congrArg (fun d => (⟨some (Label.local .start),none,none,d,[]⟩ : C.State Stack Label))\n    exact (input_single bits).symm\n  exact (SemiprimeD1StackCalls.initial_correct originalInput output (.local .start) program bits).symm.trans\n    (congrArg configuration hs)\n/-- Every initial word is paid by actual original binary input bytes. -/\ntheorem initial_length (bits : List Bool) (k : Stack) : ((initial bits).data k).length ≤ bits.length := by\n  change (input bits k).length ≤ bits.length\n  rw [input_single]\n  change (if k=originalInput then bits else []).length ≤ bits.length\n  split_ifs\n  · exact le_rfl\n  · exact Nat.zero_le _\n/-- Every complete actual machine prefix is before the SAME program's proved halt. -/\ntheorem prefix_clock (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits)\n    (fuel : ℕ) (out : C.State Stack Label) (hr : run program fuel (initial bits)=some out) : fuel ≤ runBound bits := by\n  obtain ⟨t,ht,hstop⟩:=source_run_bounded bits hc hN\n  have hh : run program 1 (done bits hN)=none := rfl\n  have hf : fuel ≤ t := by\n    by_contra hn\n    have he : fuel=t+(1+(fuel-(t+1))) := by omega\n    rw [he,SemiprimeD1StackReturnLink.run_add,hstop,Option.bind_some,\n      SemiprimeD1StackReturnLink.run_add,hh,Option.bind_none] at hr\n    cases hr\n  exact hf.trans ht\n/-- All2505 allocations, including every retained and unused shadow, are counted. -/\ntheorem word_sum (d : Stack→List Bool) (cap : ℕ) (h : ∀k,(d k).length ≤ cap) :\n    (∑k : Stack,(d k).length) ≤ 2505*cap := by\n  calc\n    _ ≤ ∑_k : Stack,cap := Finset.sum_le_sum (fun k _ => h k)\n    _ = _ := by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n/-- SAME actual finite-source prefix data and all real saved-return cells. -/\ntheorem prefix_cells (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits)\n    (fuel : ℕ) (out : C.State Stack Label) (hr : run program fuel (initial bits)=some out) :\n    (∑k : Stack,(out.data k).length)+out.frames.length ≤ 2506*(bits.length+runBound bits) := by\n  have hf:=prefix_clock bits hc hN fuel out hr\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel bits.length (initial bits) out\n    (initial_length bits) hr\n  have hs:=word_sum out.data (bits.length+fuel) hd\n  have hframes:=SemiprimeD1StackCalls.run_frame_bound program fuel (initial bits) out hr\n  change out.frames.length ≤ 0+fuel at hframes\n  omega\n/-- Genuine compiled whole original-input machine certificate, with its SAME own total clock. -/\nnoncomputable def machineSource (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits) :\n    StateTransition.EvalsToInTime machine.step (Turing.initList machine bits)\n      (some (configuration (done bits hN))) (runBound bits) := by\n  rw [initial_eq]\n  apply SemiprimeD1StackCalls.evalsCorrect originalInput output (.local .start) program\n  let h:=source_run_bounded bits hc hN\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\n/-- Every compiled original-input prefix includes all2505 data words and the real return stack. -/\ntheorem machine_prefix_cells (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits)\n    (fuel : ℕ) (cfg : machine.Cfg)\n    (hp : (fun q => q.bind machine.step)^[fuel] (some (Turing.initList machine bits))=some cfg) :\n    (∑k : Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤ 2506*(bits.length+runBound bits) := by\n  rw [initial_eq] at hp\n  have he:=SemiprimeD1StackCalls.run_correct originalInput output (.local .start) program fuel (initial bits)\n  have hh:=he.trans hp\n  cases hout : run program fuel (initial bits) with\n  | none => rw [hout] at hh;cases hh\n  | some out =>\n    rw [hout] at hh\n    have hcfg : cfg=configuration out := (Option.some.inj hh).symm\n    subst cfg\n    exact prefix_cells bits hc hN fuel out hout\nend RiemannGaussian.SemiprimeD1StackPackedRootInputStorage\n","RiemannGaussian.SemiprimeD1StackPackedRootInputView":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPackedRootInputEncoding\n/-! # Actual acquired-bank relations for the shared marked continuation -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPackedRootInputView\nopen SemiprimeD1StackPackedRootInput SemiprimeD1StackPackedRootInputEncoding\nopen SemiprimeBitArithmetic (bitValue)\nopen SemiprimeD1StackMultiplierLink (DataRel)\n/-- All207 new marked-source roles are genuinely empty at its honest ready entry. -/\ntheorem ready_private_empty (bits : List Bool) (hN : 0<bitValue bits) (k : Private) :\n    (SemiprimeD1StackMarkedRootRecordsExecution.ready bits hN).data (.inr k)=[] := by\n  rcases k with k|k\n  · rfl\n  · rcases k with k|k\n    · change SemiprimeD1StackMarkedRootRecords.privateTable\n        (SemiprimeD1StackMarkedRootRecordsTableView.tableWords bits [] [] [] [] []) k=[]\n      rw [SemiprimeD1StackMarkedRootRecordsExecution.private_empty]\n      simp only [SemiprimeD1StackMarkedRootRecords.privateTable,ite_self]\n    · cases k <;> rfl\n/-- The SAME acquired2270 bank supplies the entire real ready2011 front door. -/\ntheorem marked_ready_rel (bits : List Bool) (hN : 0<bitValue bits) :\n    DataRel markedStack (rootReady bits hN)\n      (SemiprimeD1StackMarkedRootRecordsExecution.ready bits hN).data (rootReady bits hN) := by\n  constructor\n  · intro k\n    rcases k with k|k\n    · exact SemiprimeD1PackedRootRetained.source_projection bits hN k\n    · exact (ready_private_empty bits hN k).symm\n  · intro k _\n    rfl\n/-- The marked continuation restores every old1804 word and retains every foreign2270 word. -/\ntheorem marked_result_rel (bits : List Bool) (hN : 0<bitValue bits) :\n    DataRel markedStack (rootReady bits hN)\n      (SemiprimeD1StackMarkedRootRecordsExecution.done bits hN).data (markedReady bits hN) := by\n  constructor\n  · intro k\n    rcases k with k|k\n    · exact (SemiprimeD1PackedRootRetained.source_projection bits hN k).trans\n        (SemiprimeD1StackMarkedRootRecordsOriginal.root_preserved bits hN k).symm\n    · rfl\n  · intro k hk\n    rcases k with k|k\n    · rfl\n    · rcases k with k|k\n      · exact (hk (.inr k) rfl).elim\n      · rfl\n/-- The actual copied N forms the full honest28-role source front door. -/\ntheorem context_ready_rel (bits : List Bool) (hN : 0<bitValue bits) :\n    DataRel contextStack (contextReady bits hN) (J.input bits) (contextReady bits hN) := by\n  constructor\n  · intro k\n    rfl\n  · intro k _\n    rfl\n/-- Acquiring the new header retains ALL actual original and marked record-source data. -/\ntheorem context_result_rel (bits : List Bool) (hN : 0<bitValue bits) :\n    DataRel contextStack (contextReady bits hN)\n      (SemiprimeD1StackPackedRootContextEncoding.done bits).data (result bits hN) := by\n  constructor\n  · intro k\n    rfl\n  · intro k hk\n    rcases k with k|k\n    · rfl\n    · rcases k with k|k\n      · rfl\n      · exact (hk k rfl).elim\nend RiemannGaussian.SemiprimeD1StackPackedRootInputView\n","RiemannGaussian.SemiprimeD1StackPackedRootMetadataLoop":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPackedRootMetadataCalls\n/-! # Complete actual width-marker loop, with physical precision/base growth -/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackPackedRootMetadataLoop\nopen SemiprimeD1StackPackedRootMetadata SemiprimeD1StackPackedRootMetadataEncoding\nopen SemiprimeD1StackPackedRootMetadataPrimitives SemiprimeD1StackPackedRootMetadataCalls\nopen SemiprimeD1StackProcedureTrace SemiprimeBitArithmetic\nlocal notation \"ctl\" => Label.local\n/-- The full empty allocated adder includes its real unused left shadow. -/\ntheorem empty_adder : A.store [] [] [] []=(fun _ => []) := by funext k;cases k <;> rfl\n/-- Exact actual per-iteration bank, including the retained bootstrap bank. -/\ndef work (b : B.Stack→List Bool) (reader p base template right sum : List Bool) : Stack→List Bool :=\n  bank b (A.store [] right [] sum) (words reader [] p base template)\n/-- The invariant names actual words only; no decoded natural enters code. -/\ntheorem loop_work (b : B.Stack→List Bool) (n t : ℕ) :\n    loop b n t=work b (List.replicate t true) (precisionWord n) (baseWord n) (List.replicate (2*n) false) [] [] := by\n  unfold loop work\n  rw [empty_adder]\n/-- Exact single-cell base growth. -/\ntheorem base_succ (n : ℕ) : baseWord (n+1)=false::baseWord n := by\n  simp only [baseWord,List.replicate_succ,List.cons_append]\n/-- The two actual width writes count both physical cells. -/\ntheorem template_succ (n : ℕ) : List.replicate (2*(n+1)) false=false::false::List.replicate (2*n) false := by\n  rw [show 2*(n+1)=2*n+2 by omega,List.replicate_succ,List.replicate_succ]\n/-- Exact sum of the five local pushes/pop, REAL add, preserving copy and drain. -/\ndef stepTime (n : ℕ) : ℕ :=\n  6+addTime (precisionWord n)+(5*(precisionWord (n+1)).length+4)+((precisionWord (n+1)).length+1)\n/-- One complete real marker iteration acquires the NEXT binary precision,\none base shift and TWO width cells, with all private/shadow words cleared. -/\ntheorem step_run (b : B.Stack→List Bool) (n t : ℕ) :\n    Runs program (stepTime n) (ctl .read) (loop b n (t+1)) (ctl .read) (loop b (n+1) t) := by\n  rw [loop_work,loop_work]\n  let r := List.replicate t true\n  let p := precisionWord n\n  let base := baseWord n\n  let width := List.replicate (2*n) false\n  have h0 := pop_run .read (ctl .done) (ctl .growBase) (ctl .growBase) (aux .reader)\n    (work b (true::r) p base width [] []) (true::r) rfl rfl\n  dsimp only [work] at h0\n  rw [update_aux,words_update] at h0\n  change Runs program 1 (ctl .read) (work b (true::r) p base width [] []) (ctl .growBase) (work b r p base width [] []) at h0\n  have h1 := push_run .growBase (ctl .growFirst) (aux .base) false (work b r p base width [] []) rfl\n  dsimp only [work] at h1\n  rw [update_aux,words_update] at h1\n  change Runs program 1 _ _ _ (work b r p (false::base) width [] []) at h1\n  have h2 := push_run .growFirst (ctl .growSecond) (aux .template) false (work b r p (false::base) width [] []) rfl\n  dsimp only [work] at h2\n  rw [update_aux,words_update] at h2\n  change Runs program 1 _ _ _ (work b r p (false::base) (false::width) [] []) at h2\n  have h3 := push_run .growSecond (ctl .seedHigh) (aux .template) false (work b r p (false::base) (false::width) [] []) rfl\n  dsimp only [work] at h3\n  rw [update_aux,words_update] at h3\n  change Runs program 1 _ _ _ (work b r p (false::base) (false::false::width) [] []) at h3\n  have h4 := push_run .seedHigh (ctl .seedLow) (adder .right) true (work b r p (false::base) (false::false::width) [] []) rfl\n  change Runs program 1 _ _ _ (Function.update (work b r p (false::base) (false::false::width) [] []) (adderAllocation .right) [true]) at h4\n  dsimp only [work] at h4\n  rw [update_adder,SemiprimeD1StackAdder.store_right] at h4\n  have h5 := push_run .seedLow (ctl .add) (adder .right) false (work b r p (false::base) (false::false::width) [true] []) rfl\n  change Runs program 1 _ _ _ (Function.update (work b r p (false::base) (false::false::width) [true] []) (adderAllocation .right) [false,true]) at h5\n  dsimp only [work] at h5\n  rw [update_adder,SemiprimeD1StackAdder.store_right] at h5\n  have h6 := add_call b (words r [] p (false::base) (false::false::width)) p rfl\n  rw [words_update] at h6\n  change Runs program (addTime p) _ _ _ (work b r [] (false::base) (false::false::width) [] (precisionWord (n+1))) at h6\n  have h7 := copy_call .sum .copySum .clearSum rfl (work b r [] (false::base) (false::false::width) [] (precisionWord (n+1)))\n    (precisionWord (n+1)) [] rfl rfl rfl\n  rw [List.append_nil] at h7\n  change Runs program _ _ _ _ (Function.update (work b r [] (false::base) (false::false::width) [] (precisionWord (n+1)))\n    (aux .precision) (precisionWord (n+1))) at h7\n  dsimp only [work] at h7\n  rw [update_aux,words_update] at h7\n  have h8 := drain_loop .clearSum (ctl .read) (adder .output) rfl\n    (work b r (precisionWord (n+1)) (false::base) (false::false::width) [] (precisionWord (n+1))) (precisionWord (n+1)) rfl\n  change Runs program _ _ _ _ (Function.update\n    (work b r (precisionWord (n+1)) (false::base) (false::false::width) [] (precisionWord (n+1))) (adderAllocation .output) []) at h8\n  dsimp only [work] at h8\n  rw [update_adder,SemiprimeD1StackAdder.store_output] at h8\n  have h := join (join (join (join (join (join (join (join h0 h1) h2) h3) h4) h5) h6) h7) h8\n  have ht : 1+1+1+1+1+1+addTime p+(5*(precisionWord (n+1)).length+4)+((precisionWord (n+1)).length+1)=stepTime n := by\n    dsimp only [p,stepTime]\n  rw [ht] at h\n  simpa only [stepTime,base_succ,template_succ,List.replicate_succ,r,p,base,width,work,Nat.add_assoc] using h\n\n/-- Literal transition count of the ACTUAL repeated marker loop. -/\ndef loopTime : ℕ→ℕ→ℕ\n  | _,0 => 1\n  | n,t+1 => stepTime n+loopTime (n+1) t\n/-- Complete loop physically visits every acquired marker and its final EOF. -/\ntheorem loop_run (b : B.Stack→List Bool) (n t : ℕ) :\n    Runs program (loopTime n t) (ctl .read) (loop b n t) (ctl .done) (loop b (n+t) 0) := by\n  induction t generalizing n with\n  | zero =>\n    have h := pop_run .read (ctl .done) (ctl .growBase) (ctl .growBase) (aux .reader) (loop b n 0) [] rfl rfl\n    have he : Function.update (loop b n 0) (aux .reader) []=loop b n 0 := by\n      apply Function.update_eq_self_iff.mpr\n      rfl\n    change Runs program 1 (ctl .read) (loop b n 0) (ctl .done) (Function.update (loop b n 0) (aux .reader) []) at h\n    rw [he] at h\n    exact h\n  | succ t ih =>\n    have h := join (step_run b n t) (ih (n+1))\n    simpa only [loopTime,Nat.add_assoc,Nat.add_left_comm,Nat.add_comm] using h\n\n/-- Fixed linear per-marker cost in actual counter bytes, not a native report. -/\ntheorem stepTime_le (n : ℕ) : stepTime n ≤ 50*(n+1) := by\n  have h0 := addTime_le n\n  have h1 := precision_length (n+1)\n  unfold stepTime\n  omega\n/-- Whole actual loop has a fixed quadratic cap; dimensions are paid by VALUE. -/\ntheorem loopTime_le (n t : ℕ) : loopTime n t ≤ 50*t*(n+t+1)+1 := by\n  induction t generalizing n with\n  | zero => simpa only [loopTime,Nat.mul_zero,Nat.zero_mul,Nat.zero_add] using (Nat.le_refl 1)\n  | succ t ih =>\n    have h0 := stepTime_le n\n    have h1 := ih (n+1)\n    rw [loopTime]\n    nlinarith only [h0,h1]\nend RiemannGaussian.SemiprimeD1StackPackedRootMetadataLoop\n","RiemannGaussian.SemiprimeD1StackPacketInventoryOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPacketInventoryBounds\nimport RiemannGaussian.SemiprimeD1StackPacketInventoryMeaning\n/-! # Entire original sparse packet inventory from actual acquired input bytes\nThe parent selected-key and alphabet sources supply two stopped words. This\nprepared consumer executes no selector, original getter, report or callback.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPacketInventoryOriginal\nopen SemiprimeD1StackPacketInventory SemiprimeD1StackPacketInventoryEncoding\nopen SemiprimeD1StackPacketInventoryBounds SemiprimeD1StackPacketInventoryMeaning\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nattribute [local irreducible] SemiprimeD1IncidenceSearch.run SemiprimeD1IncidenceAcquisition.acquire\n/-- Entire original actual selected-key stream, including all repeated occurrences and factor-major order. -/\ndef originalKeys (n F a:Nat) (arity:Fin F→Nat) (owner:((e:Fin F)×Fin (arity e))→Fin n):List (List Bool):=\n  (SemiprimeD1IncidenceAcquisition.acquire n F 64 a arity owner).keys\n/-- Original key membership is proved from the same selected IDs, with no external row-validity or menu advice. -/\ntheorem original_valid (n F a:Nat) (arity:Fin F→Nat) (owner:((e:Fin F)×Fin (arity e))→Fin n):\n    ValidKeys a (originalKeys n F a arity owner):=by\n  intro raw hr\n  unfold originalKeys at hr\n  rw [SemiprimeD1IncidenceAcquisition.keys_original] at hr\n  obtain ⟨p,_,rfl⟩:=List.mem_map.mp hr\n  exact SemiprimeD1StackPacketRowsOriginal.selected_key_lineage n F a arity owner p\n/-- Generic exact physical output projection precedes instantiation of any large original graph. -/\ntheorem output_bytes (keys cat:List Bool) (s:Summary):\n    (done keys cat s).data output=vectorBits (s.placements.map placementBytes):=rfl\n/-- All packet discovery bytes are retained in exact newest-first original order. -/\ntheorem packet_bytes (keys cat:List Bool) (s:Summary):\n    (done keys cat s).data packets=vectorBits s.packets:=rfl\n/-- Both actual original input words remain unchanged. -/\ntheorem inputs_retained (keys cat:List Bool) (s:Summary):\n    (done keys cat s).data source=keys ∧ (done keys cat s).data catalogue=cat:=⟨rfl,rfl⟩\n/-- The retained original selected acquisition uses the same actual original row dictionary. -/\ntheorem acquired_dictionary (n F a:Nat) (arity:Fin F→Nat) (owner:((e:Fin F)×Fin (arity e))→Fin n):\n    (SemiprimeD1IncidenceAcquisition.acquire n F 64 a arity owner).selection.cache.rows.source.dictionary=\n      SemiprimeSourceHistogramRows.acquire 64 a:=by\n  unfold SemiprimeD1IncidenceAcquisition.acquire\n  rfl\n/-- Native original placements are exactly the chronological replay from physically empty classes/seen/slots. -/\ntheorem placements_original (n F a:Nat) (arity:Fin F→Nat) (owner:((e:Fin F)×Fin (arity e))→Fin n):\n    (acquire a (originalKeys n F a arity owner)).placements=\n      (SemiprimeD1PacketInventory.acquire n F 64 a arity owner).placements:=by\n  unfold SemiprimeD1PacketInventory.acquire\n  dsimp only\n  rw [acquired_dictionary]\n  exact (acquire_original a (originalKeys n F a arity owner)\n    (SemiprimeD1IncidenceAcquisition.acquire n F 64 a arity owner).state.clock).1\n/-- Every final class, seen and slot read, packet discovery order and positive edge word has exact old meaning. -/\ntheorem state_original (n F a:Nat) (arity:Fin F→Nat) (owner:((e:Fin F)×Fin (arity e))→Fin n):\n    Rel (acquire a (originalKeys n F a arity owner))\n      (SemiprimeD1PacketInventory.acquire n F 64 a arity owner).state:=by\n  unfold SemiprimeD1PacketInventory.acquire\n  dsimp only\n  rw [acquired_dictionary]\n  exact (acquire_original a (originalKeys n F a arity owner)\n    (SemiprimeD1IncidenceAcquisition.acquire n F 64 a arity owner).state.clock).2\n/-- One actual fixed59-role source for the entire original family, with exact six-field placements and packet discovery vector. -/\ntheorem source_run_original (n F a:Nat) (arity:Fin F→Nat) (owner:((e:Fin F)×Fin (arity e))→Fin n):\n    ∃t ≤ byteBound (vectorBits (originalKeys n F a arity owner)) (alphabet a),\n      SemiprimeD1StackCalls.run program t (initial (vectorBits (originalKeys n F a arity owner)) (alphabet a))=\n        some (done (vectorBits (originalKeys n F a arity owner)) (alphabet a)\n          (acquire a (originalKeys n F a arity owner))) ∧\n      (done (vectorBits (originalKeys n F a arity owner)) (alphabet a)\n        (acquire a (originalKeys n F a arity owner))).data output=\n        vectorBits ((SemiprimeD1PacketInventory.acquire n F 64 a arity owner).placements.map placementBytes) ∧\n      (done (vectorBits (originalKeys n F a arity owner)) (alphabet a)\n        (acquire a (originalKeys n F a arity owner))).data packets=\n        vectorBits (SemiprimeD1PacketInventory.acquire n F 64 a arity owner).state.packets:=by\n  obtain ⟨t,ht,hr⟩:=source_run_keys a (originalKeys n F a arity owner) (original_valid n F a arity owner)\n  refine ⟨t,ht,hr,?_,?_⟩\n  · rw [output_bytes,placements_original]\n  · rw [packet_bytes,(state_original n F a arity owner).packets]\nend RiemannGaussian.SemiprimeD1StackPacketInventoryOriginal\n","RiemannGaussian.SemiprimeD1StackPacketInventoryRowCost":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPacketInventoryWidths\n/-! # Fixed polynomial caps for the actual inventory replay fragments -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPacketInventoryRowCost\nopen SemiprimeD1StackPacketInventoryEncoding SemiprimeD1StackPacketInventoryStepEncoding\nopen SemiprimeD1StackPacketInventoryWidths SemiprimeD1StackPacketInventoryStep\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nnamespace D\nexport SemiprimeD1StackSourceKeyFrequencyEncoding (coded encoded dictionary read)\nend D\n/-- Every copied/scanned/unread catalogue byte is charged to the same actual lookup source. -/\ntheorem readBound_le (q:List Bool) (rows:List (List Bool×List Bool)):\n    SemiprimeD1StackPacketInventoryRead.readBound q rows  ≤\n      200*(q.length+1)*((SemiprimeD1StackOwnerLookup.records rows []).length+1):=by\n  have hu:=(SemiprimeD1StackPacketRowsClock.lookup_lengths q rows).2\n  unfold SemiprimeD1StackPacketInventoryRead.readBound SemiprimeD1StackOwnerLookupBounds.runBound\n  nlinarith\n/-- Uniform cubic read cap in actual source width; historical overrides are all included. -/\ntheorem readBound_cubic (S:Nat) (hS:1 ≤ S) (q:List Bool) (rows:List (List Bool×List Bool))\n    (hq:q.length ≤ 21*S) (hd:(SemiprimeD1StackOwnerLookup.records rows []).length ≤ 50*S^2):\n    SemiprimeD1StackPacketInventoryRead.readBound q rows ≤ 300000*S^3:=by\n  have hh:=readBound_le q rows\n  have hp:=Nat.mul_le_mul (show 200*(q.length+1) ≤ 200*(22*S) by omega)\n    (show (SemiprimeD1StackOwnerLookup.records rows []).length+1 ≤ 51*S^2 by\n      have h2:1 ≤ S^2:=by nlinarith\n      omega)\n  have he:200*(22*S)*(51*S^2) ≤ 300000*S^3:=by nlinarith\n  exact hh.trans (hp.trans he)\n/-- Both dictionaries actually scanned by the source have quadratic retained byte size. -/\ntheorem dictionary_caps (S m:Nat) (hS:1 ≤ S) (hm:m ≤ S) (s:Summary) (hs:Sized m S s):\n    (D.dictionary s.classes).length ≤ 50*S^2 ∧ (D.dictionary s.seen).length ≤ 50*S^2:=by\n  have hc:=B.dictionary_length m S (classSummary s) hs.classes\n  have hv:=B.dictionary_length m (20*S) (seenSummary s) hs.seen\n  have hpc:=Nat.mul_le_mul hm (show 2*(S+1+m)+3 ≤ 4*S+5 by omega)\n  have hpv:=Nat.mul_le_mul hm (show 2*(20*S+1+m)+3 ≤ 42*S+5 by omega)\n  change (D.dictionary s.classes).length ≤ _ at hc\n  change (D.dictionary s.seen).length ≤ _ at hv\n  constructor <;> nlinarith\n/-- One literal whole replay step has a fixed cubic bound in paid source bytes. -/\ntheorem rowBound_le (a S m:Nat) (hS:1 ≤ S) (hm:m+1 ≤ S) (ha:(alphabet a).length ≤ S)\n    (s:Summary) (hs:Sized m S s) (owner factor:List Bool)\n    (ho:owner∈(SemiprimeSourceCompactWordBank.acquire 64 a).ids)\n    (hf:factor∈(SemiprimeSourceCompactWordBank.acquire 64 a).ids)\n    (hk:(key owner factor).length ≤ S):rowBound a s owner factor ≤ 1000000000*S^3:=by\n  have hi:=index_length m S s owner factor hs\n  have hi':(D.read s.classes (key owner factor)).length ≤ S:=hi.trans (by omega)\n  have hn:(Counter.successor (D.read s.classes (key owner factor))).length ≤ S:=\n    (SemiprimeD1StackSourceEnvironmentEncoding.successor_length _).trans (by change (index s owner factor).length+1 ≤ S;omega)\n  have he:s.edge.length ≤ S:=hs.classes.maximum.trans (by omega)\n  have hen:(nextEdge s).length ≤ S:=\n    (SemiprimeD1StackSourceEnvironmentEncoding.successor_length s.edge).trans (by\n      have hh:s.edge.length ≤ m:=hs.classes.maximum\n      omega)\n  have hl:=fields_length a owner ho\n  have hr:=fields_length a factor hf\n  have hp:=oriented_lengths a s owner factor ho hf\n  have hp':(oriented a s owner factor).key.length ≤ 20*S:=by omega\n  have hv':(oriented a s owner factor).slots.length ≤ 3*S:=by omega\n  have hh':(oriented a s owner factor).high.length ≤ S:=by omega\n  have hd:=dictionary_caps S m hS (by omega) s hs\n  have hq:(D.encoded (key owner factor)).length ≤ 21*S:=by\n    simp only [D.encoded,List.length_append,List.length_singleton];omega\n  have hqp:(D.encoded (oriented a s owner factor).key).length ≤ 21*S:=by\n    simp only [D.encoded,List.length_append,List.length_singleton];omega\n  have hc:=readBound_cubic S hS (D.encoded (key owner factor)) (D.coded s.classes) hq hd.1\n  have hv:=readBound_cubic S hS (D.encoded (oriented a s owner factor).key) (D.coded s.seen) hqp hd.2\n  have h2:S ≤ S^2:=Nat.le_pow (by decide:0<(2:Nat))\n  have h3:S^2 ≤ S^3:=by nlinarith\n  have hRows:SemiprimeD1StackPacketInventoryRows.rowsBound a owner factor (index s owner factor) ≤ 1000000*S^2:=by\n    have hh:(key owner factor).length+(alphabet a).length+1 ≤ 3*S:=by omega\n    have hp2:=Nat.pow_le_pow_left hh 2\n    unfold SemiprimeD1StackPacketInventoryRows.rowsBound\n      SemiprimeD1StackPacketRowsClock.polynomial SemiprimeD1StackPacketRowsClock.inputSize\n      SemiprimeD1StackPacketOrientationClock.polynomial SemiprimeD1StackPacketOrientationClock.inputSize\n    change 100000*((key owner factor).length+(alphabet a).length+1)^2+1+1+\n      (10000*((vectorBits (Reader.fields 64 a owner)).length+(vectorBits (Reader.fields 64 a factor)).length+\n      (index s owner factor).length+1)+1)+1 ≤ 1000000*S^2\n    nlinarith only [hp2,hl,hr,ha,hi,hm,hS,h2]\n  have hqsmall:(D.encoded (key owner factor)).length ≤ S+1:=by\n    simp only [D.encoded,List.length_append,List.length_singleton];omega\n  have hclass:SemiprimeD1StackPacketInventoryClass.classBound s.classes (key owner factor) ≤ 1000000*S^3:=by\n    unfold SemiprimeD1StackPacketInventoryClass.classBound\n    omega\n  have hseen:SemiprimeD1StackPacketInventoryDiscovery.seenBound s.seen (oriented a s owner factor).key ≤ 1000000*S^3:=by\n    unfold SemiprimeD1StackPacketInventoryDiscovery.seenBound\n    omega\n  unfold rowBound\n  omega\nend RiemannGaussian.SemiprimeD1StackPacketInventoryRowCost\n","RiemannGaussian.SemiprimeD1StackPacketInventoryStream":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPacketInventoryView\n/-! # Actual selected-key Field parser and physical validity consumption\nA prior real vector-tag pop exposes the framed raw key. The parser consumes\nthat actual frame, restores scratch and physically pops its true validity byte.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPacketInventoryStream\nopen SemiprimeD1StackPacketInventory SemiprimeD1StackPacketInventoryPrimitives\nopen SemiprimeD1StackPacketInventoryView SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel data_update)\nend Link\nlocal notation \"ctl\"=>Label.local\n/-- One complete real raw-key Field source, including its actual call/return and singleton true validity. -/\ntheorem field_run (f:W.Words) (r:R.Stack→List Bool) (o:O.Stack→List Bool) (key tail:List Bool)\n    (hr:f.reader=frame key tail) (ho:f.raw=[]) (hs:f.fieldScratch=[]) (hv:f.valid=[]):\n    Runs program (8*key.length+7) (ctl .parse) (view f r o) (ctl .valid)\n      (view {f with reader:=tail,raw:=key,valid:=[true]} r o) :=by\n  let start:=SemiprimeD1TensorTapeFieldBytecode.initial (frame key tail) []\n  let stop:SemiprimeD1StackBytecode.State Field.Stack Field.Label:=\n    ⟨none,none,Sum.elim (SemiprimeD1TensorTapeFieldMachine.contents tail [] key) (fun _=>[true])⟩\n  have hin:Link.DataRel fieldStack (view f r o) start.store (view f r o):=by\n    constructor\n    · intro k;rcases k with k|k\n      · cases k\n        · exact hr\n        · exact hs\n        · exact ho\n      · cases k;exact hv\n    · intro k _;rfl\n  have h0:=Link.data_update fieldStack field_injective (view f r o) start.store (view f r o) hin (.inl .input) tail\n  have h1:=Link.data_update fieldStack field_injective (view f r o) _ _ h0 (.inl .output) key\n  have h2:=Link.data_update fieldStack field_injective (view f r o) _ _ h1 (.inr ()) [true]\n  have he:Function.update (Function.update (Function.update start.store (.inl .input) tail) (.inl .output) key)\n      (.inr ()) [true]=stop.store:=by\n    funext k;rcases k with k|k <;> cases k <;> rfl\n  rw [he] at h2\n  change Link.DataRel fieldStack (view f r o) stop.store (Function.update (Function.update (Function.update\n    (view f r o) (frequencyStack (F.aux .reader)) tail) (frequencyStack (F.aux .raw)) key)\n      (frequencyStack (F.lookupStack (.inr .valid))) [true]) at h2\n  rw [update_reader,update_raw,update_valid] at h2\n  exact included_call program fieldStack Label.field field_injective Field.code (Field.active .tagPop (none,false))\n    (fun _=>rfl) (ctl .parse) (ctl .valid) rfl (8*key.length+6) start stop (view f r o) _ rfl rfl\n    (SemiprimeD1TensorTapeFieldBytecode.framed_run key tail []) hin h2\n/-- Actual true-valid pop completes the raw-key read and preserves every other physical word, including OLD-j. -/\ntheorem parse_run (f:W.Words) (r:R.Stack→List Bool) (o:O.Stack→List Bool) (key tail:List Bool)\n    (hr:f.reader=frame key tail) (ho:f.raw=[]) (hs:f.fieldScratch=[]) (hv:f.valid=[]):\n    Runs program (8*key.length+8) (ctl .parse) (view f r o) (ctl .encodeClass)\n      (view {f with reader:=tail,raw:=key,valid:=[]} r o) :=by\n  have h0:=field_run f r o key tail hr ho hs hv\n  have h1:=pop_run .valid (ctl .abort) (ctl .abort) (ctl .encodeClass) (lookupStack (.inr .valid))\n    (view {f with reader:=tail,raw:=key,valid:=[true]} r o) [true] rfl rfl\n  change Runs program 1 _ _ _ (Function.update (view {f with reader:=tail,raw:=key,valid:=[true]} r o)\n    (frequencyStack (F.lookupStack (.inr .valid))) []) at h1\n  rw [update_valid] at h1\n  have h:=join h0 h1\n  simpa only [Nat.add_assoc,SemiprimeD1StackBytecode.choose,List.head?_cons] using h\nend RiemannGaussian.SemiprimeD1StackPacketInventoryStream\n","RiemannGaussian.SemiprimeD1StackPacketRowsFinish":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPacketRowsRowView\nimport RiemannGaussian.SemiprimeD1StackPacketRowsEncoding\n/-! # Both actual history reversals produce chronological colour vectors\nHistories are physically consumed, and the originally pushed false vector\nterminators remain the actual output tails. No native reverse-vector answer is\nan input or opcode of the source.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPacketRowsFinish\nopen SemiprimeD1StackPacketRows SemiprimeD1StackPacketRowsPrimitives SemiprimeD1StackPacketRowsRowView\nopen SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => Label.local\n/-- Both complete real reversal calls preserve the original inputs and clear their actual histories. -/\ntheorem finish_run (key catalogue:List Bool) (histories:Bool→List Bool) :\n    Runs program (2*(histories false).length+2*(histories true).length+6) (ctl .reverseLeft)\n      (rowView key catalogue (fun _=>[]) (fun _=>[]) histories (fun _=>[false]) [])\n      (ctl .accept)\n      (rowView key catalogue (fun _=>[]) (fun _=>[]) (fun _=>[])\n        (fun side=>(histories side).reverse++[false]) []) :=by\n  have h0:=reverse_call (.finish false) .reverseLeft .reverseRight rfl\n    (rowView key catalogue (fun _=>[]) (fun _=>[]) histories (fun _=>[false]) []) (histories false) [false] rfl rfl\n  change Runs program _ _ _ _ (Function.update (Function.update\n    (rowView key catalogue (fun _=>[]) (fun _=>[]) histories (fun _=>[false]) [])\n    (history false) []) (output false) ((histories false).reverse++[false])) at h0\n  rw [update_histories,update_outputs] at h0\n  let midHistories:=Function.update histories false []\n  let midOutputs:=Function.update (fun _ :Bool=>[false]) false ((histories false).reverse++[false])\n  have h1:=reverse_call (.finish true) .reverseRight .accept rfl\n    (rowView key catalogue (fun _=>[]) (fun _=>[]) midHistories midOutputs []) (histories true) [false] rfl rfl\n  change Runs program _ _ _ _ (Function.update (Function.update\n    (rowView key catalogue (fun _=>[]) (fun _=>[]) midHistories midOutputs [])\n    (history true) []) (output true) ((histories true).reverse++[false])) at h1\n  rw [update_histories,update_outputs] at h1\n  have hh:Function.update midHistories true []=(fun _ :Bool=>[]) :=by funext side;cases side <;> rfl\n  have ho:Function.update midOutputs true ((histories true).reverse++[false])=\n      (fun side=>(histories side).reverse++[false]):=by funext side;cases side <;> rfl\n  rw [hh,ho] at h1\n  have h:=join h0 h1\n  have ht:(2*(histories false).length+3)+(2*(histories true).length+3)=\n      2*(histories false).length+2*(histories true).length+6:=by omega\n  simpa only [ht] using h\nend RiemannGaussian.SemiprimeD1StackPacketRowsFinish\n","RiemannGaussian.SemiprimeD1StackPacketRowsMeaning":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPacketRowsEncoding\nimport RiemannGaussian.SemiprimeD1StackSourceAlphabet64Original\n/-! # Exact original catalogue meanings for the actual numeric two-ID reader\nOnly proofs mention the original bank and dictionary. The source still has two\nphysical words, with no coordinate count or finite-word getter operand.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPacketRowsMeaning\nopen SemiprimeD1StackPacketRowsEncoding\nopen SemiprimeBitArithmetic (bitValue)\nopen SemiprimeSourceCompactBits (Compact)\nnamespace Rows\nexport SemiprimeSourceHistogramRows (Row layout expected expected_mem original_pair original_nodup)\nend Rows\nnamespace Map\nexport SemiprimeD1StackOwnerLookup (result records)\nend Map\n/-- Literal catalogue conversion retains each original key and encoded row. -/\ndef entries (pairs:List (List Bool×Rows.Row)) :List (List Bool×List Bool) :=\n  pairs.map (fun p=>(p.1,Rows.layout p.2))\n/-- Numeric first-match equality agrees with the original byte-key trie on actual compact IDs. -/\ntheorem lookup_expected (pairs:List (List Bool×Rows.Row)) (q:List Bool) (hq:Compact q)\n    (hc:∀p∈pairs,Compact p.1) :\n    (Map.result q (entries pairs) []).1=Rows.expected pairs q :=by\n  induction pairs with\n  | nil=>rfl\n  | cons p ps ih=>\n    rcases p with ⟨k,v⟩\n    have hk:=hc (k,v) (List.mem_cons_self)\n    have he:(bitValue k=bitValue q) ↔ q=k:=by\n      constructor\n      · intro h;exact (SemiprimeSourceCompactWordIds.compact_value_injective k q hk hq h).symm\n      · intro h;rw [h]\n    simp only [entries,List.map_cons,Map.result,Rows.expected,he]\n    split_ifs\n    · rfl\n    · exact ih (fun p hp=>hc p (List.mem_cons_of_mem _ hp))\n/-- Actual catalogue membership implies a successful physical presence peek, even for empty payloads. -/\ntheorem present_mem (rows:List (List Bool×List Bool)) (q value:List Bool) (hm:(q,value)∈rows) :\n    present q rows=true :=by\n  induction rows with\n  | nil=>simp at hm\n  | cons p ps ih=>\n    rcases p with ⟨k,v⟩\n    simp only [present]\n    split_ifs with h\n    · rfl\n    · rcases List.mem_cons.mp hm with he|he\n      · cases he;exact (h rfl).elim\n      · exact ih he\n/-- Encoding rows commutes with the original exact paired inventory. -/\ntheorem entries_zip (ids:List (List Bool)) (rows:List Rows.Row) :\n    entries (ids.zip rows)=ids.zip (rows.map Rows.layout) :=by\n  induction ids generalizing rows with\n  | nil=>rfl\n  | cons id ids ih=>cases rows with\n    | nil=>rfl\n    | cons row rows=>simp only [List.zip_cons_cons,entries,List.map_cons];rw [←entries,ih]\n/-- Original complete radix bank represented by the source's physical catalogue. -/\ndef originalEntries (r a:Nat) :List (List Bool×List Bool) :=\n  entries ((SemiprimeSourceCompactWordBank.acquire r a).ids.zip\n    (SemiprimeSourceCompactWordBank.acquire r a).rows)\n/-- Exact original palette fields physically serialized by the original bank row. -/\ndef fields (r a:Nat) (id:List Bool) :List (List Bool) :=\n  (SemiprimeSourceWordBank.readRow (SemiprimeSourceCompactWordBank.acquire r a) id).value.map\n    (fun x=>(SemiprimeSourceCompactBits.trim x.numerator.magnitude).bits)\n/-- Both the actual lookup payload and the physical unread-reader presence witness come from the original acquired row. -/\ntheorem original_lookup (r a:Nat) [NeZero r] (id:List Bool)\n    (hi:id∈(SemiprimeSourceCompactWordBank.acquire r a).ids) :\n    (Map.result id (originalEntries r a) []).1=SemiprimeD1PacketRows.serialize (fields r a id) ∧\n      present id (originalEntries r a)=true ∧ (fields r a id).length=a :=by\n  let pairs:=(SemiprimeSourceCompactWordBank.acquire r a).ids.zip\n    (SemiprimeSourceCompactWordBank.acquire r a).rows\n  have hc:∀p∈pairs,Compact p.1:=by\n    intro p hp\n    apply SemiprimeSourceCompactWordBank.ids_compact r a p.1\n    exact (List.of_mem_zip hp).1\n  have hp:=Rows.original_pair r a id hi\n  have he:=lookup_expected pairs id (SemiprimeSourceCompactWordBank.ids_compact r a id hi) hc\n  rw [Rows.expected_mem _ _ _ (Rows.original_nodup r a) hp] at he\n  refine ⟨?_,?_,?_⟩\n  · change _=SemiprimeD1PacketRows.serialize\n      ((SemiprimeSourceWordBank.readRow (SemiprimeSourceCompactWordBank.acquire r a) id).value.map _)\n    rw [SemiprimeD1PacketRows.serialize_row]\n    exact he\n  · exact present_mem _ id _ (List.mem_map.mpr ⟨_,hp,rfl⟩)\n  · exact (List.length_map ..).trans (SemiprimeSourceCompactWordBank.readRow_length r a id hi)\n/-- The no-count physical reader and the old fixed-width parser produce the identical fields. -/\ntheorem fields_original (r a:Nat) [NeZero r] (id:List Bool)\n    (hi:id∈(SemiprimeSourceCompactWordBank.acquire r a).ids) :\n    fields r a id=(SemiprimeD1PacketRows.parse a (SemiprimeSourceHistogramRows.readRow\n      (SemiprimeSourceHistogramRows.acquire r a) id).bits).fields :=by\n  rw [SemiprimeSourceHistogramRows.lookup_original r a id hi,SemiprimeSourceHistogramRows.encodeRow_bits]\n  have hp:=SemiprimeD1PacketRows.parse_row\n    (SemiprimeSourceWordBank.readRow (SemiprimeSourceCompactWordBank.acquire r a) id).value\n  rw [SemiprimeSourceCompactWordBank.readRow_length r a id hi] at hp\n  exact hp.1.symm\n/-- Catalogue output is precisely the actually executed frozen alphabet source's stopped word. -/\ntheorem catalogue_original (a:Nat) :\n    SemiprimeD1StackOwnerLookup.records (originalEntries 64 a) []=\n      SemiprimeD1StackSourceAlphabet64Encoding.result a (SemiprimeD1StackSourceAlphabet64.aux .output) :=by\n  rw [SemiprimeD1StackSourceAlphabet64Original.output_original]\n  rw [originalEntries,entries_zip]\n  rfl\nend RiemannGaussian.SemiprimeD1StackPacketRowsMeaning\n","RiemannGaussian.SemiprimeD1StackPacketRowsPrepare":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPacketRowsView\n/-! # Real joint-key copy and one owner-ID Field parse\nThe factor ID is the physically unconsumed raw tail, never a second framed\nfield or supplied decoded ID. Both original input words remain retained.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPacketRowsPrepare\nopen SemiprimeD1StackPacketRows SemiprimeD1StackPacketRowsPrimitives SemiprimeD1StackPacketRowsView\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\nlocal notation \"ctl\" => Label.local\n/-- Exactly the two input words are supplied before any physical seed/copy/parser stage. -/\ntheorem initial_data (key catalogue:List Bool) :\n    (initial key catalogue).data=view key catalogue [] [] [] [] [] [] [] [] [] [] [] [] [] [] :=by\n  funext k\n  rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · cases k <;> rfl\n/-- True actual key front-end, including both empty-vector seeds, the preserving copy and actual valid-byte pop. -/\ntheorem prepare_run (owner factor catalogue:List Bool) :\n    Runs program (5*(frame owner factor).length+8*owner.length+14) (ctl .start)\n      (initial (frame owner factor) catalogue).data (ctl (.copyMenu false))\n      (view (frame owner factor) catalogue factor [] [] owner [] [] [] [] [] [] [] [] [false] [false]) :=by\n  rw [initial_data]\n  have h0:=push_run .start (ctl .seedRight) (output false) false\n    (view (frame owner factor) catalogue [] [] [] [] [] [] [] [] [] [] [] [] [] []) rfl\n  change Runs program 1 _ _ _ (Function.update\n    (view (frame owner factor) catalogue [] [] [] [] [] [] [] [] [] [] [] [] [] []) (output false) [false]) at h0\n  rw [update_leftOutput] at h0\n  have h1:=push_run .seedRight (ctl .copyKey) (output true) false\n    (view (frame owner factor) catalogue [] [] [] [] [] [] [] [] [] [] [] [] [false] []) rfl\n  change Runs program 1 _ _ _ (Function.update\n    (view (frame owner factor) catalogue [] [] [] [] [] [] [] [] [] [] [] [] [false] []) (output true) [false]) at h1\n  rw [update_rightOutput] at h1\n  have h2:=copy_call .key .copyKey .parseKey rfl\n    (view (frame owner factor) catalogue [] [] [] [] [] [] [] [] [] [] [] [] [false] [false]) (frame owner factor) [] rfl rfl rfl\n  change Runs program _ _ _ _ (Function.update\n    (view (frame owner factor) catalogue [] [] [] [] [] [] [] [] [] [] [] [] [false] [false]) (aux .keyReader) (frame owner factor++[])) at h2\n  rw [List.append_nil,update_keyReader] at h2\n  have h3:=field_valid .owner .parseKey .keyValid (ctl (.copyMenu false)) rfl rfl\n    (view (frame owner factor) catalogue (frame owner factor) [] [] [] [] [] [] [] [] [] [] [] [false] [false]) owner factor rfl rfl rfl rfl\n  change Runs program _ _ _ _ (Function.update (Function.update\n    (view (frame owner factor) catalogue (frame owner factor) [] [] [] [] [] [] [] [] [] [] [] [false] [false])\n    (aux .keyReader) factor) query owner) at h3\n  rw [update_keyReader,update_queryWord] at h3\n  have h:=join (join (join h0 h1) h2) h3\n  have ht:1+1+(5*(frame owner factor).length+4)+(8*owner.length+8)=5*(frame owner factor).length+8*owner.length+14:=by omega\n  simpa only [ht] using h\nend RiemannGaussian.SemiprimeD1StackPacketRowsPrepare\n","RiemannGaussian.SemiprimeD1StackPhaseCacheFreshComponents":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPhaseCacheFresh\n/-! # Actual alias-preserving heap restore and P48-cache fresh calls -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPhaseCacheFreshComponents\nopen SemiprimeD1StackPhaseCacheFresh SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => (Sum.inl : Control→Label)\n/-- Exact actual phase cache previously acquired and serialized by the producer. -/\ndef phase (a u edges:Nat) (t p:List Bool) :P.Stack→List Bool :=\n  SemiprimeD1StackPhaseWorkingPrecisionComponents.result a u edges t p\n/-- Real heap/48field result installs the selected literal bank through the shared48alias. -/\ndef after (bank:P.Stack→List Bool) (heap counter reference axes:List Bool) :Stack→List Bool :=\n  data (Heap.input heap counter reference) (freshReadyBank bank axes)\n/-- Exact fresh whole cache/output, original heap/counter/reference retained and all48shadowsEMPTY. -/\ndef completed (a u edges:Nat) (t p:List Bool) (axes:List Nat) (heap counter reference:List Bool) :Stack→List Bool :=\n  data (Heap.input heap counter reference) (SemiprimeD1StackPhaseChildContextFreshComponents.result a u edges t p axes)\n/-- Every actual included Fresh role directly views the corresponding real shared/private word. -/\ntheorem fresh_data (heap:Heap.Stack→List Bool) (fresh:F.Stack→List Bool) (k:F.Stack) :\n    data heap fresh (freshStack k)=fresh k :=by\n  rcases k with k|k\n  · rcases k with k|k <;> rfl\n  · rfl\n/-- Empty physical P48 shadow slots do not depend on the restored cache's mathematical interpretation. -/\ntheorem private_ready (bank:P.Stack→List Bool) (axes:List Bool) :\n    privateView (freshReadyBank bank axes)=privateView (freshReadyBank (fun _=>[]) axes) :=by\n  funext k\n  rcases k with k|k\n  · rcases k with k|k <;> rfl\n  · rfl\n/-- Actual P48cache ready source is exactly the restored-bank plus actual old-header projection. -/\ntheorem fresh_ready_eq (a u edges:Nat) (t p axes:List Bool) :\n    freshReadyBank (phase a u edges t p) axes=(SemiprimeD1StackPhaseChildContextFresh.phaseReady a u edges t p axes).data :=rfl\n/-- Actual chronological real-call composition retains arbitrary real caller frames. -/\ntheorem join {m n:Nat} {pc mid finish:Label} {before between after:Stack→List Bool}\n    (h:Runs program m pc before mid between) (g:Runs program n mid between finish after) :\n    Runs program (m+n) pc before finish after :=runs_trans program m n pc mid finish before between after h g\n/-- The entire REAL58-role dereference/restore source executes, preserving the old-header/private bank. -/\ntheorem restore_call (banks:List (P.Stack→List Bool)) (i:Fin banks.length) (axes:List Bool) :\n    ∃q≤ SemiprimeD1StackPhaseBankRestoreExecution.runBound banks i+1,\n      Runs program q (ctl .start)\n        (input (SemiprimeD1StackHeapAllocate.heapBytes (SemiprimeD1StackPhaseBankRestoreExecution.records banks))\n          (List.replicate banks.length true) (List.replicate i.val true) axes)\n        (ctl .fresh)\n        (after banks[i.val] (SemiprimeD1StackHeapAllocate.heapBytes (SemiprimeD1StackPhaseBankRestoreExecution.records banks))\n          (List.replicate banks.length true) (List.replicate i.val true) axes) :=by\n  obtain ⟨q,hq,hr⟩:=SemiprimeD1StackPhaseBankRestoreExecution.source_run banks i\n  refine ⟨q+1,by omega,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program restoreStack restoreLabel restore_injective\n    R.program (.inl .start) (fun _=>rfl) (ctl .start) (ctl .fresh) rfl q\n    (SemiprimeD1StackPhaseBankRestoreExecution.source banks i) (SemiprimeD1StackPhaseBankRestoreExecution.target banks i)\n    _ _ rfl rfl rfl rfl hr\n  · constructor\n    · intro k;rcases k with k|k <;> rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rcases k with k|k <;> rfl\n    · intro k hk\n      rcases k with k|k\n      · exact (hk k rfl).elim\n      · exact congrFun (private_ready banks[i.val] axes) k\n/-- REAL Fresh.phaseReady consumes the directly aliased restored48cache; no geometry/P source reruns. -/\ntheorem fresh_call (a u edges:Nat) (t p:List Bool) (axes:List Nat) (hp:∀x∈axes,0<x) (heap counter reference:List Bool) :\n    ∃q≤ SemiprimeD1StackPhaseChildContextFreshExecution.phaseReadyBound a u edges t p axes+1,\n      Runs program q (ctl .fresh)\n        (after (phase a u edges t p) heap counter reference (SemiprimeD1StackPhaseChildContextPrimitives.header axes))\n        (ctl .done) (completed a u edges t p axes heap counter reference) :=by\n  obtain ⟨q,hq,hr⟩:=SemiprimeD1StackPhaseChildContextFreshExecution.phase_ready_run a u edges t p axes hp\n  refine ⟨q+1,by omega,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program freshStack freshLabel fresh_injective\n    F.program .phaseReady (fun _=>rfl) (ctl .fresh) (ctl .done) rfl q\n    (SemiprimeD1StackPhaseChildContextFresh.phaseReady a u edges t p (SemiprimeD1StackPhaseChildContextPrimitives.header axes))\n    (SemiprimeD1StackPhaseChildContextFreshExecution.done a u edges t p axes) _ _ rfl rfl rfl rfl hr\n  · constructor\n    · intro k\n      exact fresh_data _ _ k\n    · intro k _;rfl\n  · constructor\n    · intro k\n      exact fresh_data _ _ k\n    · intro k hk\n      rcases k with k|k\n      · rcases k with k|k\n        · exact (hk (F.contextStack (H.phaseStack k)) rfl).elim\n        · rfl\n      · rcases k with k|k\n        · rcases k with k|k\n          · rfl\n          · exact (hk (.inl (.inr k)) rfl).elim\n        · exact (hk (.inr k) rfl).elim\nend RiemannGaussian.SemiprimeD1StackPhaseCacheFreshComponents\n","RiemannGaussian.SemiprimeD1StackPhaseChildContextFreshBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPhaseChildContextFreshExecution\n/-! # Own whole/ready clocks and ALL85 physical roles plus actual returns\nRank and precision VALUE materialization remains explicitly charged by the\noriginal context resource. There is no polynomial-in-binary-precision-bytes claim.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option synthInstance.maxSize 8192\nset_option maxRecDepth 32768\nset_option maxHeartbeats 2400000\nnamespace RiemannGaussian.SemiprimeD1StackPhaseChildContextFreshBounds\nopen SemiprimeD1StackPhaseChildContextFresh SemiprimeD1StackPhaseChildContextFreshComponents\nopen SemiprimeD1StackPhaseChildContextFreshExecution\n/-- Exact original VALUE-charged context resource, including both ranks and precision widths. -/\nabbrev resource :=SemiprimeD1StackPhaseChildContextBounds.resource\n/-- Both actual rank VALUES are already included in the honest context resource. -/\ntheorem ranks_bound (a u edges : Nat) (t p : List Bool) (axes : List Nat) :\n    rank a u edges t axes+axes.prod+1≤ resource a u edges t p axes+1 :=by\n  unfold resource SemiprimeD1StackPhaseChildContextBounds.resource SemiprimeD1StackJetContextBounds.resource rank\n  omega\n/-- Complete cache-ready allocation clock is linear in the original VALUE-charged inventory. -/\ntheorem ready_polynomial (a u edges : Nat) (t p : List Bool) (axes : List Nat) :\n    readyBound a u edges t axes≤ 100*(resource a u edges t p axes+1) :=by\n  have h:=ranks_bound a u edges t p axes\n  unfold readyBound\n  split <;> omega\n/-- Whole-source cost sums the real original phase/context pipeline and all fresh-vector bytes. -/\ntheorem run_polynomial (a u edges : Nat) (t p : List Bool) (axes : List Nat) (hp : ∀x∈axes,0<x) :\n    runBound a u edges t p axes≤ 1000000000000000000*(resource a u edges t p axes+1)^4 :=by\n  have h0:=SemiprimeD1StackPhaseChildContextBounds.run_polynomial a u edges t p axes hp\n  change _≤ 1000000000000000*(resource a u edges t p axes+1)^4 at h0\n  have h1:=ready_polynomial a u edges t p axes\n  have hz:resource a u edges t p axes+1≤(resource a u edges t p axes+1)^4:=Nat.le_pow (by decide : 0<(4:Nat))\n  unfold runBound\n  omega\n/-- P48-cache entry pays real old/new context VALUE expansion and complete allocation. -/\ntheorem phase_ready_polynomial (a u edges : Nat) (t p : List Bool) (axes : List Nat) (hp : ∀x∈axes,0<x) :\n    phaseReadyBound a u edges t p axes≤ 1000000000*(resource a u edges t p axes+1)^2 :=by\n  have h0:=SemiprimeD1StackPhaseChildContextBounds.ready_polynomial a u edges t p axes hp\n  change _≤ 1000000*(resource a u edges t p axes+1)^2 at h0\n  have h1:=ready_polynomial a u edges t p axes\n  have hz:resource a u edges t p axes+1≤(resource a u edges t p axes+1)^2:=Nat.le_pow (by decide : 0<(2:Nat))\n  unfold phaseReadyBound\n  omega\n/-- Whole initial inventory contains no context/rank/q/P/vector answers. -/\ntheorem initial_bound (a u edges : Nat) (t p : List Bool) (axes : List Nat) (k : Stack) :\n    ((initial a u edges t p (Old.header axes)).data k).length≤ edges+a+u+t.length+p.length+(Old.header axes).length :=by\n  rcases k with k|k\n  · exact SemiprimeD1StackPhaseChildContextBounds.initial_bound a u edges t p axes k\n  · cases k <;> exact Nat.zero_le _\n/-- Every retained80-role context-cache cell is bounded from its ACTUAL whole original source. -/\ntheorem cache_bound (a u edges : Nat) (t p : List Bool) (axes : List Nat) (hp : ∀x∈axes,0<x) (k : H.Stack) :\n    (cache a u edges t p axes k).length≤ edges+a+u+t.length+p.length+(Old.header axes).length+\n      SemiprimeD1StackPhaseChildContextExecution.runBound a u edges t p axes :=by\n  obtain ⟨q,hq,hr⟩:=SemiprimeD1StackPhaseChildContextExecution.source_run a u edges t p axes hp\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound H.program q\n    (edges+a+u+t.length+p.length+(Old.header axes).length) _ _\n    (SemiprimeD1StackPhaseChildContextBounds.initial_bound a u edges t p axes) hr\n  exact (hd k).trans (by omega)\n/-- Direct cache-ready entry retains every physically acquired context/P48 field. -/\ntheorem ready_initial_bound (a u edges : Nat) (t p : List Bool) (axes : List Nat) (hp : ∀x∈axes,0<x) (k : Stack) :\n    ((ready a u edges t p axes).data k).length≤ edges+a+u+t.length+p.length+(Old.header axes).length+\n      SemiprimeD1StackPhaseChildContextExecution.runBound a u edges t p axes :=by\n  rcases k with k|k\n  · exact cache_bound a u edges t p axes hp k\n  · cases k <;> exact Nat.zero_le _\n/-- P48-ready entry has only actual P48 cache and original oldheader, with both contexts unacquired. -/\ntheorem phase_ready_initial_bound (a u edges : Nat) (t p : List Bool) (axes : List Nat) (k : Stack) :\n    ((phaseReady a u edges t p (Old.header axes)).data k).length≤ edges+a+u+t.length+p.length+(Old.header axes).length+\n      SemiprimeD1StackPhaseWorkingPrecisionExecution.runBound a u edges t p :=by\n  rcases k with k|k\n  · exact SemiprimeD1StackPhaseChildContextBounds.ready_initial_bound a u edges t p axes k\n  · cases k <;> exact Nat.zero_le _\n/-- Successful prefixes stop at the actual halt; all allocated fields and real return cells count. -/\ntheorem inventory (start stop : C.State Stack Label) (B cap fuel : Nat) (out : C.State Stack Label)\n    (hi : ∀k,(start.data k).length≤ B) (hf : start.frames=[])\n    (hh : ∃q≤ cap,SemiprimeD1StackCalls.run program q start=some stop) (hs : stop.pc=none)\n    (hr : SemiprimeD1StackCalls.run program fuel start=some out) :\n    (∑k:Stack,(out.data k).length)+out.frames.length≤ 86*(B+cap+1) :=by\n  obtain ⟨q,hq,hstop⟩:=hh\n  have ht:fuel≤ q:=by\n    by_contra hn\n    have he:fuel=q+(1+(fuel-(q+1))):=by omega\n    rw [he,SemiprimeD1StackReturnLink.run_add,hstop,Option.bind_some,SemiprimeD1StackReturnLink.run_add] at hr\n    have hz:SemiprimeD1StackCalls.run program 1 stop=none:=by cases stop with | mk pc flag ret data frames=>cases hs;rfl\n    rw [hz,Option.bind_none] at hr\n    cases hr\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel B start out hi hr\n  have hframes:=SemiprimeD1StackCalls.run_frame_bound program fuel start out hr\n  rw [hf,List.length_nil] at hframes\n  have hsum:(∑k:Stack,(out.data k).length)≤ 85*(B+fuel):=by\n    calc\n      _≤∑_k:Stack,(B+fuel):=Finset.sum_le_sum (fun k _=>hd k)\n      _=_:=by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  omega\n/-- Every whole-source prefix charges ALL85 roles and real returns, including both context expansions. -/\ntheorem prefix_cells (a u edges : Nat) (t p : List Bool) (axes : List Nat) (hp : ∀x∈axes,0<x)\n    (fuel : Nat) (out : C.State Stack Label)\n    (hr : SemiprimeD1StackCalls.run program fuel (initial a u edges t p (Old.header axes))=some out) :\n    (∑k:Stack,(out.data k).length)+out.frames.length≤ 1000000000000000000000*(resource a u edges t p axes+1)^4 :=by\n  have h0:=inventory _ (done a u edges t p axes) _ _ fuel out (initial_bound a u edges t p axes) rfl (source_run a u edges t p axes hp) rfl hr\n  have ht:=run_polynomial a u edges t p axes hp\n  have hi:edges+a+u+t.length+p.length+(Old.header axes).length≤ resource a u edges t p axes+1:=by\n    unfold resource SemiprimeD1StackPhaseChildContextBounds.resource SemiprimeD1StackJetContextBounds.resource Old.header\n    omega\n  have hz:resource a u edges t p axes+1≤(resource a u edges t p axes+1)^4:=Nat.le_pow (by decide : 0<(4:Nat))\n  omega\n/-- Direct context-ready prefixes count ALL retained cache words plus every fresh allocator role/return. -/\ntheorem ready_prefix_cells (a u edges : Nat) (t p : List Bool) (axes : List Nat) (hp : ∀x∈axes,0<x)\n    (fuel : Nat) (out : C.State Stack Label)\n    (hr : SemiprimeD1StackCalls.run program fuel (ready a u edges t p axes)=some out) :\n    (∑k:Stack,(out.data k).length)+out.frames.length≤ 1000000000000000000000*(resource a u edges t p axes+1)^4 :=by\n  have h0:=inventory _ (done a u edges t p axes) _ _ fuel out (ready_initial_bound a u edges t p axes hp) rfl (ready_run a u edges t p axes) rfl hr\n  have ht:=ready_polynomial a u edges t p axes\n  have hc:=SemiprimeD1StackPhaseChildContextBounds.run_polynomial a u edges t p axes hp\n  change _≤ 1000000000000000*(resource a u edges t p axes+1)^4 at hc\n  have hi:edges+a+u+t.length+p.length+(Old.header axes).length≤ resource a u edges t p axes+1:=by\n    unfold resource SemiprimeD1StackPhaseChildContextBounds.resource SemiprimeD1StackJetContextBounds.resource Old.header\n    omega\n  have hz:resource a u edges t p axes+1≤(resource a u edges t p axes+1)^4:=Nat.le_pow (by decide : 0<(4:Nat))\n  omega\n/-- P48-ready prefixes include the actual old/new context acquisitions and every physical field/return. -/\ntheorem phase_ready_prefix_cells (a u edges : Nat) (t p : List Bool) (axes : List Nat) (hp : ∀x∈axes,0<x)\n    (fuel : Nat) (out : C.State Stack Label)\n    (hr : SemiprimeD1StackCalls.run program fuel (phaseReady a u edges t p (Old.header axes))=some out) :\n    (∑k:Stack,(out.data k).length)+out.frames.length≤ 1000000000000000000000*(resource a u edges t p axes+1)^4 :=by\n  have h0:=inventory _ (done a u edges t p axes) _ _ fuel out (phase_ready_initial_bound a u edges t p axes) rfl (phase_ready_run a u edges t p axes hp) rfl hr\n  have ht:=phase_ready_polynomial a u edges t p axes hp\n  have hi:edges+a+u+t.length+p.length+(Old.header axes).length≤ resource a u edges t p axes+1:=by\n    unfold resource SemiprimeD1StackPhaseChildContextBounds.resource SemiprimeD1StackJetContextBounds.resource Old.header\n    omega\n  have hI:edges+a+u+t.length+p.length+1≤ resource a u edges t p axes+1:=by unfold resource SemiprimeD1StackPhaseChildContextBounds.resource;omega\n  have hpow:(edges+a+u+t.length+p.length+1)^4≤(resource a u edges t p axes+1)^4:=by gcongr\n  have hs2:(resource a u edges t p axes+1)^2≤(resource a u edges t p axes+1)^4:=by\n    calc\n      _≤((resource a u edges t p axes+1)^2)^2:=Nat.le_pow (by decide : 0<(2:Nat))\n      _=_:=by ring\n  have hz:resource a u edges t p axes+1≤(resource a u edges t p axes+1)^4:=Nat.le_pow (by decide : 0<(4:Nat))\n  unfold SemiprimeD1StackPhaseWorkingPrecisionExecution.runBound at h0\n  omega\n/-- SAME all85/real-return bound for every actual compiled whole prefix. -/\ntheorem machine_prefix_cells (a u edges : Nat) (t p : List Bool) (axes : List Nat) (hp : ∀x∈axes,0<x)\n    (fuel : Nat) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel] (some (SemiprimeD1StackCalls.configuration (initial a u edges t p (Old.header axes))))=some cfg) :\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤ 1000000000000000000000*(resource a u edges t p axes+1)^4 :=by\n  have he:=SemiprimeD1StackCalls.run_correct (contextStack (H.oldStack H.J.axesCache)) (aux .output) .start program fuel (initial a u edges t p (Old.header axes))\n  change (SemiprimeD1StackCalls.run program fuel (initial a u edges t p (Old.header axes))).map SemiprimeD1StackCalls.configuration=\n    (fun q=>q.bind machine.step)^[fuel] (some (SemiprimeD1StackCalls.configuration (initial a u edges t p (Old.header axes)))) at he\n  have hh:=he.trans hr\n  cases hc:SemiprimeD1StackCalls.run program fuel (initial a u edges t p (Old.header axes)) with\n  | none=>rw [hc] at hh;cases hh\n  | some out=>\n    rw [hc] at hh\n    have hcfg:SemiprimeD1StackCalls.configuration out=cfg:=Option.some.inj hh\n    subst cfg\n    exact prefix_cells a u edges t p axes hp fuel out hc\n/-- SAME all85/real-return bound for every actual compiled ready_ prefix. -/\ntheorem ready_machine_prefix_cells (a u edges : Nat) (t p : List Bool) (axes : List Nat) (hp : ∀x∈axes,0<x)\n    (fuel : Nat) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel] (some (SemiprimeD1StackCalls.configuration (ready a u edges t p axes)))=some cfg) :\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤ 1000000000000000000000*(resource a u edges t p axes+1)^4 :=by\n  have he:=SemiprimeD1StackCalls.run_correct (contextStack (H.oldStack H.J.axesCache)) (aux .output) .start program fuel (ready a u edges t p axes)\n  change (SemiprimeD1StackCalls.run program fuel (ready a u edges t p axes)).map SemiprimeD1StackCalls.configuration=\n    (fun q=>q.bind machine.step)^[fuel] (some (SemiprimeD1StackCalls.configuration (ready a u edges t p axes))) at he\n  have hh:=he.trans hr\n  cases hc:SemiprimeD1StackCalls.run program fuel (ready a u edges t p axes) with\n  | none=>rw [hc] at hh;cases hh\n  | some out=>\n    rw [hc] at hh\n    have hcfg:SemiprimeD1StackCalls.configuration out=cfg:=Option.some.inj hh\n    subst cfg\n    exact ready_prefix_cells a u edges t p axes hp fuel out hc\n/-- SAME all85/real-return bound for every actual compiled phase_ready_ prefix. -/\ntheorem phase_ready_machine_prefix_cells (a u edges : Nat) (t p : List Bool) (axes : List Nat) (hp : ∀x∈axes,0<x)\n    (fuel : Nat) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel] (some (SemiprimeD1StackCalls.configuration (phaseReady a u edges t p (Old.header axes))))=some cfg) :\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤ 1000000000000000000000*(resource a u edges t p axes+1)^4 :=by\n  have he:=SemiprimeD1StackCalls.run_correct (contextStack (H.oldStack H.J.axesCache)) (aux .output) .start program fuel (phaseReady a u edges t p (Old.header axes))\n  change (SemiprimeD1StackCalls.run program fuel (phaseReady a u edges t p (Old.header axes))).map SemiprimeD1StackCalls.configuration=\n    (fun q=>q.bind machine.step)^[fuel] (some (SemiprimeD1StackCalls.configuration (phaseReady a u edges t p (Old.header axes)))) at he\n  have hh:=he.trans hr\n  cases hc:SemiprimeD1StackCalls.run program fuel (phaseReady a u edges t p (Old.header axes)) with\n  | none=>rw [hc] at hh;cases hh\n  | some out=>\n    rw [hc] at hh\n    have hcfg:SemiprimeD1StackCalls.configuration out=cfg:=Option.some.inj hh\n    subst cfg\n    exact phase_ready_prefix_cells a u edges t p axes hp fuel out hc\nend RiemannGaussian.SemiprimeD1StackPhaseChildContextFreshBounds\n","RiemannGaussian.SemiprimeD1StackPhaseGeometry":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSubtractorExecution\nimport RiemannGaussian.SemiprimeD1StackProcedureTrace\nimport RiemannGaussian.SemiprimeD1StackPhysicalLoops\n/-! # Literal binary phase geometry and physical dyadic-order acquisition\nOnly the original unary exponent metadata and original binary grid index are\ninitially populated. Powers remain binary. The actual borrow chooses an exact\nabsolute subtraction, and a physical low-bit scan acquires the valuation.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackPhaseGeometry\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State)\nend C\nnamespace S\nexport SemiprimeD1StackAdder (Stack store)\nexport SemiprimeD1StackSubtractor (Label code state)\nend S\n/-- Ten physical original, acquired and copy/scan roles. -/\ninductive Aux where | exponent | index | counter | center | alpha | sign | zero | order | scan | scratch\n  deriving DecidableEq,Repr\ninstance : Fintype Aux :=Fintype.ofList [.exponent,.index,.counter,.center,.alpha,.sign,.zero,.order,.scan,.scratch]\n  (by intro k;cases k <;> simp)\n/-- Four real ripple-subtraction fields and ten explicit metadata fields. -/\nabbrev Stack :=S.Stack⊕Aux\n/-- The actual subtractor bank; its output is also the retained magnitude word. -/\ndef subStack : S.Stack→Stack :=Sum.inl\n/-- Literal metadata field inclusion. -/\ndef aux : Aux→Stack :=Sum.inr\n/-- Finite source control, with no exponent, point or valuation in a label. -/\ninductive Label where\n  | start | seed | power | shift | alphaCopy | alphaShift\n  | left (negative : Bool) | right (negative : Bool) | subtract (negative : Bool)\n  | readFirst | saveSign (negative : Bool) | clearWrapped | readSecond\n  | scanCopy | scan | increment | clearScan | clearOrder | saveZero (zero : Bool) | done\n  | copy (kind : Fin 7) (pc : Fin 9) | ripple (pc : S.Label)\n  deriving Fintype\n/-- Seven static preserving-copy source sites, independent of every input. -/\ndef copySource (kind : Fin 7) : Stack :=\n  if kind=0 then aux .exponent else if kind=1 then aux .center else if kind=2 then aux .index\n  else if kind=3 then aux .center else if kind=4 then aux .center else if kind=5 then aux .index\n  else subStack .output\n/-- Every operand is acquired by a real paid physical copy. -/\ndef copyTarget (kind : Fin 7) : Stack :=\n  if kind=0 then aux .counter else if kind=1 then aux .alpha else if kind=2 then subStack .left\n  else if kind=3 then subStack .right else if kind=4 then subStack .left else if kind=5 then subStack .right\n  else aux .scan\n/-- Actual scratch is disjoint from source and destination at all seven sites. -/\ndef copyStack (kind : Fin 7) (k : Fin 3) : Stack :=\n  if k=0 then copySource kind else if k=1 then copyTarget kind else aux .scratch\n/-- One fixed finite literal source for all exponent and index words. -/\ndef program : Label→C.Instruction Stack Label\n  | .start=>.call (.copy 0 0) .seed\n  | .seed=>.base (.push (aux .center) true .power)\n  | .power=>.base (.pop (aux .counter) .alphaCopy .shift .shift)\n  | .shift=>.base (.push (aux .center) false .power)\n  | .alphaCopy=>.call (.copy 1 0) .alphaShift\n  | .alphaShift=>.base (.push (aux .alpha) false (.left false))\n  | .left negative=>.call (.copy (if negative then 4 else 2) 0) (.right negative)\n  | .right negative=>.call (.copy (if negative then 5 else 3) 0) (.subtract negative)\n  | .subtract negative=>.call (.ripple (.start false)) (if negative then .readSecond else .readFirst)\n  | .readFirst=>.base (.pop (subStack .output) (.saveSign false) (.saveSign false) (.saveSign true))\n  | .saveSign negative=>.base (.push (aux .sign) negative (if negative then .clearWrapped else .scanCopy))\n  | .clearWrapped=>.base (.pop (subStack .output) (.left true) .clearWrapped .clearWrapped)\n  | .readSecond=>.base (.pop (subStack .output) .scanCopy .scanCopy .scanCopy)\n  | .scanCopy=>.call (.copy 6 0) .scan\n  | .scan=>.base (.pop (aux .scan) .clearOrder .increment .clearScan)\n  | .increment=>.base (.push (aux .order) true .scan)\n  | .clearScan=>.base (.pop (aux .scan) (.saveZero false) .clearScan .clearScan)\n  | .clearOrder=>.base (.pop (aux .order) (.saveZero true) .clearOrder .clearOrder)\n  | .saveZero zero=>.base (.push (aux .zero) zero .done)\n  | .done=>.base .halt\n  | .copy kind pc=>SemiprimeD1StackMultiplierLink.instruction (copyStack kind) (Label.copy kind)\n      (SemiprimeD1StackCopy.code pc)\n  | .ripple pc=>SemiprimeD1StackMultiplierLink.instruction subStack Label.ripple (S.code pc)\n/-- Exact physical bank view, with no native arithmetic object in the runtime. -/\ndef store (sub : S.Stack→List Bool) (metadata : Aux→List Bool) : Stack→List Bool :=Sum.elim sub metadata\n/-- Explicit metadata role words. -/\ndef words (exponent index counter center alpha sign zero order scan scratch : List Bool) : Aux→List Bool\n  | .exponent=>exponent | .index=>index | .counter=>counter | .center=>center | .alpha=>alpha\n  | .sign=>sign | .zero=>zero | .order=>order | .scan=>scan | .scratch=>scratch\n/-- Only caller exponent and index words exist at the source front door. -/\ndef input (exponent index : List Bool) : Stack→List Bool :=\n  store (S.store [] [] [] []) (words exponent index [] [] [] [] [] [] [] [])\n/-- Two original physical operands, with every work/output/flag/return field empty. -/\ndef initial (exponent index : List Bool) : C.State Stack Label :=⟨some .start,none,none,input exponent index,[]⟩\n/-- Genuine finite machine; its paired physical-input initialization is explicit. -/\ndef machine : Turing.FinTM2 :=SemiprimeD1StackCalls.machine (aux .exponent) (subStack .output) .start program\n/-- Every one of the fourteen allocated roles is counted. -/\ntheorem stack_card : Fintype.card Stack=14 :=by rw [Fintype.card_sum];decide\n/-- Actual subtraction uses four distinct physical fields. -/\ntheorem sub_injective : Function.Injective subStack :=Sum.inl_injective\n/-- Every included copy restores its original physical operand. -/\ntheorem copy_injective (kind : Fin 7) : Function.Injective (copyStack kind) :=by fin_cases kind <;> decide\n/-- Internal control is fixed finite before all exponent/index operands. -/\ntheorem control_finite : Finite machine.σ :=SemiprimeD1StackCalls.control_finite _ _ _ _\n/-- All fourteen payload alphabets and the real return alphabet are finite. -/\ntheorem alphabets_finite (k : machine.K) : Finite (machine.Γ k) :=SemiprimeD1StackCalls.all_alphabets_finite _ _ _ _ k\nend RiemannGaussian.SemiprimeD1StackPhaseGeometry\n","RiemannGaussian.SemiprimeD1StackPhaseGeometryGuardBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPhaseGeometryGuardExecution\n/-! # All21 physical roles and every actual geometry/guard return cell -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1000000\nnamespace RiemannGaussian.SemiprimeD1StackPhaseGeometryGuardBounds\nopen SemiprimeD1StackPhaseGeometryGuard SemiprimeD1StackPhaseGeometryGuardComponents\nopen SemiprimeD1StackPhaseGeometryGuardExecution\n/-- Successful prefixes cannot extend past the actual whole source halt. -/\ntheorem prefix_fuel_le (a u : Nat) (t : List Bool) (fuel : Nat) (out : C.State Stack Label)\n    (hr : SemiprimeD1StackCalls.run program fuel (initial a u t)=some out) : fuel≤ runBound a u t :=by\n  obtain ⟨q,hq,hfinal⟩:=source_run a u t\n  have hf:fuel≤ q:=by\n    by_contra hn\n    have he:fuel=q+(1+(fuel-(q+1))):=by omega\n    rw [he,SemiprimeD1StackReturnLink.run_add,hfinal,Option.bind_some,\n      SemiprimeD1StackReturnLink.run_add] at hr\n    have hz:SemiprimeD1StackCalls.run program 1 (done a u t)=none:=rfl\n    rw [hz,Option.bind_none] at hr\n    cases hr\n  exact hf.trans hq\n/-- Every old geometry field, original u, comparator scratch and real return is counted. -/\ntheorem prefix_cells (a u : Nat) (t : List Bool) (fuel : Nat) (out : C.State Stack Label)\n    (hr : SemiprimeD1StackCalls.run program fuel (initial a u t)=some out) :\n    (∑k:Stack,(out.data k).length)+out.frames.length≤300000*(a+u+t.length+1) :=by\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel (a+u+t.length) _ out (by\n    intro k\n    rcases k with k|k\n    · rcases k with k|k\n      · cases k <;> simp [initial,input,store,G.input,SemiprimeD1StackPhaseGeometry.store,\n          SemiprimeD1StackPhaseGeometry.S.store]\n      · cases k <;> simp [initial,input,store,G.input,SemiprimeD1StackPhaseGeometry.store,\n          SemiprimeD1StackPhaseGeometry.words]\n        omega\n    · cases k <;> simp [initial,input,store,words]\n      omega) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ out hr\n  change out.frames.length≤0+fuel at hf\n  have hs:(∑k:Stack,(out.data k).length)≤21*(a+u+t.length+fuel):=by\n    calc\n      _≤∑_k:Stack,(a+u+t.length+fuel):=Finset.sum_le_sum (fun k _=>hd k)\n      _=_:=by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  have ht:=prefix_fuel_le a u t fuel out hr\n  unfold runBound at ht\n  omega\n/-- SAME all-role/real-return bound for every actual compiled finite-machine prefix. -/\ntheorem machine_prefix_cells (a u : Nat) (t : List Bool) (fuel : Nat) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial a u t)))=some cfg) :\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤300000*(a+u+t.length+1) :=by\n  have he:=SemiprimeD1StackCalls.run_correct (geometryStack (G.aux .exponent)) (aux .output) .start program fuel (initial a u t)\n  change (SemiprimeD1StackCalls.run program fuel (initial a u t)).map SemiprimeD1StackCalls.configuration=\n    (fun q=>q.bind machine.step)^[fuel] (some (SemiprimeD1StackCalls.configuration (initial a u t))) at he\n  have hh:=he.trans hr\n  cases hc:SemiprimeD1StackCalls.run program fuel (initial a u t) with\n  | none=>rw [hc] at hh;cases hh\n  | some out=>\n    rw [hc] at hh\n    have hcfg:SemiprimeD1StackCalls.configuration out=cfg:=Option.some.inj hh\n    subst cfg\n    exact prefix_cells a u t fuel out hc\nend RiemannGaussian.SemiprimeD1StackPhaseGeometryGuardBounds\n","RiemannGaussian.SemiprimeD1StackPhaseWorkingPrecisionMetadataExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPhaseWorkingPrecisionMetadataStages\n/-! # Whole guarded original metadata source and genuine finite-machine halt -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nnamespace RiemannGaussian.SemiprimeD1StackPhaseWorkingPrecisionMetadataExecution\nopen SemiprimeD1StackPhaseWorkingPrecisionMetadata SemiprimeD1StackPhaseWorkingPrecisionMetadataPrimitives\nopen SemiprimeD1StackPhaseWorkingPrecisionMetadataArithmetic SemiprimeD1StackProcedureTrace\n/-- Actual accepted/rejected metadata; rejection leaves EVERY new output empty. -/\ndef resultCounts (a u M : Nat) (t : List Bool) : Counts :=\n  if accepted a u t then SemiprimeD1StackPhaseWorkingPrecisionMetadataStages.completed a u M t else empty\n/-- Exact physical acquired guard plus retained M/binaryp and actual bounded outputs. -/\ndef result (a u M : Nat) (t p : List Bool) : Stack→List Bool :=context a u M t p (resultCounts a u M t)\n/-- Actual halt clears both flags and the source's internal real-return frames. -/\ndef done (a u M : Nat) (t p : List Bool) : C.State Stack Label :=⟨none,none,none,result a u M t p,[]⟩\n/-- Own fixed polynomial includes ALL original physical metadata/index/precision bytes. -/\ndef runBound (a u M : Nat) (t p : List Bool) : Nat :=1000000*(M+a+u+t.length+p.length+1)^2\n/-- The actual acquired verdict is peeked physically; false branches directly to halt. -/\ntheorem branch_run (a u M : Nat) (t p : List Bool) :\n    Runs program 1 .branch (context a u M t p empty)\n      (if accepted a u t then .numerator 0 else .done) (context a u M t p empty) :=by\n  apply one_base program .branch _ (.peek (guardStack (G.aux .output)) .done .done (.numerator 0)) _ _ rfl\n  · change some (SemiprimeD1StackBytecode.choose Label.done Label.done (Label.numerator 0)\n      ([accepted a u t].head?))=some _\n    cases accepted a u t <;> rfl\n  · rfl\n/-- Rejected guard executes one actual peek and stops before EVERY division/product entry. -/\ntheorem rejected_after_guard (a u M : Nat) (t p : List Bool) (h : accepted a u t=false) :\n    Runs program 1 .branch (context a u M t p empty) .done (context a u M t p empty) :=by\n  have hh:=branch_run a u M t p\n  rw [h] at hh\n  exact hh\n/-- Whole original-only trace executes guarded height/product/count acquisition exactly once. -/\ntheorem source_trace (a u M : Nat) (t p : List Bool) :\n    ∃q,q+1≤ runBound a u M t p ∧ Runs program q .start (input a u M t p) .done (result a u M t p) :=by\n  obtain ⟨g,hg,h0⟩:=guard_call a u M t p\n  have h1:=branch_run a u M t p\n  let I:=M+a+u+t.length+p.length+1\n  have hI:1≤ I:=by dsimp [I];omega\n  have hsq:I≤ I^2:=by nlinarith\n  have hbig:M+a+u+1≤ I:=by dsimp [I];omega\n  have hs:(M+a+u+1)^2≤ I^2:=Nat.pow_le_pow_left hbig 2\n  have hg':g≤10000*I+1:=by dsimp [I];omega\n  cases hacc:accepted a u t with\n  | false=>\n    rw [hacc] at h1\n    have hh:=join h0 h1\n    refine ⟨g+1,?_,?_⟩\n    · change g+1+1≤1000000*I^2\n      omega\n    · simpa only [result,resultCounts,hacc,Bool.false_eq_true,ite_false] using hh\n  | true=>\n    rw [hacc] at h1\n    have hbounds:=accepted_bounds a u t hacc\n    obtain ⟨b,hb,h2⟩:=SemiprimeD1StackPhaseWorkingPrecisionMetadataHeight.source_run a u M t p\n      (accepted_positive a u t hacc)\n    obtain ⟨c,hc,h3⟩:=SemiprimeD1StackPhaseWorkingPrecisionMetadataStages.source_run a u M t p hbounds.1 hbounds.2\n    have hh:=join (join (join h0 h1) h2) h3\n    refine ⟨_,?_,by simpa only [result,resultCounts,hacc,ite_true] using hh⟩\n    have hb':b≤1000*I:=by dsimp [I];omega\n    have hc':c≤1000*I^2:=by omega\n    change _≤1000000*I^2\n    omega\n/-- Complete actual halt on one fixed finite source for all original operands. -/\ntheorem source_run (a u M : Nat) (t p : List Bool) :\n    ∃q≤ runBound a u M t p,SemiprimeD1StackCalls.run program q (initial a u M t p)=some (done a u M t p) :=by\n  obtain ⟨q,hq,hr⟩:=source_trace a u M t p\n  obtain ⟨finish,hf,hAt⟩:=hr [] (initial a u M t p) ⟨rfl,rfl,rfl⟩\n  have hh:=halt_run program .done rfl (result a u M t p) [] finish hAt\n  exact ⟨q+1,hq,by rw [SemiprimeD1StackReturnLink.run_add,hf,Option.bind_some];exact hh⟩\n/-- Genuine finite Boolean-stack certificate from ONLY original a/u/M/binaryt/binaryp. -/\nnoncomputable def metadataInTime (a u M : Nat) (t p : List Bool) :\n    StateTransition.EvalsToInTime machine.step (SemiprimeD1StackCalls.configuration (initial a u M t p))\n      (some (SemiprimeD1StackCalls.configuration (done a u M t p))) (runBound a u M t p) :=by\n  apply SemiprimeD1StackCalls.evalsCorrect (aux .edges) (aux .q) .start program\n  let h:=source_run a u M t p\n  let q:=Classical.choose h\n  have hq:=Classical.choose_spec h\n  exact ⟨⟨q,hq.2⟩,hq.1⟩\nend RiemannGaussian.SemiprimeD1StackPhaseWorkingPrecisionMetadataExecution\n","RiemannGaussian.SemiprimeD1StackPortCatalogueLoopBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPortCatalogueLoop\n/-! # Actual finite-loop transition and output bounds of the original port transducer -/\nset_option autoImplicit false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 131072\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackPortCatalogueLoopBounds\nopen SemiprimeD1StackPortCatalogueLoop SemiprimeD1StackPortCatalogueEmit\nopen SemiprimeD1EdgeCatalogueEncoding (Record record)\nopen SemiprimeD1StackEdgeCatalogueParse (wordMass)\nopen SemiprimeD1StackUnaryDivmod (unary)\n/-- Exact actual control-field byte mass, including the physically pushed unary ordinals. -/\ntheorem mass8_unary (words:Record) (n f slot:ℕ) :\n    mass8 words (unary slot) (unary f) (unary n)=n+f+slot+wordMass words := by\n  simp only [mass8,unary,List.length_replicate]\n/-- A bound for EVERY recursive loop prefix, rather than only a normalized final count. -/\ntheorem loopTime_le (words:Record) (fuel n f slot:ℕ) :\n    loopTime words fuel n f slot≤fuel*(10*(n+f+slot+2*fuel+wordMass words)+83)+1 := by\n  induction fuel generalizing n slot with\n  | zero => simp [loopTime]\n  | succ fuel ih =>\n    rw [loopTime,mass8_unary]\n    have h:=ih (n+1) (slot+1)\n    nlinarith\n/-- Literal eight-field output length, including every delimiter. -/\ntheorem record8_length (words:Record) (slot factor occurrence tail:List Bool) :\n    (record8 words slot factor occurrence tail).length=\n      2*(occurrence.length+factor.length+slot.length+wordMass words)+tail.length+8 := by\n  unfold record8\n  simp only [SemiprimeSourceHistogramKeyBits.frame_length,SemiprimeD1StackEdgeCatalogueScan.record_length]\n  omega\n/-- Every actual recursive output prefix is bounded by its own finite counter/control dimensions. -/\ntheorem records_length_le (words:Record) (fuel n f slot:ℕ) (tail:List Bool) :\n    (records words fuel n f slot tail).length≤\n      fuel*(2*(n+f+slot+2*fuel+wordMass words)+8)+tail.length := by\n  induction fuel generalizing n slot with\n  | zero => simp [records]\n  | succ fuel ih =>\n    rw [records,record8_length]\n    simp only [unary,List.length_replicate]\n    have h:=ih (n+1) (slot+1)\n    nlinarith\n/-- Actual original descriptor arity is bounded by its parsed index and readonly parameters. -/\ntheorem value_le (code:Fin 18) (index radius first second digits:ℕ) :\n    SemiprimeD1StackVertexArityRecipes.value code index radius first second digits≤\n      10*(index+radius+first+second+digits+1)^2 := by\n  generalize hS:index+radius+first+second+digits+1=S\n  have hR:radius≤S:=by omega\n  have hF:first≤S:=by omega\n  have hT:second≤S:=by omega\n  have hS1:1≤S:=by omega\n  have hS2:S≤S^2:=Nat.le_pow (by omega)\n  have hf:first*radius≤S^2:=by simpa only [pow_two] using Nat.mul_le_mul hF hR\n  have ht:second*radius≤S^2:=by simpa only [pow_two] using Nat.mul_le_mul hT hR\n  have hff:(first+first)*radius≤2*S^2:=by nlinarith only [hf]\n  have htt:(second+second)*radius≤2*S^2:=by nlinarith only [ht]\n  fin_cases code <;> norm_num [SemiprimeD1StackVertexArityRecipes.value] <;> (try split_ifs) <;> omega\n/-- The original arity follows from the actual descriptor theorem, without an arity supplier. -/\ntheorem original_arity_le {r t digits:ℕ} (v:SemiprimeMacroGraph.SubdividedVertex r t digits) :\n    SemiprimeMacroGraph.subdividedArity v≤\n      10*(SemiprimeD1StackVertexArityOriginal.indexValue v+(r*t+1)+r+t+digits+1)^2 := by\n  rw [←SemiprimeD1StackVertexArityOriginal.value_original]\n  exact value_le _ _ _ _ _ _\nend RiemannGaussian.SemiprimeD1StackPortCatalogueLoopBounds\n","RiemannGaussian.SemiprimeD1StackPortOrdinalStreamOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPortOrdinalStreamBounds\nimport RiemannGaussian.SemiprimeD1OrdinalBankSpec\nimport RiemannGaussian.SemiprimeD1StackVertexReadExecution\n/-! # Exact original port-tape binding for acquired padded occurrence IDs -/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1StackPortOrdinalStreamOriginal\nopen SemiprimeD1StackPortOrdinalStream SemiprimeD1StackPortOrdinalStreamExecution\nnamespace Bank\nexport SemiprimeD1OrdinalBankSpec (words idAt id_value id_length values word_length length)\nend Bank\n/-- Literal output equals the frozen unary Gather input, with raw padding allowed. -/\ntheorem result_portTape (words:List (List Bool)) :\n    result words=SemiprimeD1StackVertexReadExecution.portTape\n      (words.map SemiprimeBitArithmetic.bitValue) := by\n  simp only [result,SemiprimeD1StackVertexReadExecution.portTape,List.map_map]\n  rfl\n/-- Every actual selected canonical occurrence ID serializes to its exact port.\nThe ordinal list appears only in this proof, never in runtime inputs/control. -/\ntheorem selected_portTape (M:Nat) (ports:List Nat) (hp:∀i∈ports,i<M) :\n    result (ports.map (Bank.idAt M))=SemiprimeD1StackVertexReadExecution.portTape ports := by\n  rw [result_portTape]\n  congr 1\n  rw [List.map_map]\n  have h : ports.map (fun i=>SemiprimeBitArithmetic.bitValue (Bank.idAt M i))=ports.map id := by\n    apply List.map_congr_left\n    intro i hi\n    exact Bank.id_value M i (hp i hi)\n  change ports.map (fun i=>SemiprimeBitArithmetic.bitValue (Bank.idAt M i))=ports\n  simpa only [List.map_id] using h\n/-- Whole acquired bank covers ALL canonical occurrence ordinals, including\nunused scope entries. No wire-major endpoint permutation is asserted. -/\ntheorem whole_portTape (M:Nat) :\n    result (Bank.words M)=SemiprimeD1StackVertexReadExecution.portTape (List.range M) := by\n  rw [result_portTape,Bank.values]\n/-- Closed actual selected-fibre execution with no unary tape/decoded answer input. -/\ntheorem selected_source_run (M:Nat) (ports:List Nat) (hp:∀i∈ports,i<M) :\n    ∃t≤100*(ports.length+1)*(M+1),SemiprimeD1StackCalls.run program t\n      (initial (SemiprimeD1TensorTapeCodec.vectorBits (ports.map (Bank.idAt M))))=\n      some (done (ports.map (Bank.idAt M))) := by\n  obtain ⟨t,ht,he⟩:=source_run (ports.map (Bank.idAt M))\n  refine ⟨t,ht.trans ?_,he⟩\n  have h:=SemiprimeD1StackPortOrdinalStreamBounds.timeBound_le (ports.map (Bank.idAt M)) M\n    (by intro w hw;obtain ⟨i,hi,rfl⟩:=List.mem_map.mp hw;exact (Bank.id_length M i (hp i hi)).le)\n    (by intro w hw;obtain ⟨i,hi,rfl⟩:=List.mem_map.mp hw;rw [Bank.id_value M i (hp i hi)];exact (hp i hi).le)\n  simpa only [List.length_map] using h\n/-- The N-only acquired root bank's serialization has actual quadratic cost in\nits tally M; M is metadata occurrence count, never the original N value. -/\ntheorem whole_source_run (M:Nat) :\n    ∃t≤100*(M+1)^2,SemiprimeD1StackCalls.run program t\n      (initial (SemiprimeD1TensorTapeCodec.vectorBits (Bank.words M)))=some (done (Bank.words M)) := by\n  obtain ⟨t,ht,he⟩:=source_run (Bank.words M)\n  refine ⟨t,ht.trans ?_,he⟩\n  have h:=SemiprimeD1StackPortOrdinalStreamBounds.timeBound_le (Bank.words M) M\n    (fun w hw=>(Bank.word_length M w hw).le)\n    (by intro w hw\n        have hm:SemiprimeBitArithmetic.bitValue w∈(Bank.words M).map SemiprimeBitArithmetic.bitValue:=\n          List.mem_map.mpr ⟨w,hw,rfl⟩\n        rw [Bank.values] at hm\n        exact (List.mem_range.mp hm).le)\n  simpa only [Bank.length,pow_two,Nat.mul_assoc] using h\nend RiemannGaussian.SemiprimeD1StackPortOrdinalStreamOriginal\n","RiemannGaussian.SemiprimeD1StackPortOwnerRecipeDecision":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPortOwnerRecipeEmit\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nnamespace RiemannGaussian.SemiprimeD1StackPortOwnerRecipeDecision\nopen SemiprimeD1StackPortOwnerRecipe SemiprimeD1StackPortOwnerRecipeSpec SemiprimeD1StackPortOwnerRecipeEmit\nopen SemiprimeD1StackProcedureTrace (Runs one_base runs_refl runs_trans)\nopen SemiprimeD1StackUnaryDivmod (unary)\n/-- Literal original constructor tag number, fixed before all input. -/\ndef tagCode : Tag→Fin 18\n  | .input=>10 | .first=>11 | .twiddle=>12 | .second=>13\n  | .product=>14 | .carry=>15 | .digit=>16 | .orOut=>17\n/-- Proof-only description of the branch actually selected by physical tests. -/\ndef selected (p:Counters) (tag:Tag) : Recipe :=\n  match tag,p.half with\n  | .input,false=>.inputSource | .input,true=>.inputFirst\n  | .first,false=>.firstFirst | .first,true=>.firstScale\n  | .twiddle,false=>.twiddleScale | .twiddle,true=>.twiddleSecond\n  | .second,false=>.secondSecond\n  | .second,true=>if p.a<2 then .secondProduct else .secondCarry\n  | .product,false=>.productProduct | .product,true=>.productFirst\n  | .carry,false=>if p.a=0 then .carryInitial else .carryOut\n  | .carry,true=>if p.a<p.r*p.t then .carryPrevious else .carryTerminal\n  | .digit,false=>.digitInput\n  | .digit,true=>if p.b=0 then if p.digits=1 then .digitCheck else .digitOrFirst else .digitOrNew\n  | .orOut,false=>.orSource\n  | .orOut,true=>if p.b+1<p.digits-1 then .orNext else .orCheck\n/-- Fixed jump target of the original constructor/half dispatch. -/\ndef branchStart : Tag→Bool→Label\n  | .input,false=>.local (.begin .inputSource) | .input,true=>.local (.begin .inputFirst)\n  | .first,false=>.local (.begin .firstFirst) | .first,true=>.local (.begin .firstScale)\n  | .twiddle,false=>.local (.begin .twiddleScale) | .twiddle,true=>.local (.begin .twiddleSecond)\n  | .second,false=>.local (.begin .secondSecond) | .second,true=>.local .secondLimit\n  | .product,false=>.local (.begin .productProduct) | .product,true=>.local (.begin .productFirst)\n  | .carry,false=>.local .carryZero | .carry,true=>.local .carryLimit\n  | .digit,false=>.local (.begin .digitInput) | .digit,true=>.local .digitZero\n  | .orOut,false=>.local (.begin .orSource) | .orOut,true=>.local .orLimit\n/-- One real peek retains the actual physical store and branches on its actual head byte. -/\ntheorem peek_run (pc:Label) (role:Stack) (empty low high:Label) (data:Stack→List Bool)\n    (hc:program pc=.base (.peek role empty low high)) :\n    Runs program 1 pc data (SemiprimeD1StackBytecode.choose empty low high (data role).head?) data := by\n  apply one_base program pc _ (.peek role empty low high) data data hc rfl rfl\n/-- Unary zero/nonzero branch is a literal EOF or true-byte read. -/\ntheorem choose_unary (empty low high:Label) (n:ℕ) :\n    SemiprimeD1StackBytecode.choose empty low high (unary n).head?=if n=0 then empty else high := by\n  cases n <;> rfl\n/-- A computed comparison bit selects only its two fixed literal branches. -/\ntheorem choose_decide (empty low high:Label) (p:Prop) [Decidable p] :\n    SemiprimeD1StackBytecode.choose empty low high [decide p].head?=if p then high else low := by\n  by_cases h:p <;> simp [h,SemiprimeD1StackBytecode.choose]\n/-- The actual half marker is read before the static constructor/half jump. -/\ntheorem half_run (p:Counters) (tag:Tag) :\n    Runs program 1 (.local (.half tag)) (ready p) (.local (.choose tag p.half)) (ready p) := by\n  have h:=peek_run (.local (.half tag)) (arg .half) (.local (.choose tag false))\n    (.local (.choose tag true)) (.local (.choose tag true)) (ready p) rfl\n  have he:SemiprimeD1StackBytecode.choose (Label.local (.choose tag false))\n      (.local (.choose tag true)) (.local (.choose tag true)) ((ready p) (arg .half)).head?=\n      .local (.choose tag p.half):=by\n    cases hh:p.half <;> simp [ready,prepared,atStage,words,arg,reg,Function.update,hh,SemiprimeD1StackBytecode.choose]\n  rw [he] at h\n  exact h\n/-- The actual constructor/half stage executes its real finite jump. -/\ntheorem branch_start_run (p:Counters) (tag:Tag) (half:Bool) :\n    Runs program 1 (.local (.choose tag half)) (ready p) (branchStart tag half) (ready p) := by\n  have hc:program (.local (.choose tag half))=.base (.jump (branchStart tag half)):=by\n    cases tag <;> cases half <;> rfl\n  apply one_base program _ _ (.jump (branchStart tag half)) _ _ hc rfl rfl\n/-- Every additional recipe test reads its physically acquired unary word or comparison bit. -/\ntheorem branch_run (p:Counters) (tag:Tag) (hd:0<p.digits) :\n    ∃time≤2,Runs program time (branchStart tag p.half) (ready p)\n      (.local (.begin (selected p tag))) (ready p) := by\n  cases tag with\n  | input=>cases hh:p.half <;> exact ⟨0,by omega,by simpa only [branchStart,selected,hh] using runs_refl program (.local (.begin _)) (ready p)⟩\n  | first=>cases hh:p.half <;> exact ⟨0,by omega,by simpa only [branchStart,selected,hh] using runs_refl program (.local (.begin _)) (ready p)⟩\n  | twiddle=>cases hh:p.half <;> exact ⟨0,by omega,by simpa only [branchStart,selected,hh] using runs_refl program (.local (.begin _)) (ready p)⟩\n  | product=>cases hh:p.half <;> exact ⟨0,by omega,by simpa only [branchStart,selected,hh] using runs_refl program (.local (.begin _)) (ready p)⟩\n  | second=>\n    cases hh:p.half with\n    | false=>exact ⟨0,by omega,by simpa only [branchStart,selected,hh] using runs_refl program (.local (.begin .secondSecond)) (ready p)⟩\n    | true=>\n      have h:=peek_run (.local .secondLimit) (reg .smallA) (.local .abort)\n        (.local (.begin .secondCarry)) (.local (.begin .secondProduct)) (ready p) rfl\n      have hv:ready p (reg .smallA)=[decide (p.a<2)]:=by rfl\n      rw [hv,choose_decide] at h\n      refine ⟨1,by omega,?_⟩\n      by_cases he:p.a<2 <;> simpa only [branchStart,selected,hh,he,ite_true,ite_false] using h\n  | carry=>\n    cases hh:p.half with\n    | false=>\n      have h:=peek_run (.local .carryZero) (arg .a) (.local (.begin .carryInitial))\n        (.local (.begin .carryOut)) (.local (.begin .carryOut)) (ready p) rfl\n      have hv:ready p (arg .a)=unary p.a:=by rfl\n      rw [hv,choose_unary] at h\n      refine ⟨1,by omega,?_⟩\n      by_cases he:p.a=0 <;> simpa only [branchStart,selected,hh,he,ite_true,ite_false] using h\n    | true=>\n      have h:=peek_run (.local .carryLimit) (reg .ltArt) (.local .abort)\n        (.local (.begin .carryTerminal)) (.local (.begin .carryPrevious)) (ready p) rfl\n      have hv:ready p (reg .ltArt)=[decide (p.a<p.r*p.t)]:=by rfl\n      rw [hv,choose_decide] at h\n      refine ⟨1,by omega,?_⟩\n      by_cases he:p.a<p.r*p.t <;> simpa only [branchStart,selected,hh,he,ite_true,ite_false] using h\n  | digit=>\n    cases hh:p.half with\n    | false=>exact ⟨0,by omega,by simpa only [branchStart,selected,hh] using runs_refl program (.local (.begin .digitInput)) (ready p)⟩\n    | true=>\n      have h:=peek_run (.local .digitZero) (arg .b) (.local .digitSize)\n        (.local (.begin .digitOrNew)) (.local (.begin .digitOrNew)) (ready p) rfl\n      have hv:ready p (arg .b)=unary p.b:=by rfl\n      rw [hv,choose_unary] at h\n      by_cases hb:p.b=0\n      · simp only [hb,ite_true] at h\n        have hs:=peek_run (.local .digitSize) (reg .dminus) (.local (.begin .digitCheck))\n          (.local (.begin .digitOrFirst)) (.local (.begin .digitOrFirst)) (ready p) rfl\n        have hvalue:ready p (reg .dminus)=unary (p.digits-1):=by rfl\n        rw [hvalue,choose_unary] at hs\n        have he:p.digits-1=0 ↔ p.digits=1:=by omega\n        simp only [he] at hs\n        have hboth:=runs_trans program _ _ _ _ _ _ _ _ h hs\n        refine ⟨2,by omega,?_⟩\n        by_cases hd1:p.digits=1 <;> simpa only [branchStart,selected,hh,hb,hd1,ite_true,ite_false] using hboth\n      · refine ⟨1,by omega,?_⟩\n        simpa only [branchStart,selected,hh,hb,ite_false] using h\n  | orOut=>\n    cases hh:p.half with\n    | false=>exact ⟨0,by omega,by simpa only [branchStart,selected,hh] using runs_refl program (.local (.begin .orSource)) (ready p)⟩\n    | true=>\n      have h:=peek_run (.local .orLimit) (reg .ltNext) (.local .abort)\n        (.local (.begin .orCheck)) (.local (.begin .orNext)) (ready p) rfl\n      have hv:ready p (reg .ltNext)=[decide (p.b+1<p.digits-1)]:=by rfl\n      rw [hv,choose_decide] at h\n      refine ⟨1,by omega,?_⟩\n      by_cases he:p.b+1<p.digits-1 <;> simpa only [branchStart,selected,hh,he,ite_true,ite_false] using h\n/-- All actual half/branch instructions are counted; the computed recipe never enters runtime as advice. -/\ntheorem decision_run (p:Counters) (tag:Tag) (hd:0<p.digits) :\n    ∃time≤4,Runs program time (.local (.half tag)) (ready p)\n      (.local (.begin (selected p tag))) (ready p) := by\n  obtain ⟨time,ht,hr⟩:=branch_run p tag hd\n  have h:=runs_trans program _ _ _ _ _ _ _ _ (half_run p tag)\n    (runs_trans program _ _ _ _ _ _ _ _ (branch_start_run p tag p.half) hr)\n  exact ⟨1+(1+time),by omega,h⟩\nend RiemannGaussian.SemiprimeD1StackPortOwnerRecipeDecision\n","RiemannGaussian.SemiprimeD1StackPortOwnerRecipeNumeric":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPortOwnerRecipeExecution\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nnamespace RiemannGaussian.SemiprimeD1StackPortOwnerRecipeNumeric\nopen SemiprimeD1StackPortOwnerRecipe SemiprimeD1StackPortOwnerRecipeSpec\nopen SemiprimeD1StackPortOwnerRecipePrepare SemiprimeD1StackPortOwnerRecipeAcquisition\nopen SemiprimeD1StackPortOwnerRecipeEmit\n/-- Actual acquired unary operand inventory, with fixed room for literal mode tags. -/\ndef volume (p:Counters) : ℕ := p.r+p.t+p.digits+p.tag+p.a+p.b+p.c+p.d+10\n/-- A fixed quadratic cap for every operand of any real preparation primitive. -/\ndef cap (p:Counters) : ℕ := (volume p+1)^2\n/-- Every primitive operand cap is derived from the original acquired counters. -/\ntheorem operand_caps (p:Counters) :\n    9≤cap p ∧ p.r≤cap p ∧ p.t≤cap p ∧ p.digits≤cap p ∧ p.tag≤cap p ∧\n    p.a≤cap p ∧ p.b≤cap p ∧ p.c≤cap p ∧ p.d≤cap p ∧\n    p.r*p.t≤cap p ∧ p.r*p.t+1≤cap p ∧ p.a/p.r≤cap p ∧ p.b/p.r≤cap p ∧\n    p.a%p.r≤cap p ∧ p.b%p.r≤cap p ∧ p.c+p.t≤cap p ∧ p.c+p.r≤cap p ∧\n    p.a-1≤cap p ∧ p.b-1≤cap p ∧ p.digits-1≤cap p ∧ p.b+1≤cap p := by\n  let s:=volume p\n  have hs:10 ≤ s:=by dsimp [s,volume];omega\n  have hr:p.r ≤ s:=by dsimp [s,volume];omega\n  have ht:p.t ≤ s:=by dsimp [s,volume];omega\n  have hd:p.digits ≤ s:=by dsimp [s,volume];omega\n  have hg:p.tag ≤ s:=by dsimp [s,volume];omega\n  have ha:p.a ≤ s:=by dsimp [s,volume];omega\n  have hb:p.b ≤ s:=by dsimp [s,volume];omega\n  have hc:p.c ≤ s:=by dsimp [s,volume];omega\n  have he:p.d ≤ s:=by dsimp [s,volume];omega\n  have hct:p.c+p.t ≤ s:=by dsimp [s,volume];omega\n  have hcr:p.c+p.r ≤ s:=by dsimp [s,volume];omega\n  have hbn:p.b+1 ≤ s:=by dsimp [s,volume];omega\n  have hprod:p.r*p.t ≤ s^2:=by simpa only [pow_two] using Nat.mul_le_mul hr ht\n  have hbase:s≤(s+1)^2:=by nlinarith\n  have hdiva: p.a/p.r≤p.a:=Nat.div_le_self _ _\n  have hdivb: p.b/p.r≤p.b:=Nat.div_le_self _ _\n  have hmoda: p.a%p.r≤p.a:=Nat.mod_le _ _\n  have hmodb: p.b%p.r≤p.b:=Nat.mod_le _ _\n  have hsuba:p.a-1≤p.a:=Nat.sub_le _ _\n  have hsubb:p.b-1≤p.b:=Nat.sub_le _ _\n  have hsubd:p.digits-1≤p.digits:=Nat.sub_le _ _\n  change 9≤(s+1)^2 ∧ _\n  refine ⟨?_,?_,?_,?_,?_,?_,?_,?_,?_,?_,?_,?_,?_,?_,?_,?_,?_,?_,?_,?_,?_⟩\n  all_goals change _ ≤ (s+1)^2\n  all_goals first | omega | nlinarith\n/-- Fresh scalar bound on the actual nested unary multiply-plus-offset trace. -/\ntheorem madd_clock (R a b c:ℕ) (ha:a≤R) (hb:b≤R) (hc:c≤R) :\n    SemiprimeD1StackPortOwnerMaddBounds.budget a b c+1≤1000*(R+1)^2 := by\n  have hab:a*b≤R^2:=by simpa only [pow_two] using Nat.mul_le_mul ha hb\n  unfold SemiprimeD1StackPortOwnerMaddBounds.budget\n  nlinarith\n/-- Fresh scalar bound on the actual output counter of multiply-plus-offset. -/\ntheorem madd_value (R a b c:ℕ) (ha:a≤R) (hb:b≤R) (hc:c≤R) : a*b+c≤2*(R+1)^2 := by\n  have hab:a*b≤R^2:=by simpa only [pow_two] using Nat.mul_le_mul ha hb\n  nlinarith\n/-- ALL real preparation call costs have one fixed operand-polynomial bound. -/\ntheorem stepTime_le (p:Counters) (pc:Fin 41) : stepTime p pc≤1000*(cap p+1)^2 := by\n  obtain ⟨h9,hr,ht,hd,hg,ha,hb,hc,he,hprod,hwidth,hqa,hqb,hma,hmb,hct,hcr,ham,hbm,hdm,hbn⟩:=operand_caps p\n  generalize hR:cap p=R at *\n  clear hR\n  fin_cases pc\n  all_goals dsimp only [stepTime]\n  all_goals first\n    | (apply madd_clock <;> omega)\n    | nlinarith\n/-- Every literal computed register width is derived from the acquired operand inventory. -/\ntheorem cached_length_le (p:Counters) (k:Register) : (cached p 41 k).length≤2*(cap p+1)^2 := by\n  obtain ⟨h9,hr,ht,hd,hg,ha,hb,hc,he,hprod,hwidth,hqa,hqb,hma,hmb,hct,hcr,ham,hbm,hdm,hbn⟩:=operand_caps p\n  generalize hR:cap p=R at *\n  clear hR\n  have hsingle:R≤2*(R+1)^2:=by nlinarith\n  have hdouble:2*R≤2*(R+1)^2:=by nlinarith\n  cases k <;> dsimp [cached] <;>\n    try simp only [SemiprimeD1StackUnaryDivmod.unary,List.length_replicate]\n  all_goals first\n    | (apply madd_value <;> omega)\n    | omega\n/-- All acquired readonly input widths obey the same honest physical cap. -/\ntheorem input_length_le (p:Counters) (k:Input) : (words p k).length≤2*(cap p+1)^2 := by\n  obtain ⟨h9,hr,ht,hd,hg,ha,hb,hc,he,_⟩:=operand_caps p\n  generalize hR:cap p=R at *\n  clear hR\n  have hsingle:R≤2*(R+1)^2:=by nlinarith\n  cases k <;> simp only [words,SemiprimeD1StackUnaryDivmod.unary,List.length_replicate]\n  all_goals first | omega | (split <;> (simp; try omega))\n/-- Every prepared physical role, including real comparison bits and all scratch, is bounded. -/\ntheorem prepared_length_le (p:Counters) (k:Stack) : (prepared p k).length≤2*(cap p+1)^2 := by\n  rcases k with k|k\n  · exact input_length_le p k\n  · rcases k with k|k\n    · exact cached_length_le p k\n    · exact Nat.zero_le _\n/-- Tag-consumption clears one actual counter and introduces no new word advice. -/\ntheorem ready_length_le (p:Counters) (k:Stack) : (ready p k).length≤2*(cap p+1)^2 := by\n  by_cases he:k=reg .tagReader\n  · subst k\n    simp [ready]\n  · rw [ready,Function.update_of_ne he]\n    exact prepared_length_le p k\n/-- Every selected scalar field comes from an actually bounded acquired role. -/\ntheorem mass_le (p:Counters) (recipe:Recipe) : mass p recipe≤12*(cap p+1)^2 := by\n  have h0:=ready_length_le p (fields recipe 0)\n  have h1:=ready_length_le p (fields recipe 1)\n  have h2:=ready_length_le p (fields recipe 2)\n  have h3:=ready_length_le p (fields recipe 3)\n  have h4:=ready_length_le p (fields recipe 4)\n  have h5:=ready_length_le p (fields recipe 5)\n  unfold mass word\n  omega\n/-- The actual chronological preparation budget pays every site exactly once. -/\ntheorem remainingBudget_le (p:Counters) (fuel count:ℕ) :\n    remainingBudget p fuel count≤fuel*(1000*(cap p+1)^2) := by\n  induction fuel generalizing count with\n  | zero=>simp [remainingBudget]\n  | succ fuel ih=>\n    unfold remainingBudget\n    split_ifs with hc\n    · have hs:=stepTime_le p ⟨count,hc⟩\n      have ht:=ih (count+1)\n      nlinarith\n    · exact Nat.zero_le _\nend RiemannGaussian.SemiprimeD1StackPortOwnerRecipeNumeric\n","RiemannGaussian.SemiprimeD1StackPortOwnerRoutingSource":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPortOwnerRoutingView\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPortOwnerRoutingSource\nopen SemiprimeD1StackPortOwnerRouting SemiprimeD1StackPortOwnerRoutingAcquisition\nopen SemiprimeD1StackPortOwnerRoutingView\nopen SemiprimeD1StackProcedureTrace (Runs runs_trans)\nopen SemiprimeBitArithmetic (bitValue)\n/-- Actual scoped tape is copied into the real private reader; both source banks are retained. -/\ntheorem reader_copy (bits:List Bool) :\n    Runs program (5*((SemiprimeD1StackPortScopeExecution.done bits).data\n      (SemiprimeD1StackPortScopeRecords.aux .output)).length+4)\n      (.local .copyPorts) (acquired bits) (.local .parse) (ready bits) := by\n  have h:=copy_call 1 (acquired bits) (.local .copyPorts) (.local .parse) rfl rfl\n  change Runs program _ _ _ _ (Function.update (acquired bits) (aux .reader)\n    ((SemiprimeD1StackPortScopeExecution.done bits).data (SemiprimeD1StackPortScopeRecords.aux .output)++[])) at h\n  rw [List.append_nil] at h\n  have he:Function.update (acquired bits) (aux .reader)\n      ((SemiprimeD1StackPortScopeExecution.done bits).data (SemiprimeD1StackPortScopeRecords.aux .output))=ready bits:=by\n    unfold acquired fresh\n    rw [update_aux]\n    unfold ready\n    congr 1\n    funext k;cases k <;> rfl\n  rw [he] at h\n  exact h\n/-- Sum of actual N copy, both actual acquisitions and actual whole scoped-tape reader copy. -/\ndef budget (bits:List Bool) : Nat :=5*bits.length+4+\n  (SemiprimeD1StackOwnerCatalogueBounds.polynomial bits.length+1)+(10^111*(bits.length+1)^30+1)+\n  (5*((SemiprimeD1StackPortScopeExecution.done bits).data (SemiprimeD1StackPortScopeRecords.aux .output)).length+4)\n/-- Closed original binary-N prefix for the TWO real tapes required by factor-major owner routing. -/\ntheorem acquisition_run (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    ∃time≤budget bits,Runs program time (.local .main) (input bits) (.local .parse) (ready bits) := by\n  obtain ⟨time,ht,hr⟩:=sources_run bits hc hN\n  have hc:=reader_copy bits\n  have h:=runs_trans program _ _ _ _ _ _ _ _ hr hc\n  refine ⟨_,?_,h⟩\n  unfold budget\n  omega\n/-- The actually retained forward map is EXACTLY the original E-map expected by real lookup. -/\ntheorem acquired_map (bits:List Bool) (hN:0<bitValue bits) :\n    ready bits sourceMap=SemiprimeD1StackOwnerLookup.records\n      (SemiprimeD1StackOwnerLookupOriginal.Public.catalogue (bitValue bits) hN) [] := by\n  change (SemiprimeD1StackOwnerCatalogueExecution.done bits).data (SemiprimeD1StackOwnerCatalogue.aux .output)=_\n  exact SemiprimeD1StackOwnerCatalogueExecution.output_original bits hN\n/-- Actual factor-major reader bytes equal ALL original typed incidences, with no supplied order premise. -/\ntheorem reader_original (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    ready bits (aux .reader)=SemiprimeD1FactorScopePairEncoding.stream\n      (SemiprimeD1FactorScopeIncidencesOriginal.indexedRows (bitValue bits)) [] := by\n  change (SemiprimeD1StackPortScopeExecution.done bits).data (SemiprimeD1StackPortScopeRecords.aux .output)=_\n  rw [scoped_output,rows,SemiprimeD1FactorScopeIncidencesOriginal.original_rows bits hc hN]\nend RiemannGaussian.SemiprimeD1StackPortOwnerRoutingSource\n","RiemannGaussian.SemiprimeD1StackPortScopeBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPortScopeExecution\n/-! # Actual original-input transition and all-prefix bounds for scoped port records -/\nset_option autoImplicit false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 131072\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackPortScopeBounds\nopen SemiprimeD1StackPortScopeRecords SemiprimeD1StackPortScopeSource\nopen SemiprimeD1StackPortScopeExecution\nopen SemiprimeD1PortScopeEncoding (portTape)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\n/-- Both actual copied source streams are bounded at their proved executed source halt. -/\ntheorem stream_bytes (bits:List Bool) (hb:bits≠[]) :\n    (portTape (ports bits) []).length+(vectorBits (ids bits)).length≤2*10^107*(bits.length+1)^30 := by\n  obtain ⟨time,_,hr⟩:=SemiprimeD1StackPortOrdinalBankBounds.source_run_polynomial bits hb\n  have hs:=SemiprimeD1StackPortOrdinalBankBounds.prefix_cells bits hb time _ hr\n  change (∑k:S.Stack,(base bits k).length)+0≤10^107*(bits.length+1)^30 at hs\n  have hp:=Finset.single_le_sum (fun k (_:k∈(Finset.univ:Finset S.Stack))=>Nat.zero_le ((base bits k).length))\n    (Finset.mem_univ (S.portStack (SemiprimeD1StackPortCatalogue.aux .output)))\n  have hi:=Finset.single_le_sum (fun k (_:k∈(Finset.univ:Finset S.Stack))=>Nat.zero_le ((base bits k).length))\n    (Finset.mem_univ S.ids)\n  have hpe:=congrArg List.length (source_ports bits)\n  have hie:=congrArg List.length (source_ids bits)\n  change (base bits (S.portStack (SemiprimeD1StackPortCatalogue.aux .output))).length=(portTape (ports bits) []).length at hpe\n  change (base bits S.ids).length=(vectorBits (ids bits)).length at hie\n  omega\n/-- Pure fixed-polynomial substitution, before actual executable source values are instantiated. -/\ntheorem numeric_budget (n P B:ℕ) (h:P+B≤2*10^107*(n+1)^30) :\n    10^104*(n+1)^30+107*(P+B)+16≤10^111*(n+1)^30 := by\n  have hp:1≤(n+1)^30:=Nat.succ_le_of_lt (Nat.pow_pos (Nat.succ_pos n))\n  omega\n/-- The WHOLE actual original-N source/copy/stream/reverse pipeline has a fixed polynomial clock. -/\ntheorem budget_le (bits:List Bool) (hb:bits≠[]) : budget bits≤10^111*(bits.length+1)^30 :=\n  numeric_budget bits.length (portTape (ports bits) []).length (vectorBits (ids bits)).length (stream_bytes bits hb)\n/-- No graph, ID, index inverse, M, code or output record is supplied to the public source. -/\ntheorem source_run_polynomial (bits:List Bool) (hb:bits≠[]) :\n    ∃ time ≤ 10^111*(bits.length+1)^30,C.run program time (initial bits)=some (done bits) := by\n  obtain ⟨m,hm,hr⟩:=source_run bits hb\n  exact ⟨m,hm.trans (budget_le bits hb),hr⟩\n/-- Successful executed prefixes cannot pass the actual proved final halt. -/\ntheorem prefix_fuel_le (bits:List Bool) (hb:bits≠[]) (fuel:ℕ) (out:C.State Stack Label)\n    (hr:C.run program fuel (initial bits)=some out) : fuel≤10^111*(bits.length+1)^30 := by\n  obtain ⟨time,ht,he⟩:=source_run_polynomial bits hb\n  have hf:fuel≤time:=by\n    by_contra hn\n    have h:fuel=time+(1+(fuel-(time+1))):=by omega\n    rw [h,SemiprimeD1StackReturnLink.run_add,he,Option.bind_some,SemiprimeD1StackReturnLink.run_add] at hr\n    have hz:C.run program 1 (done bits)=none:=rfl\n    rw [hz,Option.bind_none] at hr\n    cases hr\n  exact hf.trans ht\n/-- ALL one hundred and five Boolean stacks and real return frames at EVERY actual source prefix. -/\ntheorem prefix_cells (bits:List Bool) (hb:bits≠[]) (fuel:ℕ) (out:C.State Stack Label)\n    (hr:C.run program fuel (initial bits)=some out) :\n    (∑k:Stack,(out.data k).length)+out.frames.length≤10^114*(bits.length+1)^30 := by\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel bits.length _ out (by\n    intro k\n    cases k with\n    | inl key =>\n      change (S.input bits key).length≤bits.length\n      rw [source_input]\n      split <;> simp\n    | inr key => exact Nat.zero_le _) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ out hr\n  change out.frames.length≤0+fuel at hf\n  have hs:(∑k:Stack,(out.data k).length)≤105*(bits.length+fuel):=by\n    calc\n      _≤∑_k:Stack,(bits.length+fuel):=Finset.sum_le_sum (fun k _=>hd k)\n      _= _:=by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  have ht:=prefix_fuel_le bits hb fuel out hr\n  have hn:bits.length≤(bits.length+1)^30:=by\n    have h:bits.length+1≤(bits.length+1)^30:=by\n      simpa only [pow_one] using Nat.pow_le_pow_right (show 1≤bits.length+1 by omega) (show 1≤30 by omega)\n    omega\n  omega\n/-- ALL actual compiled-machine prefixes start from initList of binary N alone. -/\ntheorem machine_prefix_cells (bits:List Bool) (hb:bits≠[]) (fuel:ℕ) (cfg:machine.Cfg)\n    (hr:(fun q=>q.bind machine.step)^[fuel] (some (Turing.initList machine bits))=some cfg) :\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤10^114*(bits.length+1)^30 := by\n  have he:=SemiprimeD1StackCalls.run_correct (originalInput) (aux .output) (.local .main)\n    program fuel (initial bits)\n  change (C.run program fuel (initial bits)).map SemiprimeD1StackCalls.configuration=\n    (fun q=>q.bind machine.step)^[fuel] (some (SemiprimeD1StackCalls.configuration (initial bits))) at he\n  have hh:(C.run program fuel (initial bits)).map SemiprimeD1StackCalls.configuration=some cfg:=\n    he.trans ((congrArg (fun start:machine.Cfg=>\n      (fun q:Option machine.Cfg=>q.bind machine.step)^[fuel] (some start)) (initial_eq bits).symm).trans hr)\n  cases hc:C.run program fuel (initial bits) with\n  | none => rw [hc] at hh;cases hh\n  | some out =>\n    rw [hc] at hh\n    have hcfg:SemiprimeD1StackCalls.configuration out=cfg:=Option.some.inj hh\n    subst cfg\n    exact prefix_cells bits hb fuel out hc\n/-- Actual finite-machine full-acquisition certificate, rather than a reported-cost assumption. -/\nnoncomputable def portScopeRecordsInTime (bits:List Bool) (hb:bits≠[]) :\n    StateTransition.EvalsToInTime machine.step (Turing.initList machine bits)\n      (some (SemiprimeD1StackCalls.configuration (done bits))) (10^111*(bits.length+1)^30) := by\n  rw [initial_eq bits]\n  apply SemiprimeD1StackCalls.evalsCorrect (originalInput) (aux .output) (.local .main) program\n  let cert:=source_run_polynomial bits hb\n  let m:=Classical.choose cert\n  have hs:=Classical.choose_spec cert\n  exact ⟨⟨m,hs.2⟩,hs.1⟩\nend RiemannGaussian.SemiprimeD1StackPortScopeBounds\n","RiemannGaussian.SemiprimeD1StackPortScopeClear":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPortScopeEmit\n/-! # All nine actual cached words are physically cleared between port records -/\nset_option autoImplicit false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 131072\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackPortScopeClear\nopen SemiprimeD1StackPortScopeRecords SemiprimeD1StackPortScopeView\nopen SemiprimeD1StackPortScopeEmit (wordMass)\nopen SemiprimeD1StackProcedureFragments (Runs)\n/-- Actual suffix of the finite cached record after preceding words were popped. -/\ndef remaining (words:Record) (count:ℕ) : Record := fun j=>if j.val<count then [] else words j\n/-- One physical cache write gives precisely the next remaining suffix. -/\ntheorem remaining_update (words:Record) (part:Fin 9) :\n    Function.update (remaining words part.val) part []=remaining words (part.val+1) := by\n  funext j\n  by_cases h:j=part\n  · subst j;simp [remaining,Function.update]\n  · have hn:j.val≠part.val:=by intro he;exact h (Fin.ext he)\n    simp only [Function.update_of_ne h,remaining]\n    by_cases hj:j.val<part.val\n    · have hj':j.val<part.val+1:=by omega\n      simp [hj,hj']\n    · have hj':¬j.val<part.val+1:=by omega\n      simp [hj,hj']\n/-- Literal finite cache-clear continuation. -/\ndef nextCache (part:Fin 9) : Label :=\n  if h:part.val<8 then .local (.clearCache ⟨part.val+1,by omega⟩) else .local .parse\n/-- Every copied cache bit, including the acquired ID, is physically popped. -/\ntheorem clear_step (base:S.Stack→List Bool) (ports ids:List Bool) (words:Record) (part:Fin 9) (raw:List Bool) :\n    Runs program ((words part).length+1) (.local (.clearCache part))\n      (clean base ports ids (remaining words part.val) raw) (nextCache part)\n      (clean base ports ids (remaining words (part.val+1)) raw) := by\n  have h:=clear_run (words part) (.local (.clearCache part)) (nextCache part) (cache part)\n    (clean base ports ids (remaining words part.val) raw)\n    (by change remaining words part.val part=words part;simp [remaining]) rfl\n  change Runs program _ _ _ _ (Function.update\n    (store base (remaining words part.val) (cleanWork ports ids raw)) (cache part) []) at h\n  rw [update_cache,remaining_update] at h\n  exact h\n/-- All real cached fields are consumed before the actual next record peek. -/\ntheorem caches_run (base:S.Stack→List Bool) (ports ids:List Bool) (words:Record) (raw:List Bool) :\n    Runs program (wordMass words+9) (.local (.clearCache 0)) (clean base ports ids words raw)\n      (.local .parse) (clean base ports ids (fun _=>[]) raw) := by\n  have h0:=clear_step base ports ids words 0 raw\n  have h1:=clear_step base ports ids words 1 raw\n  have h2:=clear_step base ports ids words 2 raw\n  have h3:=clear_step base ports ids words 3 raw\n  have h4:=clear_step base ports ids words 4 raw\n  have h5:=clear_step base ports ids words 5 raw\n  have h6:=clear_step base ports ids words 6 raw\n  have h7:=clear_step base ports ids words 7 raw\n  have h8:=clear_step base ports ids words 8 raw\n  have h:=h0.trans (h1.trans (h2.trans (h3.trans (h4.trans (h5.trans (h6.trans (h7.trans (h8))))))))\n  change Runs program _ _ (clean base ports ids (remaining words 0) raw) (.local .parse)\n    (clean base ports ids (remaining words 9) raw) at h\n  have hz:remaining words 0=words:=by funext j;simp [remaining]\n  have hf:remaining words 9=(fun _=>[]):=by funext j;simp [remaining,j.isLt]\n  rw [hz,hf] at h\n  have ht:((words 0).length+1+((words 1).length+1+((words 2).length+1+((words 3).length+1+((words 4).length+1+((words 5).length+1+((words 6).length+1+((words 7).length+1+((words 8).length+1)))))))))=wordMass words+9:=by unfold wordMass;omega\n  change Runs program ((words 0).length+1+((words 1).length+1+((words 2).length+1+((words 3).length+1+((words 4).length+1+((words 5).length+1+((words 6).length+1+((words 7).length+1+((words 8).length+1))))))))) _ _ _ _ at h\n  rw [ht] at h\n  exact h\nend RiemannGaussian.SemiprimeD1StackPortScopeClear\n","RiemannGaussian.SemiprimeD1StackProductCheckBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackProductCheckExecution\n\n/-! # Whole product-checker bit-time and complete physical inventory\nThese bounds count the SAME actual raw-input checker, including acquisition,\nguarding, every parser call, arithmetic, comparison, cleanup and real returns.\n-/\nset_option autoImplicit false\nset_option synthInstance.maxSize 4096\nset_option maxHeartbeats 1200000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackProductCheckBounds\nopen SemiprimeD1StackProductCheck SemiprimeD1StackProductCheckAcquisition\nopen SemiprimeD1StackProductCheckParse SemiprimeD1StackProductCheckExecution\n\n/-- All three physically acquired words have exactly the actual cache width. -/\ntheorem word_lengths (raw cached : List Bool) :\n    (first raw cached).length=cached.length ∧ (second raw cached).length=cached.length ∧\n      (third raw cached).length=cached.length :=\n  ⟨SemiprimeD1StackWordBlockExecution.result_length raw cached,\n    SemiprimeD1StackWordBlockExecution.result_length _ cached,\n    SemiprimeD1StackWordBlockExecution.result_length _ cached⟩\n/-- The guarded family is exactly the actual three parser payloads. -/\ntheorem words_three (raw cached : List Bool) :\n    SemiprimeD1StackProductCheckGuard.words raw cached=[first raw cached,second raw cached,third raw cached] := rfl\n/-- Literal framing overhead is paid in the acquired vector size. -/\ntheorem vector_length (raw cached : List Bool) :\n    (SemiprimeD1TensorTapeCodec.vectorBits (SemiprimeD1StackProductCheckGuard.words raw cached)).length=\n      6*cached.length+7 := by\n  obtain ⟨h0,h1,h2⟩:=word_lengths raw cached\n  rw [words_three]\n  simp only [SemiprimeD1TensorTapeCodec.vectorBits,List.length_cons,List.length_nil,\n    SemiprimeSourceHistogramKeyBits.frame_length,h0,h1,h2]\n  omega\n/-- One fixed cubic before all binary word values bounds every actual branch. -/\ndef runBound (raw cached : List Bool) : ℕ := 1000000*(raw.length+cached.length+3)^3\n\n/-- Complete actual source budget is polynomial in PHYSICAL input lengths,\nincluding arbitrary zero modulus words and incomplete raw assignments. -/\ntheorem timeBound_le (raw cached : List Bool) : timeBound raw cached≤runBound raw cached := by\n  let u:=raw.length+cached.length+3\n  have hu : 1≤u := by dsimp [u];omega\n  have h1p : u≤u^3 := by simpa only [pow_one] using Nat.pow_le_pow_right hu (by decide : 1≤3)\n  have h2p : u^2≤u^3 := Nat.pow_le_pow_right hu (by decide : 2≤3)\n  obtain ⟨h0,h1,h2⟩:=word_lengths raw cached\n  have hw : SemiprimeD1StackWordVectorExecution.timeBound raw cached countWord≤500*u := by\n    unfold SemiprimeD1StackWordVectorExecution.timeBound\n    change 100*(raw.length+(3+1)*(cached.length+1)+1)≤500*u\n    dsimp [u];omega\n  have hg:=SemiprimeD1StackVectorCanonicalBounds.timeBound_le\n    (SemiprimeD1StackProductCheckGuard.words raw cached) cached\n  rw [vector_length] at hg\n  have hgb : 200*(6*cached.length+7+cached.length+1)^2≤12800*u^2 := by\n    calc\n      _ ≤ 200*(8*u)^2 := Nat.mul_le_mul_left 200 (Nat.pow_le_pow_left (by dsimp [u];omega) 2)\n      _ = _ := by ring\n  have hguard:=hg.trans hgb\n  have hm:=(SemiprimeD1StackResidueMulBounds.totalTime_le (first raw cached) (second raw cached) cached).trans\n    (SemiprimeD1StackResidueMulBounds.timeBound_le_cube _ _ _)\n  rw [h0,h1] at hm\n  have hmb : 10000*(cached.length+cached.length+cached.length+3)^3≤270000*u^3 := by\n    calc\n      _ ≤ 10000*(3*u)^3 := Nat.mul_le_mul_left 10000 (Nat.pow_le_pow_left (by dsimp [u];omega) 3)\n      _ = _ := by ring\n  have hmul:=hm.trans hmb\n  have he:=SemiprimeD1StackWordEqualExecution.executionTime_le\n    (SemiprimeD1StackProductCheckCompute.residue raw cached) (third raw cached)\n  have hr : (SemiprimeD1StackProductCheckCompute.residue raw cached).length=cached.length :=\n    SemiprimeD1StackResidueMulBounds.residue_width _ _ cached\n  rw [hr,h2] at he\n  have hp : parseTime raw cached≤30*u := by\n    simp only [parseTime,h0,h1,h2]\n    dsimp [u];omega\n  have hv : (SemiprimeD1StackWordVectorExecution.result raw cached countWord).length=6*cached.length+7 :=\n    vector_length raw cached\n  change _≤1000000*u^3\n  unfold timeBound SemiprimeD1StackProductCheckReject.rejectBudget SemiprimeD1StackProductCheckCompute.computeBudget\n  rw [hv]\n  have huM : cached.length≤u := by dsimp [u];omega\n  omega\n\n/-- Actual completed checker trace with a fixed physical-input cubic clock. -/\ntheorem source_run_bounded (raw cached : List Bool) :\n    ∃t≤runBound raw cached,C.run program t (initial raw cached)=some (done raw cached) := by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackProductCheckExecution.source_run raw cached\n  exact ⟨t,ht.trans (timeBound_le raw cached),hr⟩\n/-- A proof-side trace choice, never an executing elapsed-count operand. -/\nnoncomputable def sourceCheck (raw cached : List Bool) :\n    StateTransition.EvalsToInTime (C.step program) (initial raw cached) (some (done raw cached)) (runBound raw cached) := by\n  let h:=source_run_bounded raw cached\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\n/-- The genuine fixed FinTM2 has the SAME whole input/output/clock theorem. -/\nnoncomputable def machineCheck (raw cached : List Bool) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial raw cached))\n      (some (SemiprimeD1StackCalls.configuration (done raw cached))) (runBound raw cached) :=\n  SemiprimeD1StackCalls.evalsCorrect rawInput output Label.start program _ _ _ (sourceCheck raw cached)\n\n/-- Every successful prefix lies before the actual complete halt. -/\ntheorem prefix_fuel_le (raw cached : List Bool) (fuel : ℕ) (out : C.State Stack Label)\n    (hr : C.run program fuel (initial raw cached)=some out) : fuel≤runBound raw cached := by\n  obtain ⟨t,ht,hh⟩:=source_run_bounded raw cached\n  have hf : fuel≤t := by\n    by_contra hn\n    have he : fuel=t+(1+(fuel-(t+1))) := by omega\n    rw [he,SemiprimeD1StackReturnLink.run_add,hh,Option.bind_some,SemiprimeD1StackReturnLink.run_add] at hr\n    have hz : C.run program 1 (done raw cached)=none := rfl\n    rw [hz,Option.bind_none] at hr\n    cases hr\n  exact hf.trans ht\n/-- All48 Boolean stack roles AND every real return label are counted at EVERY\nactual prefix, including the retained original input/cache/unread suffix. -/\ntheorem prefix_cells (raw cached : List Bool) (fuel : ℕ) (out : C.State Stack Label)\n    (hr : C.run program fuel (initial raw cached)=some out) :\n    (∑k : Stack,(out.data k).length)+out.frames.length≤\n      49*(raw.length+cached.length+runBound raw cached) := by\n  let I:=raw.length+cached.length\n  have hi : ∀k,((initial raw cached).data k).length≤I := by\n    intro k\n    change (input raw cached k).length≤I\n    unfold input\n    split\n    · dsimp [I];omega\n    · split\n      · dsimp [I];omega\n      · exact Nat.zero_le _\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel I _ out hi hr\n  have ht:=prefix_fuel_le raw cached fuel out hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ out hr\n  change out.frames.length≤0+fuel at hf\n  have hs : (∑k : Stack,(out.data k).length)≤48*(I+fuel) := by\n    calc\n      _ ≤ ∑_k : Stack,(I+fuel) := Finset.sum_le_sum (fun k _=>hd k)\n      _ = _ := by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  change _≤49*(I+runBound raw cached)\n  omega\n/-- Same complete inventory on the actual finite machine configuration. -/\ntheorem machine_prefix_cells (raw cached : List Bool) (fuel : ℕ) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial raw cached)))=some cfg) :\n    (∑k : Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤\n      49*(raw.length+cached.length+runBound raw cached) := by\n  have he:=SemiprimeD1StackCalls.run_correct rawInput output Label.start program fuel (initial raw cached)\n  change (C.run program fuel (initial raw cached)).map SemiprimeD1StackCalls.configuration=\n    (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial raw cached))) at he\n  have hh:=he.trans hr\n  cases hc:C.run program fuel (initial raw cached) with\n  | none => rw [hc] at hh;cases hh\n  | some out =>\n    rw [hc] at hh\n    have hcfg : SemiprimeD1StackCalls.configuration out=cfg := Option.some.inj hh\n    subst cfg\n    exact prefix_cells raw cached fuel out hc\n\nend RiemannGaussian.SemiprimeD1StackProductCheckBounds\n","RiemannGaussian.SemiprimeD1StackProductRecordBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackProductRecordExecution\n/-! # Closed product record clock and every actual physical prefix cell -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option synthInstance.maxSize 16384\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeD1StackProductRecordBounds\nopen SemiprimeD1StackProductRecord SemiprimeD1StackProductRecordExecution\n/-- Initial storage accounts for original N, the acquired bank and both accumulators. -/\ndef inputSize (bits bank hist out : List Bool) : Nat := bits.length+bank.length+hist.length+out.length\n/-- Every initial role, including both unused shadows, has an actual input-byte bound. -/\ntheorem initial_data_bound (bits bank hist out : List Bool) (k : Stack) :\n    ((initial bits bank hist out).data k).length≤ inputSize bits bank hist out := by\n  have hz (j : Z.Stack) : ((Z.initial bits).data j).length≤bits.length :=\n    SemiprimeD1StackProductTableBootstrap.initial_length bits j\n  have hs (j : S.Stack) : ((S.initial bank).data j).length≤bank.length := by\n    change (if j=SemiprimeD1StackPortOrdinalStream.Stack.bank then bank else []).length≤_\n    split <;> simp\n  rcases k with k|k\n  · have h:=hz k;change ((Z.initial bits).data k).length≤_;unfold inputSize;omega\n  · cases k with\n    | inl k => have h:=hs k;change ((S.initial bank).data k).length≤_;unfold inputSize;omega\n    | inr k => cases k <;> simp [initial,data,R.data,inputSize];omega\n/-- A real successful whole-source halt bounds all possible executed prefixes. -/\ntheorem prefix_fuel_le (bits : List Bool) (hb : bits≠[]) (words : List (List Bool))\n    (hist out : List Bool) (fuel : Nat) (finish : C.State Stack Label)\n    (hr : C.run program fuel (initial bits (SemiprimeD1TensorTapeCodec.vectorBits words) hist out)=some finish) :\n    fuel≤timeBound bits words := by\n  obtain ⟨t,ht,he⟩:=source_run bits hb words hist out\n  have hf:fuel≤t := by\n    by_contra hn\n    have h:fuel=t+(1+(fuel-(t+1))) := by omega\n    rw [h,SemiprimeD1StackReturnLink.run_add,he,Option.bind_some,SemiprimeD1StackReturnLink.run_add] at hr\n    have hz:C.run program 1 (done bits words hist out)=none:=rfl\n    rw [hz,Option.bind_none] at hr\n    cases hr\n  exact hf.trans ht\n/-- All99 roles, both unused alias shadows and all real nested return cells are counted. -/\ntheorem prefix_cells (bits : List Bool) (hb : bits≠[]) (words : List (List Bool))\n    (hist out : List Bool) (fuel : Nat) (finish : C.State Stack Label)\n    (hr : C.run program fuel (initial bits (SemiprimeD1TensorTapeCodec.vectorBits words) hist out)=some finish) :\n    (∑k:Stack,(finish.data k).length)+finish.frames.length≤\n      100*(inputSize bits (SemiprimeD1TensorTapeCodec.vectorBits words) hist out+timeBound bits words+1) := by\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel\n    (inputSize bits (SemiprimeD1TensorTapeCodec.vectorBits words) hist out) _ finish\n    (initial_data_bound bits (SemiprimeD1TensorTapeCodec.vectorBits words) hist out) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ finish hr\n  change finish.frames.length≤0+fuel at hf\n  have hs:(∑k:Stack,(finish.data k).length)≤\n      99*(inputSize bits (SemiprimeD1TensorTapeCodec.vectorBits words) hist out+fuel) := by\n    calc\n      _≤∑_k:Stack,(inputSize bits (SemiprimeD1TensorTapeCodec.vectorBits words) hist out+fuel):=\n        Finset.sum_le_sum (fun k _=>hd k)\n      _= _:=by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  have ht:=prefix_fuel_le bits hb words hist out fuel finish hr\n  omega\n/-- Same complete prefix inventory in the actual compiled finite-control machine. -/\ntheorem machine_prefix_cells (bits : List Bool) (hb : bits≠[]) (words : List (List Bool))\n    (hist out : List Bool) (fuel : Nat) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration\n        (initial bits (SemiprimeD1TensorTapeCodec.vectorBits words) hist out)))=some cfg) :\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤\n      100*(inputSize bits (SemiprimeD1TensorTapeCodec.vectorBits words) hist out+timeBound bits words+1) := by\n  have he:=SemiprimeD1StackCalls.run_correct original output (.inl .start) program fuel\n    (initial bits (SemiprimeD1TensorTapeCodec.vectorBits words) hist out)\n  change (C.run program fuel (initial bits (SemiprimeD1TensorTapeCodec.vectorBits words) hist out)).map\n    SemiprimeD1StackCalls.configuration=\n      (fun q:Option machine.Cfg=>q.bind machine.step)^[fuel]\n        (some (SemiprimeD1StackCalls.configuration\n          (initial bits (SemiprimeD1TensorTapeCodec.vectorBits words) hist out))) at he\n  have hh:(C.run program fuel (initial bits (SemiprimeD1TensorTapeCodec.vectorBits words) hist out)).map\n      SemiprimeD1StackCalls.configuration=some cfg:=he.trans hr\n  cases hrun:C.run program fuel (initial bits (SemiprimeD1TensorTapeCodec.vectorBits words) hist out) with\n  | none => rw [hrun] at hh;cases hh\n  | some finish =>\n    rw [hrun] at hh\n    have hc:SemiprimeD1StackCalls.configuration finish=cfg:=Option.some.inj hh\n    subst cfg\n    exact prefix_cells bits hb words hist out fuel finish hrun\n/-- Actual internal flags, including remembered return labels, are finite. -/\ntheorem control_finite : Finite machine.σ :=\n  SemiprimeD1StackCalls.control_finite original output (.inl .start) program\n/-- Every actual alphabet is finite, including the real return-stack alphabet. -/\ntheorem all_alphabets_finite (k : machine.K) : Finite (machine.Γ k) :=\n  SemiprimeD1StackCalls.all_alphabets_finite original output (.inl .start) program k\n/-- At most four fundamental commands implement each actually compiled instruction. -/\ntheorem compile_depth (pc : Label) :\n    SemiprimeD1StackBytecode.statementDepth (machine.m pc)≤4 :=\n  (SemiprimeD1StackCalls.compile_depth (.inl .start : Label) (program pc))\n/-- Every actual branch, scalar leaf and word-framing byte is included. -/\ntheorem table_length (bits : List Bool) :\n    (table bits).length+1≤7*2^(SemiprimeD1StackProductTableSpec.arity bits) :=\n  SemiprimeD1StackProductTableBounds.tree_length bits [] _\n/-- The old unary field is bounded only by actual metadata values, including ID zero. -/\ntheorem ports_length (words : List (List Bool)) (M : Nat)\n    (hv : ∀w∈words,SemiprimeBitArithmetic.bitValue w≤M) :\n    (S.result words).length≤words.length*(2*M+2)+1 := by\n  have h:=SemiprimeD1StackPortOrdinalStreamBounds.bank_length\n    (SemiprimeD1StackPortOrdinalStreamExecution.unaryWords words) M (by\n      intro w hw\n      obtain ⟨v,hv',rfl⟩:=List.mem_map.mp hw\n      simpa only [List.length_replicate] using hv v hv')\n  simpa only [S.result,SemiprimeD1StackPortOrdinalStreamExecution.unaryWords,List.length_map] using h\n/-- Whole real clock: public acquisition once, full table output, binary padding,\nactual unary metadata conversion and every record framing bit. -/\ntheorem timeBound_le (bits : List Bool) (words : List (List Bool)) (M : Nat)\n    (hl : ∀w∈words,w.length≤M) (hv : ∀w∈words,SemiprimeBitArithmetic.bitValue w≤M) :\n    timeBound bits words≤SemiprimeD1StackProductTableBounds.runBound bits+\n      21*2^(SemiprimeD1StackProductTableSpec.arity bits)+\n      110*(words.length+1)*(M+1)+20 := by\n  have hs:=SemiprimeD1StackPortOrdinalStreamBounds.timeBound_le words M hl hv\n  have hp:=ports_length words M hv\n  have ht:=table_length bits\n  have hz:=SemiprimeD1StackProductTableBounds.timeBound_le bits\n  unfold timeBound R.recordTime\n  nlinarith\nend RiemannGaussian.SemiprimeD1StackProductRecordBounds\n","RiemannGaussian.SemiprimeD1StackPublicInputBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicInputExecution\n\n/-! # Whole actual public input checker: quadratic clock and all-prefix memory\nThe bound is derived from the actual SAME-source header/copy/block/branch trace,\nnot from the original checker report or the pure semantic specification.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option synthInstance.maxSize 8192\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeD1StackPublicInputBounds\nopen SemiprimeD1StackPublicInput SemiprimeD1StackPublicInputState SemiprimeD1StackPublicInputExecution\n\n/-- The actual original word obtained by the paid fixed-width extraction. -/\ntheorem word_length (bits raw : List Bool) : (M.word bits raw).length=(M.cached bits).length :=\n  SemiprimeD1StackWordBlockExecution.result_length raw (M.cached bits)\n/-- Actual acquired bound bytes fit within the actual retained template width. -/\ntheorem bound_length_le (bits indexWord : List Bool) :\n    (M.actualBound bits indexWord).length≤(M.cached bits).length := by\n  have h:=SemiprimeD1StackInputWidthBounds.width_le_radix (SemiprimeD1StackPublicInputWidthExecution.cache bits indexWord)\n  have hb:=SemiprimeD1StackPublicInputWidthBounds.cache_lengths bits indexWord\n  rw [hb.2.1] at h\n  rw [SemiprimeD1StackPublicInputMeaning.actualBound,SemiprimeD1StackInputWidthBounds.bound_length,\n    SemiprimeD1StackPublicZeroBounds.cached_length]\n  unfold SemiprimeMacroParameters.radixBits at h\n  omega\n/-- Fixed whole-program polynomial before all original input/index/assignment bits. -/\ndef runBound (bits raw indexWord : List Bool) : ℕ := 1000000000000*(bits.length+raw.length+indexWord.length+2)^2\n/-- EVERY actual source call, guard, flag read, data-copy/cleanup and real\nreturn is included; canonicality and the Boolean verdict are never premises. -/\ntheorem timeBound_le (bits raw indexWord : List Bool) : timeBound bits raw indexWord≤runBound bits raw indexWord := by\n  let I:=bits.length+raw.length+indexWord.length+2\n  have hI : 1≤I := by dsimp [I];omega\n  have hi : I≤I^2 := by simpa only [pow_one] using Nat.pow_le_pow_right hI (by decide : 1≤2)\n  have hh:=SemiprimeD1StackPublicInputWidthBounds.timeBound_le bits indexWord\n  have hp : (bits.length+indexWord.length+2)^2≤I^2 := Nat.pow_le_pow_left (by dsimp [I];omega) 2\n  unfold SemiprimeD1StackPublicInputWidthBounds.runBound at hh\n  have hc : (M.cached bits).length≤66*I := by\n    have h:=SemiprimeD1StackPublicZeroBounds.cached_length_le bits\n    change (M.cached bits).length≤66*(bits.length+1) at h\n    dsimp [I];omega\n  have hb:=bound_length_le bits indexWord\n  have hr : raw.length≤I := by dsimp [I];omega\n  unfold timeBound bodyBound\n  rw [SemiprimeD1StackWordBlockBounds.totalTime_eq,word_length]\n  change _≤1000000000000*I^2\n  omega\n/-- Complete SAME actual source run with its fixed whole-input quadratic clock. -/\ntheorem source_run_bounded (bits raw indexWord : List Bool) (hb : bits≠[]) :\n    ∃t≤runBound bits raw indexWord,C.run program t (initial bits raw indexWord)=some (done bits raw indexWord) := by\n  obtain ⟨t,ht,hr⟩:=source_run bits raw indexWord hb\n  exact ⟨t,ht.trans (timeBound_le bits raw indexWord),hr⟩\n/-- Proof-only choice of an actual proved trace, never an executing cost oracle. -/\nnoncomputable def sourceCheck (bits raw indexWord : List Bool) (hb : bits≠[]) :\n    StateTransition.EvalsToInTime (C.step program) (initial bits raw indexWord)\n      (some (done bits raw indexWord)) (runBound bits raw indexWord) := by\n  let h:=source_run_bounded bits raw indexWord hb\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\n/-- The genuine fixed52-role machine has the SAME complete actual input/output clock. -/\nnoncomputable def machineCheck (bits raw indexWord : List Bool) (hb : bits≠[]) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial bits raw indexWord))\n      (some (SemiprimeD1StackCalls.configuration (done bits raw indexWord))) (runBound bits raw indexWord) :=\n  SemiprimeD1StackCalls.evalsCorrect (.inl H.original) output Label.start program _ _ _ (sourceCheck bits raw indexWord hb)\n/-- All successful actual prefixes lie before the complete bounded halt. -/\ntheorem prefix_fuel_le (bits raw indexWord : List Bool) (hb : bits≠[]) (fuel : ℕ) (out : C.State Stack Label)\n    (hr : C.run program fuel (initial bits raw indexWord)=some out) : fuel≤runBound bits raw indexWord := by\n  obtain ⟨t,ht,hh⟩:=source_run_bounded bits raw indexWord hb\n  have hf : fuel≤t := by\n    by_contra hn\n    have he : fuel=t+(1+(fuel-(t+1))) := by omega\n    rw [he,SemiprimeD1StackReturnLink.run_add,hh,Option.bind_some,SemiprimeD1StackReturnLink.run_add] at hr\n    have hz : C.run program 1 (done bits raw indexWord)=none := rfl\n    rw [hz,Option.bind_none] at hr\n    cases hr\n  exact hf.trans ht\n/-- Initial storage consists only of actual original N/index/raw input bytes. -/\ntheorem initial_length (bits raw indexWord : List Bool) (k : Stack) :\n    ((initial bits raw indexWord).data k).length≤bits.length+raw.length+indexWord.length := by\n  rcases k with k|k\n  · have h:=SemiprimeD1StackPublicInputWidthBounds.initial_length bits indexWord k\n    change (SemiprimeD1StackPublicInputWidth.input bits indexWord k).length≤bits.length+raw.length+indexWord.length\n    change (SemiprimeD1StackPublicInputWidth.input bits indexWord k).length≤bits.length+indexWord.length at h\n    omega\n  · rcases k with k|k\n    · exact Nat.zero_le _\n    · rcases k with k|k\n      · exact Nat.zero_le _\n      · rcases k with k|k\n        · exact Nat.zero_le _\n        · cases k;change raw.length≤bits.length+raw.length+indexWord.length;omega\n/-- EVERY prefix includes ALL52 Boolean data roles, every actual public cache/\nindex/raw/suffix, all guard/flag/word work AND every actual return-label cell. -/\ntheorem prefix_cells (bits raw indexWord : List Bool) (hb : bits≠[]) (fuel : ℕ) (out : C.State Stack Label)\n    (hr : C.run program fuel (initial bits raw indexWord)=some out) :\n    (∑k : Stack,(out.data k).length)+out.frames.length≤100000000000000*(bits.length+raw.length+indexWord.length+2)^2 := by\n  let I:=bits.length+raw.length+indexWord.length\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel I _ out (initial_length bits raw indexWord) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ out hr\n  change out.frames.length≤0+fuel at hf\n  have hs : (∑k : Stack,(out.data k).length)≤52*(I+fuel) := by\n    calc\n      _ ≤ ∑_k : Stack,(I+fuel) := Finset.sum_le_sum (fun k _=>hd k)\n      _ = _ := by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  have ht:=prefix_fuel_le bits raw indexWord hb fuel out hr\n  change fuel≤1000000000000*(I+2)^2 at ht\n  have hI : I≤(I+2)^2 := by\n    have h:=Nat.pow_le_pow_right (by omega : 1≤I+2) (by decide : 1≤2)\n    simp only [pow_one] at h\n    omega\n  change _≤100000000000000*(I+2)^2\n  omega\n/-- The SAME all-prefix physical inventory on the actual compiled bit machine. -/\ntheorem machine_prefix_cells (bits raw indexWord : List Bool) (hb : bits≠[]) (fuel : ℕ) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial bits raw indexWord)))=some cfg) :\n    (∑k : Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤\n      100000000000000*(bits.length+raw.length+indexWord.length+2)^2 := by\n  have he:=SemiprimeD1StackCalls.run_correct (.inl H.original) output Label.start program fuel (initial bits raw indexWord)\n  change (C.run program fuel (initial bits raw indexWord)).map SemiprimeD1StackCalls.configuration=\n    (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial bits raw indexWord))) at he\n  have hh:=he.trans hr\n  cases hc:C.run program fuel (initial bits raw indexWord) with\n  | none=>rw [hc] at hh;cases hh\n  | some out=>\n    rw [hc] at hh\n    have hcfg : SemiprimeD1StackCalls.configuration out=cfg := Option.some.inj hh\n    subst cfg\n    exact prefix_cells bits raw indexWord hb fuel out hc\nend RiemannGaussian.SemiprimeD1StackPublicInputBounds\n","RiemannGaussian.SemiprimeD1StackPublicInputTableOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicInputTableExecution\nimport RiemannGaussian.SemiprimeD1ZeroBoundaryTables\n/-! # Entire original input-family tensor, active/inactive and both sides\nScope routing/acquisition remains explicit caller work. Once its acquired\nscope has the original arity, the SAME fixed116-role compiler produces the\nENTIRE old tensor in its unchanged original local-port order.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1600000\nset_option maxRecDepth 100000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackPublicInputTableOriginal\nopen SemiprimeD1StackPublicInputTable SemiprimeD1StackPublicInputTableTrace\nopen SemiprimeD1StackPublicInputTableExecution\nopen SemiprimeMacroParameters SemiprimeBitArithmetic\nnamespace T\nexport SemiprimeD1StackStaticTableSpec (leafWords tree tree_entry)\nend T\n/-- Every original finite assignment has its actual original checker0/1\ncoefficient word, for ALL active/inactive input positions and either side. -/\ntheorem leaf_original (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits)\n    (side : Fin 2) (i : Fin (firstAxis (bitLength (bitValue bits))*secondAxis (bitLength (bitValue bits))))\n    (indexWord : List Bool) (hi : indexWord.length=i.val)\n    (input : Fin (SemiprimeMacroGraph.arity (.input side i : SemiprimeMacroGraph.Vertex\n      (firstAxis (bitLength (bitValue bits))) (secondAxis (bitLength (bitValue bits)))\n      (digitCount (bitLength (bitValue bits)))))→Bool) :\n    T.leafWords (answer bits indexWord) (List.ofFn input)=\n      [if (SemiprimeMacroEntryBitCheck.publicBitEntry (bitValue bits) hN (.input side i) input).accepted\n        then [true] else []] := by\n  unfold T.leafWords answer\n  rw [SemiprimeD1StackPublicInputMeaning.expected_original bits hc hN side i indexWord hi input]\n/-- ENTIRE old original input tensor, no permutation and no subset of assignments.\nThe arity equality is a proof about the physically acquired caller scope only. -/\ntheorem table_original (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits)\n    (side : Fin 2) (i : Fin (firstAxis (bitLength (bitValue bits))*secondAxis (bitLength (bitValue bits))))\n    (indexWord : List Bool) (hi : indexWord.length=i.val) (words : List (List Bool))\n    (hlen : words.length=SemiprimeMacroGraph.subdividedArity\n      (.inl (.input side i):SemiprimePublicAcquiredExecution.PublicVertex (bitValue bits))) :\n    table bits indexWord words=SemiprimeD1TensorTapeCodec.tape\n      (SemiprimeD1BooleanRootTablesOriginal.reference (bitValue bits) hN (.inl (.input side i))) := by\n  unfold table SemiprimeD1StackStaticTableExecution.outputTape\n  rw [hlen]\n  apply congrArg SemiprimeD1TensorTapeCodec.tape\n  apply SemiprimeD1ZeroBoundaryTables.table_ext\n  intro input\n  rw [T.tree_entry,List.nil_append]\n  dsimp only [SemiprimeD1BooleanRootTablesOriginal.reference]\n  rw [SemiprimeD1ZeroBoundaryTables.build_entry]\n  have hget:(fun j=>((List.ofFn input).toArray[j.val]?).getD false)=input:=by\n    funext j\n    simp only [List.getElem?_toArray,List.getElem?_ofFn,j.isLt,dite_true,Option.getD_some]\n  change T.leafWords (answer bits indexWord) (List.ofFn input)=\n    [if (SemiprimeMacroEntryBitCheck.publicBitEntry (bitValue bits) hN (.input side i)\n      (fun j=>((List.ofFn input).toArray[j.val]?).getD false)).accepted then [true] else []]\n  have he:=congrArg (fun f=>[if (SemiprimeMacroEntryBitCheck.publicBitEntry\n    (bitValue bits) hN (.input side i) f).accepted then [true] else []]) hget\n  exact (leaf_original bits hc hN side i indexWord hi input).trans he.symm\n/-- The ACTUAL acquired output role, rather than an advised specification tape,\nis exactly the frozen complete original input table. -/\ntheorem output_original (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits)\n    (side : Fin 2) (i : Fin (firstAxis (bitLength (bitValue bits))*secondAxis (bitLength (bitValue bits))))\n    (indexWord : List Bool) (hi : indexWord.length=i.val) (words : List (List Bool))\n    (hlen : words.length=SemiprimeMacroGraph.subdividedArity\n      (.inl (.input side i):SemiprimePublicAcquiredExecution.PublicVertex (bitValue bits))) :\n    (done bits indexWord words).data (SemiprimeD1StackStaticTable.aux .output)=\n      SemiprimeD1TensorTapeCodec.tape\n        (SemiprimeD1BooleanRootTablesOriginal.reference (bitValue bits) hN (.inl (.input side i))) :=\n  (output_table bits indexWord words).trans (table_original bits hc hN side i indexWord hi words hlen)\n/-- EACH individual entry's actual integral coefficient is the original0/1\nindicator BEFORE any network product, contraction or precision reduction. -/\ntheorem literal_original_coefficient (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits)\n    (hN : 0<bitValue bits) (side : Fin 2)\n    (i : Fin (firstAxis (bitLength (bitValue bits))*secondAxis (bitLength (bitValue bits))))\n    (indexWord : List Bool) (hi : indexWord.length=i.val)\n    (input : Fin (SemiprimeMacroGraph.arity (.input side i : SemiprimeMacroGraph.Vertex\n      (firstAxis (bitLength (bitValue bits))) (secondAxis (bitLength (bitValue bits)))\n      (digitCount (bitLength (bitValue bits)))))→Bool) :\n    SemiprimeD1JetAlgebra.coefficient (SemiprimeD1JetBoxIndex.dims [])\n      (SemiprimeD1JetBoxIndex.exponent [] 0)\n      (SemiprimeD1JetBoxIndex.exponent_inBox [] 0 (by simp) (by decide))\n      (SemiprimeD1JetLiteralLift.literal [] (T.leafWords (answer bits indexWord) (List.ofFn input)))=\n      if (SemiprimeMacroEntryBitCheck.publicBitEntry (bitValue bits) hN (.input side i) input).accepted\n        then 1 else 0 := by\n  rw [SemiprimeD1JetLiteralLift.literal_coefficient [] _ (by simp) 0 (by decide),\n    leaf_original bits hc hN side i indexWord hi input]\n  cases (SemiprimeMacroEntryBitCheck.publicBitEntry (bitValue bits) hN (.input side i) input).accepted <;>\n    simp [bitValue,bitNat]\n/-- Arbitrary precision reduces this SAME actual individual integral entry.\nNo upward modular map or lifted aggregate replaces any local coefficient. -/\ntheorem literal_entry_reduce (bits indexWord raw : List Bool) (p : Nat) :\n    SemiprimeD1JetScalarMap.scalarMap (SemiprimeD1JetBoxIndex.dims [])\n      (SemiprimeD1DyadicInteger.reduction p)\n      (SemiprimeD1JetLiteralLift.literal [] (T.leafWords (answer bits indexWord) raw))=\n      SemiprimeD1JetInterpretation.interpret ⟨[],p⟩ (T.leafWords (answer bits indexWord) raw) :=\n  SemiprimeD1JetLiteralLift.literal_reduce [] p _\nend RiemannGaussian.SemiprimeD1StackPublicInputTableOriginal\n","RiemannGaussian.SemiprimeD1StackPublicProductFinite":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicProductBounds\nimport RiemannGaussian.SemiprimeD1StackWordVectorFinite\n\n/-! # All original product vertices, all assignments, original bit time\nOnly finite proof casts identify the original input-before-output,\nword-before-bit coordinates. The executed program acquires the metadata,\nmodulus, vector and operands itself from original N and literal raw bytes.\n-/\nset_option autoImplicit false\nset_option synthInstance.maxSize 4096\nset_option maxHeartbeats 1200000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackPublicProductFinite\nopen SemiprimeD1StackPublicProduct SemiprimeD1StackPublicProductExecution\nopen SemiprimeD1StackProductCheckParse SemiprimeD1StackProductCheckMeaning\nopen SemiprimeMacroGraph SemiprimeMacroEntryBitCheck SemiprimeMacroParameters SemiprimeBitArithmetic\n\n/-- Equal-width little-endian words are determined by their integer values. -/\ntheorem words_eq {xs ys : List Bool} (hl : xs.length=ys.length) (hv : bitValue xs=bitValue ys) : xs=ys := by\n  induction xs generalizing ys with\n  | nil=>cases ys <;> simp_all\n  | cons b xs ih=>\n    cases ys with\n    | nil=>simp at hl\n    | cons c ys=>\n      have ht : xs.length=ys.length := by simpa only [List.length_cons,Nat.add_right_cancel_iff] using hl\n      cases b <;> cases c <;> simp only [bitValue,bitNat,Bool.false_eq_true,ite_false,ite_true] at hv\n      · exact congrArg (List.cons false) (ih ht (by omega))\n      · omega\n      · omega\n      · exact congrArg (List.cons true) (ih ht (by omega))\n/-- The ACTUALLY acquired modulus is exactly the old original word, not an\nassumed interpretation or canonicality answer. -/\ntheorem original_modulus (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits) :\n    cached bits=modulus (SemiprimePublicFactorCount.publicConfig (bitValue bits) hN) := by\n  let p:=SemiprimePublicFactorCount.publicConfig (bitValue bits) hN\n  have hp:=(SemiprimeD1StackRootSourceOriginal.original_parameters bits hc hN).1\n  apply words_eq\n  · rw [SemiprimeD1StackPublicProductBounds.cached_length,modulus_length,hp]\n  · change bitValue (SemiprimeD1StackFermatWords.modulusWord (transformLength bits.length))=_\n    rw [SemiprimeD1StackFermatWords.modulus_value _ (by unfold transformLength;positivity),modulus_value,hp,p.shape]\n/-- Exact original public graph width, derived from the actual acquisition. -/\ntheorem public_width (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) :\n    (cached bits).length=firstAxis (bitLength (bitValue bits))*secondAxis (bitLength (bitValue bits))+1 := by\n  rw [SemiprimeD1StackPublicProductBounds.cached_length,\n    SemiprimeD1BinaryDigitAcquisitionBounds.canonical_width bits hc,axes_product]\n/-- Exact three-word arity of every original product vertex. -/\ntheorem product_arity {r t digits : ℕ} (k : Fin (r*t)) :\n    arity (Vertex.product (r:=r) (t:=t) (digits:=digits) k)=3*(r*t+1) := by simp only [arity];ring\n/-- Proof-side original indexed word; the runtime has no indexed-word getter. -/\ndef indexedWord (width : List Bool) (input : Fin (3*width.length)→Bool) (j : Fin 3) : List Bool :=\n  List.ofFn (fun b : Fin width.length=>input (finProdFinEquiv (j,b)))\n/-- The real grouped raw blocks match the original finite-product bit order. -/\ntheorem words_original (width : List Bool) (input : Fin (3*width.length)→Bool) :\n    first (List.ofFn input) width=indexedWord width input 0 ∧\n    second (List.ofFn input) width=indexedWord width input 1 ∧\n    third (List.ofFn input) width=indexedWord width input 2 := by\n  have h:=SemiprimeD1StackWordVectorFinite.blocks_ofFn width (show 3≤3 from le_rfl) input\n  change [first (List.ofFn input) width,second (List.ofFn input) width,third (List.ofFn input) width]=\n    [indexedWord width input 0,indexedWord width input 1,indexedWord width input 2] at h\n  simpa only [List.cons.injEq,and_true] using h\n/-- Finite proof cast changes no original assignment byte or order. -/\ndef originalInput (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits)\n    (k : Fin (firstAxis (bitLength (bitValue bits))*secondAxis (bitLength (bitValue bits))))\n    (input : Fin (arity (Vertex.product (digits:=digitCount (bitLength (bitValue bits))) k))→Bool) :\n    Fin (3*(cached bits).length)→Bool := fun j=>input ⟨j.val,by\n      rw [product_arity,←public_width bits hc];exact j.isLt⟩\n/-- Every actually acquired word is the original product vertex's local word. -/\ntheorem public_words (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits)\n    (k : Fin (firstAxis (bitLength (bitValue bits))*secondAxis (bitLength (bitValue bits))))\n    (input : Fin (arity (Vertex.product (digits:=digitCount (bitLength (bitValue bits))) k))→Bool) :\n    indexedWord (cached bits) (originalInput bits hc k input) 0=\n      localWord (fun b=>input (localSlotFinEquiv (.product k) (.inl (0,b)))) ∧\n    indexedWord (cached bits) (originalInput bits hc k input) 1=\n      localWord (fun b=>input (localSlotFinEquiv (.product k) (.inl (1,b)))) ∧\n    indexedWord (cached bits) (originalInput bits hc k input) 2=\n      localWord (fun b=>input (localSlotFinEquiv (.product k) (.inr b))) := by\n  have hw:=public_width bits hc\n  constructor\n  · apply List.ext_getElem\n    · simpa only [indexedWord,localWord,SemiprimeMacroEntryBitPrimitives.portBits,List.length_ofFn] using hw\n    · intro i hi hi'\n      simp only [indexedWord,localWord,SemiprimeMacroEntryBitPrimitives.portBits,List.getElem_ofFn,originalInput]\n      congr 1\n  constructor\n  · apply List.ext_getElem\n    · simpa only [indexedWord,localWord,SemiprimeMacroEntryBitPrimitives.portBits,List.length_ofFn] using hw\n    · intro i hi hi'\n      simp only [indexedWord,localWord,SemiprimeMacroEntryBitPrimitives.portBits,List.getElem_ofFn,originalInput]\n      congr 1\n      apply Fin.ext\n      simp only [localSlotFinEquiv,finProdFinEquiv]\n      change i+(cached bits).length*1=i+(_+1)*1\n      rw [hw]\n  · apply List.ext_getElem\n    · simpa only [indexedWord,localWord,SemiprimeMacroEntryBitPrimitives.portBits,List.length_ofFn] using hw\n    · intro i hi hi'\n      simp only [indexedWord,localWord,SemiprimeMacroEntryBitPrimitives.portBits,List.getElem_ofFn,originalInput]\n      congr 1\n      apply Fin.ext\n      simp only [localSlotFinEquiv]\n      change i+(cached bits).length*2=2*(_+1)+i\n      rw [hw]\n      omega\n/-- The finite proof cast is byte-for-byte the same actual raw assignment. -/\ntheorem original_raw (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits)\n    (k : Fin (firstAxis (bitLength (bitValue bits))*secondAxis (bitLength (bitValue bits))))\n    (input : Fin (arity (Vertex.product (digits:=digitCount (bitLength (bitValue bits))) k))→Bool) :\n    List.ofFn (originalInput bits hc k input)=List.ofFn input := by\n  apply List.ext_getElem\n  · simp only [List.length_ofFn,product_arity,public_width bits hc]\n  · intro i hi hi';simp only [List.getElem_ofFn,originalInput]\n/-- ENTIRE original public product checker, for ALL original indices and ALL\nfinite assignments; modulus, guards and every operand are actually acquired. -/\ntheorem public_original (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits)\n    (k : Fin (firstAxis (bitLength (bitValue bits))*secondAxis (bitLength (bitValue bits))))\n    (input : Fin (arity (Vertex.product (digits:=digitCount (bitLength (bitValue bits))) k))→Bool) :\n    SemiprimeD1StackProductCheckExecution.answer (List.ofFn input) (cached bits)=\n      (publicBitEntry (bitValue bits) hN (.product k) input).accepted := by\n  rw [←original_raw bits hc k input]\n  let p:=SemiprimePublicFactorCount.publicConfig (bitValue bits) hN\n  have he:=old_product p (List.ofFn (originalInput bits hc k input))\n  rw [←original_modulus bits hc hN] at he\n  rw [he]\n  obtain ⟨a,b,c⟩:=words_original (cached bits) (originalInput bits hc k input)\n  obtain ⟨x,y,z⟩:=public_words bits hc k input\n  have ha:=a.trans x\n  have hb:=b.trans y\n  have hcWord:=c.trans z\n  have hi : inputWords (List.ofFn (originalInput bits hc k input)) (cached bits)=\n      fun j : Fin 2=>localWord (fun bit=>input (localSlotFinEquiv (.product k) (.inl (j,bit)))) := by\n    funext j\n    fin_cases j\n    · exact ha\n    · exact hb\n  rw [hi,ha,hb,hcWord,publicBitEntry_correct]\n  exact entryRun_correct p (configTargets p) (.product k) input\n/-- Literal output singleton equals the ORIGINAL public checker on every input. -/\ntheorem output_original (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits)\n    (k : Fin (firstAxis (bitLength (bitValue bits))*secondAxis (bitLength (bitValue bits))))\n    (input : Fin (arity (Vertex.product (digits:=digitCount (bitLength (bitValue bits))) k))→Bool) :\n    (done bits (List.ofFn input)).data output=[(publicBitEntry (bitValue bits) hN (.product k) input).accepted] := by\n  rw [output_answer,public_original bits hc hN k input]\n/-- Original all-assignment input inventory is linear in original binary width. -/\ntheorem original_inventory (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits)\n    (k : Fin (firstAxis (bitLength (bitValue bits))*secondAxis (bitLength (bitValue bits))))\n    (input : Fin (arity (Vertex.product (digits:=digitCount (bitLength (bitValue bits))) k))→Bool) :\n    bits.length+(List.ofFn input).length+2≤210*(bitLength (bitValue bits)+1) := by\n  rw [List.length_ofFn,product_arity,←public_width bits hc]\n  have h:=SemiprimeD1StackPublicProductBounds.cached_length_le bits\n  rw [SemiprimeD1BinaryDigitAcquisitionBounds.canonical_width bits hc] at h ⊢\n  omega\n/-- Whole actual original product-query time, uniformly before every N/index/\nassignment. No old checker report or callback clock has been substituted. -/\ntheorem original_time (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits)\n    (k : Fin (firstAxis (bitLength (bitValue bits))*secondAxis (bitLength (bitValue bits))))\n    (input : Fin (arity (Vertex.product (digits:=digitCount (bitLength (bitValue bits))) k))→Bool) :\n    SemiprimeD1StackPublicProductBounds.runBound bits (List.ofFn input)≤100000000000000000000*(bitLength (bitValue bits)+1)^3 := by\n  have h:=Nat.pow_le_pow_left (original_inventory bits hc k input) 3\n  rw [mul_pow] at h\n  norm_num at h\n  unfold SemiprimeD1StackPublicProductBounds.runBound\n  simp only [List.length_ofFn]\n  omega\n/-- SAME genuine machine, complete source trace and fixed original bitlength\nclock for every product index and finite assignment. -/\nnoncomputable def machineOriginal (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits)\n    (k : Fin (firstAxis (bitLength (bitValue bits))*secondAxis (bitLength (bitValue bits))))\n    (input : Fin (arity (Vertex.product (digits:=digitCount (bitLength (bitValue bits))) k))→Bool) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial bits (List.ofFn input)))\n      (some (SemiprimeD1StackCalls.configuration (done bits (List.ofFn input))))\n      (100000000000000000000*(bitLength (bitValue bits)+1)^3) := by\n  have hb : bits≠[] := by intro he;rw [he] at hN;exact (Nat.lt_irrefl 0 hN)\n  let h:=SemiprimeD1StackPublicProductBounds.machineCheck bits (List.ofFn input) hb\n  exact ⟨h.toEvalsTo,h.steps_le_m.trans (original_time bits hc k input)⟩\n/-- Full original all-prefix inventory, including every acquired public cache,\nall76 data roles and every actual return-label cell, uniformly for all inputs. -/\ntheorem original_prefix_cells (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits)\n    (k : Fin (firstAxis (bitLength (bitValue bits))*secondAxis (bitLength (bitValue bits))))\n    (input : Fin (arity (Vertex.product (digits:=digitCount (bitLength (bitValue bits))) k))→Bool)\n    (fuel : ℕ) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial bits (List.ofFn input))))=some cfg) :\n    (∑k : Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤10000000000000000000000*(bitLength (bitValue bits)+1)^3 := by\n  have hbits : bits≠[] := by intro he;rw [he] at hN;exact (Nat.lt_irrefl 0 hN)\n  have h:=SemiprimeD1StackPublicProductBounds.machine_prefix_cells bits (List.ofFn input) hbits fuel cfg hr\n  have hp:=Nat.pow_le_pow_left (original_inventory bits hc k input) 3\n  rw [mul_pow] at hp\n  norm_num at hp\n  simp only [List.length_ofFn] at h\n  omega\nend RiemannGaussian.SemiprimeD1StackPublicProductFinite\n","RiemannGaussian.SemiprimeD1StackPublicTargetBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicTargetExecution\n/-! # Closed acquisition/read polynomial, without a supplied target or cache\nThe physical unary index remains a declared caller input, not a decoded control\nregister. All original N preprocessing, cache copying and field scans are paid.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1000000\nset_option synthInstance.maxSize 4096\nnamespace RiemannGaussian.SemiprimeD1StackPublicTargetBounds\nopen SemiprimeD1StackPublicTarget SemiprimeD1StackPublicTargetExecution\nattribute [local irreducible] SemiprimeD1BinaryPublicAcquisitionComponents.result\n/-- Intrinsic bound on the ACTUAL original streaming block producer. The\ncached digit catalogue is neither supplied nor replaced by a desired size. -/\ntheorem bank_length (bits : List Bool) :\n    (SemiprimeD1TensorTapeCodec.vectorBits (digits bits)).length ≤ 24000000*(bits.length+1)^2 := by\n  have he:=SemiprimeD1StackDigitBankSpec.entries_blocks_length\n    (SemiprimeD1BinaryDigitAcquisitionComponents.radix bits) bits.length bits\n  have hr:=SemiprimeD1BinaryDigitAcquisitionComponents.radix_length bits\n  have hb:=SemiprimeD1StackTransformArithmetic.radix_bound bits.length\n  rw [hr] at he\n  rw [←SemiprimeD1StackDigitBankSpec.entries_vectorBits]\n  change (SemiprimeD1StackDigitBankSpec.entries\n    (SemiprimeD1StackDigitBankSpec.blocks (SemiprimeD1BinaryDigitAcquisitionComponents.radix bits) bits.length bits)++[false]).length ≤ _\n  simp only [List.length_append,List.length_cons,List.length_nil]\n  nlinarith [Nat.zero_le (bits.length^2)]\n/-- One fixed quadratic allowance in original BINARY input and actual query bytes. -/\ndef timeBound (bits index : List Bool) : ℕ := 1000000000*(bits.length+index.length+2)^2\n/-- Actual original-binary public acquisition/read trace with no supplied bank,\nparameter, digit, default-zero result or execution clock. -/\ntheorem source_run_bounded (bits index : List Bool) (hb : bits≠[]) :\n    ∃time ≤ timeBound bits index,C.run program time (initial bits index)=some (done bits index) := by\n  obtain ⟨t,ht,hr⟩:=source_run bits index hb\n  refine ⟨t,ht.trans ?_,hr⟩\n  have hB:=bank_length bits\n  have hp : (bits.length+1)^2 ≤ (bits.length+index.length+2)^2 := Nat.pow_le_pow_left (by omega) 2\n  have hi : index.length ≤ (bits.length+index.length+2)^2 := by\n    have hh:=Nat.pow_le_pow_right (by omega : 1 ≤ bits.length+index.length+2) (by decide : 1 ≤ 2)\n    simp only [pow_one] at hh\n    omega\n  have hpos : 0 < (bits.length+index.length+2)^2 := by positivity\n  unfold SemiprimeD1BinaryPublicAcquisitionExecution.timeBound SemiprimeD1StackJetReadExecution.timeBound timeBound\n  omega\n/-- Proof-side choice of an ACTUALLY PROVED trace; no choice/evaluator occurs in code. -/\nnoncomputable def sourceRead (bits index : List Bool) (hb : bits≠[]) :\n    StateTransition.EvalsToInTime (C.step program) (initial bits index) (some (done bits index))\n      (timeBound bits index) := by\n  let h:=source_run_bounded bits index hb\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\n/-- Genuine fixed finite machine from original binary N PLUS physical query index. -/\nnoncomputable def machineRead (bits index : List Bool) (hb : bits≠[]) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial bits index))\n      (some (SemiprimeD1StackCalls.configuration (done bits index))) (timeBound bits index) :=\n  SemiprimeD1StackCalls.evalsCorrect\n    (.inl (P.digitStack (SemiprimeD1BinaryPublicAcquisition.Digits.metaStack .input))) (.inr .output)\n    Label.start program _ _ _ (sourceRead bits index hb)\n/-- A successful actual prefix cannot occur beyond the bounded completed halt. -/\ntheorem prefix_fuel_le (bits index : List Bool) (hb : bits≠[]) (fuel : ℕ) (out : C.State Stack Label)\n    (hr : C.run program fuel (initial bits index)=some out) : fuel ≤ timeBound bits index := by\n  obtain ⟨t,ht,hh⟩:=source_run_bounded bits index hb\n  have hf : fuel ≤ t := by\n    by_contra hn\n    have he : fuel=t+(1+(fuel-(t+1))) := by omega\n    rw [he,SemiprimeD1StackReturnLink.run_add,hh,Option.bind_some,SemiprimeD1StackReturnLink.run_add] at hr\n    have hz : C.run program 1 (done bits index)=none := rfl\n    rw [hz,Option.bind_none] at hr\n    cases hr\n  exact hf.trans ht\n/-- ALL thirty-six physical data stacks and real return-label cells at EVERY\nactual prefix, including original acquisition plus repeated cache scan/copy. -/\ntheorem prefix_cells (bits index : List Bool) (hb : bits≠[]) (fuel : ℕ) (out : C.State Stack Label)\n    (hr : C.run program fuel (initial bits index)=some out) :\n    (∑k : Stack,(out.data k).length)+out.frames.length ≤\n      100000000000*(bits.length+index.length+2)^2 := by\n  let inv:=bits.length+index.length\n  have hdata : ∀k,((initial bits index).data k).length ≤ inv := by\n    intro k\n    rcases k with k|k\n    · rcases k with k|k\n      · rcases k with k|k\n        · cases k <;> simp only [initial,input,store,P.input,SemiprimeD1BinaryPublicAcquisition.store,\n            SemiprimeD1BinaryPublicAcquisition.Digits.input,SemiprimeD1BinaryDigitAcquisition.store,\n            SemiprimeD1StackTransform.input,Sum.elim_inl,List.length_nil] <;> dsimp [inv] <;> omega\n        · rcases k with k|k <;> exact Nat.zero_le _\n      · rcases k with k|k <;> exact Nat.zero_le _\n    · cases k <;> simp only [initial,input,store,R.store,Sum.elim_inr,List.length_nil] <;> dsimp [inv] <;> omega\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel inv _ out hdata hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ out hr\n  change out.frames.length ≤ 0+fuel at hf\n  have hs : (∑k : Stack,(out.data k).length) ≤ 36*(inv+fuel) := by\n    calc\n      _ ≤ ∑_k : Stack,(inv+fuel) := Finset.sum_le_sum (fun k _=>hd k)\n      _ = _ := by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  have ht:=prefix_fuel_le bits index hb fuel out hr\n  change fuel ≤ 1000000000*(inv+2)^2 at ht\n  have hi : inv ≤ (inv+2)^2 := by\n    have hh:=Nat.pow_le_pow_right (by omega : 1 ≤ inv+2) (by decide : 1 ≤ 2)\n    simp only [pow_one] at hh\n    omega\n  change (∑k : Stack,(out.data k).length)+out.frames.length ≤ 100000000000*(inv+2)^2\n  omega\n/-- The same full inventory for EVERY reached genuine FinTM2 prefix. -/\ntheorem machine_prefix_cells (bits index : List Bool) (hb : bits≠[]) (fuel : ℕ) (cfg : machine.Cfg)\n    (hr : (fun c=>c.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial bits index)))=some cfg) :\n    (∑k : Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤\n      100000000000*(bits.length+index.length+2)^2 := by\n  have he:=SemiprimeD1StackCalls.run_correct\n    (.inl (P.digitStack (SemiprimeD1BinaryPublicAcquisition.Digits.metaStack .input))) (.inr .output)\n    Label.start program fuel (initial bits index)\n  have hh:=he.trans hr\n  cases hc : C.run program fuel (initial bits index) with\n  | none=>rw [hc] at hh;cases hh\n  | some out=>\n    rw [hc] at hh\n    have hcfg : SemiprimeD1StackCalls.configuration out=cfg := Option.some.inj hh\n    subst cfg\n    exact prefix_cells bits index hb fuel out hc\nend RiemannGaussian.SemiprimeD1StackPublicTargetBounds\n","RiemannGaussian.SemiprimeD1StackPublicTransformBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicTransformQueryBounds\n/-! # Complete own transform transition budget from original input tapes -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1200000\nset_option maxRecDepth 100000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackPublicTransformBounds\nopen SemiprimeD1StackPublicTransformMetadata SemiprimeD1StackPublicTransformWords\nopen SemiprimeD1StackPublicTransformSetup SemiprimeD1StackPublicTransformGuards\nopen SemiprimeD1StackPublicTransformInventory SemiprimeD1StackPublicTransformQueryBounds\nopen SemiprimeBitArithmetic\nopen SemiprimeD1TensorTapeCodec (vectorBits)\n/-- Entire physically executed loop, including every short-circuit cleanup. -/\ntheorem loop_le (bits raw : List Bool) (second inverse : Bool)\n    (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits)\n    (hg : inputFlag (rootData bits) raw second=true) (n f : ℕ)\n    (hn : n ≤ size bits second) (hf : f ≤ inputSize bits raw second inverse) :\n    SemiprimeD1StackPublicTransformLoop.budget bits raw second inverse n f ≤\n      (n+1)*(10^21*(inputSize bits raw second inverse)^16+30*inputSize bits raw second inverse+30) := by\n  induction n generalizing f with\n  | zero=>simp only [SemiprimeD1StackPublicTransformLoop.budget,Nat.zero_add,Nat.one_mul];omega\n  | succ n ih=>\n    have hsize:=(caps bits raw second inverse).2.2.2.2.2.1\n    have hq:=query_le bits raw second inverse n hc hN hg (by omega)\n    have hrec:=ih n (by omega) (by omega)\n    simp only [SemiprimeD1StackPublicTransformLoop.budget]\n    rw [Nat.add_mul,Nat.one_mul]\n    omega\n/-- Original root/source/count/cache copies are all explicitly retained. -/\ntheorem setup_le (bits raw : List Bool) (second inverse : Bool) :\n    metadataBudget (rootData bits) second inverse+normalizationBudget (rootData bits) second inverse ≤\n      200*inputSize bits raw second inverse := by\n  obtain ⟨_,_,hm,hb,hNorm,hn,hs,hS⟩:=caps bits raw second inverse\n  have hcount : (count bits second).length=size bits second := by\n    rw [count_unary,SemiprimeD1StackUnaryDivmod.unary,List.length_replicate]\n  have hstride : (count bits (!second)).length=size bits (!second) := by\n    rw [count_unary,SemiprimeD1StackUnaryDivmod.unary,List.length_replicate]\n  change (5*(baseCode bits inverse).length+4)+5*(5*(cached bits).length+4)+3*(5*(count bits second).length+4)+\n    (5*(count bits (!second)).length+4)+normalizationBudget (rootData bits) second inverse ≤ _\n  rw [hcount,hstride]\n  unfold normalizationBudget\n  split\n  · rename_i hh\n    rw [Bool.and_eq_true] at hh\n    rcases hh with ⟨rfl,rfl⟩\n    change (5*(baseCode bits true).length+4)+5*(5*(cached bits).length+4)+3*(5*size bits true+4)+\n      (5*size bits (!true)+4)+(5*(normalizer bits true true).length+4) ≤ _\n    omega\n  · omega\n/-- Both actual original vector acquisitions and all source copies are paid. -/\ntheorem words_le (bits raw : List Bool) (second inverse : Bool) :\n    wordsBudget (rootData bits) raw second ≤ 3000*(inputSize bits raw second inverse)^2 := by\n  let S:=inputSize bits raw second inverse\n  obtain ⟨_,hr,hm,_,_,hn,_,hS⟩:=caps bits raw second inverse\n  have hc : (countWord (rootData bits) second).length=size bits second := by\n    change (count bits second).length=_\n    rw [count_unary,SemiprimeD1StackUnaryDivmod.unary,List.length_replicate]\n  have hraw : (outputRaw (rootData bits) raw second).length ≤ raw.length := by simp only [outputRaw,List.length_drop];omega\n  unfold wordsBudget SemiprimeD1StackWordVectorExecution.timeBound\n  rw [hc]\n  change (5*raw.length+4)+(100*(raw.length+(size bits second+1)*((cached bits).length+1)+1)+1)+\n    (5*(outputRaw (rootData bits) raw second).length+4)+\n    (100*((outputRaw (rootData bits) raw second).length+(size bits second+1)*((cached bits).length+1)+1)+1) ≤ 3000*S^2\n  have hmul:=Nat.mul_le_mul (show size bits second+1 ≤ S+1 by omega)\n    (show (cached bits).length+1 ≤ S+1 by omega)\n  change raw.length ≤ S at hr\n  change (cached bits).length ≤ S at hm\n  nlinarith\nprivate theorem guard_poly (t v m S : ℕ) (ht : t ≤ 200*(v+m+1)^2)\n    (hv : v ≤ 5*S^2) (hm : m ≤ S) (hs : 2 ≤ S) : t ≤ 10000*S^4 := by\n  have hsum : v+m+1 ≤ 7*S^2 := by nlinarith\n  have h:=Nat.mul_le_mul_left 200 (Nat.pow_le_pow_left hsum 2)\n  rw [mul_pow,←pow_mul,←Nat.mul_assoc] at h\n  norm_num only [Nat.reducePow,Nat.reduceMul] at h\n  omega\n/-- Computed input/output guards include physical full-vector copies and scans. -/\ntheorem front_le (bits raw : List Bool) (second inverse : Bool) :\n    frontBudget (rootData bits) raw second ≤ 1000000*(inputSize bits raw second inverse)^4 := by\n  let S:=inputSize bits raw second inverse\n  obtain ⟨_,_,hm,_,_,hn,_,hS⟩:=caps bits raw second inverse\n  obtain ⟨hvi,hvo⟩:=vector_caps bits raw second inverse\n  have hi:=guard_poly _ _ _ _ (SemiprimeD1StackVectorCanonicalBounds.timeBound_le\n    (inputs (rootData bits) raw second) (cached bits)) hvi hm hS\n  have ho:=guard_poly _ _ _ _ (SemiprimeD1StackVectorCanonicalBounds.timeBound_le\n    (outputs (rootData bits) raw second) (cached bits)) hvo hm hS\n  have hc : (countWord (rootData bits) second).length=size bits second := by\n    change (count bits second).length=_\n    rw [count_unary,SemiprimeD1StackUnaryDivmod.unary,List.length_replicate]\n  change (vectorBits (inputs (rootData bits) raw second)).length ≤ 5*S^2 at hvi\n  change (vectorBits (outputs (rootData bits) raw second)).length ≤ 5*S^2 at hvo\n  change SemiprimeD1StackVectorCanonicalExecution.timeBound (inputs (rootData bits) raw second)\n    (modulusWord (rootData bits)) ≤ 10000*S^4 at hi\n  change SemiprimeD1StackVectorCanonicalExecution.timeBound (outputs (rootData bits) raw second)\n    (modulusWord (rootData bits)) ≤ 10000*S^4 at ho\n  change size bits second ≤ S at hn\n  have h2 : S^2 ≤ S^4 := Nat.pow_le_pow_right (by omega) (by decide)\n  have h1 : S ≤ S^4 := by simpa only [pow_one] using Nat.pow_le_pow_right (by omega : 1 ≤ S) (by decide : 1 ≤ 4)\n  have hp : 0<S^4 := Nat.pow_pos (by omega)\n  unfold frontBudget\n  rw [hc]\n  change _ ≤ 1000000*S^4\n  omega\nprivate theorem loop_poly (n S : ℕ) (hn : n ≤ S) (hs : 2 ≤ S) :\n    (n+1)*(10^21*S^16+30*S+30) ≤ 10^24*S^18 := by\n  have hlin : S ≤ S^16 := by simpa only [pow_one] using Nat.pow_le_pow_right (by omega : 1 ≤ S) (by decide : 1 ≤ 16)\n  have hp : 0<S^16 := Nat.pow_pos (by omega)\n  have hterm : 10^21*S^16+30*S+30 ≤ 10^22*S^16 := by norm_num only [Nat.reducePow];omega\n  have h:=Nat.mul_le_mul (show n+1 ≤ 2*S by omega) hterm\n  rw [show (2*S)*(10^22*S^16)=2*10^22*S^17 by ring] at h\n  have hmono : S^17 ≤ S^18 := Nat.pow_le_pow_right (by omega) (by decide)\n  norm_num only [Nat.reducePow,Nat.reduceMul] at h ⊢\n  omega\n/-- Entire actual source budget has a uniform fixed polynomial in original\nacquired physical inventory. Failed guard branches do not pay imaginary queries. -/\ntheorem timeBound_le (bits raw : List Bool) (second inverse : Bool)\n    (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits) :\n    SemiprimeD1StackPublicTransformTraceBudget.timeBound bits raw second inverse+1 ≤\n      10^25*(inputSize bits raw second inverse)^18 := by\n  let S:=inputSize bits raw second inverse\n  obtain ⟨hb,_,_,_,_,hn,_,hS⟩:=caps bits raw second inverse\n  have hsetup:=setup_le bits raw second inverse\n  have hwords:=words_le bits raw second inverse\n  have hfront:=front_le bits raw second inverse\n  have hroot : SemiprimeD1StackRootSourceBounds.timeBound bits ≤ 40000000*S^2 := by\n    have h:=Nat.mul_le_mul_left 10000000 (Nat.pow_le_pow_left (show bits.length+1 ≤ 2*S by omega) 2)\n    rw [mul_pow,←Nat.mul_assoc] at h\n    norm_num only [Nat.reducePow,Nat.reduceMul] at h\n    exact h\n  have h1 : S ≤ S^18 := by simpa only [pow_one] using Nat.pow_le_pow_right (by omega : 1 ≤ S) (by decide : 1 ≤ 18)\n  have h2 : S^2 ≤ S^18 := Nat.pow_le_pow_right (by omega) (by decide)\n  have h4 : S^4 ≤ S^18 := Nat.pow_le_pow_right (by omega) (by decide)\n  have hp : 0<S^18 := Nat.pow_pos (by omega)\n  change metadataBudget (rootData bits) second inverse+normalizationBudget (rootData bits) second inverse ≤ 200*S at hsetup\n  change wordsBudget (rootData bits) raw second ≤ 3000*S^2 at hwords\n  change frontBudget (rootData bits) raw second ≤ 1000000*S^4 at hfront\n  cases ha : SemiprimeD1StackPublicTransformExecution.acceptedInputs bits raw second with\n  | false=>\n    unfold SemiprimeD1StackPublicTransformTraceBudget.timeBound\n    simp only [ha,Bool.false_eq_true,ite_false]\n    change _ ≤ 10^25*S^18\n    norm_num only [Nat.reducePow]\n    omega\n  | true=>\n    have hh:=ha\n    change (inputFlag (rootData bits) raw second && outputFlag (rootData bits) raw second)=true at hh\n    rw [Bool.and_eq_true] at hh\n    have hl:=(loop_le bits raw second inverse hc hN hh.1 (size bits second) 0 le_rfl (Nat.zero_le _)).trans\n      (loop_poly _ _ hn hS)\n    change SemiprimeD1StackPublicTransformLoop.budget bits raw second inverse (size bits second) 0 ≤ 10^24*S^18 at hl\n    unfold SemiprimeD1StackPublicTransformTraceBudget.timeBound\n    simp only [ha,ite_true]\n    change _ ≤ 10^25*S^18\n    norm_num only [Nat.reducePow] at hl ⊢\n    omega\n/-- Only the actual original binary/raw tape lengths occur in the final bound. -/\ndef runBound (bits raw : List Bool) : ℕ := 10^90*(bits.length+raw.length+1)^18\n/-- No acquired cache width, component clock, canonicality or source-size answer\nis an input to this original-tape transition polynomial. -/\ntheorem runBound_le (bits raw : List Bool) (second inverse : Bool)\n    (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits) :\n    SemiprimeD1StackPublicTransformTraceBudget.timeBound bits raw second inverse+1 ≤ runBound bits raw := by\n  have h:=Nat.mul_le_mul_left (10^25) (Nat.pow_le_pow_left (inputSize_le bits raw second inverse) 18)\n  rw [mul_pow,←Nat.mul_assoc] at h\n  norm_num only [Nat.reducePow,Nat.reduceMul] at h\n  have ht:=timeBound_le bits raw second inverse hc hN\n  unfold runBound\n  norm_num only [Nat.reducePow]\n  omega\nend RiemannGaussian.SemiprimeD1StackPublicTransformBounds\n","RiemannGaussian.SemiprimeD1StackPublicTransformFiniteWords":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicTransformOriginal\nimport RiemannGaussian.SemiprimeD1StackWordVectorFinite\n/-! # Two complete original word families, preserving raw assignment order -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 100000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackPublicTransformFiniteWords\nopen SemiprimeD1StackWordVectorSpec SemiprimeBitArithmetic\n/-- Original consecutive word coordinates, used only as a semantic view. -/\ndef halfWord (width : List Bool) (n : ℕ) (input : Fin (n*width.length+n*width.length)→Bool)\n    (second : Bool) (j : Fin n) : List Bool :=\n  List.ofFn (fun b : Fin width.length=>input ⟨(if second then n*width.length else 0)+j.val*width.length+b.val,by\n    have h:=Nat.mul_le_mul_right width.length (show j.val+1≤n by omega)\n    rw [Nat.add_mul,Nat.one_mul] at h\n    split <;> omega⟩)\n/-- Every physically acquired block has the original word-before-bit coordinates. -/\ntheorem block_half (width : List Bool) (n : ℕ) (input : Fin (n*width.length+n*width.length)→Bool)\n    (second : Bool) (j : Fin n) :\n    (((List.ofFn input).drop (if second then n*width.length else 0)).drop (j.val*width.length)).take width.length=\n      halfWord width n input second j := by\n  have h:=Nat.mul_le_mul_right width.length (show j.val+1≤n by omega)\n  rw [Nat.add_mul,Nat.one_mul] at h\n  rw [List.drop_drop]\n  apply List.ext_getElem\n  · simp only [List.length_take,List.length_drop,List.length_ofFn,halfWord,List.length_ofFn]\n    cases second <;> simp only [Bool.false_eq_true,ite_false,ite_true] <;> omega\n  · intro b hb hb'\n    simp only [List.getElem_take,List.getElem_drop,List.getElem_ofFn,halfWord]\n/-- Two actual vector calls consume the two original halves with NO word getter\nor vector-family premise on the executing machine. -/\ntheorem half_blocks (width : List Bool) (n : ℕ) (input : Fin (n*width.length+n*width.length)→Bool)\n    (second : Bool) (j : Fin n) :\n    SemiprimeD1StackExprDotSpec.wordAt\n      (blocks width n ((List.ofFn input).drop (if second then n*width.length else 0))) j.val=\n      halfWord width n input second j := by\n  have hfull : n*width.length≤((List.ofFn input).drop (if second then n*width.length else 0)).length := by\n    simp only [List.length_drop,List.length_ofFn]\n    cases second <;> simp only [Bool.false_eq_true,ite_false,ite_true] <;> omega\n  rw [SemiprimeD1StackExprDotSpec.wordAt,blocks_get_take width n _ j.val j.isLt hfull,Option.getD_some]\n  exact block_half width n input second j\n/-- Both acquired original vectors have their literal finite half-word order. -/\ntheorem acquired_halves (bits : List Bool) (second : Bool)\n    (input : Fin (SemiprimeD1StackPublicTransformMetadata.size bits second*(SemiprimeD1StackPublicTransformMetadata.cached bits).length+\n      SemiprimeD1StackPublicTransformMetadata.size bits second*(SemiprimeD1StackPublicTransformMetadata.cached bits).length)→Bool)\n    (j : Fin (SemiprimeD1StackPublicTransformMetadata.size bits second)) :\n    SemiprimeD1StackPublicTransformOriginal.input bits (List.ofFn input) second j=\n      halfWord (SemiprimeD1StackPublicTransformMetadata.cached bits) _ input false j ∧\n    SemiprimeD1StackPublicTransformOriginal.output bits (List.ofFn input) second j=\n      halfWord (SemiprimeD1StackPublicTransformMetadata.cached bits) _ input true j := by\n  have hn : (SemiprimeD1StackPublicTransformWords.countWord\n      (SemiprimeD1StackPublicTransformMetadata.rootData bits) second).length=\n      SemiprimeD1StackPublicTransformMetadata.size bits second := by\n    change (SemiprimeD1StackPublicTransformMetadata.count bits second).length=_\n    rw [SemiprimeD1StackPublicTransformMetadata.count_unary,\n      SemiprimeD1StackUnaryDivmod.unary,List.length_replicate]\n  constructor\n  · change SemiprimeD1StackExprDotSpec.wordAt (blocks _ _ _) _=_\n    rw [hn]\n    exact half_blocks _ _ input false j\n  · change SemiprimeD1StackExprDotSpec.wordAt (blocks _ _ _) _=_\n    rw [hn]\n    change SemiprimeD1StackExprDotSpec.wordAt\n      (blocks (SemiprimeD1StackPublicTransformMetadata.cached bits) _\n        ((List.ofFn input).drop (_*(SemiprimeD1StackPublicTransformMetadata.cached bits).length))) _=_\n    rw [hn]\n    exact half_blocks _ _ input true j\nend RiemannGaussian.SemiprimeD1StackPublicTransformFiniteWords\n","RiemannGaussian.SemiprimeD1StackPublicTransformGuards":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicTransformWords\n/-! # Computed physical input/output canonicality guards\nBoth guards execute on ACTUAL produced vectors, with actual short-circuit\nrejection. No canonicality/truth/word-vector answer is an endpoint premise.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 100000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackPublicTransformGuards\nopen SemiprimeD1StackPublicTransform SemiprimeD1StackPublicTransformState SemiprimeD1StackPublicTransformWords\nopen SemiprimeD1StackPublicTransformPrimitives SemiprimeD1StackProcedureTrace\nopen SemiprimeD1TensorTapeCodec (vectorBits)\n/-- Input canonicality answer of the actually acquired first vector. -/\ndef inputFlag (root : R.Stack→List Bool) (raw : List Bool) (second : Bool) : Bool :=\n  SemiprimeD1StackVectorCanonicalExecution.answer (modulusWord root) (inputs root raw second)\n/-- Output canonicality answer of the actually acquired second vector. -/\ndef outputFlag (root : R.Stack→List Bool) (raw : List Bool) (second : Bool) : Bool :=\n  SemiprimeD1StackVectorCanonicalExecution.answer (modulusWord root) (outputs root raw second)\n/-- Actual first encoded-vector copy into the retained dot input cache. -/\ndef dotCached (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) : Parts :=\n  copied (bothAcquired root raw second inverse) (.vector false 0)\n/-- Actual input-vector copy into the real canonicality checker. -/\ndef inputReady (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) : Parts :=\n  copied (dotCached root raw second inverse) (.vector false 1)\n/-- Actual completed input guard; the returned bit is still physically present. -/\ndef inputChecked (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) : Parts :=\n  {inputReady root raw second inverse with checker:=\n    (SemiprimeD1StackVectorCanonicalExecution.done (inputs root raw second) (modulusWord root)).data}\n/-- The actual input guard bit has been popped to select control. -/\ndef inputPopped (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) : Parts :=\n  set (inputChecked root raw second inverse) (.guard .output) []\n/-- Every byte of old checker input cache is physically drained before reuse. -/\ndef inputCleared (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) : Parts :=\n  set (inputPopped root raw second inverse) (.guard .cache) []\n/-- The actual output vector is copied into the now-empty checker cache. -/\ndef outputReady (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) : Parts :=\n  copied (inputCleared root raw second inverse) (.vector true 1)\n/-- Completed actual output guard, with its physical Boolean result present. -/\ndef outputChecked (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) : Parts :=\n  {outputReady root raw second inverse with checker:=\n    (SemiprimeD1StackVectorCanonicalExecution.done (outputs root raw second) (modulusWord root)).data}\n/-- The output guard's ACTUAL bit is popped before the loop is permitted. -/\ndef outputPopped (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) : Parts :=\n  set (outputChecked root raw second inverse) (.guard .output) []\n/-- Actual output-vector copy into the retained physical reader cache. -/\ndef outputCached (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) : Parts :=\n  copied (outputPopped root raw second inverse) (.vector true 2)\n/-- Actual loop count is copied from the acquired dot count-marker cache. -/\ndef loopReady (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) : Parts :=\n  copied (outputCached root raw second inverse) .remaining\n/-- BOTH originally produced vectors are paid actual copies, not a native cache. -/\ntheorem dot_copy (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) :\n    Runs program (5*(vectorBits (inputs root raw second)).length+4) .copyInputDot\n      (data (bothAcquired root raw second inverse)) .copyGuardInput (data (dotCached root raw second inverse)) :=\n  copy_run (.vector false 0) .copyInputDot .copyGuardInput rfl (bothAcquired root raw second inverse) rfl rfl\n/-- Real input-guard cache copy. -/\ntheorem input_copy (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) :\n    Runs program (5*(vectorBits (inputs root raw second)).length+4) .copyGuardInput\n      (data (dotCached root raw second inverse)) .guardInput (data (inputReady root raw second inverse)) :=\n  copy_run (.vector false 1) .copyGuardInput .guardInput rfl (dotCached root raw second inverse) rfl rfl\n/-- The real input guard receives the actual producer bytes and acquired M. -/\ntheorem input_initial (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) :\n    (inputReady root raw second inverse).checker=(V.initial (vectorBits (inputs root raw second)) (modulusWord root)).data := by\n  funext k;cases k <;> rfl\n/-- WHOLE real input guard, including every actually visited field/read/comparison. -/\ntheorem input_call (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) :\n    ∃t≤SemiprimeD1StackVectorCanonicalExecution.timeBound (inputs root raw second) (modulusWord root)+1,\n      Runs program t .guardInput (data (inputReady root raw second inverse)) .branchInput\n        (data (inputChecked root raw second inverse)) := by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackVectorCanonicalExecution.source_run (inputs root raw second) (modulusWord root)\n  refine ⟨t+1,Nat.add_le_add_right ht 1,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program Stack.guard Label.check\n    (by intro i j h;exact Stack.guard.inj h) V.program .start (fun _=>rfl) .guardInput .branchInput rfl t\n    (V.initial (vectorBits (inputs root raw second)) (modulusWord root))\n    (SemiprimeD1StackVectorCanonicalExecution.done (inputs root raw second) (modulusWord root)) _ _ rfl rfl rfl rfl hr\n  · constructor\n    · intro k;exact congrFun (input_initial root raw second inverse) k\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk;cases k <;> first | rfl | exact (hk _ rfl).elim\n/-- Actual input verdict controls reject/continue, without a truth premise. -/\ntheorem input_branch (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) :\n    Runs program 1 .branchInput (data (inputChecked root raw second inverse))\n      (if inputFlag root raw second then .clearGuard else .reject) (data (inputPopped root raw second inverse)) := by\n  have h:=pop .branchInput .bad .reject .clearGuard (.guard .output) rfl (data (inputChecked root raw second inverse))\n  have hv : data (inputChecked root raw second inverse) (.guard .output)=[inputFlag root raw second] := rfl\n  rw [hv,←data_set] at h\n  cases he : inputFlag root raw second <;> simpa only [inputPopped,he,List.head?_cons,List.tail_cons,SemiprimeD1StackBytecode.choose,Bool.false_eq_true,ite_true,ite_false] using h\n/-- The entire earlier cache is REALLY popped before the output cache is copied. -/\ntheorem clear_input (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) :\n    Runs program ((vectorBits (inputs root raw second)).length+1) .clearGuard (data (inputPopped root raw second inverse))\n      .copyGuardOutput (data (inputCleared root raw second inverse)) := by\n  have h:=drain .clearGuard .copyGuardOutput (.guard .cache) rfl (data (inputPopped root raw second inverse))\n  have hv : data (inputPopped root raw second inverse) (.guard .cache)=vectorBits (inputs root raw second) := rfl\n  rw [hv,←data_set] at h;exact h\n/-- Real output-vector cache copy, including preservation/restoration of source. -/\ntheorem output_copy (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) :\n    Runs program (5*(vectorBits (outputs root raw second)).length+4) .copyGuardOutput\n      (data (inputCleared root raw second inverse)) .guardOutput (data (outputReady root raw second inverse)) :=\n  copy_run (.vector true 1) .copyGuardOutput .guardOutput rfl (inputCleared root raw second inverse) rfl rfl\n/-- Output guard receives the actual second produced vector, not output truth. -/\ntheorem output_initial (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) :\n    (outputReady root raw second inverse).checker=(V.initial (vectorBits (outputs root raw second)) (modulusWord root)).data := by\n  funext k;cases k <;> rfl\n/-- WHOLE real output guard. -/\ntheorem output_call (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) :\n    ∃t≤SemiprimeD1StackVectorCanonicalExecution.timeBound (outputs root raw second) (modulusWord root)+1,\n      Runs program t .guardOutput (data (outputReady root raw second inverse)) .branchOutput\n        (data (outputChecked root raw second inverse)) := by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackVectorCanonicalExecution.source_run (outputs root raw second) (modulusWord root)\n  refine ⟨t+1,Nat.add_le_add_right ht 1,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program Stack.guard Label.check\n    (by intro i j h;exact Stack.guard.inj h) V.program .start (fun _=>rfl) .guardOutput .branchOutput rfl t\n    (V.initial (vectorBits (outputs root raw second)) (modulusWord root))\n    (SemiprimeD1StackVectorCanonicalExecution.done (outputs root raw second) (modulusWord root)) _ _ rfl rfl rfl rfl hr\n  · constructor\n    · intro k;exact congrFun (output_initial root raw second inverse) k\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk;cases k <;> first | rfl | exact (hk _ rfl).elim\n/-- Actual output guard verdict chooses reject/physical loop setup. -/\ntheorem output_branch (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) :\n    Runs program 1 .branchOutput (data (outputChecked root raw second inverse))\n      (if outputFlag root raw second then .copyOutputCache else .reject) (data (outputPopped root raw second inverse)) := by\n  have h:=pop .branchOutput .bad .reject .copyOutputCache (.guard .output) rfl (data (outputChecked root raw second inverse))\n  have hv : data (outputChecked root raw second inverse) (.guard .output)=[outputFlag root raw second] := rfl\n  rw [hv,←data_set] at h\n  cases he : outputFlag root raw second <;> simpa only [outputPopped,he,List.head?_cons,List.tail_cons,SemiprimeD1StackBytecode.choose,Bool.false_eq_true,ite_true,ite_false] using h\n/-- Output read cache is acquired ONCE from actual producer bytes. -/\ntheorem reader_copy (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) :\n    Runs program (5*(vectorBits (outputs root raw second)).length+4) .copyOutputCache\n      (data (outputPopped root raw second inverse)) .copyLoop (data (outputCached root raw second inverse)) :=\n  copy_run (.vector true 2) .copyOutputCache .copyLoop rfl (outputPopped root raw second inverse) rfl rfl\n/-- The literal output loop count is actually copied from acquired n markers. -/\ntheorem loop_copy (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) :\n    Runs program (5*(countWord root second).length+4) .copyLoop\n      (data (outputCached root raw second inverse)) .loop (data (loopReady root raw second inverse)) :=\n  copy_run .remaining .copyLoop .loop rfl (outputCached root raw second inverse) rfl rfl\n/-- Exact branch-dependent physical frontend result, specified AFTER real guards. -/\ndef frontResult (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) : Parts :=\n  if inputFlag root raw second then\n    if outputFlag root raw second then loopReady root raw second inverse else outputPopped root raw second inverse\n  else inputPopped root raw second inverse\n/-- Complete own frontend allowance, including both real guards and all copies\nand cache draining, although rejected executions visit only their prefix. -/\ndef frontBudget (root : R.Stack→List Bool) (raw : List Bool) (second : Bool) : ℕ :=\n  (5*(vectorBits (inputs root raw second)).length+4)+(5*(vectorBits (inputs root raw second)).length+4)+\n    (SemiprimeD1StackVectorCanonicalExecution.timeBound (inputs root raw second) (modulusWord root)+1)+1+\n    ((vectorBits (inputs root raw second)).length+1)+(5*(vectorBits (outputs root raw second)).length+4)+\n    (SemiprimeD1StackVectorCanonicalExecution.timeBound (outputs root raw second) (modulusWord root)+1)+1+\n    (5*(vectorBits (outputs root raw second)).length+4)+(5*(countWord root second).length+4)\n/-- ENTIRE real two-guard frontend: accepted cases computed BOTH canonicality\nchecks; actual early rejection is proved for every failed Boolean, without advice. -/\ntheorem front_run (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) :\n    ∃t≤frontBudget root raw second,Runs program t .copyInputDot (data (bothAcquired root raw second inverse))\n      (if inputFlag root raw second && outputFlag root raw second then .loop else .reject)\n      (data (frontResult root raw second inverse)) := by\n  obtain ⟨u,hu,hg0⟩:=input_call root raw second inverse\n  have hp:=runs_trans program _ _ _ _ _ _ _ _\n    (runs_trans program _ _ _ _ _ _ _ _ (runs_trans program _ _ _ _ _ _ _ _ (dot_copy root raw second inverse)\n      (input_copy root raw second inverse)) hg0) (input_branch root raw second inverse)\n  cases hi : inputFlag root raw second with\n  | false=>\n    have hh : Runs program ((5*(vectorBits (inputs root raw second)).length+4)+\n        (5*(vectorBits (inputs root raw second)).length+4)+u+1)\n        .copyInputDot (data (bothAcquired root raw second inverse)) .reject (data (inputPopped root raw second inverse)) := by\n      simpa only [hi,Bool.false_eq_true,ite_false] using hp\n    refine ⟨(5*(vectorBits (inputs root raw second)).length+4)+\n      (5*(vectorBits (inputs root raw second)).length+4)+u+1,?_,?_⟩\n    · unfold frontBudget;omega\n    · simpa only [frontResult,hi,Bool.false_and,Bool.false_eq_true,ite_false] using hh\n  | true=>\n    have hp' : Runs program ((5*(vectorBits (inputs root raw second)).length+4)+\n        (5*(vectorBits (inputs root raw second)).length+4)+u+1)\n        .copyInputDot (data (bothAcquired root raw second inverse)) .clearGuard (data (inputPopped root raw second inverse)) := by\n      simpa only [hi,ite_true] using hp\n    obtain ⟨v,hv,hg1⟩:=output_call root raw second inverse\n    have hs:=runs_trans program _ _ _ _ _ _ _ _\n      (runs_trans program _ _ _ _ _ _ _ _ (runs_trans program _ _ _ _ _ _ _ _\n        (clear_input root raw second inverse) (output_copy root raw second inverse)) hg1) (output_branch root raw second inverse)\n    have hh:=runs_trans program _ _ _ _ _ _ _ _ hp' hs\n    cases ho : outputFlag root raw second with\n    | false=>\n      have hh' : Runs program (((5*(vectorBits (inputs root raw second)).length+4)+\n          (5*(vectorBits (inputs root raw second)).length+4)+u+1)+\n          (((vectorBits (inputs root raw second)).length+1)+(5*(vectorBits (outputs root raw second)).length+4)+v+1))\n          .copyInputDot (data (bothAcquired root raw second inverse)) .reject (data (outputPopped root raw second inverse)) := by\n        simpa only [ho,Bool.false_eq_true,ite_false] using hh\n      refine ⟨((5*(vectorBits (inputs root raw second)).length+4)+\n        (5*(vectorBits (inputs root raw second)).length+4)+u+1)+\n        (((vectorBits (inputs root raw second)).length+1)+(5*(vectorBits (outputs root raw second)).length+4)+v+1),?_,?_⟩\n      · unfold frontBudget;omega\n      · simpa only [frontResult,hi,ho,Bool.true_and,Bool.false_eq_true,ite_true,ite_false] using hh'\n    | true=>\n      have hh' : Runs program (((5*(vectorBits (inputs root raw second)).length+4)+\n          (5*(vectorBits (inputs root raw second)).length+4)+u+1)+\n          (((vectorBits (inputs root raw second)).length+1)+(5*(vectorBits (outputs root raw second)).length+4)+v+1))\n          .copyInputDot (data (bothAcquired root raw second inverse)) .copyOutputCache (data (outputPopped root raw second inverse)) := by\n        simpa only [ho,ite_true] using hh\n      have hlast:=runs_trans program _ _ _ _ _ _ _ _\n        (runs_trans program _ _ _ _ _ _ _ _ hh' (reader_copy root raw second inverse)) (loop_copy root raw second inverse)\n      refine ⟨(((5*(vectorBits (inputs root raw second)).length+4)+\n        (5*(vectorBits (inputs root raw second)).length+4)+u+1)+\n        (((vectorBits (inputs root raw second)).length+1)+(5*(vectorBits (outputs root raw second)).length+4)+v+1))+(5*(vectorBits (outputs root raw second)).length+4)+\n        (5*(countWord root second).length+4),?_,?_⟩\n      · unfold frontBudget;omega\n      · simpa only [frontResult,hi,ho,Bool.true_and,ite_true] using hlast\nend RiemannGaussian.SemiprimeD1StackPublicTransformGuards\n","RiemannGaussian.SemiprimeD1StackPublicTransformRecordOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicTransformRecordBounds\nimport RiemannGaussian.SemiprimeD1StackPublicTransformTableOriginal\nimport RiemannGaussian.SemiprimeD1StackBooleanRecordOriginal\n/-! # Entire original transform tensor and chronological old record bytes\nThe caller acquires the actual ordered numeric scope and descriptor index.\nNo assignment, table, native evaluator or verdict is supplied to the source.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 100000\nset_option maxHeartbeats 1600000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackPublicTransformRecordOriginal\nopen SemiprimeD1StackPublicTransformRecord SemiprimeD1StackPublicTransformRecordExecution\nopen SemiprimeMacroParameters SemiprimeBitArithmetic\nopen SemiprimeD1StackPublicScaleFinite (selector)\nnamespace Bank\nexport SemiprimeD1OrdinalBankSpec (idAt)\nend Bank\nnamespace Log\nexport SemiprimeD1StackVertexRecordStreamExecution (rows history)\nend Log\n/-- Only N and two singleton descriptor flags initialize the read-only template.\nAll acquired axes/roots/normalizers/vectors/guards/results and raw bits start empty. -/\ntheorem initial_template_only (bits : List Bool) (second inverse : Bool)\n    (bank hist out : List Bool) (k : SemiprimeD1StackPublicTransform.Stack) :\n    (initial bits second inverse bank hist out).data\n      (G.tableStack (SemiprimeD1StackStaticTable.template k))=\n      if k=SemiprimeD1StackPublicTransformTable.P.inputRole then bits else\n      if k=SemiprimeD1StackPublicTransformTable.P.second then [second] else\n      if k=SemiprimeD1StackPublicTransformTable.P.inverse then [inverse] else [] :=\n  SemiprimeD1StackPublicTransformTableTrace.template_only bits second inverse k\n/-- Same proof-side original transform vertex with the actual caller scope. -/\nabbrev vertex :=SemiprimeD1StackBooleanRecordOriginal.vertex\nsection First\nvariable (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits)\n  (tr : SemiprimeMacroGraph.Transform) (j : Fin (firstAxis (bitLength (bitValue bits))))\n  (M : Nat) (ports : List Nat) (hp : ∀q∈ports,q<M)\n  (hlen : ports.length=SemiprimeMacroGraph.subdividedArity\n    (.inl (.first tr j):SemiprimePublicAcquiredExecution.PublicVertex (bitValue bits)))\ninclude hc hp\n/-- Exactly the complete original transform table and unchanged unary port order. -/\ntheorem row_first_original :\n    SemiprimeD1StackVertexRecordStream.row\n      (SemiprimeD1StackPortOrdinalStream.result (ports.map (Bank.idAt M)))\n      (SemiprimeD1StackPublicTransformTableExecution.table bits false (selector tr) (ports.map (Bank.idAt M)))=\n      SemiprimeD1StackVertexRecordStream.row\n        (SemiprimeD1StackVertexReadExecution.portTape (vertex (bitValue bits) hN (.inl (.first tr j)) ports hlen).ports)\n        (SemiprimeD1TensorTapeCodec.tape (vertex (bitValue bits) hN (.inl (.first tr j)) ports hlen).table) := by\n  have hs:=SemiprimeD1StackPortOrdinalStreamOriginal.selected_portTape M ports hp\n  have ht:=SemiprimeD1StackPublicTransformTableOriginal.table_first_original bits hc hN tr j\n    (ports.map (Bank.idAt M)) (by simpa only [List.length_map] using hlen)\n  rw [hs,ht]\n  exact congrArg (SemiprimeD1StackVertexRecordStream.row (SemiprimeD1StackVertexReadExecution.portTape ports))\n    (SemiprimeD1StackBooleanRecordOriginal.tape_cast hlen.symm\n      (SemiprimeD1BooleanRootTablesOriginal.reference (bitValue bits) hN (.inl (.first tr j)))).symm\n/-- Literal actual row prepends exactly the unchanged old product-reader record. -/\ntheorem record_bytes_first_original (rest : List SemiprimeD1LeafCounter.Vertex) :\n    SemiprimeD1StackVertexRecordStream.row\n      (SemiprimeD1StackPortOrdinalStream.result (ports.map (Bank.idAt M)))\n      (SemiprimeD1StackPublicTransformTableExecution.table bits false (selector tr) (ports.map (Bank.idAt M)))++\n      SemiprimeD1StackVertexProduct.records rest=\n      SemiprimeD1StackVertexProduct.records\n        (vertex (bitValue bits) hN (.inl (.first tr j)) ports hlen::rest) := by\n  rw [row_first_original bits hc hN tr j M ports hp hlen]\n  exact SemiprimeD1StackVertexRecordStream.row_records _ rest\n/-- Appending one actual input row retains the chronological order of all old rows. -/\ntheorem history_first_original (previous : List SemiprimeD1LeafCounter.Vertex) (old out : List Bool) :\n    (done bits false (selector tr) (ports.map (Bank.idAt M)) (Log.history previous old) out).data G.history=\n      Log.history (previous++[vertex (bitValue bits) hN (.inl (.first tr j)) ports hlen]) old := by\n  rw [history_row,row_first_original bits hc hN tr j M ports hp hlen]\n  simp only [Log.history,SemiprimeD1StackVertexRecordStreamExecution.rows_append,Log.rows,\n    List.append_nil,List.reverse_append,List.append_assoc]\n/-- One final actual logger reversal emits the exact forward old records and\none final false tag, without copying the accumulated tail at every node. -/\ntheorem reverse_first_original (previous : List SemiprimeD1LeafCounter.Vertex) (out : List Bool) :\n    SemiprimeD1StackBytecode.run SemiprimeD1StackVertexRecordStream.code\n      (2*(Log.rows (previous++[vertex (bitValue bits) hN (.inl (.first tr j)) ports hlen])).length+2)\n      ⟨some .reverse,none,SemiprimeD1StackVertexRecordStream.data [] []\n        ((done bits false (selector tr) (ports.map (Bank.idAt M)) (Log.history previous []) (false::out)).data G.history) (false::out)⟩=\n      some ⟨none,none,SemiprimeD1StackVertexRecordStream.data [] [] []\n        (SemiprimeD1StackVertexProduct.records\n          (previous++[vertex (bitValue bits) hN (.inl (.first tr j)) ports hlen])++out)⟩ := by\n  rw [history_first_original bits hc hN tr j M ports hp hlen]\n  exact SemiprimeD1StackVertexRecordStreamExecution.reverse_original _ out\n/-- The actual source execution and exact old chronological record hold together. -/\ntheorem source_run_first_original (previous : List SemiprimeD1LeafCounter.Vertex) (old out : List Bool) :\n    ∃t≤timeBound bits false (selector tr) (ports.map (Bank.idAt M)),∃finish,\n      SemiprimeD1StackCalls.run program t\n        (initial bits false (selector tr) (SemiprimeD1TensorTapeCodec.vectorBits (ports.map (Bank.idAt M)))\n          (Log.history previous old) out)=some finish ∧\n      finish=done bits false (selector tr) (ports.map (Bank.idAt M)) (Log.history previous old) out ∧\n      finish.data G.history=Log.history\n        (previous++[vertex (bitValue bits) hN (.inl (.first tr j)) ports hlen]) old := by\n  obtain ⟨t,ht,hr⟩:=source_run bits false (selector tr) hc hN (ports.map (Bank.idAt M)) (Log.history previous old) out\n  exact ⟨t,ht,_,hr,rfl,history_first_original bits hc hN tr j M ports hp hlen previous old out⟩\nomit hp in\n/-- Each individual acquired coefficient is the exact original integer0/1. -/\ntheorem literal_first_original_coefficient\n    (input : Fin (SemiprimeMacroGraph.arity (.first tr j : SemiprimeMacroGraph.Vertex\n      (firstAxis (bitLength (bitValue bits))) (secondAxis (bitLength (bitValue bits)))\n      (digitCount (bitLength (bitValue bits)))))→Bool) :\n    SemiprimeD1JetAlgebra.coefficient (SemiprimeD1JetBoxIndex.dims [])\n      (SemiprimeD1JetBoxIndex.exponent [] 0)\n      (SemiprimeD1JetBoxIndex.exponent_inBox [] 0 (by simp) (by decide))\n      (SemiprimeD1JetLiteralLift.literal []\n        (SemiprimeD1StackStaticTableSpec.leafWords (T.answer bits false (selector tr)) (List.ofFn input)))=\n      if (SemiprimeMacroEntryBitCheck.publicBitEntry (bitValue bits) hN (.first tr j) input).accepted\n        then 1 else 0 :=\n  SemiprimeD1StackPublicTransformTableOriginal.literal_first_original_coefficient bits hc hN tr j input\nend First\nsection Second\nvariable (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits)\n  (tr : SemiprimeMacroGraph.Transform) (j : Fin (secondAxis (bitLength (bitValue bits))))\n  (M : Nat) (ports : List Nat) (hp : ∀q∈ports,q<M)\n  (hlen : ports.length=SemiprimeMacroGraph.subdividedArity\n    (.inl (.second tr j):SemiprimePublicAcquiredExecution.PublicVertex (bitValue bits)))\ninclude hc hp\n/-- Exactly the complete original transform table and unchanged unary port order. -/\ntheorem row_second_original :\n    SemiprimeD1StackVertexRecordStream.row\n      (SemiprimeD1StackPortOrdinalStream.result (ports.map (Bank.idAt M)))\n      (SemiprimeD1StackPublicTransformTableExecution.table bits true (selector tr) (ports.map (Bank.idAt M)))=\n      SemiprimeD1StackVertexRecordStream.row\n        (SemiprimeD1StackVertexReadExecution.portTape (vertex (bitValue bits) hN (.inl (.second tr j)) ports hlen).ports)\n        (SemiprimeD1TensorTapeCodec.tape (vertex (bitValue bits) hN (.inl (.second tr j)) ports hlen).table) := by\n  have hs:=SemiprimeD1StackPortOrdinalStreamOriginal.selected_portTape M ports hp\n  have ht:=SemiprimeD1StackPublicTransformTableOriginal.table_second_original bits hc hN tr j\n    (ports.map (Bank.idAt M)) (by simpa only [List.length_map] using hlen)\n  rw [hs,ht]\n  exact congrArg (SemiprimeD1StackVertexRecordStream.row (SemiprimeD1StackVertexReadExecution.portTape ports))\n    (SemiprimeD1StackBooleanRecordOriginal.tape_cast hlen.symm\n      (SemiprimeD1BooleanRootTablesOriginal.reference (bitValue bits) hN (.inl (.second tr j)))).symm\n/-- Literal actual row prepends exactly the unchanged old product-reader record. -/\ntheorem record_bytes_second_original (rest : List SemiprimeD1LeafCounter.Vertex) :\n    SemiprimeD1StackVertexRecordStream.row\n      (SemiprimeD1StackPortOrdinalStream.result (ports.map (Bank.idAt M)))\n      (SemiprimeD1StackPublicTransformTableExecution.table bits true (selector tr) (ports.map (Bank.idAt M)))++\n      SemiprimeD1StackVertexProduct.records rest=\n      SemiprimeD1StackVertexProduct.records\n        (vertex (bitValue bits) hN (.inl (.second tr j)) ports hlen::rest) := by\n  rw [row_second_original bits hc hN tr j M ports hp hlen]\n  exact SemiprimeD1StackVertexRecordStream.row_records _ rest\n/-- Appending one actual input row retains the chronological order of all old rows. -/\ntheorem history_second_original (previous : List SemiprimeD1LeafCounter.Vertex) (old out : List Bool) :\n    (done bits true (selector tr) (ports.map (Bank.idAt M)) (Log.history previous old) out).data G.history=\n      Log.history (previous++[vertex (bitValue bits) hN (.inl (.second tr j)) ports hlen]) old := by\n  rw [history_row,row_second_original bits hc hN tr j M ports hp hlen]\n  simp only [Log.history,SemiprimeD1StackVertexRecordStreamExecution.rows_append,Log.rows,\n    List.append_nil,List.reverse_append,List.append_assoc]\n/-- One final actual logger reversal emits the exact forward old records and\none final false tag, without copying the accumulated tail at every node. -/\ntheorem reverse_second_original (previous : List SemiprimeD1LeafCounter.Vertex) (out : List Bool) :\n    SemiprimeD1StackBytecode.run SemiprimeD1StackVertexRecordStream.code\n      (2*(Log.rows (previous++[vertex (bitValue bits) hN (.inl (.second tr j)) ports hlen])).length+2)\n      ⟨some .reverse,none,SemiprimeD1StackVertexRecordStream.data [] []\n        ((done bits true (selector tr) (ports.map (Bank.idAt M)) (Log.history previous []) (false::out)).data G.history) (false::out)⟩=\n      some ⟨none,none,SemiprimeD1StackVertexRecordStream.data [] [] []\n        (SemiprimeD1StackVertexProduct.records\n          (previous++[vertex (bitValue bits) hN (.inl (.second tr j)) ports hlen])++out)⟩ := by\n  rw [history_second_original bits hc hN tr j M ports hp hlen]\n  exact SemiprimeD1StackVertexRecordStreamExecution.reverse_original _ out\n/-- The actual source execution and exact old chronological record hold together. -/\ntheorem source_run_second_original (previous : List SemiprimeD1LeafCounter.Vertex) (old out : List Bool) :\n    ∃t≤timeBound bits true (selector tr) (ports.map (Bank.idAt M)),∃finish,\n      SemiprimeD1StackCalls.run program t\n        (initial bits true (selector tr) (SemiprimeD1TensorTapeCodec.vectorBits (ports.map (Bank.idAt M)))\n          (Log.history previous old) out)=some finish ∧\n      finish=done bits true (selector tr) (ports.map (Bank.idAt M)) (Log.history previous old) out ∧\n      finish.data G.history=Log.history\n        (previous++[vertex (bitValue bits) hN (.inl (.second tr j)) ports hlen]) old := by\n  obtain ⟨t,ht,hr⟩:=source_run bits true (selector tr) hc hN (ports.map (Bank.idAt M)) (Log.history previous old) out\n  exact ⟨t,ht,_,hr,rfl,history_second_original bits hc hN tr j M ports hp hlen previous old out⟩\nomit hp in\n/-- Each individual acquired coefficient is the exact original integer0/1. -/\ntheorem literal_second_original_coefficient\n    (input : Fin (SemiprimeMacroGraph.arity (.second tr j : SemiprimeMacroGraph.Vertex\n      (firstAxis (bitLength (bitValue bits))) (secondAxis (bitLength (bitValue bits)))\n      (digitCount (bitLength (bitValue bits)))))→Bool) :\n    SemiprimeD1JetAlgebra.coefficient (SemiprimeD1JetBoxIndex.dims [])\n      (SemiprimeD1JetBoxIndex.exponent [] 0)\n      (SemiprimeD1JetBoxIndex.exponent_inBox [] 0 (by simp) (by decide))\n      (SemiprimeD1JetLiteralLift.literal []\n        (SemiprimeD1StackStaticTableSpec.leafWords (T.answer bits true (selector tr)) (List.ofFn input)))=\n      if (SemiprimeMacroEntryBitCheck.publicBitEntry (bitValue bits) hN (.second tr j) input).accepted\n        then 1 else 0 :=\n  SemiprimeD1StackPublicTransformTableOriginal.literal_second_original_coefficient bits hc hN tr j input\nend Second\nend RiemannGaussian.SemiprimeD1StackPublicTransformRecordOriginal\n","RiemannGaussian.SemiprimeD1StackPublicTransformWords":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicTransformSetup\n/-! # Actual consecutive input/output vector acquisition from raw assignment\nNo prepared vector/word family, arity/count answer or getter is an executing\ninput. Count and width caches are the original acquisition's ACTUAL copies.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 100000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackPublicTransformWords\nopen SemiprimeD1StackPublicTransform SemiprimeD1StackPublicTransformState SemiprimeD1StackPublicTransformSetup\nopen SemiprimeD1StackProcedureTrace\n/-- Actual physical M cache read, proof-side only. -/\ndef modulusWord (root : R.Stack→List Bool) : List Bool := root (.inl R.modulusKey)\n/-- Actual acquired n-marker cache read, proof-side only. -/\ndef countWord (root : R.Stack→List Bool) (second : Bool) : List Bool := root (axisRole second)\n/-- The actual unread raw source after first n physical word blocks. -/\ndef outputRaw (root : R.Stack→List Bool) (raw : List Bool) (second : Bool) : List Bool :=\n  raw.drop ((countWord root second).length*(modulusWord root).length)\n/-- The first actual acquired word family, specification only. -/\ndef inputs (root : R.Stack→List Bool) (raw : List Bool) (second : Bool) : List (List Bool) :=\n  SemiprimeD1StackWordVectorSpec.blocks (modulusWord root) (countWord root second).length raw\n/-- The second actual acquired word family, specification only. -/\ndef outputs (root : R.Stack→List Bool) (raw : List Bool) (second : Bool) : List (List Bool) :=\n  SemiprimeD1StackWordVectorSpec.blocks (modulusWord root) (countWord root second).length (outputRaw root raw second)\n/-- Actual raw copy after metadata/normalization has been physically constructed. -/\ndef inputReady (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) : Parts :=\n  copied (normalizedParts root raw second inverse) .rawInput\n/-- Exact complete state after whole first WordVector call. -/\ndef inputAcquired (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) : Parts :=\n  {inputReady root raw second inverse with inputVector:=\n    (SemiprimeD1StackWordVectorExecution.done raw (modulusWord root) (countWord root second)).data}\n/-- The actual unread output block is physically copied to the second producer. -/\ndef outputReady (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) : Parts :=\n  copied (inputAcquired root raw second inverse) .rawOutput\n/-- Exact complete state after BOTH actual word-vector acquisitions. -/\ndef bothAcquired (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) : Parts :=\n  {outputReady root raw second inverse with outputVector:=\n    (SemiprimeD1StackWordVectorExecution.done (outputRaw root raw second) (modulusWord root) (countWord root second)).data}\n/-- The original raw input is a real preserving copy, never a native grouping. -/\ntheorem input_copy (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) :\n    Runs program (5*raw.length+4) .copyRawInput (data (normalizedParts root raw second inverse)) .acquireInput\n      (data (inputReady root raw second inverse)) :=\n  copy_run .rawInput .copyRawInput .acquireInput rfl (normalizedParts root raw second inverse) rfl rfl\n/-- Original source/width/count placement equals the ACTUAL first producer input. -/\ntheorem input_initial (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) :\n    (inputReady root raw second inverse).inputVector=(W.initial raw (modulusWord root) (countWord root second)).data := by\n  funext k;rcases k with k|k <;> fin_cases k <;> rfl\n/-- WHOLE first vector producer executes; every read/copy/pad/frame is retained. -/\ntheorem input_call (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) :\n    ∃t≤SemiprimeD1StackWordVectorExecution.timeBound raw (modulusWord root) (countWord root second)+1,\n      Runs program t .acquireInput (data (inputReady root raw second inverse)) .copyRawOutput\n        (data (inputAcquired root raw second inverse)) := by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackWordVectorExecution.source_run raw (modulusWord root) (countWord root second)\n  refine ⟨t+1,Nat.add_le_add_right ht 1,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program Stack.inputVector Label.inputWords\n    (by intro i j h;exact Stack.inputVector.inj h) W.program (.control .start) (fun _=>rfl)\n    .acquireInput .copyRawOutput rfl t (W.initial raw (modulusWord root) (countWord root second))\n    (SemiprimeD1StackWordVectorExecution.done raw (modulusWord root) (countWord root second)) _ _ rfl rfl rfl rfl hr\n  · constructor\n    · intro k;exact congrFun (input_initial root raw second inverse) k\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk;cases k <;> first | rfl | exact (hk _ rfl).elim\n/-- Output-source acquisition copies the ACTUAL first producer's unread suffix. -/\ntheorem output_copy (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) :\n    Runs program (5*(outputRaw root raw second).length+4) .copyRawOutput\n      (data (inputAcquired root raw second inverse)) .acquireOutput (data (outputReady root raw second inverse)) :=\n  copy_run .rawOutput .copyRawOutput .acquireOutput rfl (inputAcquired root raw second inverse) rfl rfl\n/-- Output producer is filled by physical source/caches, not supplied output words. -/\ntheorem output_initial (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) :\n    (outputReady root raw second inverse).outputVector=\n      (W.initial (outputRaw root raw second) (modulusWord root) (countWord root second)).data := by\n  funext k;rcases k with k|k <;> fin_cases k <;> rfl\n/-- WHOLE second producer executes on the physically copied unread suffix. -/\ntheorem output_call (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) :\n    ∃t≤SemiprimeD1StackWordVectorExecution.timeBound (outputRaw root raw second) (modulusWord root) (countWord root second)+1,\n      Runs program t .acquireOutput (data (outputReady root raw second inverse)) .copyInputDot\n        (data (bothAcquired root raw second inverse)) := by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackWordVectorExecution.source_run (outputRaw root raw second) (modulusWord root) (countWord root second)\n  refine ⟨t+1,Nat.add_le_add_right ht 1,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program Stack.outputVector Label.outputWords\n    (by intro i j h;exact Stack.outputVector.inj h) W.program (.control .start) (fun _=>rfl)\n    .acquireOutput .copyInputDot rfl t (W.initial (outputRaw root raw second) (modulusWord root) (countWord root second))\n    (SemiprimeD1StackWordVectorExecution.done (outputRaw root raw second) (modulusWord root) (countWord root second))\n    _ _ rfl rfl rfl rfl hr\n  · constructor\n    · intro k;exact congrFun (output_initial root raw second inverse) k\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk;cases k <;> first | rfl | exact (hk _ rfl).elim\n/-- Actual executed two-vector acquisition allowance, including all source copies. -/\ndef wordsBudget (root : R.Stack→List Bool) (raw : List Bool) (second : Bool) : ℕ :=\n  (5*raw.length+4)+(SemiprimeD1StackWordVectorExecution.timeBound raw (modulusWord root) (countWord root second)+1)+\n    (5*(outputRaw root raw second).length+4)+\n    (SemiprimeD1StackWordVectorExecution.timeBound (outputRaw root raw second) (modulusWord root) (countWord root second)+1)\n/-- ENTIRE literal raw→input/output vectors; no word/vector/count answer premise. -/\ntheorem words_run (root : R.Stack→List Bool) (raw : List Bool) (second inverse : Bool) :\n    ∃t≤wordsBudget root raw second,Runs program t .copyRawInput\n      (data (normalizedParts root raw second inverse)) .copyInputDot (data (bothAcquired root raw second inverse)) := by\n  obtain ⟨u,hu,h0⟩:=input_call root raw second inverse\n  obtain ⟨v,hv,h1⟩:=output_call root raw second inverse\n  have h:=runs_trans program _ _ _ _ _ _ _ _\n    (runs_trans program _ _ _ _ _ _ _ _ (runs_trans program _ _ _ _ _ _ _ _ (input_copy root raw second inverse) h0)\n      (output_copy root raw second inverse)) h1\n  refine ⟨(5*raw.length+4)+u+(5*(outputRaw root raw second).length+4)+v,?_,h⟩\n  unfold wordsBudget;omega\nend RiemannGaussian.SemiprimeD1StackPublicTransformWords\n","RiemannGaussian.SemiprimeD1StackRationalNormalizeEncoding":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRationalNormalizeSpec\n/-! # Complete actual22-word rational normalization boundaries -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRationalNormalizeEncoding\nopen SemiprimeD1StackRationalNormalize\n/-- Every actual source, arithmetic, scratch, sign and output word. -/\nstructure Words where\n  /-- Actual x Boolean word. -/\n  x:List Bool:=[]\n  /-- Actual y Boolean word. -/\n  y:List Bool:=[]\n  /-- Actual digits Boolean word. -/\n  digits:List Bool:=[]\n  /-- Actual left Boolean word. -/\n  left:List Bool:=[]\n  /-- Actual right Boolean word. -/\n  right:List Bool:=[]\n  /-- Actual scratch Boolean word. -/\n  scratch:List Bool:=[]\n  /-- Actual difference Boolean word. -/\n  difference:List Bool:=[]\n  /-- Actual remainder Boolean word. -/\n  remainder:List Bool:=[]\n  /-- Actual quotient Boolean word. -/\n  quotient:List Bool:=[]\n  /-- Actual copyScratch Boolean word. -/\n  copyScratch:List Bool:=[]\n  /-- Actual template Boolean word. -/\n  template:List Bool:=[]\n  /-- Actual originalLeft Boolean word. -/\n  originalLeft:List Bool:=[]\n  /-- Actual originalRight Boolean word. -/\n  originalRight:List Bool:=[]\n  /-- Actual fuel Boolean word. -/\n  fuel:List Bool:=[]\n  /-- Actual scan Boolean word. -/\n  scan:List Bool:=[]\n  /-- Actual next Boolean word. -/\n  next:List Bool:=[]\n  /-- Actual trimScratch Boolean word. -/\n  trimScratch:List Bool:=[]\n  /-- Actual output Boolean word. -/\n  output:List Bool:=[]\n  /-- Actual originalSigned Boolean word. -/\n  originalSigned:List Bool:=[]\n  /-- Actual numeratorOutput Boolean word. -/\n  numeratorOutput:List Bool:=[]\n  /-- Actual denominatorOutput Boolean word. -/\n  denominatorOutput:List Bool:=[]\n  /-- Actual signOutput Boolean word. -/\n  signOutput:List Bool:=[]\n/-- Complete literal physical store, including every reused GCD/Divider role. -/\ndef bank (w:Words) :Stack→List Bool\n  | .inl (.inl (.inr .input))=>w.x\n  | .inl (.inl (.inr .divisor))=>w.y\n  | .inl (.inl (.inr .digits))=>w.digits\n  | .inl (.inl (.inl .left))=>w.left\n  | .inl (.inl (.inl .right))=>w.right\n  | .inl (.inl (.inl .scratch))=>w.scratch\n  | .inl (.inl (.inl .output))=>w.difference\n  | .inl (.inl (.inr .remainder))=>w.remainder\n  | .inl (.inl (.inr .quotient))=>w.quotient\n  | .inl (.inl (.inr .copyScratch))=>w.copyScratch\n  | .inl (.inl (.inr .template))=>w.template\n  | .inl (.inr .left)=>w.originalLeft\n  | .inl (.inr .right)=>w.originalRight\n  | .inl (.inr .fuel)=>w.fuel\n  | .inl (.inr .scan)=>w.scan\n  | .inl (.inr .next)=>w.next\n  | .inl (.inr .trimScratch)=>w.trimScratch\n  | .inl (.inr .output)=>w.output\n  | .inr .originalSigned=>w.originalSigned\n  | .inr .numeratorOutput=>w.numeratorOutput\n  | .inr .denominatorOutput=>w.denominatorOutput\n  | .inr .signOutput=>w.signOutput\n/-- A real x update preserves every other physical word. -/\ntheorem update_x (w:Words) (xs:List Bool) :\n    Function.update (bank w) (dividerStack (.inr .input)) xs=bank {w with x:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k <;> cases k <;> rfl\n    · cases k <;> rfl\n  · cases k <;> rfl\n/-- A real y update preserves every other physical word. -/\ntheorem update_y (w:Words) (xs:List Bool) :\n    Function.update (bank w) (dividerStack (.inr .divisor)) xs=bank {w with y:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k <;> cases k <;> rfl\n    · cases k <;> rfl\n  · cases k <;> rfl\n/-- A real digits update preserves every other physical word. -/\ntheorem update_digits (w:Words) (xs:List Bool) :\n    Function.update (bank w) (dividerStack (.inr .digits)) xs=bank {w with digits:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k <;> cases k <;> rfl\n    · cases k <;> rfl\n  · cases k <;> rfl\n/-- A real left update preserves every other physical word. -/\ntheorem update_left (w:Words) (xs:List Bool) :\n    Function.update (bank w) (dividerStack (.inl .left)) xs=bank {w with left:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k <;> cases k <;> rfl\n    · cases k <;> rfl\n  · cases k <;> rfl\n/-- A real right update preserves every other physical word. -/\ntheorem update_right (w:Words) (xs:List Bool) :\n    Function.update (bank w) (dividerStack (.inl .right)) xs=bank {w with right:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k <;> cases k <;> rfl\n    · cases k <;> rfl\n  · cases k <;> rfl\n/-- A real scratch update preserves every other physical word. -/\ntheorem update_scratch (w:Words) (xs:List Bool) :\n    Function.update (bank w) (dividerStack (.inl .scratch)) xs=bank {w with scratch:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k <;> cases k <;> rfl\n    · cases k <;> rfl\n  · cases k <;> rfl\n/-- A real difference update preserves every other physical word. -/\ntheorem update_difference (w:Words) (xs:List Bool) :\n    Function.update (bank w) (dividerStack (.inl .output)) xs=bank {w with difference:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k <;> cases k <;> rfl\n    · cases k <;> rfl\n  · cases k <;> rfl\n/-- A real remainder update preserves every other physical word. -/\ntheorem update_remainder (w:Words) (xs:List Bool) :\n    Function.update (bank w) (dividerStack (.inr .remainder)) xs=bank {w with remainder:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k <;> cases k <;> rfl\n    · cases k <;> rfl\n  · cases k <;> rfl\n/-- A real quotient update preserves every other physical word. -/\ntheorem update_quotient (w:Words) (xs:List Bool) :\n    Function.update (bank w) (dividerStack (.inr .quotient)) xs=bank {w with quotient:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k <;> cases k <;> rfl\n    · cases k <;> rfl\n  · cases k <;> rfl\n/-- A real copyScratch update preserves every other physical word. -/\ntheorem update_copyScratch (w:Words) (xs:List Bool) :\n    Function.update (bank w) (dividerStack (.inr .copyScratch)) xs=bank {w with copyScratch:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k <;> cases k <;> rfl\n    · cases k <;> rfl\n  · cases k <;> rfl\n/-- A real template update preserves every other physical word. -/\ntheorem update_template (w:Words) (xs:List Bool) :\n    Function.update (bank w) (dividerStack (.inr .template)) xs=bank {w with template:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k <;> cases k <;> rfl\n    · cases k <;> rfl\n  · cases k <;> rfl\n/-- A real originalLeft update preserves every other physical word. -/\ntheorem update_originalLeft (w:Words) (xs:List Bool) :\n    Function.update (bank w) (gcdStack (SemiprimeD1StackEuclidGCD.aux .left)) xs=bank {w with originalLeft:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k <;> cases k <;> rfl\n    · cases k <;> rfl\n  · cases k <;> rfl\n/-- A real originalRight update preserves every other physical word. -/\ntheorem update_originalRight (w:Words) (xs:List Bool) :\n    Function.update (bank w) (gcdStack (SemiprimeD1StackEuclidGCD.aux .right)) xs=bank {w with originalRight:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k <;> cases k <;> rfl\n    · cases k <;> rfl\n  · cases k <;> rfl\n/-- A real fuel update preserves every other physical word. -/\ntheorem update_fuel (w:Words) (xs:List Bool) :\n    Function.update (bank w) (gcdStack (SemiprimeD1StackEuclidGCD.aux .fuel)) xs=bank {w with fuel:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k <;> cases k <;> rfl\n    · cases k <;> rfl\n  · cases k <;> rfl\n/-- A real scan update preserves every other physical word. -/\ntheorem update_scan (w:Words) (xs:List Bool) :\n    Function.update (bank w) (gcdStack (SemiprimeD1StackEuclidGCD.aux .scan)) xs=bank {w with scan:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k <;> cases k <;> rfl\n    · cases k <;> rfl\n  · cases k <;> rfl\n/-- A real next update preserves every other physical word. -/\ntheorem update_next (w:Words) (xs:List Bool) :\n    Function.update (bank w) (gcdStack (SemiprimeD1StackEuclidGCD.aux .next)) xs=bank {w with next:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k <;> cases k <;> rfl\n    · cases k <;> rfl\n  · cases k <;> rfl\n/-- A real trimScratch update preserves every other physical word. -/\ntheorem update_trimScratch (w:Words) (xs:List Bool) :\n    Function.update (bank w) (gcdStack (SemiprimeD1StackEuclidGCD.aux .trimScratch)) xs=bank {w with trimScratch:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k <;> cases k <;> rfl\n    · cases k <;> rfl\n  · cases k <;> rfl\n/-- A real output update preserves every other physical word. -/\ntheorem update_output (w:Words) (xs:List Bool) :\n    Function.update (bank w) (gcdStack (SemiprimeD1StackEuclidGCD.aux .output)) xs=bank {w with output:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k <;> cases k <;> rfl\n    · cases k <;> rfl\n  · cases k <;> rfl\n/-- A real originalSigned update preserves every other physical word. -/\ntheorem update_originalSigned (w:Words) (xs:List Bool) :\n    Function.update (bank w) (aux .originalSigned) xs=bank {w with originalSigned:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k <;> cases k <;> rfl\n    · cases k <;> rfl\n  · cases k <;> rfl\n/-- A real numeratorOutput update preserves every other physical word. -/\ntheorem update_numeratorOutput (w:Words) (xs:List Bool) :\n    Function.update (bank w) (aux .numeratorOutput) xs=bank {w with numeratorOutput:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k <;> cases k <;> rfl\n    · cases k <;> rfl\n  · cases k <;> rfl\n/-- A real denominatorOutput update preserves every other physical word. -/\ntheorem update_denominatorOutput (w:Words) (xs:List Bool) :\n    Function.update (bank w) (aux .denominatorOutput) xs=bank {w with denominatorOutput:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k <;> cases k <;> rfl\n    · cases k <;> rfl\n  · cases k <;> rfl\n/-- A real signOutput update preserves every other physical word. -/\ntheorem update_signOutput (w:Words) (xs:List Bool) :\n    Function.update (bank w) (aux .signOutput) xs=bank {w with signOutput:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k <;> cases k <;> rfl\n    · cases k <;> rfl\n  · cases k <;> rfl\n/-- Every initialized byte is one of the two retained original words. -/\ntheorem initial_bank (signed den:List Bool) :\n    input signed den=bank {originalSigned:=signed,originalRight:=den}:=by\n  funext k;rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k <;> cases k <;> rfl\n    · cases k <;> rfl\n  · cases k <;> rfl\n/-- Acquired magnitude and parsed sign are physical cache words before the denominator guard. -/\ndef parsed (negative:Bool) (num den:List Bool) :Words:=\n  {originalSigned:=negative::num,originalLeft:=num,originalRight:=den,signOutput:=[negative]}\n/-- Clean positive arithmetic boundary retains the acquired magnitude, original inputs and parsed sign. -/\ndef ready (negative:Bool) (num den g n d:List Bool) :Words:=\n  {parsed negative num den with output:=g,numeratorOutput:=n,denominatorOutput:=d}\n/-- Whole output retains the original signed bytes and original denominator, with all arithmetic words empty. -/\ndef result (negative:Bool) (num den:List Bool) :Stack→List Bool:=bank { originalSigned:=negative::num,originalRight:=den, signOutput:=[(SemiprimeD1StackRationalNormalizeSpec.word negative num den).numerator.negative], numeratorOutput:=(SemiprimeD1StackRationalNormalizeSpec.word negative num den).numerator.magnitude, denominatorOutput:=(SemiprimeD1StackRationalNormalizeSpec.word negative num den).denominator}\n/-- Interpretation reads all THREE actual stopped output words; it is never a runtime getter. -/\ndef outputWord (data:Stack→List Bool) :SemiprimeRationalBits.RationalWord:=\n  ⟨⟨((data (aux .signOutput)).head?).getD false,data (aux .numeratorOutput)⟩,data (aux .denominatorOutput)⟩\n/-- Actual final halt with exact full physical bank and cleared flags/returns. -/\ndef done (negative:Bool) (num den:List Bool) :C.State Stack Label:=⟨none,none,none,result negative num den,[]⟩\n/-- Both original binary words, their physical sign head and one positive terminal allowance. -/\ndef inputSize (num den:List Bool) :Nat:=num.length+den.length+2\nend RiemannGaussian.SemiprimeD1StackRationalNormalizeEncoding\n","RiemannGaussian.SemiprimeD1StackRationalOperation":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRationalNormalizeStorage\nimport RiemannGaussian.SemiprimeD1StackWordFitExecution\nimport RiemannGaussian.SemiprimeD1StackMultiplierExecution\n/-! # Literal rational operations, normalization and both physical width fits\nOnly four original operand words and one actual width template are supplied.\nThe complete multiplier, signed add/subtract, canonical normalization and both\nfits execute on these words. All original inputs are retained. Shared arithmetic\nbanks are physically emptied between calls; no raw answer or width is supplied.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRationalOperation\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State)\nend C\nnamespace N\nexport SemiprimeD1StackRationalNormalize (Stack Label program)\nend N\nnamespace M\nexport SemiprimeD1StackMultiplier (Stack Label code)\nend M\nnamespace A\nexport SemiprimeD1StackAdder (Stack Label code)\nend A\nnamespace S\nexport SemiprimeD1StackSubtractor (Label code)\nend S\nnamespace F\nexport SemiprimeD1StackWordFit (Label program)\nend F\n/-- Four finite operations, fixed before every operand and template. -/\ninductive Op where | add | mul | neg | inv deriving DecidableEq,Repr\n/-- Complete finite operation inventory. -/\ninstance :Fintype Op:=Fintype.ofList [.add,.mul,.neg,.inv] (by intro k;cases k <;> simp)\n/-- Mathematical interpretation of the actual finite operation entry. -/\ndef operation :Op→SemiprimeRationalBits.Operation\n  | .add=>.add | .mul=>.mul | .neg=>.neg | .inv=>.inv\n/-- Five retained original tapes, two acquired magnitude caches and two fitted outputs. -/\ninductive Aux where | leftSigned | leftDen | rightSigned | rightDen | template | leftMagnitude | rightMagnitude | numeratorOutput | denominatorOutput\n  deriving DecidableEq,Repr\n/-- Complete literal caller inventory. -/\ninstance :Fintype Aux:=Fintype.ofList [.leftSigned,.leftDen,.rightSigned,.rightDen,.template,\n  .leftMagnitude,.rightMagnitude,.numeratorOutput,.denominatorOutput] (by intro k;cases k <;> simp)\n/-- All22 normalization words, five additional multiplier words and nine caller words. -/\nabbrev Stack:=N.Stack⊕((Fin 3⊕Bool)⊕Aux)\n/-- Complete actual normalization inclusion. -/\ndef normalizeStack :N.Stack→Stack:=Sum.inl\n/-- Actual caller addresses. -/\ndef aux (k:Aux) :Stack:=.inr (.inr k)\n/-- Shared four-word ripple bank, reused only after complete real cleanup. -/\ndef adderStack (k:A.Stack) :Stack:=normalizeStack (SemiprimeD1StackRationalNormalize.dividerStack (.inl k))\n/-- Multiplier's four ripple words share the actual normalization bank; five words are additional. -/\ndef multiplierStack :M.Stack→Stack\n  | .inl k=>adderStack k | .inr k=>.inr (.inl k)\n/-- Actual shared preserving-copy scratch. -/\ndef copyScratch :Stack:=normalizeStack SemiprimeD1StackRationalNormalize.copyScratch\n/-- Raw acquired signed numerator directly feeds the real normalization front door. -/\ndef rawSigned :Stack:=normalizeStack (SemiprimeD1StackRationalNormalize.aux .originalSigned)\n/-- Raw acquired denominator directly feeds the real normalization front door. -/\ndef rawDen :Stack:=normalizeStack SemiprimeD1StackRationalNormalize.denominator\n/-- First cross-product temporarily uses a normalization magnitude word, drained before its call. -/\ndef crossLeft :Stack:=normalizeStack SemiprimeD1StackRationalNormalize.numerator\n/-- Second cross-product temporarily uses the GCD output word, drained before normalization. -/\ndef crossRight :Stack:=normalizeStack SemiprimeD1StackRationalNormalize.gcdOutput\n/-- Exact normalized sign, retained by both magnitude fits. -/\ndef signOutput :Stack:=normalizeStack (SemiprimeD1StackRationalNormalize.aux .signOutput)\n/-- Four exact multiplication orientations used by legacy rational add/multiply. -/\ninductive Product where | crossLeft | crossRight | numerator | denominator deriving DecidableEq,Repr\n/-- Complete finite multiplication inventory. -/\ninstance :Fintype Product:=Fintype.ofList [.crossLeft,.crossRight,.numerator,.denominator] (by intro k;cases k <;> simp)\n/-- Fourteen physically distinct preserving-copy routes. -/\ninductive Copy where | signedLeft | signedRight | productLeft (p:Product) | productRight (p:Product) | productSave (p:Product)\n  | addLeft (reverse:Bool) | addRight (reverse:Bool) | addSave | unaryNumerator (inverse:Bool) | unaryDenominator (inverse:Bool)\n  deriving DecidableEq,Fintype,Repr\n/-- Original/current operands for each actual oriented product. -/\ndef productOperand (p:Product) (right:Bool) :Stack:=match p,right with\n  | .crossLeft,false|.numerator,false=>aux .leftMagnitude\n  | .crossRight,false|.numerator,true=>aux .rightMagnitude\n  | .crossLeft,true|.denominator,true=>aux .rightDen\n  | .crossRight,true|.denominator,false=>aux .leftDen\n/-- Literal acquired destination of each completed product. -/\ndef productOutput :Product→Stack\n  | .crossLeft=>crossLeft | .crossRight=>crossRight | .numerator=>rawSigned | .denominator=>rawDen\n/-- Every copy has three distinct literal physical operands. -/\ndef copyStack (what:Copy) (k:Fin 3) :Stack:=\n  if k=0 then match what with\n    | .signedLeft=>aux .leftSigned | .signedRight=>aux .rightSigned\n    | .productLeft p=>productOperand p false | .productRight p=>productOperand p true\n    | .productSave _=>adderStack .right\n    | .addLeft rev=>if rev then crossRight else crossLeft\n    | .addRight rev=>if rev then crossLeft else crossRight\n    | .addSave=>adderStack .output\n    | .unaryNumerator inv=>if inv then aux .leftDen else aux .leftMagnitude\n    | .unaryDenominator inv=>if inv then aux .leftMagnitude else aux .leftDen\n  else if k=1 then match what with\n    | .signedLeft=>aux .leftMagnitude | .signedRight=>aux .rightMagnitude\n    | .productLeft _=>multiplierStack SemiprimeD1StackMultiplier.input\n    | .productRight _=>multiplierStack SemiprimeD1StackMultiplier.factor\n    | .productSave p=>productOutput p\n    | .addLeft _=>adderStack .left | .addRight _=>adderStack .right\n    | .addSave|.unaryNumerator _=>rawSigned | .unaryDenominator _=>rawDen\n  else copyScratch\n/-- Five distinct fit addresses; both fit calls retain the actual caller template. -/\ndef fitStack (den:Bool) (k:Fin 5) :Stack:=\n  if k=0 then normalizeStack (SemiprimeD1StackRationalNormalize.aux (if den then .denominatorOutput else .numeratorOutput))\n  else if k=1 then aux .template\n  else if k=2 then normalizeStack SemiprimeD1StackRationalNormalize.x\n  else if k=3 then normalizeStack SemiprimeD1StackRationalNormalize.y\n  else aux (if den then .denominatorOutput else .numeratorOutput)\n/-- All actual local stages; only operation bits, parsed signs and finite call routes enter control. -/\ninductive Phase where\n  | start | parseLeft | rightCopy | parseRight | dispatch\n  | productLeft (p:Product) | productRight (p:Product) | multiply (p:Product) | productSave (p:Product) | productClear (p:Product)\n  | addLeft (reverse:Bool) | addRight (reverse:Bool) | combine (reverse:Bool) | borrow (reverse:Bool)\n  | discardDifference | addSave (negative:Bool) | clearDifference (negative:Bool)\n  | unaryNumerator | unaryDenominator | rawSign (negative:Bool)\n  | clearMagnitudeLeft | clearMagnitudeRight | clearCrossLeft | clearCrossRight\n  | normalize | fit (den:Bool) | clearRawSigned | clearRawDen | done | abort\n  deriving DecidableEq,Fintype,Repr\n/-- Finite local controls and real included-program labels. -/\ninductive Label where\n  | local (phase:Phase) (op:Op) (sx sy:Bool)\n  | normalize (pc:N.Label) | multiply (pc:M.Label) | adder (pc:A.Label) | subtractor (pc:S.Label)\n  | copier (what:Copy) (pc:Fin 9) | fit (den:Bool) (pc:F.Label)\n  deriving Fintype\n/-- Literal local label constructor. -/\ndef localLabel (p:Phase) (op:Op) (sx sy:Bool) :Label:=.local p op sx sy\n/-- Next actual product stage, never a numerical instruction. -/\ndef afterProduct (p:Product) (op:Op) (sx sy:Bool) :Label:=localLabel (match p with\n  | .crossLeft=>.productLeft .crossRight | .crossRight=>.addLeft false\n  | .numerator=>.rawSign (Bool.xor sx sy) | .denominator=>.clearMagnitudeLeft) op sx sy\n/-- One fixed finite source; all arithmetic, sign selection, normalization and both fits are actual calls. -/\ndef program :Label→C.Instruction Stack Label\n  | .normalize pc=>SemiprimeD1StackValidationLink.instruction normalizeStack Label.normalize (N.program pc)\n  | .multiply pc=>SemiprimeD1StackValidationLink.instruction multiplierStack Label.multiply (M.code pc)\n  | .adder pc=>SemiprimeD1StackMultiplierLink.instruction adderStack Label.adder (A.code pc)\n  | .subtractor pc=>SemiprimeD1StackMultiplierLink.instruction adderStack Label.subtractor (S.code pc)\n  | .copier what pc=>SemiprimeD1StackMultiplierLink.instruction (copyStack what) (Label.copier what) (SemiprimeD1StackCopy.code pc)\n  | .fit den pc=>SemiprimeD1StackValidationLink.instruction (fitStack den) (Label.fit den) (F.program pc)\n  | .local phase op sx sy=>\n    let go:=fun p=>localLabel p op sx sy\n    match phase with\n    | .start=>.call (.copier .signedLeft 0) (go .parseLeft)\n    | .parseLeft=>.base (.pop (aux .leftMagnitude) (go .abort)\n        (localLabel (if op=.add ∨ op=.mul then .rightCopy else .dispatch) op false false)\n        (localLabel (if op=.add ∨ op=.mul then .rightCopy else .dispatch) op true false))\n    | .rightCopy=>.call (.copier .signedRight 0) (go .parseRight)\n    | .parseRight=>.base (.pop (aux .rightMagnitude) (go .abort) (localLabel .dispatch op sx false) (localLabel .dispatch op sx true))\n    | .dispatch=>match op with\n      | .add=>.call (.copier (.productLeft .crossLeft) 0) (go (.productRight .crossLeft))\n      | .mul=>.call (.copier (.productLeft .numerator) 0) (go (.productRight .numerator))\n      | .neg|.inv=>.call (.copier (.unaryNumerator (op=.inv)) 0) (go .unaryDenominator)\n    | .productLeft p=>.call (.copier (.productLeft p) 0) (go (.productRight p))\n    | .productRight p=>.call (.copier (.productRight p) 0) (go (.multiply p))\n    | .multiply p=>.call (.multiply (.control .start)) (go (.productSave p))\n    | .productSave p=>.call (.copier (.productSave p) 0) (go (.productClear p))\n    | .productClear p=>.base (.pop (adderStack .right) (afterProduct p op sx sy) (go (.productClear p)) (go (.productClear p)))\n    | .addLeft rev=>.call (.copier (.addLeft rev) 0) (go (.addRight rev))\n    | .addRight rev=>.call (.copier (.addRight rev) 0) (go (.combine rev))\n    | .combine rev=>if sx=sy then .call (.adder (.start false)) (go (.addSave sx))\n      else .call (.subtractor (.start false)) (go (.borrow rev))\n    | .borrow rev=>.base (.pop (adderStack .output) (go .abort)\n        (go (.addSave (if rev then sy else sx))) (if rev then go (.addSave sy) else go .discardDifference))\n    | .discardDifference=>.base (.pop (adderStack .output) (go (.addLeft true)) (go .discardDifference) (go .discardDifference))\n    | .addSave negative=>.call (.copier .addSave 0) (go (.clearDifference negative))\n    | .clearDifference negative=>.base (.pop (adderStack .output) (go (.rawSign negative))\n        (go (.clearDifference negative)) (go (.clearDifference negative)))\n    | .unaryNumerator=>.call (.copier (.unaryNumerator (op=.inv)) 0) (go .unaryDenominator)\n    | .unaryDenominator=>.call (.copier (.unaryDenominator (op=.inv)) 0) (go (.rawSign (if op=.neg then !sx else sx)))\n    | .rawSign negative=>.base (.push rawSigned negative (if op=.add ∨ op=.mul then go (.productLeft .denominator) else go .clearMagnitudeLeft))\n    | .clearMagnitudeLeft=>.base (.pop (aux .leftMagnitude) (go .clearMagnitudeRight) (go .clearMagnitudeLeft) (go .clearMagnitudeLeft))\n    | .clearMagnitudeRight=>.base (.pop (aux .rightMagnitude) (go .clearCrossLeft) (go .clearMagnitudeRight) (go .clearMagnitudeRight))\n    | .clearCrossLeft=>.base (.pop crossLeft (go .clearCrossRight) (go .clearCrossLeft) (go .clearCrossLeft))\n    | .clearCrossRight=>.base (.pop crossRight (go .normalize) (go .clearCrossRight) (go .clearCrossRight))\n    | .normalize=>.call (.normalize .start) (go (.fit false))\n    | .fit den=>.call (.fit den .start) (go (if den then .clearRawSigned else .fit true))\n    | .clearRawSigned=>.base (.pop rawSigned (go .clearRawDen) (go .clearRawSigned) (go .clearRawSigned))\n    | .clearRawDen=>.base (.pop rawDen (go .done) (go .clearRawDen) (go .clearRawDen))\n    | .done|.abort=>.base .halt\n/-- The honest five-tape source initializes no arithmetic/cache/output word. -/\ndef input (ls ld rs rd template:List Bool) :Stack→List Bool:=\n  Sum.elim (fun _=>[]) (Sum.elim (fun _=>[]) (fun k=>match k with\n    | .leftSigned=>ls | .leftDen=>ld | .rightSigned=>rs | .rightDen=>rd | .template=>template | _=>[]))\n/-- Finite operation entry and only five actual input tapes. -/\ndef initial (op:Op) (ls ld rs rd template:List Bool) :C.State Stack Label:=\n  ⟨some (localLabel .start op false false),none,none,input ls ld rs rd template,[]⟩\n/-- Actual fixed finite36-role machine; the finite operation chooses only its entry. -/\ndef machine (op:Op) :Turing.FinTM2:=SemiprimeD1StackCalls.machine (aux .leftSigned) (aux .numeratorOutput) (localLabel .start op false false) program\n/-- Every allocated data role, including five additional multiplier words, is counted. -/\ntheorem stack_card :Fintype.card Stack=36:=by decide\n/-- The complete normalization bank is injectively included. -/\ntheorem normalize_injective :Function.Injective normalizeStack:=Sum.inl_injective\n/-- Shared four-word ripple operands are distinct. -/\ntheorem adder_injective :Function.Injective adderStack:=normalize_injective.comp (SemiprimeD1StackRationalNormalize.divider_injective.comp Sum.inl_injective)\n/-- All nine multiplier roles are distinct despite the four-word bank reuse. -/\ntheorem multiplier_injective :Function.Injective multiplierStack:=by decide\n/-- Every literal copy route has distinct actual operands. -/\ntheorem copy_injective (what:Copy) :Function.Injective (copyStack what):=by cases what <;> first | decide | (rename_i a;cases a <;> decide)\n/-- Both real fit calls have five pairwise distinct actual words. -/\ntheorem fit_injective (den:Bool) :Function.Injective (fitStack den):=by cases den <;> decide\n/-- Transient control is finite before all original data and template words. -/\ntheorem control_finite (op:Op) :Finite (machine op).σ:=SemiprimeD1StackCalls.control_finite _ _ _ _\n/-- Boolean data and genuine finite return alphabets are finite on every actual role. -/\ntheorem alphabets_finite (op:Op) :∀k,Finite ((machine op).Γ k):=SemiprimeD1StackCalls.all_alphabets_finite _ _ _ _\nend RiemannGaussian.SemiprimeD1StackRationalOperation\n","RiemannGaussian.SemiprimeD1StackRationalOperationPrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRationalOperation\nimport RiemannGaussian.SemiprimeD1StackProcedureCallsTrace\n/-! # Actual preserving copies and paid byte scans/drains -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRationalOperationPrimitives\nopen SemiprimeD1StackRationalOperation SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel data_update)\nend Link\n/-- Exact chronological source-fragment composition preserves every real outer return. -/\ntheorem join {m n:Nat} {pc mid next:Label} {before between after:Stack→List Bool}\n    (h:Runs program m pc before mid between) (g:Runs program n mid between next after) :\n    Runs program (m+n) pc before next after :=runs_trans program m n pc mid next before between after h g\n/-- Actual complete preserving copy, including both restoration loops and its real caller return. -/\ntheorem copy_call (what:Copy) (pc next:Label)\n    (hc:program pc=.call (.copier what 0) next) (before:Stack→List Bool) (xs ys:List Bool)\n    (hx:before (copyStack what 0)=xs) (hy:before (copyStack what 1)=ys) (hs:before (copyStack what 2)=[]) :\n    Runs program (5*xs.length+4) pc before next\n      (Function.update before (copyStack what 1) (xs++ys)) :=by\n  let start:=SemiprimeD1StackCopy.state 0 none xs ys []\n  let stop:=SemiprimeD1StackCopy.done xs (xs++ys)\n  have hi:Link.DataRel (copyStack what) before start.store before:=by\n    constructor\n    · intro k;fin_cases k\n      · exact hx\n      · exact hy\n      · exact hs\n    · intro k _;rfl\n  have ho:=Link.data_update (copyStack what) (copy_injective what) before start.store before hi (1:Fin 3) (xs++ys)\n  have he:Function.update start.store 1 (xs++ys)=stop.store:=by funext k;fin_cases k <;> rfl\n  rw [he] at ho\n  exact included_call program (copyStack what) (Label.copier what) (copy_injective what) SemiprimeD1StackCopy.code 0\n    (fun _=>rfl) pc next hc (5*xs.length+3) start stop before _ rfl rfl\n    (SemiprimeD1StackCopy.copy_words xs ys none) hi ho\n/-- One literal local push preserves the entire other physical bank and all real outer returns. -/\ntheorem push_run (pc:Label) (next:Label) (k:Stack) (b:Bool) (before:Stack→List Bool)\n    (hc:program pc=.base (.push k b next)) :\n    Runs program 1 pc before next (Function.update before k (b::before k)) :=\n  one_base program _ _ _ _ _ hc rfl rfl\n/-- One literal local pop consumes only the actual physical Boolean head. -/\ntheorem pop_run (pc:Label) (empty low high:Label) (k:Stack) (before:Stack→List Bool) (xs:List Bool)\n    (hc:program pc=.base (.pop k empty low high)) (hx:before k=xs) :\n    Runs program 1 pc before (SemiprimeD1StackBytecode.choose empty low high xs.head?) (Function.update before k xs.tail) :=by\n  apply one_base program pc _ (.pop k empty low high) before _ hc\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n/-- Every actual source peek preserves the entire acquired word. -/\ntheorem peek_run (pc:Label) (empty low high:Label) (k:Stack) (before:Stack→List Bool) (xs:List Bool)\n    (hc:program pc=.base (.peek k empty low high)) (hx:before k=xs) :\n    Runs program 1 pc before (SemiprimeD1StackBytecode.choose empty low high xs.head?) before :=by\n  apply one_base program pc _ (.peek k empty low high) before before hc\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n  · rfl\n/-- Every quotient/remainder/GCD/magnitude cleanup actually visits every byte and its final empty branch. -/\ntheorem drain_loop (pc:Label) (next:Label) (k:Stack)\n    (hc:program pc=.base (.pop k next pc pc)) (before:Stack→List Bool) (xs:List Bool) (hx:before k=xs) :\n    Runs program (xs.length+1) pc before next (Function.update before k []) :=by\n  induction xs generalizing before with\n  | nil=>exact pop_run pc next pc pc k before [] hc hx\n  | cons b xs ih=>\n    have h0:=pop_run pc next pc pc k before (b::xs) hc hx\n    have h1:=ih (Function.update before k xs) (Function.update_self _ _ _)\n    have hh:=join (by cases b <;> exact h0) h1\n    simpa only [List.length_cons,Function.update_idem,Nat.add_assoc,Nat.add_comm,Nat.add_left_comm] using hh\nend RiemannGaussian.SemiprimeD1StackRationalOperationPrimitives\n","RiemannGaussian.SemiprimeD1StackRecoveryAffineInnerClear":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffineOperationOutput\n/-! # All six real inner-pair fields are drained before the physical k decrement -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryAffineInnerClear\nopen SemiprimeD1StackRecoveryAffine SemiprimeD1StackRecoveryAffineView SemiprimeD1StackProcedureTrace\nopen SemiprimeD1StackRecoveryAffineCleanup\n/-- The six literal old-bank roles exactly match the already fixed source instructions. -/\ndef slot (i:Fin 6):Q.Stack:=match i.val with\n  | 0=>Q.reg .numBase false | 1=>Q.reg .numBase true | 2=>Q.reg .denBase false\n  | 3=>Q.reg .denBase true | 4=>Q.reg .numPower false | _=>Q.reg .numPower true\n/-- Both fields of all three actual transient rational caches are EMPTY at the endpoint. -/\ndef result (w:Words):Words:=\n  SemiprimeD1StackRecoveryAffineOperationOutput.emptyReg\n    (SemiprimeD1StackRecoveryAffineOperationOutput.emptyReg\n      (SemiprimeD1StackRecoveryAffineOperationOutput.emptyReg w .numBase) .denBase) .numPower\n/-- Exact six physical update endpoints, rather than a native replacement of the cleanup loop. -/\ntheorem cleared_result (w:Words):cleared slot w 6=bank (result w):=by\n  have h0:=cleared_succ slot w (0:Fin 6)\n  have h1:=cleared_succ slot w (1:Fin 6)\n  have h2:=cleared_succ slot w (2:Fin 6)\n  have h3:=cleared_succ slot w (3:Fin 6)\n  have h4:=cleared_succ slot w (4:Fin 6)\n  have h5:=cleared_succ slot w (5:Fin 6)\n  change Function.update (cleared slot w 0) (grid (slot (0:Fin 6))) []=cleared slot w 1 at h0\n  change Function.update (cleared slot w 1) (grid (slot (1:Fin 6))) []=cleared slot w 2 at h1\n  change Function.update (cleared slot w 2) (grid (slot (2:Fin 6))) []=cleared slot w 3 at h2\n  change Function.update (cleared slot w 3) (grid (slot (3:Fin 6))) []=cleared slot w 4 at h3\n  change Function.update (cleared slot w 4) (grid (slot (4:Fin 6))) []=cleared slot w 5 at h4\n  change Function.update (cleared slot w 5) (grid (slot (5:Fin 6))) []=cleared slot w 6 at h5\n  rw [←h5,←h4,←h3,←h2,←h1,←h0,cleared_zero]\n  change Function.update (Function.update (Function.update (Function.update (Function.update (Function.update\n    (bank w) (reg .numBase false) []) (reg .numBase true) []) (reg .denBase false) [])\n    (reg .denBase true) []) (reg .numPower false) []) (reg .numPower true) []=bank (result w)\n  simp only [update_register]\n  rfl\n/-- SAME actual program physically drains every byte and six actual EOF branches. -/\ntheorem source_run (part:Part) (w:Words):\n    ∃q≤6*(mass (bank w)+1),Runs program q (.local (.clearInner part 0)) (bank w)\n      (.local (.innerNext part)) (bank (result w)):=by\n  have hc:∀i:Fin 6,program (.local (.clearInner part i))=.base\n      (.pop (grid (slot i)) (next (fun j=>Label.local (.clearInner part j)) (.local (.innerNext part)) i)\n        (.local (.clearInner part i)) (.local (.clearInner part i))):=by\n    intro i\n    fin_cases i <;> rfl\n  obtain ⟨q,hq,hr⟩:=sweep (by decide:0<6) slot (fun i=>Label.local (.clearInner part i))\n    (.local (.innerNext part)) hc 5 0 rfl w\n  rw [cleared_zero,cleared_result] at hr\n  refine ⟨q,?_,hr⟩\n  have hsub:=old_mass_le w\n  nlinarith\nend RiemannGaussian.SemiprimeD1StackRecoveryAffineInnerClear\n","RiemannGaussian.SemiprimeD1StackRecoveryAffineLoopOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffineLoop\n/-! # The actual reverse-catalogue fold is exactly original affine build, including literal empty product -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryAffineLoopOriginal\nopen SemiprimeD1StackRecoveryAffineLoop SemiprimeD1StackRecoveryAffineLoopView\nopen SemiprimeRationalBits (RationalWord)\n/-- Chronological physical row traversal composes without replaying any source or recopying any accumulated tail. -/\ntheorem fold_append (width:List Bool) (q:Nat) (cs ds xs:List RationalWord):\n    fold width q (cs++ds) xs=fold width q ds (fold width q cs xs):=by\n  induction cs generalizing xs with\n  | nil=>rfl\n  | cons c cs ih=>exact ih (multiply width xs c q)\n/-- Exact raw affine array bytes preserve the native RIGHT fold's operand order and ALL fitted scalar operations. -/\ntheorem fold_original (width:List Bool) (q:Nat) (slopes:List RationalWord):\n    fold width q slopes.reverse [SemiprimeJetBits.oneWord]=\n      (SemiprimeAffineJetBits.build width q slopes).words.toList:=by\n  induction slopes with\n  | nil=>rfl\n  | cons c cs ih=>\n    rw [List.reverse_cons,fold_append,ih]\n    simp only [fold,multiply,SemiprimeAffineJetBits.build,SemiprimeAffineJetBits.affine,Array.toArray_toList]\nend RiemannGaussian.SemiprimeD1StackRecoveryAffineLoopOriginal\n","RiemannGaussian.SemiprimeD1StackRecoveryAffineSlopeStage":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffineCoefficientsOriginal\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffineArrayMove\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffineSlopeDrain\n/-! # Whole physical affine-array stage for one actually parsed original slope -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryAffineSlopeStage\nopen SemiprimeD1StackRecoveryAffine SemiprimeD1StackRecoveryAffineView SemiprimeD1StackProcedureTrace\nopen SemiprimeD1StackRecoveryAffineCoefficientBuffers\nopen SemiprimeD1StackRecoveryAffineReadCount (unary)\nopen SemiprimeD1StackRecoveryAffineOperationInput (emptyRational)\nnamespace T\nexport SemiprimeD1StackRecoveryAffinePrimitives (join push_run copy_call)\nend T\n/-- All actual original coefficient rows, with their paid physical vector terminator. -/\ndef bytes (xs:List SemiprimeRationalBits.RationalWord) (c:SemiprimeRationalBits.RationalWord) (width:List Bool) (q:Nat):List Bool:=\n  SemiprimeD1StackRecoveryAffineCoefficients.rows xs c width q [false]\n/-- Exact bank after real array replacement and actual current-slope drains. -/\ndef result (w:Words) (output:List Bool):Words:=\n  SemiprimeD1StackRecoveryAffineOperationOutput.emptyReg\n    (SemiprimeD1StackRecoveryAffineArrayMove.result (buffers w [] output) output) .slope\n/-- SAME stage's literal seed/copy, full coefficient loop, physical old-array I/O and slope drains. -/\ndef runBound (w:Words) (xs:List SemiprimeRationalBits.RationalWord) (c:SemiprimeRationalBits.RationalWord)\n    (width:List Bool) (q:Nat):Nat:=\n  1+(5*q+4)+SemiprimeD1StackRecoveryAffineCoefficients.runBound w xs c width q [false]+\n    SemiprimeD1StackRecoveryAffineArrayMove.runBound (vector xs) (bytes xs c width q)+\n      ((signed c).length+1+c.denominator.length+1)\n/-- Every coefficient and zero extension is actually acquired/evaluated, including q0/W0; no array is supplied. -/\ntheorem source_run (w:Words) (xs:List SemiprimeRationalBits.RationalWord) (q:Nat)\n    (c:SemiprimeRationalBits.RationalWord) (width:List Bool)\n    (ha:w.added .array=vector xs) (hq:w.added .retainedQ=unary q)\n    (hk:w.added .k=[]) (hrd:w.added .reader=[]) (ht:w.added .readTodo=[])\n    (hm:w.added .remaining=[]) (hn:w.added .nextArray=[])\n    (hx:∀b,w.registers (.numBase,b)=[]) (hy:∀b,w.registers (.denBase,b)=[]) (hp:∀b,w.registers (.numPower,b)=[])\n    (hz:∀b,w.registers (.denPower,b)=[])\n    (hc:w.auxiliary .copyScratch=[]) (hf:w.auxiliary .frameScratch=[]) (hv:w.auxiliary .scan=[])\n    (hr:w.rational=emptyRational width)\n    (hs:w.registers (.slope,false)=signed c) (hd:w.registers (.slope,true)=c.denominator):\n    ∃t≤runBound w xs c width q,Runs program t (.local .seedNext) (bank w)\n      (.local .slopeLoop) (bank (result w (bytes xs c width q))):=by\n  have hself:buffers w [] []=w:=by simpa only [hm,hn] using buffers_self w\n  have h0:=T.push_run (.local .seedNext) (.local .count) (aux .nextArray) false (bank (buffers w [] [])) rfl\n  change Runs program 1 _ _ _ (Function.update (bank (buffers w [] [])) (aux .nextArray) [false]) at h0\n  rw [update_next,hself] at h0\n  have h1:=T.copy_call .count (.local .count) (.local .coefficientLoop) rfl\n    (bank (buffers w [] [false])) (unary q) [] hq rfl hc\n  change Runs program _ _ _ _ (Function.update (bank (buffers w [] [false])) (aux .remaining) (unary q++[])) at h1\n  rw [List.append_nil,update_remaining] at h1\n  obtain ⟨t,htime,h2⟩:=SemiprimeD1StackRecoveryAffineCoefficients.source_run w xs q c width [false]\n    ha hk hrd ht hx hy hp hz hc hf hv hr hs hd\n  let output:=bytes xs c width q\n  let middle:=buffers w [] output\n  have h3:=SemiprimeD1StackRecoveryAffineArrayMove.source_run middle (vector xs) output ha rfl hc\n  have h4:=SemiprimeD1StackRecoveryAffineSlopeDrain.source_run\n    (SemiprimeD1StackRecoveryAffineArrayMove.result middle output)\n  change Runs program ((w.registers (.slope,false)).length+1+(w.registers (.slope,true)).length+1) _ _ _ _ at h4\n  rw [hs,hd] at h4\n  refine ⟨1+(5*(unary q).length+4)+t+\n      SemiprimeD1StackRecoveryAffineArrayMove.runBound (vector xs) output+((signed c).length+1+c.denominator.length+1),?_,\n    T.join (T.join (T.join (T.join h0 h1) h2) h3) h4⟩\n  dsimp only [output]\n  unfold runBound\n  simp only [unary,List.length_replicate]\n  omega\n/-- The complete actual stage's output is the exact authoritative native multiply array tape. -/\ntheorem bytes_original (xs:List SemiprimeRationalBits.RationalWord) (c:SemiprimeRationalBits.RationalWord) (width:List Bool) (q:Nat):\n    bytes xs c width q=vector (SemiprimeJetBits.multiplyBits width xs.toArray #[SemiprimeJetBits.oneWord,c] q).words.toList:=\n  SemiprimeD1StackRecoveryAffineCoefficientsOriginal.rows_original xs c width q\nend RiemannGaussian.SemiprimeD1StackRecoveryAffineSlopeStage\n","RiemannGaussian.SemiprimeD1StackRecoveryCoordinateCapacities":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryCoordinateBlock\n/-! # Intrinsic physical byte and actual binary-reader step bounds\nSource/output lengths and lookup costs are derived from actual physical fields.\nNo numeric coordinate magnitude or subtree clock is a work parameter.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryCoordinateCapacities\nopen SemiprimeD1StackRecoveryCoordinateEncoding SemiprimeD1StackRecoveryCoordinateBlock\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nnamespace I\nexport SemiprimeD1StackRecoveryEntriesIndexedBounds (vector_cons_length member_length result_length timeBound_le runBound)\nend I\n/-- Physical vector row count is bounded by its actual tagged/framed byte tape. -/\ntheorem vector_count (words:List (List Bool)):words.length ≤(vectorBits words).length:=by\n  have h:=SemiprimeD1TensorTapeCodec.vectorBits_length words\n  omega\n/-- Replacing each physical field by a no-longer payload cannot enlarge its literal vector tape. -/\ntheorem vector_map_mono {K:Type} (xs:List K) (f g:K→List Bool)\n    (h:∀x∈xs,(f x).length ≤(g x).length):\n    (vectorBits (xs.map f)).length ≤(vectorBits (xs.map g)).length:=by\n  induction xs with\n  | nil=>rfl\n  | cons x xs ih=>\n    have h0:=h x (List.mem_cons_self)\n    have h1:=ih (fun y hy=>h y (List.mem_cons_of_mem x hy))\n    simp only [List.map_cons,I.vector_cons_length]\n    omega\n/-- Actual selected/default word is paid by its physical block-vector bytes. -/\ntheorem coefficient_length (key:List Bool) (words:List (List Bool)):\n    (coefficient key words).length ≤(vectorBits words).length:=I.result_length words key\n/-- Actual phase coordinate row cannot exceed the already acquired phase block tape. -/\ntheorem row_length (key:List Bool) (blocks:List (List (List Bool))):\n    (vectorBits (row key blocks)).length ≤(vectorBits (blocks.map vectorBits)).length:=\n  vector_map_mono blocks _ _ (fun words _=>coefficient_length key words)\n/-- Literal tagged-frame chunk length. -/\ntheorem chunk_length (word:List Bool):(chunk word).length=2*word.length+2:=by\n  simp only [chunk,List.length_cons,SemiprimeSourceHistogramKeyBits.frame_length,List.length_nil]\n/-- Only one physical false sentinel separates vector length from the chunk-history length. -/\ntheorem chunks_length (words:List (List Bool)):(chunks words).length+1=(vectorBits words).length:=by\n  have h:=congrArg List.length (chunks_vector words)\n  simpa only [List.length_append,List.length_singleton] using h\n/-- Original phase count is paid by the actual full retained input-bank bytes. -/\ntheorem phase_count (phases:Phases):phases.length ≤(tape phases).length:=by\n  simpa only [tape,List.length_map] using vector_count (phases.map (fun blocks=>vectorBits (blocks.map vectorBits)))\n/-- Original retained blocks of every actual phase are paid by that phase's byte payload. -/\ntheorem block_count (blocks:List (List (List Bool))):blocks.length ≤(vectorBits (blocks.map vectorBits)).length:=by\n  simpa only [List.length_map] using vector_count (blocks.map vectorBits)\n/-- Every actual phase payload is paid by the original acquired outer tape. -/\ntheorem phase_length (phases:Phases) (blocks:List (List (List Bool))) (hb:blocks∈phases):\n    (vectorBits (blocks.map vectorBits)).length ≤(tape phases).length:=\n  I.member_length _ _ (List.mem_map.mpr ⟨blocks,hb,rfl⟩)\n/-- Every actual block payload is paid by its acquired phase tape. -/\ntheorem block_length (blocks:List (List (List Bool))) (words:List (List Bool)) (hw:words∈blocks):\n    (vectorBits words).length ≤(vectorBits (blocks.map vectorBits)).length:=\n  I.member_length _ _ (List.mem_map.mpr ⟨words,hw,rfl⟩)\n/-- Entire actual output column bank cannot exceed its original phase-block input tape. -/\ntheorem result_length (phases:Phases) (key:List Bool):(result phases key).length ≤(tape phases).length:=by\n  simp only [result,columns,List.map_map,Function.comp_def,tape]\n  exact vector_map_mono phases _ _ (fun blocks _=>row_length key blocks)\n/-- All actual one-block copies/parser/lookup/frame/reverse/drains fit the same physical-byte quadratic. -/\ntheorem block_time (key:List Bool) (words:List (List Bool)) (L:Nat) (hl:(vectorBits words).length ≤L):\n    blockTime key words ≤10000000*(L+key.length+1)^2:=by\n  have hlookup:=I.timeBound_le words key\n  have hp:=Nat.pow_le_pow_left (Nat.add_le_add_right (Nat.add_le_add_right hl key.length) 1) 2\n  have hs:=coefficient_length key words\n  have he:SemiprimeD1StackRecoveryEntriesIndexedExecution.timeBound words key ≤1000000*(L+key.length+1)^2:=\n    hlookup.trans (Nat.mul_le_mul_left 1000000 hp)\n  have hlin:L+key.length+1 ≤(L+key.length+1)^2:=by\n    simpa only [pow_one] using Nat.pow_le_pow_right (by omega:1 ≤L+key.length+1) (by decide:1 ≤2)\n  unfold blockTime\n  rw [chunk_length]\n  omega\nend RiemannGaussian.SemiprimeD1StackRecoveryCoordinateCapacities\n","RiemannGaussian.SemiprimeD1StackRecoveryEntriesIndexedExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryEntriesIndexedLoop\n/-! # Whole real binary-query defaulting vector reader and exact retained inputs\nThe fixed program preserves the two actual input words, clears all private\nwork and returns the exact selected literal field, defaulting at actual EOF.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryEntriesIndexedExecution\nopen SemiprimeD1StackRecoveryEntriesIndexed SemiprimeD1StackRecoveryEntriesIndexedState\nopen SemiprimeD1StackRecoveryEntriesIndexedPrimitives SemiprimeD1StackRecoveryEntriesIndexedSpec\nopen SemiprimeD1StackRecoveryEntriesIndexedLoop SemiprimeD1StackProcedureTrace\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeBitArithmetic (bitValue)\n/-- Exact actual two-input source clock, including retained vector copy and genuine halt. -/\ndef timeBound (words:List (List Bool)) (query:List Bool):Nat:=5*(vectorBits words).length+4+budget query [] words+1\n/-- Actual full halt retains raw query padding and raw cache payload, clearing all private/counter words. -/\ndef done (words:List (List Bool)) (query:List Bool):C.State Stack Label:=\n  ⟨none,none,none,view (vectorBits words) query [] [] ((words[bitValue query]?).getD []),[]⟩\n/-- One real preserving input copy enters the physical scan with binary zero ordinal. -/\ntheorem setup_run (cache query:List Bool):\n    Runs program (5*cache.length+4) (.local .start) (initial cache query).data (.local .loop) (view cache query [] cache []):=by\n  rw [initial_store]\n  have h:=copy_call .cache (.local .start) (.local .loop) (view cache query [] [] []) cache [] rfl rfl rfl rfl\n  simp only [List.append_nil] at h\n  dsimp only [view,copyTarget,aux] at h\n  rw [update_reader] at h\n  exact h\n/-- SAME finite program returns the exact original index/default semantics, without a getter or unary address supplier. -/\ntheorem source_run (words:List (List Bool)) (query:List Bool):\n    SemiprimeD1StackCalls.run program (timeBound words query) (initial (vectorBits words) query)=some (done words query):=by\n  have h0:=setup_run (vectorBits words) query\n  have h1:=loop_run words (vectorBits words) query []\n  rw [selected_initial] at h1\n  have h:=join h0 h1\n  obtain ⟨out,hr,ha⟩:=h [] (initial (vectorBits words) query) ⟨rfl,rfl,rfl⟩\n  have hh:=halt_run program (.local .done) rfl (done words query).data [] out ha\n  rw [timeBound,SemiprimeD1StackReturnLink.run_add,hr,Option.bind_some]\n  exact hh\n/-- Exact all12-role final bank: both originals retained and nine private work tapes empty. -/\ntheorem result_bank (words:List (List Bool)) (query:List Bool):\n    (done words query).data=Function.update (input (vectorBits words) query) (aux .value) ((words[bitValue query]?).getD []):=by\n  funext k\n  rcases k with k|k\n  · cases k <;> rfl\n  · cases k <;> rfl\nend RiemannGaussian.SemiprimeD1StackRecoveryEntriesIndexedExecution\n","RiemannGaussian.SemiprimeD1StackRecoveryEntriesLogger":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryEntriesPrimitives\n/-! # Four real Frames and physically reversed entry logging\nAll raw source sign/magnitude/denominator and selected child bytes are retained.\nPer-row work does not rescan old history; one final real reverse restores order.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryEntriesLogger\nopen SemiprimeD1StackRecoveryEntries SemiprimeD1StackRecoveryEntriesState\nopen SemiprimeD1StackRecoveryEntriesPrimitives SemiprimeD1StackProcedureTrace\nopen SemiprimeD1StackRecoveryDenominatorEncoding (Row)\nopen SemiprimeD1StackRecoveryEntriesEncoding (Entry)\nopen SemiprimeSourceHistogramKeyBits (frame)\n/-- Actual source Aux role at each fixed preserving-frame site. -/\ndef frameAux (part:Fin 4):Aux:=if part=0 then .child else if part=1 then .denominator else if part=2 then .magnitude else .sign\n/-- Every source-frame role is the declared physical byte word. -/\ntheorem frame_address (part:Fin 4):frameSource part=aux (frameAux part):=by fin_cases part <;> rfl\n/-- Every real preserving frame includes all byte traversals, delimiter and real call/return. -/\ntheorem frame_call (part:Fin 4) (children:List Bool) (w:Aux → List Bool):\n    Runs program (6*(w (frameAux part)).length+5) (.local (.frame part)) (data children w) (nextFrame part)\n      (data children (Function.update w .frameBuffer (frame (w (frameAux part)) (w .frameBuffer)))):=by\n  rw [data_update]\n  let before:=SemiprimeD1StackFrame.state 0 none (w (frameAux part)) (w .frameBuffer) []\n  let after:=SemiprimeD1StackFrame.done (w (frameAux part)) (frame (w (frameAux part)) (w .frameBuffer))\n  have hin:SemiprimeD1StackMultiplierLink.DataRel (frameStack part) (data children w) before.store (data children w):=by\n    constructor\n    · intro k;fin_cases k\n      · change data children w (frameSource part)=w (frameAux part)\n        rw [frame_address,data_aux]\n      · rfl\n      · exact data_scratch children w\n    · intro k _;rfl\n  have ho:=SemiprimeD1StackMultiplierLink.data_update (frameStack part) (frame_injective part)\n    (data children w) before.store (data children w) hin (1:Fin 3) (frame (w (frameAux part)) (w .frameBuffer))\n  have he:Function.update before.store 1 (frame (w (frameAux part)) (w .frameBuffer))=after.store:=by funext k;fin_cases k <;> rfl\n  rw [he] at ho\n  exact included_call program (frameStack part) (Label.frame part) (frame_injective part) SemiprimeD1StackFrame.code 0\n    (fun _=>rfl) (.local (.frame part)) (nextFrame part) rfl (6*(w (frameAux part)).length+4)\n    before after _ _ rfl rfl (SemiprimeD1StackFrame.frame_words _ _ none) hin ho\n/-- Actual input role of each of the two fixed real reversals. -/\ndef reverseFrom (finish:Bool):Aux:=if finish then .history else .frameBuffer\n/-- Actual output role of each fixed real reversal. -/\ndef reverseTo (finish:Bool):Aux:=if finish then .output else .history\n/-- Every reversal source equals its physical role. -/\ntheorem reverse_source (finish:Bool):reverseStack finish 0=aux (reverseFrom finish):=by cases finish <;> rfl\n/-- Every reversal target equals its physical role. -/\ntheorem reverse_target (finish:Bool):reverseStack finish 1=aux (reverseTo finish):=by cases finish <;> rfl\n/-- Both actual reversal operands are distinct. -/\ntheorem reverse_ne (finish:Bool):aux (reverseFrom finish)≠aux (reverseTo finish):=by cases finish <;> decide\n/-- Real reversal consumes its entire source and pays every push plus call/return. -/\ntheorem reverse_call (finish:Bool) (pc next:Label) (children:List Bool) (w:Aux → List Bool)\n    (hp:program pc=.call (.reverse finish 0) next):\n    Runs program (2*(w (reverseFrom finish)).length+3) pc (data children w) next\n      (data children (Function.update (Function.update w (reverseFrom finish) []) (reverseTo finish)\n        ((w (reverseFrom finish)).reverse++w (reverseTo finish)))):=by\n  simp only [data_update]\n  let before:=SemiprimeD1StackReverseWord.state none (w (reverseFrom finish)) (w (reverseTo finish))\n  let after:=SemiprimeD1StackReverseWord.done ((w (reverseFrom finish)).reverse++w (reverseTo finish))\n  have hin:SemiprimeD1StackMultiplierLink.DataRel (reverseStack finish) (data children w) before.store (data children w):=by\n    constructor\n    · intro k;fin_cases k\n      · change data children w (reverseStack finish 0)=_;rw [reverse_source,data_aux];rfl\n      · change data children w (reverseStack finish 1)=_;rw [reverse_target,data_aux];rfl\n    · intro k _;rfl\n  have h0:=SemiprimeD1StackMultiplierLink.data_update (reverseStack finish) (reverse_injective finish)\n    (data children w) before.store (data children w) hin (0:Fin 2) []\n  have h1:=SemiprimeD1StackMultiplierLink.data_update (reverseStack finish) (reverse_injective finish)\n    (data children w) _ _ h0 (1:Fin 2) ((w (reverseFrom finish)).reverse++w (reverseTo finish))\n  have he:Function.update (Function.update before.store 0 []) 1 ((w (reverseFrom finish)).reverse++w (reverseTo finish))=after.store:=by\n    funext k;fin_cases k <;> rfl\n  rw [he,reverse_source,reverse_target] at h1\n  exact included_call program (reverseStack finish) (Label.reverse finish) (reverse_injective finish) SemiprimeD1StackReverseWord.code 0\n    (fun _=>rfl) pc next hp (2*(w (reverseFrom finish)).length+2) before after _ _ rfl rfl\n    (SemiprimeD1StackReverseWord.reverse_run _ _ none) hin h1\n/-- Actual four payloads logged from this parsed row and physically selected child word. -/\ndef payload (r:Row) (child:List Bool):Entry:=![r 2,r 3,r 4,child]\n/-- Complete literal one-entry chunk before the actual per-row reverse. -/\ndef chunk (r:Row) (child:List Bool):List Bool:=true::SemiprimeD1StackRecoveryEntriesEncoding.fields (payload r child) []\n/-- Exact actual four-frame caller clock, independent of prior history/output length. -/\ndef frameTime (r:Row) (child:List Bool):Nat:=6*(child.length+(r 4).length+(r 3).length+(r 2).length)+20\n/-- All four acquired words are physically framed in their exact original sign/magnitude/D/child order. -/\ntheorem frame_run (children original reader:List Bool) (r:Row) (row child history buffer out:List Bool):\n    Runs program (frameTime r child) (.local (.frame 0))\n      (data children (words original reader r row child [] history buffer out)) (.local .tag)\n      (data children (words original reader r row child [] history (SemiprimeD1StackRecoveryEntriesEncoding.fields (payload r child) buffer) out)):=by\n  have h0:=frame_call 0 children (words original reader r row child [] history buffer out)\n  change Runs program (6*child.length+5) (.local (.frame 0))\n    (data children (words original reader r row child [] history buffer out)) (.local (.frame 1))\n    (data children (Function.update (words original reader r row child [] history buffer out) .frameBuffer (frame child buffer))) at h0\n  rw [update_buffer] at h0\n  have h1:=frame_call 1 children (words original reader r row child [] history (frame child buffer) out)\n  rw [update_buffer] at h1\n  change Runs program (6*(r 4).length+5) _ _ _ _ at h1\n  have h2:=frame_call 2 children (words original reader r row child [] history (frame (r 4) (frame child buffer)) out)\n  rw [update_buffer] at h2\n  change Runs program (6*(r 3).length+5) _ _ _ _ at h2\n  have h3:=frame_call 3 children (words original reader r row child [] history (frame (r 3) (frame (r 4) (frame child buffer))) out)\n  rw [update_buffer] at h3\n  change Runs program (6*(r 2).length+5) _ _ _ _ at h3\n  have h:=join (join (join h0 h1) h2) h3\n  change Runs program _ (.local (.frame 0)) _ (.local .tag) _ at h\n  convert h using 1 <;> first | rfl | (unfold frameTime;omega)\n/-- Exact physical row logger clock, including true marker and genuine buffer-to-history reversal. -/\ndef rowTime (r:Row) (child:List Bool):Nat:=frameTime r child+1+(2*(chunk r child).length+3)\n/-- One actual entry is logged without rescanning prior history; its source words remain until explicit cleanup. -/\ntheorem row_run (children original reader:List Bool) (r:Row) (row child history out:List Bool):\n    Runs program (rowTime r child) (.local (.frame 0))\n      (data children (words original reader r row child [] history [] out)) (.local (.clear 0))\n      (data children (words original reader r row child [] ((chunk r child).reverse++history) [] out)):=by\n  have h0:=frame_run children original reader r row child history [] out\n  have h1:=push_run (.local .tag) (.local .rowReverse) .frameBuffer true children\n    (words original reader r row child [] history (SemiprimeD1StackRecoveryEntriesEncoding.fields (payload r child) []) out) rfl\n  rw [update_buffer] at h1\n  have h2:=reverse_call false (.local .rowReverse) (.local (.clear 0)) children\n    (words original reader r row child [] history (chunk r child) out) rfl\n  change Runs program (2*(chunk r child).length+3) (.local .rowReverse)\n    (data children (words original reader r row child [] history (chunk r child) out)) (.local (.clear 0))\n    (data children (Function.update (Function.update (words original reader r row child [] history (chunk r child) out) .frameBuffer []) .history\n      ((chunk r child).reverse++history))) at h2\n  rw [update_buffer,update_history] at h2\n  exact join (join h0 h1) h2\nend RiemannGaussian.SemiprimeD1StackRecoveryEntriesLogger\n","RiemannGaussian.SemiprimeD1StackRecoveryFinishBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryFinishTailBounds\n/-! # Fixed quartic bound for the same complete actual recovery source\nAll input binary bytes and actual unary WIDTH markers pay their own copying,\nshifting, full padding scans, scalar calls, precision rounds and cleanup.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryFinishBounds\nopen SemiprimeD1StackRecoveryFinish SemiprimeD1StackRecoveryFinishExecution\nopen SemiprimeBitIndexClipping (SignedWord)\n/-- Actual total input bytes, including the physically parsed sign and WIDTH markers. -/\ndef resource (n:SignedWord) (d:List Bool) (p:Nat):Nat:=(B.signedTape n).length+d.length+p\n/-- Fixed coefficient and degree, independent of every actual input and result. -/\ndef runBound (n:SignedWord) (d:List Bool) (p:Nat):Nat:=1000000000000*(resource n d p+1)^4\n/-- Actual complete source clock is bounded without identifying it with any old native report clock. -/\ntheorem timeBound_le (n:SignedWord) (d:List Bool) (p:Nat):timeBound n d p ≤runBound n d p:=by\n  let z:=resource n d p+1\n  have hz:1 ≤z:=by dsimp [z];omega\n  have hp:p+1 ≤z:=by dsimp [z,resource];omega\n  have hl:z ≤z^4:=by simpa only [pow_one] using Nat.pow_le_pow_right hz (by decide:1 ≤4)\n  have h4:(p+1)^4 ≤z^4:=Nat.pow_le_pow_left hp 4\n  have h3:(p+1)^3 ≤z^4:=(Nat.pow_le_pow_left hp 3).trans (Nat.pow_le_pow_right hz (by decide:3 ≤4))\n  have h0:=SemiprimeD1StackRecoveryFinishFrontBounds.floor_time n d\n  have h1:=SemiprimeD1StackRecoveryFinishFrontBounds.preparation_time n d (List.replicate p true)\n  simp only [List.length_replicate] at h1\n  have h2:=SemiprimeD1StackRecoveryFinishLoopBounds.original_loop n d p\n  have h3t:=SemiprimeD1StackRecoveryFinishTailBounds.sign_time _ p\n    (SemiprimeD1StackRecoveryFinishTailBounds.inverse_small n d p) n.negative\n  have h4t:=SemiprimeD1StackRecoveryFinishOperatorBounds.multiply_time _ p\n    (SemiprimeD1StackRecoveryFinishTailBounds.signed_small n d p) .final\n  have h5:=SemiprimeD1StackRecoveryFinishTailBounds.cleanup_mass n d p\n  have h0':F.floorTime n d ≤1000*z^4:=by\n    have hh:(B.signedTape n).length+d.length+1 ≤z:=by dsimp [z,resource];omega\n    exact h0.trans (Nat.mul_le_mul_left 1000 (hh.trans hl))\n  have h1':P.time n d (List.replicate p true) ≤1000*z^4:=by\n    change P.time n d (List.replicate p true) ≤1000*z at h1\n    exact h1.trans (Nat.mul_le_mul_left 1000 hl)\n  have h2':N.budget p (P.result n d (List.replicate p true)) ≤500000*z^4:=\n    h2.trans (Nat.mul_le_mul_left 500000 h4)\n  have h3':S.time (inverseValues n d p) n.negative ≤200000*z^4:=\n    h3t.trans (Nat.mul_le_mul_left 200000 h3)\n  have h4':MP.time (signedValues n d p) .final ≤100000*z^4:=\n    h4t.trans (Nat.mul_le_mul_left 100000 h3)\n  have h5':G.mass (finalValues n d p) 0+49 ≤100*z^4:=by\n    have hh:9*p+2*d.length+3+49 ≤100*z:=by dsimp [z,resource];omega\n    have hx:=Nat.mul_le_mul_left 100 hl\n    omega\n  unfold timeBound bodyTime\n  change _ ≤1000000000000*z^4\n  omega\n/-- The same actual parameterless finite program halts within the fixed quartic input-byte bound. -/\ntheorem source_run_bounded (n:SignedWord) (d:List Bool)\n    (hd:0 < SemiprimeBitArithmetic.bitValue d) (p:Nat):\n    ∃q ≤runBound n d p,SemiprimeD1StackCalls.run program q\n      (initial (B.signedTape n) d (List.replicate p true))=some (done n d p):=\n  ⟨timeBound n d p,timeBound_le n d p,source_run n d hd p⟩\nend RiemannGaussian.SemiprimeD1StackRecoveryFinishBounds\n","RiemannGaussian.SemiprimeD1StackRecoveryFinishOperatorBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryFinishNewton\nimport RiemannGaussian.SemiprimeD1StackRecoveryFinishCache\n/-! # Own actual scalar-stage clock and intrinsic cache-width bounds\nThe scalar caps are derived from actual canonical source outputs. Public callers\nwill supply only original input words and unary WIDTH; no intermediate bound or\nanswer is added to runtime control or to the final public source theorem.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryFinishOperatorBounds\nopen SemiprimeD1StackRecoveryFinish SemiprimeD1StackRecoveryFinishState\nopen SemiprimeD1StackRecoveryFinishPrimitives\nnamespace M\nexport SemiprimeD1StackRecoveryFinishMultiply (word target loadTime bodyTime time result)\nend M\nnamespace A\nexport SemiprimeD1StackRecoveryFinishCorrection (word time result)\nend A\nnamespace K\nexport SemiprimeD1StackRecoveryFinishCache (word reducerTime time)\nend K\n/-- All actual binary scalar caches and final output, excluding the potentially long original binary operands. -/\ndef sizedSlots:List Slot:=[.aux .inverseInput,.aux .negative,.aux .two,.aux .current,.aux .product,\n  .aux .opposite,.aux .correction,.aux .signedResidue,.aux .numeratorResidue,.output]\n/-- Intrinsic physically acquired scalar widths at an actual iteration boundary. -/\nstructure Small (v:Values) (p:Nat):Prop where\n  /-- Actual physically supplied precision count. -/\n  width:(v .width).length=p\n  /-- All actual scalar caches were acquired by source canonical reduction/products/sums. -/\n  bounded:∀s∈sizedSlots,(v s).length≤p\n/-- One linear value/byte factor is bounded by its fixed cubic monomial. -/\ntheorem linear_cube (p:Nat):p+1≤(p+1)^3:=by\n  simpa only [pow_one] using Nat.pow_le_pow_right (by omega:1≤p+1) (by decide:1≤3)\n/-- Replacing any non-WIDTH scalar/output role by an actual bounded word preserves intrinsic scalar caps. -/\ntheorem small_update (v:Values) (p:Nat) (hv:Small v p) (s:Slot) (hs:s≠.width) (bits:List Bool) (hb:bits.length≤p):\n    Small (Function.update v s bits) p:=by\n  constructor\n  · rw [Function.update_of_ne hs.symm]\n    exact hv.width\n  · intro t ht\n    by_cases he:t=s\n    · subst t\n      rw [Function.update_same]\n      exact hb\n    · rw [Function.update_of_ne he]\n      exact hv.bounded t ht\n/-- Updating a genuine non-scalar work word such as the actual todo tape does not require an advised width bound. -/\ntheorem small_foreign (v:Values) (p:Nat) (hv:Small v p) (s:Slot) (hs:s≠.width) (hn:s∉sizedSlots) (bits:List Bool):\n    Small (Function.update v s bits) p:=by\n  constructor\n  · rw [Function.update_of_ne hs.symm]\n    exact hv.width\n  · intro t ht\n    have he:t≠s:=by intro h;subst t;exact hn ht\n    rw [Function.update_of_ne he]\n    exact hv.bounded t ht\n/-- Actual left product operands come from intrinsically bounded scalar caches. -/\ntheorem left_bound (v:Values) (p:Nat) (hv:Small v p) (site:MulSite):(v (multiplyFromLeft site)).length≤p:=by\n  cases site <;> exact hv.bounded _ (by simp [sizedSlots,multiplyFromLeft])\n/-- Actual right product operands come from intrinsically bounded scalar caches. -/\ntheorem right_bound (v:Values) (p:Nat) (hv:Small v p) (site:MulSite):(v (multiplyFromRight site)).length≤p:=by\n  cases site <;> exact hv.bounded _ (by simp [sizedSlots,multiplyFromRight])\n/-- Every actual old destination cache is paid, including its physical drain. -/\ntheorem target_bound (v:Values) (p:Nat) (hv:Small v p) (site:MulSite):(v (M.target site)).length≤p:=by\n  cases site <;> exact hv.bounded _ (by simp [sizedSlots,M.target])\n/-- Actual modular-product output bounds are intrinsic even before scalar operand caps are used. -/\ntheorem multiply_word_length (v:Values) (p:Nat) (hv:Small v p) (site:MulSite):(M.word v site).length≤p:=by\n  have h:=SemiprimeD1JetScalarBits.mul_length (v .width).length (v (multiplyFromLeft site)) (v (multiplyFromRight site))\n  simpa only [M.word,hv.width] using h\n/-- Actual product-cache replacement inherits its bound from the real acquired canonical output. -/\ntheorem small_multiply (v:Values) (p:Nat) (hv:Small v p) (site:MulSite):Small (M.result v site) p:=by\n  apply small_update v p hv (M.target site) _ (M.word v site) (multiply_word_length v p hv site)\n  cases site <;> decide\n/-- Actual correction output bound is intrinsic to the real canonical scalar sum. -/\ntheorem correction_word_length (v:Values) (p:Nat) (hv:Small v p):(A.word v).length≤p:=by\n  have h:=SemiprimeD1JetScalarBits.add_length (v .width).length (v (.aux .two)) (v (.aux .opposite))\n  simpa only [A.word,hv.width] using h\n/-- Actual correction-cache replacement inherits its bound from the real scalar-sum output. -/\ntheorem small_correction (v:Values) (p:Nat) (hv:Small v p):Small (A.result v) p:=\n  small_update v p hv (.aux .correction) (by decide) (A.word v) (correction_word_length v p hv)\n/-- SAME actual nested multiplier source clock has a fixed cubic bound on bounded physical scalar inputs. -/\ntheorem scalar_multiply_time (v:Values) (p:Nat) (hv:Small v p) (site:MulSite):\n    SemiprimeD1StackJetScalarMulExecution.totalTime (v (multiplyFromLeft site)) (v (multiplyFromRight site)) (v .width)\n      ≤54000*(p+1)^3:=by\n  have hl:=left_bound v p hv site\n  have hr:=right_bound v p hv site\n  have hw:=hv.width\n  calc\n    _≤2000*((v (multiplyFromLeft site)).length+(v (multiplyFromRight site)).length+(v .width).length+3)^3:=\n      (SemiprimeD1StackJetScalarMulExecution.totalTime_le _ _ _).trans\n        (SemiprimeD1StackJetScalarMulExecution.timeBound_le_cube _ _ _)\n    _≤2000*(3*(p+1))^3:=by gcongr;omega\n    _=54000*(p+1)^3:=by ring\n/-- Every full real cached-product call charges both operand copies, old cache drain, output move and real returns. -/\ntheorem multiply_time (v:Values) (p:Nat) (hv:Small v p) (site:MulSite):M.time v site≤100000*(p+1)^3:=by\n  have hl:=left_bound v p hv site\n  have hr:=right_bound v p hv site\n  have ht:=target_bound v p hv site\n  have hw:=multiply_word_length v p hv site\n  have hm:=scalar_multiply_time v p hv site\n  have hc:=linear_cube p\n  unfold M.time M.bodyTime M.loadTime\n  split <;> omega\n/-- Actual full scalar correction source charges its two copies, actual adder, old cache drain and output transfer. -/\ntheorem correction_time (v:Values) (p:Nat) (hv:Small v p):A.time v≤1000*(p+1)^3:=by\n  have ht:=hv.bounded (.aux .two) (by simp [sizedSlots])\n  have ho:=hv.bounded (.aux .opposite) (by simp [sizedSlots])\n  have hc:=hv.bounded (.aux .correction) (by simp [sizedSlots])\n  have hw:=correction_word_length v p hv\n  have ha:=SemiprimeD1StackJetScalarAddExecution.totalTime_le (v (.aux .two)) (v (.aux .opposite)) (v .width)\n  change SemiprimeD1StackJetScalarAddExecution.totalTime _ _ _≤30*((v (.aux .two)).length+(v (.aux .opposite)).length+(v .width).length+2) at ha\n  rw [hv.width] at ha\n  have hp:=linear_cube p\n  unfold A.time\n  omega\n/-- Real direct reducer clock pays even all high input/counter leftovers, rather than using the native prefix-only report. -/\ntheorem reducer_time (v:Values):K.reducerTime v≤5*((v .reduceInput).length+(v .width).length)+11:=by\n  have h:=(SemiprimeD1StackReduceExecution.sourceReduce (v .reduceInput) (v .width)).steps_le_m\n  change SemiprimeD1StackReduceExecution.trimTime ((v .reduceInput).take (v .width).length).reverse+\n    SemiprimeD1StackReduceExecution.prefixTime (v .reduceInput) (v .width)≤_ at h\n  unfold K.reducerTime\n  omega\n/-- Every actual copy/reduce/cache stage is linear in real input bytes and real WIDTH markers. -/\ntheorem cache_time (v:Values):K.time v≤100*((v .reduceInput).length+(v .width).length+1):=by\n  have hr:=reducer_time v\n  have hw:=SemiprimeD1JetScalarBits.reduce_length (v .width).length (v .reduceInput)\n  change (K.word v).length≤(v .width).length at hw\n  unfold K.time\n  omega\nend RiemannGaussian.SemiprimeD1StackRecoveryFinishOperatorBounds\n","RiemannGaussian.SemiprimeD1StackRecoveryFinishPreparation":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryFinishFloor\nimport RiemannGaussian.SemiprimeD1StackRecoveryFinishCache\n/-! # Actual floor-residue and Newton cache preparation\nFour real WIDTH-copy/reduce/move stages acquire all canonical scalar caches.\nNegative one is physically copied from unary WIDTH; two/one are actual constant\npushes followed by real reduction. The loop counter is another paid WIDTH copy.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryFinishPreparation\nopen SemiprimeD1StackRecoveryFinish SemiprimeD1StackRecoveryFinishState\nopen SemiprimeD1StackRecoveryFinishPrimitives SemiprimeD1StackRecoveryFinishWords\nopen SemiprimeD1StackRecoveryFinishStrip SemiprimeD1StackRecoveryFinishSetup\nopen SemiprimeD1StackRecoveryFinishRound SemiprimeD1StackRecoveryFinishFloor SemiprimeD1StackProcedureTrace\nopen SemiprimeBitIndexClipping (SignedWord)\nnamespace K\nexport SemiprimeD1StackRecoveryFinishCache (Kind target word time cached cache_run)\nend K\nlocal notation \"ctl\"=>Label.local\n/-- Exact retained source/strip words; all scalar operands/results/private work are physically clear. -/\ndef common (n:SignedWord) (d w:List Bool):Values\n  | .width=>w | .aux .numerator=>signedTape n | .aux .denominator=>d | .aux .sign=>[n.negative]\n  | .aux .denominatorWork=>odd d | .aux .content=>content d | .aux .lost=>[lost d n.magnitude] | _=>[]\n/-- Exact raw corrected floor word in the real reducer input, before any precision reduction. -/\ndef floorBank (n:SignedWord) (d w:List Bool):Values:=\n  Function.update (common n d w) .reduceInput (corrected n.negative d n.magnitude)\n/-- Actual floor source boundary matches this simple full-store invariant. -/\ntheorem floorBank_eq (n:SignedWord) (d w:List Bool):floorValues n d w=floorBank n d w:=by\n  funext s\n  cases s with\n  | aux a=>cases a <;> simp [floorValues,rounded,stripped,view,base,initialValues,floorBank,common]\n  | _=>simp [floorValues,rounded,stripped,view,base,initialValues,floorBank,common]\n/-- Generic actual reduction-cache effect from an initially empty reducer input role. -/\ntheorem cached_input (v:Values) (hv:v .reduceInput=[]) (kind:K.Kind) (bits:List Bool):\n    K.cached (Function.update v .reduceInput bits) kind=\n      Function.update v (K.target kind) (SemiprimeD1JetScalarBits.reduce (v .width).length bits).bits:=by\n  simp only [K.cached,K.word,Function.update_same,\n    Function.update_of_ne (by decide:Slot.width≠.reduceInput),Function.update_idem]\n  have he:Function.update v .reduceInput []=v:=Function.update_eq_self_iff.mpr hv.symm\n  rw [he]\n/-- Actual canonical signed-floor magnitude cache. -/\ndef first (n:SignedWord) (d w:List Bool):Values:=Function.update (common n d w) (.aux .numeratorResidue)\n  (SemiprimeD1JetScalarBits.reduce w.length (corrected n.negative d n.magnitude)).bits\n/-- Actual odd suffix copied into the reused real reducer input. -/\ndef oddBank (n:SignedWord) (d w:List Bool):Values:=Function.update (first n d w) .reduceInput (odd d)\n/-- Actual canonical odd scalar cache. -/\ndef second (n:SignedWord) (d w:List Bool):Values:=Function.update (first n d w) (.aux .inverseInput)\n  (SemiprimeD1JetScalarBits.reduce w.length (odd d)).bits\n/-- Actual copied all-WIDTH negative-one cache; no numeric two-power is computed. -/\ndef third (n:SignedWord) (d w:List Bool):Values:=Function.update (second n d w) (.aux .negative) w\n/-- Real two constant after its two actual pushes into the reused reducer input. -/\ndef twoBank (n:SignedWord) (d w:List Bool):Values:=Function.update (third n d w) .reduceInput [false,true]\n/-- Actual canonically reduced two scalar cache. -/\ndef fourth (n:SignedWord) (d w:List Bool):Values:=Function.update (third n d w) (.aux .two)\n  (SemiprimeD1JetScalarBits.reduce w.length [false,true]).bits\n/-- Real one constant after its actual push into the reused reducer input. -/\ndef oneBank (n:SignedWord) (d w:List Bool):Values:=Function.update (fourth n d w) .reduceInput [true]\n/-- Actual canonically reduced initial inverse iterate. -/\ndef fifth (n:SignedWord) (d w:List Bool):Values:=Function.update (fourth n d w) (.aux .current)\n  (SemiprimeD1JetScalarBits.reduce w.length [true]).bits\n/-- Entire actual loop-ready bank includes a physically copied WIDTH counter. -/\ndef result (n:SignedWord) (d w:List Bool):Values:=Function.update (fifth n d w) (.aux .todo) w\n/-- Own exact preparation clock is the sum of the SAME real reducer/copy/constant stages. -/\ndef time (n:SignedWord) (d w:List Bool):Nat:=\n  K.time (floorBank n d w)+(5*(odd d).length+4)+K.time (oddBank n d w)+(5*w.length+4)+1+1+\n    K.time (twoBank n d w)+1+K.time (oneBank n d w)+(5*w.length+4)\n/-- The SAME actual recovery program physically acquires every scalar cache before its precision-marker loop. -/\ntheorem preparation_run (n:SignedWord) (d w:List Bool):\n    Runs program (time n d w) (ctl .qWidth) (data (floorBank n d w)) (ctl .loop) (data (result n d w)):=by\n  have h0:=K.cache_run .quotient (floorBank n d w) rfl rfl rfl rfl\n  have he0:K.cached (floorBank n d w) .quotient=first n d w:=by\n    rw [floorBank,cached_input (common n d w) rfl]\n    rfl\n  rw [he0] at h0\n  have h1:=copy_view .odd (ctl .oddInput) (ctl .aWidth) (first n d w) rfl rfl\n  change Runs program (5*(odd d).length+4) _ _ _\n    (data (Function.update (first n d w) .reduceInput (odd d++[]))) at h1\n  simp only [List.append_nil] at h1\n  have h2:=K.cache_run .odd (oddBank n d w) rfl rfl rfl rfl\n  have he2:K.cached (oddBank n d w) .odd=second n d w:=by\n    rw [oddBank,cached_input (first n d w) rfl]\n    rfl\n  rw [he2] at h2\n  have h3:=copy_view .negative (ctl .negativeWord) (ctl .twoHigh) (second n d w) rfl rfl\n  change Runs program (5*w.length+4) _ _ _\n    (data (Function.update (second n d w) (.aux .negative) (w++[]))) at h3\n  simp only [List.append_nil] at h3\n  have h4:=push_view (ctl .twoHigh) (ctl .twoLow) .reduceInput true (third n d w) rfl\n  change Runs program 1 _ _ _ (data (Function.update (third n d w) .reduceInput [true])) at h4\n  have h5:=push_view (ctl .twoLow) (ctl .twoWidth) .reduceInput false\n    (Function.update (third n d w) .reduceInput [true]) rfl\n  simp only [Function.update_same,Function.update_idem] at h5\n  change Runs program 1 _ _ _ (data (twoBank n d w)) at h5\n  have h6:=K.cache_run .two (twoBank n d w) rfl rfl rfl rfl\n  have he6:K.cached (twoBank n d w) .two=fourth n d w:=by\n    rw [twoBank,cached_input (third n d w) rfl]\n    rfl\n  rw [he6] at h6\n  have h7:=push_view (ctl .one) (ctl .oneWidth) .reduceInput true (fourth n d w) rfl\n  change Runs program 1 _ _ _ (data (oneBank n d w)) at h7\n  have h8:=K.cache_run .one (oneBank n d w) rfl rfl rfl rfl\n  have he8:K.cached (oneBank n d w) .one=fifth n d w:=by\n    rw [oneBank,cached_input (fourth n d w) rfl]\n    rfl\n  rw [he8] at h8\n  have h9:=copy_view .todo (ctl .copyTodo) (ctl .loop) (fifth n d w) rfl rfl\n  change Runs program (5*w.length+4) _ _ _\n    (data (Function.update (fifth n d w) (.aux .todo) (w++[]))) at h9\n  simp only [List.append_nil] at h9\n  exact join (join (join (join (join (join (join (join (join h0 h1) h2) h3) h4) h5) h6) h7) h8) h9\n/-- Whole original three-input frontend and physical cache preparation reach the actual Newton loop. -/\ntheorem source_prepared (n:SignedWord) (d:List Bool) (hd:0<SemiprimeBitArithmetic.bitValue d) (w:List Bool):\n    Runs program (floorTime n d+time n d w) (ctl .start) (initial (signedTape n) d w).data\n      (ctl .loop) (data (result n d w)):=by\n  have h0:=source_floor n d hd w\n  rw [floorBank_eq] at h0\n  exact join h0 (preparation_run n d w)\nend RiemannGaussian.SemiprimeD1StackRecoveryFinishPreparation\n","RiemannGaussian.SemiprimeD1StackRecoveryFinishResidue":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryFinishWords\n/-! # Exact compact final words despite arbitrary quotient padding\nInteger floor correctness is proved separately. Compact target-width residue\nuniqueness is used only after real modular reduction, never to identify padded\nraw quotient words or silently change the Newton-product/sum order.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryFinishResidue\nopen SemiprimeBitArithmetic\nopen SemiprimeBitIndexClipping (SignedWord)\nopen SemiprimeD1StackRecoveryFinishWords\nnamespace J\nexport SemiprimeD1JetScalarBits (reduce mul reduce_length reduce_compact mul_length mul_compact mul_zmod)\nend J\n/-- Two compact actual target-width words with the same target-ring value have identical Boolean bytes. -/\ntheorem canonical_eq (p:Nat) (a b:List Bool) (ha:SemiprimeSourceCompactBits.Compact a)\n    (hb:SemiprimeSourceCompactBits.Compact b) (hla:a.length≤p) (hlb:b.length≤p)\n    (h:(bitValue a:ZMod (2^p))=(bitValue b:ZMod (2^p))):a=b:=by\n  have hva:bitValue a<2^p:=(bitValue_lt_width _).trans_le (Nat.pow_le_pow_right (by decide:1≤2) hla)\n  have hvb:bitValue b<2^p:=(bitValue_lt_width _).trans_le (Nat.pow_le_pow_right (by decide:1≤2) hlb)\n  have hv:=congrArg ZMod.val h\n  simp only [ZMod.val_natCast,Nat.mod_eq_of_lt hva,Nat.mod_eq_of_lt hvb] at hv\n  exact SemiprimeSourceCompactWordIds.compact_value_injective _ _ ha hb hv\n/-- Reducing a binary operand before the real canonical modular product preserves exact output bytes. -/\ntheorem mul_reduce_right (p:Nat) (a b:List Bool):\n    (J.mul p a (J.reduce p b).bits).bits=(J.mul p a b).bits:=by\n  apply canonical_eq p _ _ (J.mul_compact _ _ _) (J.mul_compact _ _ _)\n    (J.mul_length _ _ _) (J.mul_length _ _ _)\n  simp only [J.mul_zmod,SemiprimeD1JetScalarBits.reduce_value,ZMod.natCast_mod]\n/-- Canonical signed residue depends on the actual signed floor VALUE, not on arbitrary quotient padding. -/\ntheorem signed_congr (p:Nat) (a b:SignedWord) (h:a.value=b.value):\n    (Old.signed p a).bits=(Old.signed p b).bits:=by\n  have ha:=SemiprimeD1RecoveryStripBits.signed_good p a\n  have hb:=SemiprimeD1RecoveryStripBits.signed_good p b\n  apply canonical_eq p _ _ ha.2 hb.2 ha.1 hb.1\n  rw [SemiprimeD1RecoveryStripBits.signed_value,SemiprimeD1RecoveryStripBits.signed_value,h]\n/-- Actual early canonical magnitude cache, physically produced before the Newton loop. -/\ndef magnitudeResidue (p:Nat) (n:SignedWord) (d:List Bool):List Bool:=\n  (J.reduce p (corrected n.negative d n.magnitude)).bits\n/-- Actual post-inverse signed residue: real negative-one product for negative sign, preserving full signed floor semantics. -/\ndef signedWord (p:Nat) (n:SignedWord) (d:List Bool):List Bool:=\n  if n.negative then (J.mul p (SemiprimeD1OddInverseBits.negativeOne p).bits (magnitudeResidue p n d)).bits\n  else magnitudeResidue p n d\n/-- The real reduced-magnitude sign circuit has the same exact compact bytes as the old signed quotient circuit. -/\ntheorem signed_quotient (p:Nat) (n:SignedWord) (d:List Bool):\n    signedWord p n d=(Old.signed p (quotient n d)).bits:=by\n  cases hn:n.negative with\n  | false=>simp only [signedWord,hn,Bool.false_eq_true,ite_false,Old.signed,quotient,magnitudeResidue]\n  | true=>\n    simp only [signedWord,hn,ite_true,Old.signed,quotient,magnitudeResidue]\n    exact mul_reduce_right p _ _\n/-- Actual signed cache agrees byte for byte with the ORIGINAL full floorSignedBits result after modular reduction. -/\ntheorem signed_original (p:Nat) (n:SignedWord) (d:List Bool):\n    signedWord p n d=(Old.signed p (SemiprimeBitIndexClipping.floorSignedBits n (Old.acquire d).content).word).bits:=\n  (signed_quotient p n d).trans (signed_congr p _ _ (quotient_floor_original n d))\n/-- Proof-side description of the actual literal inverse/sign/final-product result. -/\ndef output (p:Nat) (n:SignedWord) (d:List Bool):List Bool:=\n  (J.mul p (signedWord p n d) (SemiprimeD1OddInverseBits.inverse p (odd d)).bits).bits\n/-- Exact ORIGINAL RecoveryStripBits.finish word; no native clock or encoded answer is used by the source. -/\ntheorem output_original (p:Nat) (n:SignedWord) (d:List Bool):output p n d=(Old.finish p n d).bits:=by\n  simp only [output,Old.finish,(acquire_words d).2,signed_original]\n/-- The resulting original residue is exact for every positive binary denominator and arbitrary signed numerator. -/\ntheorem residue_original (p:Nat) (n:SignedWord) (d:List Bool) (hd:0<bitValue d):\n    (bitValue (output p n d):ZMod (2^p))=SemiprimeD1IntegerRecoveryResidue.finish p\n      {numerator:=n.value,denominator:=bitValue d,arithmetic:=0,digitReads:=0}:=by\n  rw [output_original]\n  exact SemiprimeD1RecoveryStripBits.finish_value p n d hd\n/-- Final byte width and compactness are intrinsic consequences of the actual final modular product. -/\ntheorem output_good (p:Nat) (n:SignedWord) (d:List Bool):\n    (output p n d).length≤p ∧SemiprimeSourceCompactBits.Compact (output p n d):=\n  ⟨J.mul_length _ _ _,J.mul_compact _ _ _⟩\nend RiemannGaussian.SemiprimeD1StackRecoveryFinishResidue\n","RiemannGaussian.SemiprimeD1StackRecoveryGridFinishMeaning":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridExecution\n/-! # Complete exact stopped grid bank and scalar/argument bytes -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryGridFinishMeaning\nopen SemiprimeD1StackRecoveryGrid SemiprimeD1StackRecoveryGridView\nnamespace Model\nexport SemiprimeD1StackRecoveryGridModel (Payload view center alpha node)\nend Model\nnamespace Old\nexport SemiprimeRationalBits (executeOperation)\nend Old\n/-- Exact actual Ezero word acquired by the real inverse and multiplication. -/\ndef scalar (width:List Bool) (p:Model.Payload) :SemiprimeRationalBits.RationalWord:=\n  (Old.executeOperation .mul p.numerator (Old.executeOperation .inv p.denominator p.denominator width).word width).word\n/-- Exact actual original-node negation, with legacy zero sign/width preserved. -/\ndef negative (a:Nat) (t width:List Bool) :SemiprimeRationalBits.RationalWord:=\n  (Old.executeOperation .neg (Model.node a t) (Model.node a t) width).word\n/-- Exact actual center-minus-node local point. -/\ndef point (a:Nat) (t width:List Bool) :SemiprimeRationalBits.RationalWord:=\n  (Old.executeOperation .add (Model.center a width) (negative a t width) width).word\n/-- Exact actual inverse alpha. -/\ndef inverse (a:Nat) (width:List Bool) :SemiprimeRationalBits.RationalWord:=\n  (Old.executeOperation .inv (Model.alpha a width) (Model.alpha a width) width).word\n/-- Exact actual local argument, from the real point and reciprocal caches. -/\ndef argument (a:Nat) (t width:List Bool) :SemiprimeRationalBits.RationalWord:=\n  (Old.executeOperation .mul (point a t width) (inverse a width) width).word\n/-- Complete104-word final bank: original sources retained, q/work cleared and both exact final outputs acquired. -/\ndef result (a M u:Nat) (t width:List Bool) (p:Model.Payload) :Words:=\n  putReg (putReg (Model.view a M u 0 t [] width p) .scalar (scalar width p)) .argument (argument a t width)\n/-- Same actual six operations and all physical cleanup produce exactly the canonical complete stopped bank. -/\ntheorem finish_eq (a M u:Nat) (t width:List Bool) (p:Model.Payload) :\n    bank (SemiprimeD1StackRecoveryGridFinal.result\n      (Model.view a M u 0 t (SemiprimeD1StackRecoveryGridLoopPrimitives.zeroWord a) width p) width)=\n      bank (result a M u t width p):=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · rcases k with k|k\n    · rfl\n    · rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · rfl\n        · rcases k with k|k\n          · rcases k with ⟨r,b⟩\n            cases r <;> cases b <;> rfl\n          · cases k <;> rfl\n/-- Exact whole-source final bank for every actual metadata/index/template input, with no unacquired coefficient supplier. -/\ntheorem source_result (a M u:Nat) (t width:List Bool) :\n    SemiprimeD1StackRecoveryGridExecution.result a M u t width=\n      bank (result a M u t width (SemiprimeD1StackRecoveryGridExecution.payload a M u t width)):=\n  finish_eq a M u t width _\nend RiemannGaussian.SemiprimeD1StackRecoveryGridFinishMeaning\n","RiemannGaussian.SemiprimeD1StackRecoveryWeightsOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryWeightsExecution\nimport RiemannGaussian.SemiprimeD1StackRecoveryWeightsLegacy\n/-! # Complete original local-weight bytes and dimension-derived validity at the SAME actual source\nThe six upstream acquired inputs remain an explicit prepared boundary. Their\nphysical Grid/affine/inverse/power caller is separate; no N-only claim is made.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryWeightsOriginal\nopen SemiprimeD1StackRecoveryWeights SemiprimeD1StackRecoveryWeightsExecution\nopen SemiprimeD1StackRecoveryWeightsLegacy SemiprimeD1StackRecoveryWeightsIndices\n/-- All six actual input words are retained literally in the complete stopped bank. -/\ntheorem retained_inputs (inverse powers:List SemiprimeRationalBits.RationalWord) (scalar:SemiprimeRationalBits.RationalWord) (q:Nat) (width:List Bool):\n    result inverse powers scalar q width (aux .denominator)=SemiprimeD1StackNormalizedInverse.tape inverse ∧\n    result inverse powers scalar q width (aux .prefixReverse)=SemiprimeD1StackNormalizedInverse.tape powers ∧\n    result inverse powers scalar q width (SemiprimeD1StackRecoveryWeights.scalar .signed)=SemiprimeD1StackNormalizedInverse.signed scalar ∧\n    result inverse powers scalar q width (SemiprimeD1StackRecoveryWeights.scalar .den)=scalar.denominator ∧\n    result inverse powers scalar q width (aux .originalQ)=unary q ∧ result inverse powers scalar q width template=width:=⟨rfl,rfl,rfl,rfl,rfl,rfl⟩\n/-- Every actual private/helper/shadow field is empty, with immutable powers explicitly retained. -/\ntheorem work_clear (inverse powers:List SemiprimeRationalBits.RationalWord) (scalar:SemiprimeRationalBits.RationalWord) (q:Nat) (width:List Bool)\n    (k:I.Stack) (hk:¬SemiprimeD1StackRecoveryWeightsInventory.kept k):result inverse powers scalar q width (helper k)=[]:=\n  SemiprimeD1StackRecoveryWeightsFinishView.empty_private inverse powers scalar q width _ k hk\n/-- Honest six actual original input words, with every other54 physical role EMPTY. -/\ndef originalInput (width:List Bool) (a M u:Nat) (t:Fin (2^(a+1))):C.State Stack Label:=\n  initial (SemiprimeD1StackNormalizedInverse.tape (inverse width a M u t))\n    (SemiprimeD1StackNormalizedInverse.tape (powers width a M u t))\n    (SemiprimeD1StackNormalizedInverse.signed (grid width a M u t).scalar) (grid width a M u t).scalar.denominator\n    (unary (retained a M u t)) width\n/-- Exact stopped ordered array bytes, retaining ALL actual inverse/power/scalar/q/W source words. -/\ntheorem output_original (width:List Bool) (a M u:Nat) (t:Fin (2^(a+1))):\n    result (inverse width a M u t) (powers width a M u t) (grid width a M u t).scalar (retained a M u t) width (aux .output)=\n      SemiprimeD1StackNormalizedInverse.tape (SemiprimeD1RecoveryNodeBits.acquireAt width a M u t).words:=by\n  change SemiprimeD1StackNormalizedInverse.tape (SemiprimeD1StackRecoveryWeightsSpec.array width\n    (retained a M u t) (grid width a M u t).scalar (inverse width a M u t) (powers width a M u t))=_\n  rw [array_acquireAt]\n/-- The whole actual prepared source internally acquires exact old weights, not merely an endpoint value equation. -/\ntheorem source_run_original (width:List Bool) (a M u:Nat) (t:Fin (2^(a+1))):\n    ∃time ≤ timeBound (inverse width a M u t) (powers width a M u t) (grid width a M u t).scalar (retained a M u t) width,\n      SemiprimeD1StackCalls.run program time (originalInput width a M u t)=some\n        (done (inverse width a M u t) (powers width a M u t) (grid width a M u t).scalar (retained a M u t) width):=\n  source_run _ _ _ _ _\n/-- Original dimensions alone discharge all semantic Valid/Fits/canonical rational obligations, for every local coefficient. -/\ntheorem original_values (width:List Bool) (a M u:Nat) (t:Fin (2^(a+1))) (hu:u ≤ M)\n    (hW:SemiprimeD1RecoveryNodeBits.width a M ≤ width.length):\n    let words:=SemiprimeD1StackRecoveryWeightsSpec.array width (retained a M u t) (grid width a M u t).scalar\n      (inverse width a M u t) (powers width a M u t)\n    let expected:=(SemiprimeD1JetRecoveryWeights.acquire a (SemiprimeD1TaperedLoss.height M u) u t.val).weights.toList\n    words.map SemiprimeRationalBits.RationalWord.value=expected ∧ (∀x∈words,x.Valid) ∧\n      (∀x∈words,SemiprimeRationalBits.Width x width.length) ∧\n      words.map (fun x=>(x.numerator.value,SemiprimeBitArithmetic.bitValue x.denominator))=expected.map (fun x=>(x.num,x.den)):=\n  array_values width a M u t hu hW\nend RiemannGaussian.SemiprimeD1StackRecoveryWeightsOriginal\n","RiemannGaussian.SemiprimeD1StackRootPacketInventoryPrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootPacketInventoryView\n/-! # Actual acquired selected-key and original-catalogue copies with their own physical calls and returns -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootPacketInventoryPrimitives\nopen SemiprimeD1StackRootPacketInventory SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => Label.local\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel data_update)\nend Link\n/-- Actual fragments concatenate with all external real return frames retained. -/\ntheorem join {m n:Nat} {pc mid next:Label} {before between after:Stack→List Bool}\n    (h:Runs program m pc before mid between) (g:Runs program n mid between next after) :\n    Runs program (m+n) pc before next after :=runs_trans program m n pc mid next before between after h g\n/-- Every cache/input handoff is a real preserving copy, not a semantic operand assignment. -/\ntheorem copy_call (site:Copy) (before:Stack→List Bool) (xs ys:List Bool)\n    (hx:before (copySource site)=xs) (hy:before (copyTarget site)=ys) (hs:before copyScratch=[]) :\n    Runs program (5*xs.length+4) (ctl (.copy site)) before (copyNext site)\n      (Function.update before (copyTarget site) (xs++ys)) :=by\n  let start:=SemiprimeD1StackCopy.state 0 none xs ys []\n  let stop:=SemiprimeD1StackCopy.done xs (xs++ys)\n  have hi:Link.DataRel (copyStack site) before start.store before:=by\n    constructor\n    · intro k;fin_cases k\n      · exact hx\n      · exact hy\n      · exact hs\n    · intro k _;rfl\n  have ho:=Link.data_update (copyStack site) (copy_injective site) before start.store before hi (1:Fin 3) (xs++ys)\n  have he:Function.update start.store 1 (xs++ys)=stop.store:=by funext k;fin_cases k <;> rfl\n  rw [he] at ho\n  exact included_call program (copyStack site) (Label.copy site) (copy_injective site) SemiprimeD1StackCopy.code 0\n    (fun _=>rfl) (ctl (.copy site)) (copyNext site) rfl (5*xs.length+3) start stop before _ rfl rfl\n    (SemiprimeD1StackCopy.copy_words xs ys none) hi ho\nend RiemannGaussian.SemiprimeD1StackRootPacketInventoryPrimitives\n","RiemannGaussian.SemiprimeD1StackRootPacketPaddingExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootPacketPaddingEncoding\n/-! # Whole actual original-input selected-key/frequency/padding execution\nThe actual stopped source provides both consumer operands through real paid\ncopies. Both actual source calls and the final halt use this same program.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootPacketPaddingExecution\nopen SemiprimeD1StackRootPacketPadding SemiprimeD1StackRootPacketPaddingEncoding\nopen SemiprimeD1StackRootPacketPaddingInput SemiprimeD1StackRootPacketPaddingCalls\nopen SemiprimeD1StackRootPacketPaddingPrimitives SemiprimeD1StackProcedureTrace\nopen SemiprimeBitArithmetic (bitValue)\nlocal notation \"ctl\" => Label.local\nattribute [local irreducible] SemiprimeD1IncidenceAcquisition.acquire SemiprimeD1PacketPadding.acquire\n/-- SAME whole source starts with binary N and acquires the actual entire padding bank. -/\ntheorem source_trace (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits) :\n    ∃t,t+1 ≤timeBound bits hN ∧ Runs program t (ctl .start) (input bits) (ctl .done) (result bits hN) :=by\n  obtain ⟨r,hr,h0⟩:=root_call bits hc hN (fun _=>[])\n  have h1:=padding_input_run (rootDone bits hN).data (root_scratch bits hN)\n  rw [paddingReady_original bits hc hN] at h1\n  obtain ⟨p,hp,h2⟩:=padding_call (keys bits hN) (A.dimension bits) (rootDone bits hN).data\n  have h:=join (join h0 h1) h2\n  refine ⟨_,?_,h⟩\n  unfold timeBound\n  omega\n/-- The same literal binary-input program actually halts after both full sources and all actual handoffs. -/\ntheorem source_run (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits) :\n    ∃t ≤timeBound bits hN,SemiprimeD1StackCalls.run program t (initial bits)=some (done bits hN) :=by\n  obtain ⟨t,ht,h⟩:=source_trace bits hc hN\n  obtain ⟨out,he,ha⟩:=h [] (initial bits) ⟨rfl,rfl,rfl⟩\n  have hh:=halt_run program (ctl .done) rfl (result bits hN) [] out ha\n  refine ⟨t+1,ht,?_⟩\n  rw [SemiprimeD1StackReturnLink.run_add,he,Option.bind_some]\n  exact hh\n/-- Every original2114 source/cache/selection word survives the real frequency/rounding acquisition. -/\ntheorem root_retained (bits:List Bool) (hN:0 < bitValue bits) (k:R.Stack) :\n    (done bits hN).data (rootStack k)=(rootDone bits hN).data k :=rfl\n/-- The entire actual25-role frequency/rounding bank has its exact physical stopped projection. -/\ntheorem padding_retained (bits:List Bool) (hN:0 < bitValue bits) (k:Q.Stack) :\n    (done bits hN).data (paddingStack k)=(paddingDone bits hN).data k :=rfl\n/-- Entire original padding meaning is proved for abstract network/source before instantiating N. -/\ntheorem generic_output (root:R.Stack→List Bool) (network:SemiprimeD1TensorNetwork.Network) (a:Nat) :\n    data root (E.done (SemiprimeD1IncidenceAcquisition.acquire network.leftCount network.rows.length 64 a\n      (SemiprimeD1TensorNetwork.arity network.rows) (SemiprimeD1TensorNetwork.owner network.rows)).keys a).data output=\n        (SemiprimeD1PacketPadding.acquire network.leftCount network.rows.length 64 a\n          (SemiprimeD1TensorNetwork.arity network.rows) (SemiprimeD1TensorNetwork.owner network.rows)).padding :=by\n  rw [show output=paddingStack (Q.aux .padding) from rfl,SemiprimeD1StackRootPacketPaddingView.padding_word]\n  exact SemiprimeD1StackSourcePacketPaddingOriginal.packet_output_original network.leftCount network.rows.length 64 a\n    (SemiprimeD1TensorNetwork.arity network.rows) (SemiprimeD1TensorNetwork.owner network.rows)\n/-- Complete actual binary-N-only output is the EXACT original compact packet-padding word. -/\ntheorem output_original (bits:List Bool) (hN:0 < bitValue bits) :\n    (done bits hN).data output=\n      (SemiprimeD1PacketPadding.acquire (A.net bits hN).leftCount (A.net bits hN).rows.length 64 (A.dimension bits)\n        (SemiprimeD1TensorNetwork.arity (A.net bits hN).rows) (SemiprimeD1TensorNetwork.owner (A.net bits hN).rows)).padding :=by\n  have h:=generic_output (rootDone bits hN).data (A.net bits hN) (A.dimension bits)\n  simpa only [done,result,paddingDone,keys] using h\nend RiemannGaussian.SemiprimeD1StackRootPacketPaddingExecution\n","RiemannGaussian.SemiprimeD1StackRootPacketPaddingPrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootPacketPaddingView\n/-! # Actual acquired-key and dimension copies with their own physical calls and returns -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootPacketPaddingPrimitives\nopen SemiprimeD1StackRootPacketPadding SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => Label.local\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel data_update)\nend Link\n/-- Actual fragments concatenate with all external real return frames retained. -/\ntheorem join {m n:Nat} {pc mid next:Label} {before between after:Stack→List Bool}\n    (h:Runs program m pc before mid between) (g:Runs program n mid between next after) :\n    Runs program (m+n) pc before next after :=runs_trans program m n pc mid next before between after h g\n/-- Every cache/input handoff is a real preserving copy, not a semantic operand assignment. -/\ntheorem copy_call (site:Copy) (before:Stack→List Bool) (xs ys:List Bool)\n    (hx:before (copySource site)=xs) (hy:before (copyTarget site)=ys) (hs:before copyScratch=[]) :\n    Runs program (5*xs.length+4) (ctl (.copy site)) before (copyNext site)\n      (Function.update before (copyTarget site) (xs++ys)) :=by\n  let start:=SemiprimeD1StackCopy.state 0 none xs ys []\n  let stop:=SemiprimeD1StackCopy.done xs (xs++ys)\n  have hi:Link.DataRel (copyStack site) before start.store before:=by\n    constructor\n    · intro k;fin_cases k\n      · exact hx\n      · exact hy\n      · exact hs\n    · intro k _;rfl\n  have ho:=Link.data_update (copyStack site) (copy_injective site) before start.store before hi (1:Fin 3) (xs++ys)\n  have he:Function.update start.store 1 (xs++ys)=stop.store:=by funext k;fin_cases k <;> rfl\n  rw [he] at ho\n  exact included_call program (copyStack site) (Label.copy site) (copy_injective site) SemiprimeD1StackCopy.code 0\n    (fun _=>rfl) (ctl (.copy site)) (copyNext site) rfl (5*xs.length+3) start stop before _ rfl rfl\n    (SemiprimeD1StackCopy.copy_words xs ys none) hi ho\nend RiemannGaussian.SemiprimeD1StackRootPacketPaddingPrimitives\n","RiemannGaussian.SemiprimeD1StackRootPacketPaddingView":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootPacketPadding\n/-! # Exact whole2139-role producer and padding boundaries -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootPacketPaddingView\nopen SemiprimeD1StackRootPacketPadding\n/-- A real source-bank update retains every other actual allocated word. -/\ntheorem data_root (root:R.Stack→List Bool) (padding:Q.Stack→List Bool) (xs:List Bool) (k:R.Stack) :\n    Function.update (data root padding) (rootStack k) xs=data (Function.update root k xs) padding :=by\n  funext p\n  rcases p with p|p\n  · simp only [data,rootStack,Function.update_apply,Sum.elim_inl,Sum.inl.injEq]\n  · rfl\n/-- Generic physical projection is exact before original-N instantiation. -/\ntheorem root_word (root:R.Stack→List Bool) (padding:Q.Stack→List Bool) (k:R.Stack) :\n    data root padding (rootStack k)=root k :=rfl\n/-- A real source-bank update retains every other actual allocated word. -/\ntheorem data_padding (root:R.Stack→List Bool) (padding:Q.Stack→List Bool) (xs:List Bool) (k:Q.Stack) :\n    Function.update (data root padding) (paddingStack k) xs=data root (Function.update padding k xs) :=by\n  funext p\n  rcases p with p|p\n  · rfl\n  · simp only [data,paddingStack,Function.update_apply,Sum.elim_inr,Sum.inr.injEq]\n/-- Generic physical projection is exact before original-N instantiation. -/\ntheorem padding_word (root:R.Stack→List Bool) (padding:Q.Stack→List Bool) (k:Q.Stack) :\n    data root padding (paddingStack k)=padding k :=rfl\nend RiemannGaussian.SemiprimeD1StackRootPacketPaddingView\n","RiemannGaussian.SemiprimeD1StackRootPhaseParametersExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootPhaseParametersLoop\nimport RiemannGaussian.SemiprimeD1StackRootPhaseParametersFinish\n/-! # One original-N trace acquires the grid and caches every actual complete phase bank -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootPhaseParametersExecution\nopen SemiprimeD1StackRootPhaseParameters SemiprimeD1StackRootPhaseParametersEncoding\nopen SemiprimeD1StackRootPhaseParametersPrimitives SemiprimeD1StackRootPhaseParametersSource\nopen SemiprimeD1StackRootPhaseParametersView SemiprimeD1StackRootPhaseParametersLoop\nopen SemiprimeD1StackRootPhaseParametersFinish SemiprimeD1StackProcedureTrace\nopen SemiprimeBitArithmetic (bitValue)\n/-- Active vectors have their actual false sentinel; inactive grid bytes are empty. -/\ndef terminal (bits:List Bool) : List Bool :=if SemiprimeD1StackRootPhaseGridEncoding.active bits then [false] else []\n/-- No external row count, phase operand, result, mode or clock enters this complete budget. -/\ndef runBound (bits:List Bool) : Nat :=\n  SemiprimeD1StackRootPhaseGridExecution.runBound bits+\n  5*(SemiprimeD1StackRootPhaseGridEncoding.result bits G.output).length+\n  sweepBound (SemiprimeD1StackRootPhaseGridEncoding.result bits) (exponentValue bits) (levelsValue bits)\n    (edgeValue bits) (phases bits) [] (terminal bits)+\n  2*(stream (references (phases bits).length)).length+10\n/-- Exactly one physically read vector sentinel or empty inactive source. -/\ntheorem terminal_cases (bits:List Bool) : terminal bits=[] ∨ terminal bits=[false] :=by\n  unfold terminal\n  split\n  · exact Or.inr rfl\n  · exact Or.inl rfl\n/-- The physically acquired original root/grid output supplies the complete loop tape. -/\ntheorem acquired_grid (bits:List Bool) :\n    SemiprimeD1StackRootPhaseGridEncoding.result bits G.output=rowTape (phases bits) (terminal bits) :=by\n  by_cases ha:SemiprimeD1StackRootPhaseGridEncoding.active bits=true\n  · simp only [phases,terminal,ha,ite_true]\n    rw [rowTape_vector]\n    change (if SemiprimeD1StackRootPhaseGridEncoding.active bits then _ else [])=_\n    rw [ha]\n    rfl\n  · have hf:SemiprimeD1StackRootPhaseGridEncoding.active bits=false:=Bool.eq_false_iff.mpr ha\n    simp only [phases,terminal,hf,rowTape]\n    change (if SemiprimeD1StackRootPhaseGridEncoding.active bits then _ else [])=[]\n    rw [hf]\n    rfl\n/-- The current parent exponent is the actual retained tally, not successor metadata. -/\ntheorem acquired_exponent (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) :\n    SemiprimeD1StackRootPhaseGridEncoding.result bits G.exponent=List.replicate (exponentValue bits) true :=\n  SemiprimeD1StackRootPhaseGridEncoding.acquired_exponent bits hc\n/-- The current parent u tally is physically acquired from N by the retained source. -/\ntheorem acquired_levels (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) :\n    SemiprimeD1StackRootPhaseGridEncoding.result bits\n      (G.rootStack (SemiprimeD1StackRootRecursiveControl.sourceStack SemiprimeD1StackRootParameters.levels))=\n      List.replicate (levelsValue bits) true :=\n  (SemiprimeD1StackRootRecursiveControlOriginal.source_preserved bits SemiprimeD1StackRootParameters.levels).trans\n    (SemiprimeD1StackRootParametersOriginal.levels_original bits hc)\n/-- The actual shared occurrence count M is retained without a second graph scan. -/\ntheorem acquired_edges (bits:List Bool) :\n    SemiprimeD1StackRootPhaseGridEncoding.result bits\n      (G.rootStack (SemiprimeD1StackRootRecursiveControl.sourceStack SemiprimeD1StackRootParameters.edges))=\n      List.replicate (edgeValue bits) true :=\n  (SemiprimeD1StackRootRecursiveControlOriginal.source_preserved bits SemiprimeD1StackRootParameters.edges).trans\n    (SemiprimeD1StackRootRecursiveControlEncoding.acquired_edges bits)\n/-- The complete acquired grid is copied to its consuming reader ONCE and retained. -/\ntheorem grid_copy (root:G.Stack→List Bool) :\n    Runs program (5*(root G.output).length+4) (.copySite 0) (loop root [] [] 0 [])\n      .header (loop root (root G.output) [] 0 []) :=by\n  have h:=copy_call 0 (loop root [] [] 0 []) rfl rfl\n  change Runs program (5*(root G.output).length+4) (.copySite 0) (loop root [] [] 0 []) .header\n    (Function.update (view root (fun _=>[]) [] [] [] [] [] [] [] []) (aux .reader) (root G.output)) at h\n  rw [update_reader] at h\n  exact h\n/-- All sixty-two new roles are empty after the one whole acquired-grid call. -/\ntheorem afterGrid_loop (bits:List Bool) :\n    afterGrid bits=loop (SemiprimeD1StackRootPhaseGridEncoding.result bits) [] [] 0 [] :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · rcases k with k|k\n    · rfl\n    · cases k <;> rfl\n/-- WHOLE original-N-only source trace, including every actual phase call and\nboth accepted/rejected complete stopped banks, with one final physical reversal. -/\ntheorem source_trace (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    ∃t,t+1≤runBound bits ∧ Runs program t .start (input bits) .done (result bits) :=by\n  let root:=SemiprimeD1StackRootPhaseGridEncoding.result bits\n  let cached:=records (exponentValue bits) (levelsValue bits) (edgeValue bits) (phases bits)\n  obtain ⟨g,hg,h0⟩:=grid_call bits hc hN\n  rw [afterGrid_loop] at h0\n  have h1:=grid_copy root\n  have hout:root G.output=rowTape (phases bits) (terminal bits):=acquired_grid bits\n  rw [hout] at h1\n  obtain ⟨r,hr,h2⟩:=rows_run root (exponentValue bits) (levelsValue bits) (edgeValue bits)\n    (phases bits) [] (terminal bits) (terminal_cases bits) (acquired_exponent bits hc)\n    (acquired_levels bits hc) (acquired_edges bits)\n  have h3:=finish_run root cached\n  change Runs program r .header (loop root (rowTape (phases bits) (terminal bits)) [] 0 [])\n    .finishSeed (loop root [] (SemiprimeD1StackHeapAllocate.heapBytes cached) cached.length\n      (stream (references cached.length)).reverse) at h2\n  have hh:=compose (compose (compose h0 h1) h2) h3\n  refine ⟨_,?_,hh⟩\n  have hl:cached.length=(phases bits).length:=by simp only [cached,records,List.length_map]\n  change (g+1)+(5*(rowTape (phases bits) (terminal bits)).length+4)+r+(2*(stream (references cached.length)).length+4)+1≤runBound bits\n  rw [hl]\n  unfold runBound\n  rw [acquired_grid]\n  dsimp only [root] at hr\n  omega\n/-- Complete same-program halt from ORIGINAL binary N alone, with every private\nphase word cleared and every source/grid cell retained exactly. -/\ntheorem source_run (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    ∃t≤runBound bits,SemiprimeD1StackCalls.run program t (initial bits)=some (done bits) :=by\n  obtain ⟨t,ht,h⟩:=source_trace bits hc hN\n  obtain ⟨finish,hf,hs⟩:=h [] (initial bits) ⟨rfl,rfl,rfl⟩\n  have hh:=halt_run program .done rfl (result bits) [] finish hs\n  refine ⟨t+1,ht,?_⟩\n  rw [SemiprimeD1StackReturnLink.run_add,hf,Option.bind_some]\n  exact hh\nend RiemannGaussian.SemiprimeD1StackRootPhaseParametersExecution\n","RiemannGaussian.SemiprimeD1StackRootRecursiveControlExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootRecursiveControlEncoding\n\n/-! # One original-input run acquiring and executing the exact root branch\nBoth included executions are concrete, balanced traces of fixed programs.\nTheir real calls, return frames and final halt are counted explicitly.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 131072\nnamespace RiemannGaussian.SemiprimeD1StackRootRecursiveControlExecution\nopen SemiprimeD1StackRootRecursiveControl SemiprimeD1StackRootRecursiveControlEncoding\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeBitArithmetic (bitValue)\nlocal notation \"ctl\" => (Sum.inl : Control→Label)\nattribute [local irreducible] SemiprimeD1StackRootParametersExecution.result values parentExponent\n/-- Own complete clock: the actual original-input source, actual gate and both real calls. -/\ndef runBound (bits:List Bool) : Nat := SemiprimeD1StackRootParameters.runBound bits+\n  GS.runBound (parentExponent bits) (values bits)+3\n/-- One real call acquires all original root operands from N alone. -/\ntheorem source_call (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    ∃t≤SemiprimeD1StackRootParameters.runBound bits,\n      Runs program (t+1) (ctl .start) (input bits) (ctl .gate) (afterSource bits) := by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackRootParametersExecution.source_run bits hc hN\n  refine ⟨t,ht,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program sourceStack sourceLabel Sum.inl_injective\n    P.program (.inl .start) (fun _=>rfl) (ctl .start) (ctl .gate) rfl t\n    (P.initial bits) (P.done bits) _ _ rfl rfl rfl rfl hr\n  · constructor\n    · intro k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk;cases k with\n      | inl k=>exact (hk k rfl).elim\n      | inr k=>rfl\n/-- The actual source output, not prepared advice, supplies every guard/successor operand. -/\ntheorem gate_call (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) :\n    ∃t≤GS.runBound (parentExponent bits) (values bits),\n      Runs program (t+1) (ctl .gate) (afterSource bits) (ctl .done) (result bits) := by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackRecursiveScheduleExecution.source_run (parentExponent bits) (values bits)\n  refine ⟨t,ht,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program gateStack gateLabel gate_injective\n    G.program (.inl .start) (fun _=>rfl) (ctl .gate) (ctl .done) rfl t\n    (GS.initial (parentExponent bits) (values bits)) (GS.done (parentExponent bits) (values bits))\n    _ _ rfl rfl rfl rfl hr\n  · constructor\n    · exact initial_projection bits hc\n    · intro k _;rfl\n  · constructor\n    · exact result_projection bits hc\n    · intro k hk;cases k with\n      | inl k=>rfl\n      | inr k=>exact (hk (freshRole k) (freshRole_mapped k)).elim\n/-- Entire original-N source and original branch run in the same fixed program. -/\ntheorem source_trace (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    ∃t,t+1≤runBound bits ∧ Runs program t (ctl .start) (input bits) (ctl .done) (result bits) := by\n  obtain ⟨s,hs,h0⟩:=source_call bits hc hN\n  obtain ⟨g,hg,h1⟩:=gate_call bits hc\n  refine ⟨(s+1)+(g+1),?_,runs_trans program _ _ _ _ _ _ _ _ h0 h1⟩\n  unfold runBound\n  omega\n/-- Genuine complete original-input execution includes all acquisition, conditional work and halt. -/\ntheorem source_run (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    ∃t≤runBound bits,SemiprimeD1StackCalls.run program t (initial bits)=some (done bits) := by\n  obtain ⟨t,ht,h⟩:=source_trace bits hc hN\n  obtain ⟨finish,hf,hs⟩:=h [] (initial bits) ⟨rfl,rfl,rfl⟩\n  have hh:=halt_run program (ctl .done) rfl (result bits) [] finish hs\n  refine ⟨t+1,ht,?_⟩\n  rw [SemiprimeD1StackReturnLink.run_add,hf,Option.bind_some]\n  exact hh\nend RiemannGaussian.SemiprimeD1StackRootRecursiveControlExecution\n","RiemannGaussian.SemiprimeD1StackRootScaleLeafComponents":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootScaleLeafDoubling\nimport RiemannGaussian.SemiprimeD1StackRootScaleLeafDivision\n/-! # Real acquired-width scaling and exact square-root/leaf composition -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1800000\nset_option maxRecDepth 100000\nnamespace RiemannGaussian.SemiprimeD1StackRootScaleLeafComponents\nopen SemiprimeD1StackRootScaleLeaf SemiprimeD1StackRootScaleLeafPrimitives\nopen SemiprimeD1StackRootScaleLeafArithmetic SemiprimeD1StackProcedureTrace\n/-- ONLY the actual acquired old cache and ten physically empty fresh roles. -/\ndef base (bits : List Bool) : Stack→List Bool :=(ready bits).data\n/-- Reached actual materialized scale, retaining the ENTIRE old cache. -/\ndef scaled (bits : List Bool) : Stack→List Bool :=\n  store (SemiprimeD1StackRootScheduleExecution.result bits) (D.contents [] [] [] [] [] [])\n    (metadata (D.unary (scale bits.length)) [] [] [])\n/-- Every one of twenty physical doublings starts with the ACTUALLY acquired width;\nno prepared scale or width is supplied to this ready entry. -/\ntheorem acquire_scale (bits : List Bool) :\n    Runs program (5*bits.length+4+SemiprimeD1StackRootScaleLeafDoubling.runTime bits.length 20)\n      .ready (base bits) (.double 20) (scaled bits) :=by\n  have h0:=copy_call 0 .ready (.double 0) rfl (base bits) rfl\n  have hl:(base bits (copySource 0)).length=bits.length:=by\n    change (List.replicate bits.length true).length=bits.length\n    simp only [List.length_replicate]\n  rw [hl] at h0\n  have he0:Function.update (base bits) (copyTarget 0) (base bits (copySource 0)++base bits (copyTarget 0))=\n      SemiprimeD1StackRootScaleLeafDoubling.data (base bits) bits.length 0:=by\n    funext j;rcases j with j|j\n    · rfl\n    · rcases j with j|j\n      · cases j <;> rfl\n      · cases j <;> first | rfl | (change D.unary bits.length++[]=D.unary bits.length;exact List.append_nil _)\n  rw [he0] at h0\n  have h1:=SemiprimeD1StackRootScaleLeafDoubling.rounds (base bits) 20 (by omega) bits.length\n  have hi:SemiprimeD1StackRootScaleLeafDoubling.index 20 (by omega)=(0:Fin 21):=by apply Fin.ext;rfl\n  rw [hi] at h1\n  have he1:SemiprimeD1StackRootScaleLeafDoubling.data (base bits) (2^20*bits.length) 0=scaled bits:=by\n    funext j;rcases j with j|j\n    · rfl\n    · rcases j with j|j\n      · cases j <;> rfl\n      · cases j <;> rfl\n  rw [he1] at h1\n  exact join h0 h1\n/-- The ACTUALLY acquired lambda is physically copied, and the first odd block\nis really seeded by one marker push. All old cache fields stay byte-identical. -/\ntheorem prepare_square (bits : List Bool) :\n    Runs program (5*SemiprimeD1StackRootScheduleArithmetic.lambda bits.length+5)\n      (.double 20) (scaled bits) .squareCopy\n      (SemiprimeD1StackRootScaleLeafSqrt.data (SemiprimeD1StackRootScheduleExecution.result bits)\n        (D.unary (scale bits.length)) (SemiprimeD1StackRootScheduleArithmetic.lambda bits.length) 0 0) :=by\n  let copied:=store (SemiprimeD1StackRootScheduleExecution.result bits)\n    (D.contents (D.unary (SemiprimeD1StackRootScheduleArithmetic.lambda bits.length)) [] [] [] [] [])\n    (metadata (D.unary (scale bits.length)) [] [] [])\n  have h0:=copy_call 1 (.double 20) .seedOdd rfl (scaled bits) rfl\n  have hl:(scaled bits (copySource 1)).length=SemiprimeD1StackRootScheduleArithmetic.lambda bits.length:=by\n    change (List.replicate (SemiprimeD1StackRootScheduleArithmetic.lambda bits.length) true).length=_\n    simp only [List.length_replicate]\n  rw [hl] at h0\n  have he0:Function.update (scaled bits) (copyTarget 1) (scaled bits (copySource 1)++scaled bits (copyTarget 1))=copied:=by\n    funext j;rcases j with j|j\n    · rfl\n    · rcases j with j|j\n      · cases j <;> first | rfl | (change D.unary (SemiprimeD1StackRootScheduleArithmetic.lambda bits.length)++[]=_;exact List.append_nil _)\n      · cases j <;> rfl\n  rw [he0] at h0\n  have h1:=push .seedOdd .squareCopy (divStack .divisor) copied rfl\n  have he1:Function.update copied (divStack .divisor) (true::copied (divStack .divisor))=\n      SemiprimeD1StackRootScaleLeafSqrt.data (SemiprimeD1StackRootScheduleExecution.result bits)\n        (D.unary (scale bits.length)) (SemiprimeD1StackRootScheduleArithmetic.lambda bits.length) 0 0:=by\n    funext j;rcases j with j|j\n    · rfl\n    · rcases j with j|j\n      · cases j <;> rfl\n      · cases j <;> rfl\n  rw [he1] at h1\n  have h:=join h0 h1\n  have ht:(5*SemiprimeD1StackRootScheduleArithmetic.lambda bits.length+4)+1=\n      5*SemiprimeD1StackRootScheduleArithmetic.lambda bits.length+5:=by omega\n  rw [ht] at h\n  exact h\n/-- Exact acquired scale/root/leaf result, including the retained positive\nleaf divisor; all ten fresh roles and all fifteen old roles are explicit. -/\ndef result (bits : List Bool) : Stack→List Bool :=\n  SemiprimeD1StackRootScaleLeafDivision.context (SemiprimeD1StackRootScheduleExecution.result bits)\n    (scale bits.length) (root bits.length) (leaf bits.length) 0 (root bits.length+1) 0 0\n/-- Fixed polynomial ready-stage allowance, with NO repeated N/root acquisition. -/\ndef readyBound (bits : List Bool) : Nat :=1000000000000*(bits.length+1)^3\n/-- All actual scaling, square-root and quotient transitions obey this numeric envelope. -/\ntheorem arithmetic_bound (n lam k ts tl : Nat) (hl : lam≤n+20) (hk : k≤lam)\n    (hs : ts≤100000*(2*lam+1)^2) (hq : tl≤120*(2^20*n+k+2)) :\n    (5*n+4+SemiprimeD1StackRootScaleLeafDoubling.runTime n 20)+(5*lam+5)+ts+tl+1≤\n      1000000000000*(n+1)^3 :=by\n  have hd:=SemiprimeD1StackRootScaleLeafDoubling.twenty_time n\n  have hb:2*lam+1≤41*(n+1):=by omega\n  have hp:(2*lam+1)^2≤1681*(n+1)^2:=by\n    have h:=Nat.pow_le_pow_left hb 2\n    simpa only [mul_pow,show (41:Nat)^2=1681 by decide] using h\n  have hp3:(n+1)^2≤(n+1)^3:=Nat.pow_le_pow_right (by omega) (by decide)\n  norm_num at hq\n  nlinarith\n/-- Complete READY entry: genuine acquired cache → twenty physical doubles →\nexact physical integer sqrt → real divider/+1. No arithmetic supplier premise. -/\ntheorem ready_trace (bits : List Bool) :\n    ∃t,t+1≤readyBound bits ∧ Runs program t .ready (base bits) .done (result bits) :=by\n  have h0:=acquire_scale bits\n  have h1:=prepare_square bits\n  obtain ⟨ts,ht,hs⟩:=SemiprimeD1StackRootScaleLeafSqrt.square_root\n    (SemiprimeD1StackRootScheduleExecution.result bits) (D.unary (scale bits.length))\n    (SemiprimeD1StackRootScheduleArithmetic.lambda bits.length) 0\n  change Runs program ts .squareCopy\n    (SemiprimeD1StackRootScaleLeafSqrt.data (SemiprimeD1StackRootScheduleExecution.result bits)\n      (D.unary (scale bits.length)) (SemiprimeD1StackRootScheduleArithmetic.lambda bits.length) 0 0)\n    .copyRoot (SemiprimeD1StackRootScaleLeafSqrt.result (SemiprimeD1StackRootScheduleExecution.result bits)\n      (D.unary (scale bits.length)) (root bits.length)) at hs\n  obtain ⟨tl,hl,h2⟩:=SemiprimeD1StackRootScaleLeafDivision.leaf_stage\n    (SemiprimeD1StackRootScheduleExecution.result bits) (scale bits.length) (root bits.length)\n  have h:=join (join (join h0 h1) hs) h2\n  refine ⟨((5*bits.length+4+SemiprimeD1StackRootScaleLeafDoubling.runTime bits.length 20)+\n    (5*SemiprimeD1StackRootScheduleArithmetic.lambda bits.length+5))+ts+tl,?_,h⟩\n  have hk:root bits.length≤SemiprimeD1StackRootScheduleArithmetic.lambda bits.length:=Nat.sqrt_le_self _\n  exact arithmetic_bound bits.length (SemiprimeD1StackRootScheduleArithmetic.lambda bits.length)\n    (root bits.length) ts tl (SemiprimeD1StackRootScheduleArithmetic.lambda_le bits.length) hk ht hl\nend RiemannGaussian.SemiprimeD1StackRootScaleLeafComponents\n","RiemannGaussian.SemiprimeD1StackRootScheduleExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootScheduleStages\n/-! # Complete original-binary root schedule execution and its own clock -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1600000\nset_option maxRecDepth 100000\nnamespace RiemannGaussian.SemiprimeD1StackRootScheduleExecution\nopen SemiprimeD1StackRootSchedule SemiprimeD1StackRootScheduleStages\nopen SemiprimeD1StackRootScheduleArithmetic SemiprimeD1StackRootSchedulePrimitives\nopen SemiprimeD1StackProcedureTrace\n/-- Exact final actual15-role bank: N stays binary, width/metadata are paid markers,\nall copying/divider work is empty, and the constant divisor stays retained. -/\ndef result (bits : List Bool) : Stack→List Bool :=\n  context bits (D.unary (lambda bits.length)) (D.unary (levels bits.length))\n    (D.unary (exponent bits.length)) (D.unary (minimum bits.length))\n/-- Actual clean halt, with no silently erased physical work or real return cells. -/\ndef done (bits : List Bool) : C.State Stack Label :=⟨none,none,none,result bits,[]⟩\n/-- One fixed polynomial in original INPUT BYTES, never supplied to the machine. -/\ndef runBound (bits : List Bool) : Nat :=100000000*(bits.length+1)^3\n/-- Pure numeric substitution for the actual four source stages and final halt. -/\ntheorem arithmetic_bound (n lam u a b c d : Nat) (hl : lam≤n+20) (hu : u≤lam)\n    (ha : a≤5*n+28) (hb : b≤5*n+4+1000*(n+1)^2)\n    (hc : c≤5*lam+12+1000*(lam+1)^2)\n    (hd : d≤5*lam+12+180000*(lam+1)+10*u) :\n    a+b+c+d+1≤100000000*(n+1)^3 := by\n  have hl':lam+1≤21*(n+1):=by omega\n  have hp: (lam+1)^2≤441*(n+1)^2:=by\n    have h:=Nat.pow_le_pow_left hl' 2\n    simpa only [mul_pow,show (21:Nat)^2=441 by decide] using h\n  have hs:a+b+c+d+1≤10000000*(n+1)^2:=by nlinarith\n  have hpow:(n+1)^2≤(n+1)^3:=Nat.pow_le_pow_right (by omega) (by decide)\n  exact hs.trans ((Nat.mul_le_mul_left _ hpow).trans (Nat.mul_le_mul_right _ (by decide)))\n/-- ENTIRE paid root acquisition starts with only the original binary word.\nAll source traces below are concrete frozen/bootstrap/divider instructions. -/\ntheorem source_trace (bits : List Bool) :\n    ∃t,t+1≤runBound bits ∧ Runs program t .start (input bits) .done (result bits) := by\n  obtain ⟨a,ha,h0⟩:=setup bits\n  obtain ⟨b,hb,h1⟩:=acquire_lambda bits\n  obtain ⟨c,hc,h2⟩:=acquire_minimum bits\n  obtain ⟨d,hd,h3⟩:=acquire_levels bits\n  refine ⟨((a+b)+c)+d,?_,join (join (join h0 h1) h2) h3⟩\n  exact arithmetic_bound bits.length (lambda bits.length) (levels bits.length) a b c d\n    (lambda_le bits.length) (Nat.div_le_self _ _) ha hb hc hd\n/-- Real original-input source halt with the same own fixed polynomial clock. -/\ntheorem source_run (bits : List Bool) :\n    ∃t≤runBound bits,SemiprimeD1StackCalls.run program t (initial bits)=some (done bits) := by\n  obtain ⟨t,ht,hr⟩:=source_trace bits\n  obtain ⟨finish,hf,hAt⟩:=hr [] (initial bits) ⟨rfl,rfl,rfl⟩\n  have hh:=halt_run program .done rfl (result bits) [] finish hAt\n  exact ⟨t+1,ht,by rw [SemiprimeD1StackReturnLink.run_add,hf,Option.bind_some];exact hh⟩\n/-- The same program has a genuine one-input initialization, with no hidden\nwidth, scale, lambda, divisor, root levels, exponent or minimum guard input. -/\ntheorem initial_eq (bits : List Bool) :\n    Turing.initList machine bits=SemiprimeD1StackCalls.configuration (initial bits) := by\n  have hs:SemiprimeD1StackCalls.initial (boot .input) Label.start bits=initial bits:=by\n    apply congrArg (fun d=>(⟨some .start,none,none,d,[]⟩:C.State Stack Label))\n    funext k\n    rcases k with k|k\n    · cases k <;> rfl\n    · rcases k with k|k <;> rfl\n  exact (SemiprimeD1StackCalls.initial_correct (boot .input) (aux .exponent) Label.start program bits).symm.trans\n    (congrArg SemiprimeD1StackCalls.configuration hs)\n/-- Complete original-N acquisition on ONE fixed genuine finite-control machine. -/\nnoncomputable def acquireInTime (bits : List Bool) :\n    StateTransition.EvalsToInTime machine.step (Turing.initList machine bits)\n      (some (SemiprimeD1StackCalls.configuration (done bits))) (runBound bits) := by\n  rw [initial_eq]\n  apply SemiprimeD1StackCalls.evalsCorrect (boot .input) (aux .exponent) .start program\n  let h:=source_run bits\n  let t:=Classical.choose h\n  have ht:=Classical.choose_spec h\n  exact ⟨⟨t,ht.2⟩,ht.1⟩\nend RiemannGaussian.SemiprimeD1StackRootScheduleExecution\n","RiemannGaussian.SemiprimeD1StackRootSourceOccurrencesBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootNetworkRowsResources\nimport RiemannGaussian.SemiprimeD1StackSourceOccurrencesBounds\nimport RiemannGaussian.SemiprimeD1StackRootSourceOccurrencesExecution\n/-! # Own whole-root/occurrence source clock from actual acquired input bytes\nThe root source pays both retained input words to the physical index. Its\nown bound is squared after the actual root/output/count trace is charged.\nNo native graph report or supplied owner/count/key answer enters these bounds.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootSourceOccurrencesBounds\nnamespace RC\nexport SemiprimeD1StackRootNetworkRows (Stack program initialPrefix output)\nend RC\nnamespace RE\nexport SemiprimeD1StackRootNetworkRowsExecution (done timeBound source_run_prefix)\nexport SemiprimeD1StackRootNetworkRecordsAcquisition (prescription)\nend RE\nnamespace RB\nexport SemiprimeD1StackRootNetworkRowsBounds (prefixPolynomial runBoundPrefix timeBound_le_prefix)\nend RB\nnamespace RR\nexport SemiprimeD1StackRootNetworkRowsResources (initial_prefix_length)\nend RR\nopen SemiprimeBitArithmetic (bitValue)\nopen SemiprimePublicAcquiredExecution (wireCount)\n/-- The same successful source trace pays both physical index input words. -/\ntheorem occurrence_input_cap (bytes count cap:Nat) (hb:bytes ≤cap) (hc:count ≤cap) :\n    1000000*(bytes+count+1)^2 ≤1000000*(2*cap+1)^2:=by\n  exact Nat.mul_le_mul_left 1000000 (Nat.pow_le_pow_left (by omega) 2)\n/-- One quadratic cap includes the actual root call, occurrence call and final halt. -/\ntheorem combined_cap (n P rootTime rootCap indexTime:Nat) (ht:rootTime ≤rootCap)\n    (hi:indexTime ≤1000000*(2*(n+P+rootTime)+1)^2) :\n    rootTime+indexTime+3 ≤5000000*(n+P+rootCap+1)^2:=by\n  let S:=n+P+rootCap+1\n  have hs:1 ≤S:=by dsimp [S];omega\n  have hlin:2*(n+P+rootTime)+1 ≤2*S:=by dsimp [S];omega\n  have hpow:=Nat.pow_le_pow_left hlin 2\n  have hindex:indexTime ≤4000000*S^2:=by\n    have h:=hi.trans (Nat.mul_le_mul_left 1000000 hpow)\n    convert h using 1;ring\n  have hsq:1 ≤S^2:=Nat.one_le_pow _ _ hs\n  have hself:S ≤S^2:=Nat.le_pow (by decide:0<(2:Nat))\n  have htime:rootTime ≤S^2:=by\n    have h:rootTime ≤S:=by dsimp [S];omega\n    exact h.trans hself\n  change _ ≤5000000*S^2\n  omega\n/-- A single actual exponential factor is squared only after the whole physical source cost is bounded. -/\ntheorem quadratic_rate (n P r E:Nat) (he:1 ≤E):\n    5000000*(n+P+r*E+1)^2 ≤5000000*(n+P+r+1)^2*E^2:=by\n  have h: n+P+1 ≤(n+P+1)*E:=by\n    simpa only [Nat.mul_one] using Nat.mul_le_mul_left (n+P+1) he\n  have hlin:n+P+r*E+1 ≤(n+P+r+1)*E:=by nlinarith only [h]\n  have hp:=Nat.mul_le_mul_left 5000000 (Nat.pow_le_pow_left hlin 2)\n  convert hp using 1;ring\n/-- Fixed base-two arithmetic identifies the squared actual root-source exponent. -/\ntheorem scope_square (B:Nat):(2^(57*B))^2=2^(114*B):=by\n  rw [←pow_mul]\n  congr 1\n  omega\n/-- A fixed quadratic transform preserves fixed monomial witnesses in total actual input bytes. -/\ntheorem quadratic_monomial {f:Nat→Nat→Nat}\n    (hf:∃a d:Nat,∀n P,f n P ≤a*(n+P+1)^d):\n    ∃a d:Nat,∀n P,5000000*(n+P+f n P+1)^2 ≤a*(n+P+1)^d:=by\n  obtain ⟨a,d,hf⟩:=hf\n  refine ⟨5000000*(1+a)^2,2*(d+1),?_⟩\n  intro n P\n  let S:=n+P+1\n  have hs:1 ≤S:=by dsimp [S];omega\n  have hd:S^d ≤S^(d+1):=Nat.pow_le_pow_right hs (by omega)\n  have hself:S ≤S^(d+1):=by\n    simpa only [pow_one] using Nat.pow_le_pow_right hs (by omega:1 ≤d+1)\n  have hpoly:f n P ≤a*S^(d+1):=(hf n P).trans (Nat.mul_le_mul_left a hd)\n  have hlin:n+P+f n P+1 ≤(1+a)*S^(d+1):=by\n    have he:n+P+f n P+1=S+f n P:=by dsimp [S];omega\n    rw [he]\n    nlinarith only [hself,hpoly]\n  have h:=Nat.mul_le_mul_left 5000000 (Nat.pow_le_pow_left hlin 2)\n  change _ ≤(5000000*(1+a)^2)*S^(2*(d+1))\n  calc\n    _ ≤5000000*((1+a)*S^(d+1))^2:=h\n    _= _:=by rw [mul_pow,←pow_mul,Nat.mul_comm (d+1) 2];ring\n/-- Every actually acquired root data word is bounded by the SAME successful source trace. -/\ntheorem root_word_length (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits)\n    (fixed:List (Fin (wireCount (bitValue bits))×Bool)) (tail:List Bool) (k:RC.Stack):\n    ((RE.done bits hN fixed tail).data k).length ≤\n      bits.length+(RE.prescription bits fixed tail).length+RE.timeBound bits hN fixed tail:=by\n  obtain ⟨time,ht,hr⟩:=RE.source_run_prefix bits hc hN fixed tail\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound RC.program time\n    (bits.length+(RE.prescription bits fixed tail).length) _ _\n    (RR.initial_prefix_length bits (RE.prescription bits fixed tail)) hr k\n  exact hd.trans (Nat.add_le_add_left ht _)\n/-- Conservative quadratic cap for the two actual source calls and actual caller halt. -/\ndef runCapPrefix (bits:List Bool) (P:Nat):Nat:=\n  5000000*(bits.length+P+RB.runBoundPrefix bits P+1)^2\n/-- A fixed physical input/prefix polynomial before every original input. -/\ndef prefixPolynomial (n P:Nat):Nat:=5000000*(n+P+RB.prefixPolynomial n P+1)^2\n/-- Same actual combined-program rate, with the squared original root-source exponent. -/\ndef runBoundPrefix (bits:List Bool) (P:Nat):Nat:=\n  prefixPolynomial bits.length P*2^(114*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits)\n/-- Standard N-only entry physically seeds its single false prescription marker. -/\ndef runBound (bits:List Bool):Nat:=runBoundPrefix bits 1\n/-- The full quadratic caller cap fits its own fixed original scope-rate envelope. -/\ntheorem runCapPrefix_le (bits:List Bool) (P:Nat):runCapPrefix bits P ≤runBoundPrefix bits P:=by\n  have he:1 ≤2^(57*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits):=Nat.pow_pos (by decide)\n  have h:=quadratic_rate bits.length P (RB.prefixPolynomial bits.length P)\n    (2^(57*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits)) he\n  simpa only [runCapPrefix,runBoundPrefix,RB.runBoundPrefix,prefixPolynomial,scope_square] using h\n/-- The caller-prefix polynomial has fixed witnesses before both N and all physical prefix bytes. -/\ntheorem prefix_polynomial_monomial:∃coef degree:Nat,∀n P,prefixPolynomial n P ≤coef*(n+P+1)^degree:=\n  quadratic_monomial SemiprimeD1StackRootNetworkRowsBounds.prefix_polynomial_monomial\n/-- N-only polynomial witnesses use the original positive width argument n+1. -/\ntheorem polynomial_monomial:∃coef degree:Nat,∀n,prefixPolynomial n 1 ≤coef*(n+1)^degree:=by\n  obtain ⟨coef,degree,h⟩:=prefix_polynomial_monomial\n  refine ⟨coef*2^degree,degree,?_⟩\n  intro n\n  have hs:n+1+1 ≤2*(n+1):=by omega\n  have hp:=Nat.pow_le_pow_left hs degree\n  have hh:prefixPolynomial n 1 ≤coef*(2*(n+1))^degree:=(h n 1).trans (Nat.mul_le_mul_left coef hp)\n  simpa only [mul_pow,Nat.mul_assoc] using hh\nnamespace X\nexport SemiprimeD1StackRootSourceOccurrencesExecution (timeBound done source_run source_run_prefix)\nend X\nnamespace Q\nexport SemiprimeD1StackRootSourceOccurrencesComponents (rootn rootrows root_output root_number)\nend Q\nnamespace IE\nexport SemiprimeD1StackSourceOccurrencesExecution (timeBound)\nend IE\nopen SemiprimeD1StackRootSourceOccurrences\nattribute [local irreducible] Q.rootn Q.rootrows IE.timeBound RE.timeBound\n/-- The actual index source's own quadratic budget is paid by its two physically shared root words. -/\ntheorem occurrence_timeBound_physical (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0 < bitValue bits) (fixed:List (Fin (wireCount (bitValue bits))×Bool)) (tail:List Bool):\n    IE.timeBound (Q.rootn bits hN fixed) (Q.rootrows bits hN fixed) ≤1000000*\n      (((RE.done bits hN fixed tail).data RC.output).length+\n        ((RE.done bits hN fixed tail).data SemiprimeD1StackRootNetworkRowsOriginal.leftCount).length+1)^2:=by\n  rw [Q.root_output bits hc hN fixed tail,Q.root_number bits hc hN fixed tail,List.length_replicate]\n  exact SemiprimeD1StackSourceOccurrencesBounds.timeBound_le _ _\n/-- Both physical input lengths are charged to the SAME successful whole root source execution. -/\ntheorem occurrence_timeBound_cap (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0 < bitValue bits) (fixed:List (Fin (wireCount (bitValue bits))×Bool)) (tail:List Bool):\n    IE.timeBound (Q.rootn bits hN fixed) (Q.rootrows bits hN fixed) ≤1000000*\n      (2*(bits.length+(RE.prescription bits fixed tail).length+RE.timeBound bits hN fixed tail)+1)^2:=by\n  have hv:=root_word_length bits hc hN fixed tail RC.output\n  have hn:=root_word_length bits hc hN fixed tail SemiprimeD1StackRootNetworkRowsOriginal.leftCount\n  exact (occurrence_timeBound_physical bits hc hN fixed tail).trans (occurrence_input_cap _ _ _ hv hn)\n/-- The same whole caller budget includes both actual source calls, the N-only seed, and the final halt. -/\ntheorem timeBound_cap (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits)\n    (fixed:List (Fin (wireCount (bitValue bits))×Bool)) (tail:List Bool):\n    X.timeBound bits hN fixed tail ≤runCapPrefix bits (RE.prescription bits fixed tail).length:=by\n  have hr:RE.timeBound bits hN fixed tail ≤RB.runBoundPrefix bits (RE.prescription bits fixed tail).length:=\n    RB.timeBound_le_prefix bits hc hN fixed tail\n  have hi:=occurrence_timeBound_cap bits hc hN fixed tail\n  unfold X.timeBound runCapPrefix\n  exact combined_cap _ _ _ _ _ hr hi\n/-- Actual caller-prefix time fits one fixed polynomial and the squared actual table exponent. -/\ntheorem timeBound_le_prefix (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0 < bitValue bits) (fixed:List (Fin (wireCount (bitValue bits))×Bool)) (tail:List Bool):\n    X.timeBound bits hN fixed tail ≤runBoundPrefix bits (RE.prescription bits fixed tail).length:=\n  (timeBound_cap bits hc hN fixed tail).trans (runCapPrefix_le _ _)\n/-- Standard N-only source clock includes the physically seeded false prefix marker. -/\ntheorem timeBound_le (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits):\n    X.timeBound bits hN [] [] ≤runBound bits:=by\n  have h:=timeBound_le_prefix bits hc hN [] []\n  simpa only [SemiprimeD1StackRootNetworkRecordsAcquisition.prescription_empty,List.length_singleton,runBound] using h\n/-- Actual N-only finite-program source trace with its own whole acquired-index clock. -/\ntheorem source_run_bounded (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits):\n    ∃time ≤runBound bits,SemiprimeD1StackCalls.run program time (initial bits)=some (X.done bits hN [] []):=by\n  obtain ⟨time,ht,hr⟩:=X.source_run bits hc hN\n  exact ⟨time,ht.trans (timeBound_le bits hc hN),hr⟩\n/-- Every repeated/conflicting actual caller-prefix and retained tail follows the same bounded source. -/\ntheorem source_run_prefix_bounded (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0 < bitValue bits) (fixed:List (Fin (wireCount (bitValue bits))×Bool)) (tail:List Bool):\n    ∃time ≤runBoundPrefix bits (RE.prescription bits fixed tail).length,\n      SemiprimeD1StackCalls.run program time (initialPrefix bits (RE.prescription bits fixed tail))=\n        some (X.done bits hN fixed tail):=by\n  obtain ⟨time,ht,hr⟩:=X.source_run_prefix bits hc hN fixed tail\n  exact ⟨time,ht.trans (timeBound_le_prefix bits hc hN fixed tail),hr⟩\nend RiemannGaussian.SemiprimeD1StackRootSourceOccurrencesBounds\n","RiemannGaussian.SemiprimeD1StackRootSourceOccurrencesOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootSourceOccurrencesResources\n/-! # Exact original-binary-N compact occurrence-key source\nAll row/count/key acquisition occurs on the actual path. One same-program clock\npays preprocessing, all copies/parsers/normalizers/counters/logs and real returns.\nFixed monomial witnesses precede the whole family of original canonical inputs.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootSourceOccurrencesOriginal\nopen SemiprimeD1StackRootSourceOccurrences SemiprimeD1StackRootSourceOccurrencesComponents\nopen SemiprimeD1StackRootSourceOccurrencesExecution\nopen SemiprimeBitArithmetic (bitValue)\nnamespace O\nexport SemiprimeD1StackSourceOccurrencesOriginal (originalPairsFrom output_original factor_count occurrence_count)\nend O\n/-- Generic actual final-source projection is proved before instantiating any original arithmetic graph. -/\ntheorem final_projection (root:R.Stack→List Bool) (n:Nat) (rows:List (List (List Bool)))\n    (hr:root R.output=Enc.inputTape rows) (hn:root A.leftCount=List.replicate n true) (k:Q.Stack) :\n    data root (E.done n rows).data (occurrenceStack k)=(E.done n rows).data k :=by\n  exact data_occurrence root (E.done n rows).data hr hn k\n/-- Every actual mapped occurrence role has its identical physical source result, including both shared inputs. -/\ntheorem occurrence_preserved (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fixed:List (Fin (SemiprimePublicAcquiredExecution.wireCount (bitValue bits))×Bool)) (tail:List Bool) (k:Q.Stack) :\n    (done bits hN fixed tail).data (occurrenceStack k)=(occurrenceDone bits hN fixed).data k :=by\n  exact final_projection (R.done bits hN fixed tail).data (rootn bits hN fixed) (rootrows bits hN fixed)\n    (root_output bits hc hN fixed tail) (root_number bits hc hN fixed tail) k\n/-- Entire exact original factor-major/local-slot compact owner/factor-key stream is acquired from N alone. -/\ntheorem output_original (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fixed:List (Fin (SemiprimePublicAcquiredExecution.wireCount (bitValue bits))×Bool)) (tail:List Bool) :\n    (done bits hN fixed tail).data output=SemiprimeD1StackOwnerLookup.records\n      (O.originalPairsFrom (G.net bits hN fixed).leftCount 0 (G.net bits hN fixed).rows) [] :=by\n  rw [show output=occurrenceStack .output from rfl,occurrence_preserved bits hc hN fixed tail]\n  exact O.output_original (G.net bits hN fixed)\n/-- Every original factor, including an empty one, is physically counted during the acquired row prescan. -/\ntheorem factor_count (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fixed:List (Fin (SemiprimePublicAcquiredExecution.wireCount (bitValue bits))×Bool)) (tail:List Bool) :\n    (done bits hN fixed tail).data (occurrenceStack .factors)=List.replicate (G.net bits hN fixed).rows.length true :=by\n  rw [occurrence_preserved bits hc hN fixed tail]\n  exact O.factor_count (G.net bits hN fixed)\n/-- Every original local occurrence pushes its own marker, retaining repeated owner values. -/\ntheorem occurrence_count (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fixed:List (Fin (SemiprimePublicAcquiredExecution.wireCount (bitValue bits))×Bool)) (tail:List Bool) :\n    (done bits hN fixed tail).data (occurrenceStack .occurrences)=List.replicate (G.net bits hN fixed).rows.flatten.length true :=by\n  rw [occurrence_preserved bits hc hN fixed tail]\n  exact O.occurrence_count (G.net bits hN fixed)\n/-- One actual original-N execution returns exact original occurrence keys, F and M under its own complete bound. -/\ntheorem source_original (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    ∃q≤SemiprimeD1StackRootSourceOccurrencesBounds.runBound bits,\n      SemiprimeD1StackCalls.run program q (initial bits)=some (done bits hN [] []) ∧\n      (done bits hN [] []).data output=SemiprimeD1StackOwnerLookup.records\n        (O.originalPairsFrom (G.net bits hN []).leftCount 0 (G.net bits hN []).rows) [] ∧\n      (done bits hN [] []).data (occurrenceStack .factors)=List.replicate (G.net bits hN []).rows.length true ∧\n      (done bits hN [] []).data (occurrenceStack .occurrences)=List.replicate (G.net bits hN []).rows.flatten.length true :=by\n  obtain ⟨q,hq,hr⟩:=SemiprimeD1StackRootSourceOccurrencesBounds.source_run_bounded bits hc hN\n  exact ⟨q,hq,hr,output_original bits hc hN [] [],factor_count bits hc hN [] [],occurrence_count bits hc hN [] []⟩\n/-- Fixed coefficient/degree precede ALLcanonicalN for this SAMEliteral complete occurrence source and clock. -/\ntheorem uniform_original :∃coef degree:Nat,∀(bits:List Bool)\n    (_hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits),\n    ∃q≤coef*(SemiprimeMacroParameters.bitLength (bitValue bits)+1)^degree*\n      2^(114*SemiprimeMacroParameters.scopeBound (SemiprimeMacroParameters.bitLength (bitValue bits))),\n      SemiprimeD1StackCalls.run program q (initial bits)=some (done bits hN [] []) ∧\n      (done bits hN [] []).data output=SemiprimeD1StackOwnerLookup.records\n        (O.originalPairsFrom (G.net bits hN []).leftCount 0 (G.net bits hN []).rows) [] :=by\n  obtain ⟨coef,degree,hs⟩:=SemiprimeD1StackRootSourceOccurrencesResources.source_run_monomial\n  refine ⟨coef,degree,?_⟩\n  intro bits hc hN\n  obtain ⟨q,hq,hr⟩:=hs bits hc hN\n  have hw:=SemiprimeD1BinaryDigitAcquisitionBounds.canonical_width bits hc\n  refine ⟨q,?_,hr,output_original bits hc hN [] []⟩\n  simpa only [SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity,hw] using hq\n/-- Genuine finite-machine certificate starts at true Turing.initList on binary N alone. -/\nnoncomputable def machineOriginal (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    StateTransition.EvalsToInTime machine.step (Turing.initList machine bits)\n      (some (SemiprimeD1StackCalls.configuration (done bits hN [] [])))\n      (SemiprimeD1StackRootSourceOccurrencesBounds.runBound bits) :=\n  SemiprimeD1StackRootSourceOccurrencesResources.occurrencesInTime bits hc hN\nend RiemannGaussian.SemiprimeD1StackRootSourceOccurrencesOriginal\n","RiemannGaussian.SemiprimeD1StackRootSourceOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootSourceExecution\n/-! # Literal original root and normalization syntax from original input\nAll exponent identities are derived from the actual acquired word/cache LENGTHS.\nNo expected exponent, normalizer value or supplied expression is assumed.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1000000\nset_option synthInstance.maxSize 4096\nnamespace RiemannGaussian.SemiprimeD1StackRootSourceOriginal\nopen SemiprimeD1StackRootSources SemiprimeD1StackRootSourceExecution\nopen SemiprimeBitArithmetic SemiprimeMacroParameters SemiprimeMacroEntryBitCheck\n/-- Actual completed public cache, obtained by the same N-only call. -/\ndef actualCache (bits : List Bool) : P.Stack→List Bool := SemiprimeD1BinaryPublicAcquisitionComponents.result bits\n/-- The actual modulus has exactly radius+1 physical cells. -/\ntheorem modulus_length (bits : List Bool) :\n    (actualCache bits modulusKey).length=transformLength bits.length+1 := by\n  change (SemiprimeD1StackFermatWords.modulusWord (transformLength bits.length)).length=_\n  have hp : 0<transformLength bits.length := by unfold transformLength;positivity\n  simp only [SemiprimeD1StackFermatWords.modulusWord,List.length_cons,List.length_append,List.length_replicate,List.length_nil]\n  omega\n/-- Actual acquired exponent-cache length, rather than its numeric word value. -/\ntheorem exponent_length (bits : List Bool) :\n    (actualCache bits exponentKey).length=transformExponent bits.length := by\n  change (List.replicate (transformExponent bits.length) true).length=_\n  exact List.length_replicate\n/-- Both exponents are lengths of marker streams ACTUALLY produced by physical pops. -/\ntheorem marker_lengths (bits : List Bool) :\n    (rootMarkers (actualCache bits)).length=transformLength bits.length-1 ∧\n    (normalMarkers (actualCache bits)).length=transformLength bits.length-transformExponent bits.length := by\n  simp only [rootMarkers,normalMarkers,List.length_tail,List.length_drop,modulus_length,exponent_length]\n  omega\n/-- Positive canonical original N identifies physical radius/exponent with the\nactual public configuration, including depth+1 rather than an advised exponent. -/\ntheorem original_parameters (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits)\n    (hN : 0<bitValue bits) :\n    let config:=SemiprimePublicFactorCount.publicConfig (bitValue bits) hN\n    transformLength bits.length=config.r*config.t ∧ transformExponent bits.length=config.depth+1 := by\n  have hw:=SemiprimeD1BinaryDigitAcquisitionBounds.canonical_width bits hc\n  have hp:=transformExponent_ge_two (bitLength_pos hN)\n  dsimp [SemiprimePublicFactorCount.publicConfig]\n  rw [hw,axes_product]\n  constructor\n  · rfl\n  · unfold macroDepth;omega\n/-- Literal forward root code, acquired only by nine fixed physical pushes. -/\ntheorem forward_root (bits : List Bool) (hN : 0<bitValue bits) (side : Fin 2) :\n    (done bits).data (.inr .forwardRoot)=SemiprimeD1StackExprCodec.encode\n      (rootExpr (SemiprimePublicFactorCount.publicConfig (bitValue bits) hN) (.inl side)) [] := rfl\n/-- Literal forward normalization code, acquired by five fixed physical pushes. -/\ntheorem forward_normalization (bits : List Bool) (hN : 0<bitValue bits) (side : Fin 2) :\n    (done bits).data (.inr .forwardNormal)=SemiprimeD1StackExprCodec.encode\n      (normalizationExpr (SemiprimePublicFactorCount.publicConfig (bitValue bits) hN) (.inl side)) [] := rfl\n/-- EXACT old inverse rootExpr bytes. Actual marker acquisition is modulus-WORD\ncopy/drop, never evaluation or scanning of the numeric modulus VALUE. -/\ntheorem inverse_root (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits)\n    (hN : 0<bitValue bits) :\n    (done bits).data (.inr .root)=SemiprimeD1StackExprCodec.encode\n      (rootExpr (SemiprimePublicFactorCount.publicConfig (bitValue bits) hN) (.inr ())) [] := by\n  have hm:=(marker_lengths bits).1\n  have hp:=(original_parameters bits hc hN).1\n  change SemiprimeD1StackExprPowerSpec.result (rootMarkers (actualCache bits)).length\n    (SemiprimeD1StackExprCodec.encode fourExpr []) []=_\n  rw [SemiprimeD1StackExprPowerSpec.result_original,hm,hp]\n  rfl\n/-- EXACT old inverse normalizationExpr bytes: actual paired marker pops,\nPower(twoExpr), then literal zero/subtraction pushes. No semantic substitution. -/\ntheorem inverse_normalization (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits)\n    (hN : 0<bitValue bits) :\n    (done bits).data (.inr .normal)=SemiprimeD1StackExprCodec.encode\n      (normalizationExpr (SemiprimePublicFactorCount.publicConfig (bitValue bits) hN) (.inr ())) [] := by\n  have hm:=(marker_lengths bits).2\n  have hp:=original_parameters bits hc hN\n  change [true,false,false,false,false]++SemiprimeD1StackExprPowerSpec.result\n    (normalMarkers (actualCache bits)).length (SemiprimeD1StackExprCodec.encode twoExpr []) []=_\n  rw [SemiprimeD1StackExprPowerSpec.result_original,hm,hp.1,hp.2]\n  rfl\n/-- All original N, digit-bank, modulus, normalizer and geometry caches survive. -/\ntheorem retained_public (bits : List Bool) (k : P.Stack) :\n    (done bits).data (.inl k)=actualCache bits k := rfl\n/-- Source construction work/markers/base caches are physically cleared. -/\ntheorem cleanup (bits : List Bool) (k : Aux)\n    (hk : k≠.root ∧ k≠.normal ∧ k≠.forwardRoot ∧ k≠.forwardNormal) :\n    (done bits).data (.inr k)=[] := by cases k <;> simp_all [done,result,store,aux]\nend RiemannGaussian.SemiprimeD1StackRootSourceOriginal\n","RiemannGaussian.SemiprimeD1StackSelectedDescriptorRecordBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSelectedDescriptorRecordExecution\n/-! # Complete physical selector/template/record clock and every actual prefix -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1600000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackSelectedDescriptorRecordBounds\nopen SemiprimeD1StackSelectedDescriptorRecord SemiprimeD1StackSelectedDescriptorRecordExecution\nopen SemiprimeD1StackStaticTableSpec (CheckerTrace)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nvariable {K L : Type} [DecidableEq K] [Fintype K] (s : T.Static K L) (sourceMap : K→Option (Fin 6))\n/-- Every actual input word, old template and old selector is charged. -/\ndef inputSize (oldTemplate : K→List Bool) (raw : Fin 6→List Bool)\n    (oldStage oldInverse bank hist out : List Bool) : Nat :=\n  ∑k:Stack K,((initial s oldTemplate raw oldStage oldInverse bank hist out).data k).length\n/-- The same complete actual source clock: real selector computation and all\nmetadata loading/table/serializer/logger work, physical gate and calls/returns. -/\ndef runBound (oldTemplate : K→List Bool) (raw : Fin 6→List Bool) (second inverse : Bool)\n    (words : List (List Bool)) (budget : Nat→Nat) (M : Nat)\n    (oldStage oldInverse hist out : List Bool) : Nat :=\n  SemiprimeD1StackTransformSelectorsExecution.timeBound (raw 1) (raw 2) oldStage oldInverse+\n    SemiprimeD1StackDescriptorRecordBounds.runBound s sourceMap oldTemplate (fields raw [second] [inverse])\n      words budget M hist out+4\nomit [DecidableEq K] in\n/-- No native checker report, mode evaluator or metadata-size advice enters this bound. -/\ntheorem timeBound_le (oldTemplate : K→List Bool) (raw : Fin 6→List Bool) (second inverse : Bool)\n    (words : List (List Bool)) (answer : List Bool→Bool) (budget : Nat→Nat) (M : Nat)\n    (oldStage oldInverse hist out : List Bool)\n    (hl : ∀w∈words,w.length≤M) (hv : ∀w∈words,SemiprimeBitArithmetic.bitValue w≤M) :\n    timeBound s sourceMap oldTemplate raw second inverse words answer budget oldStage oldInverse hist out≤\n      runBound s sourceMap oldTemplate raw second inverse words budget M oldStage oldInverse hist out :=by\n  have h:=SemiprimeD1StackDescriptorRecordBounds.timeBound_le s sourceMap oldTemplate (fields raw [second] [inverse])\n    words answer budget M hist out hl hv\n  unfold timeBound runBound\n  omega\n/-- A successful same-source halt bounds all successful executed prefixes. -/\ntheorem prefix_fuel_le (oldTemplate : K→List Bool) (raw : Fin 6→List Bool)\n    (tagCode : Fin 18) (trCode : Fin 3) (second : Bool)\n    (htag : raw 1=List.replicate tagCode.val true) (htr : raw 2=List.replicate trCode.val true)\n    (hcode : SemiprimeD1StackTransformSelectors.tagDispatch tagCode=.copyTransform second)\n    (hraw : SemiprimeD1StackDescriptorRecord.selected sourceMap (fields raw [second] [trCode.val==2]) s.raw=[])\n    (answer : List Bool→Bool) (budget : Nat→Nat)\n    (hc : CheckerTrace s (SemiprimeD1StackDescriptorRecord.selected sourceMap (fields raw [second] [trCode.val==2])) answer budget)\n    (words : List (List Bool)) (oldStage oldInverse hist out : List Bool) (fuel : Nat)\n    (finish : C.State (Stack K) (Label L s.roles.length))\n    (hr : C.run (program s sourceMap) fuel (initial s oldTemplate raw oldStage oldInverse (vectorBits words) hist out)=some finish) :\n    fuel≤timeBound s sourceMap oldTemplate raw second (trCode.val==2) words answer budget oldStage oldInverse hist out :=by\n  obtain ⟨t,ht,he⟩:=source_run s sourceMap oldTemplate raw tagCode trCode second htag htr hcode hraw answer budget hc\n    words oldStage oldInverse hist out\n  have hf:fuel≤t:=by\n    by_contra hn\n    have h:fuel=t+(1+(fuel-(t+1))):=by omega\n    rw [h,SemiprimeD1StackReturnLink.run_add,he,Option.bind_some,SemiprimeD1StackReturnLink.run_add] at hr\n    have hz:C.run (program s sourceMap) 1 (done s sourceMap raw second (trCode.val==2) words answer hist out)=none:=rfl\n    rw [hz,Option.bind_none] at hr\n    cases hr\n  exact hf.trans ht\n/-- All2K+42 roles, every alias shadow, both original copied fields, all source\nwords, real selector cells, template banks and ACTUAL nested return cells. -/\ntheorem prefix_cells (oldTemplate : K→List Bool) (raw : Fin 6→List Bool)\n    (tagCode : Fin 18) (trCode : Fin 3) (second : Bool)\n    (htag : raw 1=List.replicate tagCode.val true) (htr : raw 2=List.replicate trCode.val true)\n    (hcode : SemiprimeD1StackTransformSelectors.tagDispatch tagCode=.copyTransform second)\n    (hraw : SemiprimeD1StackDescriptorRecord.selected sourceMap (fields raw [second] [trCode.val==2]) s.raw=[])\n    (answer : List Bool→Bool) (budget : Nat→Nat)\n    (hc : CheckerTrace s (SemiprimeD1StackDescriptorRecord.selected sourceMap (fields raw [second] [trCode.val==2])) answer budget)\n    (words : List (List Bool)) (oldStage oldInverse hist out : List Bool) (fuel : Nat)\n    (finish : C.State (Stack K) (Label L s.roles.length))\n    (hr : C.run (program s sourceMap) fuel (initial s oldTemplate raw oldStage oldInverse (vectorBits words) hist out)=some finish) :\n    (∑k:Stack K,(finish.data k).length)+finish.frames.length≤\n      (2*Fintype.card K+43)*(inputSize s oldTemplate raw oldStage oldInverse (vectorBits words) hist out+\n        timeBound s sourceMap oldTemplate raw second (trCode.val==2) words answer budget oldStage oldInverse hist out+1) :=by\n  have hi (k : Stack K) : ((initial s oldTemplate raw oldStage oldInverse (vectorBits words) hist out).data k).length≤\n      inputSize s oldTemplate raw oldStage oldInverse (vectorBits words) hist out:=by\n    unfold inputSize\n    exact Finset.single_le_sum\n      (f:=fun k:Stack K=>((initial s oldTemplate raw oldStage oldInverse (vectorBits words) hist out).data k).length)\n      (fun _ _=>Nat.zero_le _) (Finset.mem_univ k)\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound (program s sourceMap) fuel\n    (inputSize s oldTemplate raw oldStage oldInverse (vectorBits words) hist out) _ finish hi hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound (program s sourceMap) fuel _ finish hr\n  change finish.frames.length≤0+fuel at hf\n  have hs:(∑k:Stack K,(finish.data k).length)≤\n      (2*Fintype.card K+42)*(inputSize s oldTemplate raw oldStage oldInverse (vectorBits words) hist out+fuel):=by\n    calc\n      _≤∑_k:Stack K,(inputSize s oldTemplate raw oldStage oldInverse (vectorBits words) hist out+fuel):=\n        Finset.sum_le_sum (fun k _=>hd k)\n      _= _:=by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  have ht:=prefix_fuel_le s sourceMap oldTemplate raw tagCode trCode second htag htr hcode hraw answer budget hc\n    words oldStage oldInverse hist out fuel finish hr\n  nlinarith\n/-- Same complete prefix inventory for the actual compiled finite machine. -/\ntheorem machine_prefix_cells [Fintype L] (oldTemplate : K→List Bool) (raw : Fin 6→List Bool)\n    (tagCode : Fin 18) (trCode : Fin 3) (second : Bool)\n    (htag : raw 1=List.replicate tagCode.val true) (htr : raw 2=List.replicate trCode.val true)\n    (hcode : SemiprimeD1StackTransformSelectors.tagDispatch tagCode=.copyTransform second)\n    (hraw : SemiprimeD1StackDescriptorRecord.selected sourceMap (fields raw [second] [trCode.val==2]) s.raw=[])\n    (answer : List Bool→Bool) (budget : Nat→Nat)\n    (hc : CheckerTrace s (SemiprimeD1StackDescriptorRecord.selected sourceMap (fields raw [second] [trCode.val==2])) answer budget)\n    (words : List (List Bool)) (oldStage oldInverse hist out : List Bool) (fuel : Nat) (cfg : (machine s sourceMap).Cfg)\n    (hr : (fun q=>q.bind (machine s sourceMap).step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial s oldTemplate raw oldStage oldInverse (vectorBits words) hist out)))=some cfg) :\n    (∑k:Stack K,(cfg.stk (some k)).length)+(cfg.stk none).length≤\n      (2*Fintype.card K+43)*(inputSize s oldTemplate raw oldStage oldInverse (vectorBits words) hist out+\n        timeBound s sourceMap oldTemplate raw second (trCode.val==2) words answer budget oldStage oldInverse hist out+1) :=by\n  have he:=SemiprimeD1StackCalls.run_correct (rawSource 0) output (.inl .start) (program s sourceMap) fuel\n    (initial s oldTemplate raw oldStage oldInverse (vectorBits words) hist out)\n  have hh:(C.run (program s sourceMap) fuel (initial s oldTemplate raw oldStage oldInverse (vectorBits words) hist out)).map\n    SemiprimeD1StackCalls.configuration=some cfg:=he.trans hr\n  cases hrun:C.run (program s sourceMap) fuel (initial s oldTemplate raw oldStage oldInverse (vectorBits words) hist out) with\n  | none=>rw [hrun] at hh;cases hh\n  | some finish=>\n    rw [hrun] at hh\n    have heq:SemiprimeD1StackCalls.configuration finish=cfg:=Option.some.inj hh\n    subst cfg\n    exact prefix_cells s sourceMap oldTemplate raw tagCode trCode second htag htr hcode hraw answer budget hc\n      words oldStage oldInverse hist out fuel finish hrun\nend RiemannGaussian.SemiprimeD1StackSelectedDescriptorRecordBounds\n","RiemannGaussian.SemiprimeD1StackSourceIncidenceInner":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceIncidenceParse\nimport RiemannGaussian.SemiprimeD1StackSourceIncidenceAddition\n/-! # Actual complete inner occurrence scan, every repeated term and final false tag -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceIncidenceInner\nopen SemiprimeD1StackSourceIncidence SemiprimeD1StackSourceIncidenceEncoding\nopen SemiprimeD1StackSourceIncidencePrimitives SemiprimeD1StackSourceIncidenceLoopView\nopen SemiprimeD1StackSourceIncidenceParse SemiprimeD1StackSourceIncidenceAddition\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeBitArithmetic (addBits)\nnamespace Spec\nexport SemiprimeD1StackSourceIncidenceSpec (inner term)\nend Spec\n/-- Proof-side complete actual inner clock; its accumulator follows real binary additions. -/\ndef innerClock (i:Inputs) (lo lf:List Bool) :List (List Bool×List Bool)→List Bool→Nat\n  | [],_=>1\n  | (ro,rf)::rows,acc=>8*(ro.length+rf.length)+17+pairClock i lo lf ro rf acc+\n      innerClock i lo lf rows (addBits acc (Spec.term i.ids i.square i.cube i.fourth (lo,lf) (ro,rf)) false).bits\n/-- Complete actual byte scan processes every ordered inner incidence, including diagonals and duplicates. -/\ntheorem inner_run (i:Inputs) (outer lo lf:List Bool) (rows:List (List Bool×List Bool)) (acc:List Bool) :\n    ∃ q ≤ innerClock i lo lf rows acc,\n      Runs program q .innerHeader (bank i outer (Records.records rows []) lo lf [] [] [] [] [] [] acc)\n        .innerEOF (bank i outer [] lo lf [] [] [] [] [] [] (Spec.inner i.ids i.square i.cube i.fourth (lo,lf) rows acc)) :=by\n  induction rows generalizing acc with\n  | nil=>\n    have h:=pop_run .innerHeader .abort .innerEOF (.parse true .owner) (aux .innerReader)\n      (bank i outer (Records.records [] []) lo lf [] [] [] [] [] [] acc) [false] rfl rfl\n    change Runs program 1 _ _ _ (Function.update (bank i outer (Records.records [] []) lo lf [] [] [] [] [] [] acc)\n      (aux .innerReader) []) at h\n    rw [update_inner] at h\n    exact ⟨1,le_rfl,h⟩\n  | cons row rows ih=>\n    rcases row with ⟨ro,rf⟩\n    have h0:=read_inner i outer lo lf ro rf acc rows\n    obtain ⟨q,hq,h1⟩:=pair_run i outer (Records.records rows []) lo lf ro rf acc\n    obtain ⟨u,hu,h2⟩:=ih (addBits acc (Spec.term i.ids i.square i.cube i.fourth (lo,lf) (ro,rf)) false).bits\n    refine ⟨_,?_,join (join h0 h1) h2⟩\n    dsimp only [innerClock]\n    omega\n/-- The final false tag has been consumed; the real EOF peek checks its unread physical tail before cleanup. -/\ntheorem inner_finish (i:Inputs) (outer lo lf acc:List Bool) :\n    Runs program 1 .innerEOF (bank i outer [] lo lf [] [] [] [] [] [] acc)\n      (.clearKey false .owner) (bank i outer [] lo lf [] [] [] [] [] [] acc) :=by\n  exact peek_run .innerEOF (.clearKey false .owner) .abort .abort (aux .innerReader)\n    (bank i outer [] lo lf [] [] [] [] [] [] acc) [] rfl rfl\nend RiemannGaussian.SemiprimeD1StackSourceIncidenceInner\n","RiemannGaussian.SemiprimeD1StackSourceIncidencePrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceIncidence\n/-! # Real preserving copy and literal incidence-query operations -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceIncidencePrimitives\nopen SemiprimeD1StackSourceIncidence\nopen SemiprimeD1StackProcedureTrace\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel data_update)\nend Link\n/-- Same literal program trace fragments compose with arbitrary actual caller return cells. -/\ntheorem join {m n:Nat} {pc mid finish:Label} {before between after:Stack→List Bool}\n    (h:Runs program m pc before mid between) (g:Runs program n mid between finish after) :\n    Runs program (m+n) pc before finish after :=runs_trans program _ _ _ _ _ _ _ _ h g\n/-- Every paid preserving-copy call changes only its actual destination. -/\ntheorem copy_call (part:Copy) (pc next:Label) (hc:program pc=.call (.copier part 0) next)\n    (bank:Stack→List Bool) (hd:bank (copyStack part 1)=[]) (hs:bank (copyStack part 2)=[]) :\n    Runs program (5*(bank (copyStack part 0)).length+4) pc bank next\n      (Function.update bank (copyStack part 1) (bank (copyStack part 0))) :=by\n  let before:=SemiprimeD1StackCopy.state 0 none (bank (copyStack part 0)) [] []\n  let after:=SemiprimeD1StackCopy.done (bank (copyStack part 0)) (bank (copyStack part 0)++[])\n  have hin:Link.DataRel (copyStack part) bank before.store bank:=by\n    constructor\n    · intro i;fin_cases i\n      · rfl\n      · exact hd\n      · exact hs\n    · intro k _;rfl\n  apply included_call program (copyStack part) (Label.copier part) (copy_injective part)\n    SemiprimeD1StackCopy.code 0 (fun _=>rfl) pc next hc (5*(bank (copyStack part 0)).length+3)\n    before after _ _ rfl rfl (SemiprimeD1StackCopy.copy_words _ [] none) hin\n  have h:=Link.data_update (copyStack part) (copy_injective part) bank before.store bank hin 1 (bank (copyStack part 0))\n  have he:Function.update before.store 1 (bank (copyStack part 0))=after.store:=by\n    dsimp only [after]\n    rw [List.append_nil]\n    funext i;fin_cases i <;> rfl\n  simpa only [he] using h\n/-- One literal local push preserves the entire other physical bank and all real outer returns. -/\ntheorem push_run (pc:Label) (next:Label) (k:Stack) (b:Bool) (before:Stack→List Bool)\n    (hc:program pc=.base (.push k b next)) :\n    Runs program 1 pc before next (Function.update before k (b::before k)) :=\n  one_base program _ _ _ _ _ hc rfl rfl\n/-- One literal local pop consumes ONLYthe actual physical Boolean head. -/\ntheorem pop_run (pc:Label) (empty low high:Label) (k:Stack) (before:Stack→List Bool) (xs:List Bool)\n    (hc:program pc=.base (.pop k empty low high)) (hx:before k=xs) :\n    Runs program 1 pc before (SemiprimeD1StackBytecode.choose empty low high xs.head?) (Function.update before k xs.tail) :=by\n  apply one_base program pc _ (.pop k empty low high) before _ hc\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n/-- Real EOF peek does not silently discard any remaining singleton-result bytes. -/\ntheorem peek_run (pc:Label) (empty low high:Label) (k:Stack) (before:Stack→List Bool) (xs:List Bool)\n    (hc:program pc=.base (.peek k empty low high)) (hx:before k=xs) :\n    Runs program 1 pc before (SemiprimeD1StackBytecode.choose empty low high xs.head?) before :=by\n  apply one_base program pc _ (.peek k empty low high) before before hc\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n  · rfl\n/-- Every table/key/owner/row cleanup actually visits every byte and its final empty branch. -/\ntheorem drain_loop (pc:Label) (next:Label) (k:Stack)\n    (hc:program pc=.base (.pop k next pc pc)) (before:Stack→List Bool) (xs:List Bool) (hx:before k=xs) :\n    Runs program (xs.length+1) pc before next (Function.update before k []) :=by\n  induction xs generalizing before with\n  | nil=>exact pop_run pc next pc pc k before [] hc hx\n  | cons b xs ih=>\n    have h0:=pop_run pc next pc pc k before (b::xs) hc hx\n    have h1:=ih (Function.update before k xs) (Function.update_self _ _ _)\n    have hh:=join (by cases b <;> exact h0) h1\n    simpa only [List.length_cons,Function.update_idem,Nat.add_assoc,Nat.add_comm,Nat.add_left_comm] using hh\n/-- Actual four-role numeric equality consumes both copied operands and physically writes its comparison bit. -/\ntheorem equal_call (pc next:Label) (hc:program pc=.call (.equality .loop) next)\n    (bank:Stack→List Bool) (hs:bank (aux .eqScratch)=[]) (ho:bank (aux .eqOutput)=[]) :\n    Runs program (SemiprimeD1StackWordEqualExecution.executionTime (bank (aux .eqLeft)) (bank (aux .eqRight))+1)\n      pc bank next (Function.update (Function.update (Function.update bank (aux .eqLeft) []) (aux .eqRight) [])\n        (aux .eqOutput) [decide (SemiprimeBitArithmetic.bitValue (bank (aux .eqLeft))=\n          SemiprimeBitArithmetic.bitValue (bank (aux .eqRight)))]) :=by\n  let left:=bank (aux .eqLeft)\n  let right:=bank (aux .eqRight)\n  let before:=SemiprimeD1StackWordEqual.state (some .loop) none left right []\n  let after:=SemiprimeD1StackWordEqual.state none none [] []\n    [decide (SemiprimeBitArithmetic.bitValue left=SemiprimeBitArithmetic.bitValue right)]\n  have hin:Link.DataRel equalStack bank before.store bank:=by\n    constructor\n    · intro k;cases k\n      · rfl\n      · rfl\n      · exact hs\n      · exact ho\n    · intro k _;rfl\n  have h0:=Link.data_update equalStack equal_injective bank before.store bank hin (.left:A.Stack) []\n  have h1:=Link.data_update equalStack equal_injective bank _ _ h0 (.right:A.Stack) []\n  have h2:=Link.data_update equalStack equal_injective bank _ _ h1 (.output:A.Stack)\n    [decide (SemiprimeBitArithmetic.bitValue left=SemiprimeBitArithmetic.bitValue right)]\n  have he:Function.update (Function.update (Function.update before.store (.left:A.Stack) []) (.right:A.Stack) [])\n      (.output:A.Stack) [decide (SemiprimeBitArithmetic.bitValue left=SemiprimeBitArithmetic.bitValue right)]=after.store:=by\n    funext k;cases k <;> rfl\n  rw [he] at h2\n  exact included_call program equalStack Label.equality equal_injective Q.code .loop (fun _=>rfl) pc next hc\n    (SemiprimeD1StackWordEqualExecution.executionTime left right) before after bank _ rfl rfl\n    (SemiprimeD1StackWordEqualExecution.source_run left right none) hin h2\n/-- Actual ripple addition consumes its copied total and actual selected term, with no supplied result. -/\ntheorem add_call (bank:Stack→List Bool) (hs:bank (aux .sumScratch)=[]) (ho:bank (aux .total)=[]) :\n    Runs program (3*(max (bank (aux .sumLeft)).length (bank (aux .term)).length+1)+\n      2*(SemiprimeBitArithmetic.addBits (bank (aux .sumLeft)) (bank (aux .term)) false).bits.length+3)\n      .add bank (.clearKey true .owner)\n      (Function.update (Function.update (Function.update bank (aux .sumLeft) []) (aux .term) [])\n        (aux .total) (SemiprimeBitArithmetic.addBits (bank (aux .sumLeft)) (bank (aux .term)) false).bits) :=by\n  let left:=bank (aux .sumLeft)\n  let right:=bank (aux .term)\n  let before:=SemiprimeD1StackAdder.state (some (.start false)) none left right [] []\n  let after:=SemiprimeD1StackAdder.state none none [] [] [] (SemiprimeBitArithmetic.addBits left right false).bits\n  have hin:Link.DataRel addStack bank before.store bank:=by\n    constructor\n    · intro k;cases k\n      · rfl\n      · rfl\n      · exact hs\n      · exact ho\n    · intro k _;rfl\n  have h0:=Link.data_update addStack add_injective bank before.store bank hin (.left:A.Stack) []\n  have h1:=Link.data_update addStack add_injective bank _ _ h0 (.right:A.Stack) []\n  have h2:=Link.data_update addStack add_injective bank _ _ h1 (.output:A.Stack) (SemiprimeBitArithmetic.addBits left right false).bits\n  have he:Function.update (Function.update (Function.update before.store (.left:A.Stack) []) (.right:A.Stack) [])\n      (.output:A.Stack) (SemiprimeBitArithmetic.addBits left right false).bits=after.store:=by\n    funext k;cases k <;> rfl\n  rw [he] at h2\n  exact included_call program addStack Label.adder add_injective A.code (.start false) (fun _=>rfl)\n    .add (.clearKey true .owner) rfl\n    (3*(max left.length right.length+1)+2*(SemiprimeBitArithmetic.addBits left right false).bits.length+2)\n    before after bank _ rfl rfl (SemiprimeD1StackAdderExecution.source_run left right false) hin h2\n/-- Physical field parsing consumes each endpoint frame and produces a real validity singleton. -/\ntheorem parse_call (inner:Bool) (kind:Edge) (bank:Stack→List Bool) (word tail:List Bool)\n    (hi:bank (fieldStack inner kind (.inl .input))=SemiprimeSourceHistogramKeyBits.frame word tail)\n    (ho:bank (key inner kind)=[]) (hs:bank (aux .fieldScratch)=[]) (hv:bank (aux .valid)=[]) :\n    Runs program (8*word.length+7) (.parse inner kind) bank (.valid inner kind)\n      (Function.update (Function.update (Function.update bank (fieldStack inner kind (.inl .input)) tail)\n        (key inner kind) word) (aux .valid) [true]) :=by\n  let before:=SemiprimeD1TensorTapeFieldBytecode.initial (SemiprimeSourceHistogramKeyBits.frame word tail) []\n  let after:SemiprimeD1StackBytecode.State Field.Stack Field.Label:=\n    ⟨none,none,Sum.elim (SemiprimeD1TensorTapeFieldMachine.contents tail [] word) (fun _=>[true])⟩\n  have hin:Link.DataRel (fieldStack inner kind) bank before.store bank:=by\n    constructor\n    · intro k;rcases k with k|k\n      · cases k\n        · exact hi\n        · exact hs\n        · exact ho\n      · cases k;exact hv\n    · intro k _;rfl\n  have h0:=Link.data_update (fieldStack inner kind) (field_injective inner kind) bank before.store bank hin (.inl .input) tail\n  have h1:=Link.data_update (fieldStack inner kind) (field_injective inner kind) bank _ _ h0 (.inl .output) word\n  have h2:=Link.data_update (fieldStack inner kind) (field_injective inner kind) bank _ _ h1 (.inr ()) [true]\n  have he:Function.update (Function.update (Function.update before.store (.inl .input) tail) (.inl .output) word)\n      (.inr ()) [true]=after.store:=by funext k;rcases k with k|k <;> cases k <;> rfl\n  rw [he] at h2\n  exact included_call program (fieldStack inner kind) (Label.parser inner kind) (field_injective inner kind)\n    Field.code (Field.active .tagPop (none,false)) (fun _=>rfl) (.parse inner kind) (.valid inner kind) rfl\n    (8*word.length+6) before after bank _ rfl rfl (SemiprimeD1TensorTapeFieldBytecode.framed_run word tail []) hin h2\n/-- Complete real preserving environment lookup, including its own nested calls and actual return. -/\ntheorem lookup_call (kind:Edge) (side:Bool) (bank:Stack→List Bool)\n    (ids:List (List Bool)) (chosen q pfx:List Bool)\n    (hi:∀k,bank (environmentStack k)=(SemiprimeD1StackSourceEnvironmentExecution.lookupReady ids chosen q pfx).data k) :\n    ∃t≤201*(q.length+1)*((SemiprimeD1StackSourceEnvironmentEncoding.dictionary ids).length+1)+1,\n      Runs program t (.lookup kind side) bank (.readFound kind side)\n        (Sum.elim (SemiprimeD1StackSourceEnvironmentExecution.lookupDone ids chosen q pfx).data (fun k=>bank (aux k))) :=by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackSourceEnvironmentExecution.lookup_run ids chosen q pfx\n  refine ⟨t+1,by omega,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program environmentStack Label.environment environment_injective\n    E.program (.local .lookup) (fun _=>rfl) (.lookup kind side) (.readFound kind side) rfl t\n    (SemiprimeD1StackSourceEnvironmentExecution.lookupReady ids chosen q pfx)\n    (SemiprimeD1StackSourceEnvironmentExecution.lookupDone ids chosen q pfx) bank _ rfl rfl rfl rfl hr\n  · constructor\n    · exact hi\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk;rcases k with k|k\n      · exact (hk k rfl).elim\n      · rfl\nend RiemannGaussian.SemiprimeD1StackSourceIncidencePrimitives\n","RiemannGaussian.SemiprimeD1StackSourceSelectedKeysBody":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceSelectedKeysLog\n/-! # Complete actual two-ID lookup, exact joint-key framing and per-occurrence cleanup -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceSelectedKeysBody\nopen SemiprimeD1StackSourceSelectedKeys SemiprimeD1StackSourceSelectedKeysEncoding\nopen SemiprimeD1StackSourceSelectedKeysPrimitives SemiprimeD1StackSourceSelectedKeysView\nopen SemiprimeD1StackSourceSelectedKeysLookup SemiprimeD1StackSourceSelectedKeysLog\nopen SemiprimeD1StackProcedureTrace\n/-- Own actual per-occurrence producer clock; lookup and byte framing, reverse-log and four complete drains all remain paid. -/\ndef bodyTime (i:Inputs) (own fac:List Bool) :Nat :=lookupClock i own+lookupClock i fac+frameTime i own fac+\n  ((readID i.ids own).length+1)+((joint i.ids (own,fac)).length+1)+(own.length+1)+(fac.length+1)\n/-- Both selected IDs are acquired by real calls and a complete exact oldjoint key is physically emitted once. -/\ntheorem body_run (i:Inputs) (reader own fac hist:List Bool)\n    (ho:SemiprimeBitArithmetic.bitValue own < i.ids.length) (hf:SemiprimeBitArithmetic.bitValue fac < i.ids.length) :\n    ∃q≤bodyTime i own fac,Runs program q (.copyQuery .owner) (view i [] [] [] reader own fac [] [] [] [] hist [])\n      .header (view i [] [] [] reader [] [] [] [] [] [] ((chunk i.ids (own,fac)).reverse++hist) []) :=by\n  obtain ⟨q,hq,h0⟩:=owner_run i reader own fac hist ho\n  obtain ⟨t,ht,h1⟩:=factor_run i reader own fac hist hf\n  have h2:=frame_run i reader own fac hist\n  have h3:=clear_run i reader own fac (readID i.ids own) (joint i.ids (own,fac)) ((chunk i.ids (own,fac)).reverse++hist)\n  refine ⟨_,?_,join (join (join h0 h1) h2) h3⟩\n  unfold bodyTime\n  omega\nend RiemannGaussian.SemiprimeD1StackSourceSelectedKeysBody\n","RiemannGaussian.SemiprimeD1StackSourceSelectedKeysBytes":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceSelectedKeysLoop\nimport RiemannGaussian.SemiprimeD1StackSourceIncidenceBytes\n/-! # Selected-key source bounds from actual retained cache/tape/output bytes\nThe imported incidence lemmas concern only literal framing and returned-payload\nsubword lengths. No previous query clock or original report clock is reused.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceSelectedKeysBytes\nopen SemiprimeD1StackSourceSelectedKeys SemiprimeD1StackSourceSelectedKeysEncoding\nopen SemiprimeD1StackSourceSelectedKeysLookup SemiprimeD1StackSourceSelectedKeysLog\nopen SemiprimeD1StackSourceSelectedKeysBody SemiprimeD1StackSourceSelectedKeysLoop\nnamespace Env\nexport SemiprimeD1StackSourceEnvironmentEncoding (dictionary)\nend Env\n/-- Actual normalized selected-ID bytes occur inside the actual acquired marked dictionary. -/\ntheorem readID_length (i:Inputs) (key:List Bool) :(readID i.ids key).length ≤ (Env.dictionary i.ids).length :=\n  SemiprimeD1StackSourceIncidenceBytes.readID_length i.ids key\n/-- Both retained input sources are included in the one actual byte budget. -/\ntheorem basic_bounds (i:Inputs) :(tape i).length ≤ inputSize i ∧ (Env.dictionary i.ids).length ≤ inputSize i :=by\n  unfold inputSize SemiprimeD1StackSourceEnvironmentBounds.cacheSize\n  omega\n/-- One occurrence is charged by its actual pair tag and both endpoint fields, without an externally supplied count. -/\ntheorem occurrence_count_le (i:Inputs) :i.rows.length ≤ inputSize i :=by\n  have ht:=(basic_bounds i).1\n  change (SemiprimeD1StackOwnerLookup.records i.rows []).length ≤ _ at ht\n  rw [SemiprimeD1StackOwnerLookupBounds.records_length] at ht\n  simp only [List.length_nil,Nat.add_zero] at ht\n  omega\n/-- Every parsed endpoint width belongs to its physically supplied occurrence tape. -/\ntheorem endpoint_widths (i:Inputs) (row:List Bool×List Bool) (h:row∈i.rows) :\n    row.1.length ≤ inputSize i ∧ row.2.length ≤ inputSize i :=by\n  have hr:=SemiprimeD1StackSourceIncidenceBytes.record_width_le row i.rows h\n  have ht:=(basic_bounds i).1\n  change (SemiprimeD1StackOwnerLookup.records i.rows []).length ≤ _ at ht\n  omega\n/-- Joint-key width includes its actual single owner-field delimiter and rawfactor-ID tail. -/\ntheorem joint_length (i:Inputs) (row:List Bool×List Bool) :(joint i.ids row).length ≤ 3*inputSize i+1 :=by\n  have h0:=(readID_length i row.1).trans (basic_bounds i).2\n  have h1:=(readID_length i row.2).trans (basic_bounds i).2\n  unfold joint\n  rw [SemiprimeSourceHistogramKeyBits.frame_length]\n  omega\n/-- Complete vector-row width includes its actual true tag and enclosing fullkey frame. -/\ntheorem chunk_length (i:Inputs) (row:List Bool×List Bool) :(chunk i.ids row).length ≤ 6*inputSize i+4 :=by\n  have h:=joint_length i row\n  unfold chunk\n  rw [List.length_cons,SemiprimeSourceHistogramKeyBits.frame_length,List.length_nil]\n  omega\n/-- Full reversed-log size is derived internally from every actual occurrence's physical vector-row bytes. -/\ntheorem stream_length (i:Inputs) (rows:List (List Bool×List Bool)) :\n    (stream i.ids rows).length ≤ rows.length*(6*inputSize i+4) :=by\n  induction rows with\n  | nil=>simpa only [stream,List.foldr_nil,List.length_nil,Nat.zero_mul] using (Nat.le_refl 0)\n  | cons row rows ih=>\n    have h:=chunk_length i row\n    change (chunk i.ids row++stream i.ids rows).length ≤ _\n    rw [List.length_append,List.length_cons,Nat.add_mul,Nat.one_mul]\n    omega\n/-- Each real preserving lookup/copy/ID-save/drain stage has its own input-byte quadratic clock. -/\ntheorem lookupClock_le (i:Inputs) (word:List Bool) (hw:word.length ≤ inputSize i) :\n    lookupClock i word ≤ 2000*(inputSize i)^2 :=by\n  have hD:=(basic_bounds i).2\n  have hID:=(readID_length i word).trans hD\n  have hS:=inputSize_pos i\n  have hm:=Nat.mul_le_mul (show word.length+1 ≤ inputSize i+1 by omega)\n    (show (Env.dictionary i.ids).length+1 ≤ inputSize i+1 by omega)\n  unfold lookupClock\n  nlinarith only [hw,hD,hID,hS,hm]\n/-- Both actual frames and the actual row reversal cost at most a fixed multiple of the physical input byte budget. -/\ntheorem frameTime_le (i:Inputs) (own fac:List Bool) :frameTime i own fac ≤ 100*inputSize i :=by\n  have ho:=(readID_length i own).trans (basic_bounds i).2\n  have hj:=joint_length i (own,fac)\n  have hc:=chunk_length i (own,fac)\n  have hS:=inputSize_pos i\n  unfold frameTime\n  omega\n/-- Actual complete per-occurrence source, including physical parsing, lookup, framing and every cleanup drain. -/\ntheorem rowTime_le (i:Inputs) (own fac:List Bool) (ho:own.length ≤ inputSize i) (hf:fac.length ≤ inputSize i) :\n    rowTime i own fac ≤ 10000*(inputSize i)^2 :=by\n  have h0:=lookupClock_le i own ho\n  have h1:=lookupClock_le i fac hf\n  have h2:=frameTime_le i own fac\n  have hID:=(readID_length i own).trans (basic_bounds i).2\n  have hj:=joint_length i (own,fac)\n  have hS:=inputSize_pos i\n  unfold rowTime bodyTime\n  nlinarith only [h0,h1,h2,hID,hj,ho,hf,hS]\n/-- Whole actual occurrence scan pays the original multiplicity, never only distinct selected keys. -/\ntheorem rowsTime_le (i:Inputs) (rows:List (List Bool×List Bool))\n    (hr:∀row∈rows,row.1.length ≤ inputSize i ∧ row.2.length ≤ inputSize i) :\n    rowsTime i rows ≤ rows.length*(10000*(inputSize i)^2)+1 :=by\n  induction rows with\n  | nil=>simpa only [rowsTime,List.foldr_nil,List.length_nil,Nat.zero_mul,Nat.zero_add] using (Nat.le_refl 1)\n  | cons row rows ih=>\n    rcases row with ⟨own,fac⟩\n    have hh:=hr (own,fac) List.mem_cons_self\n    have ht:=rowTime_le i own fac hh.1 hh.2\n    have hi:=ih (fun row h=>hr row (List.mem_cons_of_mem _ h))\n    change rowTime i own fac+rowsTime i rows ≤ _\n    rw [List.length_cons,Nat.add_mul,Nat.one_mul]\n    omega\nend RiemannGaussian.SemiprimeD1StackSourceSelectedKeysBytes\n","RiemannGaussian.SemiprimeD1StackSourceSelectedKeysExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceSelectedKeysLoop\nimport RiemannGaussian.SemiprimeD1StackSourceSelectedKeysSetup\nimport RiemannGaussian.SemiprimeD1StackSourceSelectedKeysFinish\n/-! # Whole same-program selected-key source from actual complete cache and occurrence bytes -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceSelectedKeysExecution\nopen SemiprimeD1StackSourceSelectedKeys SemiprimeD1StackSourceSelectedKeysEncoding\nopen SemiprimeD1StackSourceSelectedKeysPrimitives SemiprimeD1StackSourceSelectedKeysView\nopen SemiprimeD1StackSourceSelectedKeysLoop SemiprimeD1StackSourceSelectedKeysSetup SemiprimeD1StackSourceSelectedKeysFinish\nopen SemiprimeD1StackProcedureTrace\n/-- Own whole trace clock includes every input copy, lookup, frame, byte drain, both reversals and final halt. -/\ndef runBound (i:Inputs) :Nat :=setupTime i+rowsTime i i.rows+finishTime i (stream i.ids i.rows).reverse+1\n/-- The complete actual source returns EXACT chronological oldjoint key-vector bytes from the retained full dictionary. -/\ntheorem source_trace (i:Inputs) (hc:Complete i) :\n    ∃q,q+1 ≤ runBound i ∧ Runs program q .start (source i).data .done (result i) :=by\n  have h0:=setup_run i\n  obtain ⟨q,hq,h1⟩:=rows_run i i.rows [] hc\n  simp only [List.append_nil] at h1\n  have h2:=finish_run i (stream i.ids i.rows).reverse\n  rw [List.reverse_reverse,stream_vector] at h2\n  refine ⟨_,?_,join (join h0 h1) h2⟩\n  unfold runBound\n  omega\n/-- Whole source includes its actual literal halt, clearing both flags and real return frames. -/\ntheorem source_run (i:Inputs) (hc:Complete i) :\n    ∃q ≤ runBound i,SemiprimeD1StackCalls.run program q (source i)=some (done i) :=by\n  obtain ⟨q,hq,hr⟩:=source_trace i hc\n  obtain ⟨finish,hf,hAt⟩:=hr [] (source i) ⟨rfl,rfl,rfl⟩\n  have hh:=halt_run program .done rfl (result i) [] finish hAt\n  exact ⟨q+1,hq,by rw [SemiprimeD1StackReturnLink.run_add,hf,Option.bind_some];exact hh⟩\n/-- Genuine finite-machine source certificate uses the actual acquired multiword bank, with complete-cache lineage explicit. -/\nnoncomputable def selectedKeysInTime (i:Inputs) (hc:Complete i) :\n    StateTransition.EvalsToInTime machine.step (SemiprimeD1StackCalls.configuration (source i))\n      (some (SemiprimeD1StackCalls.configuration (done i))) (runBound i) :=by\n  apply SemiprimeD1StackCalls.evalsCorrect (aux .source) (aux .output) .start program\n  let h:=source_run i hc\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\nend RiemannGaussian.SemiprimeD1StackSourceSelectedKeysExecution\n","RiemannGaussian.SemiprimeD1StackSourceSelectedKeysParse":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceSelectedKeysView\n/-! # Actual pair-tag/two-field occurrence parser and both true-validity pops -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceSelectedKeysParse\nopen SemiprimeD1StackSourceSelectedKeys SemiprimeD1StackSourceSelectedKeysEncoding\nopen SemiprimeD1StackSourceSelectedKeysPrimitives SemiprimeD1StackSourceSelectedKeysView\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\nnamespace Records\nexport SemiprimeD1StackOwnerLookup (records)\nend Records\n/-- The original pair tag, both endpoint key fields and both validity singletons are all physically consumed. -/\ntheorem read_row (i:Inputs) (own fac hist:List Bool) (rows:List (List Bool×List Bool)) :\n    Runs program (8*(own.length+fac.length)+17) .header\n      (view i [] [] [] (Records.records ((own,fac)::rows) []) [] [] [] [] [] [] hist []) (.copyQuery .owner)\n      (view i [] [] [] (Records.records rows []) own fac [] [] [] [] hist []) :=by\n  have h0:=pop_run .header .abort .eof (.parse .owner) (aux .reader)\n    (view i [] [] [] (Records.records ((own,fac)::rows) []) [] [] [] [] [] [] hist [])\n    (true::frame own (frame fac (Records.records rows []))) rfl rfl\n  change Runs program 1 _ _ _ (Function.update\n    (view i [] [] [] (Records.records ((own,fac)::rows) []) [] [] [] [] [] [] hist [])\n      (aux .reader) (frame own (frame fac (Records.records rows [])))) at h0\n  rw [update_reader] at h0\n  have h1:=parse_call .owner (view i [] [] [] (frame own (frame fac (Records.records rows []))) [] [] [] [] [] [] hist [])\n    own (frame fac (Records.records rows [])) rfl rfl rfl rfl\n  change Runs program _ _ _ _ (Function.update (Function.update (Function.update\n    (view i [] [] [] (frame own (frame fac (Records.records rows []))) [] [] [] [] [] [] hist [])\n      (aux .reader) (frame fac (Records.records rows []))) (aux .ownerKey) own) (aux .valid) [true]) at h1\n  rw [update_reader,update_own,update_valid] at h1\n  have h2:=pop_run (.valid .owner) .abort .abort (.parse .factor) (aux .valid)\n    (view i [] [] [] (frame fac (Records.records rows [])) own [] [] [] [true] [] hist []) [true] rfl rfl\n  change Runs program 1 _ _ _ (Function.update\n    (view i [] [] [] (frame fac (Records.records rows [])) own [] [] [] [true] [] hist []) (aux .valid) []) at h2\n  rw [update_valid] at h2\n  have h3:=parse_call .factor (view i [] [] [] (frame fac (Records.records rows [])) own [] [] [] [] [] hist [])\n    fac (Records.records rows []) rfl rfl rfl rfl\n  change Runs program _ _ _ _ (Function.update (Function.update (Function.update\n    (view i [] [] [] (frame fac (Records.records rows [])) own [] [] [] [] [] hist [])\n      (aux .reader) (Records.records rows [])) (aux .factorKey) fac) (aux .valid) [true]) at h3\n  rw [update_reader,update_fac,update_valid] at h3\n  have h4:=pop_run (.valid .factor) .abort .abort (.copyQuery .owner) (aux .valid)\n    (view i [] [] [] (Records.records rows []) own fac [] [] [true] [] hist []) [true] rfl rfl\n  change Runs program 1 _ _ _ (Function.update\n    (view i [] [] [] (Records.records rows []) own fac [] [] [true] [] hist []) (aux .valid) []) at h4\n  rw [update_valid] at h4\n  have h:=join (join (join (join h0 h1) h2) h3) h4\n  have ht:1+(8*own.length+7)+1+(8*fac.length+7)+1=8*(own.length+fac.length)+17:=by omega\n  simpa only [ht,SemiprimeD1StackBytecode.choose,List.head?_cons] using h\nend RiemannGaussian.SemiprimeD1StackSourceSelectedKeysParse\n","RiemannGaussian.SemiprimeD1StackSourceSelectionAcquireBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceSelectionAcquireExecution\nimport RiemannGaussian.SemiprimeD1StackSourceSelectionAcquireProjection\nimport RiemannGaussian.SemiprimeD1StackSourceAlphabet64Storage\n/-! # Whole physical three-input acquisition envelope with the actual alphabet paid\nThe original typed network is a proof interpretation of the acquired row word.\nAll intermediate word bounds come from the SAME actual21/30/63 source traces;\nthe final39 source keeps its own actual cubic acquired-byte clock. The factor\n64^a is explicitly included in the input envelope and is never made free.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceSelectionAcquireBounds\nopen SemiprimeD1StackSourceSelectionAcquire SemiprimeD1StackSourceSelectionAcquireEncoding\nopen SemiprimeD1StackSourceSelectionAcquireSelectorInput SemiprimeD1StackSourceSelectionAcquireKeyInput\nopen SemiprimeD1StackSourceSelectionAcquireProjection\nattribute [local irreducible] SemiprimeD1IncidenceSearch.run SemiprimeD1IncidenceAcquisition.acquire\n/-- Actual original row bytes, unary owner/exponent bytes, genuinely enumerated alphabet cardinality and one unit. -/\ndef inputSize (net:N.Network) (a:Nat) :Nat:=\n  (SemiprimeD1StackSourceOccurrencesEncoding.inputTape (originalRows net)).length+net.leftCount+a+64^a+1\n/-- Only SAME actual21/30 source caps augment the actual physical input envelope. -/\ndef producerEnvelope (net:N.Network) (a:Nat) :Nat:=inputSize net a+\n  SemiprimeD1StackSourceOccurrencesBounds.polynomial net.leftCount (originalRows net)+10000*(a+1)*(64^a+1)\n/-- Complete stopped selector word envelope follows its own actual input and actual whole trace. -/\ndef cacheEnvelope (net:N.Network) (a:Nat) :Nat:=producerEnvelope net a+selectorBound net a+1\n/-- Basic retained physical input words and the actual alphabet count are all paid before any source call. -/\ntheorem input_bounds (net:N.Network) (a:Nat) :1≤ inputSize net a ∧\n    SemiprimeD1StackSourceOccurrencesBounds.inputSize net.leftCount (originalRows net)≤ inputSize net a ∧\n    a+1≤ inputSize net a ∧ 64^a+1≤ inputSize net a :=by\n  have hL:0<64^a:=pow_pos (by decide) a\n  unfold inputSize SemiprimeD1StackSourceOccurrencesBounds.inputSize\n  omega\n/-- The producer envelope is positive and retains every actual original input byte. -/\ntheorem envelope_pos (net:N.Network) (a:Nat) :1≤ producerEnvelope net a :=by\n  have h:=(input_bounds net a).1\n  unfold producerEnvelope\n  omega\n/-- ALL21 acquired occurrence/F/M/source/scratch words are bounded using the SAME actual whole occurrence run. -/\ntheorem occurrence_word_bound (net:N.Network) (a:Nat) (k:Occ.Stack) :\n    ((occurrenceDone net).data k).length≤ producerEnvelope net a :=by\n  obtain ⟨q,hq,hr⟩:=SemiprimeD1StackSourceOccurrencesBounds.source_run_bounded net.leftCount (originalRows net)\n  have hi:∀k,((SemiprimeD1StackSourceOccurrencesExecution.source net.leftCount (originalRows net)).data k).length≤ inputSize net a:=by\n    intro k\n    have h:=SemiprimeD1StackSourceOccurrencesExecution.initial_length net.leftCount (originalRows net) k\n    have hb:=(input_bounds net a).2.1\n    unfold SemiprimeD1StackSourceOccurrencesBounds.inputSize at hb\n    exact h.trans (by omega)\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound Occ.program q (inputSize net a) _ _ hi hr k\n  change ((occurrenceDone net).data k).length≤ inputSize net a+q at hd\n  exact hd.trans (by unfold producerEnvelope;omega)\n/-- ALL30 actual acquired alphabet/counter/power/catalogue words are paid by the SAME actual alphabet construction trace. -/\ntheorem alphabet_word_bound (net:N.Network) (a:Nat) (k:Alpha.Stack) :\n    ((alphabetDone a).data k).length≤ producerEnvelope net a :=by\n  obtain ⟨q,hq,hr⟩:=SemiprimeD1StackSourceAlphabet64Bounds.source_run_bounded a\n  have hi:∀k,((Alpha.initial (List.replicate a true)).data k).length≤ inputSize net a:=by\n    intro k\n    exact (SemiprimeD1StackSourceAlphabet64Storage.initial_role_bound a k).trans\n      (by have h:=(input_bounds net a).2.2.1;omega)\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound Alpha.program q (inputSize net a) _ _ hi hr k\n  change ((alphabetDone a).data k).length≤ inputSize net a+q at hd\n  exact hd.trans (by unfold producerEnvelope;omega)\n/-- The generic seven-word selector input has no physical word larger than its actually acquired producer envelope. -/\ntheorem selector_initial_word_bound (net:N.Network) (a:Nat) (k:Select.Stack) :\n    ((selectorSource net a).data k).length≤ producerEnvelope net a :=by\n  have he:selectorReady (occurrenceDone net).data (alphabetDone a).data=(selectorSource net a).data:=\n    selectorReady_original net a\n  rw [←he,selectorReady_eq_initial]\n  rcases k with k|k\n  · rcases k with k|k\n    · exact Nat.zero_le _\n    · cases k <;> first\n      | exact occurrence_word_bound net a .output\n      | exact alphabet_word_bound net a (Alpha.aux .square)\n      | exact alphabet_word_bound net a (Alpha.aux .cube)\n      | exact alphabet_word_bound net a (Alpha.aux .fourth)\n      | exact Nat.zero_le _\n  · cases k <;> first\n    | exact alphabet_word_bound net a (Alpha.aux .output)\n    | exact occurrence_word_bound net a .number\n    | exact occurrence_word_bound net a .factors\n    | exact Nat.zero_le _\n/-- The actual seven acquired source words bound the entire original selector input, including unary n/F and catalogue colour bytes. -/\ntheorem selectorSize_le (net:N.Network) (a:Nat) :\n    SemiprimeD1StackSourceIncidenceSelectOriginal.acquiredSize net.leftCount net.rows.length a\n      (N.arity net.rows) (N.owner net.rows)+1≤9*producerEnvelope net a :=by\n  have ho:=occurrence_word_bound net a .output\n  have hN:=occurrence_word_bound net a .number\n  have hF:=occurrence_word_bound net a .factors\n  have hc:=alphabet_word_bound net a (Alpha.aux .output)\n  have hs:=alphabet_word_bound net a (Alpha.aux .square)\n  have hu:=alphabet_word_bound net a (Alpha.aux .cube)\n  have hf:=alphabet_word_bound net a (Alpha.aux .fourth)\n  change (SemiprimeD1StackSourceAlphabet64Encoding.result a (Alpha.aux .output)).length≤ producerEnvelope net a at hc\n  change (SemiprimeD1StackSourceAlphabet64Encoding.result a (Alpha.aux .square)).length≤ producerEnvelope net a at hs\n  change (SemiprimeD1StackSourceAlphabet64Encoding.result a (Alpha.aux .cube)).length≤ producerEnvelope net a at hu\n  change (SemiprimeD1StackSourceAlphabet64Encoding.result a (Alpha.aux .fourth)).length≤ producerEnvelope net a at hf\n  have hp:=envelope_pos net a\n  have hout:=SemiprimeD1StackSourceOccurrencesOriginal.output_original net\n  have hfac:=SemiprimeD1StackSourceOccurrencesOriginal.factor_count net\n  unfold SemiprimeD1StackSourceOccurrencesOriginal.originalDone at hout hfac\n  change ((occurrenceDone net).data .output)=_ at hout\n  change ((occurrenceDone net).data .factors)=_ at hfac\n  rw [hout,←SemiprimeD1StackSourceIncidenceSelectOccurrences.network_original_keys net a] at ho\n  rw [hfac,List.length_replicate] at hF\n  change (List.replicate net.leftCount true).length≤_ at hN\n  rw [List.length_replicate] at hN\n  unfold SemiprimeD1StackSourceIncidenceSelectOriginal.acquiredSize\n  change _≤9*producerEnvelope net a\n  omega\n/-- Every actual63-word stopped cache bound comes from the SAME closed actual selector run, not a supplied selected-ID width or report clock. -/\ntheorem selector_word_bound (net:N.Network) (a:Nat) (k:Select.Stack) :\n    ((selectorDone net a).data k).length≤ producerEnvelope net a+selectorBound net a :=by\n  obtain ⟨q,hq,hr⟩:=SemiprimeD1StackSourceIncidenceSelectOriginal.acquired_source_run net.leftCount net.rows.length a\n    (N.arity net.rows) (N.owner net.rows)\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound Select.program q (producerEnvelope net a) _ _\n    (selector_initial_word_bound net a) hr k\n  change ((selectorDone net a).data k).length≤ producerEnvelope net a+q at hd\n  exact hd.trans (Nat.add_le_add_left hq _)\n/-- Actual four-field handoff and the SAME stopped63-word trace bound the entire39-role input cache/tape size. -/\ntheorem keyInputSize_le (net:N.Network) (a:Nat) :\n    SemiprimeD1StackSourceSelectedKeysEncoding.inputSize (keyInput net a)≤5*cacheEnvelope net a :=by\n  have he:keyReady (selectorDone net a).data=(SemiprimeD1StackSourceSelectedKeysEncoding.source (keyInput net a)).data:=\n    keyReady_original net.leftCount net.rows.length a (N.arity net.rows) (N.owner net.rows)\n  have hD:((SemiprimeD1StackSourceSelectedKeysEncoding.source (keyInput net a)).data\n      (Keys.environmentStack (Env.aux .dictionary))).length≤ producerEnvelope net a+selectorBound net a:=by\n    rw [←he]\n    exact selector_word_bound net a Select.dictionary\n  have hK:((SemiprimeD1StackSourceSelectedKeysEncoding.source (keyInput net a)).data\n      (Keys.environmentStack (Env.aux .nextKey))).length≤ producerEnvelope net a+selectorBound net a:=by\n    rw [←he]\n    exact selector_word_bound net a Select.nextKey\n  have hP:((SemiprimeD1StackSourceSelectedKeysEncoding.source (keyInput net a)).data\n      (Keys.environmentStack (Env.aux .prefix))).length≤ producerEnvelope net a+selectorBound net a:=by\n    rw [←he]\n    exact selector_word_bound net a Select.selected\n  have hS:((SemiprimeD1StackSourceSelectedKeysEncoding.source (keyInput net a)).data\n      (Keys.aux .source)).length≤ producerEnvelope net a+selectorBound net a:=by\n    rw [←he]\n    exact selector_word_bound net a (Select.queryStack (SemiprimeD1StackSourceIncidence.aux .source))\n  change (SemiprimeD1StackSourceSelectedKeysEncoding.tape (keyInput net a)).length≤_ at hS\n  change (SemiprimeD1StackSourceEnvironmentEncoding.dictionary (selectedIDs net a)).length≤_ at hD\n  change (SemiprimeD1StackSourceEnvironmentEncoding.variableKey (selectedIDs net a).length).length≤_ at hK\n  change (SemiprimeD1TensorTapeCodec.vectorBits (selectedIDs net a)).length≤_ at hP\n  unfold SemiprimeD1StackSourceSelectedKeysEncoding.inputSize SemiprimeD1StackSourceEnvironmentBounds.cacheSize\n  change (SemiprimeD1StackSourceSelectedKeysEncoding.tape (keyInput net a)).length+\n    ((SemiprimeD1StackSourceEnvironmentEncoding.dictionary (selectedIDs net a)).length+\n      (SemiprimeD1StackSourceEnvironmentEncoding.variableKey (selectedIDs net a).length).length+\n      0+0+(SemiprimeD1TensorTapeCodec.vectorBits (selectedIDs net a)).length+1)≤_\n  unfold cacheEnvelope\n  omega\n/-- Seven real preserving input copies pay precisely the seven acquired input words, with all actual returns included. -/\ntheorem selectorCopyTime_le (net:N.Network) (a:Nat) :\n    selectorCopyTime (occurrenceDone net).data (alphabetDone a).data≤35*producerEnvelope net a+28 :=by\n  have h0:=occurrence_word_bound net a .output\n  have h1:=alphabet_word_bound net a (Alpha.aux .output)\n  have h2:=alphabet_word_bound net a (Alpha.aux .square)\n  have h3:=alphabet_word_bound net a (Alpha.aux .cube)\n  have h4:=alphabet_word_bound net a (Alpha.aux .fourth)\n  have h5:=occurrence_word_bound net a .number\n  have h6:=occurrence_word_bound net a .factors\n  unfold selectorCopyTime\n  omega\n/-- Four actual stopped-selector word copies pay every selected cache/key/prefix/occurrence byte. -/\ntheorem keyCopyTime_le (net:N.Network) (a:Nat) :\n    keyCopyTime (selectorDone net a).data≤20*(producerEnvelope net a+selectorBound net a)+16 :=by\n  have h0:=selector_word_bound net a Select.dictionary\n  have h1:=selector_word_bound net a Select.nextKey\n  have h2:=selector_word_bound net a Select.selected\n  have h3:=selector_word_bound net a (Select.queryStack (SemiprimeD1StackSourceIncidence.aux .source))\n  unfold keyCopyTime\n  omega\n/-- The actual39 source keeps its own cubic clock on its actually acquired cache/tape bytes. -/\ntheorem keysClock_le (net:N.Network) (a:Nat) :\n    SemiprimeD1StackSourceSelectedKeysBounds.polynomial (keyInput net a)≤1250000000*(cacheEnvelope net a)^3 :=by\n  have h:=Nat.pow_le_pow_left (keyInputSize_le net a) 3\n  unfold SemiprimeD1StackSourceSelectedKeysBounds.polynomial\n  calc\n    _≤10000000*(5*cacheEnvelope net a)^3:=Nat.mul_le_mul_left _ h\n    _=1250000000*(cacheEnvelope net a)^3:=by ring\n/-- All four SAME actual source clocks and eleven paid copies compose within one cubic acquired-cache envelope. -/\ntheorem timeBound_envelope (net:N.Network) (a:Nat) :timeBound net a≤10^12*(cacheEnvelope net a)^3 :=by\n  have ho:=SemiprimeD1StackSourceOccurrencesBounds.timeBound_le net.leftCount (originalRows net)\n  have hs:=selectorCopyTime_le net a\n  have hk:=keyCopyTime_le net a\n  have ht:=keysClock_le net a\n  have hp:=envelope_pos net a\n  have hC:1≤ cacheEnvelope net a:=by unfold cacheEnvelope;omega\n  have hC3:cacheEnvelope net a≤(cacheEnvelope net a)^3:=Nat.le_pow (by decide:0<(3:Nat))\n  unfold timeBound cacheEnvelope producerEnvelope at *\n  norm_num only [Nat.reducePow] at *\n  omega\n/-- The actual input and SAME21/30 clocks have one fixed quadratic envelope, with64^a explicitly present. -/\ntheorem producerEnvelope_le (net:N.Network) (a:Nat) :producerEnvelope net a≤10^7*(inputSize net a)^2 :=by\n  let R:=inputSize net a\n  have hR:1≤ R:=(input_bounds net a).1\n  have ho:=Nat.pow_le_pow_left (input_bounds net a).2.1 2\n  have hm:=Nat.mul_le_mul (input_bounds net a).2.2.1 (input_bounds net a).2.2.2\n  have hself:R≤ R^2:=Nat.le_pow (by decide:0<(2:Nat))\n  unfold producerEnvelope SemiprimeD1StackSourceOccurrencesBounds.polynomial\n  change R+1000000*(SemiprimeD1StackSourceOccurrencesBounds.inputSize net.leftCount (originalRows net))^2+\n    10000*(a+1)*(64^a+1)≤10^7*R^2\n  norm_num only [Nat.reducePow]\n  nlinarith only [ho,hm,hself]\n/-- The same actual selector input bound yields a fixed degree32 original physical-source cap. -/\ntheorem selectorBound_le (net:N.Network) (a:Nat) :selectorBound net a≤10^158*(inputSize net a)^32 :=by\n  have hs:=selectorSize_le net a\n  have hp:=producerEnvelope_le net a\n  have h9:9*producerEnvelope net a≤10^8*(inputSize net a)^2:=by norm_num only [Nat.reducePow] at hp ⊢;omega\n  have h:=Nat.pow_le_pow_left (hs.trans h9) 16\n  unfold selectorBound\n  calc\n    _≤10^30*(10^8*(inputSize net a)^2)^16:=Nat.mul_le_mul_left _ h\n    _=10^158*(inputSize net a)^32:=by ring\n/-- All actual stopped cache words are bounded by a fixed degree32 physical-input expression. -/\ntheorem cacheEnvelope_le (net:N.Network) (a:Nat) :cacheEnvelope net a≤10^159*(inputSize net a)^32 :=by\n  have hp:=producerEnvelope_le net a\n  have hs:=selectorBound_le net a\n  have hR:1≤ inputSize net a:=(input_bounds net a).1\n  have hpow:(inputSize net a)^2≤(inputSize net a)^32:=Nat.pow_le_pow_right hR (by decide)\n  have h1:1≤(inputSize net a)^32:=Nat.one_le_pow _ _ hR\n  have hb:producerEnvelope net a≤10^7*(inputSize net a)^32:=hp.trans (Nat.mul_le_mul_left _ hpow)\n  unfold cacheEnvelope\n  norm_num only [Nat.reducePow] at hs hb ⊢\n  omega\n/-- Universal whole-source polynomial with fixed constants before all networks and exponents. -/\ndef polynomial (net:N.Network) (a:Nat) :Nat:=10^500*(inputSize net a)^100\nset_option exponentiation.threshold 512 in\n/-- The actual four-source trace retains its own clocks throughout; no old native report clock is transported. -/\ntheorem timeBound_le (net:N.Network) (a:Nat) :timeBound net a≤ polynomial net a :=by\n  have ht:=timeBound_envelope net a\n  have hc:=Nat.pow_le_pow_left (cacheEnvelope_le net a) 3\n  have hR:1≤ inputSize net a:=(input_bounds net a).1\n  have hp:(inputSize net a)^96≤(inputSize net a)^100:=Nat.pow_le_pow_right hR (by decide)\n  calc\n    timeBound net a≤10^12*(cacheEnvelope net a)^3:=ht\n    _≤10^12*(10^159*(inputSize net a)^32)^3:=Nat.mul_le_mul_left _ hc\n    _=10^489*(inputSize net a)^96:=by\n      calc\n        _=(10^12*10^(159*3))*(inputSize net a)^(32*3):=by rw [mul_pow,←pow_mul,←pow_mul,Nat.mul_assoc]\n        _=10^(12+159*3)*(inputSize net a)^(32*3):=by rw [pow_add]\n        _=10^489*(inputSize net a)^96:=rfl\n    _≤10^500*(inputSize net a)^100:=Nat.mul_le_mul (Nat.pow_le_pow_right (n:=10) (i:=489) (j:=500) (by decide) (by decide)) hp\n    _=polynomial net a:=rfl\n/-- Whole literal three-input source has the same original-row exact stop within the fixed physical-input polynomial. -/\ntheorem source_run_bounded (net:N.Network) (a:Nat) :∃q≤ polynomial net a,\n    SemiprimeD1StackCalls.run program q (source net a)=some (done net a) :=by\n  obtain ⟨q,hq,hr⟩:=SemiprimeD1StackSourceSelectionAcquireExecution.source_run net a\n  exact ⟨q,hq.trans (timeBound_le net a),hr⟩\n/-- Genuine fixed154-role finite machine executes the same whole source with its own polynomial clock. -/\nnoncomputable def machineSource (net:N.Network) (a:Nat) :\n    StateTransition.EvalsToInTime machine.step (SemiprimeD1StackCalls.configuration (source net a))\n      (some (SemiprimeD1StackCalls.configuration (done net a))) (polynomial net a) :=by\n  apply SemiprimeD1StackCalls.evalsCorrect (occurrenceStack .rows) (keyStack (Keys.aux .output)) (Label.local .start) program\n  let h:=source_run_bounded net a\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\nend RiemannGaussian.SemiprimeD1StackSourceSelectionAcquireBounds\n","RiemannGaussian.SemiprimeD1StackStaticTablePrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackStaticTable\nimport RiemannGaussian.SemiprimeD1StackPhysicalLoops\n/-! # Actual generic copy, reverse, read and physical drain instructions -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1200000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackStaticTablePrimitives\nopen SemiprimeD1StackStaticTable SemiprimeD1StackProcedureTrace\nvariable {K L : Type} [DecidableEq K] (s : Static K L)\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel data_update)\nend Link\nomit [DecidableEq K] in\n/-- Read-only source, writable destination and scratch never alias at any site. -/\ntheorem copy_injective (position : Option (Fin s.roles.length)) : Function.Injective (copyStack s position) := by\n  intro a b h\n  fin_cases a <;> fin_cases b <;> cases position <;>\n    simp_all [copyStack,checker,template,aux]\nomit [DecidableEq K] in\n/-- Both consuming reversals have distinct physical operands. -/\ntheorem reverse_injective (table : Bool) : Function.Injective (reverseStack s table) := by\n  intro a b h\n  fin_cases a <;> fin_cases b <;> cases table <;> simp_all [reverseStack,checker,aux]\n/-- One actual literal Boolean push. -/\ntheorem push (pc next : Label L s.roles.length) (key : Stack K) (bit : Bool)\n    (hc : program s pc=.base (.push key bit next)) (d : Stack K→List Bool) :\n    Runs (program s) 1 pc d next (Function.update d key (bit::d key)) := by\n  apply one_base (program s) pc next (.push key bit next) _ _ hc <;> rfl\n/-- Physical clearing consumes each payload bit and the actual EOF. -/\ntheorem drain (pc next : Label L s.roles.length) (key : Stack K)\n    (hc : program s pc=.base (.pop key next pc pc)) (d : Stack K→List Bool) :\n    Runs (program s) ((d key).length+1) pc d next (Function.update d key []) := by\n  have h:=SemiprimeD1StackPhysicalLoops.drain (program s) pc next key hc d (d key)\n  rw [Function.update_eq_self] at h\n  exact h\n/-- One preserving copy executes its literal program and actual return. -/\ntheorem copy_call (position : Option (Fin s.roles.length)) (pc next : Label L s.roles.length)\n    (hc : program s pc=.call (.copy position 0) next) (d : Stack K→List Bool)\n    (hd : d (copyStack s position 1)=[]) (hs : d (aux .scratch)=[]) :\n    Runs (program s) (5*(d (copyStack s position 0)).length+4) pc d next\n      (Function.update d (copyStack s position 1) (d (copyStack s position 0))) := by\n  let word:=d (copyStack s position 0)\n  have hin : Link.DataRel (copyStack s position) d (SemiprimeD1StackCopy.state 0 none word [] []).store d := by\n    constructor\n    · intro k;fin_cases k\n      · rfl\n      · exact hd\n      · exact hs\n    · intro k _;rfl\n  have hout:=Link.data_update (copyStack s position) (copy_injective s position) _ _ _ hin (1:Fin 3) word\n  have he:Function.update (SemiprimeD1StackCopy.state 0 none word [] []).store 1 word=\n      (SemiprimeD1StackCopy.done word word).store := by funext k;fin_cases k <;> rfl\n  rw [he] at hout\n  apply included_call (program s) (copyStack s position) (Label.copy position) (copy_injective s position)\n    SemiprimeD1StackCopy.code 0 (fun _=>rfl) pc next hc (5*word.length+3)\n    (SemiprimeD1StackCopy.state 0 none word [] []) (SemiprimeD1StackCopy.done word word)\n    _ _ rfl rfl (by simpa only [List.append_nil] using SemiprimeD1StackCopy.copy_words word [] none) hin hout\n/-- Actual prefix/table reversal, retaining every other template/cache/work word. -/\ntheorem reverse_call (table : Bool) (pc next : Label L s.roles.length)\n    (hc : program s pc=.call (.reverse table 0) next) (d : Stack K→List Bool) :\n    Runs (program s) (2*(d (reverseStack s table 0)).length+3) pc d next\n      (Function.update (Function.update d (reverseStack s table 0) []) (reverseStack s table 1)\n        ((d (reverseStack s table 0)).reverse++d (reverseStack s table 1))) := by\n  let xs:=d (reverseStack s table 0)\n  let ys:=d (reverseStack s table 1)\n  have hin : Link.DataRel (reverseStack s table) d (SemiprimeD1StackReverseWord.state none xs ys).store d := by\n    constructor\n    · intro k;fin_cases k <;> rfl\n    · intro k _;rfl\n  have h0:=Link.data_update (reverseStack s table) (reverse_injective s table) _ _ _ hin (0:Fin 2) []\n  have hout:=Link.data_update (reverseStack s table) (reverse_injective s table) _ _ _ h0 (1:Fin 2) (xs.reverse++ys)\n  have he:Function.update (Function.update (SemiprimeD1StackReverseWord.state none xs ys).store 0 []) 1 (xs.reverse++ys)=\n      (SemiprimeD1StackReverseWord.done (xs.reverse++ys)).store := by funext k;fin_cases k <;> rfl\n  rw [he] at hout\n  apply included_call (program s) (reverseStack s table) (Label.reverse table) (reverse_injective s table)\n    SemiprimeD1StackReverseWord.code 0 (fun _=>rfl) pc next hc (2*xs.length+2)\n    (SemiprimeD1StackReverseWord.state none xs ys) (SemiprimeD1StackReverseWord.done (xs.reverse++ys))\n    _ _ rfl rfl (SemiprimeD1StackReverseWord.reverse_run xs ys none) hin hout\nend RiemannGaussian.SemiprimeD1StackStaticTablePrimitives\n","RiemannGaussian.SemiprimeD1StackTransformGrowth":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackTransformComponents\n\n/-! # Actual marker doubling and quadrupling for transform acquisition\nEvery output marker is a literal push. Original input and threshold are retained;\nwork is consumed/restored physically rather than expanded by a native power.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackTransformGrowth\nopen SemiprimeD1StackTransform SemiprimeD1StackTransformComponents\nopen SemiprimeD1StackProcedureFragments (At Runs one_base)\n\n/-- Three actual instructions replace one radius marker by two work markers. -/\ntheorem radius_bit (bits threshold radius square exponent tmp radix:List Bool) :\n    Runs program 3 (.inl .radiusPop) (data bits threshold (true::radius) square exponent [] [] tmp radix)\n      (.inl .radiusPop) (data bits threshold radius square exponent [] [] (true::true::tmp) radix) := by\n  have h0:Runs program 1 (.inl .radiusPop) (data bits threshold (true::radius) square exponent [] [] tmp radix)\n      (.inl .radiusPush1) (data bits threshold radius square exponent [] [] tmp radix):=by\n    apply one_base program _ _ (.pop .radius (.inl .radiusRestore) (.inl .radiusPush1) (.inl .radiusPush1)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> simp [B.execute,data,Function.update]\n  have h1:Runs program 1 (.inl .radiusPush1) (data bits threshold radius square exponent [] [] tmp radix)\n      (.inl .radiusPush2) (data bits threshold radius square exponent [] [] (true::tmp) radix):=by\n    apply one_base program _ _ (.push .temporary true (.inl .radiusPush2)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> simp [B.execute,data,Function.update]\n  have h2:Runs program 1 (.inl .radiusPush2) (data bits threshold radius square exponent [] [] (true::tmp) radix)\n      (.inl .radiusPop) (data bits threshold radius square exponent [] [] (true::true::tmp) radix):=by\n    apply one_base program _ _ (.push .temporary true (.inl .radiusPop)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> simp [B.execute,data,Function.update]\n  exact h0.trans (h1.trans (h2))\n\n/-- Two actual instructions restore one radius marker from work. -/\ntheorem radius_restore_bit (bits threshold radius square exponent tmp radix:List Bool) :\n    Runs program 2 (.inl .radiusRestore) (data bits threshold radius square exponent [] [] (true::tmp) radix)\n      (.inl .radiusRestore) (data bits threshold (true::radius) square exponent [] [] tmp radix) := by\n  have h0:Runs program 1 (.inl .radiusRestore) (data bits threshold radius square exponent [] [] (true::tmp) radix)\n      (.inl .radiusRestorePush) (data bits threshold radius square exponent [] [] tmp radix):=by\n    apply one_base program _ _ (.pop .temporary (.inl .squarePop) (.inl .radiusRestorePush) (.inl .radiusRestorePush)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> simp [B.execute,data,Function.update]\n  have h1:Runs program 1 (.inl .radiusRestorePush) (data bits threshold radius square exponent [] [] tmp radix)\n      (.inl .radiusRestore) (data bits threshold (true::radius) square exponent [] [] tmp radix):=by\n    apply one_base program _ _ (.push .radius true (.inl .radiusRestore)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> simp [B.execute,data,Function.update]\n  exact h0.trans (h1)\n\n/-- Five actual instructions replace one square marker by four work markers. -/\ntheorem square_bit (bits threshold radius square exponent tmp radix:List Bool) :\n    Runs program 5 (.inl .squarePop) (data bits threshold radius (true::square) exponent [] [] tmp radix)\n      (.inl .squarePop) (data bits threshold radius square exponent [] [] (true::true::true::true::tmp) radix) := by\n  have h0:Runs program 1 (.inl .squarePop) (data bits threshold radius (true::square) exponent [] [] tmp radix)\n      (.inl .squarePush1) (data bits threshold radius square exponent [] [] tmp radix):=by\n    apply one_base program _ _ (.pop .square (.inl .squareRestore) (.inl .squarePush1) (.inl .squarePush1)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> simp [B.execute,data,Function.update]\n  have h1:Runs program 1 (.inl .squarePush1) (data bits threshold radius square exponent [] [] tmp radix)\n      (.inl .squarePush2) (data bits threshold radius square exponent [] [] (true::tmp) radix):=by\n    apply one_base program _ _ (.push .temporary true (.inl .squarePush2)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> simp [B.execute,data,Function.update]\n  have h2:Runs program 1 (.inl .squarePush2) (data bits threshold radius square exponent [] [] (true::tmp) radix)\n      (.inl .squarePush3) (data bits threshold radius square exponent [] [] (true::true::tmp) radix):=by\n    apply one_base program _ _ (.push .temporary true (.inl .squarePush3)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> simp [B.execute,data,Function.update]\n  have h3:Runs program 1 (.inl .squarePush3) (data bits threshold radius square exponent [] [] (true::true::tmp) radix)\n      (.inl .squarePush4) (data bits threshold radius square exponent [] [] (true::true::true::tmp) radix):=by\n    apply one_base program _ _ (.push .temporary true (.inl .squarePush4)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> simp [B.execute,data,Function.update]\n  have h4:Runs program 1 (.inl .squarePush4) (data bits threshold radius square exponent [] [] (true::true::true::tmp) radix)\n      (.inl .squarePop) (data bits threshold radius square exponent [] [] (true::true::true::true::tmp) radix):=by\n    apply one_base program _ _ (.push .temporary true (.inl .squarePop)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> simp [B.execute,data,Function.update]\n  exact h0.trans (h1.trans (h2.trans (h3.trans (h4))))\n\n/-- Two actual instructions restore one square marker from work. -/\ntheorem square_restore_bit (bits threshold radius square exponent tmp radix:List Bool) :\n    Runs program 2 (.inl .squareRestore) (data bits threshold radius square exponent [] [] (true::tmp) radix)\n      (.inl .squareRestore) (data bits threshold radius (true::square) exponent [] [] tmp radix) := by\n  have h0:Runs program 1 (.inl .squareRestore) (data bits threshold radius square exponent [] [] (true::tmp) radix)\n      (.inl .squareRestorePush) (data bits threshold radius square exponent [] [] tmp radix):=by\n    apply one_base program _ _ (.pop .temporary (.inl .incExponent) (.inl .squareRestorePush) (.inl .squareRestorePush)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> simp [B.execute,data,Function.update]\n  have h1:Runs program 1 (.inl .squareRestorePush) (data bits threshold radius square exponent [] [] tmp radix)\n      (.inl .squareRestore) (data bits threshold radius (true::square) exponent [] [] tmp radix):=by\n    apply one_base program _ _ (.push .square true (.inl .squareRestore)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> simp [B.execute,data,Function.update]\n  exact h0.trans (h1)\n\n/-- The actual radius-consumption loop writes exactly two markers per input marker. -/\ntheorem radius_consume (n m:ℕ) (bits threshold square exponent radix:List Bool) :\n    Runs program (3*n+1) (.inl .radiusPop)\n      (data bits threshold (List.replicate n true) square exponent [] [] (List.replicate m true) radix)\n      (.inl .radiusRestore)\n      (data bits threshold [] square exponent [] [] (List.replicate (2*n+m) true) radix) := by\n  induction n generalizing m with\n  | zero =>\n    apply one_base program _ _ (.pop .radius (.inl .radiusRestore) (.inl .radiusPush1) (.inl .radiusPush1)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> simp [B.execute,data,Function.update]\n  | succ n ih =>\n    have hi:=ih (m+2)\n    have hn:2*n+(m+2)=2*(n+1)+m:=by omega\n    rw [hn] at hi\n    simp only [List.replicate_succ] at hi\n    have h:=(radius_bit bits threshold (List.replicate n true) square exponent (List.replicate m true) radix).trans hi\n    simpa only [List.replicate_succ,show 3+(3*n+1)=3*(n+1)+1 by omega] using h\n\n/-- Actual radius restoration consumes every work marker and retains the doubled radius. -/\ntheorem radius_restore (n r:ℕ) (bits threshold square exponent radix:List Bool) :\n    Runs program (2*n+1) (.inl .radiusRestore)\n      (data bits threshold (List.replicate r true) square exponent [] [] (List.replicate n true) radix)\n      (.inl .squarePop) (data bits threshold (List.replicate (n+r) true) square exponent [] [] [] radix) := by\n  induction n generalizing r with\n  | zero =>\n    apply one_base program _ _ (.pop .temporary (.inl .squarePop) (.inl .radiusRestorePush) (.inl .radiusRestorePush)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> simp [B.execute,data,Function.update]\n  | succ n ih =>\n    have hi:=ih (r+1)\n    have hn:n+(r+1)=(n+1)+r:=by omega\n    rw [hn] at hi\n    simp only [List.replicate_succ] at hi\n    have h:=(radius_restore_bit bits threshold (List.replicate r true) square exponent (List.replicate n true) radix).trans hi\n    simpa only [List.replicate_succ,show 2+(2*n+1)=2*(n+1)+1 by omega] using h\n\n/-- The actual square-consumption loop writes four physical markers per square marker. -/\ntheorem square_consume (n m:ℕ) (bits threshold radius exponent radix:List Bool) :\n    Runs program (5*n+1) (.inl .squarePop)\n      (data bits threshold radius (List.replicate n true) exponent [] [] (List.replicate m true) radix)\n      (.inl .squareRestore)\n      (data bits threshold radius [] exponent [] [] (List.replicate (4*n+m) true) radix) := by\n  induction n generalizing m with\n  | zero =>\n    apply one_base program _ _ (.pop .square (.inl .squareRestore) (.inl .squarePush1) (.inl .squarePush1)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> simp [B.execute,data,Function.update]\n  | succ n ih =>\n    have hi:=ih (m+4)\n    have hn:4*n+(m+4)=4*(n+1)+m:=by omega\n    rw [hn] at hi\n    simp only [List.replicate_succ] at hi\n    have h:=(square_bit bits threshold radius (List.replicate n true) exponent (List.replicate m true) radix).trans hi\n    simpa only [List.replicate_succ,show 5+(5*n+1)=5*(n+1)+1 by omega] using h\n\n/-- Actual square restoration consumes every newly acquired work marker. -/\ntheorem square_restore (n s:ℕ) (bits threshold radius exponent radix:List Bool) :\n    Runs program (2*n+1) (.inl .squareRestore)\n      (data bits threshold radius (List.replicate s true) exponent [] [] (List.replicate n true) radix)\n      (.inl .incExponent) (data bits threshold radius (List.replicate (n+s) true) exponent [] [] [] radix) := by\n  induction n generalizing s with\n  | zero =>\n    apply one_base program _ _ (.pop .temporary (.inl .incExponent) (.inl .squareRestorePush) (.inl .squareRestorePush)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> simp [B.execute,data,Function.update]\n  | succ n ih =>\n    have hi:=ih (s+1)\n    have hn:n+(s+1)=(n+1)+s:=by omega\n    rw [hn] at hi\n    simp only [List.replicate_succ] at hi\n    have h:=(square_restore_bit bits threshold radius (List.replicate s true) exponent (List.replicate n true) radix).trans hi\n    simpa only [List.replicate_succ,show 2+(2*n+1)=2*(n+1)+1 by omega] using h\n\n/-- One actual failure iteration doubles R, quadruples square and increments the exponent marker stack. -/\ntheorem grow (r s:ℕ) (bits threshold exponent radix:List Bool) :\n    Runs program (7*r+13*s+5) (.inl .radiusPop)\n      (data bits threshold (List.replicate r true) (List.replicate s true) exponent [] [] [] radix)\n      (.inl .copySquare)\n      (data bits threshold (List.replicate (2*r) true) (List.replicate (4*s) true) (true::exponent) [] [] [] radix) := by\n  have h0:=radius_consume r 0 bits threshold (List.replicate s true) exponent radix\n  have h1:=radius_restore (2*r) 0 bits threshold (List.replicate s true) exponent radix\n  have h2:=square_consume s 0 bits threshold (List.replicate (2*r) true) exponent radix\n  have h3:=square_restore (4*s) 0 bits threshold (List.replicate (2*r) true) exponent radix\n  simp only [Nat.add_zero,List.replicate_zero] at h0 h1 h2 h3\n  have h4:Runs program 1 (.inl .incExponent)\n      (data bits threshold (List.replicate (2*r) true) (List.replicate (4*s) true) exponent [] [] [] radix)\n      (.inl .copySquare)\n      (data bits threshold (List.replicate (2*r) true) (List.replicate (4*s) true) (true::exponent) [] [] [] radix):=by\n    apply one_base program _ _ (.push .exponent true (.inl .copySquare)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> simp [B.execute,data,Function.update]\n  have h:=h0.trans (h1.trans (h2.trans (h3.trans h4)))\n  convert h using 1\n  omega\nend RiemannGaussian.SemiprimeD1StackTransformGrowth\n","RiemannGaussian.SemiprimeD1StackVertexProductBody":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackVertexProductMultiply\n/-! # Actual parsed vertex-product round, including every cleanup and copy -/\nset_option autoImplicit false\nset_option synthInstance.maxSize 65536\nset_option maxRecDepth 65536\nset_option maxHeartbeats 2000000\nnamespace RiemannGaussian.SemiprimeD1StackVertexProductBody\nopen SemiprimeD1StackVertexProduct SemiprimeD1StackVertexProductState\nopen SemiprimeD1StackVertexProductRead SemiprimeD1StackVertexProductMoves\nopen SemiprimeD1StackProcedureTrace (Runs runs_trans one_base)\nopen SemiprimeD1TensorTapeCodec (vectorBits tape)\nopen SemiprimeD1StackUnaryDivmod (unary)\n\n/-- Explicit sum of the actual parser, vertex-reader, dense-multiplier,\noperand-drain and result-copy transition bounds for one literal record. -/\ndef roundBudget (ctx : SemiprimeD1JetAxes.Context) (v : Values)\n    (vertex : SemiprimeD1LeafCounter.Vertex) (b : List (List Bool)) : ℕ :=\n  let av:=(SemiprimeD1TensorTapeLeaf.evaluateVertex vertex (v .assignment)).words\n  let c : SemiprimeD1StackJetPointExecution.Cache :=\n    ⟨vectorBits av,vectorBits b,v .axes,v .width,v .rank,[]⟩\n  let out:=vectorBits (SemiprimeD1JetRingBits.mul ctx av b).words\n  8*(SemiprimeD1StackVertexReadExecution.portTape vertex.ports).length+\n  8*(tape vertex.table).length+16+\n  (SemiprimeD1StackVertexReadExecution.budget (v .assignment).length\n    (SemiprimeD1StackVertexReadExecution.portTape vertex.ports).length (tape vertex.table).length+1)+\n  (2000000*(SemiprimeD1StackJetMulBounds.inputSize ctx c+1)^6+1)+\n  ((vectorBits av).length+1)+((vectorBits b).length+1)+6*out.length+5\n\n/-- One actual record is parsed, gathered and multiplied; the coefficient\nbuffers are physically cleared before the result is copied into the next state. -/\ntheorem round_run (ctx : SemiprimeD1JetAxes.Context) (hp : ctx.Positive)\n    (v : Values) (vertex : SemiprimeD1LeafCounter.Vertex) (tail : List Bool)\n    (b : List (List Bool))\n    (hreader : v .reader=SemiprimeSourceHistogramKeyBits.frame\n      (SemiprimeD1StackVertexReadExecution.portTape vertex.ports)\n      (SemiprimeSourceHistogramKeyBits.frame (tape vertex.table) tail))\n    (hleft : v .left=[]) (hports : v .ports=[]) (htable : v .table=[])\n    (hvalid : v .valid=[]) (hresult : v .result=[])\n    (hb : v .product=vectorBits b)\n    (haxes : v .axes=vectorBits (ctx.axes.map unary))\n    (hw : (v .width).length=ctx.precision) (hr : v .rank=unary ctx.rank) :\n    ∃ m ≤ roundBudget ctx v vertex b, Runs program m .readPorts (data v) .vertexTag\n      (data (Function.update (Function.update v .reader tail) .product\n        (vectorBits (SemiprimeD1JetRingBits.mul ctx\n          (SemiprimeD1TensorTapeLeaf.evaluateVertex vertex (v .assignment)).words b).words))) := by\n  let p:=SemiprimeD1StackVertexReadExecution.portTape vertex.ports\n  let t:=tape vertex.table\n  let av:=(SemiprimeD1TensorTapeLeaf.evaluateVertex vertex (v .assignment)).words\n  let out:=vectorBits (SemiprimeD1JetRingBits.mul ctx av b).words\n  let v1:=Function.update (Function.update (Function.update v .reader\n    (SemiprimeSourceHistogramKeyBits.frame t tail)) .ports p) .valid [true]\n  let v2:=Function.update v1 .valid []\n  let v3:=Function.update (Function.update (Function.update v2 .reader tail) .table t) .valid [true]\n  let v4:=Function.update v3 .valid []\n  let v5:=Function.update (Function.update (Function.update v4 .ports []) .table []) .left (vectorBits av)\n  let v6:=Function.update v5 .result out\n  let v7:=Function.update v6 .left []\n  let v8:=Function.update v7 .product []\n  let v9:=Function.update v8 .product out\n  let v10:=Function.update v9 .result []\n  have h1 : Runs program (8*p.length+7) .readPorts (data v) .portsDone (data v1) :=\n    field_call v false p (SemiprimeSourceHistogramKeyBits.frame t tail) _ _ rfl hreader hports hvalid\n  have h2 : Runs program 1 .portsDone (data v1) .readTable (data v2) := by\n    simpa only [v1,v2,Function.update_idem] using\n      field_flag (Function.update (Function.update v .reader (SemiprimeSourceHistogramKeyBits.frame t tail)) .ports p)\n        .portsDone .readTable rfl\n  have h3 : Runs program (8*t.length+7) .readTable (data v2) .tableDone (data v3) := by\n    apply field_call v2 true t tail _ _ rfl\n    · simp [v2,v1]\n    · simpa [v2,v1,fieldTarget] using htable\n    · simp [v2]\n  have h4 : Runs program 1 .tableDone (data v3) .callVertex (data v4) := by\n    simpa only [v3,v4,Function.update_idem] using\n      field_flag (Function.update (Function.update v2 .reader tail) .table t) .tableDone .callVertex rfl\n  obtain ⟨m5,hm5,h5⟩:=vertex_call v4 vertex (by simp [v4,v3,v2,v1,p]) (by simp [v4,v3,t])\n    (by simpa [v4,v3,v2,v1] using hleft)\n  have h5' : Runs program m5 .callVertex (data v4) .callMul (data v5) := by\n    simpa only [v5,av,v4,v3,v2,v1,Function.update_of_ne (by decide : Slot.assignment ≠ .valid),\n      Function.update_of_ne (by decide : Slot.assignment ≠ .table),\n      Function.update_of_ne (by decide : Slot.assignment ≠ .reader),\n      Function.update_of_ne (by decide : Slot.assignment ≠ .ports)] using h5\n  obtain ⟨m6,hm6,h6⟩:=SemiprimeD1StackVertexProductMultiply.multiply_call ctx hp v5 av b\n    (by simp [v5]) (by simpa [v5,v4,v3,v2,v1] using hb)\n    (by simpa [v5,v4,v3,v2,v1] using haxes)\n    (by simpa [v5,v4,v3,v2,v1] using hw)\n    (by simpa [v5,v4,v3,v2,v1] using hr)\n    (by simpa [v5,v4,v3,v2,v1] using hresult)\n  have h7:=drain_current v6 .left .clearA .clearB rfl\n  have h8:=drain_current v7 .product .clearB .copyProduct rfl\n  have h9 : Runs program (5*(v8 .result).length+4) .copyProduct (data v8) .clearOutput (data v9) := by\n    simpa [copySource,copyTarget,v9,v8,v7,v6] using copy_call v8 false .copyProduct .clearOutput rfl\n  have h10:=drain_current v9 .result .clearOutput .vertexTag rfl\n  have hc:=runs_trans program _ _ _ _ _ _ _ _ h1 h2\n  have hc:=runs_trans program _ _ _ _ _ _ _ _ hc h3\n  have hc:=runs_trans program _ _ _ _ _ _ _ _ hc h4\n  have hc:=runs_trans program _ _ _ _ _ _ _ _ hc h5'\n  have hc:=runs_trans program _ _ _ _ _ _ _ _ hc h6\n  have hc:=runs_trans program _ _ _ _ _ _ _ _ hc h7\n  have hc:=runs_trans program _ _ _ _ _ _ _ _ hc h8\n  have hc:=runs_trans program _ _ _ _ _ _ _ _ hc h9\n  have hc:=runs_trans program _ _ _ _ _ _ _ _ hc h10\n  have hv10 : v10=Function.update (Function.update v .reader tail) .product out := by\n    funext s\n    cases s <;> simp_all [v10,v9,v8,v7,v6,v5,v4,v3,v2,v1]\n  refine ⟨8*p.length+7+1+(8*t.length+7)+1+m5+m6+((v6 .left).length+1)+\n    ((v7 .product).length+1)+(5*(v8 .result).length+4)+((v9 .result).length+1),?_,?_⟩\n  · dsimp only [roundBudget]\n    simp only [v5,v4,v3,v2,v1,SemiprimeD1StackVertexProductProjection.multiplierCache,\n      Function.update_self,Function.update_of_ne (by decide : Slot.assignment ≠ .valid),\n      Function.update_of_ne (by decide : Slot.assignment ≠ .table),\n      Function.update_of_ne (by decide : Slot.assignment ≠ .reader),\n      Function.update_of_ne (by decide : Slot.assignment ≠ .ports)] at hm5 hm6\n    simp [v9,v8,v7,v6,v5,v4,v3,v2,v1,p,t,out,av,hb] at hm5 hm6 ⊢\n    omega\n  · change Runs program _ .readPorts (data v) .vertexTag (data (Function.update (Function.update v .reader tail) .product out))\n    rw [←hv10]\n    exact hc\n\nend RiemannGaussian.SemiprimeD1StackVertexProductBody\n","RiemannGaussian.SemiprimeD1StackVertexProductState":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackVertexProduct\n/-! # Declarative register invariants for the actual vertex-product program\nThese finite functions describe physical configurations in proofs. They are not\narguments to the executed program, coefficient getters or result suppliers.\n-/\nset_option autoImplicit false\nset_option synthInstance.maxSize 65536\nset_option maxRecDepth 65536\nset_option maxHeartbeats 1500000\nnamespace RiemannGaussian.SemiprimeD1StackVertexProductState\nopen SemiprimeD1StackVertexProduct\n\n/-- The thirteen registers that can be live between actual included calls. -/\ninductive Slot where\n  | axes | precision | vertices | assignment | rank | width | left | product | result | reader | ports | table | valid\n  deriving DecidableEq,Repr\ninstance : Fintype Slot := Fintype.ofList\n  [.axes,.precision,.vertices,.assignment,.rank,.width,.left,.product,.result,.reader,.ports,.table,.valid]\n  (by intro k; cases k <;> simp)\n\n/-- Exact literal physical addresses of the between-call invariant. -/\ndef address : Slot → Stack\n  | .axes => axes\n  | .precision => aux .precisionBits\n  | .vertices => aux .verticesCache\n  | .assignment => aux .assignment\n  | .rank => rank\n  | .width => width\n  | .left => left\n  | .product => product\n  | .result => result\n  | .reader => aux .verticesReader\n  | .ports => aux .ports\n  | .table => aux .table\n  | .valid => aux .fieldValid\n\n/-- All live slots have genuinely distinct physical registers. -/\ntheorem address_injective : Function.Injective address := by decide\n\n/-- Proof-side finite word-register values, equivalent to a thirteen-field tuple. -/\nabbrev Values := Slot → List Bool\n\n/-- Declarative physical configuration, all unnamed callee workspace empty. -/\ndef data (v : Values) (k : Stack) : List Bool :=\n  if k=address .axes then v .axes else\n  if k=address .precision then v .precision else\n  if k=address .vertices then v .vertices else\n  if k=address .assignment then v .assignment else\n  if k=address .rank then v .rank else\n  if k=address .width then v .width else\n  if k=address .left then v .left else\n  if k=address .product then v .product else\n  if k=address .result then v .result else\n  if k=address .reader then v .reader else\n  if k=address .ports then v .ports else\n  if k=address .table then v .table else\n  if k=address .valid then v .valid else []\n\n/-- Every named physical register has its declared contents. -/\ntheorem data_get (v : Values) (s : Slot) : data v (address s)=v s := by\n  cases s <;> simp [data,address_injective.eq_iff]\n\n/-- No hidden work data is present in the between-call invariant. -/\ntheorem data_other (v : Values) (k : Stack) (hk : ∀s,k ≠ address s) : data v k=[] := by\n  simp [data,hk]\n\n/-- Exact physical stack replacement agrees with the finite register invariant. -/\ntheorem data_update (v : Values) (s : Slot) (word : List Bool) :\n    data (Function.update v s word)=Function.update (data v) (address s) word := by\n  funext k\n  by_cases hex : ∃t,k=address t\n  · obtain ⟨t,rfl⟩:=hex\n    rw [data_get]\n    by_cases he : t=s\n    · subst t\n      simp\n    · have hn : address t ≠ address s := fun hh=>he (address_injective hh)\n      simp only [Function.update_of_ne he,Function.update_of_ne hn,data_get]\n  · have hk : ∀s,k ≠ address s := by simpa only [not_exists] using hex\n    rw [data_other _ _ hk,Function.update_of_ne (hk s),data_other _ _ hk]\n\n/-- Finite original headers, acquired context and between-call buffers. -/\ndef values (axes precision vertices assignment rank width left product result reader ports table valid : List Bool) : Values\n  | .axes => axes\n  | .precision => precision\n  | .vertices => vertices\n  | .assignment => assignment\n  | .rank => rank\n  | .width => width\n  | .left => left\n  | .product => product\n  | .result => result\n  | .reader => reader\n  | .ports => ports\n  | .table => table\n  | .valid => valid\n\n/-- The actual entry exactly has the four original inputs and no acquired answers. -/\ntheorem initial_data (axes precision vertices assignment : List Bool) :\n    (initial axes precision vertices assignment).data=\n      data (values axes precision vertices assignment [] [] [] [] [] [] [] [] []) := by\n  funext k\n  by_cases hex : ∃s,k=address s\n  · obtain ⟨s,rfl⟩:=hex\n    rw [data_get]\n    cases s <;> rfl\n  · have hk : ∀s,k ≠ address s := by simpa only [not_exists] using hex\n    rw [data_other _ _ hk]\n    have ha : k ≠ SemiprimeD1StackVertexProduct.axes := hk .axes\n    have hp : k ≠ aux .precisionBits := hk .precision\n    have hv : k ≠ aux .verticesCache := hk .vertices\n    have hb : k ≠ aux .assignment := hk .assignment\n    simp only [initial,inputData,Function.update_of_ne hb,Function.update_of_ne hv,\n      Function.update_of_ne hp,Function.update_of_ne ha]\n\nend RiemannGaussian.SemiprimeD1StackVertexProductState\n","RiemannGaussian.SemiprimeD1StackVertexReadBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackVertexReadExecution\nimport Mathlib.Tactic.Linarith\n\n/-! # Actual finite-machine vertex-read time and all-prefix state\nThe argument tapes are explicit physical inputs. Their acquisition/serialization\nis not silently included or treated as free random access.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1StackVertexReadBounds\nopen SemiprimeD1StackVertexRead SemiprimeD1StackVertexReadExecution\nopen SemiprimeD1TensorTapeCodec (tape vectorBits)\nlocal notation \"ctl\" => SemiprimeD1StackVertexRead.control\n\n/-- Genuine target-machine certificate for the actual original vertex read.\nOnly proved exact path-length selection is noncomputable; runtime code is not. -/\nnoncomputable def vertexInTime (v : SemiprimeD1LeafCounter.Vertex)\n    (assignment portTail tableTail : List Bool) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration\n        ⟨some (ctl .start),none,none,input v assignment portTail tableTail,[]⟩)\n      (some (SemiprimeD1StackCalls.configuration\n        ⟨none,none,none,output v assignment portTail tableTail,[]⟩))\n      (budget assignment.length (portTape v.ports).length (tape v.table).length) := by\n  have hx := vertex_run v assignment portTail tableTail\n  let m := Classical.choose hx\n  have hm := Classical.choose_spec hx\n  apply SemiprimeD1StackCalls.evalsCorrect Stack.tableTape Stack.output (ctl .start) code\n  exact ⟨⟨m,hm.2⟩,hm.1⟩\n\n/-- The actual physical unary-port tape is polynomial in original address magnitude. -/\ntheorem portTape_length (M : ℕ) (ports : List ℕ) (hp : ∀p∈ports,p<M) :\n    (portTape ports).length≤2*ports.length*(M+1)+1 := by\n  induction ports with\n  | nil => simp [portTape,vectorBits]\n  | cons p ps ih =>\n    have hh := hp p (by simp)\n    have ht := ih (fun q hq => hp q (by simp [hq]))\n    simp only [portTape,List.map_cons,vectorBits,List.length_cons,\n      SemiprimeSourceHistogramKeyBits.frame_length,List.length_replicate] at ht ⊢\n    nlinarith\n\n/-- Closed fixed-polynomial monotonicity, without substituting an exponential arity. -/\ntheorem budget_mono {W W' P P' T T' : ℕ} (hW : W≤W') (hP : P≤P') (hT : T≤T') :\n    budget W P T≤budget W' P' T' := by\n  unfold budget SemiprimeD1StackGatherBytecode.budget SemiprimeD1StackBitGatherBounds.budget\n    SemiprimeD1StackTreeBytecode.budget\n  have hg := Nat.mul_le_mul (Nat.add_le_add_right (Nat.mul_le_mul_left 3 hW) 8)\n    (Nat.add_le_add_right hP 1)\n  exact Nat.add_le_add_right (Nat.add_le_add (Nat.mul_le_mul_left 5 hg)\n    (Nat.mul_le_mul_left 8 (Nat.add_le_add_right (Nat.mul_le_mul_left 4 hT) 3))) 3\n\n/-- Actual original scope/degree/literal table inventory bounds the executed read. -/\ntheorem sized_vertex_run (M : ℕ) (v : SemiprimeD1LeafCounter.Vertex)\n    (assignment portTail tableTail : List Bool) (hb : assignment.length=M)\n    (hp : ∀p∈v.ports,p<M) :\n    ∃m≤budget M (2*v.ports.length*(M+1)+1) (SemiprimeD1TensorTables.storage v.table),\n      C.run code m ⟨some (ctl .start),none,none,input v assignment portTail tableTail,[]⟩=\n      some ⟨none,none,none,output v assignment portTail tableTail,[]⟩ := by\n  obtain ⟨m,hm,hr⟩ := vertex_run v assignment portTail tableTail\n  exact ⟨m,hm.trans (budget_mono (by omega) (portTape_length M v.ports hp)\n    (SemiprimeD1TensorTapeCodec.tape_le_storage v.table)),hr⟩\n\n/-- Total actual prepared argument payload, including unconsumed suffixes. -/\ndef argumentSize (v : SemiprimeD1LeafCounter.Vertex) (assignment portTail tableTail : List Bool) : ℕ :=\n  (portTape v.ports++portTail).length+assignment.length+(tape v.table++tableTail).length\n\n/-- Every actual source-prefix Boolean cell and finite return-stack symbol is counted. -/\ntheorem prefix_cells (v : SemiprimeD1LeafCounter.Vertex) (assignment portTail tableTail : List Bool)\n    (fuel : ℕ) (out : C.State Stack Label)\n    (h : C.run code fuel ⟨some (ctl .start),none,none,input v assignment portTail tableTail,[]⟩=some out) :\n    (out.data .ports).length+(out.data .assignment).length+(out.data .reader).length+\n      (out.data .scratch).length+(out.data .accumulator).length+(out.data .path).length+\n      (out.data .tableTape).length+(out.data .tasks).length+(out.data .output).length+\n      out.frames.length≤10*(argumentSize v assignment portTail tableTail+fuel) := by\n  have hd := SemiprimeD1StackReturnLink.run_data_bound code fuel\n    (argumentSize v assignment portTail tableTail) _ out (by\n      intro k\n      cases k <;> simp [input,data,argumentSize] <;> omega) h\n  have hf := SemiprimeD1StackCalls.run_frame_bound code fuel _ out h\n  change out.frames.length≤0+fuel at hf\n  have h0 := hd .ports\n  have h1 := hd .assignment\n  have h2 := hd .reader\n  have h3 := hd .scratch\n  have h4 := hd .accumulator\n  have h5 := hd .path\n  have h6 := hd .tableTape\n  have h7 := hd .tasks\n  have h8 := hd .output\n  omega\n\n/-- All actually visited target configurations obey the same complete storage bound. -/\ntheorem machine_prefix_cells (v : SemiprimeD1LeafCounter.Vertex)\n    (assignment portTail tableTail : List Bool) (fuel : ℕ) (cfg : machine.Cfg)\n    (h : (fun c => c.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration\n        ⟨some (ctl .start),none,none,input v assignment portTail tableTail,[]⟩))=some cfg) :\n    (cfg.stk (some Stack.ports)).length+(cfg.stk (some Stack.assignment)).length+\n      (cfg.stk (some Stack.reader)).length+(cfg.stk (some Stack.scratch)).length+\n      (cfg.stk (some Stack.accumulator)).length+(cfg.stk (some Stack.path)).length+\n      (cfg.stk (some Stack.tableTape)).length+(cfg.stk (some Stack.tasks)).length+\n      (cfg.stk (some Stack.output)).length+(cfg.stk none).length≤\n      10*(argumentSize v assignment portTail tableTail+fuel) := by\n  dsimp only [SemiprimeD1StackVertexRead.machine] at cfg h ⊢\n  let start : C.State Stack Label :=\n    ⟨some (ctl .start),none,none,input v assignment portTail tableTail,[]⟩\n  have he := SemiprimeD1StackCalls.run_correct Stack.tableTape Stack.output (ctl .start) code fuel start\n  change (C.run code fuel start).map SemiprimeD1StackCalls.configuration=\n    (fun c => c.bind machine.step)^[fuel] (some (SemiprimeD1StackCalls.configuration start)) at he\n  have hefinal := he.trans h\n  cases hs : C.run code fuel start with\n  | none => rw [hs] at hefinal; cases hefinal\n  | some out =>\n    rw [hs] at hefinal\n    have hc : SemiprimeD1StackCalls.configuration out=cfg := Option.some.inj hefinal\n    rw [←hc]\n    exact prefix_cells v assignment portTail tableTail fuel out hs\n\nend RiemannGaussian.SemiprimeD1StackVertexReadBounds\n","RiemannGaussian.SemiprimeD1StackVertexRecordSpliceExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackVertexRecordSplice\n/-! # Exact EOF cancellation with no accumulated-history traversal\nEvery new record bit is physically reversed once. The native row prefix is\nonly an output specification; it is never supplied to finite machine control.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackVertexRecordSpliceExecution\nopen SemiprimeD1StackVertexRecordSplice SemiprimeD1StackProcedureTrace\n/-- Actual reversal consumes only the new record while prepending onto the unchanged old tail. -/\ntheorem reverse_call (record history : List Bool) :\n    Runs program (2*record.length+3) (.local .start) (data record history) (.local .strip) (data [] (record.reverse++history)) := by\n  apply included_call program id Label.reverse Function.injective_id SemiprimeD1StackReverseWord.code 0\n    (fun _=>rfl) (.local .start) (.local .strip) rfl (2*record.length+2)\n    (SemiprimeD1StackReverseWord.state none record history) (SemiprimeD1StackReverseWord.done (record.reverse++history))\n    _ _ rfl rfl (SemiprimeD1StackReverseWord.reverse_run record history none)\n  · constructor\n    · intro k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk;exact (hk k rfl).elim\n/-- The new singleton EOF is now at the front and is removed by ONE literal Boolean pop. -/\ntheorem strip_run (row history : List Bool) :\n    Runs program 1 (.local .strip) (data [] (false::(row.reverse++history))) (.local .done) (data [] (row.reverse++history)) := by\n  apply one_base program (.local .strip) (.local .done) (.pop 1 (.local .reject) (.local .done) (.local .reject)) _ _ rfl rfl\n  funext k\n  fin_cases k <;> rfl\n/-- Whole SAME actual two-word source, exact raw cancellation, cleared flags and true halt. -/\ntheorem source_run (row history : List Bool) :\n    SemiprimeD1StackCalls.run program (timeBound row) (initial (row++[false]) history)=some (done (row.reverse++history)) := by\n  have h0:=reverse_call (row++[false]) history\n  simp only [List.reverse_append,List.reverse_singleton,List.singleton_append] at h0\n  have h1:=strip_run row history\n  have h:=runs_trans program _ _ _ _ _ _ _ _ h0 h1\n  obtain ⟨finish,hfinish,hAt⟩:=h [] (initial (row++[false]) history) ⟨rfl,rfl,rfl⟩\n  have hhalt:=halt_run program (.local .done) rfl (data [] (row.reverse++history)) [] finish hAt\n  have hr : SemiprimeD1StackCalls.run program ((2*(row++[false]).length+3+1)+1) (initial (row++[false]) history)=\n      some (done (row.reverse++history)) := by\n    rw [SemiprimeD1StackReturnLink.run_add,hfinish,Option.bind_some]\n    exact hhalt\n  have hclock : timeBound row=(2*(row++[false]).length+3+1)+1 := by\n    simp only [timeBound,List.length_append,List.length_singleton]\n    omega\n  rw [hclock]\n  exact hr\n/-- SAME actual caller trace preserves arbitrary real outer returns and stale transient flags. -/\ntheorem source_trace (row history : List Bool) :\n    Runs program (timeBound row-1) (.local .start) (data (row++[false]) history) (.local .done) (data [] (row.reverse++history)) := by\n  have h0:=reverse_call (row++[false]) history\n  simp only [List.reverse_append,List.reverse_singleton,List.singleton_append] at h0\n  have h:=runs_trans program _ _ _ _ _ _ _ _ h0 (strip_run row history)\n  convert h using 1\n  simp only [timeBound,List.length_append,List.length_singleton]\n  omega\n/-- Exact bit-machine clock depends on the NEW row only; the old history is never recopied. -/\ndef machineSplice (row history : List Bool) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial (row++[false]) history))\n      (some (SemiprimeD1StackCalls.configuration (done (row.reverse++history)))) (timeBound row) := by\n  apply SemiprimeD1StackCalls.evalsCorrect 0 1 (.local .start) program\n  exact ⟨⟨timeBound row,source_run row history⟩,le_rfl⟩\nend RiemannGaussian.SemiprimeD1StackVertexRecordSpliceExecution\n","RiemannGaussian.SemiprimeD1StackWeightedModeExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackWeightedModeLoop\n/-! # Actual prepared positive-weight source, including initialization and output\nOnly the physical catalogue and unary precision WIDTH are supplied. The source\ncopies them, pops the budget predecessor, enumerates feasible branches, reverses\nits actual chronological log, and halts with the exact ordered tuple vector.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackWeightedModeExecution\nopen SemiprimeD1StackWeightedMode SemiprimeD1StackWeightedModePrimitives SemiprimeD1StackWeightedModeView\nopen SemiprimeD1StackWeightedModeActivation (join)\nopen SemiprimeD1StackWeightedModeSpec SemiprimeD1StackWeightedModeLoop\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nlocal notation \"ctl\" => (Sum.inl : Control→Label)\n/-- Literal output payloads, not a runtime feasible-tuple generator. -/\ndef payloads (ws:List Nat) (width:Nat) :List (List Bool):=values ws (width-1) []\n/-- Exact initialized two-input store: no result, traversal or count is an input. -/\ntheorem input_store (cat width:List Bool) :input cat width=store (base cat width [] [] []):=by\n  funext k;cases k <;> rfl\n/-- A physical unary predecessor is one real pop, including WIDTH zero. -/\ntheorem unary_tail (n:Nat) :(unary n).tail=unary (n-1):=by\n  cases n with\n  | zero=>rfl\n  | succ n=>simp only [unary_succ,List.tail_cons,Nat.add_sub_cancel]\n/-- Exact paid initial copies, predecessor pop and path terminator push. -/\ntheorem setup_run (ws:List Nat) (width:Nat) :\n    Runs program (5*(vector ws).length+5*width+10) (ctl .start)\n      (input (vector ws) (unary width)) (ctl .root)\n      (store (node (vector ws) (unary width) ws (width-1) (path []) [] [] [])):=by\n  let a:=base (vector ws) (unary width) [] [] []\n  let b:Words:={a with weights:=vector ws}\n  let c:Words:={b with budget:=unary width}\n  let d:Words:={c with budget:=unary (width-1)}\n  have h0:=copy_call .catalogue .start .widthCopy rfl (store a) (vector ws) [] rfl rfl rfl\n  rw [List.append_nil,store_write] at h0\n  change Runs program (5*(vector ws).length+4) _ _ _ (store b) at h0\n  have h1:=copy_call .width .widthCopy .budgetPred rfl (store b) (unary width) [] rfl rfl rfl\n  rw [List.append_nil,store_write,unary_length] at h1\n  change Runs program (5*width+4) _ _ _ (store c) at h1\n  have h2:=pop_run .budgetPred (ctl .pathSeed) (ctl .pathSeed) (ctl .pathSeed) .budget\n    (store c) (unary width) rfl rfl\n  have hchoose:SemiprimeD1StackBytecode.choose (ctl .pathSeed) (ctl .pathSeed) (ctl .pathSeed)\n      (unary width).head?=ctl .pathSeed:=by cases (unary width).head? with\n    | none=>rfl\n    | some b=>cases b <;> rfl\n  rw [hchoose,unary_tail,store_write] at h2\n  change Runs program 1 _ _ _ (store d) at h2\n  have h3:=push_run .pathSeed (ctl .root) .path false (store d) rfl\n  rw [store_write] at h3\n  change Runs program 1 _ _ _ (store (node (vector ws) (unary width) ws (width-1) (path []) [] [] [])) at h3\n  have h:=join h0 (join h1 (join h2 h3))\n  rw [input_store]\n  convert h using 1;omega\n/-- Literal reverse log followed by its one physical false marker is the codec vector. -/\ntheorem history_vector (xs:List (List Bool)) :(history xs []).reverse++[false]=vectorBits xs:=by\n  have hfold:xs.foldr (fun x tail=>row x++tail) []++[false]=vectorBits xs:=by\n    induction xs with\n    | nil=>rfl\n    | cons x xs ih=>\n      rw [List.foldr_cons,List.append_assoc]\n      change (true::SemiprimeSourceHistogramKeyBits.frame x [])++_=_\n      rw [List.cons_append,SemiprimeD1TensorTapeCodec.frame_append,List.nil_append,ih]\n      rfl\n  simpa only [history,List.append_nil,List.reverse_reverse] using hfold\n/-- Exact stopped data retains both actual inputs and contains only their computed tuple vector. -/\ndef result (ws:List Nat) (width:Nat) :Stack→List Bool:=\n  store (base (vector ws) (unary width) [] [] (vectorBits (payloads ws width)))\n/-- Actual stopped source state; all work words and real return frames are empty. -/\ndef done (ws:List Nat) (width:Nat) :C.State Stack Label:=⟨none,none,none,result ws width,[]⟩\n/-- Own complete primitive allowance includes the physical output reversal. -/\ndef timeBound (ws:List Nat) (width:Nat) :Nat:=\n  nodeBudget ws (width-1) 1+5*(vector ws).length+5*width+\n    2*(history (payloads ws width) []).length+17\nattribute [local irreducible] nodeBudget\n/-- The whole actual source executes from its two physical inputs to the literal ordered vector. -/\ntheorem source_trace (ws:List Nat) (hw:∀w∈ws,0 < w) (width:Nat) :\n    ∃t,t+1 ≤ timeBound ws width ∧ Runs program t (ctl .start)\n      (input (vector ws) (unary width)) (ctl .done) (result ws width):=by\n  obtain ⟨t,ht,hr⟩:=visit_run (vector ws) (unary width) ws hw (width-1) [] [] [] []\n  change t ≤ nodeBudget ws (width-1) 1 at ht\n  change Runs program t (ctl .visit)\n    (store (node (vector ws) (unary width) ws (width-1) (path []) [] [] []))\n    (ctl .returning) (store (base (vector ws) (unary width) [] (history (payloads ws width) []) [])) at hr\n  have h0:=setup_run ws width\n  have h1:=recursive_call .root .finishSeed _ _ t rfl hr\n  let v:=base (vector ws) (unary width) [] (history (payloads ws width) []) []\n  let s:Words:={v with output:=[false]}\n  have h2:=push_run .finishSeed (ctl .reverse) .output false (store v) rfl\n  rw [store_write] at h2\n  change Runs program 1 _ _ _ (store s) at h2\n  have h3:=reverse_call (store s) (history (payloads ws width) []) [false] rfl rfl\n  rw [store_write,store_write,history_vector] at h3\n  change Runs program (2*(history (payloads ws width) []).length+3) _ _ _ (result ws width) at h3\n  have h:=join h0 (join h1 (join h2 h3))\n  refine ⟨(5*(vector ws).length+5*width+10)+((t+2)+(1+(2*(history (payloads ws width) []).length+3))),?_,h⟩\n  unfold timeBound\n  omega\n/-- Exact source execution includes its final real halt, with no advised tuple or visit count. -/\ntheorem source_run (ws:List Nat) (hw:∀w∈ws,0 < w) (width:Nat) :\n    ∃t ≤ timeBound ws width,C.run program t (initial (vector ws) (unary width))=some (done ws width):=by\n  obtain ⟨t,ht,hr⟩:=source_trace ws hw width\n  obtain ⟨finish,hf,ha⟩:=hr [] (initial (vector ws) (unary width)) ⟨rfl,rfl,rfl⟩\n  have hh:=halt_run program (ctl .done) rfl (result ws width) [] finish ha\n  refine ⟨t+1,ht,?_⟩\n  rw [SemiprimeD1StackReturnLink.run_add,hf,Option.bind_some]\n  exact hh\n/-- Original native feasible tuple order, encoded by the actual physical output. -/\ntheorem output_exact (ws:List Nat) (width:Nat) :\n    (done ws width).data .output=\n      vectorBits ((SemiprimeD1WeightedTuples.tuples ws (width-1)).map vector):=by\n  simp only [done,result,store,base,payloads,values,List.nil_append]\nend RiemannGaussian.SemiprimeD1StackWeightedModeExecution\n","RiemannGaussian.SemiprimeD1StackWeightedModeRound":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackWeightedModeEmit\nimport RiemannGaussian.SemiprimeD1StackWeightedModeSubtract\n/-! # Whole real weighted-node entry, restoration, successor and failed return -/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackWeightedModeRound\nopen SemiprimeD1StackWeightedMode SemiprimeD1StackWeightedModePrimitives SemiprimeD1StackWeightedModeView\nopen SemiprimeD1StackWeightedModeActivation SemiprimeD1StackWeightedModeCleanup\nopen SemiprimeD1StackWeightedModeEmit\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nlocal notation \"ctl\" => (Sum.inl : Control→Label)\n/-- Every positive actual unary weight has a real marker to drive the finite guard. -/\ntheorem unary_head (w:Nat) (hw:0 < w) :(unary w).head?=some true:=by\n  cases w with\n  | zero=>omega\n  | succ w=>rw [unary_succ];rfl\n/-- The real next-weight parse and guard enter exponent zero of exactly that positive weight. -/\ntheorem enter (cat width:List Bool) (w:Nat) (ws:List Nat) (R:Nat) (path frames hist out:List Bool)\n    (hw:0 < w) :\n    Runs program (8*w+10) (ctl .visit) (store (node cat width (w::ws) R path frames hist out))\n      (ctl (.save 4)) (store (loop cat width w ws R 0 path frames hist out)):=by\n  let v:=node cat width (w::ws) R path frames hist out\n  let v1:Words:={v with weights:=frame (unary w) (vector ws)}\n  let v2:Words:={v1 with weights:=vector ws,weight:=unary w,valid:=[true]}\n  let v3:Words:={v2 with valid:=[]}\n  have h0:=pop_run .visit (ctl .abort) (ctl .tupleSeed) (ctl .weightRead) .weights (store v)\n    (true::frame (unary w) (vector ws)) rfl rfl\n  rw [store_write] at h0\n  change Runs program 1 _ _ (ctl .weightRead) (store v1) at h0\n  have h1:=field_call .weight .weightRead .weightValid rfl (store v1) (unary w) (vector ws) rfl rfl rfl rfl\n  rw [store_write,store_write,store_write,unary_length] at h1\n  change Runs program (8*w+7) _ _ _ (store v2) at h1\n  have h2:=pop_run .weightValid (ctl .abort) (ctl .abort) (ctl .weightPositive) .valid (store v2) [true] rfl rfl\n  rw [store_write] at h2\n  change Runs program 1 _ _ (ctl .weightPositive) (store v3) at h2\n  have h3:Runs program 1 (ctl .weightPositive) (store v3) (ctl (.save 4)) (store v3):=by\n    apply one_base program _ _ (.peek .weight (ctl .abort) (ctl (.save 4)) (ctl (.save 4))) _ _ rfl\n    · simp only [SemiprimeD1StackBytecode.execute,show store v3 .weight=unary w from rfl,unary_head w hw,\n        SemiprimeD1StackBytecode.choose]\n    · rfl\n  have hh:=join h0 (join h1 (join h2 h3))\n  change Runs program (1+((8*w+7)+(1+1))) _ _ _ (store (loop cat width w ws R 0 path frames hist out)) at hh\n  convert hh using 1;omega\n/-- Every actual child return restores the full five-word activation by real parsers. -/\ntheorem restore (cat width:List Bool) (w:Nat) (ws:List Nat) (R e:Nat) (path frames hist out:List Bool) :\n    Runs program (8*mass (loop cat width w ws R e path frames hist out)+41) (ctl .afterChild)\n      (store (base cat width (activation w ws R e path frames) hist out)) (ctl .copyWeight)\n      (store (loop cat width w ws R e path frames hist out)):=by\n  let v:=base cat width frames hist out\n  let fields:Fin 5→List Bool:=![unary w,vector ws,unary R,unary e,path]\n  have h0:Runs program 1 (ctl .afterChild) (store (restored v fields 0 frames))\n      (ctl (.restore 0)) (store (restored v fields 0 frames)):=by\n    exact one_base program _ _ (.jump (ctl (.restore 0))) _ _ rfl rfl rfl\n  have h1:=restore_run v fields frames rfl\n  have hh:=join h0 h1\n  change Runs program (1+(8*((unary w).length+(vector ws).length+(unary R).length+(unary e).length+path.length)+40))\n    (ctl .afterChild) (store (base cat width (activation w ws R e path frames) hist out)) (ctl .copyWeight)\n    (store (loop cat width w ws R e path frames hist out)) at hh\n  convert hh using 1\n  dsimp only [mass,loop,node,base]\n  omega\n/-- A feasible successor is created only after actually subtracting its full positive weight. -/\ntheorem successor (cat width:List Bool) (w:Nat) (ws:List Nat) (R e:Nat) (path frames hist out:List Bool) :\n    Runs program (7*w+6) (ctl .copyWeight) (store (loop cat width w ws (w+R) e path frames hist out))\n      (ctl (.save 4)) (store (loop cat width w ws R (e+1) path frames hist out)):=by\n  let v:=loop cat width w ws (w+R) e path frames hist out\n  let v1:Words:={v with subTodo:=unary w}\n  have h0:=copy_call .weight .copyWeight .subtract rfl (store v) (unary w) [] rfl rfl rfl\n  rw [List.append_nil,store_write,unary_length] at h0\n  change Runs program (5*w+4) _ _ _ (store v1) at h0\n  have h1:=SemiprimeD1StackWeightedModeSubtract.success v1 w R e rfl rfl rfl\n  have hh:=join h0 h1\n  change Runs program ((5*w+4)+(2*w+2)) _ _ _ (store (loop cat width w ws R (e+1) path frames hist out)) at hh\n  convert hh using 1;omega\n/-- The sole failed next-exponent test clears all mutable words and returns, creating no child. -/\ntheorem failed_return (cat width:List Bool) (w:Nat) (ws:List Nat) (R e:Nat) (path frames hist out:List Bool)\n    (hr:R < w) :\n    ∃t ≤20*(mass (loop cat width w ws R e path frames hist out)+1)+50,\n      Runs program t (ctl .copyWeight) (store (loop cat width w ws R e path frames hist out))\n        (ctl .returning) (store (base cat width frames hist out)):=by\n  have hw:R+1 ≤ w:=by omega\n  obtain ⟨d,hd⟩:=Nat.exists_eq_add_of_le hw\n  have hwd:w=R+d+1:=by omega\n  let v:=loop cat width w ws R e path frames hist out\n  let v1:Words:={v with subTodo:=unary w}\n  let v2:Words:={v with subTodo:=[],budget:=[]}\n  have h0:=copy_call .weight .copyWeight .subtract rfl (store v) (unary w) [] rfl rfl rfl\n  rw [List.append_nil,store_write,unary_length] at h0\n  change Runs program (5*w+4) _ _ _ (store v1) at h0\n  have h1:=SemiprimeD1StackWeightedModeSubtract.failure v1 R d (by change unary w=unary (R+d+1);rw [hwd]) rfl\n  change Runs program (2*R+d+3) _ _ _ (store v2) at h1\n  have h2:=cleanup_run v2\n  change Runs program (cleanupMass v2+9) _ _ _ (store (base cat width frames hist out)) at h2\n  refine ⟨(5*w+4)+((2*R+d+3)+(cleanupMass v2+9)),?_,join h0 (join h1 h2)⟩\n  dsimp only [cleanupMass,v2,v,mass,loop,node,base]\n  simp only [unary_length,List.length_nil,Nat.add_zero]\n  omega\n/-- The empty suffix emits exactly the complete actual chosen path and executes real cleanup. -/\ntheorem leaf_visit (cat width:List Bool) (R:Nat) (chosen:List Nat) (frames hist out:List Bool) :\n    ∃t ≤70*(R+(path chosen).length+1)+1,\n      Runs program t (ctl .visit) (store (node cat width [] R (path chosen) frames hist out))\n        (ctl .returning) (store (base cat width frames ((row (vector chosen)).reverse++hist) out)):=by\n  let fields:=chosen.reverse.map unary\n  let v:=node cat width [] R (path chosen) frames hist out\n  have h0:=pop_run .visit (ctl .abort) (ctl .tupleSeed) (ctl .weightRead) .weights (store v) [false] rfl rfl\n  rw [store_write] at h0\n  change Runs program 1 _ _ (ctl .tupleSeed)\n    (store {base cat width frames hist out with budget:=unary R,path:=vectorBits fields}) at h0\n  obtain ⟨t,ht,h1⟩:=leaf_run cat width R fields frames hist out\n  have htuple:vectorBits fields.reverse=vector chosen:=by\n    simp only [fields,List.map_reverse,List.reverse_reverse,vector]\n  rw [htuple] at h1\n  refine ⟨1+t,by change 1+t ≤70*(R+(vectorBits fields).length+1)+1;omega,join h0 h1⟩\nend RiemannGaussian.SemiprimeD1StackWeightedModeRound\n","RiemannGaussian.SemiprimeD1StackWordEqualBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackWordEqualExecution\n\n/-! # Linear binary-value comparison and original public equality semantics\nThis physical bit comparison directly handles arbitrary high-zero padding;\nit does not construct either numeric value or call two subtraction routines.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 800000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackWordEqualBounds\nopen SemiprimeD1StackWordEqual SemiprimeD1StackWordEqualExecution SemiprimeD1StackBytecode\nopen SemiprimeD1StackAdder (Stack store)\nopen SemiprimeBitArithmetic\n\n/-- Actual source certificate; expected numeric equality appears only in its specification. -/\ndef sourceEqual (left right : List Bool) :\n    StateTransition.EvalsToInTime (step code) (state (some .loop) none left right [])\n      (some (state none none [] [] [decide (bitValue left=bitValue right)]))\n      (2*(left.length+right.length)+8) :=\n  ⟨⟨_,source_run left right none⟩,executionTime_le left right⟩\n/-- Actual four-stack finite-machine equality with the SAME linear transition bound. -/\ndef machineEqual (left right : List Bool) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackBytecode.configuration (state (some .loop) none left right []))\n      (some (SemiprimeD1StackBytecode.configuration\n        (state none none [] [] [decide (bitValue left=bitValue right)])))\n      (2*(left.length+right.length)+8) :=\n  SemiprimeD1StackBytecode.evalsCorrect Stack.left Stack.output Label.loop code _ _ _ (sourceEqual left right)\n\n/-- Exact Boolean result of the frozen public equality checker, now acquired\nby direct physical digit comparisons instead of two subtractor calls. -/\ntheorem original_answer (left right : List Bool) :\n    decide (bitValue left=bitValue right)=(SemiprimeMacroEntryBitPrimitives.equalBits left right).accepted := by\n  by_cases h : bitValue left=bitValue right\n  · have ho:=(SemiprimeMacroEntryBitPrimitives.equalBits_correct left right).mpr h\n    simp only [h,decide_true,ho]\n  · have ho : (SemiprimeMacroEntryBitPrimitives.equalBits left right).accepted=false := by\n      apply Bool.eq_false_iff.mpr\n      intro ht\n      exact h ((SemiprimeMacroEntryBitPrimitives.equalBits_correct left right).mp ht)\n    simp only [h,decide_false,ho]\n\n/-- Every successful prefix is bounded by the actually proved halt. -/\ntheorem prefix_fuel_le (left right : List Bool) (fuel : ℕ) (out : State Stack Label)\n    (hr : run code fuel (state (some .loop) none left right [])=some out) :\n    fuel ≤ 2*(left.length+right.length)+8 := by\n  have ht:=SemiprimeD1StackBytecodeBounds.fuel_le_halt code\n    (state (some .loop) none left right [])\n    (state none none [] [] [decide (bitValue left=bitValue right)]) out\n    (executionTime left right) fuel (source_run left right none) rfl hr\n  exact ht.trans (executionTime_le left right)\n\n/-- Every real visited Boolean cell is counted, including both mismatch tails. -/\ntheorem prefix_cells (left right : List Bool) (fuel : ℕ) (out : State Stack Label)\n    (hr : run code fuel (state (some .loop) none left right [])=some out) :\n    SemiprimeD1StackBytecodeBounds.cells out ≤ 10*(left.length+right.length)+40 := by\n  have ht:=prefix_fuel_le left right fuel out hr\n  have hc:=SemiprimeD1StackBytecodeBounds.run_cells code fuel _ out hr\n  have hi : SemiprimeD1StackBytecodeBounds.cells (state (some .loop) none left right [])=\n      left.length+right.length := by\n    have hu : (Finset.univ : Finset Stack)={.left,.right,.scratch,.output} := by decide\n    simp [SemiprimeD1StackBytecodeBounds.cells,hu,state,store]\n  have hk : Fintype.card Stack=4 := by decide\n  rw [hi,hk] at hc\n  omega\n\n/-- The same linear storage cap holds at every actually reached compiled-machine prefix. -/\ntheorem machine_prefix_cells (left right : List Bool) (fuel : ℕ) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackBytecode.configuration (state (some .loop) none left right [])))=some cfg) :\n    (∑k : Stack,(cfg.stk k).length) ≤ 10*(left.length+right.length)+40 := by\n  have he:=SemiprimeD1StackBytecode.run_correct Stack.left Stack.output Label.loop code fuel\n    (state (some .loop) none left right [])\n  change (run code fuel (state (some .loop) none left right [])).map SemiprimeD1StackBytecode.configuration=\n    (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackBytecode.configuration (state (some .loop) none left right []))) at he\n  have hh:=he.trans hr\n  cases hc:run code fuel (state (some .loop) none left right []) with\n  | none => rw [hc] at hh;cases hh\n  | some out =>\n    rw [hc] at hh\n    have hcfg : SemiprimeD1StackBytecode.configuration out=cfg := Option.some.inj hh\n    subst cfg\n    exact prefix_cells left right fuel out hc\n\nend RiemannGaussian.SemiprimeD1StackWordEqualBounds\n","RiemannGaussian.SemiprimeD1TensorTapeLookup":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1TensorTapeCodec\n\n/-! # Sequential physical tensor-table tape lookup\nThe unselected subtree is actually traversed and discarded. No native table\npointer or random-access operation occurs in the lookup runtime.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeD1TensorTapeLookup\nopen SemiprimeD1TensorTables SemiprimeD1TensorTapeCodec\n\n/-- Scan past one tagged table, including all unselected coefficient payloads. -/\ndef skip : ℕ → List Bool → Parsed\n  | 0,[] => ⟨[],[],2⟩\n  | 0,_::tail => let out:=parseVector tail; ⟨[],out.rest,out.clock+3⟩\n  | _+1,[] => ⟨[],[],2⟩\n  | n+1,_::tail =>\n    let low:=skip n tail\n    let high:=skip n low.rest\n    ⟨[],high.rest,low.clock+high.clock+5⟩\n\n/-- Actual assignment-bit-controlled sequential lookup, preserving the tail. -/\ndef read : ℕ → List Bool → List Bool → Parsed\n  | 0,_,[] => ⟨[],[],2⟩\n  | 0,_,_::tail => let out:=parseVector tail; ⟨out.words,out.rest,out.clock+3⟩\n  | _+1,_,[] => ⟨[],[],2⟩\n  | n+1,bits,_::tail =>\n    if bits.head?.getD false then\n      let low:=skip n tail\n      let high:=read n bits.tail low.rest\n      ⟨high.words,high.rest,low.clock+high.clock+7⟩\n    else\n      let low:=read n bits.tail tail\n      let high:=skip n low.rest\n      ⟨low.words,high.rest,low.clock+high.clock+7⟩\n\n/-- Skipping an actual serialized table reaches its exact following tape. -/\ntheorem skip_correct {n : ℕ} (table : Table n) (tail : List Bool) :\n    (skip n (tape table++tail)).rest=tail := by\n  induction table generalizing tail with\n  | leaf words => simpa only [tape,List.cons_append,skip] using (parseVector_correct words tail).2\n  | fork low high ihl ihh =>\n    simp only [tape,List.cons_append,List.append_assoc,skip,ihl,ihh]\n\n/-- The actual fixed-scope table code cannot be a proper prefix of another. -/\ntheorem prefix_free {n : ℕ} (table other : Table n) (suffix : List Bool)\n    (h : tape other=tape table++suffix) : suffix=[] := by\n  have hl:=skip_correct table suffix\n  have hr:=skip_correct other []\n  simp only [List.append_nil] at hr\n  rw [←h] at hl\n  exact hl.symm.trans hr\n\n/-- Physical sequential lookup preserves the literal original coefficient words. -/\ntheorem read_correct {n : ℕ} (table : Table n) (bits tail : List Bool) :\n    (read n bits (tape table++tail)).words=(lookup table bits).words ∧\n      (read n bits (tape table++tail)).rest=tail := by\n  induction table generalizing bits tail with\n  | leaf words =>\n    have h:=parseVector_correct words tail\n    simp only [tape,List.cons_append,read,lookup,SemiprimeD1JetAxes.copyVector_value,h.1,h.2,and_self]\n  | @fork n low high ihl ihh =>\n    have hl:=ihl bits.tail (tape high++tail)\n    have hh:=ihh bits.tail tail\n    simp only [tape,List.cons_append,List.append_assoc,read,lookup]\n    split_ifs\n    · simp only [skip_correct,hh.1,hh.2,and_self]\n    · simp only [hl.1,hl.2,skip_correct,and_self]\n\n/-- All unselected subtree scans and copied fields cost linear actual tape work. -/\ntheorem skip_clock {n : ℕ} (table : Table n) (tail : List Bool) :\n    (skip n (tape table++tail)).clock ≤ 8*(tape table).length := by\n  induction table generalizing tail with\n  | leaf words =>\n    have h:=parseVector_clock words tail\n    simp only [tape,List.cons_append,skip,List.length_cons]\n    omega\n  | fork low high ihl ihh =>\n    have hl:=ihl (tape high++tail)\n    have hh:=ihh tail\n    simp only [tape,List.cons_append,List.append_assoc,skip,skip_correct,List.length_cons,List.length_append]\n    omega\n\n/-- The selected and unselected branches are both actually paid, never free skips. -/\ntheorem read_clock {n : ℕ} (table : Table n) (bits tail : List Bool) :\n    (read n bits (tape table++tail)).clock ≤ 8*(tape table).length := by\n  induction table generalizing bits tail with\n  | leaf words =>\n    have h:=parseVector_clock words tail\n    simp only [tape,List.cons_append,read,List.length_cons]\n    omega\n  | @fork n low high ihl ihh =>\n    have hl:=ihl bits.tail (tape high++tail)\n    have hh:=ihh bits.tail tail\n    have hsl:=skip_clock low (tape high++tail)\n    have hsh:=skip_clock high tail\n    have hrl:=(read_correct low bits.tail (tape high++tail)).2\n    simp only [tape,List.cons_append,List.append_assoc,read,skip_correct,List.length_cons,List.length_append]\n    split_ifs\n    · dsimp only\n      omega\n    · rw [hrl]\n      dsimp only\n      omega\n\n/-- Closed serialization and sequential lookup, retaining both actual reports. -/\ndef fromTable {n : ℕ} (table : Table n) (bits : List Bool) : SemiprimeD1JetRingBits.Run :=\n  let encoded:=serialize table\n  let out:=read n bits encoded.bits\n  ⟨out.words,encoded.clock+out.clock+4⟩\n\n/-- No serialized bank or value advice is needed by the closed table endpoint. -/\ntheorem fromTable_words {n : ℕ} (table : Table n) (bits : List Bool) :\n    (fromTable table bits).words=(lookup table bits).words := by\n  have h:=(read_correct table bits []).1\n  simpa only [fromTable,serialize_bits,List.append_nil] using h\n\n/-- Setup copies and unselected scans are included in the full actual report. -/\ntheorem fromTable_clock {n : ℕ} (table : Table n) (bits : List Bool) :\n    (fromTable table bits).clock ≤ 8*(n+2)*(tape table).length+4 := by\n  have hs:=serialize_clock table\n  have hr:=read_clock table bits []\n  simp only [List.append_nil] at hr\n  simp only [fromTable,serialize_bits]\n  nlinarith\n\n/-- Original canonical coefficient/degree caps bound the complete physical path. -/\ntheorem fromTable_good_clock (ctx : SemiprimeD1JetAxes.Context) {n : ℕ} (table : Table n)\n    (hg : Good ctx table) (bits : List Bool) :\n    (fromTable table bits).clock ≤\n      8*(n+2)*((2*ctx.rank*(ctx.precision+1)+3)*2^n)+4 := by\n  apply (fromTable_clock table bits).trans\n  have h:=tape_length ctx table hg\n  gcongr\n  omega\n\n/-- Literal tree depth is itself bounded by its acquired serialized storage. -/\ntheorem tape_depth {n : ℕ} (table : Table n) : n+1 ≤ (tape table).length := by\n  induction table with\n  | leaf words => simp only [tape,List.length_cons];omega\n  | fork low high ihl ihh =>\n    simp only [tape,List.length_cons,List.length_append]\n    omega\n\n/-- A quadratic actual-tape bound requires no caller-supplied degree cap. -/\ntheorem fromTable_storage_clock {n : ℕ} (table : Table n) (bits : List Bool) :\n    (fromTable table bits).clock ≤ 8*((tape table).length+1)*(tape table).length+4 := by\n  apply (fromTable_clock table bits).trans\n  have h:=tape_depth table\n  exact Nat.add_le_add_right (Nat.mul_le_mul_right _\n    (Nat.mul_le_mul_left 8 (by omega : n+2 ≤ (tape table).length+1))) 4\n\nend RiemannGaussian.SemiprimeD1TensorTapeLookup\n","RiemannGaussian.SemiprimeD1TensorTapePublicReport":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1TensorTapeBinaryFactorExecution\nimport RiemannGaussian.SemiprimeD1PublicRecoveryBudget\n\n/-! # Exact public report aggregation for the tape-backed binary execution\nThe prefix budget in internal composition refers to this actual closed program.\nNo count/backend supplier is a runtime input and no old query clock is reused.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 400000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1TensorTapePublicReport\nopen SemiprimePublicAcquiredExecution SemiprimeBitArithmetic SemiprimeBitDivision\nattribute [local irreducible] SemiprimeD1TensorTapePublicSearch.search\n  SemiprimeD1PhysicalPublicSearch.search SemiprimeD1PublicOperandBits.run\n  SemiprimeD1FactorValidationBits.run\n\n/-- Sum the actual retained fields from one cached binary-execution report. -/\ndef work (input : List Bool) : ℕ :=\n  let out:=SemiprimeD1TensorTapeBinaryFactorExecution.run input\n  out.queryWork+out.arithmeticClock+out.metadataWork\n\n/-- The binary endpoint retains exactly the actually executed search query sum. -/\ntheorem run_queryWork_eq (input : List Bool) (hN : 0<bitValue input) :\n    (SemiprimeD1TensorTapeBinaryFactorExecution.run input).queryWork=\n      ((SemiprimeD1TensorTapePublicSearch.queriedPrefixes (bitValue input) hN).map\n        (fun fixed => (SemiprimeD1TensorTapePublicCounter.prefixRun (bitValue input) hN fixed).clock)).sum := by\n  have hz:=(nonzeroBits_correct input).mpr hN\n  have he:=SemiprimeD1TensorTapePublicSearch.search_queryWork_eq (bitValue input) hN\n  dsimp only [SemiprimeD1TensorTapeBinaryFactorExecution.run]\n  rw [dite_eq_left hz]\n  split <;> exact he\n\n/-- Internal uniform-prefix composition counts every actual repeated acquisition. -/\ntheorem run_queryWork (input : List Bool) (hN : 0<bitValue input) (C : ℕ)\n    (hC : ∀ fixed : List (Fin (wireCount (bitValue input))×Bool),\n      fixed.length ≤ wireCount (bitValue input) →\n      (SemiprimeD1TensorTapePublicCounter.prefixRun (bitValue input) hN fixed).clock ≤ C) :\n    (SemiprimeD1TensorTapeBinaryFactorExecution.run input).queryWork ≤\n      (wireCount (bitValue input)+1)*C := by\n  have hz:=(nonzeroBits_correct input).mpr hN\n  have hs:=SemiprimeD1TensorTapePublicSearch.search_queryWork (bitValue input) hN C hC\n  dsimp only [SemiprimeD1TensorTapeBinaryFactorExecution.run]\n  rw [dite_eq_left hz]\n  split <;> exact hs\n\n/-- The final physical factor bytes are preserved literally on every input. -/\ntheorem run_factors_eq_physical (input : List Bool) :\n    (SemiprimeD1TensorTapeBinaryFactorExecution.run input).factors=\n      (SemiprimeD1BinaryFactorExecution.run input).factors := by\n  by_cases hz : (nonzeroBits input).nonzero=true\n  · have hN:=(nonzeroBits_correct input).mp hz\n    have hv:=congrArg SemiprimeCountRecovery.SearchResult.values\n      (SemiprimeD1TensorTapePublicSearch.search_result_eq_physical (bitValue input) hN)\n    dsimp only [SemiprimeD1TensorTapeBinaryFactorExecution.run,SemiprimeD1BinaryFactorExecution.run]\n    simp only [dite_eq_left hz]\n    rw [hv]\n    cases (SemiprimeD1PhysicalPublicSearch.search (bitValue input) hN).result.values <;> rfl\n  · simp only [SemiprimeD1TensorTapeBinaryFactorExecution.run,SemiprimeD1BinaryFactorExecution.run,dite_eq_right hz]\n\n/-- Only unchanged decoder/validation/control reports agree after exact branch\nand metadata refinement. Changed query and recursion reports are excluded. -/\ntheorem run_local_eq (input : List Bool) :\n    (SemiprimeD1TensorTapeBinaryFactorExecution.run input).arithmeticClock+\n      (SemiprimeD1TensorTapeBinaryFactorExecution.run input).metadataWork=\n    (SemiprimeD1BinaryFactorExecution.run input).arithmeticClock+\n      (SemiprimeD1BinaryFactorExecution.run input).metadataWork := by\n  by_cases hz : (nonzeroBits input).nonzero=true\n  · have hN:=(nonzeroBits_correct input).mp hz\n    have hv:=congrArg SemiprimeCountRecovery.SearchResult.values\n      (SemiprimeD1TensorTapePublicSearch.search_result_eq_physical (bitValue input) hN)\n    have hm:=SemiprimeD1TensorTapePublicSearch.search_metadata_eq_physical (bitValue input) hN\n    dsimp only [SemiprimeD1TensorTapeBinaryFactorExecution.run,SemiprimeD1BinaryFactorExecution.run]\n    simp only [dite_eq_left hz]\n    rw [hv,hm]\n    cases (SemiprimeD1PhysicalPublicSearch.search (bitValue input) hN).result.values <;> rfl\n  · simp only [SemiprimeD1TensorTapeBinaryFactorExecution.run,SemiprimeD1BinaryFactorExecution.run,dite_eq_right hz]\n\n/-- Physical decoding and proper-divisor/cofactor validation have the original\nproved polynomial budget because their actual inputs and operations agree. -/\ntheorem run_local_work (input : List Bool) (hc : SemiprimeSourceCompactBits.Compact input)\n    (hN : 0<bitValue input) :\n    (SemiprimeD1TensorTapeBinaryFactorExecution.run input).arithmeticClock+\n      (SemiprimeD1TensorTapeBinaryFactorExecution.run input).metadataWork ≤\n        SemiprimeD1PublicRecoveryBudget.localBudget (wireCount (bitValue input)) := by\n  rw [run_local_eq]\n  exact SemiprimeD1PublicRecoveryBudget.run_local_work input hc hN\n\n/-- Actual new public report from a derived uniform actual-prefix bound. -/\ntheorem work_le (input : List Bool) (hc : SemiprimeSourceCompactBits.Compact input)\n    (hN : 0<bitValue input) (C : ℕ)\n    (hC : ∀ fixed : List (Fin (wireCount (bitValue input))×Bool),\n      fixed.length ≤ wireCount (bitValue input) →\n      (SemiprimeD1TensorTapePublicCounter.prefixRun (bitValue input) hN fixed).clock ≤ C) :\n    work input ≤ (wireCount (bitValue input)+1)*C+\n      SemiprimeD1PublicRecoveryBudget.localBudget (wireCount (bitValue input)) := by\n  have hq:=run_queryWork input hN C hC\n  have hl:=run_local_work input hc hN\n  unfold work\n  dsimp only\n  omega\n\n/-- Fixed recovery constants precede the complete original-input family. The\nremaining premise is internal actual-prefix composition, not a runtime oracle. -/\ntheorem exists_original_join : ∃ C₀ k : ℕ,∀ input : List Bool,\n    SemiprimeSourceCompactBits.Compact input → ∀ hN : 0<bitValue input,∀ C : ℕ,\n    (∀ fixed : List (Fin (wireCount (bitValue input))×Bool),\n      fixed.length ≤ wireCount (bitValue input) →\n      (SemiprimeD1TensorTapePublicCounter.prefixRun (bitValue input) hN fixed).clock ≤ C) →\n    work input ≤ (wireCount (bitValue input)+1)*C+\n      C₀*(SemiprimeMacroParameters.bitLength (bitValue input)+1)^k := by\n  obtain ⟨C₀,k,hlocal⟩:=SemiprimeD1PublicRecoveryBudget.exists_original_local_work\n  refine ⟨C₀,k,?_⟩\n  intro input hc hN C hC\n  have hq:=run_queryWork input hN C hC\n  have hl:=hlocal input hc hN\n  rw [←run_local_eq input] at hl\n  unfold work\n  dsimp only\n  omega\n\nend RiemannGaussian.SemiprimeD1TensorTapePublicReport\n","RiemannGaussian.SemiprimeD1TensorTapeTreeMachine":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1TensorTapeVectorMachine\nimport RiemannGaussian.SemiprimeD1TensorTapeLookup\n\n/-! # Fixed Boolean-stack tree lookup\nThe task stack stores seek/skip bits. Forks push exactly two tasks. Every skipped\nsubtree is scanned physically; only the selected literal vector is copied.\nAll lengths and tree depths below are proof indices, not control registers.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1TensorTapeTreeMachine\nopen Turing Turing.TM2 Turing.TM2.Stmt\nopen SemiprimeD1TensorTapeCodec (vectorBits tape)\nopen SemiprimeSourceHistogramKeyBits (frame)\n\n/-- Fixed physical Boolean stacks. -/\ninductive Stack | input | tasks | path | scratch | output deriving DecidableEq,Inhabited,Repr\ninstance : Fintype Stack where\n  elems := {.input,.tasks,.path,.scratch,.output}\n  complete := by intro x; cases x <;> simp\n\n/-- Eight finite labels for all tree depths. -/\ninductive PC | start | task | node | marker | tag | data | resume | reverse\n  deriving DecidableEq,Inhabited,Repr\ninstance : Fintype PC where\n  elems := {.start,.task,.node,.marker,.tag,.data,.resume,.reverse}\n  complete := by intro x; cases x <;> simp\n\n/-- Popped bit and seek flag are the only finite registers. -/\nabbrev Registers := Option Bool×Bool\n/-- Every stack has a two-symbol alphabet. -/\nabbrev Alphabet (_ : Stack) := Bool\n/-- Conditional single-byte copy, preserving the seek flag. -/\ndef copyThen (next : Registers → PC) : Stmt Alphabet PC Registers :=\n  .branch (fun v => v.2)\n    (.push .scratch (fun v => v.1.getD false) (.goto next)) (.goto next)\n\n/-- Add two physical subtree tasks and reset only finite flags. -/\ndef forkTasks (lo hi : Registers → Bool) : Stmt Alphabet PC Registers :=\n  .push .tasks hi (.push .tasks lo\n    (.load (fun _ => (none,false)) (.goto (fun _ => .task))))\n\n/-- Actual fixed instruction table, with no tree/word/Nat oracle operation. -/\ndef program : PC → Stmt Alphabet PC Registers\n  | .start => .push .tasks (fun _ => true) (.goto (fun _ => .task))\n  | .task => .pop .tasks (fun _ b => (b,b.getD false))\n      (.branch (fun v => v.1.isSome) (.goto (fun _ => .node)) (.goto (fun _ => .reverse)))\n  | .node => .pop .input (fun v b => (b,v.2))\n      (.branch (fun v => v.1==some true)\n        (.branch (fun v => v.2)\n          (.pop .path (fun v b => (b,v.2))\n            (forkTasks (fun v => !(v.1.getD false)) (fun v => v.1.getD false)))\n          (forkTasks (fun _ => false) (fun _ => false)))\n        (.goto (fun _ => .marker)))\n  | .marker => .pop .input (fun v b => (b,v.2))\n      (copyThen (fun v => if v.1==some true then .tag else .resume))\n  | .tag => .pop .input (fun v b => (b,v.2))\n      (copyThen (fun v => if v.1==some true then .data else .marker))\n  | .data => .pop .input (fun v b => (b,v.2)) (copyThen (fun _ => .tag))\n  | .resume => .load (fun _ => (none,false)) (.goto (fun _ => .task))\n  | .reverse => .pop .scratch (fun v b => (b,v.2))\n      (.branch (fun v => v.1.isSome)\n        (.push .output (fun v => v.1.getD false) (.goto (fun _ => .reverse))) .halt)\n\n/-- The genuine finite-alphabet machine. -/\ndef machine : FinTM2 where\n  K := Stack\n  k₀ := .input\n  k₁ := .output\n  Γ := Alphabet\n  Λ := PC\n  main := .start\n  σ := Registers\n  initialState := (none,false)\n  m := program\n\n/-- Explicit literal stack contents. -/\ndef contents (input tasks path scratch output : List Bool) : (k : Stack) → List (Alphabet k)\n  | .input => input\n  | .tasks => tasks\n  | .path => path\n  | .scratch => scratch\n  | .output => output\n\n/-- Concrete fixed-control configurations. -/\ndef cfg (pc : Option PC) (v : Registers) (input tasks path scratch output : List Bool) :\n    TM2.Cfg Alphabet PC Registers := ⟨pc,v,contents input tasks path scratch output⟩\n\n/-- Actual primitive transition. -/\ndef step := TM2.step program\n\n/-- Updating a stack changes exactly its literal data. -/\n@[simp] theorem update_contents (input tasks path scratch output xs : List Bool) (k : Stack) :\n    Function.update (contents input tasks path scratch output) k xs =\n      contents (if k = .input then xs else input) (if k = .tasks then xs else tasks)\n        (if k = .path then xs else path) (if k = .scratch then xs else scratch)\n        (if k = .output then xs else output) := by\n  funext j\n  cases k <;> cases j <;> simp [contents]\n\n/-- Exact paths, indexed only in the proof. -/\ninductive Executes : ℕ → TM2.Cfg Alphabet PC Registers → TM2.Cfg Alphabet PC Registers → Prop\n  | refl (c) : Executes 0 c c\n  | next {n c d e} : step c=some d → Executes n d e → Executes (n+1) c e\n\n/-- Concatenate actual transition sequences. -/\ntheorem Executes.trans {n m : ℕ} {a b c : TM2.Cfg Alphabet PC Registers}\n    (h : Executes n a b) (g : Executes m b c) : Executes (n+m) a c := by\n  induction h with\n  | refl => simpa using g\n  | @next n a d b hs ht ih =>\n    simpa only [Nat.add_assoc,Nat.add_comm,Nat.add_left_comm] using Executes.next hs (ih g)\n\n/-- Exact paths refine Mathlib's actual iterate semantics. -/\ntheorem Executes.iterates {n : ℕ} {a b : TM2.Cfg Alphabet PC Registers}\n    (h : Executes n a b) :\n    ((fun x : Option (TM2.Cfg Alphabet PC Registers) => x.bind step)^[n]) (some a)=some b := by\n  induction h with\n  | refl => rfl\n  | @next n a d b hs ht ih =>\n    rw [Function.iterate_succ_apply]\n    simpa only [Option.bind_some,hs] using ih\n\n/-- A literal transition-time certificate. -/\ndef Executes.inTime {n : ℕ} {a b : TM2.Cfg Alphabet PC Registers}\n    (h : Executes n a b) : StateTransition.EvalsToInTime step a (some b) n :=\n  ⟨⟨n,h.iterates⟩,le_rfl⟩\n\n/-- Physically reverse the selected vector, leaving all other stacks intact. -/\ntheorem reverse_exec (v : Registers) (xs tasks path rev out : List Bool) :\n    Executes (rev.length+1) (cfg (some .reverse) v xs tasks path rev out)\n      (cfg none (none,v.2) xs tasks path [] (rev.reverse++out)) := by\n  induction rev generalizing v out with\n  | nil =>\n    apply Executes.next ?_ (Executes.refl _)\n    simp [SemiprimeD1TensorTapeTreeMachine.step,program,cfg,contents,TM2.step,TM2.stepAux]\n  | cons b bs ih =>\n    have ht := ih (some b,v.2) (b::out)\n    have hs : step (cfg (some .reverse) v xs tasks path (b::bs) out)=\n        some (cfg (some .reverse) (some b,v.2) xs tasks path bs (b::out)) := by\n      simp [SemiprimeD1TensorTapeTreeMachine.step,program,cfg,contents,TM2.step,TM2.stepAux]\n    simpa [List.reverse_cons,List.append_assoc] using Executes.next hs ht\n\n/-- Raw field scan, with no nested-word control payload. -/\ntheorem field_exec (w tail tasks path rev out : List Bool) (mode : Bool) (last : Option Bool) :\n    Executes (2*w.length+1)\n      (cfg (some .tag) (last,mode) (frame w tail) tasks path rev out)\n      (cfg (some .marker) (some false,mode) tail tasks path\n        (if mode then (frame w []).reverse++rev else rev) out) := by\n  induction w generalizing rev last with\n  | nil =>\n    apply Executes.next ?_ (Executes.refl _)\n    cases mode <;> simp [SemiprimeD1TensorTapeTreeMachine.step,program,copyThen,\n      cfg,contents,frame,TM2.step,TM2.stepAux]\n  | cons b bs ih =>\n    have htag : step (cfg (some .tag) (last,mode) (frame (b::bs) tail) tasks path rev out)=\n        some (cfg (some .data) (some true,mode) (b::frame bs tail) tasks path\n          (if mode then true::rev else rev) out) := by\n      cases mode <;> simp [SemiprimeD1TensorTapeTreeMachine.step,program,copyThen,\n        cfg,contents,frame,TM2.step,TM2.stepAux]\n    have hdata : step (cfg (some .data) (some true,mode) (b::frame bs tail) tasks path\n        (if mode then true::rev else rev) out)=\n        some (cfg (some .tag) (some b,mode) (frame bs tail) tasks path\n          (if mode then b::true::rev else rev) out) := by\n      cases mode <;> simp [SemiprimeD1TensorTapeTreeMachine.step,program,copyThen,\n        cfg,contents,TM2.step,TM2.stepAux]\n    have ht := Executes.next htag (Executes.next hdata (ih _ (some b)))\n    convert ht using 1\n    cases mode <;> simp [frame,List.reverse_cons,List.append_assoc]\n\n/-- Raw vector scan; all unselected bytes are physically consumed. -/\ntheorem vector_scan (ws : List (List Bool)) (tail tasks path rev out : List Bool)\n    (mode : Bool) (last : Option Bool) :\n    Executes (vectorBits ws).length\n      (cfg (some .marker) (last,mode) (vectorBits ws++tail) tasks path rev out)\n      (cfg (some .resume) (some false,mode) tail tasks path\n        (if mode then (vectorBits ws).reverse++rev else rev) out) := by\n  induction ws generalizing rev last with\n  | nil =>\n    apply Executes.next ?_ (Executes.refl _)\n    cases mode <;> simp [SemiprimeD1TensorTapeTreeMachine.step,program,copyThen,\n      cfg,contents,vectorBits,TM2.step,TM2.stepAux]\n  | cons w ws ih =>\n    have hs : step (cfg (some .marker) (last,mode) (vectorBits (w::ws)++tail) tasks path rev out)=\n        some (cfg (some .tag) (some true,mode) (frame w (vectorBits ws++tail)) tasks path\n          (if mode then true::rev else rev) out) := by\n      cases mode <;> simp [SemiprimeD1TensorTapeTreeMachine.step,program,copyThen,\n        cfg,contents,vectorBits,SemiprimeD1TensorTapeVectorMachine.frame_append,TM2.step,TM2.stepAux]\n    have hf := field_exec w (vectorBits ws++tail) tasks path (if mode then true::rev else rev) out mode (some true)\n    have hi := ih (if mode then (frame w []).reverse++(if mode then true::rev else rev)\n      else (if mode then true::rev else rev)) (some false)\n    have ht := Executes.next hs (hf.trans hi)\n    have hframe : frame w (vectorBits ws)=frame w []++vectorBits ws := by\n      simpa using SemiprimeD1TensorTapeVectorMachine.frame_append w [] (vectorBits ws)\n    convert ht using 1 <;> cases mode <;>\n      simp [vectorBits,SemiprimeSourceHistogramKeyBits.frame_length,hframe,\n        List.reverse_append,List.reverse_cons,List.append_assoc]\n\nend RiemannGaussian.SemiprimeD1TensorTapeTreeMachine\n","RiemannGaussian.SemiprimeD1WeightedPotential":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1WeightedTuples\n\n/-! Finite geometric potential for the actually acquired weighted menu. -/\nset_option autoImplicit false\nset_option maxHeartbeats 2400000\nnamespace RiemannGaussian.SemiprimeD1WeightedPotential\nopen SemiprimeD1WeightedTuples\nopen scoped BigOperators\n\n/-- Finite geometric majorant; no infinite-product oracle is used. -/\ntheorem finite_geometric_le {x : ℝ} (hx : 0≤x) (hx1 : x<1) (n : ℕ) :\n    (∑ i∈Finset.range n,x^i)≤ (1-x)⁻¹ := by\n  have he := geom_sum_mul_neg x n\n  have hp : 0≤x^n := pow_nonneg hx _\n  rw [← one_div]\n  apply (le_div_iff₀ (sub_pos.mpr hx1)).mpr\n  simpa only [one_div] using (show (∑ i∈Finset.range n,x^i)*(1-x)≤1 by linarith)\n\n/-- Literal finite Euler normalizer, one factor per acquired positive mode. -/\nnoncomputable def normalizer (ws : List ℕ) (a : ℝ) : ℝ :=\n  (ws.map fun (w : ℕ) => (1-Real.exp (-a*w))⁻¹).prod\n\n/-- Every factor and normalizer is positive for original positive weights. -/\ntheorem normalizer_pos {ws : List ℕ} {a : ℝ} (ha : 0<a) (hw : ∀w∈ws,0<w) :\n    0<normalizer ws a := by\n  apply List.prod_pos\n  intro x hx\n  obtain ⟨w,hw',rfl⟩ := List.mem_map.mp hx\n  apply inv_pos.mpr\n  apply sub_pos.mpr\n  rw [Real.exp_lt_one_iff]\n  have hp : (0:ℝ)<w := Nat.cast_pos.mpr (hw w hw')\n  nlinarith\n\n/-- Exact coefficient-free finite potential bound for the executed menu. -/\ntheorem length_le_potential {ws : List ℕ} {a : ℝ} (ha : 0<a)\n    (hw : ∀w∈ws,0<w) (P : ℕ) :\n    ((tuples ws P).length:ℝ)≤ Real.exp (a*P)*normalizer ws a := by\n  induction ws generalizing P with\n  | nil => simp [tuples,normalizer];positivity\n  | cons w ws ih =>\n    have hwp := hw w (by simp)\n    have hws : ∀v∈ws,0<v := fun v hv => hw v (by simp [hv])\n    have hn := (normalizer_pos ha hws).le\n    have hx0 : 0≤ Real.exp (-a*w) := (Real.exp_pos _).le\n    have hx1 : Real.exp (-a*w)<1 := by\n      rw [Real.exp_lt_one_iff]\n      have : (0:ℝ)<w := Nat.cast_pos.mpr hwp\n      nlinarith\n    have hterm (e : ℕ) (he : e∈Finset.range (P/w+1)) :\n      ((tuples ws (P-w*e)).length:ℝ)≤\n        Real.exp (a*P)*(Real.exp (-a*w))^e*normalizer ws a := by\n      have hm : w*e≤P := by\n        have hd : e≤P/w := by have := Finset.mem_range.mp he;omega\n        simpa [Nat.mul_comm] using (Nat.le_div_iff_mul_le hwp).mp hd\n      have hexp : Real.exp (a*(P-w*e:ℕ))=Real.exp (a*P)*(Real.exp (-a*w))^e := by\n        rw [Nat.cast_sub hm,Nat.cast_mul,← Real.exp_nat_mul,← Real.exp_add]\n        congr 1\n        ring\n      simpa only [hexp] using ih hws (P-w*e)\n    have hsum := Finset.sum_le_sum hterm\n    have hgeom := finite_geometric_le hx0 hx1 (P/w+1)\n    have hfinal := mul_le_mul_of_nonneg_left hgeom\n      (mul_nonneg (Real.exp_pos (a*P)).le hn)\n    have hlen : ((tuples (w::ws) P).length:ℝ)=\n      ∑e∈Finset.range (P/w+1),((tuples ws (P-w*e)).length:ℝ) := by\n      simp only [tuples,List.length_flatMap,List.length_map,Nat.cast_list_sum,List.map_map]\n      change ((List.range (P/w+1)).map fun e => ((tuples ws (P-w*e)).length:ℝ)).sum = _\n      rw [← List.sum_toFinset _ List.nodup_range,List.toFinset_range]\n    rw [hlen]\n    calc\n      _ ≤ ∑e∈Finset.range (P/w+1),Real.exp (a*P)*(Real.exp (-a*w))^e*normalizer ws a := hsum\n      _ = (Real.exp (a*P)*normalizer ws a)*(∑e∈Finset.range (P/w+1),(Real.exp (-a*w))^e) := by\n        rw [Finset.mul_sum]\n        apply Finset.sum_congr rfl\n        intro e he\n        ring\n      _ ≤ (Real.exp (a*P)*normalizer ws a)*(1-Real.exp (-a*w))⁻¹ := hfinal\n      _ = Real.exp (a*P)*normalizer (w::ws) a := by simp [normalizer];ring\n\n/-- Exact regrouping by the actual acquired finite weight list. -/\ntheorem sum_by_count (ws : List ℕ) (s : Finset ℕ) (f : ℕ→ℝ)\n    (hs : ∀w∈ws,w∈s) :\n    (ws.map f).sum=∑w∈s,(ws.count w:ℝ)*f w := by\n  induction ws with\n  | nil => simp\n  | cons w ws ih =>\n    have hw := hs w (by simp)\n    have ht : ∀v∈ws,v∈s := fun v hv => hs v (by simp [hv])\n    simp only [List.map_cons,List.sum_cons,ih ht,List.count_cons]\n    simp [Nat.cast_add,add_mul,Finset.sum_add_distrib,ite_mul,hw,add_comm]\n\n/-- Each positive mode contributes the finite Euler logarithm. -/\nnoncomputable def logFactor (a : ℝ) (w : ℕ) : ℝ := -Real.log (1-Real.exp (-a*w))\n\n/-- The zero weight has zero formal log factor; it is excluded from runtime input. -/\ntheorem logFactor_nonneg {a : ℝ} (ha : 0<a) (w : ℕ) : 0≤logFactor a w := by\n  cases w with\n  | zero => simp [logFactor]\n  | succ w =>\n    have he : Real.exp (-a*(w+1:ℕ))<1 := by\n      rw [Real.exp_lt_one_iff]\n      have : (0:ℝ)<(w+1:ℕ) := by positivity\n      nlinarith\n    have hp := Real.exp_pos (-a*(w+1:ℕ))\n    have hh : Real.log (1-Real.exp (-a*(w+1:ℕ)))≤0 :=\n      Real.log_nonpos (by linarith) (by linarith)\n    exact neg_nonneg.mpr hh\n\n/-- No analytic infinite product is needed for the acquired finite normalizer. -/\ntheorem normalizer_exp {ws : List ℕ} {a : ℝ} (ha : 0<a) (hw : ∀w∈ws,0<w) :\n    normalizer ws a=Real.exp ((ws.map (logFactor a)).sum) := by\n  induction ws with\n  | nil => simp [normalizer]\n  | cons w ws ih =>\n    have hp : 0<w := hw w (by simp)\n    have ht : ∀v∈ws,0<v := fun v hv => hw v (by simp [hv])\n    have he : Real.exp (-a*w)<1 := by\n      rw [Real.exp_lt_one_iff]\n      have : (0:ℝ)<w := Nat.cast_pos.mpr hp\n      nlinarith\n    simp only [normalizer,List.map_cons,List.prod_cons,List.sum_cons,Real.exp_add] at *\n    rw [ih ht]\n    simp only [logFactor,Real.exp_neg,Real.exp_log (sub_pos.mpr he)]\n\n/-- Finite multiplicity grouping exposes exactly the per-weight source bound. -/\ntheorem logsum_multiplicity {ws : List ℕ} {a : ℝ} (ha : 0<a) (K B : ℕ)\n    (hw : ∀w∈ws,w≤K) (hb : ∀w,(ws.count w)≤B) :\n    (ws.map (logFactor a)).sum≤(B:ℝ)*∑j∈Finset.range K,logFactor a (j+1) := by\n  rw [sum_by_count ws (Finset.range (K+1)) (logFactor a)\n    (fun w h => Finset.mem_range.mpr (by have := hw w h;omega))]\n  calc\n    _ ≤ ∑w∈Finset.range (K+1),(B:ℝ)*logFactor a w := by\n      apply Finset.sum_le_sum\n      intro w hw'\n      exact mul_le_mul_of_nonneg_right (by exact_mod_cast hb w) (logFactor_nonneg ha w)\n    _ = (B:ℝ)*∑w∈Finset.range (K+1),logFactor a w := by rw [Finset.mul_sum]\n    _ = (B:ℝ)*∑j∈Finset.range K,logFactor a (j+1) := by\n      rw [Finset.sum_range_succ']\n      simp [logFactor]\n\n/-- Exact useful nonoptimal balancing, avoiding a ceiling on mode multiplicity. -/\ntheorem balance_exponent {B P : ℝ} (hB : 0<B) (hP : 0<P) :\n    (Real.sqrt B/Real.sqrt P)*P+2*B/(Real.sqrt B/Real.sqrt P)=3*Real.sqrt (B*P) := by\n  let b := Real.sqrt B\n  let p := Real.sqrt P\n  have hb : b≠0 := ne_of_gt (Real.sqrt_pos.mpr hB)\n  have hp : p≠0 := ne_of_gt (Real.sqrt_pos.mpr hP)\n  have hb2 : b*b=B := by simpa [b,pow_two] using Real.sq_sqrt hB.le\n  have hp2 : p*p=P := by simpa [p,pow_two] using Real.sq_sqrt hP.le\n  have ht1 : b/p*P=b*p := by rw [←hp2];field_simp\n  have ht2 : 2*B/(b/p)=2*b*p := by rw [←hb2];field_simp\n  rw [Real.sqrt_mul hB.le]\n  change b/p*P+2*B/(b/p)=3*(b*p)\n  rw [ht1,ht2]\n  ring\n\nend RiemannGaussian.SemiprimeD1WeightedPotential\n","RiemannGaussian.SemiprimeD1WordPacketCoefficientClock":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1WordPacketArithmeticClock\nimport RiemannGaussian.SemiprimeD1PacketCoefficientClock\n\n/-! # Actual packet mode coefficients and cached affine row acquisition\nAll same-bit checks and actual signed crossing-mode calls are charged. Numeric\nmode/tile caps describe acquired original catalogue fields, not supplied entry\nvalues or intermediate width/clock answers.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 150000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1WordPacketCoefficientClock\nopen SemiprimeD1JetAxes SemiprimeD1JetAffineCoefficient SemiprimeD1JetAffineCoefficientBounds\nopen SemiprimeD1JetWordPacketEntryBits SemiprimeD1PacketEntryInputs SemiprimeD1WordPacketArithmeticClock\nopen SemiprimeD1PacketEntryBits (borrow sameBit)\n\n/-- Original physical index acquisition and both actual bit scans. -/\ndef sameBitClock (a : ℕ) : ℕ := 2*SemiprimeSourceHistogramPortKeys.encodeBudget (2^a)+8*a+9\n\n/-- Same-bit control is computed, never assumed as a branch oracle. -/\ntheorem sameBit_clock (a : ℕ) (i : Fin a) (x y : Fin (2^a)) :\n    (sameBit x.val y.val i.val).work  ≤  sameBitClock a := by\n  have hx := SemiprimeSourceHistogramPortKeys.encodeKey_clock x.val (2^a) x.isLt.le\n  have hy := SemiprimeSourceHistogramPortKeys.encodeKey_clock y.val (2^a) y.isLt.le\n  have hl := SemiprimeD1ModeRoutingBits.readBit_work\n    (SemiprimeSourceHistogramPortKeys.encodeKey x.val).bits i.val\n  have hr := SemiprimeD1ModeRoutingBits.readBit_work\n    (SemiprimeSourceHistogramPortKeys.encodeKey y.val).bits i.val\n  change (SemiprimeSourceHistogramPortKeys.encodeKey x.val).clock+\n    (SemiprimeSourceHistogramPortKeys.encodeKey y.val).clock+_+_+5  ≤  _\n  unfold sameBitClock\n  omega\n\n/-- Closed actual acquired mode budget, uniform over its original level. -/\ndef modeClock (ctx : Context) (a b : ℕ) : ℕ :=\n  SemiprimeD1JetWordKernelBounds.budget ctx ctx.precision a+\n    SemiprimeD1JetWordModeBounds.budget ctx ctx.precision a a b\n\n/-- Actual source and vector budgets are monotone in level and finite exponent. -/\ntheorem mode_order_mono (ctx : Context) (a i b B : ℕ) (hi:i ≤ a) (hb:b ≤ B) :\n    SemiprimeD1JetWordKernelBounds.budget ctx ctx.precision a+\n      SemiprimeD1JetWordModeBounds.budget ctx ctx.precision a i b ≤ modeClock ctx a B := by\n  unfold modeClock SemiprimeD1JetWordModeBounds.budget\n    SemiprimeD1JetWordModeScalarBounds.budget SemiprimeD1JetWordModeScalarBounds.stepBudget\n  gcongr\n\n/-- Whole new mode clock derives from actual original source and acquired vector bounds. -/\ntheorem mode_clock (ctx : Context) (z : JetRun) (hz:Good ctx z.words) (a : ℕ) (i : Fin a)\n    (b : ℕ) (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (x y:Fin (2^a)) :\n    (SemiprimeD1JetWordModeBits.acquireOriginal ctx (borrow z) a i.val b t x y).clock ≤ modeClock ctx a b := by\n  have hm:=SemiprimeD1JetWordModeBounds.acquireOriginal_clock ctx (borrow z) a i.val b ctx.precision\n    t x y le_rfl hz.1.le hz.2\n  have hk:=SemiprimeD1JetWordKernelBounds.acquireOriginal_clock ctx (borrow z) a t x y ctx.precision\n    le_rfl hz.1.le hz.2\n  change (SemiprimeD1JetWordKernelBits.acquireOriginal ctx (borrow z) a t x y).clock ≤ \n    0+SemiprimeD1JetWordKernelBounds.budget ctx ctx.precision a at hk\n  have hu:=mode_order_mono ctx a i.val b b i.isLt.le le_rfl\n  omega\n\n/-- Whole crossing coefficient, including both zero and active physical branches. -/\ndef coefficientClock (ctx : Context) (a B T : ℕ) : ℕ :=\n  modeClock ctx a B+\n    signClock ctx+sameBitClock a+T+2^a+2^a+10+ctx.rank+1\n\n/-- Every actual catalogue coefficient derives canonical current shape. -/\ntheorem coefficient_good (ctx : Context) (z : JetRun) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a)\n    (item : SemiprimeD1PacketModeMask.Item) : Good ctx (coefficient ctx z a i t row item).words := by\n  dsimp only [coefficient]\n  split\n  · exact signed_good ctx _ _ (SemiprimeD1JetWordModeBits.acquireOriginal_good ctx _ _ _ _ _ _ _)\n  · exact zero_good ctx\n\n/-- Whole actual physical coefficient cost from original acquired input bounds. -/\ntheorem coefficient_clock (ctx : Context) (z : JetRun) (hz : Good ctx z.words) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a)\n    (item : SemiprimeD1PacketModeMask.Item) (B T : ℕ)\n    (hb : item.mode.order  ≤  B) (ht : item.tile  ≤  T) :\n    (coefficient ctx z a i t row item).clock  ≤  coefficientClock ctx a B T := by\n  let tile : Fin (2^a) := ⟨item.tile%2^a,Nat.mod_lt _ (by positivity)⟩\n  have htest := sameBit_clock a i row.slot tile\n  have hmode:=mode_clock ctx z hz a i item.mode.order t row.slot tile\n  have hmodeGood:Good ctx (SemiprimeD1JetWordModeBits.acquireOriginal ctx (borrow z) a i.val\n      item.mode.order t row.slot tile).words:=SemiprimeD1JetWordModeBits.acquireOriginal_good _ _ _ _ _ _ _ _\n  have hsign:=signed_clock ctx (!row.bit)\n    (SemiprimeD1JetWordModeBits.acquireOriginal ctx (borrow z) a i.val item.mode.order t row.slot tile) hmodeGood\n  have hbound:modeClock ctx a item.mode.order ≤ modeClock ctx a B:=by\n    unfold modeClock SemiprimeD1JetWordModeBounds.budget\n    gcongr\n  have hrow : row.slot.val  ≤  2^a := row.slot.isLt.le\n  dsimp only [coefficient]\n  split\n  · change (signed ctx (!row.bit)\n      (SemiprimeD1JetWordModeBits.acquireOriginal ctx (borrow z) a i.val item.mode.order t row.slot tile)).clock+\n      (sameBit row.slot.val tile.val i.val).work+item.tile+row.slot.val+2^a+10  ≤  _\n    unfold coefficientClock\n    omega\n  · change ctx.rank+1+(sameBit row.slot.val tile.val i.val).work+item.tile+row.slot.val+2^a+10  ≤  _\n    unfold coefficientClock\n    omega\n\n/-- Actual coefficient-vector list traversal, with every called coefficient paid. -/\ntheorem coefficients_clock (ctx : Context) (z : JetRun) (hz : Good ctx z.words) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a)\n    (items : List SemiprimeD1PacketModeMask.Item) (B T : ℕ)\n    (hb : ∀item∈items,item.mode.order  ≤  B) (ht : ∀item∈items,item.tile  ≤  T) :\n    (coefficients ctx z a i t row items).work  ≤  items.length*(coefficientClock ctx a B T+4)+1 := by\n  induction items with\n  | nil => simp only [coefficients,List.length_nil,Nat.zero_mul,Nat.zero_add,le_refl]\n  | cons item items ih =>\n    have hh := coefficient_clock ctx z hz a i t row item B T (hb _ List.mem_cons_self) (ht _ List.mem_cons_self)\n    have hh' := ih (fun x hx => hb x (List.mem_cons_of_mem _ hx)) (fun x hx => ht x (List.mem_cons_of_mem _ hx))\n    change (coefficient ctx z a i t row item).clock+(coefficients ctx z a i t row items).work+4  ≤  _\n    simp only [List.length_cons,Nat.add_mul,Nat.one_mul]\n    omega\n\n/-- Actual coefficient list contains exactly the cached physical coefficient outputs. -/\ntheorem coefficients_payload (ctx : Context) (z : JetRun) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a)\n    (items : List SemiprimeD1PacketModeMask.Item) :\n    (coefficients ctx z a i t row items).value=items.map (fun item=>(coefficient ctx z a i t row item).words) := by\n  induction items with\n  | nil => rfl\n  | cons item items ih => simp only [coefficients,List.map_cons,ih]\n\n/-- Actual row recipe list contains exactly its cached physical recipe outputs. -/\ntheorem recipes_payload (ctx : Context) (z : JetRun) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (columns : List (Wire a))\n    (items : List SemiprimeD1PacketModeMask.Item) (rows : List (Wire a)) :\n    (recipes ctx z a i t columns items rows).value=rows.map (fun row=>(recipe ctx z a i t row columns items).value) := by\n  induction rows with\n  | nil => rfl\n  | cons row rows ih => simp only [recipes,List.map_cons,ih]\n\n/-- Computed row recipe satisfies the actual physical coefficient interpreter's\nsource invariant, with no intermediate shape or fit advice. -/\ntheorem recipe_source (ctx : Context) (z : JetRun) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a) (columns : List (Wire a))\n    (items : List SemiprimeD1PacketModeMask.Item) :\n    Source ctx ctx.precision items.length (recipe ctx z a i t row columns items).value := by\n  have hb := rowBase_good ctx z a t row columns\n  refine ⟨hb.1.le,hb.2,?_,?_⟩\n  · change (coefficients ctx z a i t row items).value.length  ≤  items.length\n    rw [coefficients_payload,List.length_map]\n  · intro v hv\n    change v ∈ (coefficients ctx z a i t row items).value at hv\n    rw [coefficients_payload] at hv\n    obtain ⟨item,_,rfl⟩ := List.mem_map.mp hv\n    have hh := coefficient_good ctx z a i t row item\n    exact ⟨hh.1.le,hh.2⟩\n\n/-- Full row acquisition budget, polynomial in the original catalogue and row columns. -/\ndef recipeClock (ctx : Context) (a C K B T : ℕ) : ℕ :=\n  rowBaseClock ctx a C+K*(coefficientClock ctx a B T+4)+6\n\n/-- Cached base and coefficient producers are both retained by the actual recipe. -/\ntheorem recipe_clock (ctx : Context) (z : JetRun) (hz : Good ctx z.words) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a) (columns : List (Wire a))\n    (items : List SemiprimeD1PacketModeMask.Item) (B T : ℕ)\n    (hb : ∀item∈items,item.mode.order  ≤  B) (ht : ∀item∈items,item.tile  ≤  T) :\n    (recipe ctx z a i t row columns items).work  ≤  recipeClock ctx a columns.length items.length B T := by\n  have hbase := rowBase_clock ctx z hz a t row columns\n  have hcoeff := coefficients_clock ctx z hz a i t row items B T hb ht\n  change (rowBase ctx z a t row columns).clock+(coefficients ctx z a i t row items).work+5  ≤  _\n  unfold recipeClock\n  omega\n\n/-- All actual real rows are acquired once; no local truth table callback is supplied. -/\ntheorem recipes_clock (ctx : Context) (z : JetRun) (hz : Good ctx z.words) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (columns : List (Wire a))\n    (items : List SemiprimeD1PacketModeMask.Item) (rows : List (Wire a)) (B T : ℕ)\n    (hb : ∀item∈items,item.mode.order  ≤  B) (ht : ∀item∈items,item.tile  ≤  T) :\n    (recipes ctx z a i t columns items rows).work  ≤ \n      rows.length*(recipeClock ctx a columns.length items.length B T+4)+1 := by\n  induction rows with\n  | nil => simp only [recipes,List.length_nil,Nat.zero_mul,Nat.zero_add,le_refl]\n  | cons row rows ih =>\n    have hh := recipe_clock ctx z hz a i t row columns items B T hb ht\n    change (recipe ctx z a i t row columns items).work+(recipes ctx z a i t columns items rows).work+4  ≤  _\n    simp only [List.length_cons,Nat.add_mul,Nat.one_mul]\n    omega\n\nend RiemannGaussian.SemiprimeD1WordPacketCoefficientClock\n","RiemannGaussian.SemiprimeD1WordTapeBinaryFactorExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1WordTapePublicSearch\nimport RiemannGaussian.SemiprimeD1BinaryFactorExecution\nimport RiemannGaussian.SemiprimeD1PublicOperandBits\nimport RiemannGaussian.SemiprimeD1FactorValidationBits\n\n/-! # Closed binary-output semiprime factor execution\nAll count queries acquire their own original root and execute the physical\nrecursive counter. Operand construction uses original selected-label scans and\nBoolean radix assembly; proper-divisor validation and cofactor recovery use\nBoolean comparison and restoring division. The result contains literal factor\nbytes. Query, physical arithmetic and native metadata reports remain distinct;\nno complete primitive-machine runtime is asserted by this module.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 400000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1WordTapeBinaryFactorExecution\nopen SemiprimePublicAcquiredExecution SemiprimeBitArithmetic SemiprimeBitDivision\nopen SemiprimePublicAcquiredExecution SemiprimeBitPrimeScan\nattribute [local irreducible] SemiprimeD1WordTapePublicSearch.search\n  SemiprimeD1PhysicalPublicCounter.search SemiprimeD1PublicCounter.search\n  SemiprimeD1PublicOperandBits.run SemiprimeD1FactorValidationBits.run\n  SemiprimePublicAcquiredExecution.decodeOperand\n\n/-- Literal factor bytes and every retained contribution of this executed path. -/\nstructure Run where\n  /-- Successful ordinary factor pair in little-endian binary words. -/\n  factors : Option (List Bool × List Bool)\n  /-- Actual original-prefix count queries executed by the search. -/\n  queries : ℕ\n  /-- All actual original root acquisition and physical recursive reports. -/\n  queryWork : ℕ\n  /-- Actual input zero test, radix shift/add and final validation/division. -/\n  arithmeticClock : ℕ\n  /-- Typed constructor/index/label/control reports, requiring host lowering. -/\n  metadataWork : ℕ\n\n/-- Original binary input is the only input. No acquired count, table, mode,\ncoefficient, word getter, decoder result or factor answer is supplied. -/\ndef run (input : List Bool) : Run :=\n  let initial := nonzeroBits input\n  if hz : initial.nonzero=true then\n    let N := bitValue input\n    let hN : 0 < N := (nonzeroBits_correct input).mp hz\n    let queried := SemiprimeD1WordTapePublicSearch.search N hN\n    match queried.result.values with\n    | none => ⟨none,queried.result.queries,queried.queryWork,initial.clock+3,\n      queried.metadataWork+10*(wireCount N+input.length+1)⟩\n    | some values =>\n      let operand := SemiprimeD1PublicOperandBits.run N values 0\n      let checked := SemiprimeD1FactorValidationBits.run input operand.bits\n      let answer := if checked.valid then some (operand.bits,checked.cofactor) else none\n      ⟨answer,queried.result.queries,queried.queryWork,\n        initial.clock+operand.arithmeticClock+checked.clock+7,\n        queried.metadataWork+operand.metadataWork+10*(wireCount N+input.length+values.length+1)⟩\n  else ⟨none,0,0,initial.clock+3,10*(input.length+1)⟩\n\n/-- Every successful byte result is a true ordinary factor pair on every input. -/\ntheorem run_sound (input left right : List Bool) (h : (run input).factors=some (left,right)) :\n    bitValue left*bitValue right=bitValue input ∧ 2 ≤ bitValue left ∧ 2 ≤ bitValue right := by\n  dsimp only [run] at h\n  split at h\n  · split at h\n    · cases h\n    · dsimp only at h\n      split at h\n      · cases h\n        exact SemiprimeD1FactorValidationBits.run_factor_pair _ _ (by assumption)\n      · cases h\n  · cases h\n\n/-- Closed search completeness and ordinary decoded factors, derived from the\nexact actual original-prefix counter without any count supplier at execution. -/\ntheorem selected_complete (N p q : ℕ) (hN : 0 < N) (hp : p.Prime) (hq : q.Prime)\n    (hsem : N=p*q) :\n    ∃ values,(SemiprimeD1WordTapePublicSearch.search N hN).result.values=some values ∧\n      2 ≤ decodeOperand N values 0 ∧ 2 ≤ decodeOperand N values 1 ∧\n        decodeOperand N values 0*decodeOperand N values 1=N := by\n  have hc := SemiprimeD1PublicCorrectness.prefixCount_exact N p q hN hp hq hsem\n  obtain ⟨values,hvalues⟩ := SemiprimeD1PublicCountConsequences.search_exists N p q hN hp hq hsem hc\n  have he : (SemiprimeD1WordTapePublicSearch.search N hN).result.values=\n      (SemiprimeD1PublicCounter.search N hN).values :=\n    congrArg SemiprimeCountRecovery.SearchResult.values\n      ((SemiprimeD1WordTapePublicSearch.search_spec N hN).trans\n        ((SemiprimeD1WordTapePublicCounter.search_eq_physical N hN).trans\n          (SemiprimeD1PhysicalPublicCounter.search_eq_original N hN)))\n  exact ⟨values,he.trans hvalues,\n    SemiprimeD1PublicCountConsequences.selected_factor_pair N hN hc values hvalues⟩\n\n/-- Every semiprime, including a repeated prime, produces an entire actual\nbinary factor pair. All word/count/search/carry/cofactor semantics are closed. -/\ntheorem run_complete (input : List Bool) (p q : ℕ) (hp : p.Prime) (hq : q.Prime)\n    (hsem : bitValue input=p*q) :\n    ∃ left right,(run input).factors=some (left,right) ∧\n      bitValue left*bitValue right=bitValue input ∧\n      2 ≤ bitValue left ∧ 2 ≤ bitValue right ∧ (bitValue left=p ∨ bitValue left=q) := by\n  have hN : 0 < bitValue input := by rw [hsem];exact Nat.mul_pos hp.pos hq.pos\n  have hz := (nonzeroBits_correct input).mpr hN\n  obtain ⟨values,hvalues,hl,hr,hprod⟩ := selected_complete (bitValue input) p q hN hp hq hsem\n  let operand := SemiprimeD1PublicOperandBits.run (bitValue input) values 0\n  have hd : bitValue operand.bits=decodeOperand (bitValue input) values 0 :=\n    SemiprimeD1PublicOperandBits.run_value _ _ _\n  have hlt : bitValue operand.bits < bitValue input := by rw [hd];nlinarith\n  have hdvd : bitValue operand.bits ∣ bitValue input := by\n    rw [hd]\n    exact ⟨decodeOperand (bitValue input) values 1,hprod.symm⟩\n  have hflag : (SemiprimeD1FactorValidationBits.run input operand.bits).valid=true :=\n    (SemiprimeD1FactorValidationBits.run_valid input operand.bits).mpr\n      ⟨hd.symm ▸ hl,hlt,Nat.mod_eq_zero_of_dvd hdvd⟩\n  have hout : (run input).factors=some\n      (operand.bits,(SemiprimeD1FactorValidationBits.run input operand.bits).cofactor) := by\n    dsimp only [run]\n    rw [dite_eq_left hz,hvalues]\n    exact ite_eq_left hflag\n  have hpair := SemiprimeD1FactorValidationBits.run_factor_pair input operand.bits hflag\n  refine ⟨operand.bits,(SemiprimeD1FactorValidationBits.run input operand.bits).cofactor,\n    hout,hpair.1,hpair.2.1,hpair.2.2,?_⟩\n  exact SemiprimeD1SemiprimePrefix.left_factor_eq p q _ _ hp hq hpair.2.1 hpair.2.2\n    (hpair.1.trans hsem)\n\n/-- The byte-producing execution makes only the same original linear number\nof count queries; validation and cofactor production add none. -/\ntheorem run_queries (input : List Bool) : (run input).queries ≤ wireCount (bitValue input)+1 := by\n  dsimp only [run]\n  split\n  · have hs := SemiprimeD1WordTapePublicSearch.search_queries (bitValue input)\n      ((nonzeroBits_correct input).mp (by assumption))\n    split <;> exact hs\n  · dsimp only\n    omega\n\nend RiemannGaussian.SemiprimeD1WordTapeBinaryFactorExecution\n","RiemannGaussian.SemiprimeD1WordTapeRecursiveClock":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1WordTapeRecursivePhase\n\n/-! # Exact actual phase report separation for word/tape child construction\nAll new child factory clocks remain in the local term. Only recursive answer\nreports are separated, after actual positive-context network refinement.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 800000\nnamespace RiemannGaussian.SemiprimeD1WordTapeRecursiveClock\nopen SemiprimeD1JetAxes SemiprimeD1TensorNetwork SemiprimeD1RecursiveCounter\nopen SemiprimeD1RecursiveCallTree SemiprimeD1PhysicalRecursiveClock\nopen SemiprimeD1JetAffineCoefficient (JetRun)\nattribute [local irreducible] SemiprimeD1OriginalModeAcquisition.acquire\n\n/-- Exact one-mode report separation preserves every new word/tape producer report. -/\ntheorem phaseTerm_clock (next : Context → Network → JetRun) (parent : Call) (a u : ℕ)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (i : Fin a) (beta : List ℕ)\n    (hp : parent.ctx.Positive) (huM : u ≤ edgeCount parent.net) (hi : i.val<u) :\n    (SemiprimeD1WordTapeRecursivePhase.phaseTerm next parent a u t i beta).words=\n      (SemiprimeD1WordTapeRecursivePhase.phaseTerm (eraseClock next) parent a u t i beta).words ∧\n    (SemiprimeD1WordTapeRecursivePhase.phaseTerm next parent a u t i beta).clock=\n      (SemiprimeD1WordTapeRecursivePhase.phaseTerm (eraseClock next) parent a u t i beta).clock+\n      ((List.finRange 64).map (fun g =>\n        (next (child parent a u t i beta g).ctx (child parent a u t i beta g).net).clock)).sum := by\n  let source:=SemiprimeD1OriginalModeAcquisition.acquire parent.net.leftCount\n    parent.net.rows.length 64 a u i.val parent.ctx.precision (arity parent.net.rows) (owner parent.net.rows)\n  let q:=SemiprimeD1ModeRate.jetHeight (edgeCount parent.net) u*(u-i.val)\n  let fresh:=SemiprimeD1FreshJetBits.acquireFresh parent.ctx q source.precision\n  let current : Context:=⟨q::parent.ctx.axes,source.precision⟩\n  have hc : current.Positive := SemiprimeD1WordTapeRecursivePhase.current_positive parent.ctx _ _ _ _ hp huM hi\n  unfold SemiprimeD1WordTapeRecursivePhase.phaseTerm\n  apply product_map\n  · intro g hg\n    rfl\n  · intro g hg\n    let data:=SemiprimeD1ChildWordNetwork.fromSource parent.net source i g parent.ctx [q]\n      source.precision fresh t beta\n    have he:=SemiprimeD1ChildWordNetwork.fromSource_network parent.net source i g parent.ctx [q]\n      source.precision fresh t beta hc\n    change data.clock+(next current data.network).clock+5=\n      data.clock+0+5+(next current\n        (SemiprimeD1ChildNetwork.fromSource parent.net source i g parent.ctx [q]\n          source.precision fresh t beta).network).clock\n    change data.network=_ at he\n    rw [he]\n    omega\n\n/-- Literal acquired-mode sum separates only the actual recursive child reports. -/\ntheorem phaseTotal_clock (next : Context → Network → JetRun) (parent : Call) (a u : ℕ)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (i : Fin a)\n    (hp : parent.ctx.Positive) (huM : u ≤ edgeCount parent.net) (hi : i.val<u) :\n    (SemiprimeD1WordTapeRecursivePhase.phaseTotal next parent a u t i).words=\n      (SemiprimeD1WordTapeRecursivePhase.phaseTotal (eraseClock next) parent a u t i).words ∧\n    (SemiprimeD1WordTapeRecursivePhase.phaseTotal next parent a u t i).clock=\n      (SemiprimeD1WordTapeRecursivePhase.phaseTotal (eraseClock next) parent a u t i).clock+\n        modeChildClocks next parent a u t i := by\n  unfold SemiprimeD1WordTapeRecursivePhase.phaseTotal modeChildClocks\n  apply sum_map\n  · intro beta hb\n    exact (phaseTerm_clock next parent a u t i beta hp huM hi).1\n  · intro beta hb\n    exact (phaseTerm_clock next parent a u t i beta hp huM hi).2\n\n/-- Exact report over the original grid/tuple/group call inventory. The new\nsource, word packet, tape copies and all recopy/setup reports stay in local work. -/\ntheorem phase_clock (next : Context → Network → JetRun) (parent : Call) (a u : ℕ)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (hp : parent.ctx.Positive) (huM : u ≤ edgeCount parent.net) :\n    (SemiprimeD1WordTapeRecursivePhase.phase next parent.ctx parent.net a u t).blocks=\n      (SemiprimeD1WordTapeRecursivePhase.phase (eraseClock next) parent.ctx parent.net a u t).blocks ∧\n    (SemiprimeD1WordTapeRecursivePhase.phase next parent.ctx parent.net a u t).precision=\n      (SemiprimeD1WordTapeRecursivePhase.phase (eraseClock next) parent.ctx parent.net a u t).precision ∧\n    (SemiprimeD1WordTapeRecursivePhase.phase next parent.ctx parent.net a u t).clock=\n      (SemiprimeD1WordTapeRecursivePhase.phase (eraseClock next) parent.ctx parent.net a u t).clock+\n      ((phaseChildren parent a u t).map (fun c => (next c.ctx c.net).clock)).sum := by\n  dsimp only [SemiprimeD1WordTapeRecursivePhase.phase,phaseChildren]\n  split\n  · rename_i hi\n    let i : Fin a:=⟨_,hi.1⟩\n    let source:=SemiprimeD1OriginalModeAcquisition.acquire parent.net.leftCount\n      parent.net.rows.length 64 a u i.val parent.ctx.precision (arity parent.net.rows) (owner parent.net.rows)\n    let q:=SemiprimeD1ModeRate.jetHeight (edgeCount parent.net) u*(u-i.val)\n    have ht:=phaseTotal_clock next parent a u t i hp huM hi.2.1\n    have hw:=ht.1\n    refine ⟨?_,rfl,?_⟩\n    · simp only [List.map_map,Function.comp_def]\n      change ((List.range q).map (fun j =>\n        (SemiprimeD1JetBlockBits.extract parent.ctx j (SemiprimeD1WordTapeRecursivePhase.phaseTotal next parent a u t i).words).words)).toArray=\n        ((List.range q).map (fun j =>\n        (SemiprimeD1JetBlockBits.extract parent.ctx j (SemiprimeD1WordTapeRecursivePhase.phaseTotal (eraseClock next) parent a u t i).words).words)).toArray\n      rw [hw]\n    · have hsum : ((source.modes.values.flatMap (fun beta => (List.finRange 64).map\n          (child parent a u t i beta))).map (fun c => (next c.ctx c.net).clock)).sum=\n        modeChildClocks next parent a u t i := by\n        rw [sum_flatMap]\n        simp only [List.map_map,Function.comp_def,modeChildClocks,source]\n      change _+(SemiprimeD1WordTapeRecursivePhase.phaseTotal next parent a u t i).clock+\n        (((List.range q).map (fun j => SemiprimeD1JetBlockBits.extract parent.ctx j\n          (SemiprimeD1WordTapeRecursivePhase.phaseTotal next parent a u t i).words)).map (fun block => block.clock)).sum+_ =\n        _+(SemiprimeD1WordTapeRecursivePhase.phaseTotal (eraseClock next) parent a u t i).clock+\n        (((List.range q).map (fun j => SemiprimeD1JetBlockBits.extract parent.ctx j\n          (SemiprimeD1WordTapeRecursivePhase.phaseTotal (eraseClock next) parent a u t i).words)).map (fun block => block.clock)).sum+_+_\n      rw [hw,hsum]\n      omega\n  · simp only [List.map_nil,List.sum_nil,Nat.add_zero,and_self]\n\n/-- Actual retained word/tape phase payload cache, not an external getter. -/\ndef retained (next : Context → Network → JetRun) (parent : Call) (a u : ℕ) : Array PhaseRun :=\n  ((List.finRange (SemiprimeD1WireKernelOriginal.size a)).map\n    (SemiprimeD1WordTapeRecursivePhase.phase next parent.ctx parent.net a u)).toArray\n\n/-- Erasing child reports preserves the actual retained payload blocks. -/\ntheorem retained_blocks (next : Context → Network → JetRun) (parent : Call) (a u : ℕ)\n    (hp : parent.ctx.Positive) (huM : u ≤ edgeCount parent.net) :\n    (retained next parent a u).map PhaseRun.blocks=\n      (retained (eraseClock next) parent a u).map PhaseRun.blocks := by\n  apply Array.toList_inj.mp\n  simp only [retained,Array.toList_map,List.map_map,Function.comp_def]\n  apply List.map_congr_left\n  intro t ht\n  exact (phase_clock next parent a u t hp huM).1\n\n/-- Every grid point and repeated tuple/group child keeps its literal multiplicity. -/\ntheorem phases_clock (next : Context → Network → JetRun) (parent : Call) (a u : ℕ)\n    (hp : parent.ctx.Positive) (huM : u ≤ edgeCount parent.net) :\n    (((List.finRange (SemiprimeD1WireKernelOriginal.size a)).map\n      (SemiprimeD1WordTapeRecursivePhase.phase next parent.ctx parent.net a u)).map PhaseRun.clock).sum=\n    (((List.finRange (SemiprimeD1WireKernelOriginal.size a)).map\n      (SemiprimeD1WordTapeRecursivePhase.phase (eraseClock next) parent.ctx parent.net a u)).map PhaseRun.clock).sum+\n    (((List.finRange (SemiprimeD1WireKernelOriginal.size a)).flatMap\n      (phaseChildren parent a u)).map (fun c => (next c.ctx c.net).clock)).sum := by\n  rw [sum_flatMap]\n  simp only [List.map_map,Function.comp_def]\n  have h : ∀t∈List.finRange (SemiprimeD1WireKernelOriginal.size a),\n      (SemiprimeD1WordTapeRecursivePhase.phase next parent.ctx parent.net a u t).clock=\n      (SemiprimeD1WordTapeRecursivePhase.phase (eraseClock next) parent.ctx parent.net a u t).clock+\n      ((phaseChildren parent a u t).map (fun c => (next c.ctx c.net).clock)).sum := by\n    intro t ht\n    exact (phase_clock next parent a u t hp huM).2.2\n  rw [show (List.finRange (SemiprimeD1WireKernelOriginal.size a)).map\n      (fun t => (SemiprimeD1WordTapeRecursivePhase.phase next parent.ctx parent.net a u t).clock)=\n      (List.finRange (SemiprimeD1WireKernelOriginal.size a)).map\n      (fun t => (SemiprimeD1WordTapeRecursivePhase.phase (eraseClock next) parent.ctx parent.net a u t).clock+\n        ((phaseChildren parent a u t).map (fun c => (next c.ctx c.net).clock)).sum) from List.map_congr_left h]\n  exact List.sum_map_add\n\nend RiemannGaussian.SemiprimeD1WordTapeRecursiveClock\n","RiemannGaussian.SemiprimeFiniteEnumerations":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceLayout\n\n/-!\n# Computable finite lists for the native source layout\n\nAll data definitions use explicit lists, constructors and finite-domain function\nrecursion. Classical reasoning is confined to erased proof fields/theorems.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeFiniteEnumerations\nopen scoped BigOperators\nopen OAI.Algorithms.SubexponentialSAT\nopen OAI.Algorithms.SubexponentialSAT.Subexp.ConstructivePacking\nopen OAI.Algorithms.SubexponentialSAT.MulticolorTypes\n\n/-- Literal ascending Fin enumeration. -/\ndef fin (n : ℕ) : FiniteEnumeration (Fin n) :=\n  ⟨List.finRange n, List.nodup_finRange n, List.mem_finRange⟩\n\n/-- Transport through a supplied computable equivalence. -/\ndef transport {A B : Type*} (e : FiniteEnumeration A) (f : A ≃ B) : FiniteEnumeration B where\n  values := e.values.map f\n  nodup := e.nodup.map f.injective\n  complete b := List.mem_map.mpr ⟨f.symm b,e.complete _,f.apply_symm_apply b⟩\n\n/-- Explicit disjoint sum, with all left entries before all right entries. -/\ndef sum {A B : Type*} (a : FiniteEnumeration A) (b : FiniteEnumeration B) : FiniteEnumeration (A ⊕ B) where\n  values := a.values.map Sum.inl ++ b.values.map Sum.inr\n  nodup := by\n    apply List.nodup_append.mpr\n    refine ⟨a.nodup.map Sum.inl_injective,b.nodup.map Sum.inr_injective,?_⟩\n    intro x hx y hy hxy\n    obtain ⟨u,_,rfl⟩ := List.mem_map.mp hx\n    obtain ⟨v,_,rfl⟩ := List.mem_map.mp hy\n    cases hxy\n  complete x := by\n    cases x with\n    | inl x => exact List.mem_append.mpr (Or.inl (List.mem_map.mpr ⟨x,a.complete x,rfl⟩))\n    | inr x => exact List.mem_append.mpr (Or.inr (List.mem_map.mpr ⟨x,b.complete x,rfl⟩))\n\n/-- Explicit Cartesian pair list, with its original lexicographic order. -/\ndef prod {A B : Type*} (a : FiniteEnumeration A) (b : FiniteEnumeration B) : FiniteEnumeration (A × B) where\n  values := a.values.product b.values\n  nodup := a.nodup.product b.nodup\n  complete x := List.mem_product.mpr ⟨a.complete x.1,b.complete x.2⟩\n\n/-- Dependent finite incidence enumeration, without an abstract finite inverse. -/\ndef sigma {A : Type*} {B : A → Type*} (a : FiniteEnumeration A)\n    (b : (i : A) → FiniteEnumeration (B i)) : FiniteEnumeration (Sigma B) where\n  values := a.values.flatMap (fun i => (b i).values.map (Sigma.mk i))\n  nodup := by\n    apply List.nodup_flatMap.mpr\n    constructor\n    · intro i _\n      apply (b i).nodup.map\n      intro x y h\n      cases h\n      rfl\n    · apply a.nodup.imp\n      intro i j hij\n      apply List.disjoint_left.mpr\n      intro z hz hz'\n      obtain ⟨x,_,hx⟩ := List.mem_map.mp hz\n      obtain ⟨y,_,hy⟩ := List.mem_map.mp hz'\n      exact hij (congrArg Sigma.fst (hx.trans hy.symm))\n  complete x := List.mem_flatMap.mpr ⟨x.1,a.complete _,List.mem_map.mpr ⟨x.2,(b x.1).complete _,rfl⟩⟩\n\n/-- All functions on a finite Fin domain, by finite head/tail recursion. -/\ndef pi : (n : ℕ) → {B : Fin n → Type*} → ((i : Fin n) → FiniteEnumeration (B i)) →\n    FiniteEnumeration ((i : Fin n) → B i)\n  | 0, _, _ => ⟨[fun i => Fin.elim0 i],by simp,by\n      intro f\n      have h : f=(fun i => Fin.elim0 i) := by funext i; exact Fin.elim0 i\n      simp [h]⟩\n  | n+1, B, es => transport (prod (es 0) (pi n (fun i => es i.succ))) (Fin.consEquiv B)\n\n@[simp] theorem fin_length (n : ℕ) : (fin n).values.length=n := by simp [fin]\n\n@[simp] theorem transport_length {A B : Type*} (e : FiniteEnumeration A) (f : A ≃ B) :\n    (transport e f).values.length=e.values.length := by simp only [transport, List.length_map]\n\n@[simp] theorem sum_length {A B : Type*} (a : FiniteEnumeration A) (b : FiniteEnumeration B) :\n    (sum a b).values.length=a.values.length+b.values.length := by simp [sum]\n\n@[simp] theorem prod_length {A B : Type*} (a : FiniteEnumeration A) (b : FiniteEnumeration B) :\n    (prod a b).values.length=a.values.length*b.values.length := List.length_product _ _\n\n/-- Exact dependent incidence-list size. -/\ntheorem sigma_length {A : Type*} {B : A → Type*} (a : FiniteEnumeration A)\n    (b : (i : A) → FiniteEnumeration (B i)) :\n    (sigma a b).values.length=(a.values.map (fun i => (b i).values.length)).sum := by\n  simp [sigma, List.length_flatMap]\n\n/-- The function list has the exact finite Cartesian-product size. -/\ntheorem pi_length (n : ℕ) {B : Fin n → Type*} (es : (i : Fin n) → FiniteEnumeration (B i)) :\n    (pi n es).values.length=∏ i, (es i).values.length := by\n  induction n with\n  | zero => simp [pi]\n  | succ n ih => simp only [pi, transport_length, prod_length, ih, Fin.prod_univ_succ]\n\n/-- The actual r^Q source word list. -/\ndef words (r Q : ℕ) : FiniteEnumeration (Word r Q) := pi Q (fun _ => fin r)\n\n/-- The actual universal incidence alphabet for one slot. -/\ndef universal (r Q : ℕ) : FiniteEnumeration (UniversalType r Q 1) :=\n  transport (prod (words r Q) (pi 1 (fun _ => words r Q))) (equivProd r Q 1).symm\n\n/-- All actual score terms, including repetitions in the original incidences. -/\ndef scoreTerms {I V : Type} (inc : FiniteEnumeration I) (vars : FiniteEnumeration V) (Q : ℕ) :\n    FiniteEnumeration (SqrtLog.Packing.ScoreTerm I V Q) :=\n  sum (prod inc inc) (prod (fin Q) (prod vars vars))\n\n/-- Explicit source data from original incidence, variable and factor lists. -/\ndef sourceEnumerations {I V E : Type}\n    (inc : FiniteEnumeration I) (vars : FiniteEnumeration V) (factors : FiniteEnumeration E)\n    (r Q : ℕ) [NeZero r] : SemiprimeSourceLayout.Enumerations I V E r Q where\n  incidences := inc\n  types := universal r Q\n  wordFirst := fun _ => 0\n  wordTail := (words r Q).values.filter (fun w => decide (w ≠ fun _ => 0))\n  words_nodup := by\n    apply List.nodup_cons.mpr\n    constructor\n    · simp\n    · exact (words r Q).nodup.filter _\n  words_complete w := by\n    by_cases hw : w=(fun _ => 0)\n    · simp only [List.mem_cons, hw, true_or]\n    · exact List.mem_cons.mpr (Or.inr (List.mem_filter.mpr ⟨(words r Q).complete w,by simpa using hw⟩))\n  terms := scoreTerms inc vars Q\n  indices := sum vars factors\n\n/-- Complete original dependent ports of an explicit indexed network. -/\ndef indexedIncidences (m : ℕ) (arity : Fin m → ℕ) : FiniteEnumeration ((e : Fin m) × Fin (arity e)) :=\n  sigma (fin m) (fun e => fin (arity e))\n\n/-- Fully specified lists for an original Fin-indexed Boolean network. -/\ndef indexed (n m r Q : ℕ) [NeZero r] (arity : Fin m → ℕ) :\n    SemiprimeSourceLayout.Enumerations ((e : Fin m) × Fin (arity e)) (Fin n) (Fin m) r Q :=\n  sourceEnumerations (indexedIncidences m arity) (fin n) (fin m) r Q\n\n/-- Exact computed word-alphabet length. -/\ntheorem words_length (r Q : ℕ) : (words r Q).values.length=r^Q := by\n  rw [FiniteEnumeration.length_eq_card]\n  exact card_word r Q\n\n/-- Exact computed universal-type alphabet length. -/\ntheorem universal_length (r Q : ℕ) : (universal r Q).values.length=r^(2*Q) := by\n  rw [FiniteEnumeration.length_eq_card, card_universalType]\n  congr 1\n  omega\n\n/-- Exact original indexed incidence count. -/\ntheorem indexedIncidences_length (m : ℕ) (arity : Fin m → ℕ) :\n    (indexedIncidences m arity).values.length=∑ e, arity e := by\n  rw [FiniteEnumeration.length_eq_card]\n  simp\n\nsection Search\nvariable {I V E : Type} [Fintype I] [Fintype V] [Fintype E]\n  [DecidableEq I] [DecidableEq V] [DecidableEq E] {r Q : ℕ} [NeZero r]\n\n/-- Compiled conditional-expectation data path. No noncomputable SourceLayout\nwrapper is called; finite type dictionaries and all lists are explicit inputs. -/\ndef searchWords (owner : I → V) (factor : I → E)\n    (en : SemiprimeSourceLayout.Enumerations I V E r Q) (ε : ℚ) :\n    SqrtLog.Packing.WordAssignment V E r Q :=\n  SqrtLog.Packing.computedWords owner factor en.wordFirst en.wordTail en.terms.values en.indices.values\n    (ε*(Fintype.card I : ℚ)/(Fintype.card (UniversalType r Q 1) : ℚ))\n    ((Fintype.card V : ℚ)/(2*(r : ℚ)))\n\nomit [Fintype E] [DecidableEq I] [NeZero r] in\n/-- The compiled word search is literally the one used by the proved layout. -/\ntheorem searchWords_eq (owner : I → V) (factor : I → E)\n    (en : SemiprimeSourceLayout.Enumerations I V E r Q) (ε : ℚ) :\n    searchWords owner factor en ε=SemiprimeSourceLayout.searchedWords owner factor en ε := rfl\n\n/-- Compiled complete buckets, minimum scans, lookup and literal leftovers. -/\ndef searchPacking (owner : I → V) (factor : I → E)\n    (en : SemiprimeSourceLayout.Enumerations I V E r Q) (ε : ℚ) :\n    PackingData I (UniversalType r Q 1) :=\n  SqrtLog.Packing.computedPacking owner factor en.incidences en.types en.wordFirst en.wordTail\n    en.terms.values en.indices.values\n    (ε*(Fintype.card I : ℚ)/(Fintype.card (UniversalType r Q 1) : ℚ))\n    ((Fintype.card V : ℚ)/(2*(r : ℚ)))\n\nomit [Fintype E] [DecidableEq I] [NeZero r] in\n/-- The compiled packing is the layout's actual searched packing on these lists. -/\ntheorem searchPacking_eq (owner : I → V) (factor : I → E)\n    (en : SemiprimeSourceLayout.Enumerations I V E r Q) (ε : ℚ) :\n    searchPacking owner factor en ε=SemiprimeSourceLayout.searchedPacking owner factor en ε := rfl\n\n/-- The source instrumentation runs the same compiled local word computations. -/\ndef searchWordsCounted (owner : I → V) (factor : I → E)\n    (en : SemiprimeSourceLayout.Enumerations I V E r Q) (ε : ℚ) :\n    SqrtLog.Packing.WordAssignment V E r Q × ℕ :=\n  SqrtLog.Packing.computedWordsCounted owner factor en.wordFirst en.wordTail en.terms.values en.indices.values\n    (ε*(Fintype.card I : ℚ)/(Fintype.card (UniversalType r Q 1) : ℚ))\n    ((Fintype.card V : ℚ)/(2*(r : ℚ)))\n\nomit [Fintype E] [DecidableEq I] [NeZero r] in\n/-- The operationally counted word result is the actual uncounted result. -/\ntheorem searchWordsCounted_value (owner : I → V) (factor : I → E)\n    (en : SemiprimeSourceLayout.Enumerations I V E r Q) (ε : ℚ) :\n    (searchWordsCounted owner factor en ε).1=searchWords owner factor en ε :=\n  SqrtLog.Packing.computedWordsCounted_value owner factor _ _ _ _ _ _\n\nomit [Fintype E] [DecidableEq I] [NeZero r] in\n/-- Actual local-term evaluation count, not a supplied exponential computation. -/\ntheorem searchWordsCounted_calls (owner : I → V) (factor : I → E)\n    (en : SemiprimeSourceLayout.Enumerations I V E r Q) (ε : ℚ) :\n    (searchWordsCounted owner factor en ε).2 ≤\n      en.indices.values.length*(2*en.wordTail.length*(en.terms.values.length*(en.wordFirst::en.wordTail).length^4)) :=\n  SqrtLog.Packing.computedWordsCounted_calls_le owner factor _ _ _ _ _ _\n\nend Search\n\n/-- A fully compiled original indexed-network word supplier. -/\ndef indexedWords (n m r Q : ℕ) [NeZero r] (arity : Fin m → ℕ)\n    (coordinate : (e : Fin m) → Fin (arity e) → Fin n) (ε : ℚ) :\n    SqrtLog.Packing.WordAssignment (Fin n) (Fin m) r Q :=\n  searchWords (fun i : (e : Fin m) × Fin (arity e) => coordinate i.1 i.2) Sigma.fst\n    (indexed n m r Q arity) ε\n\n/-- A fully compiled original indexed-network complete-bucket supplier. -/\ndef indexedPacking (n m r Q : ℕ) [NeZero r] (arity : Fin m → ℕ)\n    (coordinate : (e : Fin m) → Fin (arity e) → Fin n) (ε : ℚ) :\n    PackingData ((e : Fin m) × Fin (arity e)) (UniversalType r Q 1) :=\n  searchPacking (fun i : (e : Fin m) × Fin (arity e) => coordinate i.1 i.2) Sigma.fst\n    (indexed n m r Q arity) ε\n\nend RiemannGaussian.SemiprimeFiniteEnumerations\n\n#print axioms RiemannGaussian.SemiprimeFiniteEnumerations.searchPacking_eq\n#print axioms RiemannGaussian.SemiprimeFiniteEnumerations.searchWordsCounted_calls\n","RiemannGaussian.SemiprimeHermiteBitsScheduledController":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeHermiteBitsPublicController\nimport RiemannGaussian.SemiprimeCachedSourceScheduledExecution\n\n/-!\n# N-only controller calling the physical Hermite counter\n\nThe only runtime input is N. Actual cached-source queries, floor operations,\nzero-first recovery, and physical operand reconstruction retain their reports.\nThe literal schedule/guard and public enumeration construction still require\ntheir separate setup/physical-bit refinements; no complete bit clock is inferred\nfrom the selected scalar/list/branch ledger below.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1600000\nnamespace RiemannGaussian.SemiprimeHermiteBitsScheduledController\nopen SemiprimeHermiteBitsPublicController SemiprimePublicAcquiredExecution\nopen SemiprimeScheduledFactorExecution\n\n/-- Additional actual branch/report control leaves the acquired result unchanged. -/\ndef bump (r : FactorRun) (n : ℕ) : FactorRun := ⟨r.value,r.queries,r.work+n⟩\n\n/-- Execute the actual finite trial interval, with every tested remainder retained. -/\ndef trialList (N : ℕ) : List ℕ → FactorRun\n  | [] => ⟨none,0,1⟩\n  | p::ps => if 2≤ p ∧ N%p=0 then ⟨some p,0,5⟩ else\n    let tail := trialList N ps\n    ⟨tail.value,0,tail.work+5⟩\n\n/-- Literal finite fallback has the same chosen first divisor as the old algorithm. -/\ntheorem trialList_value (N : ℕ) (xs : List ℕ) :\n    (trialList N xs).value=xs.find? (fun p => decide (2≤ p ∧ N%p=0)) := by\n  induction xs with\n  | nil => rfl\n  | cons p ps ih => by_cases h : 2≤ p ∧ N%p=0 <;> simp [trialList,h,ih]\n\n/-- Every actual finite trial step contributes to the selected-operation report. -/\ntheorem trialList_work (N : ℕ) (xs : List ℕ) : (trialList N xs).work≤5*xs.length+1 := by\n  induction xs with\n  | nil => simp [trialList]\n  | cons p ps ih => by_cases h : 2≤ p ∧ N%p=0 <;>\n      simp [trialList,h,List.length_cons] <;> omega\n\n/-- Explicit ascending finite interval construction, retaining list/loop work. -/\ndef rangeFrom : ℕ → ℕ → SemiprimePaidPrefixController.Run (List ℕ)\n  | 0, _ => ⟨[],1⟩\n  | n+1, start => let tail := rangeFrom n (start+1); ⟨start::tail.value,tail.work+3⟩\n\n/-- The acquired interval is the literal original ascending range. -/\ntheorem rangeFrom_value (n start : ℕ) : (rangeFrom n start).value=List.range' start n := by\n  induction n generalizing start with\n  | zero => rfl\n  | succ n ih => simp only [rangeFrom,ih,List.range'_succ,Nat.add_one]\n\n/-- Each interval cell, successor and recursive step is accounted for. -/\ntheorem rangeFrom_work (n start : ℕ) : (rangeFrom n start).work=3*n+1 := by\n  induction n generalizing start with\n  | zero => rfl\n  | succ n ih => simp only [rangeFrom,ih]; omega\n\n/-- Acquire the actual finite range and retain its full trial scan. -/\ndef trial (N : ℕ) : FactorRun :=\n  let candidates := rangeFrom N 0\n  let result := trialList N candidates.value\n  bump result (candidates.work+1)\n\n/-- Trial range allocation and each tested scalar remainder are included. -/\ntheorem trial_work (N : ℕ) : (trial N).work≤8*N+3 := by\n  have h := trialList_work N (List.range N)\n  simp only [List.length_range] at h\n  simp only [trial,bump,rangeFrom_work,rangeFrom_value,← List.range_eq_range']\n  omega\n\n/-- Exact old fallback output, without a divisor answer input. -/\ntheorem trial_value (N : ℕ) : (trial N).value=trialFactor N :=\n  by simpa only [trial,bump,rangeFrom_value,← List.range_eq_range',trialFactor] using trialList_value N (List.range N)\n\n/-- Entire deterministic factor algorithm. Counter values and all their reports\nare acquired internally, never supplied through a public count callback. -/\ndef run (N : ℕ) : FactorRun :=\n  if hN : 0< N then\n    if hr : 0< groups N then\n      letI : NeZero (groups N) := ⟨Nat.ne_of_gt hr⟩\n      if fastGuard N then\n        bump (SemiprimeHermiteBitsPublicController.factor N hN (groups N) (points N)\n          (epsilon N) (degree N) (precision N)) 3\n      else bump (trial N) 3\n    else bump (trial N) 2\n  else ⟨none,0,1⟩\n\n/-- EVERY-N exact value equivalence; work reports are NOT identified or discarded. -/\ntheorem run_value (N : ℕ) : (run N).value=SemiprimeCachedSourceScheduledExecution.run N := by\n  by_cases hN : 0< N\n  · by_cases hr : 0< groups N\n    · let _ : NeZero (groups N) := ⟨Nat.ne_of_gt hr⟩\n      by_cases hg : fastGuard N\n      · have hQ : 1≤ points N := Nat.le_trans (by decide : 1≤2) hg.2.2.2.1\n        have hAQ := guard_interval N hg\n        have hp := precision_valid N hN (guard_points_pos N hg)\n        simpa only [run,SemiprimeCachedSourceScheduledExecution.run,dite_eq_left hN,\n          dite_eq_left hr,ite_eq_left hg,bump] using\n          SemiprimeHermiteBitsPublicController.factor_value N hN (groups N) (points N)\n            (epsilon N) (degree N) (precision N) hQ hAQ hp.1 hp.2\n      · simpa only [run,SemiprimeCachedSourceScheduledExecution.run,dite_eq_left hN,\n          dite_eq_left hr,ite_eq_right hg,bump] using trial_value N\n    · simpa only [run,SemiprimeCachedSourceScheduledExecution.run,dite_eq_left hN,dite_eq_right hr,bump] using trial_value N\n  · simp only [run,SemiprimeCachedSourceScheduledExecution.run,dite_eq_right hN]\n\n/-- Every actual returned value is a proper integer factor. -/\ntheorem run_sound (N p : ℕ) (h : (run N).value=some p) : 2≤ p ∧ p< N ∧ p∣N :=\n  SemiprimeCachedSourceScheduledExecution.run_sound N p ((run_value N).symm.trans h)\n\n/-- All-input completeness, including zero, one, primes and perfect squares. -/\ntheorem run_none_iff (N : ℕ) :\n    (run N).value=none ↔ ¬Nonempty (SemiprimePublicFactorCount.OrdinaryFactors N) := by\n  rw [run_value]\n  exact SemiprimeCachedSourceScheduledExecution.run_none_iff N\n\nopen Filter in\n/-- The eventual fast branch actually invokes the word-packet controller. -/\ntheorem eventually_run_nativeBits : ∀ᶠ N : ℕ in atTop,\n    ∃ hN : 0< N, ∃ hg : fastGuard N,\n      letI : NeZero (groups N) := ⟨Nat.ne_of_gt (guard_groups_pos N hg)⟩\n      run N=bump (SemiprimeHermiteBitsPublicController.factor N hN (groups N) (points N)\n        (epsilon N) (degree N) (precision N)) 3 := by\n  filter_upwards [eventually_fastGuard,eventually_gt_atTop 0] with N hg hN\n  exact ⟨hN,hg,by simp only [run,dite_eq_left hN,dite_eq_left (guard_groups_pos N hg),ite_eq_left hg]⟩\n\n/-- Fast-branch aggregate bound: countBudget is a bound on the ACTUAL internal\ncounter report, while all additional prefix/recovery/decoder work is explicit. -/\ntheorem run_fast_work (N : ℕ) (hN : 0< N) (hg : fastGuard N) [NeZero (groups N)] (B : ℕ)\n    (hb : ∀ fixed, fixed.length≤ wireCount N →\n      (SemiprimeHermiteBitsPublicController.counter N hN (groups N) (points N)\n        (epsilon N) (degree N) (precision N) fixed).work≤ B) :\n    (run N).work≤(wireCount N+1)*\n      (B+wireCount N+3*(wireCount N+1)^2+SemiprimePaidFactorDecoder.budget N (wireCount N)+19) := by\n  have hf := SemiprimeHermiteBitsPublicController.factor_work N hN (groups N) (points N)\n    (epsilon N) (degree N) (precision N) B hb\n  simp only [run,dite_eq_left hN,dite_eq_left (guard_groups_pos N hg),ite_eq_left hg,bump]\n  nlinarith\n\nend RiemannGaussian.SemiprimeHermiteBitsScheduledController\n","RiemannGaussian.SemiprimeHermiteEvaluationBits":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeWordFoldArithmetic\nimport RiemannGaussian.SemiprimeHermiteArrayHeight\n\n/-! # Physical Hermite scalar evaluation\n\nThe actual ascending evaluation caches its scalar and integer power. Affine\nproducts retain one suffix result. Input acquisition is separate; every arithmetic\ninstruction here executes on Boolean rational words and retains its clock.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2000000\nnamespace RiemannGaussian.SemiprimeHermiteEvaluationBits\nopen SemiprimeRationalBits SemiprimeJetBits SemiprimeDotBits\nopen SemiprimeJetArrayHeight SemiprimeHermiteArrayHeight\n\n/-- Actual physical evaluation state. -/\nstructure EvalReport where\n  /-- Cached accumulated value. -/\n  word : RationalWord\n  /-- Cached argument power. -/\n  power : RationalWord\n  /-- Retained arithmetic and finite-cell work. -/\n  clock : ℕ\n\n/-- Ascending-power evaluation, matching the scalar recurrence literally. -/\ndef evalPrefix (template : List Bool) (a : Array RationalWord) (x : RationalWord) : ℕ → EvalReport\n  | 0 => ⟨zeroWord,oneWord,4⟩\n  | len+1 =>\n    let old := evalPrefix template a x len\n    let term := executeOperation .mul (wordAt a len) old.power template\n    let value := executeOperation .add old.word term.word template\n    let power := executeOperation .mul old.power x template\n    ⟨value.word,power.word,old.clock+term.clock+value.clock+power.clock+accessCost template a+8*template.length+12⟩\n\n/-- The exact suffix product of the acquired affine factors. -/\ndef affineValue (template : List Bool) (x : RationalWord) : List RationalWord → RationalReport\n  | [] => ⟨oneWord,4⟩\n  | c::cs =>\n    let old := affineValue template x cs\n    let term := executeOperation .mul c x template\n    let factor := executeOperation .add oneWord term.word template\n    let out := executeOperation .mul old.word factor.word template\n    ⟨out.word,old.clock+term.clock+factor.clock+out.clock+8*template.length+12⟩\n\n/-- A common representation gives an instruction's reduced binary bounds. -/\ntheorem fits_of_representation {q : ℚ} {d B W : ℕ} (hd : 0<d)\n    (hq : Representation q d B) (hden : d<2^W) (hnum : B<2^W) : Fits q W := by\n  have h := representation_reduced_bound hd hq\n  exact ⟨h.2.trans_lt hnum,h.1.trans_lt hden⟩\n\n/-- Exact physical evaluation from original coefficient and integer-argument bounds.\nThe two numeric caps concern original input data, not intermediate advice. -/\ntheorem evalPrefix_correct (template : List Bool) (a : Array RationalWord)\n    (xw : RationalWord) (x : ℤ) (d B T J len : ℕ)\n    (hd : 0<d) (ha : Valid a) (hxw : xw.Valid) (hxval : xw.value=(x:ℚ))\n    (hx : x.natAbs≤T) (hlen : len≤J)\n    (hcoeff : ∀ i<J,Representation (SemiprimeJetArray.coefficient (decode a) i) d B)\n    (hden : d<2^template.length)\n    (hnum : (J+1)*(B+1)*(T+1)^(J+1)<2^template.length) :\n    (evalPrefix template a xw len).word.value=\n      (SemiprimeHermiteArrayHeight.evalPrefix (decode a) x len).value ∧\n    (evalPrefix template a xw len).power.value=(x:ℚ)^len ∧\n    (evalPrefix template a xw len).word.Valid ∧\n    (evalPrefix template a xw len).power.Valid := by\n  have hpow : ∀ k≤J+1,(x^k).natAbs≤(T+1)^(J+1) := by\n    intro k hk\n    rw [Int.natAbs_pow]\n    exact (Nat.pow_le_pow_left (by omega : x.natAbs≤T+1) k).trans\n      (Nat.pow_le_pow_right (by omega) hk)\n  have hbase : 1≤(T+1)^(J+1) := Nat.one_le_pow _ _ (by omega)\n  have hone : 1<2^template.length := by\n    have hb : 1≤(J+1)*(B+1)*(T+1)^(J+1) := Nat.one_le_iff_ne_zero.mpr (by positivity)\n    omega\n  have hpfit : ∀ k≤J+1,Fits ((x:ℚ)^k) template.length := by\n    intro k hk\n    have hr := representation_integer (x^k)\n    have hn : (x^k).natAbs<2^template.length := by\n      have he : (T+1)^(J+1)≤(J+1)*(B+1)*(T+1)^(J+1) := by\n        simpa only [Nat.one_mul] using Nat.mul_le_mul_right ((T+1)^(J+1))\n          (Nat.one_le_iff_ne_zero.mpr (by positivity))\n      exact (hpow k hk).trans_lt (he.trans_lt hnum)\n    simpa only [Int.cast_pow] using fits_of_representation (by decide : 0<1) hr hone hn\n  induction len with\n  | zero => simp [evalPrefix,SemiprimeHermiteArrayHeight.evalPrefix,zeroWord_value,\n      oneWord_valid,zeroWord_valid]\n  | succ len ih =>\n    have ho := ih (by omega)\n    have hterm : Representation ((wordAt a len).value*(x:ℚ)^len) d\n        (B*(T+1)^(J+1)) := by\n      have hc := hcoeff len (by omega)\n      rw [coefficient_decode] at hc\n      simpa only [Int.cast_pow] using representation_integer_mul hc (x^len) (hpow len (by omega))\n    have htfit := fits_of_representation hd hterm hden (by\n      have he : B*(T+1)^(J+1)≤(J+1)*(B+1)*(T+1)^(J+1) := by\n        exact Nat.mul_le_mul_right _ ((Nat.le_add_right B 1).trans\n          (by simpa only [Nat.one_mul] using Nat.mul_le_mul_right (B+1) (show 1≤J+1 by omega)))\n      exact he.trans_lt hnum)\n    have ht := executeOperation_correct .mul (wordAt a len) (evalPrefix template a xw len).power\n      template (wordAt_valid a ha len) ho.2.2.2 (by simpa only [Operation.value,ho.2.1] using htfit)\n    have hvrep' := evalPrefix_representation (decode a) x d B T J (len+1) hx hlen hcoeff\n    have hvnum : (len+1)*B*(T+1)^J<2^template.length := by\n      have hp : (T+1)^J≤(T+1)^(J+1) := Nat.pow_le_pow_right (by omega) (by omega)\n      have he : (len+1)*B*(T+1)^J≤(J+1)*(B+1)*(T+1)^(J+1) :=\n        Nat.mul_le_mul (Nat.mul_le_mul (by omega) (by omega)) hp\n      exact he.trans_lt hnum\n    have hvfit := fits_of_representation hd hvrep' hden hvnum\n    have hv := executeOperation_correct .add (evalPrefix template a xw len).word\n      (executeOperation .mul (wordAt a len) (evalPrefix template a xw len).power template).word\n      template ho.2.2.1 ht.2.1 (by\n        simpa only [Operation.value,ho.1,ht.1,Operation.value,ho.2.1,\n          SemiprimeHermiteArrayHeight.evalPrefix,coefficient_decode,evalPrefix_power] using hvfit)\n    have hp := executeOperation_correct .mul (evalPrefix template a xw len).power xw template\n      ho.2.2.2 hxw (by simpa only [Operation.value,ho.2.1,hxval,pow_succ] using hpfit (len+1) (by omega))\n    refine ⟨?_,?_,hv.2.1,hp.2.1⟩\n    · simpa only [evalPrefix,Operation.value,ho.1,ht.1,ho.2.1,\n        SemiprimeHermiteArrayHeight.evalPrefix,coefficient_decode,evalPrefix_power] using hv.1\n    · simpa only [evalPrefix,Operation.value,ho.2.1,hxval,pow_succ] using hp.1\n\n/-- Every affine suffix has a power of the ORIGINAL common denominator.\nThe scalar product uses no inverse and no intermediate height advice. -/\ntheorem affineValue_correct (template : List Bool) (xw : RationalWord) (x : ℤ)\n    (cs : List RationalWord) (d B T J : ℕ) (hd : 0<d)\n    (hxw : xw.Valid) (hxval : xw.value=(x:ℚ)) (hx : x.natAbs≤T)\n    (hlen : cs.length≤J)\n    (hc : ∀ c∈cs,c.Valid ∧ Representation c.value d B)\n    (hden : d^J<2^template.length)\n    (hnum : (d+B*T+1)^(J+1)<2^template.length) :\n    (affineValue template xw cs).word.value=\n      (SemiprimeHermiteArrayHeight.affineValue x (cs.map RationalWord.value)).value ∧\n    (affineValue template xw cs).word.Valid ∧\n    Representation (affineValue template xw cs).word.value\n      (d^cs.length) ((d+B*T+1)^cs.length) := by\n  have hone : 1<2^template.length :=\n    (Nat.one_le_pow J d (by omega)).trans_lt hden\n  have hdsmall : d<2^template.length := by\n    have hp : d≤d+B*T+1 := by omega\n    exact (hp.trans (Nat.le_self_pow (by omega : J+1≠0) (d+B*T+1))).trans_lt hnum\n  induction cs with\n  | nil =>\n    simp only [affineValue,List.map_nil,SemiprimeHermiteArrayHeight.affineValue,\n      oneWord_value,oneWord_valid,List.length_nil,pow_zero,true_and]\n    exact representation_one 1 (by decide)\n  | cons c cs ih =>\n    have hi := ih (by simpa only [List.length_cons] using (show cs.length+1≤J from hlen) |> fun h => by omega)\n      (fun z hz => hc z (List.mem_cons_of_mem c hz))\n    have hc' := hc c List.mem_cons_self\n    have hr := representation_integer_mul hc'.2 x hx\n    have hnterm : B*T<2^template.length := by\n      exact (show B*T≤d+B*T+1 by omega).trans_lt\n        ((Nat.le_self_pow (by omega : J+1≠0) (d+B*T+1)).trans_lt hnum)\n    have ht := executeOperation_correct .mul c xw template hc'.1 hxw\n      (by simpa only [Operation.value,hxval] using fits_of_representation hd hr hdsmall hnterm)\n    have hfRep := representation_add_one hr hd\n    have hnf : d+B*T<2^template.length := by\n      exact (Nat.le_succ _).trans_lt\n        ((Nat.le_self_pow (by omega : J+1≠0) (d+B*T+1)).trans_lt hnum)\n    have hf := executeOperation_correct .add oneWord\n      (executeOperation .mul c xw template).word template oneWord_valid ht.2.1\n      (by simpa only [Operation.value,oneWord_value,ht.1,hxval] using\n        fits_of_representation hd hfRep hdsmall hnf)\n    have hfrep : Representation\n        (executeOperation .add oneWord (executeOperation .mul c xw template).word template).word.value\n        d (d+B*T+1) := by\n      rw [hf.1,Operation.value,oneWord_value,ht.1,Operation.value,hxval]\n      exact representation_mono hfRep (by omega)\n    have hmrep := representation_mul hi.2.2 hfrep\n    have hmd : d^cs.length*d<2^template.length := by\n      rw [← pow_succ]\n      exact (Nat.pow_le_pow_right (by omega) (by simpa only [List.length_cons] using hlen)).trans_lt hden\n    have hmn : (d+B*T+1)^cs.length*(d+B*T+1)<2^template.length := by\n      rw [← pow_succ]\n      exact (Nat.pow_le_pow_right (by omega) (by simp only [List.length_cons] at hlen; omega)).trans_lt hnum\n    have hm := executeOperation_correct .mul (affineValue template xw cs).word\n      (executeOperation .add oneWord (executeOperation .mul c xw template).word template).word\n      template hi.2.1 hf.2.1 (fits_of_representation (Nat.mul_pos (Nat.pow_pos hd) hd) hmrep hmd hmn)\n    refine ⟨?_,hm.2.1,?_⟩\n    · simp only [affineValue,hm.1,Operation.value,hi.1,hf.1,oneWord_value,\n        ht.1,hxval,List.map_cons,SemiprimeHermiteArrayHeight.affineValue]\n    · change Representation (executeOperation .mul _ _ template).word.value _ _\n      rw [hm.1]\n      simpa only [List.length_cons,pow_succ,Operation.value] using hmrep\n\n/-- The output representation follows from the ORIGINAL common coefficient bound. -/\ntheorem evalPrefix_representation (template : List Bool) (a : Array RationalWord)\n    (xw : RationalWord) (x : ℤ) (d B T J len : ℕ)\n    (hd : 0<d) (ha : Valid a) (hxw : xw.Valid) (hxval : xw.value=(x:ℚ))\n    (hx : x.natAbs≤T) (hlen : len≤J)\n    (hcoeff : ∀ i<J,Representation (SemiprimeJetArray.coefficient (decode a) i) d B)\n    (hden : d<2^template.length)\n    (hnum : (J+1)*(B+1)*(T+1)^(J+1)<2^template.length) :\n    Representation (evalPrefix template a xw len).word.value d (len*B*(T+1)^J) := by\n  rw [(evalPrefix_correct template a xw x d B T J len hd ha hxw hxval hx hlen hcoeff hden hnum).1]\n  exact SemiprimeHermiteArrayHeight.evalPrefix_representation (decode a) x d B T J len hx hlen hcoeff\n\nend RiemannGaussian.SemiprimeHermiteEvaluationBits\n","RiemannGaussian.SemiprimeLocalBits":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeJetBits\nimport RiemannGaussian.SemiprimeLocalExecutionBitBounds\n\n/-! # Physical-word local multilinear interpolation\nTruth entries are actual signed words. Recursive branches and all rational word\noperations are executed, cached, and charged; interpretation is proof-only.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1600000\nnamespace RiemannGaussian.SemiprimeLocalBits\nopen scoped BigOperators\nopen SemiprimeRationalBits SemiprimeDotBits SemiprimeJetBits\nopen SemiprimeBitIndexClipping SemiprimeJetArray SemiprimeJetArrayHeight\nopen SemiprimeLocalArrayFrontend SemiprimeLocalExecutionHeight\n\n/-- Actual signed integer entry and the callback's paid bit work. -/\nstructure EntryWord where\n  /-- Physical signed integer output. -/\n  bits : SignedWord\n  /-- Actual callback work. -/\n  clock : ℕ\n\n/-- Denominator-one encoding; no rational-valued supplier is called. -/\ndef EntryWord.rational (e : EntryWord) : RationalWord := ⟨e.bits,[true]⟩\n\n/-- The frozen integer table used only by the refinement statement. -/\ndef table {w : ℕ} (T : (Fin w → Bool) → EntryWord) (eta : Fin w → Bool) : EntryReport :=\n  ⟨(T eta).bits.value,0,0⟩\n\n@[simp] theorem entry_value (e : EntryWord) : e.rational.value=(e.bits.value : ℚ) := by\n  simp [EntryWord.rational,RationalWord.value,SemiprimeBitArithmetic.bitValue,SemiprimeBitArithmetic.bitNat]\n\n/-- Every integer-entry word has a legal literal denominator. -/\ntheorem entry_valid (e : EntryWord) : e.rational.Valid := by change 0<1; decide\n\n/-- Materialized literal one jet. -/\ndef oneArray (J : ℕ) : Array RationalWord :=\n  Array.ofFn (fun i : Fin J => if i.val=0 then oneWord else zeroWord)\n\n@[simp] theorem oneArray_size (J : ℕ) : (oneArray J).size=J := by simp [oneArray]\n\ntheorem oneArray_valid (J : ℕ) : Valid (oneArray J) := by\n  intro i hi\n  simp only [oneArray,Array.getElem_ofFn]\n  split_ifs <;> exact (by change 0<1; decide)\n\ntheorem oneArray_bounded (J W : ℕ) (hW : 0<W) : Bounded (oneArray J) W := by\n  intro i hi\n  simp only [oneArray,Array.getElem_ofFn]\n  split_ifs\n  · exact oneWord_width hW\n  · simp only [zeroWord,Width,List.length_nil,List.length_cons]\n    omega\n\ntheorem oneArray_coefficient (J i : ℕ) (hi : i<J) :\n    coefficient (decode (oneArray J)) i = coefficient (SemiprimeArrayOps.oneJet J).coefficients i := by\n  simp [oneArray,decode,coefficient,hi,SemiprimeArrayOps.oneJet,apply_ite,zeroWord_value]\n\n/-- Cached depth-first physical evaluator, with the actual leaf callback clock. -/\ndef localEvaluateBits (template : List Bool) (J : ℕ) : (w : ℕ) →\n    ((Fin w → Bool) → EntryWord) → (Fin w → Array RationalWord) → JetReport\n  | 0,T,_ =>\n      let e := T Fin.elim0\n      let one := oneArray J\n      let out := scaleBits template one e.rational J\n      ⟨out.words,e.clock+out.clock+3*J+4⟩\n  | w+1,T,inputs =>\n      let lo := localEvaluateBits template J w (fun eta => T (Fin.cons false eta)) (fun i => inputs i.succ)\n      let hi := localEvaluateBits template J w (fun eta => T (Fin.cons true eta)) (fun i => inputs i.succ)\n      let one := oneArray J\n      let neg := scaleBits template (inputs 0) negOneWord J\n      let no := addBits template one neg.words J\n      let left := multiplyBits template no.words lo.words J\n      let right := multiplyBits template (inputs 0) hi.words J\n      let out := addBits template left.words right.words J\n      ⟨out.words,lo.clock+hi.clock+neg.clock+no.clock+left.clock+right.clock+out.clock+3*J+12⟩\n\n/-- Every physical branch result has the retained width. -/\ntheorem localEvaluateBits_size (template : List Bool) (J w : ℕ)\n    (T : (Fin w → Bool) → EntryWord) (inputs : Fin w → Array RationalWord) :\n    (localEvaluateBits template J w T inputs).words.size=J := by\n  cases w <;> simp [localEvaluateBits]\n\n/-- Physical fitting gives bounded buffers without assuming arithmetic correctness. -/\ntheorem localEvaluateBits_bounded (template : List Bool) (J w : ℕ)\n    (T : (Fin w → Bool) → EntryWord) (inputs : Fin w → Array RationalWord) :\n    Bounded (localEvaluateBits template J w T inputs).words template.length := by\n  cases w with\n  | zero => exact scaleBits_bounded _ _ _ _\n  | succ w => exact addBits_bounded _ _ _ _\n\n/-- Numeric cap derived from port denominators, coefficient bounds and branch arity. -/\ndef cap (J d B w : ℕ) : ℕ := (d+1)^w + (localBase J d B+1)^w + d+B+2\n\n/-- Restricting a truth branch never increases the numeric cap. -/\ntheorem cap_mono (J d B : ℕ) {s w : ℕ} (h : s ≤ w) : cap J d B s≤cap J d B w := by\n  unfold cap\n  have h₁ := Nat.pow_le_pow_right (show 0<d+1 by omega) h\n  have h₂ := Nat.pow_le_pow_right (show 0<localBase J d B+1 by omega) h\n  omega\n\n/-- Low-coefficient equality, used for intermediate primitive refinements. -/\ndef EqualBelow (J : ℕ) (a b : Array ℚ) : Prop := ∀ i<J, coefficient a i=coefficient b i\n\n/-- A frozen addition depends only on its retained input coefficients. -/\ntheorem add_congr (J : ℕ) {a b c d : Array ℚ} (h₁ : EqualBelow J a b) (h₂ : EqualBelow J c d) :\n    EqualBelow J (SemiprimeArrayOps.addJet a c J).coefficients (SemiprimeArrayOps.addJet b d J).coefficients := by\n  intro i hi\n  rw [SemiprimeArrayOps.addJet_coefficient _ _ J i hi,SemiprimeArrayOps.addJet_coefficient _ _ J i hi,h₁ i hi,h₂ i hi]\n\n/-- A frozen convolution depends only on its retained input coefficients. -/\ntheorem multiply_congr (J : ℕ) {a b c d : Array ℚ} (h₁ : EqualBelow J a b) (h₂ : EqualBelow J c d) :\n    EqualBelow J (multiply a c J).coefficients (multiply b d J).coefficients := by\n  intro i hi\n  rw [multiply_coefficient _ _ J i hi,multiply_coefficient _ _ J i hi]\n  apply Finset.sum_congr rfl\n  intro k hk\n  have hki : k ≤ i := Nat.le_of_lt_succ (Finset.mem_range.mp hk)\n  rw [h₁ k (by omega),h₂ (i-k) (by omega)]\nend RiemannGaussian.SemiprimeLocalBits\n","RiemannGaussian.SemiprimeLocalExecutionBitBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeLocalExecutionHeight\nimport RiemannGaussian.SemiprimeRationalBits\n\n/-!\n# Polynomial bit budgets for the local interpreter's actual states\n\nThe inequalities convert the literal numerator/denominator representations to\nnormalized rational fits. They do not assert a primitive interpreter has already\nbeen assembled, and do not assume that desired intermediate outputs fit.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeLocalExecutionBitBounds\nopen SemiprimeLocalExecutionHeight SemiprimeLocalArrayFrontend\nopen SemiprimeJetArray SemiprimeJetArrayHeight SemiprimeRationalBits\n\n/-- A scalar represented with dyadically bounded numerator and denominator fits\none additional bit beyond their larger exponent. -/\ntheorem representation_fits {q : ℚ} {d B a b : ℕ} (hd : 0<d)\n    (h : Representation q d B) (hdB : d ≤ 2^a) (hBB : B ≤ 2^b) :\n    Fits q (a+b+1) := by\n  apply fits_of_representation hd h\n  · exact hBB.trans_lt (Nat.pow_lt_pow_right (by decide) (by omega))\n  · exact hdB.trans_lt (Nat.pow_lt_pow_right (by decide) (by omega))\n\n/-- The multiplier in the source Horner bound has only O(b) bits. -/\ntheorem horner_base_le (J T b : ℕ) (hJ : J ≤ 2^b) (hT : T ≤ 2^b) :\n    1+J*(T+1) ≤ 2^(2*b+2) := by\n  have hp : 1 ≤ 2^b := Nat.one_le_pow _ _ (by decide)\n  have hm := Nat.mul_le_mul hJ (Nat.add_le_add_right hT 1)\n  have he : 2^(2*b+2) = 4*(2^b)^2 := by\n    rw [show 2*b+2=b+b+2 by omega, pow_add, pow_add]\n    norm_num\n    ring\n  rw [he]\n  nlinarith\n\n/-- Every Horner suffix numerator has a bit budget linear in its source length. -/\ntheorem hornerBound_le (J B T b len : ℕ)\n    (hJ : J ≤ 2^b) (hB : B ≤ 2^b) (hT : T ≤ 2^b) :\n    hornerBound J B T len ≤ 2^(b+(2*b+2)*len) := by\n  have hm := Nat.mul_le_mul hB (Nat.pow_le_pow_left (horner_base_le J T b hJ hT) len)\n  simpa only [hornerBound, ← pow_mul, ← pow_add] using hm\n\n/-- The completed local interpolation base has at most 2b+2 bits. -/\ntheorem localBase_le (J d B b : ℕ) (hJ : J ≤ 2^b) (hd : d ≤ 2^b) (hB : B ≤ 2^b) :\n    localBase J d B ≤ 2^(2*b+2) := by\n  have hm := Nat.mul_le_mul hJ (Nat.add_le_add hd hB)\n  have he : 2^(2*b+2) = 4*(2^b)^2 := by\n    rw [show 2*b+2=b+b+2 by omega, pow_add, pow_add]\n    norm_num\n    ring\n  rw [he]\n  unfold localBase\n  nlinarith\n\n/-- The actual Horner suffix fits a polynomial-width primitive-rational buffer. -/\ntheorem shiftFrom_fits (a : Array ℚ) (t : ℤ) (J d B T b start len : ℕ)\n    (hd : 0<d) (hdB : d ≤ 2^b) (hJ : J ≤ 2^b) (hB : B ≤ 2^b) (hT : T ≤ 2^b)\n    (ht : t.natAbs ≤ T)\n    (ha : ∀ i, start ≤ i → i < start+len → Representation (coefficient a i) d B)\n    (i : ℕ) (hi : i < J) :\n    Fits (coefficient (shiftFrom a (t : ℚ) J start len).coefficients i)\n      (2*b+(2*b+2)*len+1) := by\n  have h := representation_fits hd (shiftFrom_bound a t J d B T start len ht ha i hi)\n    hdB (hornerBound_le J B T b len hJ hB hT)\n  convert h using 1\n  congr 1\n  ring\n\n/-- Every actual corrected-input prefix fits, without assuming a Taylor-output height. -/\ntheorem acquireCorrected_fits (source : ℕ → Array ℚ) (t : ℤ)\n    (R J d B T b n : ℕ) (base correction : ℕ → Bool)\n    (hd : 0<d) (hdB : d ≤ 2^b) (hJ : J ≤ 2^b) (hB : B ≤ 2^b)\n    (hT : T ≤ 2^b) (hn : n ≤ 2^b) (ht : t.natAbs ≤ T)\n    (hs : ∀ v < n, ∀ i ≤ R, Representation (coefficient (source v) i) d B)\n    (i : ℕ) (hi : i < J) :\n    Fits (coefficient (acquireCorrected source (t : ℚ) R J base correction n).coefficients i)\n      (3*b+(2*b+2)*(R+1)+1) := by\n  have hnum : n*hornerBound J B T (R+1) ≤ 2^(2*b+(2*b+2)*(R+1)) := by\n    have hm := Nat.mul_le_mul hn (hornerBound_le J B T b (R+1) hJ hB hT)\n    convert hm using 1\n    ring\n  convert representation_fits hd\n    (acquireCorrected_bound source t R J d B T n base correction ht hs i hi) hdB hnum using 1\n  congr 1\n  ring\n\n/-- Every recursive branch output has a bit budget linear in the branch arity. -/\ntheorem localEvaluate_fits (J w d B b : ℕ) (hd : 0<d)\n    (hJ : J ≤ 2^b) (hdB : d ≤ 2^b) (hB : B ≤ 2^b)\n    (T : (Fin w → Bool) → EntryReport) (inputs : Fin w → Array ℚ)\n    (hT : ∀ eta, (T eta).value.natAbs ≤ 1) (hinputs : ∀ v, ArrayBound (inputs v) J d B)\n    (i : ℕ) (hi : i < J) :\n    Fits (coefficient (localEvaluate J w T inputs).coefficients i) ((3*b+2)*w+1) := by\n  have hden : d^w ≤ 2^(b*w) := by\n    simpa only [← pow_mul] using Nat.pow_le_pow_left hdB w\n  have hnum : localBase J d B^w ≤ 2^((2*b+2)*w) := by\n    simpa only [← pow_mul] using Nat.pow_le_pow_left (localBase_le J d B b hJ hdB hB) w\n  convert representation_fits (pow_pos hd _) (localEvaluate_representation J w d B hd T inputs hT hinputs i hi)\n    hden hnum using 1\n  congr 1\n  ring\n\n/-- Every partial Horner multiplication fits the next-suffix width budget. -/\ntheorem shiftFrom_prefix_fits (a : Array ℚ) (t : ℤ) (J d B T b start len k p : ℕ)\n    (hd : 0<d) (hdB : d ≤ 2^b) (hJ : J ≤ 2^b) (hB : B ≤ 2^b) (hT : T ≤ 2^b)\n    (ht : t.natAbs ≤ T)\n    (ha : ∀ i, start ≤ i → i < start+len → Representation (coefficient a i) d B)\n    (hk : k < J) (hp : p ≤ k) :\n    Fits (dotPrefix (shiftFrom a (t : ℚ) J start len).coefficients\n      #[(t : ℚ),1] (k-1) p).value (2*b+(2*b+2)*(len+1)+1) := by\n  have hrep := shiftFrom_product_prefix a t J d B T start len k p ht ha hk hp\n  have hn : p*hornerBound J B T len*(T+1) ≤ hornerBound J B T (len+1) := by\n    unfold hornerBound\n    rw [pow_succ]\n    have hmul := Nat.mul_le_mul_right (B*(1+J*(T+1))^len*(T+1)) (show p ≤ J by omega)\n    have he : B*((1+J*(T+1))^len*(1+J*(T+1))) =\n        J*(B*(1+J*(T+1))^len*(T+1))+B*(1+J*(T+1))^len := by ring\n    rw [he]\n    calc\n      _ = p*(B*(1+J*(T+1))^len*(T+1)) := by ring\n      _ ≤ J*(B*(1+J*(T+1))^len*(T+1)) := hmul\n      _ ≤ _ := Nat.le_add_right _ _\n  have hr := representation_mono hrep hn\n  have hf := representation_fits hd hr hdB (hornerBound_le J B T b (len+1) hJ hB hT)\n  convert hf using 1\n  congr 1\n  ring\n\n/-- Product-denominator and numerator budgets for every local nonleaf buffer. -/\ntheorem local_level_bounds (J d B b w : ℕ)\n    (hJ : J ≤ 2^b) (hd : d ≤ 2^b) (hB : B ≤ 2^b) :\n    d*d^w ≤ 2^(b*(w+1)) ∧\n      J*(d+B)*localBase J d B^w ≤ 2^((2*b+2)*(w+1)) := by\n  constructor\n  · have hm := Nat.pow_le_pow_left hd (w+1)\n    calc\n      d*d^w = d^(w+1) := (pow_succ' _ _).symm\n      _ ≤ (2^b)^(w+1) := hm\n      _ = _ := by rw [← pow_mul]\n  · have hb := localBase_le J d B b hJ hd hB\n    have hp := Nat.pow_le_pow_left hb (w+1)\n    have hfac : J*(d+B) ≤ localBase J d B := by\n      unfold localBase\n      nlinarith [Nat.zero_le (J*(d+B))]\n    have hm := Nat.mul_le_mul_right (localBase J d B^w) hfac\n    calc\n      _ ≤ localBase J d B * localBase J d B^w := hm\n      _ = localBase J d B^(w+1) := (pow_succ' _ _).symm\n      _ ≤ _ := by simpa only [← pow_mul] using hp\n\n/-- Every false and true convolution accumulator in the actual local trace fits.\nThe width is linear in branch arity and in the port coefficient bit budget. -/\ntheorem localStep_prefix_fits (J w d B b : ℕ) (hd : 0<d)\n    (hJ : J ≤ 2^b) (hdB : d ≤ 2^b) (hB : B ≤ 2^b)\n    (T : (Fin (w+1) → Bool) → EntryReport) (inputs : Fin (w+1) → Array ℚ)\n    (hsafe : LocalStepSafe J w d B T inputs) (k p : ℕ) (hk : k < J) (hp : p ≤ k) :\n    Fits (dotPrefix (SemiprimeArrayOps.addJet (SemiprimeArrayOps.oneJet J).coefficients\n      (SemiprimeArrayOps.scaleJet (inputs 0) (-1) J).coefficients J).coefficients\n      (localEvaluate J w (fun eta => T (Fin.cons false eta)) (fun v => inputs v.succ)).coefficients\n      (k-1) p).value ((3*b+2)*(w+1)+1) ∧\n    Fits (dotPrefix (inputs 0)\n      (localEvaluate J w (fun eta => T (Fin.cons true eta)) (fun v => inputs v.succ)).coefficients\n      (k-1) p).value ((3*b+2)*(w+1)+1) := by\n  have hlev := local_level_bounds J d B b w hJ hdB hB\n  have hleft := representation_mono (hsafe.leftPrefix k hk p hp)\n    (Nat.mul_le_mul_right (localBase J d B^w) (Nat.mul_le_mul_right (d+B) (show p ≤ J by omega)))\n  have hright := representation_mono (hsafe.rightPrefix k hk p hp)\n    (show p*B*localBase J d B^w ≤ J*(d+B)*localBase J d B^w by gcongr <;> omega)\n  have hl := representation_fits (Nat.mul_pos hd (pow_pos hd _)) hleft hlev.1 hlev.2\n  have hr := representation_fits (Nat.mul_pos hd (pow_pos hd _)) hright hlev.1 hlev.2\n  constructor\n  · convert hl using 1\n    congr 1\n    ring\n  · convert hr using 1\n    congr 1\n    ring\n\n/-- Both completed multiplication buffers at every local node fit the same width. -/\ntheorem localStep_buffers_fits (J w d B b : ℕ) (hd : 0<d)\n    (hJ : J ≤ 2^b) (hdB : d ≤ 2^b) (hB : B ≤ 2^b)\n    (T : (Fin (w+1) → Bool) → EntryReport) (inputs : Fin (w+1) → Array ℚ)\n    (hsafe : LocalStepSafe J w d B T inputs) (k : ℕ) (hk : k < J) :\n    Fits (coefficient (multiply\n      (SemiprimeArrayOps.addJet (SemiprimeArrayOps.oneJet J).coefficients\n        (SemiprimeArrayOps.scaleJet (inputs 0) (-1) J).coefficients J).coefficients\n      (localEvaluate J w (fun eta => T (Fin.cons false eta)) (fun v => inputs v.succ)).coefficients J).coefficients k)\n      ((3*b+2)*(w+1)+1) ∧\n    Fits (coefficient (multiply (inputs 0)\n      (localEvaluate J w (fun eta => T (Fin.cons true eta)) (fun v => inputs v.succ)).coefficients J).coefficients k)\n      ((3*b+2)*(w+1)+1) := by\n  have hlev := local_level_bounds J d B b w hJ hdB hB\n  have hleft := hsafe.left k hk\n  have hright := representation_mono (hsafe.right k hk)\n    (show J*B*localBase J d B^w ≤ J*(d+B)*localBase J d B^w by gcongr; omega)\n  have hl := representation_fits (Nat.mul_pos hd (pow_pos hd _)) hleft hlev.1 hlev.2\n  have hr := representation_fits (Nat.mul_pos hd (pow_pos hd _)) hright hlev.1 hlev.2\n  constructor\n  · convert hl using 1\n    congr 1\n    ring\n  · convert hr using 1\n    congr 1\n    ring\n\n/-- Scalar products before accumulation fit the same local-node width. -/\ntheorem localStep_terms_fits (J w d B b : ℕ) (hd : 0<d)\n    (hJ : J ≤ 2^b) (hdB : d ≤ 2^b) (hB : B ≤ 2^b)\n    (T : (Fin (w+1) → Bool) → EntryReport) (inputs : Fin (w+1) → Array ℚ)\n    (hsafe : LocalStepSafe J w d B T inputs) (k i : ℕ) (hk : k < J) (hi : i ≤ k) :\n    Fits (coefficient (SemiprimeArrayOps.addJet (SemiprimeArrayOps.oneJet J).coefficients\n      (SemiprimeArrayOps.scaleJet (inputs 0) (-1) J).coefficients J).coefficients i *\n      coefficient (localEvaluate J w (fun eta => T (Fin.cons false eta))\n        (fun v => inputs v.succ)).coefficients (k-i)) ((3*b+2)*(w+1)+1) ∧\n    Fits (coefficient (inputs 0) i * coefficient (localEvaluate J w\n      (fun eta => T (Fin.cons true eta)) (fun v => inputs v.succ)).coefficients (k-i))\n      ((3*b+2)*(w+1)+1) := by\n  have hlev := local_level_bounds J d B b w hJ hdB hB\n  have hleft := representation_mono (hsafe.leftTerm k hk i hi)\n    (show (d+B)*localBase J d B^w ≤ J*(d+B)*localBase J d B^w by\n      have h := Nat.mul_le_mul_right ((d+B)*localBase J d B^w) (show 1 ≤ J by omega)\n      simpa only [one_mul, Nat.mul_assoc] using h)\n  have hright := representation_mono (hsafe.rightTerm k hk i hi)\n    (show B*localBase J d B^w ≤ J*(d+B)*localBase J d B^w by\n      calc\n        _ ≤ (d+B)*localBase J d B^w := Nat.mul_le_mul_right _ (by omega)\n        _ ≤ _ := by\n          have h := Nat.mul_le_mul_right ((d+B)*localBase J d B^w) (show 1 ≤ J by omega)\n          simpa only [one_mul, Nat.mul_assoc] using h)\n  have hl := representation_fits (Nat.mul_pos hd (pow_pos hd _)) hleft hlev.1 hlev.2\n  have hr := representation_fits (Nat.mul_pos hd (pow_pos hd _)) hright hlev.1 hlev.2\n  constructor\n  · convert hl using 1\n    congr 1\n    ring\n  · convert hr using 1\n    congr 1\n    ring\n\n/-- One explicit polynomial bit budget for the executed coefficient-to-local-value call. -/\ntheorem nativeLocal_fits {n : ℕ} (w J R d B T b : ℕ) (hd : 0<d)\n    (hdB : d ≤ 2^b) (hJ : J ≤ 2^b) (hB : B ≤ 2^b) (hT : T ≤ 2^b) (hn : n ≤ 2^b)\n    (t : ℤ) (ht : t.natAbs ≤ T) (source : Fin w → Fin n → Array ℚ)\n    (base correction : Fin n → Bool) (entries : (Fin w → Bool) → EntryReport)\n    (hentries : ∀ eta, (entries eta).value.natAbs ≤ 1)\n    (hs : ∀ v u i, i ≤ R → Representation (coefficient (source v u) i) d B)\n    (i : ℕ) (hi : i < J) :\n    Fits (coefficient (nativeLocal w J R (t : ℚ) source base correction entries).coefficients i)\n      ((3*(2*b+(2*b+2)*(R+1))+2)*w+1) := by\n  let p := 2*b+(2*b+2)*(R+1)\n  have hbp : b ≤ p := by dsimp [p]; omega\n  have hpow : 2^b ≤ 2^p := Nat.pow_le_pow_right (by decide) hbp\n  have hnum : n*hornerBound J B T (R+1) ≤ 2^p := by\n    have hm := Nat.mul_le_mul hn (hornerBound_le J B T b (R+1) hJ hB hT)\n    convert hm using 1\n    dsimp [p]\n    ring\n  let inputs := Array.ofFn (fun v : Fin w => acquireCorrectedFin (source v)\n    (t : ℚ) R J base correction)\n  let ports := fun v : Fin w => (inputs[v.val]'(by simp [inputs])).coefficients\n  have hports (v : Fin w) : ArrayBound (ports v) J d (n*hornerBound J B T (R+1)) := by\n    simpa only [ports, inputs, Array.getElem_ofFn] using\n      acquireCorrectedFin_bound (source v) t R J d B T base correction ht (hs v)\n  exact localEvaluate_fits J w d _ p hd (hJ.trans hpow) (hdB.trans hpow) hnum\n    entries ports hentries hports i hi\n\nend RiemannGaussian.SemiprimeLocalExecutionBitBounds\n","RiemannGaussian.SemiprimeMaterializedScheduledExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeMaterializedPublicExecution\nimport RiemannGaussian.SemiprimeScheduledFactorExecution\n\n/-!\n# Natural-input materialized factoring execution\n\nThe only runtime input is N. The original computed schedule and literal decidable\nguard select the new materialized public count/search; the same complete finite\ntrial fallback handles the complementary branch. No source array, design,\ncoefficient, local table, count answer or externally chosen parameter is supplied.\nThis is a semantic execution join, not a new whole primitive-bit clock theorem.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1600000\nnamespace RiemannGaussian.SemiprimeMaterializedScheduledExecution\nopen scoped BigOperators\nopen Filter SemiprimePublicAcquiredExecution\nopen SemiprimeScheduledFactorExecution\n\n/-- Entire deterministic N-only algorithm, with the new materialized counter on\nits automatically chosen fast branch and the old finite complete fallback. -/\ndef run (N : ℕ) : Option ℕ :=\n  if hN : 0<N then\n    if hr : 0<groups N then\n      letI : NeZero (groups N) := ⟨Nat.ne_of_gt hr⟩\n      if fastGuard N then\n        SemiprimeMaterializedPublicExecution.factor N hN (groups N) (points N)\n          (epsilon N) (degree N) (precision N)\n      else trialFactor N\n    else trialFactor N\n  else none\n\n/-- Exact output equivalence on EVERY natural input, not only promised semiprimes.\nThe two algorithms can have different operation traces and work reports. -/\ntheorem run_eq_old (N : ℕ) : run N=SemiprimeScheduledFactorExecution.run N := by\n  by_cases hN : 0<N\n  · by_cases hr : 0<groups N\n    · let _ : NeZero (groups N) := ⟨Nat.ne_of_gt hr⟩\n      by_cases hg : fastGuard N\n      · have hQ : 1≤points N := Nat.le_trans (by decide : 1≤2) hg.2.2.2.1\n        have hAQ := guard_interval N hg\n        have hp := precision_valid N hN (guard_points_pos N hg)\n        have he := SemiprimeMaterializedPublicExecution.factor_eq_old N hN (groups N) (points N)\n          (epsilon N) (degree N) (precision N) hQ hAQ hp.1 hp.2\n        simpa only [run,SemiprimeScheduledFactorExecution.run,dite_eq_left hN,\n          dite_eq_left hr,ite_eq_left hg] using he\n      · simp only [run,SemiprimeScheduledFactorExecution.run,dite_eq_left hN,\n          dite_eq_left hr,ite_eq_right hg]\n    · simp only [run,SemiprimeScheduledFactorExecution.run,dite_eq_left hN,dite_eq_right hr]\n  · simp only [run,SemiprimeScheduledFactorExecution.run,dite_eq_right hN]\n\n/-- Every actual returned integer is a proper divisor of the original input. -/\ntheorem run_sound (N p : ℕ) (h : run N=some p) : 2≤p ∧ p<N ∧ p∣N :=\n  SemiprimeScheduledFactorExecution.run_sound N p ((run_eq_old N).symm.trans h)\n\n/-- Complete failure characterization for all naturals, including zero, one,\nprimes, and perfect squares. -/\ntheorem run_none_iff (N : ℕ) :\n    run N=none ↔ ¬Nonempty (SemiprimePublicFactorCount.OrdinaryFactors N) := by\n  rw [run_eq_old]\n  exact SemiprimeScheduledFactorExecution.run_none_iff N\n\n/-- The literal guard eventually passes, so the runtime actually uses the new\nmaterialized source counter rather than the finite fallback. -/\ntheorem eventually_run_materialized : ∀ᶠ N : ℕ in atTop,\n    ∃ hN : 0<N, ∃ hg : fastGuard N,\n      letI : NeZero (groups N) := ⟨Nat.ne_of_gt (guard_groups_pos N hg)⟩\n      run N=SemiprimeMaterializedPublicExecution.factor N hN (groups N) (points N)\n        (epsilon N) (degree N) (precision N) := by\n  filter_upwards [eventually_fastGuard,eventually_gt_atTop 0] with N hg hN\n  exact ⟨hN,hg,by simp only [run,dite_eq_left hN,dite_eq_left (guard_groups_pos N hg),ite_eq_left hg]⟩\n\nend RiemannGaussian.SemiprimeMaterializedScheduledExecution\n","RiemannGaussian.SemiprimeMaterializedSelectionHeight":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeRowSelectionTracked\nimport Mathlib.LinearAlgebra.Matrix.Nonsingular\nimport Mathlib.LinearAlgebra.Matrix.NonsingularInverse\nimport Mathlib.LinearAlgebra.Matrix.Determinant.Misc\n\n/-! # Pivot-minor certificates for the actual executed selector\n\nAll states below are actual prefixes of `run`. No inverse, selected basis or\nminor answer is supplied as a hypothesis.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1600000\nnoncomputable section\nnamespace RiemannGaussian.SemiprimeMaterializedSelectionHeight\nopen scoped BigOperators Matrix\nopen SemiprimeRowSelectionExecution\n\n/-- Literal retained original-row matrix of a computed prefix. -/\ndef selectedMatrix {m n : ℕ} (C : Fin m → Fin n → ℤ) (ids : List (Fin m)) :\n    Matrix (Fin (run C ids).selected.length) (Fin n) ℤ :=\n  fun i v => C ((run C ids).selected.get i) v\n\n/-- Reindex the actual selected rows by the actual active pivot slots. This is\nproof-only bookkeeping; it does not choose a new basis or run an inverse. -/\ndef pivotEquiv {m n : ℕ} (C : Fin m → Fin n → ℤ) (ids : List (Fin m)) :\n    Fin (run C ids).selected.length ≃ Active (run C ids) :=\n  Fintype.equivOfCardEq (by\n    rw [Fintype.card_fin,active_card]\n    exact run_selected_length C ids)\n\n/-- The integer square pivot minor, from selected ORIGINAL rows and columns. -/\ndef pivotMatrix {m n : ℕ} (C : Fin m → Fin n → ℤ) (ids : List (Fin m)) :\n    Matrix (Fin (run C ids).selected.length) (Fin (run C ids).selected.length) ℤ :=\n  fun i j => selectedMatrix C ids i (pivotEquiv C ids j).val\n\n/-- The same acquired integer minor viewed in the rational arithmetic field. -/\ndef rationalPivot {m n : ℕ} (C : Fin m → Fin n → ℤ) (ids : List (Fin m)) :\n    Matrix (Fin (run C ids).selected.length) (Fin (run C ids).selected.length) ℚ :=\n  fun i j => (pivotMatrix C ids i j : ℚ)\n\n/-- Zero active coordinates determine zero in the actual reduced workspace. -/\ntheorem zero_of_active_zero {m n : ℕ} (s : State m n) (hg : Good s)\n    (row : Row n) (hm : row∈workSpan s)\n    (hz : ∀ c : Active s,row c.val=0) : row=0 := by\n  have hr := (residual_zero_iff s hg row).mpr hm\n  funext v\n  have hv := congrFun hr v\n  rw [SemiprimeRowSelectionExecution.residual,cacheRow_apply] at hv\n  have hs : (∑ c : Fin n,if s.active c then row c*s.rows c v else 0)=0 := by\n    apply Finset.sum_eq_zero\n    intro c _\n    by_cases hc : s.active c=true\n    · simp only [hc,ite_true,hz ⟨c,hc⟩,zero_mul]\n    · simp [hc]\n  simpa [hs] using hv\n\n/-- Retained original rows of EVERY computed prefix are independent, including\nempty/all-zero prefixes. -/\ntheorem prefix_selected_independent {m n : ℕ} (C : Fin m → Fin n → ℤ)\n    (ids : List (Fin m)) :\n    LinearIndependent ℚ (fun i : Fin (run C ids).selected.length =>\n      originalRow C ((run C ids).selected.get i)) := by\n  apply linearIndependent_iff_card_eq_finrank_span.mpr\n  change Fintype.card (Fin (run C ids).selected.length)=Module.finrank ℚ\n    (Submodule.span ℚ (Set.range (fun i => originalRow C ((run C ids).selected.get i))))\n  rw [← inputSpan_get,← run_selected_span,Fintype.card_fin]\n  exact (run_selected_length C ids).trans\n    (workSpan_finrank (run C ids) (run_good C ids)).symm\n\n/-- Restricting the retained originals to the actual pivot columns preserves\nindependence; injectivity is proved on the computed workspace. -/\ntheorem pivot_rows_independent {m n : ℕ} (C : Fin m → Fin n → ℤ)\n    (ids : List (Fin m)) :\n    LinearIndependent ℚ (fun i j => (pivotMatrix C ids i j : ℚ)) := by\n  apply linearIndependent_iff'.mpr\n  intro t coeff he k hk\n  let row : Row n := ∑ i∈t,coeff i • originalRow C ((run C ids).selected.get i)\n  have hm : row∈workSpan (run C ids) := by\n    apply Submodule.sum_mem\n    intro i hi\n    apply Submodule.smul_mem\n    rw [run_selected_span]\n    exact input_mem_span C _ _ (List.get_mem _ _)\n  have hz : ∀ c : Active (run C ids),row c.val=0 := by\n    intro c\n    have hv := congrFun he ((pivotEquiv C ids).symm c)\n    simpa [row,pivotMatrix,selectedMatrix,originalRow] using hv\n  have hr := zero_of_active_zero _ (run_good C ids) row hm hz\n  exact (linearIndependent_iff'.mp (prefix_selected_independent C ids)) t coeff hr k hk\n\n/-- The computed pivot minor is genuinely nonsingular. -/\ntheorem pivot_det_ne_zero {m n : ℕ} (C : Fin m → Fin n → ℤ)\n    (ids : List (Fin m)) :\n    (rationalPivot C ids).det≠0 := by\n  exact Matrix.nonsingular_iff_det_ne_zero.mp\n    (Matrix.Nonsingular.of_linearIndependent_row (pivot_rows_independent C ids))\n\n/-- Active computed rows, now reindexed by retained-original positions. -/\ndef workingMatrix {m n : ℕ} (C : Fin m → Fin n → ℤ) (ids : List (Fin m)) :\n    Matrix (Fin (run C ids).selected.length) (Fin n) ℚ :=\n  fun i v => (run C ids).rows (pivotEquiv C ids i).val v\n\n/-- The actual working matrix has identity entries at its pivot columns. -/\ntheorem working_pivot {m n : ℕ} (C : Fin m → Fin n → ℤ) (ids : List (Fin m))\n    (i j : Fin (run C ids).selected.length) :\n    workingMatrix C ids i (pivotEquiv C ids j).val=if i=j then 1 else 0 := by\n  rw [workingMatrix,(run_good C ids).pivot _ _ (pivotEquiv C ids i).property\n    (pivotEquiv C ids j).property]\n  have he : (pivotEquiv C ids i).val=(pivotEquiv C ids j).val ↔ i=j := by\n    constructor\n    · intro h; exact (pivotEquiv C ids).injective (Subtype.ext h)\n    · intro h; subst j; rfl\n  simp only [he]\n\n/-- The actual selected original matrix equals pivot minor times ACTUAL\nworking matrix. This is a consequence, not a supplied linear-system answer. -/\ntheorem pivot_mul_working {m n : ℕ} (C : Fin m → Fin n → ℤ)\n    (ids : List (Fin m)) :\n    rationalPivot C ids * workingMatrix C ids=\n      fun i v => (selectedMatrix C ids i v : ℚ) := by\n  ext i v\n  let row : Row n := ∑ j : Fin (run C ids).selected.length,\n    (pivotMatrix C ids i j : ℚ) • workingMatrix C ids j\n  have hm : row∈workSpan (run C ids) := by\n    apply Submodule.sum_mem\n    intro j _\n    exact Submodule.smul_mem _ _ (row_mem_workSpan _ _)\n  have hs : (fun v => (selectedMatrix C ids i v : ℚ))∈workSpan (run C ids) := by\n    rw [run_selected_span]\n    exact input_mem_span C _ _ (List.get_mem _ _)\n  have hz : row-(fun v => (selectedMatrix C ids i v : ℚ))=0 := by\n    apply zero_of_active_zero _ (run_good C ids) _ (Submodule.sub_mem _ hm hs)\n    intro c\n    obtain ⟨j,rfl⟩ := (pivotEquiv C ids).surjective c\n    simp only [Pi.sub_apply,row,Finset.sum_apply,Pi.smul_apply,smul_eq_mul,\n      working_pivot,mul_ite,mul_one,mul_zero,Finset.sum_ite_eq',Finset.mem_univ,ite_true,\n      pivotMatrix,sub_self]\n  have hrow := sub_eq_zero.mp hz\n  simpa only [row,Matrix.mul_apply,rationalPivot,Finset.sum_apply,Pi.smul_apply,smul_eq_mul] using\n    congrFun hrow v\n\n/-- Every actual working entry is a Cramer ratio of original integer minors. -/\ntheorem working_cramer {m n : ℕ} (C : Fin m → Fin n → ℤ)\n    (ids : List (Fin m)) (i : Fin (run C ids).selected.length) (v : Fin n) :\n    workingMatrix C ids i v=\n      (rationalPivot C ids).cramer\n        (fun j => (selectedMatrix C ids j v : ℚ)) i /\n        (rationalPivot C ids).det := by\n  let A : Matrix (Fin (run C ids).selected.length) (Fin (run C ids).selected.length) ℚ :=\n    fun i j => (pivotMatrix C ids i j : ℚ)\n  let x := fun i => workingMatrix C ids i v\n  let b := fun j => (selectedMatrix C ids j v : ℚ)\n  have hx : A *ᵥ x=b := by\n    funext j\n    exact congrFun (congrFun (pivot_mul_working C ids) j) v\n  have hc : A.cramer b=A.det • x := by\n    rw [← hx,Matrix.cramer_eq_adjugate_mulVec,Matrix.mulVec_mulVec,Matrix.adjugate_mul,\n      Matrix.smul_mulVec,Matrix.one_mulVec]\n  have hv := congrFun hc i\n  have hd : A.det≠0 := pivot_det_ne_zero C ids\n  change x i=A.cramer b i/A.det\n  rw [hv,Pi.smul_apply,smul_eq_mul]\n  exact (mul_div_cancel_left₀ (x i) hd).symm\n\n/-- Common integer denominator of all stored active entries in this prefix. -/\ndef pivotDenominator {m n : ℕ} (C : Fin m → Fin n → ℤ) (ids : List (Fin m)) : ℤ :=\n  (pivotMatrix C ids).det\n\n/-- Integer Cramer numerator obtained by replacing a pivot column with one\nactual original coefficient column. -/\ndef pivotNumerator {m n : ℕ} (C : Fin m → Fin n → ℤ) (ids : List (Fin m))\n    (i : Fin (run C ids).selected.length) (v : Fin n) : ℤ :=\n  ((pivotMatrix C ids).updateCol i (fun j => selectedMatrix C ids j v)).det\n\n/-- Integer and rational views of the acquired pivot determinant agree. -/\ntheorem cast_pivotDenominator {m n : ℕ} (C : Fin m → Fin n → ℤ) (ids : List (Fin m)) :\n    (pivotDenominator C ids : ℚ)=(rationalPivot C ids).det := by\n  exact (Int.castRingHom ℚ).map_det (pivotMatrix C ids)\n\n/-- The actual integer pivot determinant is nonzero. -/\ntheorem pivotDenominator_ne_zero {m n : ℕ} (C : Fin m → Fin n → ℤ) (ids : List (Fin m)) :\n    pivotDenominator C ids≠0 := by\n  intro h\n  have he := cast_pivotDenominator C ids\n  rw [h,Int.cast_zero] at he\n  exact pivot_det_ne_zero C ids he.symm\n\n/-- Cramer numerators too are casts of ORIGINAL integer minors. -/\ntheorem cast_pivotNumerator {m n : ℕ} (C : Fin m → Fin n → ℤ) (ids : List (Fin m))\n    (i : Fin (run C ids).selected.length) (v : Fin n) :\n    (pivotNumerator C ids i v : ℚ)=(rationalPivot C ids).cramer\n      (fun j => (selectedMatrix C ids j v : ℚ)) i := by\n  rw [Matrix.cramer_apply]\n  have he : (Int.castRingHom ℚ).mapMatrix\n      ((pivotMatrix C ids).updateCol i (fun j => selectedMatrix C ids j v))=\n      (rationalPivot C ids).updateCol i (fun j => (selectedMatrix C ids j v : ℚ)) := by\n    ext j k\n    simp [RingHom.mapMatrix,Matrix.map_apply,Matrix.updateCol_apply,rationalPivot]\n  change (Int.castRingHom ℚ) ((pivotMatrix C ids).updateCol i (fun j => selectedMatrix C ids j v)).det=_\n  rw [RingHom.map_det,he]\n\n/-- Every stored active entry has a proved integer-minor representation with\none denominator shared by the entire actual prefix state. -/\ntheorem working_integer_ratio {m n : ℕ} (C : Fin m → Fin n → ℤ)\n    (ids : List (Fin m)) (i : Fin (run C ids).selected.length) (v : Fin n) :\n    workingMatrix C ids i v=(pivotNumerator C ids i v : ℚ)/(pivotDenominator C ids : ℚ) := by\n  rw [cast_pivotNumerator,cast_pivotDenominator]\n  exact working_cramer C ids i v\n\n/-- Elementary Leibniz envelope for minors; its logarithm is polynomial in\nmatrix order and input bit height. -/\ndef minorBound (order height : ℕ) : ℕ := order.factorial*height^order\n\n/-- Determinant magnitudes of bounded integer matrices obey the explicit\nfactorial-power envelope, including the empty matrix. -/\ntheorem integer_det_bound {r : ℕ} (A : Matrix (Fin r) (Fin r) ℤ) (height : ℕ)\n    (hA : ∀ i j,|A i j|≤(height : ℤ)) : A.det.natAbs≤ minorBound r height := by\n  have hd := Matrix.det_le (abv := AbsoluteValue.abs) hA\n  apply Int.ofNat_le.mp\n  rw [Int.natCast_natAbs]\n  simpa only [AbsoluteValue.abs_apply,Fintype.card_fin,nsmul_eq_mul,minorBound,\n    Nat.cast_mul,Nat.cast_pow] using hd\n\n/-- The acquired common denominator satisfies the original-input minor bound. -/\ntheorem pivotDenominator_bound {m n : ℕ} (C : Fin m → Fin n → ℤ)\n    (ids : List (Fin m)) (height : ℕ) (hC : ∀ j v,|C j v|≤(height : ℤ)) :\n    (pivotDenominator C ids).natAbs≤ minorBound (run C ids).selected.length height := by\n  apply integer_det_bound\n  intro i j\n  exact hC _ _\n\n/-- Replacing a column does not enlarge the ORIGINAL coefficient bound. -/\ntheorem pivotNumerator_bound {m n : ℕ} (C : Fin m → Fin n → ℤ)\n    (ids : List (Fin m)) (height : ℕ) (hC : ∀ j v,|C j v|≤(height : ℤ))\n    (i : Fin (run C ids).selected.length) (v : Fin n) :\n    (pivotNumerator C ids i v).natAbs≤ minorBound (run C ids).selected.length height := by\n  apply integer_det_bound\n  intro j k\n  rw [Matrix.updateCol_apply]\n  split_ifs <;> exact hC _ _\n\n/-- Reducing a proved integer fraction cannot increase numerator magnitude or\ndenominator; no arbitrary circuit-height hypothesis is used. -/\ntheorem reduced_fraction_bounds (q : ℚ) (a b : ℤ) (hb : b≠0)\n    (he : q=(a : ℚ)/(b : ℚ)) : q.num.natAbs≤a.natAbs ∧ q.den≤b.natAbs := by\n  obtain ⟨c,ha,hb'⟩ := Rat.num_den_mk hb (by simpa only [Rat.divInt_eq_div] using he)\n  have hc : c≠0 := by intro h; simp [h] at hb'; exact hb hb'\n  have hcpos : 1≤c.natAbs := Nat.one_le_iff_ne_zero.mpr (Int.natAbs_ne_zero.mpr hc)\n  have han : a.natAbs=c.natAbs*q.num.natAbs := by rw [ha,Int.natAbs_mul]\n  have hbn : b.natAbs=c.natAbs*q.den := by rw [hb',Int.natAbs_mul,Int.natAbs_natCast]\n  constructor\n  · have h := Nat.mul_le_mul_right q.num.natAbs hcpos\n    simpa only [one_mul,← han] using h\n  · have h := Nat.mul_le_mul_right q.den hcpos\n    simpa only [one_mul,← hbn] using h\n\n/-- Canonical rational numerator AND denominator of every actual stored active\nentry have polynomial-bit factorial-power bounds from original integers. -/\ntheorem working_canonical_bounds {m n : ℕ} (C : Fin m → Fin n → ℤ)\n    (ids : List (Fin m)) (height : ℕ) (hC : ∀ j v,|C j v|≤(height : ℤ))\n    (i : Fin (run C ids).selected.length) (v : Fin n) :\n    (workingMatrix C ids i v).num.natAbs≤ minorBound (run C ids).selected.length height ∧\n    (workingMatrix C ids i v).den≤ minorBound (run C ids).selected.length height := by\n  have hr := reduced_fraction_bounds _ _ _ (pivotDenominator_ne_zero C ids) (working_integer_ratio C ids i v)\n  exact ⟨hr.1.trans (pivotNumerator_bound C ids height hC i v),\n    hr.2.trans (pivotDenominator_bound C ids height hC)⟩\n\n/-- A polynomial binary exponent bounds the entire minor envelope whenever the\noriginal integer coefficients fit b bits. This is not exponential in a circuit\nsize: the exponent is the quadratic expression r*(r+b). -/\ntheorem minorBound_le_two_pow (r height bits : ℕ) (hh : height≤2^bits) :\n    minorBound r height≤2^(r*(r+bits)) := by\n  have hf := Nat.factorial_le_pow r\n  have hr : r≤2^r := (Nat.lt_two_pow_self (n := r)).le\n  have hp := Nat.pow_le_pow_left hr r\n  have hw := Nat.pow_le_pow_left hh r\n  calc\n    minorBound r height≤(2^r)^r*(2^bits)^r := Nat.mul_le_mul (hf.trans hp) hw\n    _=2^(r*(r+bits)) := by rw [← Nat.pow_mul,← Nat.pow_mul,← Nat.pow_add]; congr 1; ring\n\n/-- Explicit canonical numerator/denominator binary bounds for the ACTUAL\nstored prefix, with original-coefficient bit height as the only data bound. -/\ntheorem working_binary_bounds {m n : ℕ} (C : Fin m → Fin n → ℤ)\n    (ids : List (Fin m)) (bits : ℕ) (hC : ∀ j v,|C j v|≤(2^bits : ℕ))\n    (i : Fin (run C ids).selected.length) (v : Fin n) :\n    (workingMatrix C ids i v).num.natAbs≤2^((run C ids).selected.length*((run C ids).selected.length+bits)) ∧\n    (workingMatrix C ids i v).den≤2^((run C ids).selected.length*((run C ids).selected.length+bits)) := by\n  have h := working_canonical_bounds C ids (2^bits) hC i v\n  have hb := minorBound_le_two_pow (run C ids).selected.length (2^bits) bits le_rfl\n  exact ⟨h.1.trans hb,h.2.trans hb⟩\n\n/-- The actual retained rank never exceeds the number of original columns. -/\ntheorem prefix_rank_le_columns {m n : ℕ} (C : Fin m → Fin n → ℤ) (ids : List (Fin m)) :\n    (run C ids).selected.length≤n := by\n  rw [run_selected_length]\n  exact (Finset.card_filter_le _ _).trans (by simp)\n\n/-- ALL stored row slots, not just an abstract basis, have polynomial binary\nheight after every actual prefix. Inactive slots are the literal zero row. -/\ntheorem state_binary_bounds {m n : ℕ} (C : Fin m → Fin n → ℤ)\n    (ids : List (Fin m)) (bits : ℕ) (hC : ∀ j v,|C j v|≤(2^bits : ℕ))\n    (c v : Fin n) :\n    ((run C ids).rows c v).num.natAbs≤2^(n*(n+bits)) ∧\n    ((run C ids).rows c v).den≤2^(n*(n+bits)) := by\n  by_cases hc : (run C ids).active c=true\n  · let i := (pivotEquiv C ids).symm ⟨c,hc⟩\n    have he : workingMatrix C ids i v=(run C ids).rows c v := by\n      exact congrArg (fun z : Active (run C ids) => (run C ids).rows z.val v)\n        ((pivotEquiv C ids).apply_symm_apply ⟨c,hc⟩)\n    have h := working_binary_bounds C ids bits hC i v\n    have hlen := prefix_rank_le_columns C ids\n    have hb : 2^((run C ids).selected.length*((run C ids).selected.length+bits))≤2^(n*(n+bits)) := by\n      gcongr\n    rw [he] at h\n    exact ⟨h.1.trans hb,h.2.trans hb⟩\n  · have hz := (run_good C ids).inactive c (Bool.eq_false_iff.mpr hc)\n    rw [hz]\n    simp only [Pi.zero_apply,Rat.num_zero,Int.natAbs_zero,Rat.den_zero]\n    constructor\n    · exact Nat.zero_le _\n    · exact Nat.one_le_two_pow\n\nend RiemannGaussian.SemiprimeMaterializedSelectionHeight\n","RiemannGaussian.SemiprimeMergedIndexAcquisition":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeHyperbolicWrapCoverage\n\n/-!\n# Merge the exact short index and linear wrap into one common-base interval\n\nThe linear wrap bound permits public period folding without discarding\nthe original quadratic: at most three full wrap lifts are retained. The\nmerged index uses the SAME base g^m at every cached residue. Two intervals\nbelow the routed local periods cover it, reducing the target records to\nresidue/denominator pairs. Full acquisition and bit costs remain separate.\n-/\n\nnamespace RiemannGaussian.SemiprimeMergedIndexAcquisition\n\nopen SemiprimeQuotientRows SemiprimeDenseRowCarries SemiprimeWideWrapCoverage\nopen SemiprimeHyperbolicWrapCoverage SemiprimeWrapIndexRecovery\nopen SemiprimeGroupSelection SemiprimeLocalOrderRouting SemiprimeCentreFreeCover\nopen SemiprimeIntervalJet\nopen Polynomial\n\n/-- One public base is shared by every residue and denominator. -/\ndef commonStep {G : Type*} [CommGroup G] (g : G) (m : ℕ) : G := g^(m : ℤ)\n\n/-- Fold both original tags into one signed index, retaining their exact\ninteger linear relation for subsequent reconstruction. -/\ndef combinedIndex (m j k : ℕ) (i : ℤ) : ℤ :=\n  (m : ℤ)*i+(1-(j : ℤ))*(k : ℤ)\n\n/-- The original row's carry is a known power of the common base. -/\ntheorem carryStep_common {G : Type*} [CommGroup G] (g : G) (N m j : ℕ) :\n    (progressionSeed g N m j).carryStep=(commonStep g m)^(1-(j : ℤ)) := by\n  simp only [progressionSeed,commonStep,zpow_mul]\n\n/-- The folded power still contains the complete original wrap and index. -/\ntheorem combined_power {G : Type*} [CommGroup G] (g : G) (N m j k : ℕ) (i : ℤ) :\n    (commonStep g m)^combinedIndex m j k i=\n      g^((m : ℤ)^2*i)*(progressionSeed g N m j).carryStep^k := by\n  simp only [commonStep,combinedIndex,progressionSeed,←zpow_natCast,\n    ←zpow_mul,←zpow_add]\n  congr 1\n  ring\n\n/-- Original power collisions are exactly common-base interval hits. -/\ntheorem merged_hit_iff {G : Type*} [CommGroup G] (g : G) (N m j t k : ℕ) (i : ℤ) :\n    wrappedValue t k (progressionSeed g N m j)=g^((m : ℤ)^2*i) ↔\n      (progressionSeed g N m j).step^t=(commonStep g m)^combinedIndex m j k i := by\n  rw [wrappedValue,zpow_neg,zpow_natCast,mul_inv_eq_iff_eq_mul,←combined_power]\n\n/-- Linear wrap and short-index bounds give a single quadratic signed\nrange, independent of the original residue and denominator. -/\ntheorem combinedIndex_bounds {m j k : ℕ} {i : ℤ} (hm : 1<m)\n    (hj : 1≤j) (hjm : j<m) (hk : k≤2*m+1) (hi : i.natAbs<2*m) :\n    -4*(m : ℤ)^2≤combinedIndex m j k i ∧ combinedIndex m j k i<2*(m : ℤ)^2 := by\n  have hmz : (0 : ℤ)<m := by exact_mod_cast (by omega : 0<m)\n  have hjz : (1 : ℤ)≤j := by exact_mod_cast hj\n  have hjmz : (j : ℤ)≤m := by exact_mod_cast hjm.le\n  have hkz : (k : ℤ)≤2*(m : ℤ)+1 := by exact_mod_cast hk\n  have hiz : |i|<(2*m : ℕ) := by\n    simpa only [Int.natCast_natAbs] using\n      (show (i.natAbs : ℤ)<(2*m : ℕ) by exact_mod_cast hi)\n  have hi' := abs_lt.mp hiz\n  push_cast at hi'\n  have hlo := mul_lt_mul_of_pos_left hi'.1 hmz\n  have hhi := mul_lt_mul_of_pos_left hi'.2 hmz\n  have hprod := mul_le_mul (by linarith only [hjmz] : (j : ℤ)-1≤(m : ℤ)-1)\n    hkz (by positivity : (0 : ℤ)≤k) (by linarith only [hmz] : (0 : ℤ)≤(m : ℤ)-1)\n  have hneg : (1-(j : ℤ))*(k : ℤ)≤0 :=\n    mul_nonpos_of_nonpos_of_nonneg (by linarith only [hjz]) (by positivity)\n  unfold combinedIndex\n  constructor <;> nlinarith only [hlo,hhi,hprod,hneg,hmz]\n\n/-- Each half is shorter than the existing routed long local periods. -/\ndef mergedLength (m : ℕ) : ℕ := 3*m^2\n\n/-- Adjacent lower and upper intervals cover every proved combined index. -/\ndef mergedStart (m : ℕ) (upper : Bool) : ℤ :=\n  if upper then -(m : ℤ)^2 else -4*(m : ℤ)^2\n\n/-- The whole signed range is covered by two public simple-root intervals. -/\ntheorem combinedIndex_half {m : ℕ} {z : ℤ}\n    (hz₀ : -4*(m : ℤ)^2≤z) (hz₁ : z<2*(m : ℤ)^2) :\n    ∃ (upper : Bool) (r : ℕ), r<mergedLength m ∧ z=mergedStart m upper+r := by\n  by_cases hz : z < -(m : ℤ)^2\n  · let r := (z+4*(m : ℤ)^2).toNat\n    have hr : (r : ℤ)=z+4*(m : ℤ)^2 := Int.toNat_of_nonneg (by omega)\n    have hr₁ : (r : ℤ)<(mergedLength m : ℤ) := by\n      unfold mergedLength\n      push_cast\n      nlinarith only [hr,hz]\n    exact ⟨false,r,by exact_mod_cast hr₁,by simp only [mergedStart,Bool.false_eq_true,ite_false]; omega⟩\n  · let r := (z+(m : ℤ)^2).toNat\n    have hr : (r : ℤ)=z+(m : ℤ)^2 := Int.toNat_of_nonneg (by omega)\n    have hr₁ : (r : ℤ)<(mergedLength m : ℤ) := by\n      unfold mergedLength\n      push_cast\n      nlinarith only [hr,hz₁]\n    exact ⟨true,r,by exact_mod_cast hr₁,by simp only [mergedStart,ite_true]; omega⟩\n\n/-- Invert the known coefficient 1-j modulo the public modulus. -/\ndef wrapResidue (m j : ℕ) (z : ℤ) : ℕ :=\n  ((-publicInverse m (j-1)*z)%(m : ℤ)).toNat\n\n/-- The merged integer index determines the true wrap residue exactly. -/\ntheorem wrapResidue_eq {m j k : ℕ} {i : ℤ} (hj : 1≤j)\n    (hcop : (j-1).Coprime m) :\n    wrapResidue m j (combinedIndex m j k i)=k%m := by\n  let w := publicInverse m (j-1)\n  have hInv := (publicInverse_correct hcop).mul_right (k : ℤ)\n  have he : -w*combinedIndex m j k i=\n      (m : ℤ)*(-w*i)+((j-1 : ℕ) : ℤ)*w*k := by\n    have hjz : ((j-1 : ℕ) : ℤ)=(j : ℤ)-1 := by omega\n    unfold combinedIndex\n    rw [hjz]\n    ring\n  have hzero : (m : ℤ)*(-w*i) ≡ 0 [ZMOD m] :=\n    Int.modEq_zero_iff_dvd.mpr (dvd_mul_right _ _)\n  have hw : -w*combinedIndex m j k i ≡ (k : ℤ) [ZMOD m] := by\n    rw [he]\n    simpa only [zero_add,one_mul] using hzero.add hInv\n  unfold wrapResidue\n  rw [hw.eq,←Int.natCast_mod,Int.toNat_natCast]\n\n/-- Retain all three full wraps, rather than choosing one modular alias. -/\ndef mergedWraps (m j : ℕ) (z : ℤ) : List ℕ :=\n  (List.range 3).map fun l => wrapResidue m j z+l*m\n\n/-- Every proved linear wrap occurs among the three retained lifts. -/\ntheorem mergedWraps_mem {m j k : ℕ} {i : ℤ} (hm : 1<m) (hj : 1≤j)\n    (hcop : (j-1).Coprime m) (hk : k≤2*m+1) :\n    k∈mergedWraps m j (combinedIndex m j k i) := by\n  have hm₀ : 0<m := by omega\n  have hl : k/m<3 := (Nat.div_lt_iff_lt_mul hm₀).mpr (by omega)\n  unfold mergedWraps\n  apply List.mem_map.mpr\n  refine ⟨k/m,List.mem_range.mpr hl,?_⟩\n  rw [wrapResidue_eq hj hcop]\n  simpa only [Nat.mul_comm] using Nat.mod_add_div k m\n\n/-- Reconstruct the original exact short index at each retained full wrap. -/\ndef unmergeIndex (m j k : ℕ) (z : ℤ) : ℤ :=\n  (z-(1-(j : ℤ))*(k : ℤ))/(m : ℤ)\n\n/-- No integer recovery information is lost by the two index transports. -/\ntheorem unmergeIndex_exact {m : ℕ} (hm : 0<m) (j k : ℕ) (i : ℤ) :\n    unmergeIndex m j k (combinedIndex m j k i)=i := by\n  unfold unmergeIndex combinedIndex\n  rw [add_sub_cancel_right,Int.mul_ediv_cancel_left _ (by exact_mod_cast hm.ne')]\n\n/-- The decoder keeps the complete quadratic root list at every retained\nfull wrap, including a common global power collision. -/\ndef mergedRecovery {G : Type*} (N m t : ℕ) (s : ProgressionSeed G) (z : ℤ) : List ℤ :=\n  (mergedWraps m s.residue z).flatMap fun k =>\n    wrappedRecovery N m t k s (unmergeIndex m s.residue k z)\n\n/-- An original exact recovery root survives the finite alias bundle. -/\ntheorem mergedRecovery_preserves_root {G : Type*} {N m t k : ℕ}\n    (s : ProgressionSeed G) (i p : ℤ) (hm : 1<m) (hj : 1≤s.residue)\n    (hcop : (s.residue-1).Coprime m) (hk : k≤2*m+1)\n    (hroot : p∈wrappedRecovery N m t k s i) :\n    p∈mergedRecovery N m t s (combinedIndex m s.residue k i) := by\n  apply List.mem_flatMap.mpr\n  refine ⟨k,mergedWraps_mem hm hj hcop hk,?_⟩\n  rw [unmergeIndex_exact (by omega)]\n  exact hroot\n\n/-- There are exactly three retained wraps at any decoded index. -/\ntheorem mergedWraps_length (m j : ℕ) (z : ℤ) : (mergedWraps m j z).length=3 := by\n  simp only [mergedWraps,List.length_map,List.length_range]\n\n/-- Complete literal quadratic recovery requires at most six candidates. -/\ntheorem mergedRecovery_length_le_six {G : Type*} (N m t : ℕ)\n    (s : ProgressionSeed G) (z : ℤ) : (mergedRecovery N m t s z).length≤6 := by\n  unfold mergedRecovery\n  rw [List.length_flatMap]\n  have hb : ∀ k∈mergedWraps m s.residue z,\n      (wrappedRecovery N m t k s (unmergeIndex m s.residue k z)).length≤2 := by\n    intro k _\n    exact wrappedRecovery_length_le_two _ _ _ _ _ _\n  have hh := List.sum_le_length_nsmul\n    ((mergedWraps m s.residue z).map fun k =>\n      (wrappedRecovery N m t k s (unmergeIndex m s.residue k z)).length) 2\n    (by intro n hn; obtain ⟨k,hk,rfl⟩ := List.mem_map.mp hn; exact hb k hk)\n  simpa only [List.length_map,mergedWraps_length,smul_eq_mul] using hh\n\n/-- Normalize a signed half interval to the nonnegative interval reader. -/\ndef mergedTarget {G : Type*} [CommGroup G] (g : G) (m t : ℕ)\n    (s : ProgressionSeed G) (upper : Bool) : G :=\n  s.step^t*(commonStep g m)^(-mergedStart m upper)\n\n/-- The normalized reader retains the original absolute signed index. -/\ntheorem mergedTarget_root {G : Type*} [CommGroup G] (g : G) (m t : ℕ)\n    (s : ProgressionSeed G) (upper : Bool) (r : ℕ) {z : ℤ}\n    (hz : z=mergedStart m upper+r) (hhit : s.step^t=(commonStep g m)^z) :\n    mergedTarget g m t s upper=(commonStep g m)^r := by\n  simp only [mergedTarget,hhit,hz,←zpow_natCast,←zpow_add]\n  congr 1\n  ring\n\n/-- The merged target is constructed over the original public global\nring and commutes with the unavailable factor-field projection. -/\ntheorem mergedTarget_map {G H : Type*} [CommGroup G] [CommGroup H]\n    (φ : G→*H) (g : G) (N m j t : ℕ) (upper : Bool) :\n    φ (mergedTarget g m t (progressionSeed g N m j) upper)=\n      mergedTarget (φ g) m t (progressionSeed (φ g) N m j) upper := by\n  simp only [mergedTarget,commonStep,progressionSeed,map_mul,map_pow,map_zpow]\n\n/-- A retained original collision gives the corresponding common-base\nroot in either half, with no division by the vanishing detector. -/\ntheorem mergedTarget_map_root {G H : Type*} [CommGroup G] [CommGroup H]\n    (φ : G→*H) (g : G) (N m j t k : ℕ) (i : ℤ) (upper : Bool) (r : ℕ)\n    (hz : combinedIndex m j k i=mergedStart m upper+r)\n    (hhit : φ (wrappedValue t k (progressionSeed g N m j))=(φ g)^((m : ℤ)^2*i)) :\n    φ (mergedTarget g m t (progressionSeed g N m j) upper)=\n      (φ (commonStep g m))^r := by\n  rw [wrappedValue_map] at hhit\n  have he := (merged_hit_iff (φ g) N m j t k i).mp hhit\n  rw [mergedTarget_map]\n  simpa only [commonStep,map_zpow] using\n    mergedTarget_root (φ g) m t (progressionSeed (φ g) N m j) upper r hz he\n\n/-- The common base keeps both routed rough local periods, so each\nmerged half has simple roots without a new order oracle or stronger route. -/\ntheorem long_common_periods {p q m : ℕ} (hm : 1<m)\n    (g : (ZMod (p*q))ˣ) (hlong : LongData g m) :\n    let beta := commonStep (projectedUnit g m) m\n    mergedLength m≤orderOf (ZMod.castHom (dvd_mul_right p q) (ZMod p)\n      (beta : ZMod (p*q))) ∧\n    mergedLength m≤orderOf (ZMod.castHom (dvd_mul_left q p) (ZMod q)\n      (beta : ZMod (p*q))) := by\n  have heP : orderOf (ZMod.castHom (dvd_mul_right p q) (ZMod p)\n      ((commonStep (projectedUnit g m) m : (ZMod (p*q))ˣ) : ZMod (p*q)))=\n      orderOf (leftUnit (projectedUnit g m)) := by\n    change orderOf (((Units.map (ZMod.castHom (dvd_mul_right p q) (ZMod p)).toMonoidHom)\n      ((projectedUnit g m)^m) : (ZMod p)ˣ) : ZMod p)=_\n    rw [orderOf_units,map_pow]\n    exact (rough_coprime_small (by omega : 0<m) le_rfl hlong.2.2.2.2.2.1).orderOf_pow\n  have heQ : orderOf (ZMod.castHom (dvd_mul_left q p) (ZMod q)\n      ((commonStep (projectedUnit g m) m : (ZMod (p*q))ˣ) : ZMod (p*q)))=\n      orderOf (rightUnit (projectedUnit g m)) := by\n    change orderOf (((Units.map (ZMod.castHom (dvd_mul_left q p) (ZMod q)).toMonoidHom)\n      ((projectedUnit g m)^m) : (ZMod q)ˣ) : ZMod q)=_\n    rw [orderOf_units,map_pow]\n    exact (rough_coprime_small (by omega : 0<m) le_rfl hlong.2.2.2.2.2.2).orderOf_pow\n  dsimp only\n  rw [heP,heQ]\n  have hP := hlong.2.2.2.1.1\n  have hQ := hlong.2.2.2.1.2\n  unfold mergedLength\n  constructor <;> nlinarith only [hP,hQ]\n\n/-- The old bounded integer-index stage covers either merged half. -/\ntheorem merged_interval_cover (m : ℕ) : mergedLength m≤(2*m)^2 := by\n  unfold mergedLength\n  nlinarith\n\n/-- One merged half reads three scalars, then retains all possible full\nwrap tags if the collision is globally shared. Every candidate is checked. -/\nnoncomputable def recoverMergedHalf {N : ℕ} (g : (ZMod N)ˣ) (m t : ℕ)\n    (s : ProgressionSeed ((ZMod N)ˣ)) (upper : Bool) : Option ℕ :=\n  match recoverTaggedInterval (commonStep g m) (mergedTarget g m t s upper)\n      (mergedLength m) (2*m) with\n  | none => none\n  | some (Sum.inl d) => some d\n  | some (Sum.inr r) => recoverCandidates N (mergedRecovery N m t s (mergedStart m upper+r))\n\n/-- Every merged half result is a checked proper divisor. -/\ntheorem recoverMergedHalf_sound {N m t d : ℕ} (g : (ZMod N)ˣ)\n    (s : ProgressionSeed ((ZMod N)ˣ)) (upper : Bool)\n    (h : recoverMergedHalf g m t s upper=some d) : ProperDivisor N d := by\n  unfold recoverMergedHalf at h\n  split at h\n  · cases h\n  · rename_i e he\n    have hd := Option.some.inj h\n    subst d\n    exact recoverTaggedInterval_factor_sound _ _ he\n  · exact recoverCandidates_sound h\n\n/-- At a proved original witness, the half reader succeeds through\nnonsaturation, mixed-index saturation and an exact common global index. -/\ntheorem recoverMergedHalf_succeeds_of_exact_hit {p q m t k : ℕ} (hp : p.Prime)\n    (hq : q.Prime) (hpq : p<q) (hm : 1<m) (g : (ZMod (p*q))ˣ)\n    (j : ℕ) (hj : 1≤j) (hcop : (j-1).Coprime m) (i : ℤ) (hk : k≤2*m+1)\n    (upper : Bool) (r : ℕ) (hr : r<mergedLength m)\n    (hz : combinedIndex m j k i=mergedStart m upper+r)\n    (hLP : mergedLength m≤orderOf (ZMod.castHom (dvd_mul_right p q) (ZMod p)\n      ((commonStep g m : (ZMod (p*q))ˣ) : ZMod (p*q))))\n    (hLQ : mergedLength m≤orderOf (ZMod.castHom (dvd_mul_left q p) (ZMod q)\n      ((commonStep g m : (ZMod (p*q))ˣ) : ZMod (p*q))))\n    (hhit : (Units.map (ZMod.castHom (dvd_mul_right p q) (ZMod p)).toMonoidHom)\n      (wrappedValue t k (progressionSeed g (p*q) m j))=\n        ((Units.map (ZMod.castHom (dvd_mul_right p q) (ZMod p)).toMonoidHom) g)^((m : ℤ)^2*i))\n    (hroot : (p : ℤ)∈wrappedRecovery (p*q) m t k (progressionSeed g (p*q) m j) i) :\n    ∃ d, recoverMergedHalf g m t (progressionSeed g (p*q) m j) upper=some d := by\n  have hpow := mergedTarget_map_root\n    (Units.map (ZMod.castHom (dvd_mul_right p q) (ZMod p)).toMonoidHom)\n    g (p*q) m j t k i upper r hz hhit\n  have hval := congrArg (fun u : (ZMod p)ˣ => (u : ZMod p)) hpow\n  simp only [Units.coe_map,Units.val_pow_eq_pow_val] at hval\n  have hd := recoverTaggedInterval_preserves_root hp hq hpq _ _ hr\n    (merged_interval_cover m) hLP hLQ hval\n  rcases hd with ⟨d,hd⟩|hd\n  · exact ⟨d,by simp only [recoverMergedHalf,hd]⟩\n  · have hproper : ProperDivisor (p*q) p :=\n      ⟨hp.one_lt,by nlinarith only [hq.one_lt,hp.pos],dvd_mul_right p q⟩\n    have hmem := mergedRecovery_preserves_root (progressionSeed g (p*q) m j) i p\n      hm hj hcop hk hroot\n    change (p : ℤ)∈mergedRecovery (p*q) m t (progressionSeed g (p*q) m j)\n      (combinedIndex m j k i) at hmem\n    rw [hz] at hmem\n    obtain ⟨d,he⟩ := recoverCandidates_succeeds hproper hmem\n    exact ⟨d,by simpa only [recoverMergedHalf,hd] using he⟩\n\n/-- Acquire a merged half from one common m-root polynomial and 3m\nnormalized points, without expanding its quadratic interval. -/\nnoncomputable def mergedJet {R : Type*} [CommRing R] (beta : Rˣ) (x : R)\n    (m : ℕ) : R×R×R :=\n  SemiprimeSharedIntervalJet.sharedBlockedJet beta x m (3*m)\n\n/-- The same shared polynomial works for every residue, denominator and\nhalf, and its product and marked derivatives are exact through zeros. -/\ntheorem mergedJet_exact {R : Type*} [CommRing R] (beta : Rˣ) (x : R)\n    {m : ℕ} (hm : 0<m) :\n    mergedJet beta x m=(intervalProduct (beta : R) x (mergedLength m),\n      targetDerivative (beta : R) x (mergedLength m),\n      baseDerivative (beta : R) x (mergedLength m)) := by\n  unfold mergedJet\n  rw [SemiprimeSharedIntervalJet.sharedBlockedJet_exact beta x hm]\n  have he : (3*m)*m=mergedLength m := by unfold mergedLength; ring\n  rw [he]\n\n/-- Read the three acquired merged-half scalars with the exact tag decoder. -/\nnoncomputable def recoverBlockedMergedHalf {N : ℕ} (g : (ZMod N)ˣ) (m t : ℕ)\n    (s : ProgressionSeed ((ZMod N)ˣ)) (upper : Bool) : Option ℕ :=\n  let beta := commonStep g m\n  let x := mergedTarget g m t s upper\n  match recoverTaggedJet beta x (mergedLength m) (2*m)\n      (mergedJet beta (x : ZMod N) m) with\n  | none => none\n  | some (Sum.inl d) => some d\n  | some (Sum.inr r) => recoverCandidates N (mergedRecovery N m t s (mergedStart m upper+r))\n\n/-- Blocked acquisition preserves the precise saturation-complete reader. -/\ntheorem recoverBlockedMergedHalf_eq {N m t : ℕ} (hm : 0<m) (g : (ZMod N)ˣ)\n    (s : ProgressionSeed ((ZMod N)ˣ)) (upper : Bool) :\n    recoverBlockedMergedHalf g m t s upper=recoverMergedHalf g m t s upper := by\n  simp only [recoverBlockedMergedHalf,mergedJet_exact _ _ hm,\n    recoverMergedHalf,recoverTaggedInterval]\n\n/-- The reduced public target stream contains only residue/denominator\npairs and two half flags. Cached seeds are retained without an i axis. -/\ndef mergedColumns {G : Type*} [CommGroup G] (g : G) (N m : ℕ) :\n    List (ℕ×ProgressionSeed G×Bool) :=\n  (progressionSeeds g N m).flatMap fun s =>\n    (List.range (m-1)).flatMap fun r => [(r+1,s,false),(r+1,s,true)]\n\n/-- Every cached seed and positive denominator is queried in both halves. -/\ntheorem mergedColumn_mem {G : Type*} [CommGroup G] {g : G} {N m t : ℕ}\n    {s : ProgressionSeed G} (hs : s∈progressionSeeds g N m) (ht : 0<t) (htm : t<m)\n    (upper : Bool) : (t,s,upper)∈mergedColumns g N m := by\n  apply List.mem_flatMap.mpr\n  refine ⟨s,hs,?_⟩\n  apply List.mem_flatMap.mpr\n  refine ⟨t-1,List.mem_range.mpr (by omega),?_⟩\n  have he : t-1+1=t := by omega\n  rw [he]\n  cases upper <;> simp\n\n/-- Exact target record count; the former short-index axis is absent. -/\ntheorem mergedColumns_length {G : Type*} [CommGroup G] (g : G) (N m : ℕ) :\n    (mergedColumns g N m).length=2*(m-1)^2 := by\n  simp [mergedColumns,progressionSeeds,List.length_flatMap,pow_two,Function.comp_def]\n  ring\n\n/-- A public scan of the reduced target stream, using the blocked common\npolynomial reader. Its executable backend and whole bit bound remain open. -/\nnoncomputable def scanMergedColumns {N : ℕ} (g : (ZMod N)ˣ) (m : ℕ) :\n    List (ℕ×ProgressionSeed ((ZMod N)ˣ)×Bool)→Option ℕ\n  | [] => none\n  | (t,s,upper)::xs => match recoverBlockedMergedHalf g m t s upper with\n    | some d => some d\n    | none => scanMergedColumns g m xs\n\n/-- Every factor returned by the complete reduced stream is proper. -/\ntheorem scanMergedColumns_sound {N m d : ℕ} (hm : 0<m) (g : (ZMod N)ˣ)\n    {xs : List (ℕ×ProgressionSeed ((ZMod N)ˣ)×Bool)}\n    (h : scanMergedColumns g m xs=some d) : ProperDivisor N d := by\n  induction xs with\n  | nil => simp only [scanMergedColumns] at h; cases h\n  | cons a xs ih =>\n    rcases a with ⟨t,s,upper⟩\n    unfold scanMergedColumns at h\n    split at h\n    · rename_i e he\n      have hd := Option.some.inj h\n      subst d\n      rw [recoverBlockedMergedHalf_eq hm] at he\n      exact recoverMergedHalf_sound _ _ _ he\n    · exact ih h\n\n/-- A successful member guarantees success of the entire public stream,\nwithout an assumed tie order or a hidden successful tag supplied as input. -/\ntheorem scanMergedColumns_succeeds_of_member {N m t d : ℕ} (g : (ZMod N)ˣ)\n    (s : ProgressionSeed ((ZMod N)ˣ)) (upper : Bool)\n    {xs : List (ℕ×ProgressionSeed ((ZMod N)ˣ)×Bool)}\n    (hmem : (t,s,upper)∈xs) (hd : recoverBlockedMergedHalf g m t s upper=some d) :\n    ∃ e, scanMergedColumns g m xs=some e := by\n  induction xs with\n  | nil => simp only [List.not_mem_nil] at hmem\n  | cons a xs ih =>\n    rcases a with ⟨t',s',upper'⟩\n    rw [scanMergedColumns]\n    cases he : recoverBlockedMergedHalf g m t' s' upper' with\n    | some e => exact ⟨e,rfl⟩\n    | none =>\n      have hh := List.mem_cons.mp hmem\n      rcases hh with hh|hh\n      · cases hh\n        rw [hd] at he\n        cases he\n      · exact ih hh\n\n/-- The actual matched-width long route has a successful merged target.\nEvery factor ratio and exact quadratic witness comes from the arithmetic\nforcing theorem, not from a supplied successful collision certificate. -/\ntheorem long_public_route_merged_column {p q a : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (hpq : p<q) (hB : 4≤SemiprimeLehmanCoverage.sixthWidth (p*q))\n    (hnone : SemiprimeStrassenPrefix.factorPrefix (p*q)\n      (SemiprimeEuclidRowBudget.publicRowModulus (p*q))=none)\n    (hroute : routeAtRowModulus (p*q)=.longBase a) :\n    ∃ hc : a.Coprime (p*q),\n      let m := SemiprimeEuclidRowBudget.publicRowModulus (p*q)\n      let h := projectedUnit (ZMod.unitOfCoprime a hc) m\n      ∃ (t : ℕ) (upper : Bool),\n        (t,progressionSeed h (p*q) m (p%m),upper)∈mergedColumns h (p*q) m ∧\n        ∃ d, recoverBlockedMergedHalf h m t (progressionSeed h (p*q) m (p%m)) upper=some d := by\n  have hd := routeAtRowModulus_semiprime hp hq hpq hB\n  rw [hroute] at hd\n  obtain ⟨hc,hlong⟩ := hd\n  let m := SemiprimeEuclidRowBudget.publicRowModulus (p*q)\n  let g := ZMod.unitOfCoprime a hc\n  have hN := Nat.mul_pos hp.pos hq.pos\n  have hmBounds := SemiprimeEuclidRowBudget.publicRowModulus_bounds hN\n  have hm : 1<m := by dsimp only [m]; omega\n  have hsize : p*q≤m^6 := (SemiprimeLehmanCoverage.sixthWidth_upper (p*q)).trans\n    (Nat.pow_le_pow_left hmBounds.1 6)\n  have hcover : m^2<p*q := public_modulus_prefix_below_input hN hB\n  have hprefix := SemiprimeStrassenPrefix.prefix_none_excludes_small_prime\n    hcover hp (dvd_mul_right p q) hnone\n  have hj : 1<p%m := by\n    have he := long_true_residue_ne_one hp hpq.le hm hprefix.le hsize g hlong\n    have hmm : m≤m^2 := by nlinarith only [hm]\n    have hcop := SemiprimeStrassenPrefix.prefix_none_coprime_integer\n      hcover hnone (by omega : 0<m) hmm\n    have hjcop : (p%m).Coprime m := by\n      change Nat.gcd (p%m) m=1\n      rw [←Nat.gcd_rec]\n      exact hcop.symm.of_dvd_right (dvd_mul_right p q)\n    have hjpos : 0<p%m := by\n      by_contra! hn\n      have hz : p%m=0 := by omega\n      simp only [hz,Nat.coprime_zero_left] at hjcop\n      omega\n    omega\n  have hmprime : m.Prime := SemiprimeEuclidRowBudget.publicRowModulus_prime (p*q)\n  have hcop : (p%m-1).Coprime m :=\n    (hmprime.coprime_iff_not_dvd.mpr (Nat.not_dvd_of_pos_of_lt\n      (by omega : 0<p%m-1) (by have hh := Nat.mod_lt p (by omega : 0<m); omega))).symm\n  have hperiods := long_common_periods hm g hlong\n  obtain ⟨t,k,i,hcache,_hrow,ht,htm,_htx,hk,hi,hhit,hroot⟩ :=\n    actual_public_hyperbolic_after_prefix hp hq hpq.le hB hnone (projectedUnit g m)\n  have hz := combinedIndex_bounds hm hj.le (Nat.mod_lt p (by omega)) hk hi\n  obtain ⟨upper,r,hr,hz⟩ := combinedIndex_half hz.1 hz.2\n  obtain ⟨d,hd⟩ := recoverMergedHalf_succeeds_of_exact_hit hp hq hpq hm\n    (projectedUnit g m) (p%m) hj.le hcop i hk upper r hr hz\n      hperiods.1 hperiods.2 hhit hroot\n  refine ⟨hc,t,upper,mergedColumn_mem hcache ht htm upper,d,?_⟩\n  rw [recoverBlockedMergedHalf_eq (by omega)]\n  exact hd\n\n/-- A finite N-only scan of the reduced target records is complete on\nthe actual long branch, including saturated and common global hits. -/\ntheorem long_public_route_scan_succeeds {p q a : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (hpq : p<q) (hB : 4≤SemiprimeLehmanCoverage.sixthWidth (p*q))\n    (hnone : SemiprimeStrassenPrefix.factorPrefix (p*q)\n      (SemiprimeEuclidRowBudget.publicRowModulus (p*q))=none)\n    (hroute : routeAtRowModulus (p*q)=.longBase a) :\n    ∃ hc : a.Coprime (p*q),\n      let m := SemiprimeEuclidRowBudget.publicRowModulus (p*q)\n      let h := projectedUnit (ZMod.unitOfCoprime a hc) m\n      ∃ d, scanMergedColumns h m (mergedColumns h (p*q) m)=some d ∧ ProperDivisor (p*q) d := by\n  obtain ⟨hc,t,upper,hmem,d,hd⟩ := long_public_route_merged_column hp hq hpq hB hnone hroute\n  obtain ⟨e,he⟩ := scanMergedColumns_succeeds_of_member _ _ _ hmem hd\n  have hmBounds := SemiprimeEuclidRowBudget.publicRowModulus_bounds (Nat.mul_pos hp.pos hq.pos)\n  exact ⟨hc,e,he,scanMergedColumns_sound (by omega) _ he⟩\n\n/-- A SINGLE common interval polynomial, its target derivative and its\nmarked base derivative serve every merged target. This is a specification\nof their coefficients; a fast executable construction is not assumed. -/\nnoncomputable def mergedPolynomials {R : Type*} [CommRing R] (beta : R) (m : ℕ) :\n    R[X]×R[X]×R[X] :=\n  let P := SemiprimeCartesianCompletion.rootPolynomial (Finset.range (mergedLength m))\n    (fun r => beta^r)\n  (P,P.derivative,SemiprimeSharedIntervalJet.babyBasePolynomial beta (mergedLength m))\n\n/-- Evaluate the three separately retained channels at one public target. -/\nnoncomputable def evaluateMergedPolynomials {R : Type*} [CommRing R]\n    (P : R[X]×R[X]×R[X]) (x : R) : R×R×R :=\n  (P.1.eval x,P.2.1.eval x,P.2.2.eval x)\n\n/-- Batch polynomial evaluation supplies each original merged detector\nand both exact derivatives over EVERY commutative ring, through all zeros. -/\ntheorem mergedPolynomials_eval_exact {R : Type*} [CommRing R] (beta x : R) (m : ℕ) :\n    evaluateMergedPolynomials (mergedPolynomials beta m) x=\n      (intervalProduct beta x (mergedLength m),targetDerivative beta x (mergedLength m),\n        baseDerivative beta x (mergedLength m)) := by\n  simp only [evaluateMergedPolynomials,mergedPolynomials,\n    ←targetDerivative_eq_derivative,SemiprimeSharedIntervalJet.babyBasePolynomial_eval]\n  simp only [SemiprimeCartesianCompletion.rootPolynomial,Polynomial.eval_prod,\n    Polynomial.eval_sub,Polynomial.eval_X,Polynomial.eval_C,intervalProduct]\n\n/-- Read a supplied triple alongside its ORIGINAL target record. Scalar\nacquisition can be shared while the two index channels stay unpooled. -/\nnoncomputable def readMergedJet {N : ℕ} (g : (ZMod N)ˣ) (m : ℕ)\n    (c : ℕ×ProgressionSeed ((ZMod N)ˣ)×Bool) (jet : ZMod N×ZMod N×ZMod N) : Option ℕ :=\n  match recoverTaggedJet (commonStep g m) (mergedTarget g m c.1 c.2.1 c.2.2)\n      (mergedLength m) (2*m) jet with\n  | none => none\n  | some (Sum.inl d) => some d\n  | some (Sum.inr r) => recoverCandidates N\n      (mergedRecovery N m c.1 c.2.1 (mergedStart m c.2.2+r))\n\n/-- Shared polynomial evaluation gives the original tag-preserving reader. -/\ntheorem readMergedJet_exact {N : ℕ} (g : (ZMod N)ˣ) (m t : ℕ)\n    (s : ProgressionSeed ((ZMod N)ˣ)) (upper : Bool) :\n    readMergedJet g m (t,s,upper)\n      (evaluateMergedPolynomials\n        (mergedPolynomials ((commonStep g m : (ZMod N)ˣ) : ZMod N) m)\n        ((mergedTarget g m t s upper : (ZMod N)ˣ) : ZMod N))=\n      recoverMergedHalf g m t s upper := by\n  simp only [readMergedJet,mergedPolynomials_eval_exact,recoverMergedHalf,recoverTaggedInterval]\n\n/-- Retain the target tag beside each of the three evaluated scalars.\nThe three common polynomials are constructed once before the target map. -/\nnoncomputable def mergedBatchJets {N : ℕ} (g : (ZMod N)ˣ) (m : ℕ) :\n    List ((ℕ×ProgressionSeed ((ZMod N)ˣ)×Bool)×(ZMod N×ZMod N×ZMod N)) :=\n  let P := mergedPolynomials ((commonStep g m : (ZMod N)ˣ) : ZMod N) m\n  (mergedColumns g N m).map fun c =>\n    (c,evaluateMergedPolynomials P ((mergedTarget g m c.1 c.2.1 c.2.2 : (ZMod N)ˣ) : ZMod N))\n\n/-- Read an aligned batch of tagged triples. No sum or product of the\ndifferent zero targets replaces their separately retained index channels. -/\nnoncomputable def scanMergedJetBatch {N : ℕ} (g : (ZMod N)ˣ) (m : ℕ) :\n    List ((ℕ×ProgressionSeed ((ZMod N)ˣ)×Bool)×(ZMod N×ZMod N×ZMod N))→Option ℕ\n  | [] => none\n  | (c,jet)::xs => match readMergedJet g m c jet with\n    | some d => some d\n    | none => scanMergedJetBatch g m xs\n\n/-- Aligned common-polynomial acquisition equals the proved blocked\nscan on every public target list, including saturation and global matches. -/\ntheorem scanMergedJetBatch_map_exact {N m : ℕ} (hm : 0<m) (g : (ZMod N)ˣ)\n    (xs : List (ℕ×ProgressionSeed ((ZMod N)ˣ)×Bool)) :\n    scanMergedJetBatch g m (xs.map fun c =>\n      (c,evaluateMergedPolynomials\n        (mergedPolynomials ((commonStep g m : (ZMod N)ˣ) : ZMod N) m)\n        ((mergedTarget g m c.1 c.2.1 c.2.2 : (ZMod N)ˣ) : ZMod N)))=\n      scanMergedColumns g m xs := by\n  induction xs with\n  | nil => rfl\n  | cons c xs ih =>\n    rcases c with ⟨t,s,upper⟩\n    simp only [List.map_cons,scanMergedJetBatch,readMergedJet_exact,\n      scanMergedColumns,recoverBlockedMergedHalf_eq hm]\n    cases he : recoverMergedHalf g m t s upper with\n    | some d => rfl\n    | none => exact ih\n\n/-- The whole labelled batch computes the same complete public scan. -/\ntheorem mergedBatch_scan_exact {N m : ℕ} (hm : 0<m) (g : (ZMod N)ˣ) :\n    scanMergedJetBatch g m (mergedBatchJets g m)=\n      scanMergedColumns g m (mergedColumns g N m) := by\n  exact scanMergedJetBatch_map_exact hm g _\n\n/-- Every factor returned after common-polynomial acquisition is proper. -/\ntheorem mergedBatch_scan_sound {N m d : ℕ} (hm : 0<m) (g : (ZMod N)ˣ)\n    (h : scanMergedJetBatch g m (mergedBatchJets g m)=some d) : ProperDivisor N d := by\n  rw [mergedBatch_scan_exact hm] at h\n  exact scanMergedColumns_sound hm g h\n\n/-- Shared whole-batch acquisition preserves the guaranteed factor on\nevery actual public long output and every remaining factor ratio. -/\ntheorem long_public_route_batch_succeeds {p q a : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (hpq : p<q) (hB : 4≤SemiprimeLehmanCoverage.sixthWidth (p*q))\n    (hnone : SemiprimeStrassenPrefix.factorPrefix (p*q)\n      (SemiprimeEuclidRowBudget.publicRowModulus (p*q))=none)\n    (hroute : routeAtRowModulus (p*q)=.longBase a) :\n    ∃ hc : a.Coprime (p*q),\n      let m := SemiprimeEuclidRowBudget.publicRowModulus (p*q)\n      let h := projectedUnit (ZMod.unitOfCoprime a hc) m\n      ∃ d, scanMergedJetBatch h m (mergedBatchJets h m)=some d ∧ ProperDivisor (p*q) d := by\n  obtain ⟨hc,d,hd,hproper⟩ := long_public_route_scan_succeeds hp hq hpq hB hnone hroute\n  have hmBounds := SemiprimeEuclidRowBudget.publicRowModulus_bounds (Nat.mul_pos hp.pos hq.pos)\n  exact ⟨hc,d,by rwa [mergedBatch_scan_exact (by omega)],hproper⟩\n\n/-- There is one triple per reduced target, retaining every target tag. -/\ntheorem mergedBatchJets_length {N : ℕ} (g : (ZMod N)ˣ) (m : ℕ) :\n    (mergedBatchJets g m).length=2*(m-1)^2 := by\n  simp only [mergedBatchJets,List.length_map,mergedColumns_length]\n\n/-- Root inputs, target points, cached seeds and one constant have a\nquadratic whole-family count. No per-residue wrap polynomial is needed.\nThis input count is not a polynomial arithmetic or bit-cost certificate. -/\ntheorem merged_whole_input_bound {G : Type*} [CommGroup G] (g : G) (N m : ℕ) (hm : 0<m) :\n    mergedLength m+(mergedColumns g N m).length+(progressionSeeds g N m).length+1≤\n      5*m^2+m := by\n  rw [mergedColumns_length,progressionSeeds_length,mergedLength]\n  have he : m-1+1=m := by omega\n  have hs := Nat.pow_le_pow_left (Nat.sub_le m 1) 2\n  nlinarith only [he,hs]\n\n/-- A full common-interval polynomial necessarily has quadratic degree\non the actual long branch. This restricts that representation, not every\nimplicit circuit capable of acquiring the required collision. -/\ntheorem common_polynomial_degree_floor {p q m : ℕ} (hm : 1<m) (hp : p.Prime)\n    (g : (ZMod (p*q))ˣ) (hlong : LongData g m) (P : (ZMod p)[X]) (hP : P≠0)\n    (hzero : ∀ r<mergedLength m, P.eval\n      ((ZMod.castHom (dvd_mul_right p q) (ZMod p)\n        ((commonStep (projectedUnit g m) m : (ZMod (p*q))ˣ) : ZMod (p*q)))^r)=0) :\n    mergedLength m≤P.natDegree := by\n  let : Fact p.Prime := ⟨hp⟩\n  exact interval_annihilator_degree _ (long_common_periods hm g hlong).1 P hP hzero\n\nend RiemannGaussian.SemiprimeMergedIndexAcquisition\n","RiemannGaussian.SemiprimePaidConstraintAcquisition":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimePaidConstraintRows\nimport RiemannGaussian.SemiprimePaidPackingSnapshot\n\n/-! # Acquiring the complete finite integer constraint family\nAll row names and all original-coordinate entries are explicitly materialized.\nThe universal numerator and packing tables are acquired once before this loop.\nThe result is a scalar/list work ledger, not a primitive bit clock.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimePaidConstraintAcquisition\nopen OAI.Algorithms.SubexponentialSAT\nopen MulticolorTypes Subexp.ConstructivePacking\nopen SemiprimeMaterializedSourceUniversal\nopen SemiprimePaidConstraintRows (Index encode source source_value source_work)\nvariable {I : Type} {n r Q : ℕ}\n\n/-- All complete-block row names in ascending block and original alphabet order. -/\ndef blockNames (keys : List (UniversalType r Q 1)) : ℕ → Run (List (Index I r Q))\n  | 0 => ⟨[],1⟩\n  | b+1 =>\n      let prev := blockNames keys b\n      let next := collect (fun u => (⟨Sum.inl (b,u),2⟩ : Run (Index I r Q))) keys\n      ⟨prev.value++next.value,prev.work+next.work+prev.value.length+3⟩\n\ntheorem blockNames_value (keys : List (UniversalType r Q 1)) (b : ℕ) :\n    (blockNames (I:=I) keys b).value=\n      (List.range b).flatMap (fun k => keys.map (fun u => Sum.inl (k,u))) := by\n  induction b with\n  | zero => rfl\n  | succ b ih => simp [blockNames,ih,collect_value,List.range_succ]\n\ntheorem blockNames_length (keys : List (UniversalType r Q 1)) (b : ℕ) :\n    (blockNames (I:=I) keys b).value.length=b*keys.length := by\n  rw [blockNames_value]\n  simp [List.length_flatMap,List.sum_replicate]\n\ntheorem blockNames_work (keys : List (UniversalType r Q 1)) (b : ℕ) :\n    (blockNames (I:=I) keys b).work≤10*(b+1)^2*(keys.length+1) := by\n  induction b with\n  | zero => simp [blockNames]; omega\n  | succ b ih =>\n      have hc := collect_work (fun u => (⟨Sum.inl (b,u),2⟩ : Run (Index I r Q))) keys 2\n        (by intro u _; rfl)\n      simp only [blockNames,blockNames_length]\n      nlinarith\n\n/-- Append every original incidence as a potential leftover row. -/\ndef names (keys : List (UniversalType r Q 1)) (blocks : ℕ) (is : List I) :\n    Run (List (Index I r Q)) :=\n  let bs := blockNames keys blocks\n  let tail := collect (fun i => (⟨Sum.inr i,1⟩ : Run (Index I r Q))) is\n  ⟨bs.value++tail.value,bs.work+tail.work+bs.value.length+2⟩\n\ntheorem names_value (keys : List (UniversalType r Q 1)) (blocks : ℕ) (is : List I) :\n    (names keys blocks is).value=\n      (List.range blocks).flatMap (fun b => keys.map (fun u => Sum.inl (b,u)))++is.map Sum.inr := by\n  simp only [names,blockNames_value,collect_value]\n\ntheorem names_length (keys : List (UniversalType r Q 1)) (blocks : ℕ) (is : List I) :\n    (names keys blocks is).value.length=blocks*keys.length+is.length := by\n  simp only [names,List.length_append,blockNames_length,collect_value,List.length_map]\n\n/-- The acquired row ordering is precisely the old padded enumeration ordering. -/\ntheorem names_packing (P : PackingData I (UniversalType r Q 1)) :\n    (names P.types.values P.blockCount P.vertices.values).value=\n      (SemiprimePaddedBlockExecution.indices P).values.map (encode P) := by\n  rw [names_value]\n  simp only [SemiprimePaddedBlockExecution.indices,SemiprimeFiniteEnumerations.sum,\n    SemiprimeFiniteEnumerations.prod,SemiprimeFiniteEnumerations.fin,List.map_append,\n    List.map_map,Function.comp_def,encode,List.product,List.map_flatMap]\n  rw [← List.map_coe_finRange P.blockCount,List.flatMap_map]\n\ntheorem names_work (keys : List (UniversalType r Q 1)) (blocks : ℕ) (is : List I) :\n    (names keys blocks is).work≤\n      10*(blocks+1)^2*(keys.length+1)+3*is.length+blocks*keys.length+3 := by\n  have hb := blockNames_work (I:=I) keys blocks\n  have ht := collect_work (fun i => (⟨Sum.inr i,1⟩ : Run (Index I r Q))) is 1\n    (by intro i _; rfl)\n  simp only [names,blockNames_length]\n  omega\n\nvariable [DecidableEq I]\n\n/-- One dense original-coordinate row, acquired by literal finite callback calls. -/\ndef row (is : List I) (owner : I → Fin n)\n    (addresses : SemiprimeMaterializedSourcePullback.Addresses I r Q)\n    (producer : I → Run (UniversalType r Q 1))\n    (cache : SemiprimePaidConstraintCache.Cache (r:=r) (Q:=Q))\n    (t : Fin Q) (g : Fin r) (j : Index I r Q) : Run (List ℤ) :=\n  let out := collect (source is owner addresses producer cache t g j) (List.finRange n)\n  ⟨out.value,out.work+2*n+1⟩\n\n/-- The complete Q-by-r-by-p-by-n integer family from already acquired finite data. -/\ndef table (is : List I) (owner : I → Fin n)\n    (addresses : SemiprimeMaterializedSourcePullback.Addresses I r Q)\n    (producer : I → Run (UniversalType r Q 1))\n    (cache : SemiprimePaidConstraintCache.Cache (r:=r) (Q:=Q))\n    (js : List (Index I r Q)) : Run (List (List (List (List ℤ)))) :=\n  let out := collect (fun t => collect (fun g => collect\n    (row is owner addresses producer cache t g) js) (List.finRange r)) (List.finRange Q)\n  ⟨out.value,out.work+Q*(2*r+1)+2*Q+1⟩\n\ntheorem table_value (is : List I) (owner : I → Fin n)\n    (addresses : SemiprimeMaterializedSourcePullback.Addresses I r Q)\n    (producer : I → Run (UniversalType r Q 1))\n    (cache : SemiprimePaidConstraintCache.Cache (r:=r) (Q:=Q)) (js : List (Index I r Q)) :\n    (table is owner addresses producer cache js).value=\n      (List.finRange Q).map (fun t => (List.finRange r).map (fun g =>\n        js.map (fun j => (List.finRange n).map (fun v =>\n          (source is owner addresses producer cache t g j v).value)))) := by\n  simp only [table,row,collect_value]\n\n/-- Complete acquired integer family and its literal original row names. -/\nstructure Family (I : Type) (r Q : ℕ) where\n  /-- Original padded row names, in their exact source order. -/\n  indices : List (Index I r Q)\n  /-- Stored entries: node, head, original row, original variable. -/\n  entries : List (List (List (List ℤ)))\n\n/-- Actually acquire packing, numerators, row names and every integer entry. -/\ndef acquire (A R : ℕ) (is : List I) (owner : I → Fin n)\n    (keys : List (UniversalType r Q 1)) (producer : I → Run (UniversalType r Q 1)) :\n    Run (Family I r Q) :=\n  let pack := SemiprimePaidPackingSnapshot.acquire is keys producer\n  let cache := SemiprimePaidConstraintCache.acquire A R keys\n  let js := names keys pack.value.blocks is\n  let entries := table is owner pack.value.addresses producer cache.value js.value\n  ⟨⟨js.value,entries.value⟩,pack.work+cache.work+js.work+entries.work+n+r+Q+4⟩\n\n/-- Original integer entries are acquired in exactly the original padded row order. -/\ntheorem acquire_entries [Fintype I] (P : PackingData I (UniversalType r Q 1))\n    (A R : ℕ) (owner : I → Fin n) (producer : I → Run (UniversalType r Q 1))\n    (hp : ∀ i, (producer i).value=P.label i) :\n    (acquire A R P.vertices.values owner P.types.values producer).value.entries=\n      (List.finRange Q).map (fun t => (List.finRange r).map (fun g =>\n        (SemiprimePaddedBlockExecution.indices P).values.map (fun j =>\n          (List.finRange n).map (SemiprimePaddedBlockExecution.sourceRow P owner\n            (fun u => u.head t) g (SemiprimeUniversalSourceExecution.constraint A R t g) j)))) := by\n  unfold acquire\n  dsimp only\n  rw [SemiprimePaidPackingSnapshot.acquire_blocks P producer hp,\n    SemiprimePaidPackingSnapshot.acquire_addresses P producer hp,names_packing,table_value]\n  simp only [List.map_map,Function.comp_def,source_value P A R owner producer hp]\n\n/-- Explicit polynomial for the already acquired integer-entry loop. -/\ndef tableBudget (M n D L B Q r p : ℕ) : ℕ :=\n  Q*(r*(p*(n*(M*(3*L+B+9*Q+2*(D*(7*Q+4)+1)+29)+5)+4)+3)+3)+1+Q*(2*r+1)+2*Q+1\n\ntheorem table_work (A R : ℕ) (keys : List (UniversalType r Q 1))\n    (is : List I) (owner : I → Fin n)\n    (addresses : SemiprimeMaterializedSourcePullback.Addresses I r Q)\n    (producer : I → Run (UniversalType r Q 1)) (B : ℕ)\n    (hw : ∀ i, (producer i).work≤B) (js : List (Index I r Q)) :\n    (table is owner addresses producer (SemiprimePaidConstraintCache.acquire A R keys).value js).work≤\n      tableBudget is.length n keys.length addresses.length B Q r js.length := by\n  let E := is.length*(3*addresses.length+B+9*Q+2*(keys.length*(7*Q+4)+1)+29)+1\n  have hr (t : Fin Q) (g : Fin r) (j : Index I r Q) :\n      (row is owner addresses producer (SemiprimePaidConstraintCache.acquire A R keys).value t g j).work≤\n        n*(E+4)+2 := by\n    have hc := collect_work (source is owner addresses producer\n        (SemiprimePaidConstraintCache.acquire A R keys).value t g j) (List.finRange n) E\n        (fun v _ => source_work A R keys is owner addresses producer B hw t g j v)\n    simp only [List.length_finRange] at hc\n    unfold row\n    dsimp only\n    nlinarith\n  have hj (t : Fin Q) (g : Fin r) :\n      (collect (row is owner addresses producer\n        (SemiprimePaidConstraintCache.acquire A R keys).value t g) js).work≤\n        js.length*(n*(E+4)+4)+1 := by\n    exact collect_work _ _ _ (fun j _ => hr t g j)\n  have hg (t : Fin Q) :\n      (collect (fun g => collect (row is owner addresses producer\n        (SemiprimePaidConstraintCache.acquire A R keys).value t g) js) (List.finRange r)).work≤\n        r*(js.length*(n*(E+4)+4)+3)+1 := by\n    simpa only [List.length_finRange] using collect_work _ (List.finRange r) _ (fun g _ => hj t g)\n  have ht := collect_work _ (List.finRange Q) _ (fun t _ => hg t)\n  simp only [List.length_finRange] at ht\n  unfold table tableBudget\n  dsimp only\n  dsimp only [E] at ht\n  norm_num only [Nat.add_assoc] at ht ⊢\n  omega\n\n/-- All setup and all entries; block count is an actual acquired dimension. -/\ndef budget (A R M n D B Q r blocks : ℕ) : ℕ :=\n  SemiprimeMaterializedSourceAcquisition.packingBudget M D Q B+1+\n  SemiprimeMaterializedSourceUniversal.tableBudget A R Q D+2*R+4+\n  (10*(blocks+1)^2*(D+1)+3*M+blocks*D+3)+\n  tableBudget M n D M B Q r (blocks*D+M)+n+r+Q+4\n\n/-- The complete original integer family retains every setup and entry-loop report. -/\ntheorem acquire_work (P : PackingData I (UniversalType r Q 1)) (A R : ℕ)\n    (owner : I → Fin n) (producer : I → Run (UniversalType r Q 1))\n    (hp : ∀ i, (producer i).value=P.label i) (B : ℕ) (hw : ∀ i, (producer i).work≤B) :\n    (acquire A R P.vertices.values owner P.types.values producer).work≤\n      budget A R P.vertices.values.length n P.types.values.length B Q r P.blockCount := by\n  have hpw := SemiprimePaidPackingSnapshot.acquire_work P producer hp B hw\n  have hcw := SemiprimePaidConstraintCache.acquire_work A R P.types.values\n  have hjw := names_work P.types.values P.blockCount P.vertices.values\n  have htw := table_work A R P.types.values P.vertices.values owner\n    (SemiprimePaidPackingSnapshot.acquire P.vertices.values P.types.values producer).value.addresses\n    producer B hw (names P.types.values P.blockCount P.vertices.values).value\n  have hl : (SemiprimePaidPackingSnapshot.acquire P.vertices.values P.types.values producer).value.addresses.length=\n      P.vertices.values.length := by\n    rw [SemiprimePaidPackingSnapshot.acquire_addresses P producer hp]\n    exact List.length_map _\n  rw [hl,names_length] at htw\n  unfold acquire\n  dsimp only\n  rw [SemiprimePaidPackingSnapshot.acquire_blocks P producer hp]\n  unfold budget\n  omega\n\nomit [DecidableEq I] in\n/-- A minimum scan capped by the incidence count cannot create extra blocks. -/\ntheorem blocks_le (P : PackingData I (UniversalType r Q 1)) :\n    P.blockCount≤P.vertices.values.length := by\n  have h (keys : List (UniversalType r Q 1)) : P.minCount keys≤P.vertices.values.length := by\n    induction keys with\n    | nil => rfl\n    | cons u us ih => exact (min_le_right _ _).trans ih\n  exact h P.types.values\n\n/-- A literal polynomial envelope for universal numerator setup. -/\ndef universalPolynomial (A R Q D : ℕ) : ℕ :=\n  Q*(D*(D*(D*entryPolynomial Q R+2)+3)+3)+1+\n    (A*(R+1)+A+R+R^2)+(2*A*(R+1)+R^2)+1\n\n/-- A literal fixed polynomial after the actual universal alphabet pays subset expansion. -/\ndef polynomial (A R M n D B Q r : ℕ) : ℕ :=\n  SemiprimeMaterializedSourceAcquisition.packingBudget M D Q B+1+\n  universalPolynomial A R Q D+2*R+4+\n  (10*(M+1)^2*(D+1)+3*M+M*D+3)+\n  tableBudget M n D M B Q r (M*D+M)+n+r+Q+4\n\ntheorem budget_polynomial (A R M n D B Q r blocks : ℕ)\n    (hD : 2^(2*Q)≤D) (hb : blocks≤M) :\n    budget A R M n D B Q r blocks≤polynomial A R M n D B Q r := by\n  have he := entryBudget_polynomial Q R D hD\n  unfold budget polynomial universalPolynomial SemiprimeMaterializedSourceUniversal.tableBudget tableBudget\n  gcongr\n\n/-- Native r≥2 closes the universal-expansion and block-count premises internally. -/\ntheorem acquire_work_native (P : PackingData I (UniversalType r Q 1)) (hr : 2≤r)\n    (A R : ℕ) (owner : I → Fin n) (producer : I → Run (UniversalType r Q 1))\n    (hp : ∀ i, (producer i).value=P.label i) (B : ℕ) (hw : ∀ i, (producer i).work≤B) :\n    (acquire A R P.vertices.values owner P.types.values producer).work≤\n      polynomial A R P.vertices.values.length n P.types.values.length B Q r := by\n  apply (acquire_work P A R owner producer hp B hw).trans\n  apply budget_polynomial\n  · rw [P.types.length_eq_card,card_universalType]\n    have h : 2^(2*Q)≤r^(2*Q) := Nat.pow_le_pow_left hr _\n    simpa only [show Q*(1+1)=2*Q by omega] using h\n  · exact blocks_le P\n\nend RiemannGaussian.SemiprimePaidConstraintAcquisition\n","RiemannGaussian.SemiprimePaidConstraintCache":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeMaterializedSourceCache\nimport RiemannGaussian.SemiprimeSourceConstraintAcquisition\n\n/-! # Paid cached universal integer constraints\nThe numerator family is acquired by the existing actual parity/difference\nprogram. Each later constraint reads that finite family by executed list scans.\nThe report counts scalar/register/list work; physical bit refinement is separate.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1600000\nnamespace RiemannGaussian.SemiprimePaidConstraintCache\nopen OAI.Algorithms.SubexponentialSAT\nopen MulticolorTypes SqrtLog\nopen SemiprimeMaterializedSourceUniversal\nvariable {r Q : ℕ}\n\n/-- Actual finite list access, including all visited cells. -/\ndef getRun {α : Type*} : List α → ℕ → Run (Option α)\n  | [], _ => ⟨none,1⟩\n  | a::_, 0 => ⟨some a,2⟩\n  | _::as, k+1 => let tail := getRun as k; ⟨tail.value,tail.work+2⟩\n\ntheorem getRun_value {α : Type*} (xs : List α) (k : ℕ) :\n    (getRun xs k).value=xs[k]? := by\n  induction xs generalizing k with\n  | nil => simp [getRun]\n  | cons a as ih => cases k <;> simp [getRun,ih]\n\ntheorem getRun_work {α : Type*} (xs : List α) (k : ℕ) :\n    (getRun xs k).work≤2*xs.length+1 := by\n  induction xs generalizing k with\n  | nil => simp [getRun]\n  | cons a as ih =>\n      cases k with\n      | zero => simp only [getRun,List.length_cons]; omega\n      | succ k =>\n          have ht := ih k\n          simp only [getRun,List.length_cons]\n          omega\n\n/-- Read one stored original universal numerator with two keyed scans. -/\ndef numerator (keys : List (UniversalType r Q 1)) (cache : List (List (List ℤ)))\n    (t : Fin Q) (u y : UniversalType r Q 1) : Run ℤ :=\n  let node := getRun cache t.val\n  let row := SemiprimeMaterializedSourceCache.lookup u keys (node.value.getD [])\n  let entry := SemiprimeMaterializedSourceCache.lookup y keys (row.value.getD [])\n  ⟨entry.value.getD 0,node.work+row.work+entry.work+3⟩\n\n/-- Actual cached acquisition, not an externally supplied numerator function. -/\ntheorem numerator_value (A R : ℕ) (keys : List (UniversalType r Q 1))\n    (complete : ∀ u, u∈keys) (t : Fin Q) (u y : UniversalType r Q 1) :\n    (numerator keys (table A R keys).value t u y).value=LayoutNumerator.entry 0 t A R u y := by\n  unfold numerator\n  dsimp only\n  rw [getRun_value,table_value]\n  have ht : (List.finRange Q)[t.val]?=some t := by\n    rw [List.getElem?_eq_getElem (by simp),List.getElem_finRange]\n    congr 1\n  simp only [List.getElem?_map,ht,Option.map_some,Option.getD_some]\n  rw [SemiprimeMaterializedSourceCache.lookup_map u keys _ (complete u)]\n  simp only [Option.getD_some]\n  rw [SemiprimeMaterializedSourceCache.lookup_map y keys _ (complete y)]\n  rfl\n\ntheorem numerator_work (keys : List (UniversalType r Q 1)) (cache : List (List (List ℤ)))\n    (t : Fin Q) (u y : UniversalType r Q 1) :\n    (numerator keys cache t u y).work≤2*cache.length+2*(keys.length*(7*Q+4)+1)+4 := by\n  have hn := getRun_work cache t.val\n  have hr := SemiprimeMaterializedSourceCache.lookup_work u keys\n    ((getRun cache t.val).value.getD [])\n  have he := SemiprimeMaterializedSourceCache.lookup_work y keys\n    ((SemiprimeMaterializedSourceCache.lookup u keys ((getRun cache t.val).value.getD [])).value.getD [])\n  unfold numerator\n  dsimp only\n  omega\n\n/-- A cleared-defect entry; all head tests and complete equality comparisons execute. -/\ndef constraint (denominator : ℤ) (keys : List (UniversalType r Q 1))\n    (cache : List (List (List ℤ))) (t : Fin Q) (g : Fin r)\n    (u y : UniversalType r Q 1) : Run ℤ :=\n  if u.head t=g ∧ u.slot 0 t≠g then\n    if y.head t=g ∧ y.slot 0 t≠g then\n      let entry := numerator keys cache t u y\n      let eq := SemiprimeMaterializedSourceCache.same u y\n      ⟨(if eq.value then denominator else 0)-entry.value,entry.work+eq.work+11⟩\n    else ⟨0,8⟩\n  else ⟨0,4⟩\n\n/-- Exactly the original padded constraint, including every zero-padding branch. -/\ntheorem constraint_value (A R : ℕ) (keys : List (UniversalType r Q 1))\n    (complete : ∀ u, u∈keys) (t : Fin Q) (g : Fin r) (u y : UniversalType r Q 1) :\n    (constraint ((powerTwo (R-1)).value) keys (table A R keys).value t g u y).value=\n      SemiprimeUniversalSourceExecution.constraint A R t g u y := by\n  unfold constraint SemiprimeUniversalSourceExecution.constraint\n  split_ifs <;> simp_all only [numerator_value A R keys complete,\n    SemiprimeMaterializedSourceCache.same_correct,powerTwo_value,\n    SemiprimeUniversalSourceExecution.numerator_eq,ite_true,ite_false]\n\ntheorem constraint_work (denominator : ℤ) (keys : List (UniversalType r Q 1))\n    (cache : List (List (List ℤ))) (t : Fin Q) (g : Fin r)\n    (u y : UniversalType r Q 1) :\n    (constraint denominator keys cache t g u y).work≤\n      2*cache.length+2*(keys.length*(7*Q+4)+1)+7*Q+16 := by\n  have hn := numerator_work keys cache t u y\n  have he := SemiprimeMaterializedSourceCache.same_work u y\n  unfold constraint\n  split_ifs <;> dsimp only <;> omega\n\n/-- Immutable integer numerator table and its acquired denominator. -/\nstructure Cache where\n  /-- Original universal alphabet in its source order. -/\n  keys : List (UniversalType r Q 1)\n  /-- One acquired Q-by-D-by-D numerator family. -/\n  entries : List (List (List ℤ))\n  /-- Acquired power of two used to clear the universal defect. -/\n  denominator : ℤ\n\n/-- Acquire all universal numerator data once, before any original-coordinate scans. -/\ndef acquire (A R : ℕ) (keys : List (UniversalType r Q 1)) : Run (Cache (r:=r) (Q:=Q)) :=\n  let entries := table A R keys\n  let denominator := powerTwo (R-1)\n  ⟨⟨keys,entries.value,denominator.value⟩,entries.work+denominator.work+3⟩\n\n/-- Runtime read from the actual acquired universal integer data. -/\ndef read (cache : Cache (r:=r) (Q:=Q)) (t : Fin Q) (g : Fin r)\n    (u y : UniversalType r Q 1) : Run ℤ :=\n  constraint cache.denominator cache.keys cache.entries t g u y\n\ntheorem read_acquire (A R : ℕ) (keys : List (UniversalType r Q 1))\n    (complete : ∀ u, u∈keys) (t : Fin Q) (g : Fin r) (u y : UniversalType r Q 1) :\n    (read (acquire A R keys).value t g u y).value=\n      SemiprimeUniversalSourceExecution.constraint A R t g u y :=\n  constraint_value A R keys complete t g u y\n\ntheorem acquire_work (A R : ℕ) (keys : List (UniversalType r Q 1)) :\n    (acquire A R keys).work≤tableBudget A R Q keys.length+2*R+4 := by\n  have ht := table_work A R keys\n  unfold acquire\n  dsimp only\n  rw [powerTwo_work]\n  omega\n\ntheorem read_acquire_work (A R : ℕ) (keys : List (UniversalType r Q 1))\n    (t : Fin Q) (g : Fin r) (u y : UniversalType r Q 1) :\n    (read (acquire A R keys).value t g u y).work≤\n      9*Q+2*(keys.length*(7*Q+4)+1)+16 := by\n  have h := constraint_work (powerTwo (R-1)).value keys (table A R keys).value t g u y\n  have hl : (table A R keys).value.length=Q := by\n    rw [table_value,List.length_map,List.length_finRange]\n  rw [hl] at h\n  change (constraint (powerTwo (R-1)).value keys (table A R keys).value t g u y).work≤_\n  omega\n\nend RiemannGaussian.SemiprimePaidConstraintCache\n","RiemannGaussian.SemiprimePaidFactorDecoder":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimePaidPrefixController\nimport RiemannGaussian.SemiprimePublicAcquiredExecution\nimport RiemannGaussian.SemiprimeMaterializedSourceWords\n\n/-!\n# Reported input-bit reconstruction\n\nEvery selected-label lookup, original wire-index lookup, binary accumulation,\npower multiplication and digit sum executes a finite loop. Public enumeration\nconstruction and primitive word addressing retain their separate acquisition/\nbit-refinement interfaces; the edge list is cached before its repeated scans.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1600000\nnamespace RiemannGaussian.SemiprimePaidFactorDecoder\nopen scoped BigOperators\nopen SemiprimePaidPrefixController SemiprimePublicAcquiredExecution SemiprimeMacroParameters\nopen OAI.Algorithms.SubexponentialSAT.Subexp.ConstructivePacking\n\n/-- Actual selected-bit list scan, correctly handling even repeated false labels. -/\ndef selectedBit {I : Type*} [DecidableEq I] (i : I) : List (I × Bool) → Run Bool\n  | [] => ⟨false,1⟩\n  | p::ps => if decide (p.1=i) && p.2 then ⟨true,4⟩ else\n    let rest := selectedBit i ps\n    ⟨rest.value,rest.work+4⟩\n\n/-- Literal selected-bit decoder used by the original public algorithm. -/\ntheorem selectedBit_value {I : Type*} [DecidableEq I] (i : I) (values : List (I × Bool)) :\n    (selectedBit i values).value=values.any (fun p => decide (p.1=i) && p.2) := by\n  induction values with\n  | nil => rfl\n  | cons p ps ih => by_cases h : p.1=i ∧ p.2=true <;> simp [selectedBit,List.any_cons,h,ih]\n\n/-- Every selected-label comparison and list step is paid. -/\ntheorem selectedBit_work {I : Type*} [DecidableEq I] (i : I) (values : List (I × Bool)) :\n    (selectedBit i values).work≤4*values.length+1 := by\n  induction values with\n  | nil => simp [selectedBit]\n  | cons p ps ih => by_cases h : p.1=i ∧ p.2=true <;>\n      simp [selectedBit,h,List.length_cons] <;> omega\n\n/-- Actual original physical wire carried by an input digit coordinate. -/\ndef inputWire (N : ℕ) (side : Fin 2) (i : ℕ)\n    (hi : i< firstAxis (bitLength N)*secondAxis (bitLength N))\n    (bit : Fin (firstAxis (bitLength N)*secondAxis (bitLength N)+1)) : PublicEdge N :=\n  ((.inl (.input side ⟨i,hi⟩,bit)),false)\n\n/-- Scan an already acquired public edge list to obtain the physical wire index. -/\ndef inputIndex (N : ℕ) (edges : FiniteEnumeration (PublicEdge N)) (side : Fin 2) (i : ℕ)\n    (hi : i< firstAxis (bitLength N)*secondAxis (bitLength N))\n    (bit : Fin (firstAxis (bitLength N)*secondAxis (bitLength N)+1)) : Run ℕ :=\n  let found := SemiprimeMaterializedSourceWords.indexRun (inputWire N side i hi bit) edges.values\n  ⟨found.value,found.work+1⟩\n\n/-- The reported index scan is exactly the original finite-enumeration inverse. -/\ntheorem inputIndex_value (N : ℕ) (edges : FiniteEnumeration (PublicEdge N)) (side : Fin 2) (i : ℕ)\n    (hi : i< firstAxis (bitLength N)*secondAxis (bitLength N))\n    (bit : Fin (firstAxis (bitLength N)*secondAxis (bitLength N)+1)) :\n    (inputIndex N edges side i hi bit).value=\n      OAI.Algorithms.SubexponentialSAT.LocalExpectation.indexCode edges.values (inputWire N side i hi bit) :=\n  SemiprimeMaterializedSourceWords.indexRun_value _ _\n\n/-- Finite physical index lookup has its actual linear scan bound. -/\ntheorem inputIndex_work (N : ℕ) (edges : FiniteEnumeration (PublicEdge N)) (side : Fin 2) (i : ℕ)\n    (hi : i< firstAxis (bitLength N)*secondAxis (bitLength N))\n    (bit : Fin (firstAxis (bitLength N)*secondAxis (bitLength N)+1)) :\n    (inputIndex N edges side i hi bit).work≤2*edges.values.length+3 := by\n  have h := SemiprimeMaterializedSourceWords.indexRun_work (inputWire N side i hi bit) edges.values\n  change (SemiprimeMaterializedSourceWords.indexRun (inputWire N side i hi bit) edges.values).work+1≤_\n  omega\n\n/-- Execute physical index lookup and a literal natural-index selected-label scan. -/\ndef inputBit (N : ℕ) (side : Fin 2) (values : List (Fin (wireCount N) × Bool)) (i : ℕ)\n    (hi : i< firstAxis (bitLength N)*secondAxis (bitLength N))\n    (bit : Fin (firstAxis (bitLength N)*secondAxis (bitLength N)+1))\n    (edges : FiniteEnumeration (PublicEdge N)) : Run Bool :=\n  let index := inputIndex N edges side i hi bit\n  let labels := values.map (fun p => (p.1.val,p.2))\n  let result := selectedBit index.value labels\n  ⟨result.value,index.work+result.work+2*values.length+2⟩\n\n/-- Actual selected input bit, with the original physical indexing convention. -/\ntheorem inputBit_value (N : ℕ) (side : Fin 2) (values : List (Fin (wireCount N) × Bool)) (i : ℕ)\n    (hi : i< firstAxis (bitLength N)*secondAxis (bitLength N))\n    (bit : Fin (firstAxis (bitLength N)*secondAxis (bitLength N)+1))\n    (edges : FiniteEnumeration (PublicEdge N)) (he : edges=edgeEnumeration N) :\n    (inputBit N side values i hi bit edges).value=\n      SemiprimeAcquiredPrefixSearch.selectedBits values\n        ((edgeEnumeration N).equivFin.symm (inputWire N side i hi bit)) := by\n  subst edges\n  simp only [inputBit,inputIndex_value,selectedBit_value,List.any_map,Function.comp_def,\n    SemiprimeAcquiredPrefixSearch.selectedBits]\n  apply congrArg (fun f : (Fin (wireCount N) × Bool) → Bool => values.any f)\n  funext p\n  let idx : Fin (wireCount N) := (edgeEnumeration N).equivFin.symm (inputWire N side i hi bit)\n  change (decide (p.1.val=idx.val) && p.2)=(decide (p.1=idx) && p.2)\n  apply congrArg (fun b : Bool => b && p.2)\n  apply Bool.eq_iff_iff.mpr\n  simp only [decide_eq_true_eq]\n  exact Fin.ext_iff.symm\n\n/-- Work of each actual physical input-bit request, including the copied index list. -/\ntheorem inputBit_work (N : ℕ) (side : Fin 2) (values : List (Fin (wireCount N) × Bool)) (i : ℕ)\n    (hi : i< firstAxis (bitLength N)*secondAxis (bitLength N))\n    (bit : Fin (firstAxis (bitLength N)*secondAxis (bitLength N)+1))\n    (edges : FiniteEnumeration (PublicEdge N)) (he : edges=edgeEnumeration N) :\n    (inputBit N side values i hi bit edges).work≤2*wireCount N+6*values.length+6 := by\n  have hx := inputIndex_work N edges side i hi bit\n  have hb := selectedBit_work (inputIndex N edges side i hi bit).value\n    (values.map (fun p => (p.1.val,p.2)))\n  simp only [List.length_map] at hb\n  have hl : edges.values.length=wireCount N := congrArg (fun e => e.values.length) he\n  change (inputIndex N edges side i hi bit).work+_+2*values.length+2≤_\n  rw [hl] at hx\n  omega\n\n/-- Execute little-endian binary accumulation, retaining all actual bit reports. -/\ndef binary : (width : ℕ) → (Fin width → Run Bool) → Run ℕ\n  | 0, _ => ⟨0,1⟩\n  | width+1, get =>\n    let bit := get 0\n    let tail := binary width (fun i => get i.succ)\n    ⟨2*tail.value+bit.value.toNat,bit.work+tail.work+3⟩\n\n/-- Exact agreement with the original physical binary decoder. -/\ntheorem binary_value (width : ℕ) (get : Fin width → Run Bool) :\n    (binary width get).value=SemiprimeMacroEntryExecution.binaryDecode (fun i => (get i).value) := by\n  induction width with\n  | zero => rfl\n  | succ width ih =>\n    rw [SemiprimeMacroEntryExecution.binaryDecode,Nat.ofBits_succ]\n    simp only [binary,ih,SemiprimeMacroEntryExecution.binaryDecode]\n    rfl\n\n/-- Every actual bit callback, multiply/add and branch is retained. -/\ntheorem binary_work (width B : ℕ) (get : Fin width → Run Bool) (hb : ∀ i, (get i).work≤ B) :\n    (binary width get).work≤ width*(B+3)+1 := by\n  induction width with\n  | zero => simp [binary]\n  | succ width ih =>\n    have ht := ih (fun i => get i.succ) (fun i => hb i.succ)\n    have hh := hb 0\n    simp only [binary]\n    nlinarith\n\n/-- Actual scalar power construction, with multiplication and loop reports. -/\ndef power (base : ℕ) : ℕ → Run ℕ\n  | 0 => ⟨1,1⟩\n  | k+1 => let old := power base k; ⟨old.value*base,old.work+2⟩\n\ntheorem power_value (base k : ℕ) : (power base k).value=base^k := by\n  induction k with\n  | zero => rfl\n  | succ k ih => simp only [power,ih,pow_succ]\n\ntheorem power_work (base k : ℕ) : (power base k).work=2*k+1 := by\n  induction k with\n  | zero => rfl\n  | succ k ih => simp only [power,ih]; omega\n\n/-- Actual finite sum of already reported digit computations. -/\ndef sumRun {A : Type*} (f : A → Run ℕ) : List A → Run ℕ\n  | [] => ⟨0,1⟩\n  | a::as => let v := f a; let tail := sumRun f as\n            ⟨v.value+tail.value,v.work+tail.work+3⟩\n\ntheorem sumRun_value {A : Type*} (f : A → Run ℕ) (xs : List A) :\n    (sumRun f xs).value=(xs.map (fun a => (f a).value)).sum := by\n  induction xs with\n  | nil => rfl\n  | cons a as ih => simp only [sumRun,List.map_cons,List.sum_cons,ih]\n\ntheorem sumRun_work {A : Type*} (f : A → Run ℕ) (xs : List A) (B : ℕ)\n    (hb : ∀ a ∈ xs, (f a).work≤ B) : (sumRun f xs).work≤ xs.length*(B+3)+1 := by\n  induction xs with\n  | nil => simp [sumRun]\n  | cons a as ih =>\n    have ha := hb a (by simp)\n    have ht := ih (fun b hb' => hb b (by simp [hb']))\n    simp only [sumRun,List.length_cons]\n    nlinarith\n\n/-- One real physical input digit, including its radix power and accumulation. -/\ndef digit (N base : ℕ) (side : Fin 2) (values : List (Fin (wireCount N) × Bool)) (i : ℕ)\n    (edges : FiniteEnumeration (PublicEdge N)) : Run ℕ :=\n  if hi : i< firstAxis (bitLength N)*secondAxis (bitLength N) then\n    let bits := binary (firstAxis (bitLength N)*secondAxis (bitLength N)+1)\n      (fun bit => inputBit N side values i hi bit edges)\n    let place := power base i\n    ⟨bits.value*place.value,bits.work+place.work+3⟩\n  else ⟨0,2⟩\n\n/-- One digit computes the same little-endian summand as the original decoder. -/\ntheorem digit_value (N base : ℕ) (side : Fin 2) (values : List (Fin (wireCount N) × Bool)) (i : ℕ)\n    (edges : FiniteEnumeration (PublicEdge N)) (he : edges=edgeEnumeration N) :\n    (digit N base side values i edges).value=\n      (if hi : i< firstAxis (bitLength N)*secondAxis (bitLength N) then\n        SemiprimeMacroEntryExecution.binaryDecode (fun bit =>\n          SemiprimeAcquiredPrefixSearch.selectedBits values\n            ((edgeEnumeration N).equivFin.symm (inputWire N side i hi bit))) else 0)*base^i := by\n  unfold digit\n  by_cases hi : i< firstAxis (bitLength N)*secondAxis (bitLength N)\n  · have hb (bit : Fin (firstAxis (bitLength N)*secondAxis (bitLength N)+1)) :=\n      inputBit_value N side values i hi bit edges he\n    simp only [dite_eq_left hi,binary_value,power_value,hb]\n  · simp only [dite_eq_right hi,Nat.zero_mul]\n\n/-- Fully computed operand, caching the original public edge list and radix once. -/\ndef decode (N : ℕ) (values : List (Fin (wireCount N) × Bool)) (side : Fin 2) : Run ℕ :=\n  let edges := edgeEnumeration N\n  let base := power 2 (radixBits (bitLength N))\n  let indices := finIndices (digitCount (bitLength N))\n  let result := sumRun (fun i : Fin (digitCount (bitLength N)) =>\n    digit N base.value side values i.val edges) indices.value\n  ⟨result.value,base.work+result.work+indices.work+1⟩\n\n/-- Exact original physical little-endian operand, not a semantic normalizer oracle. -/\ntheorem decode_value (N : ℕ) (values : List (Fin (wireCount N) × Bool)) (side : Fin 2) :\n    (decode N values side).value=decodeOperand N values side := by\n  let f : ℕ → ℕ := fun i =>\n    (if hi : i< firstAxis (bitLength N)*secondAxis (bitLength N) then\n      SemiprimeMacroEntryExecution.binaryDecode (fun bit =>\n        SemiprimeAcquiredPrefixSearch.selectedBits values\n          ((edgeEnumeration N).equivFin.symm (inputWire N side i hi bit))) else 0)*\n      (2^radixBits (bitLength N))^i\n  calc\n    (decode N values side).value = ∑ i : Fin (digitCount (bitLength N)), f i.val := by\n      simp only [decode,finIndices_value,sumRun_value,digit_value _ _ _ _ _ _ rfl,power_value,\n        ← List.ofFn_eq_map,List.sum_ofFn]\n      rfl\n    _ = ∑ i ∈ Finset.range (digitCount (bitLength N)), f i := Fin.sum_univ_eq_sum_range f _\n    _ = decodeOperand N values side := rfl\n\n/-- Uniform selected-operation operand reconstruction budget. -/\ndef budget (N v : ℕ) : ℕ :=\n  digitCount (bitLength N)*((firstAxis (bitLength N)*secondAxis (bitLength N)+1)*\n    (2*wireCount N+6*v+9)+2*digitCount (bitLength N)+8)+2*radixBits (bitLength N)+3*(digitCount (bitLength N)+1)^2+3\n\n/-- Every actual index/selected-bit read and integer digit operation is charged. -/\ntheorem decode_work (N : ℕ) (values : List (Fin (wireCount N) × Bool)) (side : Fin 2) :\n    (decode N values side).work≤ budget N values.length := by\n  have hd (i : Fin (digitCount (bitLength N))) :\n      (digit N (power 2 (radixBits (bitLength N))).value side values i.val (edgeEnumeration N)).work≤\n        (firstAxis (bitLength N)*secondAxis (bitLength N)+1)*(2*wireCount N+6*values.length+9)+\n          2*digitCount (bitLength N)+5 := by\n    unfold digit\n    split\n    · rename_i hi\n      have hb := binary_work (firstAxis (bitLength N)*secondAxis (bitLength N)+1)\n        (2*wireCount N+6*values.length+6) _ (fun bit => inputBit_work N side values i.val hi bit _ rfl)\n      simp only [power_work]\n      have he : 2*wireCount N+6*values.length+6+3=2*wireCount N+6*values.length+9 := by omega\n      rw [he] at hb\n      have hi' := i.isLt\n      omega\n    · change 2≤_\n      omega\n  have hs := sumRun_work (fun i : Fin (digitCount (bitLength N)) =>\n    digit N (power 2 (radixBits (bitLength N))).value side values i.val (edgeEnumeration N))\n    (List.finRange (digitCount (bitLength N))) _ (fun i _ => hd i)\n  simp only [List.length_finRange] at hs\n  have ha := finIndices_work (digitCount (bitLength N))\n  simp only [decode,finIndices_value,power_work,budget]\n  have he : (firstAxis (bitLength N)*secondAxis (bitLength N)+1)*(2*wireCount N+6*values.length+9)+\n      2*digitCount (bitLength N)+5+3 =\n      (firstAxis (bitLength N)*secondAxis (bitLength N)+1)*(2*wireCount N+6*values.length+9)+\n      2*digitCount (bitLength N)+8 := by omega\n  rw [he] at hs\n  omega\n\nend RiemannGaussian.SemiprimePaidFactorDecoder\n","RiemannGaussian.SemiprimePublicConstructedCount":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeScheduledCounter\nimport RiemannGaussian.SemiprimePublicFactorCount\n\n/-!\n# The constructed public counter counts ordinary factors\n\nThis joins the actual scheduled row construction and ordered Boolean tables to\nthe whole-family factor-count theorem. It is a semantic composition theorem;\nexecution of the finite choices and the full primitive-bit bound are separate.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1600000\nnoncomputable section\nnamespace RiemannGaussian.SemiprimePublicConstructedCount\nopen scoped BigOperators\nopen SemiprimeMacroGraph SemiprimeMacroGraphSemantics SemiprimeMacroGraphExtension\nopen SemiprimeMacroParameters SemiprimePublicFactorCount\nopen SemiprimeScheduledCounter SemiprimeSourceLayoutRate\nopen SemiprimeCounterSearch SemiprimeCountRecovery SemiprimeConstructedCounter\nattribute [local instance] Classical.propDecidable\n\n/-- Reindexing the counter's finite sets as literal Boolean wire assignments. -/\ndef assignmentEquiv (A : Type) [Fintype A] [DecidableEq A] :\n    Finset A ≃ (A → Bool) where\n  toFun := assignmentBit\n  invFun f := Finset.univ.filter (fun a => f a = true)\n  left_inv x := by ext a; simp [assignmentBit]\n  right_inv f := by funext a; simp [assignmentBit]\n\n/-- The local-conjunction counter is the literal zero/one tensor contraction. -/\ntheorem accepted_eq_tensor {A E : Type} [Fintype A] [DecidableEq A] [Fintype E]\n    (arity : E → ℕ) (table : (e : E) → (Fin (arity e) → Bool) → Bool)\n    (coordinate : (e : E) → Fin (arity e) → A) :\n    acceptedCount (originalPredicate arity table coordinate) =\n      ∑ assignment : A → Bool, ∏ e : E,\n        if table e (fun i => assignment (coordinate e i)) then (1 : ℕ) else 0 := by\n  unfold acceptedCount\n  apply Fintype.sum_equiv (assignmentEquiv A)\n  intro x\n  rw [boolean_product_indicator]\n  simp only [originalPredicate, assignmentEquiv, Equiv.coe_fn_mk, decide_eq_true_eq]\n  rfl\n\n/-- The constructed counter's empty restriction is a literal tensor sum. -/\ntheorem constructed_empty_count {A E : Type} [Fintype A] [DecidableEq A]\n    [Fintype E] [DecidableEq E] {arity : E → ℕ}\n    {coordinate : (e : E) → Fin (arity e) → A}\n    (table : (e : E) → (Fin (arity e) → Bool) → Bool)\n    (coverage : ∀ a, ∃ e i, coordinate e i = a) (p : Parameters arity coordinate) :\n    prefixCount (problem table coverage p) [] =\n      ∑ assignment : A → Bool, ∏ e : E,\n        if table e (fun i => assignment (coordinate e i)) then (1 : ℕ) else 0 := by\n  rw [constructed_prefix_count]\n  have he : restricted assignmentBit (originalPredicate arity table coordinate) [] =\n      originalPredicate arity table coordinate := by\n    funext x\n    simp only [restricted, List.all_nil, Bool.and_true]\n  rw [he]\n  exact accepted_eq_tensor arity table coordinate\n\n/-- Coverage is derived from the actual two occurrences of every public bit. -/\ntheorem public_coverage {L : ℕ} (hL : 0 < L)\n    (a : Edge (firstAxis L) (secondAxis L) (digitCount L)) :\n    ∃ v i, publicCoordinate hL v i = a := by\n  by_contra h\n  have hn : ∀ v i, publicCoordinate hL v i ≠ a := by simpa using h\n  have hc := ordered_edge_occurrence_two (digitCount_bounds hL).1\n    (public_digit_capacity hL) a\n  have hz : (∑ v : SubdividedVertex (firstAxis L) (secondAxis L) (digitCount L),\n      ∑ i : Fin (subdividedArity v),\n        if publicCoordinate hL v i = a then (1 : ℕ) else 0) = 0 := by simp [hn]\n  change (∑ v : SubdividedVertex (firstAxis L) (secondAxis L) (digitCount L),\n    ∑ i : Fin (subdividedArity v),\n      if publicCoordinate hL v i = a then (1 : ℕ) else 0) = 2 at hc\n  omega\n\n/-- The actual public row-construction counter; no supplied replacement rows. -/\ndef publicProblem (N : ℕ) (hN : 0 < N)\n    (hg : sourceLayoutGuard (variableCount (bitLength N)) (scopeBound (bitLength N))) :\n    Problem (Edge (firstAxis (bitLength N)) (secondAxis (bitLength N)) (digitCount (bitLength N)))\n      (SubdividedVertex (firstAxis (bitLength N)) (secondAxis (bitLength N)) (digitCount (bitLength N))) :=\n  problem (subdividedTable (publicConfig N hN))\n    (public_coverage (bitLength_pos hN)) (publicParameters (bitLength_pos hN) hg)\n\n/-- Every restricted query is exactly the count of original accepting assignments\nwith those fixed wire bits. Inconsistent restrictions correctly have count zero. -/\ntheorem public_prefix_count (N : ℕ) (hN : 0 < N)\n    (hg : sourceLayoutGuard (variableCount (bitLength N)) (scopeBound (bitLength N)))\n    (fixed : List (Edge (firstAxis (bitLength N)) (secondAxis (bitLength N))\n      (digitCount (bitLength N)) × Bool)) :\n    prefixCount (publicProblem N hN hg) fixed =\n      acceptedCount (restricted assignmentBit\n        (originalPredicate subdividedArity (subdividedTable (publicConfig N hN))\n          (publicCoordinate (bitLength_pos hN))) fixed) :=\n  constructed_prefix_count _ _ _ fixed\n\n/-- The completely constructed public count equals the ordinary ordered proper\nfactor-pair cardinal for every positive integer meeting the executable layout guard. -/\ntheorem public_constructed_factor_count (N : ℕ) (hN : 0 < N)\n    (hg : sourceLayoutGuard (variableCount (bitLength N)) (scopeBound (bitLength N))) :\n    prefixCount (publicProblem N hN hg) [] = Fintype.card (OrdinaryFactors N) := by\n  exact (constructed_empty_count (subdividedTable (publicConfig N hN))\n    (public_coverage (bitLength_pos hN)) (publicParameters (bitLength_pos hN) hg)).trans\n      (public_tensor_factor_count N hN)\n\n/-- Public constructed counting detects a proper factor exactly, including squares. -/\ntheorem public_constructed_positive_iff (N : ℕ) (hN : 0 < N)\n    (hg : sourceLayoutGuard (variableCount (bitLength N)) (scopeBound (bitLength N))) :\n    0 < prefixCount (publicProblem N hN hg) [] ↔ Nonempty (OrdinaryFactors N) := by\n  rw [public_constructed_factor_count, Fintype.card_pos_iff]\n\n/-- No additional counter calls are introduced by the public-graph composition. -/\ntheorem public_search_queries (N : ℕ) (hN : 0 < N)\n    (hg : sourceLayoutGuard (variableCount (bitLength N)) (scopeBound (bitLength N)))\n    (indices : List (Edge (firstAxis (bitLength N)) (secondAxis (bitLength N))\n      (digitCount (bitLength N)))) :\n    (counterSearch (publicProblem N hN hg) indices).queries ≤ indices.length + 1 :=\n  counterSearch_queries_le _ _\n\nend RiemannGaussian.SemiprimePublicConstructedCount\n","RiemannGaussian.SemiprimeQuotientCentering":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeQuotientRows\n\n/-!\n# Target-preserving public centering of quotient rows\n\nThe original quadratic is retained alongside its public integer shift.\nThe RH-path unit-phase identity preserves the complete residual GCD.\nBalanced factor boxes provide a shorter common index interval, without a\nhidden-factor input or a baby/giant matrix. This is a construction and\ncoverage theorem, not a one-sixth factoring or bit-complexity theorem.\n-/\n\nnamespace RiemannGaussian.SemiprimeQuotientCentering\n\nopen SemiprimeQuotientRows\n\n/-- Shift along the trivial linear direction, keeping the original row\navailable separately. The Euclidean coordinates and division count survive. -/\ndef shiftRow (m j : ℕ) (k : ℤ) (z : QuotientRow) : QuotientRow :=\n  { z with b := z.b-k*m, c := z.c-k*j }\n\n/-- The public shift preserves the exact quotient class. -/\ntheorem shiftRow_relation {N m j : ℕ} {z : QuotientRow}\n    (hz : quotientRelation N m j z.a z.b z.c z.t) (k : ℤ) :\n    quotientRelation N m j (shiftRow m j k z).a (shiftRow m j k z).b\n      (shiftRow m j k z).c (shiftRow m j k z).t := by\n  simpa only [shiftRow, neg_mul, sub_eq_add_neg] using quotientRelation_shift hz (-k)\n\n/-- The full polynomial loses precisely k copies of the trivial linear\nrow; the quadratic leading coordinate is retained. -/\ntheorem shiftRow_quadratic (m j : ℕ) (k x : ℤ) (z : QuotientRow) :\n    quadratic (shiftRow m j k z).a (shiftRow m j k z).b (shiftRow m j k z).c x=\n      quadratic z.a z.b z.c x-k*((m : ℤ)*x+j) := by\n  simp only [shiftRow,quadratic]\n  ring\n\n/-- The giant exponent and collision index have the same public shift. -/\ntheorem shiftRow_giant (m j : ℕ) (k : ℤ) (z : QuotientRow) :\n    giantExponent m j (shiftRow m j k z).a (shiftRow m j k z).b (shiftRow m j k z).c=\n      giantExponent m j z.a z.b z.c-k*(m : ℤ)^2 := by\n  simp only [shiftRow,giantExponent]\n  ring\n\n/-- The candidate recovery polynomial is unchanged when its retained\nindex is transported with the row. No collision channel is discarded. -/\ntheorem shiftRow_recovery (N m j : ℕ) (k i : ℤ) (z : QuotientRow) :\n    integerRoots (shiftRow m j k z).a\n        ((shiftRow m j k z).b*m-2*(shiftRow m j k z).a*j-(m : ℤ)^2*(i-k))\n        ((shiftRow m j k z).t*N)=\n      integerRoots z.a (z.b*m-2*z.a*j-(m : ℤ)^2*i) (z.t*N) := by\n  simp only [shiftRow]\n  congr 1\n  ring\n\n/-- A center phase factors from the ORIGINAL difference only when the\nbaby target is shifted too. This identity works over every public ring. -/\ntheorem shiftRow_residual {R : Type*} [CommRing R] (g : Rˣ)\n    (m j : ℕ) (k i : ℤ) (z : QuotientRow) :\n    ((g^giantExponent m j (shiftRow m j k z).a (shiftRow m j k z).b\n        (shiftRow m j k z).c : Rˣ) : R)-((g^((m : ℤ)^2*(i-k)) : Rˣ) : R)=\n      ((g^(-k*(m : ℤ)^2) : Rˣ) : R)*\n        (((g^giantExponent m j z.a z.b z.c : Rˣ) : R)-\n          ((g^((m : ℤ)^2*i) : Rˣ) : R)) := by\n  rw [shiftRow_giant]\n  have h₁ : giantExponent m j z.a z.b z.c-k*(m : ℤ)^2=\n      -k*(m : ℤ)^2+giantExponent m j z.a z.b z.c := by ring\n  have h₂ : (m : ℤ)^2*(i-k)=-k*(m : ℤ)^2+(m : ℤ)^2*i := by ring\n  rw [h₁,h₂,zpow_add,zpow_add,Units.val_mul,Units.val_mul,mul_sub]\n\n/-- Exact public GCD preservation includes prime powers and saturation.\nThe existing RH cancellation theorem supplies the unit transport. -/\ntheorem shiftRow_residual_gcd {N : ℕ} (g : (ZMod N)ˣ)\n    (m j : ℕ) (k i : ℤ) (z : QuotientRow) :\n    N.gcd (((g^giantExponent m j (shiftRow m j k z).a (shiftRow m j k z).b\n        (shiftRow m j k z).c : (ZMod N)ˣ) : ZMod N)-\n          ((g^((m : ℤ)^2*(i-k)) : (ZMod N)ˣ) : ZMod N)).val=\n      N.gcd (((g^giantExponent m j z.a z.b z.c : (ZMod N)ˣ) : ZMod N)-\n        ((g^((m : ℤ)^2*i) : (ZMod N)ˣ) : ZMod N)).val := by\n  rw [shiftRow_residual]\n  exact SemiprimeRHCancellation.unit_mul_gcd_eq _ _\n\n/-- Public lower endpoint of the signed factor sum. Its sign is kept\nbefore applying the interval estimate. -/\ndef lowerSum (N m j : ℕ) (a b t : ℤ) : ℤ :=\n  a*(if 0≤a then (N/2).sqrt else N.sqrt)+t*N.sqrt+b*m-2*a*j\n\n/-- Public upper endpoint, retaining the same offset and orientation. -/\ndef upperSum (N m j : ℕ) (a b t : ℤ) : ℤ :=\n  a*(if 0≤a then N.sqrt else (N/2).sqrt)+t*(2*N).sqrt+b*m-2*a*j\n\n/-- Round the public interval midpoint to the nearest m-squared shift.\nInteger division handles either signed orientation. -/\ndef publicShift (N m j : ℕ) (a b t : ℤ) : ℤ :=\n  (lowerSum N m j a b t+upperSum N m j a b t+(m : ℤ)^2)/(2*(m : ℤ)^2)\n\n/-- The packet keeps its original quadratic and the exact public shift,\nso normalization does not erase recovery or phase information. -/\nstructure CenteredPacket where\n  /-- The actual Euclidean row before the new phase extraction. -/\n  original : QuotientRow\n  /-- The public integer change of collision origin. -/\n  shift : ℤ\nderiving Repr\n\n/-- Construct the retained packet with N-only public row data. -/\ndef publicPacket (N m j : ℕ) : CenteredPacket :=\n  let z := publicRow N m j\n  ⟨z,publicShift N m j z.a z.b z.t⟩\n\n/-- Derive a centered quadratic without discarding its source. -/\ndef packetRow (m j : ℕ) (w : CenteredPacket) : QuotientRow :=\n  shiftRow m j w.shift w.original\n\n/-- Both actual balanced factors lie in the literal public square-root\nbox. No primality or oracle is required for this arithmetic statement. -/\ntheorem balanced_factor_box {p q : ℕ} (hpq : p≤q) (hq₂ : q≤2*p) :\n    (p*q/2).sqrt≤p ∧ p≤(p*q).sqrt ∧ (p*q).sqrt≤q ∧ q≤(2*(p*q)).sqrt := by\n  have hN : p*q≤2*p^2 := by nlinarith only [Nat.mul_le_mul_left p hq₂]\n  have hhalf : p*q/2≤p^2 := by omega\n  have hpRoot : p≤(p*q).sqrt := Nat.le_sqrt'.mpr (by nlinarith only [Nat.mul_le_mul_left p hpq])\n  have hqRoot : (p*q).sqrt≤q := by\n    have h := Nat.sqrt_le_sqrt (show p*q≤q^2 by nlinarith only [Nat.mul_le_mul_right q hpq])\n    simpa only [Nat.sqrt_eq'] using h\n  have hqUp : q≤(2*(p*q)).sqrt :=\n    Nat.le_sqrt'.mpr (by nlinarith only [Nat.mul_le_mul_right q hq₂])\n  have hpLo : (p*q/2).sqrt≤p := by\n    simpa only [Nat.sqrt_eq'] using Nat.sqrt_le_sqrt hhalf\n  exact ⟨hpLo,hpRoot,hqRoot,hqUp⟩\n\n/-- Signed rectangle endpoints bound the exact coupled factor sum.\nThe factors occur only in the proof of coverage. -/\ntheorem factor_sum_interval {N m j p q : ℕ} {a b t : ℤ}\n    (hpLo : (N/2).sqrt≤p) (hpHi : p≤N.sqrt)\n    (hqLo : N.sqrt≤q) (hqHi : q≤(2*N).sqrt) (ht : 0≤t) :\n    lowerSum N m j a b t≤a*p+t*q+b*m-2*a*j ∧\n      a*p+t*q+b*m-2*a*j≤upperSum N m j a b t := by\n  have hpLoZ : ((N/2).sqrt : ℤ)≤p := by exact_mod_cast hpLo\n  have hpHiZ : (p : ℤ)≤N.sqrt := by exact_mod_cast hpHi\n  have hqLoZ : (N.sqrt : ℤ)≤q := by exact_mod_cast hqLo\n  have hqHiZ : (q : ℤ)≤(2*N).sqrt := by exact_mod_cast hqHi\n  have htLo := mul_le_mul_of_nonneg_left hqLoZ ht\n  have htHi := mul_le_mul_of_nonneg_left hqHiZ ht\n  unfold lowerSum upperSum\n  split_ifs with ha\n  · constructor <;> nlinarith only [htLo,htHi,mul_le_mul_of_nonneg_left hpLoZ ha,\n        mul_le_mul_of_nonneg_left hpHiZ ha]\n  · have ha' : a≤0 := (lt_of_not_ge ha).le\n    constructor <;> nlinarith only [htLo,htHi,mul_le_mul_of_nonpos_left hpLoZ ha',\n        mul_le_mul_of_nonpos_left hpHiZ ha']\n\n/-- The public interval width contains no uncentered b or j cost. -/\ntheorem factor_sum_width (N m j : ℕ) (a b t : ℤ) :\n    upperSum N m j a b t-lowerSum N m j a b t=\n      |a| *((N.sqrt : ℤ)-(N/2).sqrt)+t*(((2*N).sqrt : ℤ)-N.sqrt) := by\n  unfold lowerSum upperSum\n  split_ifs with ha\n  · rw [abs_of_nonneg ha]\n    ring\n  · rw [abs_of_neg (lt_of_not_ge ha)]\n    ring\n\n/-- The shared envelope depends on the width of the public factor box,\nrather than on the full uncentered factor sum. -/\ndef centeredLength (N m : ℕ) : ℕ :=\n  (m.sqrt*((2*N).sqrt-(N/2).sqrt)+m^2)/(2*m^2)+1\n\n/-- Exact integer midpoint rounding centers every value in the original\ninterval, including negative sums and boundary ties. -/\ntheorem rounded_interval {lo hi x d : ℤ} (hd : 0<d)\n    (hxLo : lo≤x) (hxHi : x≤hi) :\n    2*|x-((lo+hi+d)/(2*d))*d|≤hi-lo+d := by\n  let k := (lo+hi+d)/(2*d)\n  have hmod : 0≤(lo+hi+d)%(2*d) := Int.emod_nonneg _ (by omega)\n  have hlt : (lo+hi+d)%(2*d)<2*d := Int.emod_lt_of_pos _ (by omega)\n  have he : (lo+hi+d)%(2*d)+(2*d)*k=lo+hi+d := Int.emod_add_mul_ediv _ _\n  have hr : |2*(x-k*d)|≤hi-lo+d := abs_le.mpr (by constructor <;> nlinarith only [he,hmod,hlt,hxLo,hxHi])\n  rw [abs_mul,abs_of_nonneg (by decide : (0 : ℤ)≤2)] at hr\n  exact hr\n\n/-- Every signed index of the exact factor sum has the shorter public\nbound after transporting the row and target by the same public shift. -/\ntheorem centered_index_bound {N m j p q : ℕ} {a b t i : ℤ}\n    (hm : 0<m) (hpLo : (N/2).sqrt≤p) (hpHi : p≤N.sqrt)\n    (hqLo : N.sqrt≤q) (hqHi : q≤(2*N).sqrt)\n    (ha : |a|≤(m.sqrt : ℕ)) (ht₀ : 0≤t) (ht : t≤(m.sqrt : ℕ))\n    (hi : (m : ℤ)^2*i=a*p+t*q+b*m-2*a*j) :\n    (i-publicShift N m j a b t).natAbs < centeredLength N m := by\n  have hinterval := factor_sum_interval (m:=m) (j:=j) (a:=a) (b:=b) hpLo hpHi hqLo hqHi ht₀\n  have hlo : (N/2).sqrt≤N.sqrt := Nat.sqrt_le_sqrt (Nat.div_le_self N 2)\n  have hhi : N.sqrt≤(2*N).sqrt := Nat.sqrt_le_sqrt (by omega)\n  have hloZ : ((N/2).sqrt : ℤ)≤N.sqrt := by exact_mod_cast hlo\n  have hhiZ : (N.sqrt : ℤ)≤(2*N).sqrt := by exact_mod_cast hhi\n  have hd₁ : (0 : ℤ)≤(N.sqrt : ℤ)-(N/2).sqrt := by omega\n  have hd₂ : (0 : ℤ)≤((2*N).sqrt : ℤ)-N.sqrt := by omega\n  have hwidth : upperSum N m j a b t-lowerSum N m j a b t≤\n      (m.sqrt : ℤ)*(((2*N).sqrt : ℤ)-(N/2).sqrt) := by\n    rw [factor_sum_width]\n    have h₁ := mul_le_mul_of_nonneg_right ha hd₁\n    have h₂ := mul_le_mul_of_nonneg_right ht hd₂\n    nlinarith only [h₁,h₂]\n  have hmZ : (0 : ℤ)<m := by exact_mod_cast hm\n  have hround := rounded_interval (lo:=lowerSum N m j a b t) (hi:=upperSum N m j a b t)\n    (x:=(m : ℤ)^2*i) (d:=(m : ℤ)^2) (sq_pos_of_pos hmZ)\n    (by rw [hi]; exact hinterval.1) (by rw [hi]; exact hinterval.2)\n  have he : (m : ℤ)^2*i-publicShift N m j a b t*(m : ℤ)^2=\n      (i-publicShift N m j a b t)*(m : ℤ)^2 := by ring\n  change 2*|(m : ℤ)^2*i-publicShift N m j a b t*(m : ℤ)^2|≤_ at hround\n  rw [he,abs_mul,abs_of_nonneg (sq_nonneg (m : ℤ)),←Int.natCast_natAbs] at hround\n  have hd : ((2*N).sqrt : ℤ)-(N/2).sqrt=(((2*N).sqrt-(N/2).sqrt : ℕ) : ℤ) := by\n    rw [Nat.cast_sub (hlo.trans hhi)]\n  have hb : 2*(i-publicShift N m j a b t).natAbs*m^2≤\n      m.sqrt*((2*N).sqrt-(N/2).sqrt)+m^2 := by\n    have h : 2*((i-publicShift N m j a b t).natAbs : ℤ)*(m : ℤ)^2≤\n        (m.sqrt : ℤ)*((((2*N).sqrt-(N/2).sqrt : ℕ) : ℤ))+(m : ℤ)^2 := by\n      rw [←hd]\n      linarith only [hround,hwidth]\n    exact_mod_cast h\n  have hdiv := (Nat.le_div_iff_mul_le (show 0<2*m^2 by positivity)).mpr\n    (show (i-publicShift N m j a b t).natAbs*(2*m^2)≤\n      m.sqrt*((2*N).sqrt-(N/2).sqrt)+m^2 by nlinarith only [hb])\n  unfold centeredLength\n  omega\n\n/-- The actual public packet covers every balanced semiprime. It keeps\nthe original index, shifted index, nonzero quadratic and exact relation. -/\ntheorem publicPacket_balanced_coverage {p q m : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (hpq : p≤q) (hq₂ : q≤2*p) (hm : 1<m) (hN : m.Coprime (p*q)) :\n    let w := publicPacket (p*q) m (p%m)\n    let z := packetRow m (p%m) w\n    ∃ i : ℤ, i.natAbs < centeredLength (p*q) m ∧ z.a≠0 ∧\n      quadratic z.a z.b z.c (p/m : ℕ)=p*i ∧\n      quadratic w.original.a w.original.b w.original.c (p/m : ℕ)=p*(i+w.shift) ∧\n      quotientRelation (p*q : ℕ) m (p%m : ℕ) z.a z.b z.c z.t ∧\n      (p : ℤ)∈integerRoots z.a (z.b*m-2*z.a*(p%m : ℕ)-(m : ℤ)^2*i) (z.t*(p*q : ℕ)) := by\n  let src := publicRow (p*q) m (p%m)\n  let k := publicShift (p*q) m (p%m) src.a src.b src.t\n  let z := shiftRow m (p%m) k src\n  have hmp : m.Coprime p := hN.of_dvd_right (dvd_mul_right p q)\n  have hj : (p%m).Coprime m := by\n    change Nat.gcd (p%m) m=1\n    rw [←Nat.gcd_rec]\n    exact hmp\n  have hc := publicRow_correct hm hN hj\n  obtain ⟨i,_,ha,hi,_⟩ := publicRow_balanced_coverage hp hq hpq hq₂ hm hN\n  have hrel : quotientRelation ((p : ℤ)*q) m (p%m : ℕ) src.a src.b src.c src.t := by\n    simpa only [Nat.cast_mul] using hc.2.2.2.2.2.1\n  have hp0 : (p : ℤ)≠0 := by exact_mod_cast hp.ne_zero\n  have he : (p : ℤ)=(m : ℤ)*(p/m : ℕ)+(p%m : ℕ) := by\n    have h := Nat.mod_add_div p m\n    exact_mod_cast (by omega : p=m*(p/m)+p%m)\n  have hs := scaled_quadratic_factor_sum he hrel\n  rw [hi] at hs\n  have hsum : (m : ℤ)^2*i=src.a*p+src.t*q+src.b*m-2*src.a*(p%m : ℕ) := by\n    apply mul_left_cancel₀ hp0\n    nlinarith only [hs]\n  have habs : |src.a|≤(m.sqrt : ℕ) := by\n    rw [←Int.natCast_natAbs]\n    exact_mod_cast hc.2.1\n  have hbox := balanced_factor_box hpq hq₂\n  have hbound := centered_index_bound (m:=m) (j:=(p%m)) (by omega)\n    hbox.1 hbox.2.1 hbox.2.2.1 hbox.2.2.2 habs hc.2.2.1.le hc.2.2.2.1 hsum\n  have hnew : quadratic z.a z.b z.c (p/m : ℕ)=(p : ℤ)*(i-k) := by\n    rw [shiftRow_quadratic,←he,hi]\n    ring\n  have hnewrel : quotientRelation ((p : ℤ)*q) m (p%m : ℕ) z.a z.b z.c z.t := by\n    exact shiftRow_relation (by simpa only [Nat.cast_mul] using hrel) k\n  have hnewa : z.a≠0 := ha\n  have hroot := integerRoots_complete hnewa (quotient_row_recovery_equation he hnewrel hnew)\n  change ∃ i', i'.natAbs < centeredLength (p*q) m ∧ z.a≠0 ∧\n    quadratic z.a z.b z.c (p/m : ℕ)=p*i' ∧\n    quadratic src.a src.b src.c (p/m : ℕ)=p*(i'+k) ∧\n    quotientRelation (p*q : ℕ) m (p%m : ℕ) z.a z.b z.c z.t ∧\n    (p : ℤ)∈integerRoots z.a (z.b*m-2*z.a*(p%m : ℕ)-(m : ℤ)^2*i') (z.t*(p*q : ℕ))\n  refine ⟨i-k,hbound,hnewa,hnew,?_,?_,?_⟩\n  · simpa only [sub_add_cancel] using hi\n  · simpa only [Nat.cast_mul] using hnewrel\n  · simpa only [Nat.cast_mul] using hroot\n\n/-- The shorter shared baby axis still contains a real hidden-field\ncollision, and its shifted quadratic list still recovers the actual p. -/\ntheorem publicPacket_balanced_power_coverage {p q m : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (hpq : p≤q) (hq₂ : q≤2*p) (hm : 1<m) (hN : m.Coprime (p*q))\n    (g : (ZMod p)ˣ) :\n    let w := publicPacket (p*q) m (p%m)\n    let z := packetRow m (p%m) w\n    ∃ i : ℤ, i.natAbs < centeredLength (p*q) m ∧\n      g^giantExponent m (p%m : ℕ) z.a z.b z.c=g^((m : ℤ)^2*i) ∧\n      (p : ℤ)∈integerRoots z.a (z.b*m-2*z.a*(p%m : ℕ)-(m : ℤ)^2*i) (z.t*(p*q : ℕ)) := by\n  let : Fact p.Prime := ⟨hp⟩\n  let w := publicPacket (p*q) m (p%m)\n  let z := packetRow m (p%m) w\n  obtain ⟨i,hindex,_,hi,_,hr,hroot⟩ := publicPacket_balanced_coverage hp hq hpq hq₂ hm hN\n  have hrel : quotientRelation ((p : ℤ)*q) m (p%m : ℕ) z.a z.b z.c z.t := by\n    simpa only [Nat.cast_mul] using hr\n  have he : (p : ℤ)=(m : ℤ)*(p/m : ℕ)+(p%m : ℕ) := by\n    have h := Nat.mod_add_div p m\n    exact_mod_cast (by omega : p=m*(p/m)+p%m)\n  have hperiod : g^((p : ℤ)-1)=1 := by\n    have h := ZMod.units_pow_card_sub_one_eq_one p g\n    have hz : g^((p-1 : ℕ) : ℤ)=1 := by simpa only [zpow_natCast] using h\n    simpa only [Nat.cast_sub hp.one_le,Nat.cast_one] using hz\n  exact ⟨i,hindex,quotient_row_power_hit g he hrel hi (by exact_mod_cast hp.ne_zero) hperiod,hroot⟩\n\n/-- A fifth-root square modulus gives a smaller explicit input budget.\nThis counts row/point inputs only; it does not certify bit complexity. -/\ntheorem centeredLength_fifth_budget {N M : ℕ} (hM : 0<M) (hN : N≤M^10) :\n    centeredLength N (M^2)≤M^2+2 := by\n  have hroot : (2*N).sqrt≤2*M^5 := by\n    have h : 2*N≤(2*M^5)^2 := by nlinarith only [hN]\n    simpa only [Nat.sqrt_eq'] using Nat.sqrt_le_sqrt h\n  have hdiff : (2*N).sqrt-(N/2).sqrt≤2*M^5 := (Nat.sub_le _ _).trans hroot\n  have hb := Nat.mul_le_mul_left M hdiff\n  have hn : M*((2*N).sqrt-(N/2).sqrt)+(M^2)^2≤(M^2+1)*(2*(M^2)^2) := by\n    nlinarith only [hb]\n  have hd : 0<2*(M^2)^2 := by positivity\n  have hdiv := Nat.div_le_div_right (c:=2*(M^2)^2) hn\n  rw [Nat.mul_div_cancel _ hd] at hdiv\n  unfold centeredLength\n  rw [Nat.sqrt_eq']\n  omega\n\n/-- Both signed giant orientations and the centered points have a\nlinear fifth-root construction budget, with their full pair grid absent. -/\ntheorem centered_fifth_layout {N M : ℕ} (hM : 0<M) (hN : N≤M^10) :\n    2*M^2+centeredLength N (M^2)≤3*M^2+2 := by\n  have h := centeredLength_fifth_budget hM hN\n  omega\n\n/-- At sixth-root modulus scale, this centering still gives a cubic\nM index envelope. This upper bound is not a general factoring lower bound. -/\ntheorem centeredLength_sixth_budget {N M : ℕ} (hM : 0<M) (hN : N≤M^12) :\n    centeredLength N (M^2)≤M^3+2 := by\n  have hroot : (2*N).sqrt≤2*M^6 := by\n    have h : 2*N≤(2*M^6)^2 := by nlinarith only [hN]\n    simpa only [Nat.sqrt_eq'] using Nat.sqrt_le_sqrt h\n  have hdiff : (2*N).sqrt-(N/2).sqrt≤2*M^6 := (Nat.sub_le _ _).trans hroot\n  have hb := Nat.mul_le_mul_left M hdiff\n  have hn : M*((2*N).sqrt-(N/2).sqrt)+(M^2)^2≤(M^3+1)*(2*(M^2)^2) := by\n    nlinarith only [hb]\n  have hd : 0<2*(M^2)^2 := by positivity\n  have hdiv := Nat.div_le_div_right (c:=2*(M^2)^2) hn\n  rw [Nat.mul_div_cancel _ hd] at hdiv\n  unfold centeredLength\n  rw [Nat.sqrt_eq']\n  omega\n\n/-- Literal public control: the original zero index becomes -2, and the\nentire common axis shrinks from the previous 41 points to six. -/\ntheorem control_public_shift :\n    publicShift 10403 4 1 (-1) (-1) 1=2 ∧ centeredLength 10403 4=6 ∧\n      SemiprimeQuotientRows.indexLength 10403 4=41 ∧\n      integerRoots (-1) ((-9)*4-2*(-1)*1-4^2*(-2)) 10403=[-103,101] := by\n  norm_num [publicShift,lowerSum,upperSum,centeredLength,SemiprimeQuotientRows.indexLength,integerRoots]\n\n/-- Centering the giant alone loses this actual factor signal. Moving\nthe baby target by the same phase retains the exact collision. -/\ntheorem control_target_transport :\n    (2 : ZMod 101)^10400=1 ∧ (2 : ZMod 101)^10368≠1 ∧\n      (2 : ZMod 101)^10368*(2 : ZMod 101)^32=1 := by\n  reduce_mod_char\n  norm_num\n  decide\n\nend RiemannGaussian.SemiprimeQuotientCentering\n","RiemannGaussian.SemiprimeRowPartnerOffsets":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSymmetricRowAxes\n\n/-!\n# Actual public residue-partner offset cancellation\n\nFor two actual packets with swapped oriented coefficients and partner\nresidues, the two quotient relations force their offset difference to be\ndivisible by m squared. Opposite public centers restrict that difference\nto zero or one signed m-squared step. After the public prefix, the paired\naffine-root difference is therefore zero or a unit, never a proper-factor\nsignal. This does not assume every packet has a partner in the stream.\n-/\n\nnamespace RiemannGaussian.SemiprimeRowPartnerOffsets\n\nopen SemiprimeQuotientRows SemiprimeQuotientCentering SemiprimeEuclidRowFamily\nopen SemiprimeCompanionRows SemiprimeCompanionCenterSpectrum SemiprimeCenteredOffsetExtractor\nopen SemiprimeRowAreaSpectrum SemiprimeQuadraticPointJets SemiprimeAffineRowRoots\nopen SemiprimeLiteralQuadraticRoots\nopen SemiprimeSymmetricRowAxes\n\n/-- The oriented difference before modular reduction or centering bounds. -/\ndef partnerDelta (m : ℕ) (u v : FamilyPacket) (s : ℤ) : ℤ :=\n  packetOffset m v-s*packetOffset m u\n\n/-- The two true factor residues satisfy the public partner relation automatically. -/\ntheorem factor_residue_product_dvd (p q m : ℕ) :\n    (m : ℤ)∣(p : ℤ)*q-(p%m : ℕ)*(q%m : ℕ) := by\n  have hp : (p%m : ℕ)+(m : ℤ)*(p/m : ℕ)=(p : ℤ) := by\n    exact_mod_cast Nat.mod_add_div p m\n  have hq : (q%m : ℕ)+(m : ℤ)*(q/m : ℕ)=(q : ℤ) := by\n    exact_mod_cast Nat.mod_add_div q m\n  refine ⟨(p/m : ℕ)*(q : ℤ)+(p%m : ℕ)*(q/m : ℕ),?_⟩\n  linear_combination -(q : ℤ)*hp-(p%m : ℕ)*hq\n\ntheorem publicPacket_coefficient_residue_dvd {N m : ℕ} (hm : 0<m)\n    {u : FamilyPacket} (hu : u∈publicPackets N m) :\n    (m : ℤ)∣u.original.a*u.residue^2-(N : ℤ)*u.original.t := by\n  have h := publicPacket_original_relation hm hu\n  unfold quotientRelation at h\n  refine ⟨(u.residue : ℤ)*u.original.b-(m : ℤ)*u.original.c,?_⟩\n  linear_combination h\n\n/-- The public partner congruence forces the second m-divisible factor. -/\ntheorem publicPacket_partner_coefficient_dvd {N m : ℕ} (hm : 0<m)\n    {u : FamilyPacket} (hu : u∈publicPackets N m) {k : ℕ}\n    (hprod : (m : ℤ)∣(N : ℤ)-(u.residue : ℤ)*k) :\n    (m : ℤ)∣u.original.a*u.residue-u.original.t*k := by\n  obtain ⟨c,hc⟩ := publicPacket_coefficient_residue_dvd hm hu\n  obtain ⟨d,hd⟩ := hprod\n  have he : (u.residue : ℤ)*(u.original.a*u.residue-u.original.t*k)=\n      (m : ℤ)*(c+u.original.t*d) := by\n    linear_combination hc+u.original.t*hd\n  obtain ⟨x,y,hxy⟩ := (publicPacket_residue_coprime hu).isCoprime\n  refine ⟨x*(c+u.original.t*d)+y*(u.original.a*u.residue-u.original.t*k),?_⟩\n  linear_combination x*he-(u.original.a*u.residue-u.original.t*k)*hxy\n\n/-- Two m-divisible factors explain the complete m-squared cancellation. -/\ntheorem publicPacket_partner_delta_dvd {N m : ℕ} (hm : 0<m)\n    {u v : FamilyPacket} (hu : u∈publicPackets N m) (hv : v∈publicPackets N m)\n    (s : ℤ) (ha : v.original.a=s*u.original.t) (ht : v.original.t=s*u.original.a)\n    (hprod : (m : ℤ)∣(N : ℤ)-(u.residue : ℤ)*v.residue) :\n    (m : ℤ)^2∣partnerDelta m u v s := by\n  obtain ⟨e,he⟩ := publicPacket_partner_coefficient_dvd hm hu hprod\n  obtain ⟨d,hd⟩ := hprod\n  have hur := publicPacket_tangent_integer hm hu\n  have hvr := publicPacket_tangent_integer hm hv\n  rw [ha,ht] at hvr\n  have hident : (u.residue : ℤ)*v.residue*partnerDelta m u v s =\n      (m : ℤ)^2*((u.residue : ℤ)*(centeredPacketRow m v).c-\n        s*(v.residue : ℤ)*(centeredPacketRow m u).c-s*d*e) := by\n    unfold partnerDelta\n    linear_combination (u.residue : ℤ)*hvr-s*(v.residue : ℤ)*hur-\n      s*((u.original.a*u.residue-u.original.t*v.residue)*hd+\n        (m : ℤ)*d*he)\n  have hcop := ((publicPacket_residue_coprime hu).mul_left\n    (publicPacket_residue_coprime hv)).pow_right 2\n  obtain ⟨x,y,hxy⟩ := hcop.isCoprime\n  simp only [Nat.cast_mul,Nat.cast_pow] at hxy\n  refine ⟨x*((u.residue : ℤ)*(centeredPacketRow m v).c-\n    s*(v.residue : ℤ)*(centeredPacketRow m u).c-s*d*e)+y*partnerDelta m u v s,?_⟩\n  linear_combination x*hident-partnerDelta m u v s*hxy\n\ntheorem partner_delta_abs_le {N m : ℕ} (hm : 0<m) (u v : FamilyPacket) (s : ℤ)\n    (hs : s=-1 ∨ s=1) (ha : v.original.a=s*u.original.t)\n    (ht : v.original.t=s*u.original.a) (side : Bool)\n    (huc : CenterChoice N m u side) (hvc : CenterChoice N m v (!side)) :\n    |partnerDelta m u v s|≤(m : ℤ)^2 := by\n  have hur := packet_center_equation u side huc\n  have hvr := packet_center_equation v (!side) hvc\n  have hA : centerA N (!side)=centerB N side := rfl\n  have hB : centerB N (!side)=centerA N side := by simp only [centerB,Bool.not_not]\n  rw [ha,ht,hA,hB] at hvr\n  have hδ : 2*partnerDelta m u v s=\n      s*packetCenterError N m u side-packetCenterError N m v (!side) := by\n    unfold partnerDelta\n    linear_combination s*hur-hvr\n  have heu := packetCenterError_abs_le (N:=N) hm u side\n  have hev := packetCenterError_abs_le (N:=N) hm v (!side)\n  have hsabs : |s*packetCenterError N m u side|=|packetCenterError N m u side| := by\n    rcases hs with rfl|rfl <;> simp\n  have hb := abs_sub_le (s*packetCenterError N m u side) 0\n    (packetCenterError N m v (!side))\n  simp only [sub_zero,zero_sub,abs_neg,hsabs] at hb\n  have hδabs := congrArg abs hδ\n  norm_num only [abs_mul,Int.reduceAbs] at hδabs\n  nlinarith\n\ntheorem bounded_multiple {d z : ℤ} (hd : 0<d) (hdiv : d∣z) (hb : |z|≤d) :\n    z=0 ∨ z=d ∨ z=-d := by\n  obtain ⟨k,hk⟩ := hdiv\n  have hz := abs_le.mp hb\n  have hlo : -1≤k := by\n    by_contra hc\n    have hm := mul_le_mul_of_nonneg_left (show k≤-2 by omega) hd.le\n    nlinarith\n  have hhi : k≤1 := by\n    by_contra hc\n    have hm := mul_le_mul_of_nonneg_left (show 2≤k by omega) hd.le\n    nlinarith\n  have hcases : k=0 ∨ k=1 ∨ k=-1 := by omega\n  rcases hcases with rfl|rfl|rfl <;> simp_all\n\n/-- On the actual source, the public prefix makes every nonzero partner correction a unit. -/\ntheorem publicPacket_partner_delta_zero_or_unit {N m : ℕ} (hm : 0<m) (hcover : m^2<N)\n    (hn : SemiprimeStrassenPrefix.factorPrefix N m=none)\n    {u v : FamilyPacket} (hu : u∈publicPackets N m) (hv : v∈publicPackets N m)\n    (s : ℤ) (hs : s=-1 ∨ s=1) (ha : v.original.a=s*u.original.t)\n    (ht : v.original.t=s*u.original.a)\n    (hprod : (m : ℤ)∣(N : ℤ)-(u.residue : ℤ)*v.residue) (side : Bool)\n    (huc : CenterChoice N m u side) (hvc : CenterChoice N m v (!side)) :\n    (partnerDelta m u v s : ZMod N)=0 ∨ IsUnit (partnerDelta m u v s : ZMod N) := by\n  have hd := publicPacket_partner_delta_dvd hm hu hv s ha ht hprod\n  have hb := partner_delta_abs_le hm u v s hs ha ht side huc hvc\n  have hp : 0<(m : ℤ)^2 := by positivity\n  have hmUnit := (prefix_none_modulus_unit hm hcover hn).pow 2\n  rcases bounded_multiple hp hd hb with h0|hplus|hminus\n  · exact Or.inl (by rw [h0,Int.cast_zero])\n  · exact Or.inr (by simpa only [hplus,Int.cast_pow,Int.cast_natCast] using hmUnit)\n  · exact Or.inr (by simpa only [hminus,Int.cast_neg,Int.cast_pow,Int.cast_natCast]\n      using hmUnit.neg)\n\n/-- The natural paired affine channels give whole-N matches or unit differences.\nThis explains the duplicates; it does not force a useful factor collision. -/\ntheorem publicPacket_partner_root_zero_or_unit {N m : ℕ} (hm : 0<m) (hcover : m^2<N)\n    (hn : SemiprimeStrassenPrefix.factorPrefix N m=none)\n    {u v : FamilyPacket} (hu : u∈publicPackets N m) (hv : v∈publicPackets N m)\n    (s : ℤ) (hs : s=-1 ∨ s=1) (ha : v.original.a=s*u.original.t)\n    (ht : v.original.t=s*u.original.a)\n    (hprod : (m : ℤ)∣(N : ℤ)-(u.residue : ℤ)*v.residue) (side : Bool)\n    (huc : CenterChoice N m u side) (hvc : CenterChoice N m v (!side)) :\n    packetRoot N m v false-packetRoot N m u true=0 ∨\n      IsUnit (packetRoot N m v false-packetRoot N m u true) := by\n  have hva := prefix_none_publicPacket_leading_unit hm hcover hn hv\n  have htUnit : IsUnit (u.original.t : ZMod N) := by\n    have h := hva\n    rw [ha,Int.cast_mul] at h\n    exact isUnit_of_mul_isUnit_right h\n  have hur := packetRoot_coefficient (m:=m) u true htUnit\n  have hvr := packetRoot_coefficient (m:=m) v false hva\n  simp only [packetScale,ite_true] at hur\n  simp only [packetScale,Bool.false_eq_true,ite_false] at hvr\n  have ha' : (v.original.a : ZMod N)=(s : ZMod N)*(u.original.t : ZMod N) := by\n    rw [ha,Int.cast_mul]\n  have he : (v.original.a : ZMod N)*\n      (packetRoot N m v false-packetRoot N m u true)=-(partnerDelta m u v s : ZMod N) := by\n    unfold partnerDelta\n    push_cast\n    rw [ha'] at hvr ⊢\n    linear_combination hvr-(s : ZMod N)*hur\n  have hd := publicPacket_partner_delta_zero_or_unit hm hcover hn hu hv s hs ha ht\n    hprod side huc hvc\n  rcases hd with hz|hunit\n  · rw [hz,neg_zero] at he\n    have h := congrArg (fun x => (v.original.a : ZMod N)⁻¹*x) he\n    rw [←mul_assoc,ZMod.inv_mul_of_unit _ hva,one_mul,mul_zero] at h\n    exact Or.inl h\n  · have hprodUnit : IsUnit ((v.original.a : ZMod N)*\n        (packetRoot N m v false-packetRoot N m u true)) := he ▸ hunit.neg\n    exact Or.inr (isUnit_of_mul_isUnit_right hprodUnit)\n\n/-- Even the correct hidden-factor residue pair supplies no proper signal from\nthis swapped-center symmetry. The factors select proof witnesses only. -/\ntheorem publicPacket_factor_residue_root_zero_or_unit {p q m : ℕ}\n    (hm : 0<m) (hcover : m^2<p*q)\n    (hn : SemiprimeStrassenPrefix.factorPrefix (p*q) m=none)\n    {u v : FamilyPacket} (hu : u∈publicPackets (p*q) m) (hv : v∈publicPackets (p*q) m)\n    (hj : u.residue=p%m) (hk : v.residue=q%m)\n    (s : ℤ) (hs : s=-1 ∨ s=1) (ha : v.original.a=s*u.original.t)\n    (ht : v.original.t=s*u.original.a) (side : Bool)\n    (huc : CenterChoice (p*q) m u side) (hvc : CenterChoice (p*q) m v (!side)) :\n    packetRoot (p*q) m v false-packetRoot (p*q) m u true=0 ∨\n      IsUnit (packetRoot (p*q) m v false-packetRoot (p*q) m u true) := by\n  have hprod : (m : ℤ)∣(p*q : ℕ)-(u.residue : ℤ)*v.residue := by\n    simpa only [hj,hk,Nat.cast_mul] using factor_residue_product_dvd p q m\n  exact publicPacket_partner_root_zero_or_unit hm hcover hn hu hv s hs ha ht\n    hprod side huc hvc\n\n/-- Neither new signed axis gains a proper signal from its natural partner.\nFor the minus axis, the corresponding comparison is the reflected sum. -/\ntheorem publicPacket_partner_axis_zero_or_unit {N m : ℕ} (hm : 0<m) (hcover : m^2<N)\n    (hn : SemiprimeStrassenPrefix.factorPrefix N m=none)\n    {u v : FamilyPacket} (hu : u∈publicPackets N m) (hv : v∈publicPackets N m)\n    (s : ℤ) (hs : s=-1 ∨ s=1) (ha : v.original.a=s*u.original.t)\n    (ht : v.original.t=s*u.original.a)\n    (hprod : (m : ℤ)∣(N : ℤ)-(u.residue : ℤ)*v.residue) (side : Bool)\n    (huc : CenterChoice N m u side) (hvc : CenterChoice N m v (!side))\n    (minus : Bool) (hdu : axisDenominator u minus≠0) :\n    axisRoot N m v minus-(if minus then -axisRoot N m u minus else axisRoot N m u minus)=0 ∨\n      IsUnit (axisRoot N m v minus-\n        (if minus then -axisRoot N m u minus else axisRoot N m u minus)) := by\n  have hc : axisDenominator v minus=(if minus then -s else s)*axisDenominator u minus := by\n    cases minus <;> simp [axisDenominator,ha,ht] <;> ring\n  have hsne : s≠0 := by rcases hs with rfl|rfl <;> norm_num\n  have hphase : (if minus then -s else s)≠0 := by cases minus <;> simp [hsne]\n  have huUnit := prefix_none_axis_unit hm hcover hn hu minus hdu\n  have hvUnit := prefix_none_axis_unit hm hcover hn hv minus\n    (show axisDenominator v minus≠0 by rw [hc]; exact mul_ne_zero hphase hdu)\n  have hur := axisRoot_coefficient (m:=m) u minus huUnit\n  have hvr := axisRoot_coefficient (m:=m) v minus hvUnit\n  have he : (axisDenominator v minus : ZMod N)*\n      (axisRoot N m v minus-(if minus then -axisRoot N m u minus else axisRoot N m u minus))=\n      -(partnerDelta m u v s : ZMod N) := by\n    unfold partnerDelta\n    push_cast\n    rw [hc,Int.cast_mul] at hvr ⊢\n    cases minus <;> simp only [Bool.false_eq_true,ite_false,ite_true,Int.cast_neg] at hvr ⊢\n    · linear_combination hvr-(s : ZMod N)*hur\n    · linear_combination hvr-(s : ZMod N)*hur\n  have hd := publicPacket_partner_delta_zero_or_unit hm hcover hn hu hv s hs ha ht\n    hprod side huc hvc\n  rcases hd with hz|hunit\n  · rw [hz,neg_zero] at he\n    have h := congrArg (fun x => (axisDenominator v minus : ZMod N)⁻¹*x) he\n    rw [←mul_assoc,ZMod.inv_mul_of_unit _ hvUnit,one_mul,mul_zero] at h\n    exact Or.inl h\n  · have hprodUnit : IsUnit ((axisDenominator v minus : ZMod N)*\n        (axisRoot N m v minus-\n          (if minus then -axisRoot N m u minus else axisRoot N m u minus))) := he ▸ hunit.neg\n    exact Or.inr (isUnit_of_mul_isUnit_right hprodUnit)\n\n/-- Correct factor residues also fail to force a signal in the two new axes. -/\ntheorem publicPacket_factor_residue_axis_zero_or_unit {p q m : ℕ}\n    (hm : 0<m) (hcover : m^2<p*q)\n    (hn : SemiprimeStrassenPrefix.factorPrefix (p*q) m=none)\n    {u v : FamilyPacket} (hu : u∈publicPackets (p*q) m) (hv : v∈publicPackets (p*q) m)\n    (hj : u.residue=p%m) (hk : v.residue=q%m)\n    (s : ℤ) (hs : s=-1 ∨ s=1) (ha : v.original.a=s*u.original.t)\n    (ht : v.original.t=s*u.original.a) (side : Bool)\n    (huc : CenterChoice (p*q) m u side) (hvc : CenterChoice (p*q) m v (!side))\n    (minus : Bool) (hdu : axisDenominator u minus≠0) :\n    axisRoot (p*q) m v minus-\n        (if minus then -axisRoot (p*q) m u minus else axisRoot (p*q) m u minus)=0 ∨\n      IsUnit (axisRoot (p*q) m v minus-\n        (if minus then -axisRoot (p*q) m u minus else axisRoot (p*q) m u minus)) := by\n  have hprod : (m : ℤ)∣(p*q : ℕ)-(u.residue : ℤ)*v.residue := by\n    simpa only [hj,hk,Nat.cast_mul] using factor_residue_product_dvd p q m\n  exact publicPacket_partner_axis_zero_or_unit hm hcover hn hu hv s hs ha ht\n    hprod side huc hvc minus hdu\n\nend RiemannGaussian.SemiprimeRowPartnerOffsets\n","RiemannGaussian.SemiprimeScheduledFactorExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimePublicAcquiredExecution\n\n/-! # Deterministic natural-input factor algorithm with a literal source guard -/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeScheduledFactorExecution\nopen scoped BigOperators\nopen Filter SemiprimeMacroParameters SemiprimeCounterRate SemiprimeSourceLayoutRate\nopen SemiprimePublicAcquiredExecution\n\n/-- Actual binary logarithm of the public Boolean wire count. -/\ndef lambda (N : ℕ) : ℕ := Nat.clog 2 (wireCount N)\n/-- The actual scheduled source group count. -/\ndef groups (N : ℕ) : ℕ := scheduledGroupCount (lambda N)\n/-- The actual scheduled number of interpolation nodes. -/\ndef points (N : ℕ) : ℕ := scheduledPointCount (lambda N)\n/-- The actual scheduled source polynomial degree. -/\ndef degree (N : ℕ) : ℕ := scheduledDegree (lambda N)\n/-- The actual rational source tolerance, computed without real logarithms. -/\ndef epsilon (N : ℕ) : ℚ := 1/(groups N*lambda N : ℕ)\n/-- Precision is computed from actual total input arity, not assumed adequate. -/\ndef precision (N : ℕ) : ℕ := 2*wireCount N*degree N/points N+1\n\n/-- The actual scheduled precision is the published inclusive support cutoff plus one. -/\ntheorem precision_formula (N : ℕ) : precision N=\n    2*wireCount N*scheduledDegree (Nat.clog 2 (wireCount N))/\n      scheduledPointCount (Nat.clog 2 (wireCount N))+1 := rfl\n\n/-- Integer/rational sufficient guard used by the executable branch. -/\ndef fastGuard (N : ℕ) : Prop :=\n  0<wireCount N ∧ 0<scopeBound (bitLength N) ∧ 2≤groups N ∧ 2≤points N ∧\n  4≤degree N ∧ 4*degree N≤points N ∧ 0<epsilon N ∧ epsilon N≤1/2 ∧\n  4*(2+scopeBound (bitLength N))*scheduledDimension (wireCount N)^2*(groups N*lambda N)^2≤2*wireCount N ∧\n  16*points N*groups N^2≤wireCount N ∧\n  32*(points N-1)*Nat.clog 2 (2*groups N*lambda N)≤degree N^2 ∧\n  epsilon N*(2*wireCount N : ℕ)≤(wireCount N : ℚ)/2\n\n/-- The runtime guard uses only decidable integer and rational operations. -/\ninstance fastGuardDecidable (N : ℕ) : Decidable (fastGuard N) := by\n  unfold fastGuard\n  infer_instance\n\n/-- Complete elementary fallback on a literal finite candidate interval. -/\ndef trialFactor (N : ℕ) : Option ℕ :=\n  (List.range N).find? (fun p => decide (2≤p ∧ N%p=0))\n\n/-- Every fallback output is a proper integer divisor. -/\ntheorem trialFactor_sound (N p : ℕ) (h : trialFactor N=some p) : 2≤p ∧ p<N ∧ p∣N := by\n  have hm := List.mem_of_find?_eq_some h\n  have hp : 2≤p ∧ N%p=0 := of_decide_eq_true (List.find?_some (p := fun p => decide (2≤p ∧ N%p=0)) (l := List.range N) h)\n  exact ⟨hp.1,List.mem_range.mp hm,Nat.dvd_of_mod_eq_zero hp.2⟩\n\n/-- Ordinary proper factor pairs exist exactly when a proper divisor exists. -/\ntheorem ordinary_iff_divisor (N : ℕ) :\n    Nonempty (SemiprimePublicFactorCount.OrdinaryFactors N) ↔ ∃ p, 2≤p ∧ p<N ∧ p∣N := by\n  constructor\n  · rintro ⟨⟨⟨p,q⟩,hp,hq,hprod⟩⟩\n    exact ⟨p.val,hp,by nlinarith,⟨q.val,hprod.symm⟩⟩\n  · rintro ⟨p,hp,hlt,hdvd⟩\n    let q := N/p\n    have hprod : p*q=N := Nat.mul_div_cancel' hdvd\n    have hq : 2≤q := by nlinarith\n    refine ⟨⟨(⟨p,by omega⟩,⟨q,?_⟩),hp,hq,hprod⟩⟩\n    exact Nat.lt_succ_of_le (Nat.div_le_self N p)\n\n/-- The fallback has no failure other than absence of a proper factor. -/\ntheorem trialFactor_none_iff (N : ℕ) :\n    trialFactor N=none ↔ ¬Nonempty (SemiprimePublicFactorCount.OrdinaryFactors N) := by\n  rw [ordinary_iff_divisor]\n  unfold trialFactor\n  rw [List.find?_eq_none]\n  simp only [List.mem_range,decide_eq_true_eq]\n  constructor\n  · intro h ⟨p,hp,hlt,hdvd⟩\n    exact h p hlt ⟨hp,Nat.mod_eq_zero_of_dvd hdvd⟩\n  · intro h p hlt hp\n    exact h ⟨p,hp.1,hlt,Nat.dvd_of_mod_eq_zero hp.2⟩\n\n/-- Precision satisfies the exact interpolation requirement on the branch that uses it. -/\ntheorem precision_valid (N : ℕ) (hN : 0<N) (hQ : 0<points N) :\n    0<precision N ∧ (∑ e, indexedArity N e)*degree N<points N*precision N := by\n  refine ⟨Nat.succ_pos _,?_⟩\n  rw [indexed_incidence_count N hN]\n  exact Nat.lt_mul_div_succ _ hQ\n\n/-- The accepted numerical guard proves the scheduled group count is positive. -/\ntheorem guard_groups_pos (N : ℕ) (hg : fastGuard N) : 0<groups N :=\n  Nat.lt_of_lt_of_le (by decide : 0<2) hg.2.2.1\n\n/-- The accepted numerical guard proves the interpolation count is positive. -/\ntheorem guard_points_pos (N : ℕ) (hg : fastGuard N) : 0<points N :=\n  Nat.lt_of_lt_of_le (by decide : 0<2) hg.2.2.2.1\n\n/-- The centered source interval starts before the last interpolation node. -/\ntheorem guard_interval (N : ℕ) (hg : fastGuard N) :\n    OAI.Algorithms.SubexponentialSAT.Subexp.TailInterval.intervalStart\n      (groups N) (points N) (degree N)≤points N :=\n  (Nat.le_add_right _ _).trans\n    (OAI.Algorithms.SubexponentialSAT.Subexp.TailInterval.intervalStart_end_le\n      hg.2.2.1 hg.2.2.2.2.1 hg.2.2.2.2.2.1)\n\n/-- The public natural-input algorithm; all parameters and all fallback choices are computed. -/\ndef run (N : ℕ) : Option ℕ :=\n  if hN : 0<N then\n    if hr : 0<groups N then\n      letI : NeZero (groups N) := ⟨Nat.ne_of_gt hr⟩\n      if fastGuard N then\n        factor N hN (groups N) (points N) (epsilon N) (degree N) (precision N)\n      else trialFactor N\n    else trialFactor N\n  else none\n\n/-- Every algorithm output is a genuine proper divisor of its original input. -/\ntheorem run_sound (N p : ℕ) (h : run N=some p) : 2≤p ∧ p<N ∧ p∣N := by\n  by_cases hN : 0<N\n  · by_cases hr : 0<groups N\n    · let _ : NeZero (groups N) := ⟨Nat.ne_of_gt hr⟩\n      by_cases hg : fastGuard N\n      · have hQ := guard_points_pos N hg\n        have hAQ := guard_interval N hg\n        have hf : factor N hN (groups N) (points N) (epsilon N) (degree N) (precision N)=some p := by\n          simpa only [run,dite_eq_left hN,dite_eq_left hr,ite_eq_left hg] using h\n        exact factor_sound N hN (groups N) (points N) (epsilon N) (degree N) (precision N)\n          (Nat.le_trans (by decide : 1≤2) hg.2.2.2.1) hAQ (precision_valid N hN hQ).1\n          (precision_valid N hN hQ).2 p hf\n      · exact trialFactor_sound N p (by simpa only [run,dite_eq_left hN,dite_eq_left hr,ite_eq_right hg] using h)\n    · exact trialFactor_sound N p (by simpa only [run,dite_eq_left hN,dite_eq_right hr] using h)\n  · have hn : (none : Option ℕ)=some p := by simpa only [run,dite_eq_right hN] using h\n    cases hn\n\n/-- The algorithm is complete on every natural input, including primes and squares. -/\ntheorem run_none_iff (N : ℕ) : run N=none ↔ ¬Nonempty (SemiprimePublicFactorCount.OrdinaryFactors N) := by\n  by_cases hN : 0<N\n  · by_cases hr : 0<groups N\n    · let _ : NeZero (groups N) := ⟨Nat.ne_of_gt hr⟩\n      by_cases hg : fastGuard N\n      · have hQ := guard_points_pos N hg\n        have hAQ := guard_interval N hg\n        simp only [run,dite_eq_left hN,dite_eq_left hr,ite_eq_left hg]\n        exact factor_none_iff N hN (groups N) (points N) (epsilon N) (degree N) (precision N)\n          (Nat.le_trans (by decide : 1≤2) hg.2.2.2.1) hAQ (precision_valid N hN hQ).1 (precision_valid N hN hQ).2\n      · simpa only [run,dite_eq_left hN,dite_eq_left hr,ite_eq_right hg] using trialFactor_none_iff N\n    · simpa only [run,dite_eq_left hN,dite_eq_right hr] using trialFactor_none_iff N\n  · have hn : N=0 := Nat.eq_zero_of_not_pos hN\n    subst N\n    rw [ordinary_iff_divisor]\n    have he : run 0=none := rfl\n    rw [he]\n    simp only [true_iff]\n    rintro ⟨p,_hp,hlt,_hdvd⟩\n    exact Nat.not_lt_zero p hlt\n\n/-- An elementary upper bound converts the integer spectral check to real-log width. -/\ntheorem log_nat_le_clog (a : ℕ) (ha : 0<a) : Real.log (a : ℝ) ≤ (Nat.clog 2 a : ℝ) := by\n  have hp : (a : ℝ) ≤ (2 : ℝ)^Nat.clog 2 a := by exact_mod_cast Nat.le_pow_clog (by decide) a\n  have hl := Real.log_le_log (by exact_mod_cast ha) hp\n  rw [Real.log_pow] at hl\n  have htwo : Real.log (2 : ℝ) ≤ 1 := by\n    simpa only [show (2 : ℝ)-1=1 by norm_num] using Real.log_le_sub_one_of_pos (by norm_num : (0 : ℝ)<2)\n  exact hl.trans (by simpa only [mul_one] using mul_le_mul_of_nonneg_left htwo (Nat.cast_nonneg _))\n\n/-- Casting a reciprocal product can be proved before inserting any public graph expressions. -/\ntheorem inverse_nat_cast (a b : ℕ) :\n    ((1/((a*b : ℕ) : ℚ) : ℚ) : ℝ)=1/((a : ℝ)*(b : ℝ)) := by\n  simp only [Rat.cast_div,Rat.cast_one,Nat.cast_mul,Rat.cast_mul,Rat.cast_natCast]\n\n/-- Rational positivity transfers to the real comparison without expanding its argument. -/\ntheorem rational_pos_real (q : ℚ) (h : 0<q) : (0 : ℝ)<q := by exact_mod_cast h\n/-- A rational half bound transfers without inspecting its argument's expression. -/\ntheorem rational_half_real (q : ℚ) (h : q≤1/2) : (q : ℝ)≤1/2 := by\n  have hh : (q : ℝ)≤((1/2 : ℚ) : ℝ) := Rat.cast_le.mpr h\n  simpa only [Rat.cast_div,Rat.cast_one,Rat.cast_ofNat] using hh\n/-- Reverse transfer of a real comparison on a rational value. -/\ntheorem real_pos_rational (q : ℚ) (h : (0 : ℝ)<q) : 0<q := by exact_mod_cast h\n/-- Reverse transfer of the fixed half bound. -/\ntheorem real_half_rational (q : ℚ) (h : (q : ℝ)≤1/2) : q≤1/2 := by\n  have hh : (q : ℝ)≤((1/2 : ℚ) : ℝ) := by\n    simpa only [Rat.cast_div,Rat.cast_one,Rat.cast_ofNat] using h\n  exact Rat.cast_le.mp hh\n/-- Integer spectral width casts without unfolding any public sizes. -/\ntheorem width_cast (a b c : ℕ) (h : 32*a*b≤c^2) :\n    (32 : ℝ)*(a : ℝ)*(b : ℝ)≤(c : ℝ)^2 := by exact_mod_cast h\n\n/-- Apply an integer width envelope to an explicitly bounded logarithm. -/\ntheorem width_from_log (a b c : ℕ) (x : ℝ) (hx : x≤(b : ℝ)) (h : 32*a*b≤c^2) :\n    (32 : ℝ)*(a : ℝ)*x≤(c : ℝ)^2 :=\n  (mul_le_mul_of_nonneg_left hx (mul_nonneg (by norm_num) (Nat.cast_nonneg a))).trans\n    (width_cast a b c h)\n\n/-- The actual decidable guard implies the generic published constructor's real guard. -/\ntheorem fastGuard_source (N : ℕ) (hg : fastGuard N) :\n    sourceLayoutGuard (wireCount N) (scopeBound (bitLength N)) := by\n  rcases hg with ⟨hn,hw,hr,hQ,hR,hsize,hpos,hhalf,hinc,hrow,hwidth,_hload⟩\n  have hcast : (epsilon N : ℝ)=sourceEpsilon (lambda N) := inverse_nat_cast (groups N) (lambda N)\n  have hepos : 0<sourceEpsilon (lambda N) := (rational_pos_real (epsilon N) hpos).trans_eq hcast\n  have hehalf : sourceEpsilon (lambda N)≤1/2 := by\n    calc\n      _ = (epsilon N : ℝ) := hcast.symm\n      _ ≤ _ := rational_half_real _ hhalf\n  have hprod : 0<groups N*lambda N := by\n    by_contra hz\n    have he : groups N*lambda N=0 := Nat.eq_zero_of_not_pos hz\n    simp only [epsilon,he,Nat.cast_zero,div_zero] at hpos\n    exact lt_irrefl _ hpos\n  have harg : 0<2*groups N*lambda N := by\n    simpa only [Nat.mul_assoc] using Nat.mul_pos (by decide : 0<2) hprod\n  have hid : 2/sourceEpsilon (lambda N)=((2*groups N*lambda N : ℕ) : ℝ) := by\n    simp only [sourceEpsilon,one_div,div_inv_eq_mul]\n    change 2*((groups N : ℝ)*(lambda N : ℝ))=_\n    push_cast\n    ring\n  have hlog : Real.log (2/sourceEpsilon (lambda N))≤(Nat.clog 2 (2*groups N*lambda N) : ℝ) := by\n    rw [hid]\n    exact log_nat_le_clog _ harg\n  refine ⟨hn,hw,hr,hQ,hR,hsize,hepos,hehalf,hinc,hrow,?_⟩\n  exact width_from_log (points N-1) (Nat.clog 2 (2*groups N*lambda N)) (degree N)\n    (Real.log (2/sourceEpsilon (lambda N))) hlog hwidth\n\n/-- The mathematical public guard and the two already proved executable tests\nforce the literal runtime guard to pass. -/\ntheorem fastGuard_of_public (N : ℕ)\n    (hg : sourceLayoutGuard (variableCount (bitLength N)) (scopeBound (bitLength N)))\n    (hwidth : 32*(scheduledPointCount (Nat.clog 2 (variableCount (bitLength N)))-1)*\n      Nat.clog 2 (2*scheduledGroupCount (Nat.clog 2 (variableCount (bitLength N)))*\n        Nat.clog 2 (variableCount (bitLength N))) ≤ scheduledDegree (Nat.clog 2 (variableCount (bitLength N)))^2)\n    (hload : SemiprimeScheduledCounter.scheduledEpsilon (variableCount (bitLength N))*\n      (2*variableCount (bitLength N) : ℕ)≤(variableCount (bitLength N) : ℚ)/2) : fastGuard N := by\n  rw [← wireCount_eq N] at hg hwidth hload\n  rcases hg with ⟨hn,hw,hr,hQ,hR,hsize,hpos,hhalf,hinc,hrow,_hreal⟩\n  have hcast : (epsilon N : ℝ)=sourceEpsilon (lambda N) := inverse_nat_cast (groups N) (lambda N)\n  have hposQ : 0<epsilon N := real_pos_rational _ (hpos.trans_eq hcast.symm)\n  have hhalfQ : epsilon N≤1/2 := real_half_rational _ (by\n    calc\n      (epsilon N : ℝ)=sourceEpsilon (lambda N) := hcast\n      _ ≤ _ := hhalf)\n  exact ⟨hn,hw,hr,hQ,hR,hsize,hposQ,hhalfQ,hinc,hrow,hwidth,hload⟩\n\n/-- Public bit length really tends to infinity with the integer input. -/\ntheorem bitLength_tendsto : Tendsto bitLength atTop atTop := by\n  apply Filter.tendsto_atTop.mpr\n  intro b\n  filter_upwards [eventually_ge_atTop (2^b)] with N hN\n  by_contra hz\n  have hs : bitLength N≤b := Nat.le_of_lt (Nat.lt_of_not_ge hz)\n  have hp := Nat.pow_le_pow_right (by decide : 0<2) hs\n  have hi := input_lt_bitLength_power N\n  exact Nat.not_lt_of_ge hN (hi.trans_le hp)\n\n/-- The fallback is confined to finitely many inputs: the actual fast guard passes eventually. -/\ntheorem eventually_fastGuard : ∀ᶠ N : ℕ in atTop, fastGuard N := by\n  have h := bitLength_tendsto.eventually SemiprimeScheduledCounter.eventually_public_executable_guards\n  filter_upwards [h] with N hN\n  exact fastGuard_of_public N hN.1 hN.2.1 hN.2.2\n\n/-- Eventually the runtime actually takes the source-counter branch, not the fallback. -/\ntheorem eventually_run_fast : ∀ᶠ N : ℕ in atTop,\n    ∃ hN : 0<N, ∃ hg : fastGuard N,\n      letI : NeZero (groups N) := ⟨Nat.ne_of_gt (lt_of_lt_of_le (by decide : 0<2) hg.2.2.1)⟩\n      run N=factor N hN (groups N) (points N) (epsilon N) (degree N) (precision N) := by\n  filter_upwards [eventually_fastGuard,eventually_gt_atTop 0] with N hg hN\n  exact ⟨hN,hg,by simp only [run,dite_eq_left hN,dite_eq_left (guard_groups_pos N hg),ite_eq_left hg]⟩\n\nend RiemannGaussian.SemiprimeScheduledFactorExecution\n","RiemannGaussian.SemiprimeSeedMomentPrefixRigidity":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSeedMomentCancellationObstruction\nimport Mathlib.RingTheory.PowerSeries.Inverse\nimport Mathlib.RingTheory.PowerSeries.WellKnown\n\n/-!\n# Finite-prefix certification of the original whole-family moment series\n\nThe original geometric block sum satisfies a difference equation with an\noriginal seed series of degree at most m-1. A candidate rational series\nof degree d can be certified using 2d+2(m-1)+1 genuine coefficients,\nprovided the original scale has no short resonances. The proof works over\nthe composite ring; it never assumes that ring is a field.\n\nThis is a whole-family VALIDATION theorem. It does not assert existence\nof a linear-degree candidate, an algorithm to find one, a bound for\nacquiring the genuine prefix, or a full bit-time or memory bound.\nAll polynomial presentations and infinite series here are proof-side.\n-/\n\nnamespace RiemannGaussian.SemiprimeSeedMomentPrefixRigidity\n\nopen scoped BigOperators\nopen Polynomial\nopen SemiprimeSeedMomentCancellationObstruction SemiprimeSeedPointRigidity\nopen SemiprimeDenseRowCarries SemiprimeSeedSumAcquisition\nopen SemiprimeCentreFreeCover SemiprimeLocalOrderRouting\nopen SemiprimeWrapIndexRecovery SemiprimeIntervalJet\n\n/-- A proof-side rational presentation with denominator constant one.\nNeither the presentation nor its degree is executable input advice. -/\nabbrev RationalBound {R : Type*} [CommRing R] (F : PowerSeries R) (d : ℕ) : Prop :=\n  ∃ U V : R[X], U.coeff 0=1 ∧ U.natDegree≤d ∧ V.natDegree≤d ∧\n    (U : PowerSeries R)*F=(V : PowerSeries R)\n\n/-- A zero prefix remains zero after multiplication by ANY series. -/\ntheorem zero_prefix_mul {R : Type*} [CommRing R] {H : PowerSeries R} {K : ℕ}\n    (hH : ∀ r≤K, PowerSeries.coeff r H=0) (P : PowerSeries R) :\n    ∀ r≤K, PowerSeries.coeff r (P*H)=0 := by\n  intro r hr\n  rw [PowerSeries.coeff_mul]\n  apply Finset.sum_eq_zero\n  intro ij hij\n  have he := Finset.mem_antidiagonal.mp hij\n  rw [hH ij.2 (by omega),mul_zero]\n\n/-- Degree plus a genuine zero prefix annihilates a rational series.\nCancellation uses a unit constant, not a domain assumption. -/\ntheorem rational_zero_of_prefix {R : Type*} [CommRing R] {H : PowerSeries R} {K : ℕ}\n    (hH : RationalBound H K) (hzero : ∀ r≤K, PowerSeries.coeff r H=0) : H=0 := by\n  obtain ⟨U,V,hU,_,hV,hUV⟩ := hH\n  have hVzero : V=0 := by\n    ext r\n    by_cases hr : r≤K\n    · have he := zero_prefix_mul hzero (U : PowerSeries R) r hr\n      rw [hUV,Polynomial.coeff_coe] at he\n      exact he\n    · exact coeff_eq_zero_of_natDegree_lt (by omega)\n  have hunit : IsUnit (U : PowerSeries R) := by\n    apply PowerSeries.isUnit_iff_constantCoeff.mpr\n    rw [←PowerSeries.coeff_zero_eq_constantCoeff_apply,Polynomial.coeff_coe,hU]\n    exact isUnit_one\n  apply hunit.mul_left_cancel\n  simpa only [hVzero,Polynomial.coe_zero,mul_zero] using hUV\n\n/-- Addition of rational presentations charges the SUM of their degrees. -/\ntheorem rational_add {R : Type*} [CommRing R] {F G : PowerSeries R} {a b : ℕ}\n    (hF : RationalBound F a) (hG : RationalBound G b) : RationalBound (F+G) (a+b) := by\n  obtain ⟨U,V,hU,hUd,hVd,hUV⟩ := hF\n  obtain ⟨S,T,hS,hSd,hTd,hST⟩ := hG\n  refine ⟨U*S,V*S+T*U,?_,?_,?_,?_⟩\n  · simp [hU,hS]\n  · exact natDegree_mul_le.trans (Nat.add_le_add hUd hSd)\n  · apply natDegree_add_le_of_degree_le\n    · exact natDegree_mul_le.trans (Nat.add_le_add hVd hSd)\n    · exact natDegree_mul_le.trans (by omega)\n  · simp only [Polynomial.coe_mul,Polynomial.coe_add]\n    calc\n      (U : PowerSeries R)*S*(F+G)=((U : PowerSeries R)*F)*S+\n          ((S : PowerSeries R)*G)*U := by ring\n      _=(V : PowerSeries R)*S+(T : PowerSeries R)*U := by rw [hUV,hST]\n\n/-- Subtraction has the same composite-ring-safe degree bound. -/\ntheorem rational_sub {R : Type*} [CommRing R] {F G : PowerSeries R} {a b : ℕ}\n    (hF : RationalBound F a) (hG : RationalBound G b) : RationalBound (F-G) (a+b) := by\n  obtain ⟨U,V,hU,hUd,hVd,hUV⟩ := hF\n  obtain ⟨S,T,hS,hSd,hTd,hST⟩ := hG\n  refine ⟨U*S,V*S-T*U,?_,?_,?_,?_⟩\n  · simp [hU,hS]\n  · exact natDegree_mul_le.trans (Nat.add_le_add hUd hSd)\n  · exact (natDegree_sub_le _ _).trans (max_le\n      (natDegree_mul_le.trans (Nat.add_le_add hVd hSd))\n      (natDegree_mul_le.trans (by omega)))\n  · simp only [Polynomial.coe_mul,Polynomial.coe_sub]\n    calc\n      (U : PowerSeries R)*S*(F-G)=((U : PowerSeries R)*F)*S-\n          ((S : PowerSeries R)*G)*U := by ring\n      _=(V : PowerSeries R)*S-(T : PowerSeries R)*U := by rw [hUV,hST]\n\n/-- Polynomial scaling and series rescaling agree coefficient by coefficient. -/\ntheorem polynomial_rescale {R : Type*} [CommRing R] (U : R[X]) (c : R) :\n    ((U.comp (C c*X) : R[X]) : PowerSeries R)=PowerSeries.rescale c (U : PowerSeries R) := by\n  ext r\n  rw [Polynomial.coeff_coe,comp_C_mul_X_coeff,PowerSeries.coeff_rescale,\n    Polynomial.coeff_coe,mul_comm]\n\n/-- Rescaling preserves a rational degree bound and denominator constant one. -/\ntheorem rational_rescale {R : Type*} [CommRing R] {F : PowerSeries R} {d : ℕ}\n    (hF : RationalBound F d) (c : R) : RationalBound (PowerSeries.rescale c F) d := by\n  obtain ⟨U,V,hU,hUd,hVd,hUV⟩ := hF\n  have hlinear : (C c*X : R[X]).natDegree≤1 := by\n    simpa only [pow_one] using natDegree_C_mul_X_pow_le c 1\n  refine ⟨U.comp (C c*X),V.comp (C c*X),?_,?_,?_,?_⟩\n  · simp only [comp_C_mul_X_coeff,pow_zero,mul_one,hU]\n  · exact natDegree_comp_le.trans ((Nat.mul_le_mul_left _ hlinear).trans (by simpa using hUd))\n  · exact natDegree_comp_le.trans ((Nat.mul_le_mul_left _ hlinear).trans (by simpa using hVd))\n  · rw [polynomial_rescale,polynomial_rescale,←map_mul,hUV]\n\n/-- A rational series with zero constant and no short scale resonances\ncannot hide as a nonzero invariant remainder. -/\ntheorem rational_invariant_zero {R : Type*} [CommRing R] {H : PowerSeries R} {c : R} {d : ℕ}\n    (hH : RationalBound H d) (h0 : PowerSeries.coeff 0 H=0)\n    (hinv : PowerSeries.rescale c H=H)\n    (hgaps : ∀ r, 0<r → r≤d → IsUnit (c^r-1)) : H=0 := by\n  apply rational_zero_of_prefix hH\n  intro r hr\n  by_cases hzero : r=0\n  · simpa only [hzero] using h0\n  · have he := congrArg (PowerSeries.coeff r) hinv\n    rw [PowerSeries.coeff_rescale] at he\n    apply (hgaps r (by omega) hr).mul_left_cancel\n    rw [mul_zero]\n    calc\n      (c^r-1)*PowerSeries.coeff r H=c^r*PowerSeries.coeff r H-PowerSeries.coeff r H := by ring\n      _=0 := sub_eq_zero.mpr he\n\n/-- A low-degree candidate matching a short genuine prefix agrees with\nthe ENTIRE structured family. No hidden-field computation is a premise. -/\ntheorem structured_prefix_rigidity {R : Type*} [CommRing R]\n    {A B F : PowerSeries R} {c : R} {J M Q d : ℕ}\n    (hA : RationalBound A M) (hB : RationalBound B Q) (hF : RationalBound F d)\n    (heq : PowerSeries.rescale c B-B=PowerSeries.rescale (c^J) A-A)\n    (hprefix : ∀ r≤2*(d+M), PowerSeries.coeff r F=PowerSeries.coeff r B)\n    (hgaps : ∀ r, 0<r → r≤d+Q → IsUnit (c^r-1)) : F=B := by\n  have hdiff : RationalBound (F-B) (d+Q) := rational_sub hF hB\n  have hresidual : RationalBound\n      ((PowerSeries.rescale c F-F)-(PowerSeries.rescale (c^J) A-A)) (2*(d+M)) := by\n    have hh := rational_sub (rational_sub (rational_rescale hF c) hF)\n      (rational_sub (rational_rescale hA (c^J)) hA)\n    convert hh using 1\n    omega\n  have hreszero : (PowerSeries.rescale c F-F)-(PowerSeries.rescale (c^J) A-A)=0 := by\n    apply rational_zero_of_prefix hresidual\n    intro r hr\n    rw [←heq,map_sub,map_sub,map_sub,PowerSeries.coeff_rescale,\n      PowerSeries.coeff_rescale,hprefix r hr]\n    ring\n  have hinv : PowerSeries.rescale c (F-B)=F-B := by\n    rw [map_sub]\n    rw [←heq] at hreszero\n    linear_combination hreszero\n  have h0 : PowerSeries.coeff 0 (F-B)=0 := by\n    rw [map_sub,hprefix 0 (Nat.zero_le _),sub_self]\n  exact sub_eq_zero.mp (rational_invariant_zero hdiff h0 hinv hgaps)\n\n/-- One centered geometric moment series has a linear presentation. -/\ntheorem single_moments_rational {R : Type*} [CommRing R] (x : R) :\n    RationalBound (PowerSeries.mk fun r => if r=0 then 0 else x^r) 1 := by\n  have hx : (C x*X : R[X]).natDegree≤1 := by\n    simpa only [pow_one] using natDegree_C_mul_X_pow_le x 1\n  have hs : (PowerSeries.mk fun r => if r=0 then 0 else x^r)=\n      PowerSeries.rescale x (PowerSeries.mk (1 : ℕ→R))-1 := by\n    ext r\n    by_cases hr : r=0\n    · subst r\n      rw [PowerSeries.coeff_mk,map_sub,PowerSeries.coeff_rescale,PowerSeries.coeff_mk]\n      simp\n    · simp [hr,PowerSeries.coeff_rescale]\n  refine ⟨1-C x*X,C x*X,by simp,?_,hx,?_⟩\n  · exact (natDegree_sub_le _ _).trans (max_le (by simp) hx)\n  · rw [hs]\n    have he := congrArg (PowerSeries.rescale x)\n      (PowerSeries.mk_one_mul_one_sub_eq_one R)\n    simp only [map_mul,map_sub,map_one,PowerSeries.rescale_X] at he\n    simp only [Polynomial.coe_sub,Polynomial.coe_one,Polynomial.coe_mul,\n      Polynomial.coe_C,Polynomial.coe_X]\n    calc\n      (1-PowerSeries.C x*PowerSeries.X)*\n          (PowerSeries.rescale x (PowerSeries.mk (1 : ℕ→R))-1)=\n        PowerSeries.rescale x (PowerSeries.mk (1 : ℕ→R))*\n          (1-PowerSeries.C x*PowerSeries.X)-1+PowerSeries.C x*PowerSeries.X := by ring\n      _=PowerSeries.C x*PowerSeries.X := by rw [he]; ring\n\n/-- The full finite labeled moment family has a rational presentation\nof degree at most its raw label count. This presentation is ghost data. -/\ntheorem finite_moments_rational {R ι : Type*} [CommRing R]\n    (S : Finset ι) (x : ι→R) :\n    RationalBound (∑ i∈S,PowerSeries.mk fun r => if r=0 then 0 else (x i)^r) S.card := by\n  classical\n  induction S using Finset.induction_on with\n  | empty =>\n    refine ⟨1,0,by simp,by simp,by simp,by simp⟩\n  | @insert i S hi ih =>\n    rw [Finset.sum_insert hi,Finset.card_insert_of_notMem hi]\n    simpa only [Nat.add_comm 1] using rational_add (single_moments_rational (x i)) ih\n\n/-- The ORIGINAL centered seed series has degree at most m-1. -/\ntheorem original_seed_rational {N : ℕ} (g : (ZMod N)ˣ) (m : ℕ) :\n    RationalBound (centredSeedSeries g m) (m-1) := by\n  have he : centredSeedSeries g m=\n      ∑ j∈Finset.range (m-1),PowerSeries.mk fun r => if r=0 then 0 else\n        (((progressionSeed g N m (j+1)).step : ZMod N)^r) := by\n    ext r\n    simp only [centredSeedSeries,PowerSeries.coeff_mk,map_sum]\n    by_cases hr : r=0\n    · simp [hr]\n    · simp only [ite_eq_right hr,seedMoment]\n  rw [he]\n  simpa only [Finset.card_range] using finite_moments_rational (Finset.range (m-1))\n    (fun j => ((progressionSeed g N m (j+1)).step : ZMod N))\n\n/-- The complete ORIGINAL normalized grid has degree at most (m-1)J.\nThe large product is used only in the proof, never by a constructor. -/\ntheorem original_grid_rational {N : ℕ} (g : (ZMod N)ˣ) (m w J : ℕ) :\n    RationalBound (centredGridSeries g m w J) ((m-1)*J) := by\n  have he : centredGridSeries g m w J=\n      ∑ jk∈(Finset.range (m-1)) ×ˢ (Finset.range J),\n        PowerSeries.mk fun r => if r=0 then 0 else (seedPoint g m w (jk.1+1) jk.2)^r := by\n    ext r\n    simp only [centredGridSeries,PowerSeries.coeff_mk,map_sum]\n    by_cases hr : r=0\n    · simp [hr]\n    · simp only [ite_eq_right hr,gridMoment,Finset.sum_product]\n  rw [he]\n  simpa only [Finset.card_product,Finset.card_range] using\n    finite_moments_rational ((Finset.range (m-1)) ×ˢ (Finset.range J))\n      (fun jk => seedPoint g m w (jk.1+1) jk.2)\n\n/-- The exact difference equation of the ORIGINAL family, including\ncoefficients where division by a geometric denominator is impossible. -/\ntheorem original_moment_equation {N : ℕ} (g : (ZMod N)ˣ) (m w J : ℕ) :\n    let c := (((((seedBase g m)^w)⁻¹ : (ZMod N)ˣ) : ZMod N))\n    PowerSeries.rescale c (centredGridSeries g m w J)-centredGridSeries g m w J=\n      PowerSeries.rescale (c^J) (centredSeedSeries g m)-centredSeedSeries g m := by\n  dsimp only\n  ext r\n  by_cases hr : r=0\n  · subst r\n    rw [map_sub,map_sub,PowerSeries.coeff_rescale,PowerSeries.coeff_rescale]\n    simp [centredGridSeries,centredSeedSeries]\n  · rw [map_sub,map_sub,PowerSeries.coeff_rescale,PowerSeries.coeff_rescale,\n      centredGridSeries_coeff g m w J r (by omega),centredSeedSeries_coeff g m r (by omega)]\n    have he := gridMoment_geometric_difference g m w J r\n    rw [pow_right_comm] at he\n    linear_combination he\n\n/-- Roughness preserves both hidden local periods at the public width\n4m. Orders remain proof-side; the constructor receives only public data. -/\ntheorem original_linear_scale_orders {p q m : ℕ} (hm : 4≤m)\n    (g : (ZMod (p*q))ˣ) (hlong : LongData g m) :\n    let h := projectedUnit g m\n    let c := ((seedBase h m)^(4*m))⁻¹\n    orderOf (leftUnit c)=orderOf (leftUnit h) ∧\n      orderOf (rightUnit c)=orderOf (rightUnit h) := by\n  have he : m^2*(4*m)=4*m^3 := by ring\n  have hp := (rough_coprime_small (by omega : 0<4) hm hlong.2.2.2.2.2.1).mul_right\n    ((rough_coprime_small (by omega : 0<m) le_rfl hlong.2.2.2.2.2.1).pow_right 3)\n  have hq := (rough_coprime_small (by omega : 0<4) hm hlong.2.2.2.2.2.2).mul_right\n    ((rough_coprime_small (by omega : 0<m) le_rfl hlong.2.2.2.2.2.2).pow_right 3)\n  constructor\n  · simpa only [leftUnit,seedBase,map_inv,orderOf_inv,map_pow,←pow_mul,he] using hp.orderOf_pow\n  · simpa only [rightUnit,seedBase,map_inv,orderOf_inv,map_pow,←pow_mul,he] using hq.orderOf_pow\n\n/-- No original linear-width scale resonance survives in this entire\nquadratic coefficient window, in EITHER prime reduction. -/\ntheorem original_linear_scale_gaps {p q m : ℕ} (hp : p.Prime) (hq : q.Prime) (hm : 4≤m)\n    (g : (ZMod (p*q))ˣ) (hlong : LongData g m) :\n    let c := (((((seedBase (projectedUnit g m) m)^(4*m))⁻¹ : (ZMod (p*q))ˣ) : ZMod (p*q)))\n    ∀ r, 0<r → r≤2*m^2 → IsUnit (c^r-1) := by\n  dsimp only\n  let c := ((seedBase (projectedUnit g m) m)^(4*m))⁻¹\n  have hord := original_linear_scale_orders hm g hlong\n  have hleft : 4*m^2<orderOf (leftUnit c) := by\n    rw [hord.1]\n    nlinarith only [hlong.2.2.2.1.1]\n  have hright : 4*m^2<orderOf (rightUnit c) := by\n    rw [hord.2]\n    nlinarith only [hlong.2.2.2.1.2]\n  intro r hr hrbound\n  apply isUnit_of_prime_reductions hp hq\n  · rw [map_sub,map_pow,map_one]\n    apply sub_ne_zero.mpr\n    intro he\n    have hu : (leftUnit c)^r=(leftUnit c)^0 := by\n      apply Units.ext\n      simp only [Units.val_pow_eq_pow_val,pow_zero,Units.val_one]\n      change (ZMod.castHom (dvd_mul_right p q) (ZMod p) (c : ZMod (p*q)))^r=1\n      exact he\n    have heq := pow_injOn_Iio_orderOf (by omega : r<orderOf (leftUnit c))\n      (by omega : 0<orderOf (leftUnit c)) hu\n    omega\n  · rw [map_sub,map_pow,map_one]\n    apply sub_ne_zero.mpr\n    intro he\n    have hu : (rightUnit c)^r=(rightUnit c)^0 := by\n      apply Units.ext\n      simp only [Units.val_pow_eq_pow_val,pow_zero,Units.val_one]\n      change (ZMod.castHom (dvd_mul_left q p) (ZMod q) (c : ZMod (p*q)))^r=1\n      exact he\n    have heq := pow_injOn_Iio_orderOf (by omega : r<orderOf (rightUnit c))\n      (by omega : 0<orderOf (rightUnit c)) hu\n    omega\n\n/-- Linear-many genuine coefficients certify a degree-at-most-m\ncandidate for the FULL padded original family. Existence is NOT asserted. -/\ntheorem original_linear_prefix_rigidity {p q m d : ℕ}\n    (hp : p.Prime) (hq : q.Prime) (hm : 4≤m) (hd : d≤m)\n    (g : (ZMod (p*q))ˣ) (hlong : LongData g m)\n    (F : PowerSeries (ZMod (p*q))) (hF : RationalBound F d)\n    (hprefix : ∀ r≤2*(d+(m-1)), PowerSeries.coeff r F=\n      PowerSeries.coeff r (centredGridSeries (projectedUnit g m) m (4*m)\n        (seedLength m/(4*m)+1))) :\n    F=centredGridSeries (projectedUnit g m) m (4*m)\n      (seedLength m/(4*m)+1) := by\n  have hcount := (linear_moment_grid_count hm).2.2\n  apply structured_prefix_rigidity (original_seed_rational _ m)\n    (original_grid_rational _ m (4*m) _) hF (original_moment_equation _ m (4*m) _) hprefix\n  intro r hr hrbound\n  apply original_linear_scale_gaps hp hq hm g hlong r hr\n  have hm2 : m≤m^2 := by nlinarith only [hm]\n  omega\n\n/-- A concrete finite polynomial certificate replaces the unknown\ninfinite candidate by U,V and genuine prefix equations. -/\ntheorem structured_polynomial_prefix_certificate {R : Type*} [CommRing R]\n    {A B : PowerSeries R} {c : R} {J M Q d : ℕ}\n    (hA : RationalBound A M) (hB : RationalBound B Q)\n    (heq : PowerSeries.rescale c B-B=PowerSeries.rescale (c^J) A-A)\n    (hgaps : ∀ r, 0<r → r≤d+Q → IsUnit (c^r-1))\n    (U V : R[X]) (hU : U.coeff 0=1) (hUd : U.natDegree≤d) (hVd : V.natDegree≤d)\n    (hprefix : ∀ r≤2*(d+M), PowerSeries.coeff r ((U : PowerSeries R)*B)=V.coeff r) :\n    (U : PowerSeries R)*B=(V : PowerSeries R) := by\n  have hconstant : PowerSeries.constantCoeff (U : PowerSeries R)=(1 : Rˣ) := by\n    rw [←PowerSeries.coeff_zero_eq_constantCoeff_apply,Polynomial.coeff_coe,hU,Units.val_one]\n  let I := PowerSeries.invOfUnit (U : PowerSeries R) 1\n  have hUI : (U : PowerSeries R)*I=1 := PowerSeries.mul_invOfUnit _ _ hconstant\n  have hIU : I*(U : PowerSeries R)=1 := PowerSeries.invOfUnit_mul _ _ hconstant\n  let F := I*(V : PowerSeries R)\n  have hUV : (U : PowerSeries R)*F=(V : PowerSeries R) := by\n    dsimp only [F]\n    rw [←mul_assoc,hUI,one_mul]\n  have hzero : ∀ r≤2*(d+M), PowerSeries.coeff r ((U : PowerSeries R)*(F-B))=0 := by\n    intro r hr\n    rw [mul_sub,hUV,map_sub,Polynomial.coeff_coe,hprefix r hr,sub_self]\n  have hplain : ∀ r≤2*(d+M), PowerSeries.coeff r (F-B)=0 := by\n    have hh := zero_prefix_mul hzero I\n    simpa only [←mul_assoc,hIU,one_mul] using hh\n  have hF : F=B := structured_prefix_rigidity hA hB ⟨U,V,hU,hUd,hVd,hUV⟩ heq\n    (fun r hr => sub_eq_zero.mp (by simpa only [map_sub] using hplain r hr)) hgaps\n  rw [←hF]\n  exact hUV\n\n/-- The public-width ORIGINAL family needs at most 4m-1 coefficients,\nincluding its already-known zero constant, to validate this finite\ndegree-at-most-m certificate. No certificate existence is inferred. -/\ntheorem original_linear_polynomial_certificate {p q m d : ℕ}\n    (hp : p.Prime) (hq : q.Prime) (hm : 4≤m) (hd : d≤m)\n    (g : (ZMod (p*q))ˣ) (hlong : LongData g m)\n    (U V : (ZMod (p*q))[X]) (hU : U.coeff 0=1)\n    (hUd : U.natDegree≤d) (hVd : V.natDegree≤d)\n    (hprefix : ∀ r≤2*(d+(m-1)), PowerSeries.coeff r\n      ((U : PowerSeries (ZMod (p*q)))*centredGridSeries (projectedUnit g m) m (4*m)\n        (seedLength m/(4*m)+1))=V.coeff r) :\n    2*(d+(m-1))+1≤4*m-1 ∧\n      (U : PowerSeries (ZMod (p*q)))*centredGridSeries (projectedUnit g m) m (4*m)\n        (seedLength m/(4*m)+1)=(V : PowerSeries (ZMod (p*q))) := by\n  refine ⟨by omega,?_⟩\n  apply structured_polynomial_prefix_certificate (original_seed_rational _ m)\n    (original_grid_rational _ m (4*m) _) (original_moment_equation _ m (4*m) _)\n    _ U V hU hUd hVd hprefix\n  intro r hr hrbound\n  apply original_linear_scale_gaps hp hq hm g hlong r hr\n  have hcount := (linear_moment_grid_count hm).2.2\n  have hm2 : m≤m^2 := by nlinarith only [hm]\n  omega\n\n/-- The same certificate applies throughout the quadratic degree\nwindow. In particular, degrees of the form m times a polylogarithmic\nfactor are allowed whenever they remain at most m^2. -/\ntheorem original_polynomial_prefix_certificate {p q m d : ℕ}\n    (hp : p.Prime) (hq : q.Prime) (hm : 4≤m) (hd : d≤m^2)\n    (g : (ZMod (p*q))ˣ) (hlong : LongData g m)\n    (U V : (ZMod (p*q))[X]) (hU : U.coeff 0=1)\n    (hUd : U.natDegree≤d) (hVd : V.natDegree≤d)\n    (hprefix : ∀ r≤2*(d+(m-1)), PowerSeries.coeff r\n      ((U : PowerSeries (ZMod (p*q)))*centredGridSeries (projectedUnit g m) m (4*m)\n        (seedLength m/(4*m)+1))=V.coeff r) :\n    (U : PowerSeries (ZMod (p*q)))*centredGridSeries (projectedUnit g m) m (4*m)\n      (seedLength m/(4*m)+1)=(V : PowerSeries (ZMod (p*q))) := by\n  apply structured_polynomial_prefix_certificate (original_seed_rational _ m)\n    (original_grid_rational _ m (4*m) _) (original_moment_equation _ m (4*m) _)\n    _ U V hU hUd hVd hprefix\n  intro r hr hrbound\n  apply original_linear_scale_gaps hp hq hm g hlong r hr\n  have hcount := (linear_moment_grid_count hm).2.2\n  omega\n\n/-- Finite-prefix whole-family validation attaches to the ACTUAL\nN-only public long route. It supplies no private factor, order, candidate\nexistence, or acquisition-cost premise to an executable algorithm. -/\ntheorem actual_public_route_prefix_certificate {p q a : ℕ}\n    (hp : p.Prime) (hq : q.Prime) (hpq : p<q)\n    (hB : 4≤SemiprimeLehmanCoverage.sixthWidth (p*q))\n    (hroute : routeAtRowModulus (p*q)=.longBase a) :\n    ∃ hc : a.Coprime (p*q),\n      let m := SemiprimeEuclidRowBudget.publicRowModulus (p*q)\n      let h := projectedUnit (ZMod.unitOfCoprime a hc) m\n      let B := centredGridSeries h m (4*m) (seedLength m/(4*m)+1)\n      ∀ (d : ℕ) (U V : (ZMod (p*q))[X]), d≤m^2 → U.coeff 0=1 →\n        U.natDegree≤d → V.natDegree≤d →\n        (∀ r≤2*(d+(m-1)), PowerSeries.coeff r ((U : PowerSeries (ZMod (p*q)))*B)=V.coeff r) →\n        (U : PowerSeries (ZMod (p*q)))*B=(V : PowerSeries (ZMod (p*q))) := by\n  have hd := routeAtRowModulus_semiprime hp hq hpq hB\n  rw [hroute] at hd\n  obtain ⟨hc,hlong⟩ := hd\n  have hN := Nat.mul_pos hp.pos hq.pos\n  have hmBounds := SemiprimeEuclidRowBudget.publicRowModulus_bounds hN\n  have hm : 4≤SemiprimeEuclidRowBudget.publicRowModulus (p*q) := hB.trans hmBounds.1\n  refine ⟨hc,?_⟩\n  dsimp only\n  intro d U V hdegree hU hUd hVd hprefix\n  exact original_polynomial_prefix_certificate hp hq hm hdegree\n    (ZMod.unitOfCoprime a hc) hlong U V hU hUd hVd hprefix\n\nend RiemannGaussian.SemiprimeSeedMomentPrefixRigidity\n","RiemannGaussian.SemiprimeSourceArrayProgramSafe":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceArrayProgramBlocks\nimport RiemannGaussian.SemiprimeSourceArrayProgramLowering\nimport RiemannGaussian.SemiprimeSourceCodeArrayHeight\n\n/-! # Original-representation safety of emitted scalar array instructions\nEvery multiplication and intermediate convolution prefix is bounded from the\noriginal operand representations. No intermediate Fits answer is an input.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2400000\nnamespace RiemannGaussian.SemiprimeSourceArrayProgramSafe\nopen scoped BigOperators\nopen SemiprimeRationalBits SemiprimeJetArrayHeight\nopen SemiprimeSourceArrayProgramIR SemiprimeSourceArrayProgramBlocks\nopen SemiprimeSourceArrayProgramLowering\n\n/-- Original common integer representatives derive physical output fits. -/\ntheorem fits_representation {x : ℚ} {d B W : ℕ} (hd : 0<d)\n    (hx : Representation x d B) (hden : d<2^W) (hnum : B<2^W) : Fits x W := by\n  have h := representation_reduced_bound hd hx\n  exact ⟨h.2.trans_lt hnum,h.1.trans_lt hden⟩\n\n/-- Independent instructions preserve original operands, and hence original-derived fits. -/\ntheorem independent_safe (W : ℕ) (code : List Instruction) (start : ℕ) (env : ℕ → ℚ)\n    (hi : ∀ i∈code,i.left<start ∧ i.right<start)\n    (hf : ∀ i∈code,Fits (i.value env) W) : Safe W code start env := by\n  induction code generalizing start env with\n  | nil => trivial\n  | cons i code ih =>\n    have hhead := hi i List.mem_cons_self\n    refine ⟨hf i List.mem_cons_self,ih (start+1) (Function.update env start (i.value env)) ?_ ?_⟩\n    · intro j hj\n      have h := hi j (List.mem_cons_of_mem i hj)\n      exact ⟨by omega,by omega⟩\n    · intro j hj\n      have h := hi j (List.mem_cons_of_mem i hj)\n      simpa only [Instruction.value,Function.update_of_ne (by omega : j.left≠start),\n        Function.update_of_ne (by omega : j.right≠start)] using hf j (List.mem_cons_of_mem i hj)\n\n/-- All emitted array-add outputs fit from the original common denominator. -/\ntheorem addCode_safe (J start d B W : ℕ) (a b : ℕ → ℕ) (env : ℕ → ℚ)\n    (hd : 0<d) (ha : ∀ k<J,a k<start) (hb : ∀ k<J,b k<start)\n    (hA : ∀ k<J,Representation (env (a k)) d B)\n    (hB : ∀ k<J,Representation (env (b k)) d B)\n    (hden : d<2^W) (hnum : 2*B<2^W) : Safe W (addCode J a b) start env := by\n  apply independent_safe\n  · intro i hi\n    obtain ⟨k,hk,rfl⟩ := List.mem_map.mp hi\n    exact ⟨ha k (List.mem_range.mp hk),hb k (List.mem_range.mp hk)⟩\n  · intro i hi\n    obtain ⟨k,hk,rfl⟩ := List.mem_map.mp hi\n    have h := representation_add (hA k (List.mem_range.mp hk)) (hB k (List.mem_range.mp hk))\n    exact fits_representation hd h hden (by simpa only [two_mul] using hnum)\n\n/-- Every product AND addition in the actual dot prefix fits from original\noperand representations; the zero accumulator is an original register. -/\ntheorem dotCode_safe (zeroId start k len d B W : ℕ) (a b : ℕ → ℕ) (env : ℕ → ℚ)\n    (hd : 0<d) (hz : zeroId<start) (he : env zeroId=0)\n    (ha : ∀ i<len,a i<start) (hb : ∀ i<len,b (k-i)<start)\n    (hA : ∀ i<len,Representation (env (a i)) d B)\n    (hB : ∀ i<len,Representation (env (b (k-i))) d B)\n    (hden : d*d<2^W) (hnum : len*(B*B)<2^W) :\n    Safe W (dotCode zeroId start k a b len) start env := by\n  induction len with\n  | zero => trivial\n  | succ len ih =>\n    rw [dotCode,safe_append,dotCode_length]\n    have hprevious := ih (fun i hi => ha i (by omega)) (fun i hi => hb i (by omega))\n      (fun i hi => hA i (by omega)) (fun i hi => hB i (by omega))\n      (lt_of_le_of_lt (Nat.mul_le_mul_right _ (Nat.le_succ len)) hnum)\n    refine ⟨hprevious,?_⟩\n    let e := evaluate (dotCode zeroId start k a b len) start env\n    have ea : e (a len)=env (a len) := evaluate_old _ start _ env (ha len (by omega))\n    have eb : e (b (k-len))=env (b (k-len)) := evaluate_old _ start _ env (hb len (by omega))\n    have hprod : Representation (e (a len)*e (b (k-len))) (d*d) (B*B) := by\n      rw [ea,eb]\n      exact representation_mul (hA len (by omega)) (hB len (by omega))\n    have hprefix := dotCode_correct zeroId start k len a b env hz he\n      (fun i hi => ha i (by omega)) (fun i hi => hb i (by omega))\n    have hsum : Representation (e (accumulator zeroId start len)) (d*d) (len*(B*B)) := by\n      change Representation (evaluate (dotCode zeroId start k a b len) start env _) _ _\n      rw [hprefix]\n      have h := representation_sum (Finset.range len) (fun i => env (a i)*env (b (k-i)))\n        (d*d) (B*B) (fun i hi => representation_mul\n          (hA i (by have := Finset.mem_range.mp hi;omega))\n          (hB i (by have := Finset.mem_range.mp hi;omega)))\n      simpa only [Finset.card_range] using h\n    have hpfit := fits_representation (Nat.mul_pos hd hd) hprod hden\n      (lt_of_le_of_lt (Nat.le_mul_of_pos_left _ (Nat.succ_pos len)) hnum)\n    have hacc := accumulator_lt zeroId start len hz\n    change Safe W [⟨.mul,a len,b (k-len)⟩,\n      ⟨.add,start+2*len,accumulator zeroId start len⟩] (start+2*len) e\n    refine ⟨hpfit,?_,trivial⟩\n    change Fits ((Function.update e (start+2*len) (e (a len)*e (b (k-len)))) (start+2*len)+\n      (Function.update e (start+2*len) (e (a len)*e (b (k-len)))) (accumulator zeroId start len)) W\n    rw [Function.update_same,Function.update_of_ne (by omega : accumulator zeroId start len≠start+2*len)]\n    have hadd := representation_add hprod hsum\n    apply fits_representation (Nat.mul_pos hd hd) hadd hden\n    convert hnum using 1; ring\n\n/-- The entire emitted cached convolution is safe, including every term and\nprefix at EVERY coefficient, not only the final returned coefficient. -/\ntheorem mulCode_safe (zeroId start J d B W : ℕ) (a b : ℕ → ℕ) (env : ℕ → ℚ)\n    (hd : 0<d) (hz : zeroId<start) (he : env zeroId=0)\n    (ha : ∀ i<J,a i<start) (hb : ∀ i<J,b i<start)\n    (hA : ∀ i<J,Representation (env (a i)) d B)\n    (hB : ∀ i<J,Representation (env (b i)) d B)\n    (hden : d*d<2^W) (hnum : J*(B*B)<2^W) :\n    Safe W (mulCode zeroId start a b J) start env := by\n  induction J with\n  | zero => trivial\n  | succ J ih =>\n    rw [mulCode,safe_append]\n    refine ⟨ih (fun i hi => ha i (by omega)) (fun i hi => hb i (by omega))\n      (fun i hi => hA i (by omega)) (fun i hi => hB i (by omega))\n      (lt_of_le_of_lt (Nat.mul_le_mul_right _ (Nat.le_succ J)) hnum),?_⟩\n    let previous := mulCode zeroId start a b J\n    let next := start+previous.length\n    let e := evaluate previous start env\n    apply dotCode_safe zeroId next J (J+1) d B W a b e hd\n    · dsimp [next];omega\n    · exact (evaluate_old previous start zeroId env hz).trans he\n    · intro i hi; exact (ha i hi).trans_le (by dsimp [next];omega)\n    · intro i _; exact (hb (J-i) (by omega)).trans_le (by dsimp [next];omega)\n    · intro i hi\n      rw [show e (a i)=env (a i) from evaluate_old previous start _ env (ha i hi)]\n      exact hA i hi\n    · intro i _\n      rw [show e (b (J-i))=env (b (J-i)) from evaluate_old previous start _ env (hb _ (by omega))]\n      exact hB _ (by omega)\n    · exact hden\n    · exact hnum\n\n/-- Internal compositional safety lemma: all demanded scalar values are the\nEXACT original products/prefixes, not unknown execution-state quantities. -/\ntheorem dotCode_safe_known (zeroId start k len W : ℕ) (a b : ℕ → ℕ) (env : ℕ → ℚ)\n    (hz : zeroId<start) (he : env zeroId=0)\n    (ha : ∀ i<len,a i<start) (hb : ∀ i<len,b (k-i)<start)\n    (hprod : ∀ i<len,Fits (env (a i)*env (b (k-i))) W)\n    (hsum : ∀ m ≤ len,Fits (∑ i∈Finset.range m,env (a i)*env (b (k-i))) W) :\n    Safe W (dotCode zeroId start k a b len) start env := by\n  induction len with\n  | zero => trivial\n  | succ len ih =>\n    rw [dotCode,safe_append,dotCode_length]\n    refine ⟨ih (fun i hi => ha i (by omega)) (fun i hi => hb i (by omega))\n      (fun i hi => hprod i (by omega)) (fun m hm => hsum m (by omega)),?_⟩\n    let e := evaluate (dotCode zeroId start k a b len) start env\n    have ea : e (a len)=env (a len) := evaluate_old _ start _ env (ha len (by omega))\n    have eb : e (b (k-len))=env (b (k-len)) := evaluate_old _ start _ env (hb len (by omega))\n    have hprefix := dotCode_correct zeroId start k len a b env hz he\n      (fun i hi => ha i (by omega)) (fun i hi => hb i (by omega))\n    have hacc := accumulator_lt zeroId start len hz\n    change Safe W [⟨.mul,a len,b (k-len)⟩,\n      ⟨.add,start+2*len,accumulator zeroId start len⟩] (start+2*len) e\n    refine ⟨?_,?_,trivial⟩\n    · change Fits (e (a len)*e (b (k-len))) W\n      rw [ea,eb]\n      exact hprod len (by omega)\n    · change Fits ((Function.update e (start+2*len) (e (a len)*e (b (k-len)))) (start+2*len)+\n        (Function.update e (start+2*len) (e (a len)*e (b (k-len)))) (accumulator zeroId start len)) W\n      rw [Function.update_same,Function.update_of_ne (by omega : accumulator zeroId start len≠start+2*len)]\n      change e (accumulator zeroId start len)=_ at hprefix\n      rw [ea,eb,hprefix]\n      have hs := hsum (len+1) (by omega)\n      rw [Finset.sum_range_succ] at hs\n      simpa only [add_comm] using hs\n\n/-- Internal whole-array safety lemma with exact original scalar products and\nfinite convolution prefixes. The source specialization below proves these. -/\ntheorem mulCode_safe_known (zeroId start J W : ℕ) (a b : ℕ → ℕ) (env : ℕ → ℚ)\n    (hz : zeroId<start) (he : env zeroId=0)\n    (ha : ∀ i<J,a i<start) (hb : ∀ i<J,b i<start)\n    (hprod : ∀ k<J,∀ i ≤ k,Fits (env (a i)*env (b (k-i))) W)\n    (hsum : ∀ k<J,∀ m ≤ k+1,Fits (∑ i∈Finset.range m,env (a i)*env (b (k-i))) W) :\n    Safe W (mulCode zeroId start a b J) start env := by\n  induction J with\n  | zero => trivial\n  | succ J ih =>\n    rw [mulCode,safe_append]\n    refine ⟨ih (fun i hi => ha i (by omega)) (fun i hi => hb i (by omega))\n      (fun k hk => hprod k (by omega)) (fun k hk => hsum k (by omega)),?_⟩\n    let previous := mulCode zeroId start a b J\n    let next := start+previous.length\n    let e := evaluate previous start env\n    have ea (i : ℕ) (hi : i<J+1) : e (a i)=env (a i) := evaluate_old previous start _ env (ha i hi)\n    have eb (i : ℕ) (hi : i<J+1) : e (b i)=env (b i) := evaluate_old previous start _ env (hb i hi)\n    apply dotCode_safe_known zeroId next J (J+1) W a b e\n    · dsimp [next];omega\n    · exact (evaluate_old previous start zeroId env hz).trans he\n    · intro i hi; exact (ha i hi).trans_le (by dsimp [next];omega)\n    · intro i _; exact (hb (J-i) (by omega)).trans_le (by dsimp [next];omega)\n    · intro i hi\n      rw [ea i hi,eb (J-i) (by omega)]\n      exact hprod J (by omega) i (by omega)\n    · intro m hm\n      have heq : (∑ i∈Finset.range m,e (a i)*e (b (J-i)))=\n          ∑ i∈Finset.range m,env (a i)*env (b (J-i)) := by\n        apply Finset.sum_congr rfl\n        intro i hi\n        have him := Finset.mem_range.mp hi\n        rw [ea i (by omega),eb (J-i) (by omega)]\n      rw [heq]\n      exact hsum J (by omega) m hm\n\nend RiemannGaussian.SemiprimeSourceArrayProgramSafe\n","RiemannGaussian.SemiprimeSourceCountPowers":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceScoreWeightBits\nimport RiemannGaussian.SemiprimeReportPolynomialGrowth\n\n/-! # Acquired collision-count powers without unary cardinality expansion\nThe actual Boolean multiplier keeps its fixed base as the left operand, so\nhigh-zero padding grows only linearly with the original exponent. Natural\nexponent/control and report stages retain their explicit native interface.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeSourceCountPowers\nopen SemiprimeBitArithmetic SemiprimeSourceOffsetInputsCore\nopen SemiprimeReportPolynomialGrowth\n\n/-- Repeated physical multiplication; no native power supplies the output. -/\ndef powerBits (base : List Bool) : ℕ → NatRun\n  | 0 => ⟨[true],1⟩\n  | k+1 =>\n    let old := powerBits base k\n    let out := mulBits base old.bits\n    ⟨out.bits,old.clock+bitCost out+out.bits.length+3⟩\n\n/-- The returned bits encode the exact power on every original exponent. -/\ntheorem powerBits_value (base : List Bool) (k : ℕ) :\n    bitValue (powerBits base k).bits=bitValue base^k := by\n  induction k with\n  | zero => rfl\n  | succ k ih => simp only [powerBits,mulBits_correct,ih,pow_succ,Nat.mul_comm]\n\n/-- Fixing the multiplier's left operand prevents repeated doubling of padding. -/\ntheorem powerBits_length (base : List Bool) (k : ℕ) :\n    (powerBits base k).bits.length ≤ 2*k*base.length+1 := by\n  induction k with\n  | zero => simp [powerBits]\n  | succ k ih =>\n    have hm := mulBits_length base (powerBits base k).bits\n    simp only [powerBits]\n    nlinarith\n\n/-- A single physical product and its returned payload scan at exponent cap K. -/\ndef stepBudget (B K : ℕ) : ℕ :=\n  12*B*(B+(2*K*B+1)+2)+1+(2*K*B+1)+3\n\n/-- All repeated products and output-cell work are bounded without a power oracle. -/\ntheorem powerBits_clock (base : List Bool) (k K : ℕ) (hk : k ≤ K) :\n    (powerBits base k).clock ≤ 1+k*stepBudget base.length K := by\n  induction k with\n  | zero => simp [powerBits]\n  | succ k ih =>\n    have hc := ih (by omega)\n    have hl := powerBits_length base k\n    have ho := powerBits_length base (k+1)\n    have hm := mulBits_cost base (powerBits base k).bits\n    have hk' : k ≤ K := by omega\n    have hx : (powerBits base k).bits.length ≤ 2*K*base.length+1 := by\n      exact hl.trans (Nat.add_le_add_right (Nat.mul_le_mul_right base.length\n        (Nat.mul_le_mul_left 2 hk')) 1)\n    have hy : (powerBits base (k+1)).bits.length ≤ 2*K*base.length+1 := by\n      exact ho.trans (Nat.add_le_add_right (Nat.mul_le_mul_right base.length\n        (Nat.mul_le_mul_left 2 hk)) 1)\n    have hp : bitCost (mulBits base (powerBits base k).bits) ≤\n        12*base.length*(base.length+(2*K*base.length+1)+2)+1 := by\n      apply hm.trans\n      gcongr\n    change (powerBits base k).clock+bitCost (mulBits base (powerBits base k).bits)+\n      (powerBits base (k+1)).bits.length+3 ≤ _\n    unfold stepBudget at hc ⊢\n    nlinarith\n\n/-- Four physically acquired constants shared by every original score term. -/\nstructure Powers where\n  /-- L squared, where the original alphabet has L=r^Q words. -/\n  square : List Bool\n  /-- L cubed. -/\n  cube : List Bool\n  /-- L to the fourth power, the original padding denominator. -/\n  fourth : List Bool\n  /-- The distinct-key head count, r to the power 4Q-1. -/\n  head : List Bool\n  /-- All input acquisition and physical multiplication reports. -/\n  clock : ℕ\n\n/-- Acquire only original r, then produce all four constants physically. -/\ndef acquire (r Q : ℕ) : Powers :=\n  let base := natBits r\n  let square := powerBits base.bits (2*Q)\n  let cube := powerBits base.bits (3*Q)\n  let fourth := powerBits base.bits (4*Q)\n  let head := powerBits base.bits (4*Q-1)\n  ⟨square.bits,cube.bits,fourth.bits,head.bits,\n    base.clock+square.clock+cube.clock+fourth.clock+head.clock+5⟩\n\n/-- The actual acquired payloads, with no input encoded-power or count advice. -/\ntheorem acquire_value (r Q : ℕ) :\n    bitValue (acquire r Q).square=r^(2*Q) ∧\n    bitValue (acquire r Q).cube=r^(3*Q) ∧\n    bitValue (acquire r Q).fourth=r^(4*Q) ∧\n    bitValue (acquire r Q).head=r^(4*Q-1) := by\n  simp only [acquire,powerBits_value,natBits_value,and_self]\n\n/-- A common actual array bound polynomial in original r,Q, independent of L^4. -/\ndef width (r Q : ℕ) : ℕ := 8*Q*(r+1)+1\n\n/-- All four payload widths follow physical multiplication growth. -/\ntheorem acquire_length (r Q : ℕ) :\n    (acquire r Q).square.length ≤ width r Q ∧\n    (acquire r Q).cube.length ≤ width r Q ∧\n    (acquire r Q).fourth.length ≤ width r Q ∧\n    (acquire r Q).head.length ≤ width r Q := by\n  have hb := natBits_length r\n  have h2 := powerBits_length (natBits r).bits (2*Q)\n  have h3 := powerBits_length (natBits r).bits (3*Q)\n  have h4 := powerBits_length (natBits r).bits (4*Q)\n  have hh := powerBits_length (natBits r).bits (4*Q-1)\n  have hh' : 4*Q-1 ≤ 4*Q := by omega\n  have h2' : 2*(2*Q)*(natBits r).bits.length+1 ≤ width r Q := by\n    unfold width\n    nlinarith\n  have h3' : 2*(3*Q)*(natBits r).bits.length+1 ≤ width r Q := by\n    unfold width\n    nlinarith\n  have h4' : 2*(4*Q)*(natBits r).bits.length+1 ≤ width r Q := by\n    unfold width\n    nlinarith\n  have hh'' : 2*(4*Q-1)*(natBits r).bits.length+1 ≤ width r Q := by\n    apply le_trans _ h4'\n    gcongr\n  exact ⟨h2.trans h2',h3.trans h3',h4.trans h4',hh.trans hh''⟩\n\n/-- Closed input/multiplication budget with no exponential materialized factor. -/\ndef budget (r Q : ℕ) : ℕ :=\n  20*(r+1)^2+4*(1+4*Q*stepBudget (r+1) (4*Q))+5\n\n/-- The complete actual power acquisition has original-dimension polynomial work. -/\ntheorem acquire_clock (r Q : ℕ) : (acquire r Q).clock ≤ budget r Q := by\n  have hb := natBits_clock r\n  have hl := natBits_length r\n  have h2 := powerBits_clock (natBits r).bits (2*Q) (4*Q) (by omega)\n  have h3 := powerBits_clock (natBits r).bits (3*Q) (4*Q) (by omega)\n  have h4 := powerBits_clock (natBits r).bits (4*Q) (4*Q) (by omega)\n  have hh := powerBits_clock (natBits r).bits (4*Q-1) (4*Q) (by omega)\n  have hs : stepBudget (natBits r).bits.length (4*Q) ≤ stepBudget (r+1) (4*Q) := by\n    unfold stepBudget\n    gcongr\n  have h2' : 1+2*Q*stepBudget (natBits r).bits.length (4*Q) ≤\n      1+4*Q*stepBudget (r+1) (4*Q) := by gcongr; omega\n  have h3' : 1+3*Q*stepBudget (natBits r).bits.length (4*Q) ≤\n      1+4*Q*stepBudget (r+1) (4*Q) := by gcongr; omega\n  have h4' : 1+4*Q*stepBudget (natBits r).bits.length (4*Q) ≤\n      1+4*Q*stepBudget (r+1) (4*Q) := by gcongr\n  have hh' : 1+(4*Q-1)*stepBudget (natBits r).bits.length (4*Q) ≤\n      1+4*Q*stepBudget (r+1) (4*Q) := by gcongr; omega\n  unfold acquire budget\n  dsimp only\n  omega\n\n/-- Fixed constants precede the entire original-dimension family. -/\ntheorem budget_monomial : ∃ C k : ℕ,∀ r Q S,r ≤ S → Q ≤ S → budget r Q ≤ C*(S+1)^k := by\n  have hp : Bound (fun S => budget S S) := by\n    simp only [budget,stepBudget]\n    boundArithmetic\n  obtain ⟨C,k,h⟩ := hp\n  refine ⟨C,k,?_⟩\n  intro r Q S hr hQ\n  apply le_trans _ (h S)\n  simp only [budget,stepBudget]\n  gcongr\n\nend RiemannGaussian.SemiprimeSourceCountPowers\n","RiemannGaussian.SemiprimeSourceHistogramScalesBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceHistogramScales\n\n/-! # Complete original-input scale-cache work with compact query operands\nOnly original list counts and r,Q,lambda occur in the final budget. The native\nr/lambda encoding costs remain explicit; no padded M/n encoding is executed.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeSourceHistogramScalesBounds\nopen SemiprimeBitArithmetic SemiprimeSourceOffsetInputsCore\nopen SemiprimeSourceHistogramScales SemiprimeReportPolynomialGrowth\n\n/-- Paid native encoder and immediate high-zero removal. -/\ndef naturalBudget (n : ℕ) : ℕ := 20*(n+1)^2+6*(n+1)+6\n\n/-- Original native parameter setup is explicit, not a binary encoder assumption. -/\ntheorem natural_clock (n : ℕ) : (natural n).clock ≤ naturalBudget n := by\n  have hc := natBits_clock n\n  have hl := natBits_length n\n  simp only [natural,SemiprimeSourceCompactBits.trim_clock,naturalBudget]\n  omega\n\n/-- Repeated physical multiplication and final trim in actual base bit width. -/\ndef powerBudget (A k : ℕ) : ℕ :=\n  1+k*SemiprimeSourceCountPowers.stepBudget A k+6*(2*k*A+1)+6\n\n/-- The complete power clock requires only the actual original base width. -/\ntheorem power_clock (base : List Bool) (k A : ℕ) (ha : base.length ≤ A) :\n    (power base k).clock ≤ powerBudget A k := by\n  have hc := SemiprimeSourceCountPowers.powerBits_clock base k k le_rfl\n  have hl := SemiprimeSourceCountPowers.powerBits_length base k\n  have hb : SemiprimeSourceCountPowers.stepBudget base.length k ≤\n      SemiprimeSourceCountPowers.stepBudget A k := by\n    unfold SemiprimeSourceCountPowers.stepBudget\n    gcongr\n  have hl' : (SemiprimeSourceCountPowers.powerBits base k).bits.length ≤ 2*k*A+1 := by\n    apply hl.trans\n    gcongr\n  have hc' := hc.trans (Nat.add_le_add_left (Nat.mul_le_mul_left k hb) 1)\n  simp only [power,SemiprimeSourceCompactBits.trim_clock,powerBudget]\n  omega\n\n/-- Conservative physical width before and after the actual power trim. -/\ntheorem power_length (base : List Bool) (k A : ℕ) (ha : base.length ≤ A) :\n    (power base k).bits.length ≤ 2*k*A+1 := by\n  apply (SemiprimeSourceCompactBits.trim_length _).trans\n  apply (SemiprimeSourceCountPowers.powerBits_length base k).trans\n  gcongr\n\n/-- Actual multiplier and immediate trim, polynomial in its true operand widths. -/\ndef productBudget (A B : ℕ) : ℕ := 12*A*(A+B+2)+1+6*(2*A+B)+6\n\n/-- All multiplier and trim work, with no product/encoded-value advice. -/\ntheorem product_clock (a b : List Bool) (A B : ℕ) (ha : a.length ≤ A) (hb : b.length ≤ B) :\n    (product a b).clock ≤ productBudget A B := by\n  have hc := mulBits_cost a b\n  have hl := mulBits_length a b\n  have hc' : bitCost (mulBits a b) ≤ 12*A*(A+B+2)+1 := by\n    apply hc.trans\n    gcongr\n  have hl' : (mulBits a b).bits.length ≤ 2*A+B := by\n    apply hl.trans\n    gcongr\n  simp only [product,SemiprimeSourceCompactBits.trim_clock,productBudget]\n  omega\n\n/-- Actual product output width follows the multiplier and the trim scan. -/\ntheorem product_length (a b : List Bool) (A B : ℕ) (ha : a.length ≤ A) (hb : b.length ≤ B) :\n    (product a b).bits.length ≤ 2*A+B := by\n  apply (SemiprimeSourceCompactBits.trim_length _).trans\n  apply (mulBits_length a b).trans\n  gcongr\n\n/-- Seven actually executed weight products and both output trims. -/\ndef weightsBudget (K : ℕ) : ℕ := SemiprimeSourceScoreWeightBits.weightBudget K+\n  12*SemiprimeSourceScoreWeightBits.weightWidth K+7\n\n/-- Weight construction is paid at its actual compact input widths. -/\ntheorem weights_clock (M n lam U : List Bool) (K : ℕ)\n    (hM : M.length ≤ K) (hn : n.length ≤ K) (hl : lam.length ≤ K) (hU : U.length ≤ K) :\n    (weights M n lam U).clock ≤ weightsBudget K := by\n  have hc := SemiprimeSourceScoreWeightBits.weights_clock M n lam U K hM hn hl hU\n  have hw := SemiprimeSourceScoreWeightBits.weights_length M n lam U K hM hn hl hU\n  simp only [weights,SemiprimeSourceCompactBits.trim_clock,weightsBudget]\n  omega\n\n/-- Physical alphabet-power width from the ALREADY trimmed original base. -/\ndef alphabetWidth (r Q : ℕ) : ℕ := 2*Q*Nat.clog 2 (r+1)+1\n/-- Conservative square width, still logarithmic in original alphabet magnitude. -/\ndef squareWidth (r Q : ℕ) : ℕ := 3*alphabetWidth r Q\n/-- Query weight input width uses compact M,n,lambda, not their padded encodings. -/\ndef inputWidth (r Q lam M n : ℕ) : ℕ :=\n  Nat.clog 2 (M+1)+Nat.clog 2 (n+1)+Nat.clog 2 (lam+1)+squareWidth r Q\n\n/-- Actual compact weight operands all fit the original-derived logarithmic bound. -/\ntheorem acquire_weight_input_widths {A B : Type*} (r Q lam : ℕ)\n    (records : List A) (vertices : List B) :\n    (SemiprimeSourceHistogramCountInput.count records).bits.length ≤\n        inputWidth r Q lam records.length vertices.length ∧\n    (SemiprimeSourceHistogramCountInput.count vertices).bits.length ≤\n        inputWidth r Q lam records.length vertices.length ∧\n    (natural lam).bits.length ≤ inputWidth r Q lam records.length vertices.length ∧\n    (product (power (natural r).bits Q).bits (power (natural r).bits Q).bits).bits.length ≤\n        inputWidth r Q lam records.length vertices.length := by\n  have hM := SemiprimeSourceHistogramCountInput.count_length records\n  have hn := SemiprimeSourceHistogramCountInput.count_length vertices\n  have hl := natural_length lam\n  have hL := power_length (natural r).bits Q (Nat.clog 2 (r+1)) (natural_length r)\n  have hU := product_length (power (natural r).bits Q).bits (power (natural r).bits Q).bits\n    (alphabetWidth r Q) (alphabetWidth r Q) hL hL\n  unfold inputWidth squareWidth\n  exact ⟨by omega,by omega,by omega,by omega⟩\n\n/-- Complete original list/dimension scale-cache budget; no unary L/L⁴ appears. -/\ndef budget (r Q lam M n : ℕ) : ℕ :=\n  M*SemiprimeSourceHistogramCountInput.stepBudget M+1+\n  (n*SemiprimeSourceHistogramCountInput.stepBudget n+1)+\n  naturalBudget r+naturalBudget lam+\n  powerBudget (Nat.clog 2 (r+1)) Q+\n  productBudget (alphabetWidth r Q) (alphabetWidth r Q)+\n  productBudget (squareWidth r Q) (squareWidth r Q)+\n  powerBudget (Nat.clog 2 (r+1)) (4*Q-1)+\n  weightsBudget (inputWidth r Q lam M n)+20\n\n/-- The actual original-input scale cache retains every lower acquisition report. -/\ntheorem acquire_clock {A B : Type*} (r Q lam : ℕ) (records : List A) (vertices : List B) :\n    (acquire r Q lam records vertices).clock ≤ budget r Q lam records.length vertices.length := by\n  have hM := SemiprimeSourceHistogramCountInput.count_clock records\n  have hn := SemiprimeSourceHistogramCountInput.count_clock vertices\n  have hr := natural_clock r\n  have hl := natural_clock lam\n  have hL := power_clock (natural r).bits Q (Nat.clog 2 (r+1)) (natural_length r)\n  have hG := power_clock (natural r).bits (4*Q-1) (Nat.clog 2 (r+1)) (natural_length r)\n  have hLl := power_length (natural r).bits Q (Nat.clog 2 (r+1)) (natural_length r)\n  have hL2 := product_clock (power (natural r).bits Q).bits (power (natural r).bits Q).bits\n    (alphabetWidth r Q) (alphabetWidth r Q) hLl hLl\n  have hL2l : (product (power (natural r).bits Q).bits (power (natural r).bits Q).bits).bits.length ≤\n      squareWidth r Q := by\n    have h := product_length (power (natural r).bits Q).bits (power (natural r).bits Q).bits\n      (alphabetWidth r Q) (alphabetWidth r Q) hLl hLl\n    unfold squareWidth\n    omega\n  have hL4 := product_clock\n    (product (power (natural r).bits Q).bits (power (natural r).bits Q).bits).bits\n    (product (power (natural r).bits Q).bits (power (natural r).bits Q).bits).bits\n    (squareWidth r Q) (squareWidth r Q) hL2l hL2l\n  have hw := acquire_weight_input_widths r Q lam records vertices\n  have hweights := weights_clock\n    (SemiprimeSourceHistogramCountInput.count records).bits\n    (SemiprimeSourceHistogramCountInput.count vertices).bits (natural lam).bits\n    (product (power (natural r).bits Q).bits (power (natural r).bits Q).bits).bits\n    (inputWidth r Q lam records.length vertices.length) hw.1 hw.2.1 hw.2.2.1 hw.2.2.2\n  unfold acquire budget\n  dsimp only\n  omega\n\n/-- Compact-width logarithms admit an elementary conservative original-resource cap. -/\ntheorem clog_cap (x S : ℕ) (hx : x ≤ S) : Nat.clog 2 (x+1) ≤ S+1 := by\n  apply le_trans _ (Nat.add_le_add_right hx 1)\n  apply (Nat.clog_le_iff_le_pow (by decide : 1<(2:ℕ))).2\n  exact Nat.lt_two_pow_self.le\n\n/-- Physical power setup budgets are monotone in actual operand width and exponent. -/\ntheorem powerBudget_mono {A k A' k' : ℕ} (hA : A ≤ A') (hk : k ≤ k') :\n    powerBudget A k ≤ powerBudget A' k' := by\n  unfold powerBudget SemiprimeSourceCountPowers.stepBudget\n  gcongr\n\n/-- Physical product setup budgets are monotone in actual operand widths. -/\ntheorem productBudget_mono {A B A' B' : ℕ} (hA : A ≤ A') (hB : B ≤ B') :\n    productBudget A B ≤ productBudget A' B' := by\n  unfold productBudget\n  gcongr\n\n/-- Compact-weight setup budgets are monotone in actual input-width caps. -/\ntheorem weightsBudget_mono {K K' : ℕ} (h : K ≤ K') : weightsBudget K ≤ weightsBudget K' := by\n  unfold weightsBudget SemiprimeSourceScoreWeightBits.weightBudget SemiprimeSourceScoreWeightBits.weightWidth\n  gcongr\n\n/-- A single polynomial expression covers the entire original input family.\nThis conservative setup envelope does not replace the proved compact query widths. -/\ndef polynomialBudget (S : ℕ) : ℕ :=\n  2*(S*(30*((S+1)+2)+20)+1)+2*naturalBudget S+\n  powerBudget (S+1) S+\n  productBudget (2*S*(S+1)+1) (2*S*(S+1)+1)+\n  productBudget (3*(2*S*(S+1)+1)) (3*(2*S*(S+1)+1))+\n  powerBudget (S+1) (4*S)+weightsBudget (3*(S+1)+3*(2*S*(S+1)+1))+20\n\n/-- Every original dimension/list count discharges this conservative numeric cap. -/\ntheorem budget_polynomial (r Q lam M n S : ℕ)\n    (hr : r ≤ S) (hQ : Q ≤ S) (hl : lam ≤ S) (hM : M ≤ S) (hn : n ≤ S) :\n    budget r Q lam M n ≤ polynomialBudget S := by\n  have hlogr := clog_cap r S hr\n  have hlogl := clog_cap lam S hl\n  have hlogM := clog_cap M S hM\n  have hlogn := clog_cap n S hn\n  have hMc : M*SemiprimeSourceHistogramCountInput.stepBudget M+1 ≤\n      S*(30*((S+1)+2)+20)+1 := by\n    unfold SemiprimeSourceHistogramCountInput.stepBudget\n    gcongr\n  have hnc : n*SemiprimeSourceHistogramCountInput.stepBudget n+1 ≤\n      S*(30*((S+1)+2)+20)+1 := by\n    unfold SemiprimeSourceHistogramCountInput.stepBudget\n    gcongr\n  have hrn : naturalBudget r ≤ naturalBudget S := by unfold naturalBudget;gcongr\n  have hln : naturalBudget lam ≤ naturalBudget S := by unfold naturalBudget;gcongr\n  have hAw : alphabetWidth r Q ≤ 2*S*(S+1)+1 := by unfold alphabetWidth;gcongr\n  have hSw : squareWidth r Q ≤ 3*(2*S*(S+1)+1) := by unfold squareWidth;gcongr\n  have hIw : inputWidth r Q lam M n ≤ 3*(S+1)+3*(2*S*(S+1)+1) := by\n    unfold inputWidth\n    omega\n  have hP := powerBudget_mono hlogr hQ\n  have hG := powerBudget_mono hlogr (show 4*Q-1 ≤ 4*S by omega)\n  have hS := productBudget_mono hAw hAw\n  have hF := productBudget_mono hSw hSw\n  have hW := weightsBudget_mono hIw\n  unfold budget polynomialBudget\n  omega\n\n/-- Fixed constants precede all original dimensions and actual metadata lists. -/\ntheorem acquire_clock_monomial : ∃ C k : ℕ,∀ {A B : Type*} (r Q lam : ℕ)\n    (records : List A) (vertices : List B) (S : ℕ),\n    r ≤ S → Q ≤ S → lam ≤ S → records.length ≤ S → vertices.length ≤ S →\n    (acquire r Q lam records vertices).clock ≤ C*(S+1)^k := by\n  have hp : SemiprimeReportPolynomialGrowth.Bound polynomialBudget := by\n    change Bound (fun S => polynomialBudget S)\n    simp only [polynomialBudget,naturalBudget,powerBudget,SemiprimeSourceCountPowers.stepBudget,\n      productBudget,weightsBudget,SemiprimeSourceScoreWeightBits.weightBudget,\n      SemiprimeSourceScoreWeightBits.weightWidth]\n    boundArithmetic\n  obtain ⟨C,k,h⟩ := hp\n  refine ⟨C,k,?_⟩\n  intro A B r Q lam records vertices S hr hQ hl hM hn\n  exact (acquire_clock r Q lam records vertices).trans\n    ((budget_polynomial r Q lam records.length vertices.length S hr hQ hl hM hn).trans (h S))\n\nend RiemannGaussian.SemiprimeSourceHistogramScalesBounds\n","RiemannGaussian.SemiprimeSourceIncidenceHistogram":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceHistogramGrouping\nimport RiemannGaussian.SemiprimeSourceIncidenceCountFormula\n\n/-! # Sixteen sparse features for the actual conditional incidence count\nNo full pair list or incidence-matrix oracle is an input. Histogram bins and\nweights derive from the actual occurrence list, retaining parallel incidences.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeSourceIncidenceHistogram\nopen scoped BigOperators\nopen SemiprimeSourceHistogramGrouping SemiprimeSourceIncidencePairAverage\nopen SemiprimeSourceIncidenceCountFormula\nopen SemiprimeMaterializedScoreEnvironment\n\n/-- Four equality features: constant, free-key diagonal, fixed-label bucket,\nand fixed-constant correction. -/\nabbrev Feature := Fin 4\n\n/-- Signed coefficients of L times the exact equality kernel. -/\ndef coefficient (L : ℚ) (f : Feature) : ℚ := ![1,L-1,L,-1] f\n\n/-- Actual per-key eligibility; fixed-label reads are needed only for feature 2. -/\ndef featureWeight (remaining : List ℕ) (f : Feature) (a : ℕ) : ℚ :=\n  if f=0 then 1 else if f=1 then if a∈remaining then 1 else 0\n  else if a∈remaining then 0 else 1\n\n/-- Each feature has one derived equality key, not a supplied histogram. -/\ndef featureKey {W : Type*} (ω : ℕ → W) (f : Feature) (a : ℕ) : ℕ ⊕ W :=\n  if f=1 then .inl a else if f=2 then .inr (ω a) else .inl 0\n\n/-- Actual weighted same-feature collision of two original keys. -/\ndef featurePair {W : Type*} [DecidableEq W] (remaining : List ℕ) (ω : ℕ → W)\n    (f : Feature) (a c : ℕ) : ℚ :=\n  if featureKey ω f a=featureKey ω f c then\n    featureWeight remaining f a*featureWeight remaining f c else 0\n\n/-- Scaled original conditional kernel, using no unknown inverse. -/\ndef kernel {W : Type*} [DecidableEq W] (L : ℚ) (remaining : List ℕ)\n    (ω : ℕ → W) (a c : ℕ) : ℚ :=\n  if a=c then L else if a∈remaining ∨ c∈remaining then 1\n  else if ω a=ω c then L else 0\n\n/-- Pointwise four-feature identity; aliases and all fixed/free cases are exact. -/\ntheorem kernel_expansion {W : Type*} [DecidableEq W] (L : ℚ)\n    (remaining : List ℕ) (ω : ℕ → W) (a c : ℕ) :\n    kernel L remaining ω a c=∑ f : Feature,coefficient L f*featurePair remaining ω f a c := by\n  classical\n  simp only [Fin.sum_univ_succ,Fin.sum_univ_zero]\n  by_cases he : a=c\n  · subst c\n    by_cases ha : a∈remaining <;>\n      simp [kernel,coefficient,featurePair,featureKey,featureWeight,ha]\n  · by_cases ha : a∈remaining <;> by_cases hc : c∈remaining <;>\n      by_cases hw : ω a=ω c <;>\n      simp [kernel,coefficient,featurePair,featureKey,featureWeight,he,ha,hc,hw]\n\n/-- Scaling by the known positive menu length matches the existing potential. -/\ntheorem kernel_potential {W : Type*} [DecidableEq W] (L : ℕ) (hL : 0<L)\n    (remaining : List ℕ) (ω : ℕ → W) (a c : ℕ) :\n    kernel (L:ℚ) remaining ω a c=(L:ℚ)*pairPotential L remaining ω a c := by\n  have hn : (L:ℚ)≠0 := by exact_mod_cast Nat.ne_of_gt hL\n  by_cases he : a=c <;> by_cases hf : a∈remaining ∨ c∈remaining <;>\n    by_cases hw : ω a=ω c <;> simp [kernel,pairPotential,he,hf,hw,hn]\n\n/-- Two-feature joint port key; it is computed from each actual port. -/\ndef jointKey {I W : Type*} (ω : ℕ → W) (owner factor : I → ℕ)\n    (f g : Feature) (i : I) : (ℕ ⊕ W) × (ℕ ⊕ W) :=\n  (featureKey ω f (owner i),featureKey ω g (factor i))\n\n/-- Literal per-port zero/one mask selects eligible feature records. -/\ndef jointWeight {I : Type*} (remaining : List ℕ) (owner factor : I → ℕ)\n    (f g : Feature) (i : I) : ℚ :=\n  featureWeight remaining f (owner i)*featureWeight remaining g (factor i)\n\n/-- One sparse feature histogram: at most one derived key per original port.\nZero-weight records may be omitted by an implementation. -/\ndef histogram {I W : Type*} [DecidableEq W] (xs : List I) (remaining : List ℕ)\n    (ω : ℕ → W) (owner factor : I → ℕ) (f g : Feature) : ℚ :=\n  ∑ k∈(xs.map (jointKey ω owner factor f g)).toFinset,\n    (bucket (jointKey ω owner factor f g) xs (jointWeight remaining owner factor f g) k)^2\n\n/-- The complete sixteen-feature scalar is derived from the original ports. -/\ndef histogramSum {I W : Type*} [DecidableEq W] (L : ℚ) (xs : List I)\n    (remaining : List ℕ) (ω : ℕ → W) (owner factor : I → ℕ) : ℚ :=\n  ∑ f : Feature,∑ g : Feature,coefficient L f*coefficient L g*\n    histogram xs remaining ω owner factor f g\n\n/-- Every feature has at most as many sparse keys as actual port occurrences. -/\ntheorem histogram_keys_bound {I W : Type*} [DecidableEq W] (xs : List I)\n    (ω : ℕ → W) (owner factor : I → ℕ) (f g : Feature) :\n    (xs.map (jointKey ω owner factor f g)).toFinset.card ≤ xs.length :=\n  sparse_keys_card _ xs\n\n/-- Joint grouping is exactly the product of the two feature collision kernels. -/\ntheorem feature_grouping {I W : Type*} [DecidableEq W] (xs : List I)\n    (remaining : List ℕ) (ω : ℕ → W) (owner factor : I → ℕ) (f g : Feature) :\n    pairs xs (fun i j => featurePair remaining ω f (owner i) (owner j)*\n      featurePair remaining ω g (factor i) (factor j))=\n      histogram xs remaining ω owner factor f g := by\n  have h := weighted_pair_grouping (jointKey ω owner factor f g) xs\n    (jointWeight remaining owner factor f g)\n  change pairs xs (fun i j => if jointKey ω owner factor f g i=jointKey ω owner factor f g j then\n      jointWeight remaining owner factor f g i*jointWeight remaining owner factor f g j else 0)=_ at h\n  unfold histogram\n  rw [← h]\n  unfold pairs\n  congr 1\n  apply List.map_congr_left\n  intro i _\n  congr 1\n  apply List.map_congr_left\n  intro j _\n  dsimp only\n  by_cases ho : featureKey ω f (owner i)=featureKey ω f (owner j) <;>\n    by_cases hf : featureKey ω g (factor i)=featureKey ω g (factor j) <;>\n    simp [featurePair,jointKey,jointWeight,ho,hf]\n  ring\n\n/-- Finite feature sums commute with the actual ordered occurrence-pair sum. -/\ntheorem pairs_sum {I A : Type*} [DecidableEq A] (xs : List I) (s : Finset A)\n    (F : A → I → I → ℚ) :\n    pairs xs (fun i j => ∑ a∈s,F a i j)=∑ a∈s,pairs xs (F a) := by\n  induction s using Finset.induction_on with\n  | empty => simp [pairs]\n  | @insert a s ha ih => simp only [Finset.sum_insert ha,pairs_add,ih]\n\n/-- The original pair sum contracts to sixteen actual sparse histograms. -/\ntheorem kernel_pairs {I W : Type*} [DecidableEq W] (L : ℚ) (xs : List I)\n    (remaining : List ℕ) (ω : ℕ → W) (owner factor : I → ℕ) :\n    pairs xs (fun i j => kernel L remaining ω (owner i) (owner j)*\n      kernel L remaining ω (factor i) (factor j))=\n      histogramSum L xs remaining ω owner factor := by\n  simp_rw [kernel_expansion]\n  simp_rw [Finset.sum_mul,Finset.mul_sum]\n  rw [pairs_sum]\n  apply Finset.sum_congr rfl\n  intro f _\n  rw [pairs_sum]\n  apply Finset.sum_congr rfl\n  intro g _\n  have hp : (fun i j => (coefficient L f*featurePair remaining ω f (owner i) (owner j))*\n      (coefficient L g*featurePair remaining ω g (factor i) (factor j)))=\n      (fun i j => (coefficient L f*coefficient L g)*\n        (featurePair remaining ω f (owner i) (owner j)*\n          featurePair remaining ω g (factor i) (factor j))) := by\n    funext i j\n    ring\n  rw [hp,pairs_scale,feature_grouping]\n\n/-- Pointwise original padded count is L² times the two scaled equality kernels. -/\ntheorem padded_kernel (r Q : ℕ) (hr : 0<r) (a b c d : ℕ)\n    (remaining : List ℕ) (env : Environment r Q) (hn : remaining.Nodup)\n    (hab : a≠b) (had : a≠d) (hcb : c≠b) (hcd : c≠d) :\n    ((SemiprimeSourceScoreCountsPadding.paddedLocal\n      (SemiprimeFiniteEnumerations.words r Q).values (.incidence a b c d) remaining env).value:ℚ)=\n      ((r^Q:ℕ):ℚ)^2*kernel ((r^Q:ℕ):ℚ) remaining (denote env) a c*\n        kernel ((r^Q:ℕ):ℚ) remaining (denote env) b d := by\n  have hL : 0<r^Q := pow_pos hr Q\n  have hv := paddedLocal_formula r Q hr a b c d remaining env hn hab had hcb hcd\n  simp only [SemiprimeSourceHeadCountFormula.alphabet] at hv\n  rw [hv,kernel_potential (r^Q) hL,kernel_potential (r^Q) hL]\n  have hp := classified_probability (r^Q) hL remaining (denote env) a b c d\n  have hden : (((r^Q:ℕ):ℚ)^4)≠0 := pow_ne_zero _ (by exact_mod_cast Nat.ne_of_gt hL)\n  have he := (eq_div_iff hden).mp hp\n  rw [← he]\n  ring\n\n/-- Exact ORIGINAL padded incidence sum, from the actual arbitrary port list.\nCross-namespace separation follows from original complete index encoding;\nparallel incidences and repeated owners/factors remain separate occurrences. -/\ntheorem original_incidence_pairs {I : Type*} (xs : List I) (owner factor : I → ℕ)\n    (r Q : ℕ) (hr : 0<r) (remaining : List ℕ) (env : Environment r Q)\n    (hn : remaining.Nodup)\n    (hcross : ∀ i∈xs,∀ j∈xs,owner i≠factor j) :\n    pairs xs (fun i j => ((SemiprimeSourceScoreCountsPadding.paddedLocal\n      (SemiprimeFiniteEnumerations.words r Q).values\n      (.incidence (owner i) (factor i) (owner j) (factor j)) remaining env).value:ℚ))=\n      ((r^Q:ℕ):ℚ)^2*histogramSum ((r^Q:ℕ):ℚ) xs remaining (denote env) owner factor := by\n  have he : pairs xs (fun i j => ((SemiprimeSourceScoreCountsPadding.paddedLocal\n        (SemiprimeFiniteEnumerations.words r Q).values\n        (.incidence (owner i) (factor i) (owner j) (factor j)) remaining env).value:ℚ))=\n      ((r^Q:ℕ):ℚ)^2*pairs xs (fun i j =>\n        kernel ((r^Q:ℕ):ℚ) remaining (denote env) (owner i) (owner j)*\n          kernel ((r^Q:ℕ):ℚ) remaining (denote env) (factor i) (factor j)) := by\n    rw [← pairs_scale]\n    unfold pairs\n    congr 1\n    apply List.map_congr_left\n    intro i hi\n    congr 1\n    apply List.map_congr_left\n    intro j hj\n    dsimp only\n    have hv := padded_kernel r Q hr (owner i) (factor i) (owner j) (factor j)\n      remaining env hn (hcross i hi i hi) (hcross i hi j hj)\n        (hcross j hj i hi) (hcross j hj j hj)\n    simpa only [mul_assoc] using hv\n  rw [he,kernel_pairs]\n\n/-- Every feature mask is a literal zero or one, independently of labels. -/\ntheorem featureWeight_zero_one (remaining : List ℕ) (f : Feature) (a : ℕ) :\n    featureWeight remaining f a=0 ∨ featureWeight remaining f a=1 := by\n  fin_cases f <;> by_cases ha : a∈remaining <;> simp [featureWeight,ha]\n\n/-- Joint port eligibility has no fractional or signed weight. -/\ntheorem jointWeight_zero_one {I : Type*} (remaining : List ℕ) (owner factor : I → ℕ)\n    (f g : Feature) (i : I) :\n    jointWeight remaining owner factor f g i=0 ∨ jointWeight remaining owner factor f g i=1 := by\n  rcases featureWeight_zero_one remaining f (owner i) with h|h <;>\n    rcases featureWeight_zero_one remaining g (factor i) with h'|h' <;>\n    simp [jointWeight,h,h']\n\n/-- The actual eligible original ports; no free-label read determines this filter. -/\ndef eligiblePorts {I : Type*} (xs : List I) (remaining : List ℕ) (owner factor : I → ℕ)\n    (f g : Feature) : List I :=\n  xs.filter (fun i => decide (jointWeight remaining owner factor f g i=1))\n\n/-- A zero/one weighted bucket is the actual filtered occurrence multiplicity. -/\ntheorem masked_bucket {I K : Type*} [DecidableEq K] (xs : List I) (label : I → K)\n    (weight : I → ℚ) (hw : ∀i,weight i=0 ∨ weight i=1) (k : K) :\n    bucket label xs weight k=\n      ((multiplicity label (xs.filter (fun i => decide (weight i=1))) k:ℕ):ℚ) := by\n  induction xs with\n  | nil => simp [bucket,SemiprimeSourceHistogramGrouping.multiplicity]\n  | cons i xs ih =>\n    rcases hw i with hi|hi <;> by_cases hk : label i=k <;>\n      simp [bucket,SemiprimeSourceHistogramGrouping.multiplicity,hi,hk] at ih ⊢ <;> linarith\n\n/-- Every sparse term is literally a square-count histogram of its filtered\noriginal port list, not an advised weighted matrix or a rational normalizer. -/\ntheorem histogram_filtered {I W : Type*} [DecidableEq W] (xs : List I)\n    (remaining : List ℕ) (ω : ℕ → W) (owner factor : I → ℕ) (f g : Feature) :\n    histogram xs remaining ω owner factor f g=\n      ∑ k∈((eligiblePorts xs remaining owner factor f g).map\n          (jointKey ω owner factor f g)).toFinset,\n        ((multiplicity (jointKey ω owner factor f g)\n          (eligiblePorts xs remaining owner factor f g) k:ℕ):ℚ)^2 := by\n  classical\n  let selected := eligiblePorts xs remaining owner factor f g\n  let label := jointKey ω owner factor f g\n  have hb (k) := masked_bucket xs label (jointWeight remaining owner factor f g)\n    (jointWeight_zero_one remaining owner factor f g) k\n  change histogram xs remaining ω owner factor f g=\n    ∑k∈(selected.map label).toFinset,((multiplicity label selected k:ℕ):ℚ)^2\n  change (∑k∈(xs.map label).toFinset,\n    (bucket label xs (jointWeight remaining owner factor f g) k)^2)=_\n  simp_rw [hb]\n  change (∑k∈(xs.map label).toFinset,((multiplicity label selected k:ℕ):ℚ)^2)=_\n  have hs : (selected.map label).toFinset ⊆ (xs.map label).toFinset := by\n    intro k hk\n    rcases List.mem_map.mp (List.mem_toFinset.mp hk) with ⟨i,hi,rfl⟩\n    have hix : i∈xs := (List.mem_filter.mp hi).1\n    exact List.mem_toFinset.mpr (List.mem_map.mpr ⟨i,hix,rfl⟩)\n  symm\n  apply Finset.sum_subset hs\n  intro k _ hk\n  have hn : k∉selected.map label := by simpa only [List.mem_toFinset] using hk\n  have hz : multiplicity label selected k=0 := by\n    unfold SemiprimeSourceHistogramGrouping.multiplicity\n    apply List.countP_eq_zero.mpr\n    intro i hi\n    simp only [decide_eq_true_eq]\n    intro he\n    exact hn (List.mem_map.mpr ⟨i,hi,he⟩)\n  rw [hz]\n  norm_num\n\nend RiemannGaussian.SemiprimeSourceIncidenceHistogram\n","RiemannGaussian.SemiprimeSourceOffsetProgramBudget":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceOffsetProgramBits\nimport RiemannGaussian.SemiprimeSourceProgramStorage\n\n/-! # Original-resource bound for the physical source-offset block\nThe conservative physical width is a magnitude bound. For the actual scheduled\nsource scales that magnitude is a FIXED polynomial of the original materialized\nresources, including U=r^(2Q). No arbitrary input magnitude is assumed polynomial\nin its own binary length. Initial encoding and the whole public caller stay separate.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeSourceOffsetProgramBudget\nopen SemiprimeRationalBits SemiprimeSourceProgramBits SemiprimeSourceOffsetProgramBits\nopen SemiprimeSourceOffsetHeight SemiprimeReportPolynomialGrowth\n\n/-- Explicit original-resource majorant of the scheduled scale denominator. -/\ndef denominatorEnvelope (S : ℕ) : ℕ := S*S*S*(2*S)\n/-- Explicit original-resource majorant of the scheduled scale numerator. -/\ndef numeratorEnvelope (S : ℕ) : ℕ := S*(2*S)+S*(S*S)*S\n/-- Actual conservative width bounded after substituting original bank and dimensions. -/\ndef widthEnvelope (S : ℕ) : ℕ :=\n  height (denominatorEnvelope S) (numeratorEnvelope S) S S S S S+1\n/-- All twelve actual instruction, operand-scan and persistent-copy reports. -/\ndef clockEnvelope (S : ℕ) : ℕ := 12*(stepBudget 19 (widthEnvelope S) 4+3)+1\n\n/-- Scheduled scales give a width polynomial in the ORIGINAL resource cap, with\nthe actual universal bank U retained as a separate input-size resource. -/\ntheorem scheduled_width_le (M n r Q lam S : ℕ)\n    (hM : M ≤ S) (hn : n ≤ S) (hr : r ≤ S) (hQ : Q ≤ S) (hlam : lam ≤ S)\n    (hU : r^(2*Q) ≤ S) :\n    width (r*lam*r^(2*Q)*(2*r)) (M*(2*r)+n*(r*lam)*r^(2*Q)) M n r Q ≤ widthEnvelope S := by\n  have hd : r*lam*r^(2*Q)*(2*r) ≤ denominatorEnvelope S := by\n    unfold denominatorEnvelope\n    gcongr\n  have hb : M*(2*r)+n*(r*lam)*r^(2*Q) ≤ numeratorEnvelope S := by\n    unfold numeratorEnvelope\n    gcongr\n  unfold width widthEnvelope height\n  gcongr\n\n/-- Actual source enumerations discharge the universal-size substitution exactly. -/\ntheorem caller_width_le {I E : Type} {n r Q : ℕ}\n    (en : SemiprimeSourceLayout.Enumerations I (Fin n) E r Q) (lam S : ℕ)\n    (hM : en.incidences.values.length ≤ S) (hn : n ≤ S) (hr : r ≤ S)\n    (hQ : Q ≤ S) (hlam : lam ≤ S) (hU : en.types.values.length ≤ S) :\n    width (r*lam*r^(2*Q)*(2*r))\n      (en.incidences.values.length*(2*r)+n*(r*lam)*r^(2*Q))\n      en.incidences.values.length n r Q ≤ widthEnvelope S := by\n  apply scheduled_width_le _ _ _ _ _ S hM hn hr hQ hlam\n  simpa only [caller_universal_length] using hU\n\n/-- The actual physical offset interpreter has a bound in original resources, once\nits seven ORIGINAL input registers have been acquired at the proved width. -/\ntheorem caller_run_clock {I E : Type} {n r Q : ℕ}\n    (en : SemiprimeSourceLayout.Enumerations I (Fin n) E r Q) (lam S : ℕ)\n    (hM : en.incidences.values.length ≤ S) (hn : n ≤ S) (hr : r ≤ S)\n    (hQ : Q ≤ S) (hlam : lam ≤ S) (hU : en.types.values.length ≤ S)\n    (memory : List RationalWord) (hlen : memory.length=7)\n    (hwidth : ∀ w∈memory,Width w (width (r*lam*r^(2*Q)*(2*r))\n      (en.incidences.values.length*(2*r)+n*(r*lam)*r^(2*Q)) en.incidences.values.length n r Q)) :\n    (run (List.replicate (width (r*lam*r^(2*Q)*(2*r))\n      (en.incidences.values.length*(2*r)+n*(r*lam)*r^(2*Q)) en.incidences.values.length n r Q) false)\n      code memory).clock ≤ clockEnvelope S := by\n  let W := width (r*lam*r^(2*Q)*(2*r))\n    (en.incidences.values.length*(2*r)+n*(r*lam)*r^(2*Q)) en.incidences.values.length n r Q\n  have hW : 1 ≤ W := by unfold W width; omega\n  have hb := run_clock (List.replicate W false) code memory 4\n    (by simpa only [List.length_replicate] using hW) (by decide) code_addresses\n    (by simpa only [List.length_replicate] using hwidth)\n  rw [List.length_replicate,code_length,hlen] at hb\n  have hw := caller_width_le en lam S hM hn hr hQ hlam hU\n  apply hb.trans\n  unfold clockEnvelope stepBudget\n  dsimp only [W]\n  gcongr\n\n/-- Uniform fixed monomial witnesses for the actual block's original-resource envelope. -/\ntheorem clockEnvelope_monomial : ∃ C k : ℕ,∀ S,clockEnvelope S ≤ C*(S+1)^k := by\n  change Bound (fun S => clockEnvelope S)\n  simp only [clockEnvelope,stepBudget,widthEnvelope,height,denominatorEnvelope,numeratorEnvelope]\n  boundArithmetic\n\nend RiemannGaussian.SemiprimeSourceOffsetProgramBudget\n","RiemannGaussian.SemiprimeSourceProgramStorage":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceProgramBits\nimport RiemannGaussian.SemiprimeReportPolynomialGrowth\n\n/-! # Concrete store and instruction payloads of the source simulator\nAll states are generated by the actual physical step. Counts conservatively\nretain every complete store version, including duplicate payloads. Arithmetic\nprimitive scratch and a full pointer/tape encoding remain separate obligations.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeSourceProgramStorage\nopen SemiprimeRationalBits SemiprimeSourceMemoryBits SemiprimeSourceProgramBits\nopen SemiprimeReportPolynomialGrowth\n\n/-- Sign plus the two physical magnitude-word payloads. -/\ndef wordCells (x : RationalWord) : ℕ := x.numerator.magnitude.length+x.denominator.length+1\n/-- All physical data cells in one stored finite memory version. -/\ndef memoryCells (memory : List RationalWord) : ℕ := (memory.map wordCells).sum\n/-- A constant-size opcode/tag allowance plus both physical address words. -/\ndef instructionCells (i : Instruction) : ℕ := i.left.length+i.right.length+6\n/-- The literal instruction bank's payload and per-instruction tags. -/\ndef codeCells (code : List Instruction) : ℕ := (code.map instructionCells).sum\n\n/-- Width bounds imply a concrete memory payload bound. -/\ntheorem memoryCells_bound (memory : List RationalWord) (W : ℕ)\n    (h : ∀ x∈memory,Width x W) : memoryCells memory ≤ memory.length*(2*W+1) := by\n  induction memory with\n  | nil => simp [memoryCells]\n  | cons x xs ih =>\n    have hx := h x List.mem_cons_self\n    have ht := ih (fun y hy => h y (List.mem_cons_of_mem x hy))\n    simp only [memoryCells,List.map_cons,List.sum_cons,List.length_cons] at ⊢\n    change wordCells x+memoryCells xs ≤ _\n    unfold wordCells\n    rcases hx with ⟨hn,hd⟩\n    nlinarith\n\n/-- No instruction descriptor has an opaque unbounded address field. -/\ntheorem codeCells_bound (code : List Instruction) (B : ℕ)\n    (h : ∀ i∈code,i.left.length ≤ B ∧ i.right.length ≤ B) :\n    codeCells code ≤ code.length*(2*B+6) := by\n  induction code with\n  | nil => simp [codeCells]\n  | cons i code ih =>\n    have hi := h i List.mem_cons_self\n    have ht := ih (fun j hj => h j (List.mem_cons_of_mem i hj))\n    simp only [codeCells,List.map_cons,List.sum_cons,List.length_cons] at ⊢\n    change instructionCells i+codeCells code ≤ _\n    unfold instructionCells\n    nlinarith\n\n/-- Proof view of the initial state and every actual post-instruction store. -/\ndef stores (template : List Bool) : List Instruction → List RationalWord → List (List RationalWord)\n  | [],memory => [memory]\n  | i::code,memory => memory::stores template code (step template i memory).memory\n\n/-- There is one real store version per instruction plus the initial one. -/\ntheorem stores_length (template : List Bool) (code : List Instruction) (memory : List RationalWord) :\n    (stores template code memory).length=code.length+1 := by\n  induction code generalizing memory with\n  | nil => simp [stores]\n  | cons i code ih => simp only [stores,List.length_cons,ih]\n\n/-- Every recorded state has bounded width and actual register count, derived from the\ninput and literal instruction traversal rather than an assumed reachable-state cap. -/\ntheorem stores_bound (template : List Bool) (code : List Instruction) (memory : List RationalWord)\n    (h : ∀ x∈memory,Width x template.length) :\n    ∀ state∈stores template code memory,\n      state.length ≤ memory.length+code.length ∧ ∀ x∈state,Width x template.length := by\n  induction code generalizing memory with\n  | nil =>\n    intro state hs\n    simp only [stores,List.mem_singleton] at hs\n    subst state\n    exact ⟨by simp,h⟩\n  | cons i code ih =>\n    intro state hs\n    simp only [stores,List.mem_cons] at hs\n    rcases hs with rfl | hs\n    · exact ⟨by simp only [List.length_cons]; omega,h⟩\n    · have ht := ih (step template i memory).memory (step_width template i memory h) state hs\n      rw [step_length] at ht\n      exact ⟨by simpa only [List.length_cons,Nat.add_assoc,Nat.add_comm,Nat.add_left_comm] using ht.1,ht.2⟩\n\n/-- The terminal executed result is a genuine state in the trace, not an abstract envelope. -/\ntheorem run_mem_stores (template : List Bool) (code : List Instruction) (memory : List RationalWord) :\n    (run template code memory).memory∈stores template code memory := by\n  induction code generalizing memory with\n  | nil => simp [run,stores]\n  | cons i code ih => exact List.mem_cons_of_mem _ (ih (step template i memory).memory)\n\n/-- A literal fixed bound for all persistent store versions, keeping every copied cell. -/\ntheorem all_store_cells (template : List Bool) (code : List Instruction) (memory : List RationalWord)\n    (h : ∀ x∈memory,Width x template.length) :\n    ((stores template code memory).map memoryCells).sum ≤\n      (code.length+1)*(memory.length+code.length)*(2*template.length+1) := by\n  have each (state : List RationalWord) (hs : state∈stores template code memory) :\n      memoryCells state ≤ (memory.length+code.length)*(2*template.length+1) := by\n    have hb := stores_bound template code memory h state hs\n    exact (memoryCells_bound state template.length hb.2).trans (Nat.mul_le_mul_right _ hb.1)\n  have sum_bound (states : List (List RationalWord)) (C : ℕ)\n      (hc : ∀ state∈states,memoryCells state ≤ C) :\n      (states.map memoryCells).sum ≤ states.length*C := by\n    induction states with\n    | nil => simp\n    | cons state states ih =>\n      have ht := ih (fun a ha => hc a (List.mem_cons_of_mem state ha))\n      have hh := hc state List.mem_cons_self\n      simp only [List.map_cons,List.sum_cons,List.length_cons]\n      nlinarith\n  have hs := sum_bound (stores template code memory)\n    ((memory.length+code.length)*(2*template.length+1)) each\n  simpa only [stores_length,Nat.mul_assoc] using hs\n\n/-- Actual program execution plus all persistent stores has fixed polynomial growth\nin original register/code/payload/address bounds. Primitive scratch is not counted twice. -/\ntheorem resource_polynomial : ∃ C k : ℕ,∀ M T W B S,\n    M ≤ S → T ≤ S → W ≤ S → B ≤ S →\n    T*(stepBudget (M+T) W B+3)+1+(T+1)*(M+T)*(2*W+1)+T*(2*B+6) ≤ C*(S+1)^k := by\n  have hp : Bound (fun S => S*(stepBudget (S+S) S S+3)+1+\n      (S+1)*(S+S)*(2*S+1)+S*(2*S+6)) := by\n    unfold stepBudget\n    boundArithmetic\n  obtain ⟨C,k,h⟩ := hp\n  refine ⟨C,k,?_⟩\n  intro M T W B S hM hT hW hB\n  apply le_trans _ (h S)\n  unfold stepBudget\n  dsimp only\n  gcongr\n\nend RiemannGaussian.SemiprimeSourceProgramStorage\n","RiemannGaussian.SemiprimeSourceRuntimeDesignBridge":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeRuntimeDesignAcquisition\nimport RiemannGaussian.SemiprimePaddedConstraintSpan\n\n/-!\n# Proof-only bridge from source row matches to the pure runtime design\n\nThe algorithm is RuntimeDesignAcquisition.build on raw integer input. Layout.Data\noccurs only in validity and rank theorems, never as an argument of that algorithm.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1400000\nnamespace RiemannGaussian.SemiprimeSourceRuntimeDesignBridge\nopen scoped BigOperators\nopen OAI.Algorithms.SubexponentialSAT.SqrtLog\nopen LayoutExactBuckets\nopen SemiprimeRuntimeDesignAcquisition SemiprimeRowSelectionExecution\n\n/-- Integer-kernel locality is unchanged by an explicitly identified coordinate order. -/\ntheorem killsIntegerKernel_equiv {V W I : Type} [Fintype V] [Fintype W]\n    (e : V ≃ W) (C : I → W → ℤ) (a : W → ℚ) (h : KillsIntegerKernel a C) :\n    KillsIntegerKernel (fun v => a (e v)) (fun i v => C i (e v)) := by\n  intro z hz\n  change (∑ v, a (e v)*(z v : ℚ))=0\n  have hold (i : I) : ∑ w, C i w*z (e.symm w)=0 := by\n    calc\n      _ = ∑ v, C i (e v)*z (e.symm (e v)) := (e.sum_comp _).symm\n      _ = 0 := by simpa only [signature, Equiv.symm_apply_apply] using hz i\n  have ha := h (fun w => z (e.symm w)) hold\n  calc\n    _ = ∑ w, a w*(z (e.symm w) : ℚ) := by\n      simpa only [Equiv.symm_apply_apply] using e.sum_comp (fun w => a w*(z (e.symm w) : ℚ))\n    _ = 0 := ha\n\nvariable {I : Type} {n F Q R : ℕ}\nvariable {owner : I → Fin n} {factor : I → Fin F}\n\n/-- The actual head sets agree by their public coordinate labels. -/\ndef headEquiv (d : RawDesign n F)\n    (L : Layout.Data (O := ℚ) (G := Fin d.r) owner factor Q R) (t : Fin Q)\n    (hhead : ∀ v, d.head v=L.head t v) (g : Fin d.r) :\n    {v : Fin n // d.head v=g} ≃ {v : Fin n // L.head t v=g} where\n  toFun v := ⟨v.val,by rw [← hhead]; exact v.property⟩\n  invFun v := ⟨v.val,by rw [hhead]; exact v.property⟩\n  left_inv _ := rfl\n  right_inv _ := rfl\n\n/-- Complete old-row coverage gives native locality for the raw constraints.\nNo raw locality conclusion or selected native-span premise is supplied. -/\ntheorem raw_locality (d : RawDesign n F)\n    (L : Layout.Data (O := ℚ) (G := Fin d.r) owner factor Q R) (t : Fin Q)\n    (hhead : ∀ v, d.head v=L.head t v)\n    (hassigned : ∀ e, d.assigned e=L.color e t)\n    (arity : Fin F → ℕ) (incidence : (e : Fin F) → Fin (arity e) → I)\n    (hfactor : ∀ e i, factor (incidence e i)=e)\n    (hold : ∀ (g : Fin d.r) (j : Fin (L.rowCount t g)),\n      ∃ k : Fin (d.count g), ∀ v : {v : Fin n // L.head t v=g},\n        d.rows g k v.val=L.constraints t g j v)\n    (e : Fin F) (i : Fin (arity e)) (g : Fin d.r) (hg : g ≠ d.assigned e) :\n    KillsIntegerKernel\n      (fun v : {v : Fin n // d.head v=g} => (L.row (incidence e i) v.val).eval (L.node t))\n      (fun j (v : {v : Fin n // d.head v=g}) => d.rows g j v.val) := by\n  have hne : g ≠ L.color (factor (incidence e i)) t := by\n    simpa only [hfactor, ← hassigned] using hg\n  have hl := L.locality t (incidence e i) g hne\n  have hcoverage : ∀ j : Fin (L.rowCount t g),\n      ∃ k : Fin (d.count g),\n        (fun v : {v : Fin n // L.head t v=g} => d.rows g k v.val)=L.constraints t g j := by\n    intro j\n    obtain ⟨k,hk⟩ := hold g j\n    exact ⟨k,funext hk⟩\n  have hraw := SemiprimePaddedConstraintSpan.killsIntegerKernel_of_complete\n    (L.constraints t g) (fun j (v : {v : Fin n // L.head t v=g}) => d.rows g j v.val)\n    hcoverage (fun v => (L.row (incidence e i) v.val).eval (L.node t)) hl\n  exact killsIntegerKernel_equiv (headEquiv d L t hhead g) _ _ hraw\n\n/-- Padding by old rows and zeros preserves the exact acquired selected count. -/\ntheorem selected_count_source (d : RawDesign n F)\n    (L : Layout.Data (O := ℚ) (G := Fin d.r) owner factor Q R) (t : Fin Q)\n    (hhead : ∀ v, d.head v=L.head t v)\n    (hnew : ∀ (g : Fin d.r) (k : Fin (d.count g)),\n      (∀ v : {v : Fin n // L.head t v=g}, d.rows g k v.val=0) ∨\n      ∃ j : Fin (L.rowCount t g), ∀ v : {v : Fin n // L.head t v=g},\n        d.rows g k v.val=L.constraints t g j v)\n    (hold : ∀ (g : Fin d.r) (j : Fin (L.rowCount t g)),\n      ∃ k : Fin (d.count g), ∀ v : {v : Fin n // L.head t v=g},\n        d.rows g k v.val=L.constraints t g j v) (g : Fin d.r) :\n    (build d).m g=LayoutRank.rowRank (L.constraints t g) := by\n  let rawOld : Fin (d.count g) → {v : Fin n // L.head t v=g} → ℤ := fun j v => d.rows g j v.val\n  let rawNew : Fin (d.count g) → {v : Fin n // d.head v=g} → ℤ := fun j v => d.rows g j v.val\n  have hcolNew := rank_column_equiv rawNew (columns d g)\n  have hcolOld := rank_column_equiv rawOld ((columns d g).trans (headEquiv d L t hhead g))\n  have heq : LayoutRank.rowRank rawNew=LayoutRank.rowRank rawOld := hcolNew.symm.trans hcolOld\n  have hp := SemiprimePaddedConstraintSpan.rowRank_eq_of_padding (L.constraints t g) rawOld\n    (fun k => by\n      rcases hnew g k with hz|⟨j,hj⟩\n      · exact Or.inl (funext hz)\n      · exact Or.inr ⟨j,funext hj⟩)\n    (fun j => by obtain ⟨k,hk⟩ := hold g j; exact ⟨k,funext hk⟩)\n  exact (SemiprimeRuntimeDesignAcquisition.selected_count d g).trans (heq.trans hp)\n\n/-- Native source validity of the pure acquired design, derived from row matches. -/\ndef sourceCertificate (d : RawDesign n F)\n    (L : Layout.Data (O := ℚ) (G := Fin d.r) owner factor Q R) (t : Fin Q)\n    (hhead : ∀ v, d.head v=L.head t v)\n    (hassigned : ∀ e, d.assigned e=L.color e t)\n    (arity : Fin F → ℕ) (incidence : (e : Fin F) → Fin (arity e) → I)\n    (hfactor : ∀ e i, factor (incidence e i)=e)\n    (hW : ∀ g j v, |d.rows g j v|≤(d.W g : ℤ))\n    (hold : ∀ (g : Fin d.r) (j : Fin (L.rowCount t g)),\n      ∃ k : Fin (d.count g), ∀ v : {v : Fin n // L.head t v=g},\n        d.rows g k v.val=L.constraints t g j v) :\n    SemiprimeIndexedNodeCertificate.Data arity (SemiprimeLayoutSelection.nodeRows L arity incidence t) :=\n  certify d arity (SemiprimeLayoutSelection.nodeRows L arity incidence t) hW\n    (raw_locality d L t hhead hassigned arity incidence hfactor hold)\n\n/-- Proof-only source validity erases to the polynomial-free integer-row algorithm. -/\ntheorem sourceCertificate_runtime (d : RawDesign n F)\n    (L : Layout.Data (O := ℚ) (G := Fin d.r) owner factor Q R) (t : Fin Q)\n    (hhead : ∀ v, d.head v=L.head t v)\n    (hassigned : ∀ e, d.assigned e=L.color e t)\n    (arity : Fin F → ℕ) (incidence : (e : Fin F) → Fin (arity e) → I)\n    (hfactor : ∀ e i, factor (incidence e i)=e)\n    (hW : ∀ g j v, |d.rows g j v|≤(d.W g : ℤ))\n    (hold : ∀ (g : Fin d.r) (j : Fin (L.rowCount t g)),\n      ∃ k : Fin (d.count g), ∀ v : {v : Fin n // L.head t v=g},\n        d.rows g k v.val=L.constraints t g j v) :\n    SemiprimeNodeArrayExecution.runtimeDesign\n      (rows := fun e i v => L.row (incidence e i) v) (t := L.node t)\n      (sourceCertificate d L t hhead hassigned arity incidence hfactor hW hold)=build d := rfl\n\nend RiemannGaussian.SemiprimeSourceRuntimeDesignBridge\n","RiemannGaussian.SemiprimeSourceScorePhysicalSearch":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceScoreCountBits\nimport RiemannGaussian.SemiprimeSourceScoreWeightAcquisition\nimport RiemannGaussian.SemiprimeSourceScoreCountOrder\nimport RiemannGaussian.SemiprimeSourceScoreChoice\n\n/-! # Original source search driven by actual physical integer counts\nWeights are acquired once. Each candidate is scored by actual Boolean terminal,\ncounter and weighted-arithmetic circuits; the physical comparator drives source\nlabel selection. Host source labels, natural loop indices and original descriptor\nconstruction remain explicit metadata interfaces, not a whole tape-machine proof.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeSourceScorePhysicalSearch\nopen SemiprimeRationalBits SemiprimeMaterializedWords\nopen OAI.Algorithms.SubexponentialSAT.MulticolorTypes\nopen SemiprimeMaterializedScoreEnvironment\n\n/-- Actual cached-input physical scores are the cancelled integer objective. -/\ntheorem score_value {r Q : ℕ} (M n lam : ℕ) (a : Word r Q) (tail : List (Word r Q))\n    (programs : List (ScoreProgram Q)) (s : ℕ) (fixed : List (Word r Q)) :\n    (SemiprimeSourceScoreCountBits.score (SemiprimeSourceScoreWeightAcquisition.acquire M n r Q lam)\n      a tail programs s fixed).word.value =\n      (SemiprimeSourceScoreCountOrder.integerValue M n lam (r^(2*Q)) a tail programs s fixed:ℚ) := by\n  rw [SemiprimeSourceScoreCountBits.score_value,\n    (SemiprimeSourceScoreWeightAcquisition.acquire_value M n r Q lam).1,\n    (SemiprimeSourceScoreWeightAcquisition.acquire_value M n r Q lam).2]\n  rfl\n\n/-- The physical callback preserves all comparisons of the ORIGINAL objective. -/\ntheorem score_order {r Q : ℕ} (M n lam : ℕ) (a : Word r Q) (tail : List (Word r Q))\n    (programs : List (ScoreProgram Q)) (offset : ℚ) (s t : ℕ) (fixed other : List (Word r Q))\n    (hr : 0 < r) (hlam : 0 < lam) (hcard : (a::tail).length^4=(r^(2*Q))^2) :\n    (SemiprimeSourceScoreCountBits.score (SemiprimeSourceScoreWeightAcquisition.acquire M n r Q lam)\n      a tail programs s fixed).word.value ≤\n      (SemiprimeSourceScoreCountBits.score (SemiprimeSourceScoreWeightAcquisition.acquire M n r Q lam)\n        a tail programs t other).word.value ↔\n      (SemiprimeMaterializedScoreSearch.sequential a tail programs\n        ((M:ℚ)/((r:ℚ)*(lam:ℚ)*(r^(2*Q):ℕ))) ((n:ℚ)/(2*(r:ℚ))) offset s fixed).value ≤\n      (SemiprimeMaterializedScoreSearch.sequential a tail programs\n        ((M:ℚ)/((r:ℚ)*(lam:ℚ)*(r^(2*Q):ℕ))) ((n:ℚ)/(2*(r:ℚ))) offset t other).value := by\n  rw [score_value,score_value]\n  have hc :\n      (SemiprimeSourceScoreCountOrder.integerValue M n lam (r^(2*Q)) a tail programs s fixed:ℚ) ≤\n        (SemiprimeSourceScoreCountOrder.integerValue M n lam (r^(2*Q)) a tail programs t other:ℚ) ↔\n      SemiprimeSourceScoreCountOrder.integerValue M n lam (r^(2*Q)) a tail programs s fixed ≤\n        SemiprimeSourceScoreCountOrder.integerValue M n lam (r^(2*Q)) a tail programs t other := by\n    exact_mod_cast Iff.rfl\n  exact hc.trans (SemiprimeSourceScoreCountOrder.integer_le_iff M n lam (r^(2*Q))\n    a tail programs offset s t fixed other hr hlam (pow_pos hr _) hcard)\n\n/-- Acquire original integer weights ONCE and execute the actual candidate callback. -/\ndef run {r Q : ℕ} (M n lam : ℕ) (a : Word r Q) (tail : List (Word r Q))\n    (programs : List (ScoreProgram Q)) (N : ℕ) : Run (List (Word r Q)) :=\n  let weights := SemiprimeSourceScoreWeightAcquisition.acquire M n r Q lam\n  let out := SemiprimeSourceScoreChoice.assign a tail\n    (SemiprimeSourceScoreCountBits.score weights a tail programs) N []\n  ⟨out.value,weights.clock+out.work+2⟩\n\n/-- The new execution returns the EXACT original deterministic source labels.\nOffset and rational scale values are proof-side only and are absent from runtime inputs. -/\ntheorem run_refines {r Q : ℕ} (M n lam : ℕ) (a : Word r Q) (tail : List (Word r Q))\n    (programs : List (ScoreProgram Q)) (N : ℕ) (offset : ℚ)\n    (hr : 0 < r) (hlam : 0 < lam) (hcard : (a::tail).length^4=(r^(2*Q))^2) :\n    (run M n lam a tail programs N).value =\n      (SemiprimeMaterializedScoreSearch.search a tail programs\n        ((M:ℚ)/((r:ℚ)*(lam:ℚ)*(r^(2*Q):ℕ))) ((n:ℚ)/(2*(r:ℚ))) offset N).value := by\n  exact SemiprimeSourceScoreChoice.assign_refines a tail\n    (SemiprimeSourceScoreCountBits.score (SemiprimeSourceScoreWeightAcquisition.acquire M n r Q lam)\n      a tail programs)\n    (SemiprimeMaterializedScoreSearch.sequential a tail programs\n      ((M:ℚ)/((r:ℚ)*(lam:ℚ)*(r^(2*Q):ℕ))) ((n:ℚ)/(2*(r:ℚ))) offset)\n    (fun s xs => SemiprimeSourceScoreCountBits.score_valid _ a tail programs s xs)\n    (fun s xs v w => score_order M n lam a tail programs offset s s (v::xs) (w::xs) hr hlam hcard) N []\n\n/-- Original source descriptor construction is executed before the physical search. -/\ndef computedList {I V E : Type} [DecidableEq V] [DecidableEq E] {r Q : ℕ}\n    (owner : I → V) (factor : I → E) (M n lam : ℕ) (a : Word r Q) (tail : List (Word r Q))\n    (terms : List (OAI.Algorithms.SubexponentialSAT.SqrtLog.Packing.ScoreTerm I V Q))\n    (indices : List (V⊕E)) : Run (List (Word r Q)) :=\n  let compiled := SemiprimeMaterializedSourceWords.compileAll owner factor indices terms\n  let out := run M n lam a tail compiled.value indices.length\n  ⟨out.value,compiled.work+out.work+1⟩\n\n/-- No score-program oracle remains at this original descriptor-list entry point. -/\ntheorem computedList_refines {I V E : Type} [DecidableEq V] [DecidableEq E] {r Q : ℕ}\n    (owner : I → V) (factor : I → E) (M n lam : ℕ) (a : Word r Q) (tail : List (Word r Q))\n    (terms : List (OAI.Algorithms.SubexponentialSAT.SqrtLog.Packing.ScoreTerm I V Q))\n    (indices : List (V⊕E)) (offset : ℚ) (hr : 0 < r) (hlam : 0 < lam)\n    (hcard : (a::tail).length^4=(r^(2*Q))^2) :\n    (computedList owner factor M n lam a tail terms indices).value=\n      (SemiprimeMaterializedSourceWords.computedList owner factor a tail terms indices\n        ((M:ℚ)/((r:ℚ)*(lam:ℚ)*(r^(2*Q):ℕ))) ((n:ℚ)/(2*(r:ℚ))) offset).value := by\n  exact run_refines M n lam a tail _ indices.length offset hr hlam hcard\n\nend RiemannGaussian.SemiprimeSourceScorePhysicalSearch\n","RiemannGaussian.SemiprimeSourceWordBank":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceWordBankRows\n\n/-! # Original-input physical word bank and Boolean-address lookup -/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeSourceWordBank\nopen SemiprimeSourceScorePredicateBits SemiprimeRationalBits\nopen SemiprimeBitArithmetic SemiprimeBitDivision SemiprimeBitPrimeScan\nopen SemiprimeBitProductSort SemiprimeSourceOffsetInputsCore SemiprimeBitIndexTraversal\n\n/-- Concrete original coordinate bank with acquired Boolean candidate IDs. -/\nstructure Bank where\n  /-- Complete ordered physical coordinate rows. -/\n  rows : List Row\n  /-- Acquired ascending physical index words. -/\n  ids : List (List Bool)\n  /-- Original row acquisition and all index/cell/control work. -/\n  clock : ℕ\n\n/-- Actual ascending Boolean IDs; increments and current-ID copies are paid. -/\ndef ascending (current : List Bool) : ℕ → SemiprimeMaterializedWords.Run (List (List Bool))\n  | 0 => ⟨[],1⟩\n  | n+1 =>\n    let copied := fitBits current current\n    let next := addBits current [true] false\n    let rest := ascending next.bits n\n    ⟨copied.bits::rest.value,bitCost copied+bitCost next+rest.work+5⟩\n\n/-- Index zero is a literal empty little-endian magnitude. -/\ndef defaultID : List Bool := []\n\n/-- Construct rows and indices solely from original r,Q; no word-bank argument. -/\ndef acquire (r Q : ℕ) : Bank :=\n  let table := SemiprimeSourceWordBankRows.rows r Q\n  let indices := ascending [] table.value.length\n  ⟨table.value,indices.value,table.work+indices.work+table.value.length+4⟩\n\n/-- Physical row lookup copies every visited row, tests/decrements the address,\nand returns the empty physical row only on genuine out-of-range lookup. -/\ndef readRows : List Row → List Bool → SemiprimeMaterializedWords.Run Row\n  | [],_ => ⟨[],4⟩\n  | row::rows,address =>\n    let visit := copyRow row\n    let test := nonzeroBits address\n    if test.nonzero then\n      let decrement := subBits address [true] false\n      let rest := readRows rows decrement.result.bits\n      ⟨rest.value,visit.work+test.clock+bitCost decrement.result+rest.work+6⟩\n    else ⟨visit.value,visit.work+test.clock+4⟩\n\n/-- Concrete bank lookup used by physical ID environments. -/\ndef readRow (bank : Bank) (id : List Bool) : SemiprimeMaterializedWords.Run Row :=\n  readRows bank.rows id\n\n/-- Exact physical address semantics, with no native integer lookup in runtime. -/\ntheorem readRows_value (rows : List Row) (address : List Bool) :\n    (readRows rows address).value=(rows[bitValue address]?).getD [] := by\n  induction rows generalizing address with\n  | nil => simp [readRows]\n  | cons row rows ih =>\n    by_cases h : (nonzeroBits address).nonzero=true\n    · have hp := (nonzeroBits_correct address).mp h\n      have hd := (decrementBits_value hp).2\n      have he : bitValue address=(bitValue address-1)+1 := by omega\n      simp only [readRows,h,ite_true,ih,hd]\n      conv_rhs => rw [he]\n      rw [List.getElem?_cons_succ]\n    · have hz := (nonzeroBits_false_iff address).mp (Bool.eq_false_of_not_eq_true h)\n      simp only [readRows,Bool.eq_false_of_not_eq_true h,Bool.false_eq_true,ite_false,\n        copyRow_value,hz,List.getElem?_cons_zero,Option.getD_some]\n\n/-- The public lookup has exactly the acquired row-index interpretation. -/\ntheorem readRow_value (bank : Bank) (id : List Bool) :\n    (readRow bank id).value=(bank.rows[bitValue id]?).getD [] := readRows_value _ _\n\n/-- Generated ID values are the literal ascending range, with no integer encoder oracle. -/\ntheorem ascending_values (current : List Bool) (n : ℕ) :\n    (ascending current n).value.map bitValue=List.range' (bitValue current) n := by\n  induction n generalizing current with\n  | zero => rfl\n  | succ n ih =>\n    simp only [ascending,List.map_cons,fitBits_self,addBits_correct,bitNat,Bool.false_eq_true,\n      ite_false,Nat.add_zero,bitValue,List.range'_succ,ih]\n    rfl\n\n/-- Exact number of physical IDs. -/\ntheorem ascending_length (current : List Bool) (n : ℕ) : (ascending current n).value.length=n := by\n  have h := congrArg List.length (ascending_values current n)\n  simpa only [List.length_map,List.length_range'] using h\n\n/-- IDs and acquired rows have the same actual length. -/\ntheorem acquire_ids_length (r Q : ℕ) : (acquire r Q).ids.length=(acquire r Q).rows.length := by\n  exact ascending_length [] _\n\nend RiemannGaussian.SemiprimeSourceWordBank\n","RiemannGaussian.SemiprimeWordPacketCounterBudget":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeWordPacketCounter\nimport RiemannGaussian.SemiprimeMaterializedWordFibreBounds\nimport RiemannGaussian.SemiprimeNativeBitsCounterBudget\n\n/-! # Retained cost of the actual word packet counter\nThe executed native group, head, summary and signed support reports are joined\nto the real cached source getters and Hermite consumer. Only completed nodes\ncross the rational boundary. This bound is not a complete address/tape clock.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeWordPacketCounterBudget\nopen scoped BigOperators\nopen SemiprimeRationalBits SemiprimeJetBits SemiprimeLocalBits\nopen SemiprimeWordPacketCounter\nopen SemiprimeNodeArrayExecution (RuntimeDesign)\nopen SemiprimeMaterializedSourceUniversal (Run)\nopen SemiprimeNativeBitsCounter (nodeWord inputControl inputAt_acquire inputWork_acquire nodeWord_work)\nvariable {n F : ℕ} {arity : Fin F → ℕ}\n\n/-- The larger node template covers the actual emitted group words. -/\ntheorem group_bounded (b J R : ℕ) (d : RuntimeDesign n F) (tw : RationalWord)\n    (source : (e : Fin F) → Fin (arity e) → Fin n → Array RationalWord)\n    (entries : (e : Fin F) → (Fin (arity e) → Bool) → EntryWord)\n    (U : Finset (Fin n)) (g : Fin d.r) (a : (k : Fin d.r) → Fin (d.h k) → Bool) :\n    Bounded (group b J R d tw source entries U g a).words (nodeWidth b R J arity d) := by\n  have hw := SemiprimeNativeGroupBitsBudget.run_bounded b arity J R tw source d.grouping d.assigned\n    (fun v => decide (v ∈ U)) entries g a\n  have hW := SemiprimeWordPacketWidth.groupWidth_le b R n F (∑ e,arity e) J d.r (headCap d)\n    (SemiprimePacketArrayExecution.summaryCount d.r d.h d.m d.W)\n    (SemiprimeCounterEnumeration.weightedCount n (J-1))\n  intro i hi\n  exact ⟨(hw i hi).1.trans hW,(hw i hi).2.trans hW⟩\n\n/-- Structural output size follows from the actual physical group execution. -/\ntheorem group_size (b J R : ℕ) (d : RuntimeDesign n F) (tw : RationalWord)\n    (source : (e : Fin F) → Fin (arity e) → Fin n → Array RationalWord)\n    (entries : (e : Fin F) → (Fin (arity e) → Bool) → EntryWord)\n    (U : Finset (Fin n)) (g : Fin d.r) (a : (k : Fin d.r) → Fin (d.h k) → Bool) :\n    (group b J R d tw source entries U g a).words.size=J :=\n  SemiprimeNativeGroupBits.run_size b arity J R tw source d.grouping d.assigned\n    (fun v => decide (v ∈ U)) entries g a\n\n/-- Complete node traversal plus its retained parameter and cache allowance. -/\ndef nodeBudget (b J R H M C : ℕ) (arity : Fin F → ℕ) (d : RuntimeDesign n F) : ℕ :=\n  SemiprimeMaterializedWordFibreBounds.nodeBudget (nodeWidth b R J arity d) n J d.r H M C\n    (SemiprimePacketArrayExecution.summaryCount d.r d.h d.m d.W)+nodeControl b R J arity d\n\n/-- The original group budget pays every actual new group callback. Its old\nnonnegative decoding allowance is harmless overestimation, not cost equality. -/\ntheorem node_clock (b Q J R H M w A E : ℕ) (a : Fin Q) (d : RuntimeDesign n F)\n    (source : (e : Fin F) → Fin (arity e) → Fin n → Array RationalWord)\n    (entries : (e : Fin F) → (Fin (arity e) → Bool) → EntryWord)\n    (hh : ∀ g,d.h g≤H) (hm : ∀ g,d.m g≤M) (harity : ∀ e,arity e≤w)\n    (hsource : ∀ e i v,Bounded (source e i v) (SemiprimeNativeGroupBits.groupWidth b R F (∑ e,arity e)))\n    (hsize : ∀ e i v,(source e i v).size≤A)\n    (hentry : ∀ e eta,(entries e eta).clock≤E)\n    (hentryWidth : ∀ e eta,(entries e eta).bits.magnitude.length≤\n      SemiprimeNativeGroupBits.groupWidth b R F (∑ e,arity e)) :\n    (node b J R d (nodeWord b a).word source entries).clock≤\n      nodeBudget b J R H M\n        (SemiprimeNativeBitsCounterBudget.groupBudget n F R J b (∑ e,arity e) w A E) arity d := by\n  have hp : 0<(List.replicate (nodeWidth b R J arity d) false).length := by\n    rw [List.length_replicate]\n    exact SemiprimeWordPacketWidth.positive b R n F (∑ e,arity e) J d.r (headCap d)\n      (SemiprimePacketArrayExecution.summaryCount d.r d.h d.m d.W)\n      (SemiprimeCounterEnumeration.weightedCount n (J-1))\n  have hg (U : Finset (Fin n)) (g : Fin d.r) (x : (k : Fin d.r) → Fin (d.h k) → Bool) :=\n    (group_clock_le_legacy b J R d (nodeWord b a).word source entries U g x).trans\n      (SemiprimeNativeBitsCounterBudget.group_work b Q J R w A E a d source entries\n        harity hsource hsize hentry hentryWidth U g x)\n  have hw := SemiprimeMaterializedWordFibreBounds.node_clock\n    (List.replicate (nodeWidth b R J arity d) false) J d\n    (group b J R d (nodeWord b a).word source entries) H M _ hp hh hm hg\n    (by simpa only [List.length_replicate] using group_bounded b J R d (nodeWord b a).word source entries)\n    (group_size b J R d (nodeWord b a).word source entries)\n  simp only [List.length_replicate] at hw\n  exact Nat.add_le_add_right hw _\n\n/-- Polynomial allowance for the single rational boundary at a completed node. -/\ndef decodeBudget (W J : ℕ) : ℕ := J*(20000*(2*W+1)^3+5)+2*J+1\n\n/-- Completed physical nodes have a structurally bounded final decode allowance. -/\ntheorem node_decode_work (b J R : ℕ) (d : RuntimeDesign n F) (tw : RationalWord)\n    (source : (e : Fin F) → Fin (arity e) → Fin n → Array RationalWord)\n    (entries : (e : Fin F) → (Fin (arity e) → Bool) → EntryWord) :\n    SemiprimeNativeGroupBits.decodeWork (node b J R d tw source entries).words≤\n      decodeBudget (nodeWidth b R J arity d) J := by\n  have hw := SemiprimeMaterializedWordFibreBounds.node_bounded\n    (List.replicate (nodeWidth b R J arity d) false) J d (group b J R d tw source entries)\n  simp only [List.length_replicate] at hw\n  have hs := SemiprimeMaterializedWordFibreBounds.node_size\n    (List.replicate (nodeWidth b R J arity d) false) J d (group b J R d tw source entries)\n  have hb := SemiprimeNativeGroupBitsBudget.decodeWork_bound\n    (node b J R d tw source entries).words (nodeWidth b R J arity d) hw\n  change (node b J R d tw source entries).words.size=J at hs\n  rw [hs] at hb\n  exact hb\n\n/-- All actual nodes, one decode per completed node, and the Hermite work. -/\ndef reductionBudget (b Q J R H M C : ℕ) (arity : Fin F → ℕ)\n    (design : Fin Q → RuntimeDesign n F) : ℕ :=\n  (∑ a : Fin Q,(nodeBudget b J R H M C arity (design a)+\n    decodeBudget (nodeWidth b R J arity (design a)) J))+\n    Q*(2*J+4+2*SemiprimeHermiteArrayHeight.nodeWork Q J)\n\n/-- Original word sizes and entry reports discharge the full physical callback\nbudget. Cached source getters and node encoders are charged exactly once. -/\ntheorem count_work (b Q J R H M w A E : ℕ) (design : Fin Q → RuntimeDesign n F)\n    (source : (e : Fin F) → Fin (arity e) → Fin n → Run (Array RationalWord))\n    (entries : (e : Fin F) → (Fin (arity e) → Bool) → EntryWord)\n    (hh : ∀ a g,(design a).h g≤H) (hm : ∀ a g,(design a).m g≤M)\n    (harity : ∀ e,arity e≤w)\n    (hsource : ∀ e i v,Bounded (source e i v).value (SemiprimeNativeGroupBits.groupWidth b R F (∑ e,arity e)))\n    (hsize : ∀ e i v,(source e i v).value.size≤A)\n    (hentry : ∀ e eta,(entries e eta).clock≤E)\n    (hentryWidth : ∀ e eta,(entries e eta).bits.magnitude.length≤\n      SemiprimeNativeGroupBits.groupWidth b R F (∑ e,arity e)) :\n    (count b Q J R design source entries).work≤\n      (∑ e,∑ i,∑ v,(source e i v).work)+Q*(4*(b+1)+4)+\n        reductionBudget b Q J R H M\n          (SemiprimeNativeBitsCounterBudget.groupBudget n F R J b (∑ e,arity e) w A E) arity design+\n        inputControl n F (∑ e,arity e) R b+10*Q+10 := by\n  let acquire := fun a : Fin Q => SemiprimeNativeGroupBits.toScalarRun\n    (node b J R (design a) (nodeWord b a).word (fun e i v => (source e i v).value) entries)\n  have hn (a : Fin Q) : (acquire a).work≤\n      nodeBudget b J R H M\n        (SemiprimeNativeBitsCounterBudget.groupBudget n F R J b (∑ e,arity e) w A E) arity (design a)+\n      decodeBudget (nodeWidth b R J arity (design a)) J := by\n    dsimp only [acquire]\n    rw [SemiprimeNativeGroupBits.toScalarRun_work]\n    exact Nat.add_le_add\n      (node_clock b Q J R H M w A E a (design a) (fun e i v => (source e i v).value) entries\n        (hh a) (hm a) harity hsource hsize hentry hentryWidth)\n      (node_decode_work b J R (design a) (nodeWord b a).word (fun e i v => (source e i v).value) entries)\n  have hr := (SemiprimeAcquiredHermite.reconstruct_work Q J acquire).trans\n    (Nat.add_le_add_right (Finset.sum_le_sum (fun a _ => hn a)) _)\n  change _≤reductionBudget b Q J R H M\n    (SemiprimeNativeBitsCounterBudget.groupBudget n F R J b (∑ e,arity e) w A E) arity design at hr\n  simp only [count,Array.getElem_ofFn,inputAt_acquire,inputWork_acquire,\n    Array.toList_ofFn,List.map_ofFn,Function.comp_def,List.sum_ofFn,nodeWord_work,\n    Finset.sum_const,Finset.card_univ,Fintype.card_fin,smul_eq_mul]\n  exact Nat.add_le_add_right (Nat.add_le_add_right\n    (Nat.add_le_add_right (Nat.add_le_add_left hr _) _) _) _\n\nend RiemannGaussian.SemiprimeWordPacketCounterBudget\n"};
